// Plan element labels scale with the longest side of the structural plan.
// A 93'-8" plan uses 5" labels; every other plan varies linearly from that reference.
const PLAN_ELEMENT_LABEL_REFERENCE_LONGEST_SIDE = (93 * 0.3048) + (8 * 0.0254);
const PLAN_ELEMENT_LABEL_REFERENCE_TEXT_HEIGHT = 5 * 0.0254;

function getPlanAnnotationTextHeight() {
    return getCurrentUnitSystem() === "imperial"
        ? IMPERIAL_PLAN_ANNOTATION_TEXT_HEIGHT
        : METRIC_PLAN_ANNOTATION_TEXT_HEIGHT;
}

function getPlanElementLabelTextSizeForBounds(bounds = {}, fallback = getPlanAnnotationTextHeight()) {
    const minX = parseNumberOrFallback(bounds?.minX ?? bounds?.left ?? 0, 0);
    const maxX = parseNumberOrFallback(bounds?.maxX ?? bounds?.right ?? minX, minX);
    const minY = parseNumberOrFallback(bounds?.minY ?? bounds?.bottom ?? 0, 0);
    const maxY = parseNumberOrFallback(bounds?.maxY ?? bounds?.top ?? minY, minY);
    const explicitWidth = parsePositiveNumberOrFallback(bounds?.width, 0, 0);
    const explicitHeight = parsePositiveNumberOrFallback(bounds?.height, 0, 0);
    const width = explicitWidth > 0 ? explicitWidth : Math.max(Math.abs(maxX - minX), 0);
    const height = explicitHeight > 0 ? explicitHeight : Math.max(Math.abs(maxY - minY), 0);
    const longestSide = Math.max(width, height);

    if (!(longestSide > EDGE_TOLERANCE)) {
        return parsePositiveNumberOrFallback(fallback, PLAN_ELEMENT_LABEL_REFERENCE_TEXT_HEIGHT, 0.001);
    }

    return PLAN_ELEMENT_LABEL_REFERENCE_TEXT_HEIGHT
        * (longestSide / PLAN_ELEMENT_LABEL_REFERENCE_LONGEST_SIDE);
}
