function normalizeBeamSpanNumber(value, fallback = 1) {
    const parsed = Number.parseInt(value, 10);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function getBeamSpanNumber(beam = {}) {
    const sourceIndex = Number.parseInt(beam?.sourceEtabsSegmentIndex, 10);
    return normalizeBeamSpanNumber(
        beam?.spanNumber ?? beam?.span ?? beam?.tramo ?? (Number.isFinite(sourceIndex) ? sourceIndex + 1 : 1),
        1
    );
}

function getBeamSpanCount(beam = {}) {
    return normalizeBeamSpanNumber(
        beam?.spanCount ?? beam?.segmentCount ?? beam?.tramoCount ?? beam?.sourceEtabsSegmentCount,
        1
    );
}

function isContinuousBeamSpan(beam = {}) {
    return getBeamSpanCount(beam) > 1 || Number.isFinite(Number.parseInt(beam?.sourceEtabsSegmentIndex, 10));
}

function getBeamSpanDisplayLabel(beam = {}) {
    return `${translate("insert.beamSpan") || "TRAMO"} ${getBeamSpanNumber(beam)}`;
}

function stripLegacyBeamSpanSuffix(value, beam = {}) {
    const name = normalizeTextValue(value);
    if (!name) return "";

    // Older project snapshots may have stored the visual span label inside the
    // beam name. A span is never part of the drawing name; it is only an
    // internal member identifier. Support the previous English/Spanish forms
    // and the former "-2" ETABS suffix without touching the source member ID.
    const withoutExplicitSpan = name
        .replace(/\s*(?:[-—–:]\s*)?(?:TRAMO|SPAN)\s*\d+\s*$/iu, "")
        .replace(/\s*\(\s*(?:TRAMO|SPAN)\s*\d+\s*\)\s*$/iu, "")
        .trim();
    if (withoutExplicitSpan !== name) {
        return withoutExplicitSpan;
    }

    if (normalizeTextValue(beam?.sourceImportType).toLowerCase() === "architectural_dxf") {
        return name;
    }
    if (!isContinuousBeamSpan(beam) || getBeamSpanCount(beam) <= 1) {
        return name;
    }

    const spanNumber = getBeamSpanNumber(beam);
    return name.replace(new RegExp(`\\s*-\\s*0*${spanNumber}\\s*$`), "").trim();
}

function normalizeContinuousBeamDisplayName(value, beam = {}) {
    return stripLegacyBeamSpanSuffix(value, beam);
}

