function isPositiveDownloadFeedbackRating(rating = projectState.downloadFeedbackResponse.rating) {
    const normalizedRating = String(rating || "").trim().toLowerCase();
    return normalizedRating === "5"
        || normalizedRating === "4"
        || normalizedRating === "helpful";
}

function isDownloadFeedbackIssueRequired() {
    const normalizedRating = String(projectState.downloadFeedbackResponse.rating || "").trim().toLowerCase();
    return normalizedRating === "3"
        || normalizedRating === "2"
        || normalizedRating === "1"
        || normalizedRating === "partial"
        || normalizedRating === "failed";
}

function isDownloadFeedbackOverlayOpen() {
    return Boolean(dom.downloadFeedbackOverlay && !dom.downloadFeedbackOverlay.hidden);
}

function setDownloadFeedbackStatus(message = "", tone = "") {
    projectState.downloadFeedbackStatusMessage = typeof message === "string" ? message : "";
    projectState.downloadFeedbackStatusTone = typeof tone === "string" ? tone : "";
}

function resetDownloadFeedbackResponse() {
    projectState.downloadFeedbackResponse = {
        rating: "",
        issue: "",
        other: "",
        experience: "",
        reviewAuthorized: true
    };
    setDownloadFeedbackStatus("", "");
    if (dom.downloadFeedbackExperienceInput) {
        dom.downloadFeedbackExperienceInput.value = "";
    }
    if (dom.downloadFeedbackOtherInput) {
        dom.downloadFeedbackOtherInput.value = "";
    }
    if (dom.downloadFeedbackReviewCheckbox) {
        dom.downloadFeedbackReviewCheckbox.checked = true;
    }
}

function closeDownloadFeedbackOverlay({ reset = true } = {}) {
    if (!dom.downloadFeedbackOverlay || projectState.downloadFeedbackSubmitting) {
        return;
    }

    dom.downloadFeedbackOverlay.hidden = true;
    projectState.downloadFeedbackOpen = false;
    if (reset) {
        resetDownloadFeedbackResponse();
        projectState.downloadFeedbackRequest = {
            downloadId: "",
            fileName: "",
            outputMode: "",
            selection: ""
        };
    }
    renderDownloadFeedbackUi();
}

function openDownloadFeedbackOverlay(request = {}) {
    if (!dom.downloadFeedbackOverlay) {
        return;
    }

    closeSupportOverlay({ restoreFocus: false, force: true });
    closeAiChatDrawer();
    projectState.downloadFeedbackOpen = true;
    projectState.downloadFeedbackRequest = {
        downloadId: String(request.downloadId || "").trim(),
        fileName: String(request.fileName || "").trim(),
        outputMode: String(request.outputMode || "").trim(),
        selection: String(request.selection || "").trim()
    };
    resetDownloadFeedbackResponse();
    dom.downloadFeedbackOverlay.hidden = false;
    renderDownloadFeedbackUi();
}

function renderDownloadFeedbackUi() {
    if (!isBrowser || !dom.downloadFeedbackOverlay) {
        return;
    }

    const copy = getDownloadFeedbackCopy();
    const issueRequired = isDownloadFeedbackIssueRequired();
    const overlayOpen = isDownloadFeedbackOverlayOpen();

    if (dom.downloadFeedbackKicker) {
        dom.downloadFeedbackKicker.textContent = copy.kicker;
    }
    if (dom.downloadFeedbackTitle) {
        dom.downloadFeedbackTitle.textContent = copy.title;
    }
    if (dom.downloadFeedbackQuestion) {
        dom.downloadFeedbackQuestion.textContent = copy.question;
    }
    if (dom.downloadFeedbackIssueTitle) {
        dom.downloadFeedbackIssueTitle.textContent = copy.issueTitle;
    }
    if (dom.downloadFeedbackExperienceTitle) {
        dom.downloadFeedbackExperienceTitle.textContent = copy.experienceTitle;
    }
    if (dom.downloadFeedbackReviewTitle) {
        dom.downloadFeedbackReviewTitle.textContent = copy.reviewTitle;
    }
    if (dom.downloadFeedbackReviewLabel) {
        const labelText = dom.downloadFeedbackReviewLabel.querySelector("span");
        if (labelText) {
            labelText.textContent = copy.reviewLabel;
        }
    }
    if (dom.downloadFeedbackOtherInput) {
        dom.downloadFeedbackOtherInput.value = projectState.downloadFeedbackResponse.other || "";
        dom.downloadFeedbackOtherInput.hidden = projectState.downloadFeedbackResponse.issue !== "other";
        dom.downloadFeedbackOtherInput.disabled = projectState.downloadFeedbackSubmitting;
        dom.downloadFeedbackOtherInput.setAttribute("placeholder", copy.otherPlaceholder);
    }
    if (dom.downloadFeedbackExperienceSection) {
        dom.downloadFeedbackExperienceSection.hidden = !isPositiveDownloadFeedbackRating();
    }
    if (dom.downloadFeedbackExperienceInput) {
        dom.downloadFeedbackExperienceInput.value = projectState.downloadFeedbackResponse.experience || "";
        dom.downloadFeedbackExperienceInput.disabled = projectState.downloadFeedbackSubmitting;
        dom.downloadFeedbackExperienceInput.setAttribute("placeholder", copy.experiencePlaceholder);
    }
    if (dom.downloadFeedbackIssueSection) {
        dom.downloadFeedbackIssueSection.hidden = !issueRequired;
    }
    if (dom.downloadFeedbackReviewCheckbox) {
        dom.downloadFeedbackReviewCheckbox.checked = Boolean(projectState.downloadFeedbackResponse.reviewAuthorized);
        dom.downloadFeedbackReviewCheckbox.disabled = projectState.downloadFeedbackSubmitting;
    }
    if (dom.downloadFeedbackStatusNote) {
        const tone = projectState.downloadFeedbackStatusTone || "info";
        dom.downloadFeedbackStatusNote.textContent = projectState.downloadFeedbackStatusMessage || "";
        dom.downloadFeedbackStatusNote.hidden = !projectState.downloadFeedbackStatusMessage;
        dom.downloadFeedbackStatusNote.setAttribute("data-tone", tone);
    }
    if (dom.downloadFeedbackSubmitButton) {
        setButtonCopy(dom.downloadFeedbackSubmitButton, projectState.downloadFeedbackSubmitting ? copy.sending : copy.submit);
        dom.downloadFeedbackSubmitButton.disabled = projectState.downloadFeedbackSubmitting || !overlayOpen;
    }
    if (dom.downloadFeedbackCloseButton) {
        setButtonCopy(dom.downloadFeedbackCloseButton, copy.close);
        dom.downloadFeedbackCloseButton.disabled = projectState.downloadFeedbackSubmitting;
    }

    document.querySelectorAll("[data-feedback-rating]").forEach((button) => {
        const rating = String(button.dataset.feedbackRating || "");
        button.textContent = copy.ratings[rating] || button.textContent;
        button.classList.toggle("is-selected", projectState.downloadFeedbackResponse.rating === rating);
        button.setAttribute("aria-pressed", String(projectState.downloadFeedbackResponse.rating === rating));
        button.disabled = projectState.downloadFeedbackSubmitting;
    });

    document.querySelectorAll("[data-feedback-issue]").forEach((button) => {
        const issue = String(button.dataset.feedbackIssue || "");
        button.textContent = copy.issues[issue] || button.textContent;
        button.classList.toggle("is-selected", projectState.downloadFeedbackResponse.issue === issue);
        button.setAttribute("aria-pressed", String(projectState.downloadFeedbackResponse.issue === issue));
        button.disabled = projectState.downloadFeedbackSubmitting;
    });
}

async function submitDownloadFeedback() {
    const copy = getDownloadFeedbackCopy();
    const { rating, issue } = projectState.downloadFeedbackResponse;
    const otherText = String(dom.downloadFeedbackOtherInput?.value || "").trim();
    const experienceText = isPositiveDownloadFeedbackRating(rating)
        ? String(dom.downloadFeedbackExperienceInput?.value || "").trim()
        : "";
    const reviewAuthorized = Boolean(dom.downloadFeedbackReviewCheckbox?.checked);

    if (!rating) {
        setDownloadFeedbackStatus(copy.ratingRequired, "error");
        renderDownloadFeedbackUi();
        return;
    }

    if (isDownloadFeedbackIssueRequired() && !issue) {
        setDownloadFeedbackStatus(copy.issueRequired, "error");
        renderDownloadFeedbackUi();
        return;
    }

    if (issue === "other" && !otherText) {
        setDownloadFeedbackStatus(copy.otherRequired, "error");
        renderDownloadFeedbackUi();
        dom.downloadFeedbackOtherInput?.focus();
        return;
    }

    projectState.downloadFeedbackSubmitting = true;
    projectState.downloadFeedbackResponse.reviewAuthorized = reviewAuthorized;
    projectState.downloadFeedbackResponse.other = otherText;
    projectState.downloadFeedbackResponse.experience = experienceText;
    setDownloadFeedbackStatus("", "");
    renderDownloadFeedbackUi();

    let payload = null;
    try {
        if (reviewAuthorized) {
            try {
                await persistPendingEtabsReviewUploads();
            } catch (error) {
                console.warn("[etabs-upload] Review upload failed:", error?.message || error);
            }
        }

        const response = await fetch("/api/health?intent=download-feedback", {
            method: "POST",
            credentials: "same-origin",
            headers: {
                "Content-Type": "application/json",
                Accept: "application/json"
            },
            body: JSON.stringify({
                intent: "download-feedback",
                downloadId: projectState.downloadFeedbackRequest.downloadId,
                fileName: projectState.downloadFeedbackRequest.fileName,
                outputMode: projectState.downloadFeedbackRequest.outputMode,
                selection: projectState.downloadFeedbackRequest.selection,
                projectName: String(projectState.currentProjectName || "").trim(),
                pagePath: isBrowser ? window.location.pathname : "",
                language: projectState.language,
                feedbackRating: rating,
                feedbackIssue: issue,
                feedbackIssueOther: otherText,
                feedbackExperience: experienceText,
                reviewAuthorized,
                etabsUploads: normalizeEtabsUploadCollection(projectState.etabsUploads)
            })
        });
        payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            throw new Error(
                typeof payload?.error === "string" && payload.error.trim()
                    ? payload.error
                    : copy.error
            );
        }
    } catch (error) {
        setDownloadFeedbackStatus(error?.message || copy.error, "error");
        projectState.downloadFeedbackSubmitting = false;
        renderDownloadFeedbackUi();
        return;
    }

    projectState.downloadFeedbackSubmitting = false;
    closeDownloadFeedbackOverlay();
    openAppNoticeDialog({
        title: projectState.language === "en" ? "Thanks" : "Gracias",
        message: reviewAuthorized
            ? payload?.reviewEmailState === "not_configured" || payload?.reviewEmailState === "store_failed"
                ? copy.successReviewStoredOnly
                : copy.successReview
            : copy.success
    });
}

function renderSupportUi() {
    if (!isBrowser) {
        return;
    }

    const overlayOpen = isSupportOverlayOpen();
    if (dom.supportFab) {
        const supportLabel = translate("workspace.supportAria");
        dom.supportFab.title = supportLabel;
        dom.supportFab.setAttribute("aria-label", supportLabel);
        dom.supportFab.setAttribute("aria-expanded", String(overlayOpen));
        dom.supportFab.disabled = projectState.supportSubmitting;
    }

    if (dom.supportModalKicker) {
        dom.supportModalKicker.textContent = translate("support.kicker");
    }
    if (dom.supportModalTitle) {
        dom.supportModalTitle.textContent = translate("support.title");
    }
    if (dom.supportModalCopy) {
        dom.supportModalCopy.textContent = translate("support.copy");
    }
    if (dom.supportSubjectLabel) {
        dom.supportSubjectLabel.textContent = translate("support.subjectLabel");
    }
    if (dom.supportSubjectInput) {
        dom.supportSubjectInput.setAttribute("placeholder", translate("support.subjectPlaceholder"));
        dom.supportSubjectInput.disabled = projectState.supportSubmitting;
    }
    if (dom.supportMessageLabel) {
        dom.supportMessageLabel.textContent = translate("support.messageLabel");
    }
    if (dom.supportMessageInput) {
        dom.supportMessageInput.setAttribute("placeholder", translate("support.messagePlaceholder"));
        dom.supportMessageInput.disabled = projectState.supportSubmitting;
    }
    if (dom.supportSessionNote) {
        dom.supportSessionNote.textContent = projectState.authenticatedUser?.email
            ? translate("support.sessionUser", { email: projectState.authenticatedUser.email })
            : translate("support.sessionGuest");
    }
    if (dom.supportStatusNote) {
        const tone = projectState.supportStatusTone || "info";
        dom.supportStatusNote.textContent = projectState.supportStatusMessage || "";
        dom.supportStatusNote.hidden = !projectState.supportStatusMessage;
        dom.supportStatusNote.setAttribute("data-tone", tone);
    }
    if (dom.supportSendButton) {
        setButtonCopy(dom.supportSendButton, projectState.supportSubmitting ? translate("support.sending") : translate("support.send"));
        dom.supportSendButton.disabled = projectState.supportSubmitting;
    }
    if (dom.supportCloseButton) {
        dom.supportCloseButton.disabled = projectState.supportSubmitting;
        dom.supportCloseButton.title = translate("support.close");
        dom.supportCloseButton.setAttribute("aria-label", translate("support.close"));
    }
}

function closeSupportOverlay({ restoreFocus = true, resetStatus = true, force = false } = {}) {
    if (!dom.supportOverlay) {
        return;
    }

    if (!force && projectState.supportSubmitting) {
        return;
    }

    dom.supportOverlay.hidden = true;
    if (resetStatus) {
        setSupportStatus("", "");
    }
    renderSupportUi();
    if (restoreFocus) {
        dom.supportFab?.focus();
    }
}

function openSupportOverlay() {
    if (!dom.supportOverlay) {
        return;
    }

    closeAiChatDrawer();
    closeWorkspace3DOverlay({ restoreFocus: false });
    setSupportStatus("", "");
    dom.supportOverlay.hidden = false;
    renderSupportUi();
    if (isBrowser) {
        window.setTimeout(() => {
            dom.supportSubjectInput?.focus();
        }, 0);
    }
}

async function submitSupportRequest() {
    if (projectState.supportSubmitting) {
        return;
    }

    const subject = String(dom.supportSubjectInput?.value || "").trim();
    const message = String(dom.supportMessageInput?.value || "").trim();

    if (!subject) {
        setSupportStatus(translate("errors.supportSubjectRequired"), "error");
        renderSupportUi();
        dom.supportSubjectInput?.focus();
        return;
    }

    if (!message) {
        setSupportStatus(translate("errors.supportMessageRequired"), "error");
        renderSupportUi();
        dom.supportMessageInput?.focus();
        return;
    }

    projectState.supportSubmitting = true;
    setSupportStatus("", "");
    renderSupportUi();

    let payload = null;
    try {
        const response = await fetch("/api/support", {
            method: "POST",
            credentials: "same-origin",
            headers: {
                "Content-Type": "application/json",
                Accept: "application/json"
            },
            body: JSON.stringify({
                subject,
                message,
                source: "workspace_support_fab",
                pagePath: isBrowser ? window.location.pathname : "",
                projectName: String(projectState.currentProjectName || "").trim(),
                language: projectState.language
            })
        });
        payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            throw new Error(
                typeof payload?.error === "string" && payload.error.trim()
                    ? payload.error
                    : translate("errors.supportSubmitFailed")
            );
        }
    } catch (error) {
        setSupportStatus(error?.message || translate("errors.supportSubmitFailed"), "error");
    }

    projectState.supportSubmitting = false;
    renderSupportUi();

    if (!payload) {
        return;
    }

    clearSupportForm();
    closeSupportOverlay({ restoreFocus: false, force: true });
    const emailState = typeof payload.emailState === "string" ? payload.emailState : "";
    openAppNoticeDialog({
        title: translate("support.successTitle"),
        message: emailState === "send_failed"
            ? translate("support.successSendFailed")
            : emailState === "not_configured" || payload.emailConfigured === false
                ? translate("support.successStoredOnly")
                : translate("support.successSent")
    });
}

function triggerAnalyzePlanImage() {
    closeEtabsHelpPopovers();
    closeSupportOverlay({ restoreFocus: false, force: true });
    closeWorkspace3DOverlay({ restoreFocus: false });
    if (dom.aiChatOverlay) {
        dom.aiChatOverlay.hidden = false;
        setAiChatFabExpanded(true);
        setTimeout(() => dom.aiChatInput?.focus(), 100);
    }
}

if (isBrowser) {
    init();
}

function init() {
    restorePendingProjectSnapshot();
    normalizeState();
    normalizeOutputSelections();
    registerEventListeners();
    resizeCanvas();
    setSidebarMode(projectState.sidebarMode);
    setOutputMode(projectState.outputMode);
    updateUI();
    applyLanguage();
    render();
    if (new URLSearchParams(window.location.search).get("tool") === "apu-element") {
        openApuElementOverlay();
    }
    initSiteEntryTracking();
    initSurvey();
    beginWorkspaceScratchFlow();
    updateCanvasControlButtons();
    updateCanvasCursor();
    notifyWorkspaceCommandModeChange();
    void refreshBillingStatus({ silent: true }).then(() => resumePendingBillingCheckout());
}

function createEntityId(prefix) {
    return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

function getEntityTypeLabel(type) {
    const normalizedType = type === "col" ? "column" : type;
    switch (normalizedType) {
        case "column":
            return translate("naming.column");
        case "beam":
            return translate("naming.beam");
        case "wall":
            return translate("naming.wall");
        case "foundation":
            return translate("naming.foundation");
        case "slab":
            return translate("naming.slab");
        case "hole":
            return translate("naming.hole");
        default:
            return normalizedType;
    }
}

function getInsertNamePlaceholder(type) {
    const normalizedType = type === "column" ? "col" : type;
    switch (normalizedType) {
        case "beam":
            return translate("insert.beamNamePlaceholder");
        case "wall":
            return translate("insert.wallNamePlaceholder");
        case "foundation":
            return translate("insert.foundationNamePlaceholder");
        case "slab":
            return translate("insert.slabNamePlaceholder");
        case "hole":
            return translate("insert.holeNamePlaceholder");
        case "col":
        default:
            return translate("insert.columnNamePlaceholder");
    }
}

function getModalNamePlaceholder(type) {
    const normalizedType = type === "col" ? "column" : type;
    switch (normalizedType) {
        case "beam":
            return translate("modal.beamNamePlaceholder");
        case "wall":
            return translate("modal.wallNamePlaceholder");
        case "foundation":
            return translate("modal.foundationNamePlaceholder") || translate("insert.foundationNamePlaceholder");
        case "slab":
            return translate("modal.slabNamePlaceholder");
        case "hole":
            return translate("modal.holeNamePlaceholder") || translate("insert.holeNamePlaceholder");
        case "column":
        default:
            return translate("modal.columnNamePlaceholder");
    }
}

function getEntityCollection(level, type) {
    if (!level) {
        return [];
    }

    switch (type) {
        case "column":
            return level.columns || [];
        case "beam":
            return level.beams || [];
        case "wall":
            return level.walls || [];
        case "foundation":
            return level.foundations || [];
        case "slab":
            return level.slabs || [];
        case "hole":
            return level.holes || [];
        default:
            return [];
    }
}

function getAllModelEntities(type) {
    const normalizedType = type === "col" ? "column" : type;
    return projectState.levels.flatMap((level) => getEntityCollection(level, normalizedType));
}

function getEntityLevelId(type, entity) {
    const normalizedType = type === "col" ? "column" : type;
    const entityId = entity?.id;
    if (!entityId) {
        return null;
    }

    const level = projectState.levels.find((candidate) => (
        getEntityCollection(candidate, normalizedType).some((item) => item?.id === entityId)
    ));
    return level?.id ?? null;
}

function getEntitiesForNameScope(type, levelId = null) {
    const normalizedType = type === "col" ? "column" : type;
    if (normalizedType !== "column" || levelId == null) {
        return getAllModelEntities(normalizedType);
    }

    const level = projectState.levels.find((candidate) => String(candidate?.id) === String(levelId));
    return getEntityCollection(level, normalizedType);
}

function getEntityNamingPrefix(type, source = {}) {
    const normalizedType = type === "col" ? "column" : type;

    if (normalizedType === "column") {
        return "C";
    }

    if (normalizedType === "beam") {
        return normalizeStructuralMaterialSpec(source?.structuralMaterial).type === "wood"
            ? "T"
            : "V";
    }

    if (normalizedType === "foundation") {
        return isStripFoundation(source) ? "ZC" : "Z";
    }

    if (normalizedType === "slab") {
        const normalizedSlab = source?.id ? normalizeSlab(source) : normalizeSlabInsertDraft(source);
        if (normalizedSlab.type === "hole") {
            return "H";
        }
        if (normalizedSlab.type === SLAB_TYPE_SOLID_STAIR) {
            return "LE";
        }
        if (normalizedSlab.type === SLAB_TYPE_METAL_DECK) {
            return "MD";
        }
        return normalizedSlab.type === "lightened" ? "LA" : "L";
    }

    if (normalizedType === "wall") {
        const normalizedWall = source?.id ? normalizeWall(source) : normalizeWallInsertDraft(source);
        return normalizedWall.material === "masonry" ? "MB" : "MH";
    }

    return "E";
}

function getEntitiesByName(type, name, excludedIds = new Set(), levelId = null) {
    const normalizedType = type === "col" ? "column" : type;
    const normalizedName = normalizeTextValue(name).toLowerCase();
    if (!normalizedName) {
        return [];
    }

    return getEntitiesForNameScope(normalizedType, levelId).filter((entity) => (
        !excludedIds.has(entity.id)
        && normalizeTextValue(entity?.name).toLowerCase() === normalizedName
    ));
}

function hasEntityNameConflict(type, name, excludedIds = new Set(), levelId = null) {
    return getEntitiesByName(type, name, excludedIds, levelId).length > 0;
}

function getNextAvailableEntityName(type, source = {}, excludedIds = new Set(), levelId = null) {
    const prefix = getEntityNamingPrefix(type, source);
    const reservedNames = new Set(
        getEntitiesForNameScope(type, levelId)
            .filter((entity) => !excludedIds.has(entity.id))
            .map((entity) => normalizeTextValue(entity?.name).toLowerCase())
            .filter(Boolean)
    );

    let index = 1;
    while (reservedNames.has(`${prefix}${index}`.toLowerCase())) {
        index += 1;
    }

    return `${prefix}${index}`;
}

function getAxisIndexByValue(axisType, value, tolerance = 0.01) {
    return (projectState.axes[axisType] || []).findIndex((axisValue) => Math.abs(axisValue - value) <= tolerance);
}

function getAxisLabelForValue(axisType, value) {
    const axisIndex = getAxisIndexByValue(axisType, value);
    if (axisIndex < 0) {
        return Number.isFinite(value) ? Number(value).toFixed(2) : "";
    }

    return getAxisLabelForIndex(axisType, axisIndex);
}

function getGridNodeLabel(x, y) {
    return `${getAxisLabelForValue("x", x)}${getAxisLabelForValue("y", y)}`;
}

function getGridBayLabel(bounds = {}) {
    const normalizedBounds = normalizeSlabBounds(bounds);
    return `${getAxisLabelForValue("x", normalizedBounds.x1)}${getAxisLabelForValue("y", normalizedBounds.y1)}`;
}

function getSmartEntityName(type, source = {}) {
    const normalizedType = type === "col" ? "column" : type;
    if (normalizedType === "column") {
        return getGridNodeLabel(source.x, source.y);
    }

    if (normalizedType === "foundation") {
        return getGridNodeLabel(source.x, source.y);
    }

    if (normalizedType === "slab" || normalizedType === "hole") {
        return getGridBayLabel(source);
    }

    if (normalizedType === "beam" || normalizedType === "wall") {
        const startLabel = getGridNodeLabel(source.x1, source.y1);
        const endLabel = getGridNodeLabel(source.x2, source.y2);
        return `${startLabel}-${endLabel}`;
    }

    return "";
}

function getBeamSectionPropertiesKey(source) {
    const normalized = source?.id ? normalizeBeamModel(source) : normalizeBeamInsertDraft(source);
    return JSON.stringify({
        sourceSection: normalizeTextValue(source?.sourceSection),
        sourceShape: normalizeTextValue(source?.sourceShape),
        steelProfile: source?.steelProfile || null,
        b: normalized.b,
        h: normalized.h,
        structuralMaterial: normalized.structuralMaterial,
        topRebar: normalized.topRebar,
        botRebar: normalized.botRebar,
        stirrups: normalized.stirrups,
        coverTop: normalized.coverTop,
        coverBottom: normalized.coverBottom
    });
}

function getWallSectionPropertiesKey(source) {
    const normalized = normalizeWall(source);
    return JSON.stringify({
        b: normalized.b,
        h: normalized.h,
        structuralMaterial: normalized.structuralMaterial,
        material: normalized.material,
        concrete: normalized.concrete,
        masonry: normalized.masonry
    });
}

function getFoundationSectionPropertiesKey(source) {
    const normalized = source?.id ? normalizeFoundation(source) : normalizeFoundationInsertDraft(source);
    return JSON.stringify({
        foundationType: normalized.foundationType,
        b: normalized.b,
        h: normalized.h,
        thickness: normalized.thickness,
        structuralMaterial: normalized.structuralMaterial,
        solid: normalized.solid,
        topRebar: normalized.topRebar,
        botRebar: normalized.botRebar,
        transverseRebarZones: normalized.transverseRebarZones,
        additionalRebar: normalized.additionalRebar
    });
}

function getSlabSectionPropertiesKey(source) {
    const normalized = source?.id ? normalizeSlab(source) : normalizeSlabInsertDraft(source);
    return JSON.stringify({
        h: normalized.h,
        structuralMaterial: normalized.structuralMaterial,
        type: normalized.type,
        temperatureSteel: normalized.temperatureSteel,
        solid: normalized.solid,
        lightened: normalized.lightened
    });
}

function getEntitySectionPropertiesKey(type, source = {}) {
    const normalizedType = type === "col" ? "column" : type;
    switch (normalizedType) {
        case "column":
            return getColumnSectionPropertiesKey(source);
        case "beam":
            return getBeamSectionPropertiesKey(source);
        case "wall":
            return getWallSectionPropertiesKey(source);
        case "foundation":
            return getFoundationSectionPropertiesKey(source);
        case "slab":
        case "hole":
            return getSlabSectionPropertiesKey(source);
        default:
            return "";
    }
}

function canonicalizeSmartRenameValue(value) {
    if (typeof value === "number") {
        return Number.isFinite(value) ? Number(value.toFixed(5)) : null;
    }

    if (Array.isArray(value)) {
        return value.map(canonicalizeSmartRenameValue);
    }

    if (value && typeof value === "object") {
        return Object.keys(value)
            .sort()
            .reduce((result, key) => {
                const nextValue = canonicalizeSmartRenameValue(value[key]);
                if (nextValue !== undefined && nextValue !== "") {
                    result[key] = nextValue;
                }
                return result;
            }, {});
    }

    if (typeof value === "string") {
        return normalizeTextValue(value).toLowerCase();
    }

    if (typeof value === "boolean" || value === null) {
        return value;
    }

    return undefined;
}

function getSmartRenameSegmentLength(source = {}) {
    const x1 = parseNumberOrFallback(source?.x1, 0);
    const y1 = parseNumberOrFallback(source?.y1, 0);
    const x2 = parseNumberOrFallback(source?.x2, x1);
    const y2 = parseNumberOrFallback(source?.y2, y1);
    return Number(Math.hypot(x2 - x1, y2 - y1).toFixed(5));
}

function getSmartRenameRectangularDimensions(source = {}) {
    const bounds = normalizeSlabBounds(source);
    return {
        width: Number(Math.abs(bounds.x2 - bounds.x1).toFixed(5)),
        height: Number(Math.abs(bounds.y2 - bounds.y1).toFixed(5))
    };
}

function getEtabsSmartRenamePrefix(type, source = {}) {
    const normalizedType = type === "col" ? "column" : type;
    if (normalizedType === "column") {
        return "C";
    }

    if (normalizedType === "beam") {
        return normalizeStructuralMaterialSpec(source?.structuralMaterial).type === "wood"
            ? "T"
            : "V";
    }

    if (normalizedType === "foundation") {
        return "Z";
    }

    if (normalizedType === "slab") {
        return "L";
    }

    if (normalizedType === "wall") {
        return normalizeWall(source).material === "masonry"
            ? "M"
            : (projectState.language === "en" ? "CW" : "MH");
    }

    return "";
}

function getEtabsSmartRenameWoodTrussProperties(source = {}) {
    const normalized = source?.id ? normalizeBeamModel(source) : normalizeBeamInsertDraft(source);
    return {
        sourceSection: normalized.sourceSection,
        sourceShape: normalized.sourceShape,
        h: normalized.h,
        structuralMaterial: normalized.structuralMaterial
    };
}

function getEtabsSmartRenameProperties(type, source = {}, level = null) {
    const normalizedType = type === "col" ? "column" : type;

    if (normalizedType === "column") {
        const { name, ...section } = getColumnSectionDefinition(source);
        return section;
    }

    if (normalizedType === "beam") {
        if (getEtabsSmartRenamePrefix("beam", source) === "T") {
            return {
                ...getEtabsSmartRenameWoodTrussProperties(source),
                length: getSmartRenameSegmentLength(source)
            };
        }

        const { name, ...section } = getBeamSectionDefinition(source);
        return {
            ...section,
            length: getSmartRenameSegmentLength(source)
        };
    }

    if (normalizedType === "slab") {
        const { name, ...section } = getSlabSectionDefinition(source);
        return {
            ...section,
            panel: getSmartRenameRectangularDimensions(source)
        };
    }

    if (normalizedType === "foundation") {
        const { name, h: sectionHeight, ...section } = getFoundationSectionDefinition(source);
        const normalized = source?.id ? normalizeFoundation(source) : normalizeFoundationInsertDraft(source);
        const supportingColumnSections = typeof getFoundationSupportingColumnSectionKeys === "function"
            ? getFoundationSupportingColumnSectionKeys(level, source)
            : undefined;

        // Strip footings are renamed by their width and depth (H), not by the
        // actual run length. Their longitudinal length may vary while still
        // representing the same footing type in plans and schedules.
        if (isStripFoundation(normalized)) {
            return {
                ...section,
                foundationType: "strip",
                width: normalized.b,
                thickness: normalized.thickness,
                ...(supportingColumnSections ? { supportingColumnSections } : {})
            };
        }

        return {
            ...section,
            foundationType: "isolated",
            width: normalized.b,
            length: normalized.h,
            thickness: normalized.thickness,
            ...(supportingColumnSections ? { supportingColumnSections } : {})
        };
    }

    if (normalizedType === "wall") {
        const normalizedWall = normalizeWall(source);

        // Reinforced-concrete wall marks describe a wall TYPE, not one exact
        // physical segment. Walls with the same thickness and reinforcement
        // therefore reuse the same MH/CW name even when their plan lengths or
        // storey heights differ. Masonry keeps its previous length-sensitive
        // grouping because its detailing can depend on the complete panel run.
        if (normalizedWall.material !== "masonry") {
            return {
                material: normalizedWall.material,
                b: normalizedWall.b,
                concrete: normalizedWall.concrete
            };
        }

        const { name, ...section } = getWallSectionDefinition(source);
        return {
            ...section,
            length: getSmartRenameSegmentLength(source)
        };
    }

    return {};
}

function getEtabsSmartRenameGroupKey(type, source = {}, level = null) {
    const prefix = getEtabsSmartRenamePrefix(type, source);
    if (!prefix) {
        return "";
    }

    return `${prefix}|${JSON.stringify(canonicalizeSmartRenameValue(getEtabsSmartRenameProperties(type, source, level)))}`;
}

function getEtabsSmartRenameBeamTypeProperties(source = {}, level = null) {
    const properties = {
        ...getEtabsSmartRenameProperties("beam", source, level)
    };
    delete properties.length;
    return properties;
}

function getEtabsSmartRenameContinuousWoodTrussGroupKey(chain, level = null) {
    const members = Array.isArray(chain?.members) ? chain.members.filter(Boolean) : [];
    if (!members.length || !members.every((beam) => getEtabsSmartRenamePrefix("beam", beam) === "T")) {
        return "";
    }

    const sectionSequence = [];
    let previousSignature = "";
    members.forEach((beam) => {
        const properties = getEtabsSmartRenameBeamTypeProperties(beam, level);
        const signature = JSON.stringify(canonicalizeSmartRenameValue(properties));
        if (signature !== previousSignature) {
            sectionSequence.push(properties);
            previousSignature = signature;
        }
    });

    const projectedLength = Math.abs(
        parseNumberOrFallback(chain?.end, Number.NaN)
        - parseNumberOrFallback(chain?.start, Number.NaN)
    );
    const summedLength = members.reduce((total, beam) => total + getSmartRenameSegmentLength(beam), 0);
    const length = Number((projectedLength > EDGE_TOLERANCE ? projectedLength : summedLength).toFixed(5));
    const properties = sectionSequence.length === 1
        ? { ...sectionSequence[0], length }
        : { sectionSequence, length };

    return `T|${JSON.stringify(canonicalizeSmartRenameValue(properties))}`;
}

function getEtabsSmartRenameContinuousBeamChains(level) {
    const beamOrder = new Map();
    (level?.beams || []).forEach((beam, index) => {
        if (beam?.id) {
            beamOrder.set(beam.id, index);
        }
    });

    return getContinuousBeamChainsForLevel(level)
        .map((chain, chainIndex) => {
            const uniqueMembers = [];
            const seenMemberIds = new Set();
            (chain?.members || []).forEach((beam) => {
                if (!beam?.id || seenMemberIds.has(beam.id)) {
                    return;
                }
                seenMemberIds.add(beam.id);
                uniqueMembers.push(beam);
            });

            const firstSeenOrder = uniqueMembers.reduce((minimum, beam) => (
                Math.min(minimum, beamOrder.get(beam.id) ?? Number.MAX_SAFE_INTEGER)
            ), Number.MAX_SAFE_INTEGER);

            return {
                ...chain,
                chainIndex,
                members: uniqueMembers,
                firstSeenOrder
            };
        })
        .filter((chain) => chain.members.length > 0)
        .sort((left, right) => (
            left.firstSeenOrder - right.firstSeenOrder
            || left.chainIndex - right.chainIndex
        ));
}

// A vertical column stack is a contiguous sequence of members at one plan
// coordinate.  Smart renaming intentionally assigns one name to every member
// in that stack, even where its section or reinforcement changes by storey.
function getEtabsSmartRenameColumnPositionKey(source = {}) {
    const normalized = normalizeColumnModel(source);
    return [
        Number(parseNumberOrFallback(normalized.x, 0).toFixed(3)),
        Number(parseNumberOrFallback(normalized.y, 0).toFixed(3))
    ].join("|");
}

function getEtabsSmartRenameColumnStacks(levels = projectState.levels) {
    const stacks = [];
    const activeStacksBySlot = new Map();
    let firstSeenOrder = 0;

    (Array.isArray(levels) ? levels : []).forEach((level, levelIndex) => {
        const entriesByPosition = new Map();
        (level?.columns || []).forEach((column, columnIndex) => {
            const positionKey = getEtabsSmartRenameColumnPositionKey(column);
            if (!entriesByPosition.has(positionKey)) {
                entriesByPosition.set(positionKey, []);
            }
            entriesByPosition.get(positionKey).push({ column, columnIndex, positionKey });
        });

        entriesByPosition.forEach((positionEntries, positionKey) => {
            positionEntries
                .sort((left, right) => left.columnIndex - right.columnIndex)
                .forEach((entry, duplicateIndex) => {
                    // A duplicate at the same coordinate is rare, but using an
                    // ordinal keeps the grouping deterministic without merging
                    // physically distinct members.
                    const slotKey = `${positionKey}|${duplicateIndex}`;
                    let stack = activeStacksBySlot.get(slotKey);
                    if (!stack || stack.lastLevelIndex !== levelIndex - 1) {
                        stack = {
                            positionKey,
                            firstSeenOrder: firstSeenOrder++,
                            entries: [],
                            lastLevelIndex: levelIndex - 1
                        };
                        stacks.push(stack);
                        activeStacksBySlot.set(slotKey, stack);
                    }

                    stack.entries.push({
                        level,
                        levelIndex,
                        column: entry.column,
                        positionKey
                    });
                    stack.lastLevelIndex = levelIndex;
                });
        });
    });

    return stacks;
}

function getEtabsSmartRenameColumnStackSignature(stack) {
    const entries = Array.isArray(stack?.entries) ? stack.entries : [];
    if (!entries.length) {
        return "";
    }

    return JSON.stringify(canonicalizeSmartRenameValue({
        startLevelIndex: entries[0].levelIndex,
        endLevelIndex: entries[entries.length - 1].levelIndex,
        sequence: entries.map((entry) => ({
            levelIndex: entry.levelIndex,
            properties: getEtabsSmartRenameProperties("column", entry.column, entry.level)
        }))
    }));
}

function createEtabsSmartRenameStats() {
    return {
        elements: 0,
        groups: 0,
        columns: 0,
        beams: 0,
        foundations: 0,
        slabs: 0,
        concreteWalls: 0,
        masonryWalls: 0
    };
}

function addEtabsSmartRenameGroupToStats(stats, type, prefix) {
    stats.groups += 1;
    if (type === "column") {
        stats.columns += 1;
    } else if (type === "beam") {
        stats.beams += 1;
    } else if (type === "foundation") {
        stats.foundations += 1;
    } else if (type === "slab") {
        stats.slabs += 1;
    } else if (type === "wall" && ["MH", "CW"].includes(prefix)) {
        stats.concreteWalls += 1;
    } else if (type === "wall" && prefix === "M") {
        stats.masonryWalls += 1;
    }
}

function applyEtabsSmartRenameToModel() {
    const groupNames = new Map();
    const prefixCounters = {
        C: 0,
        V: 0,
        T: 0,
        Z: 0,
        L: 0,
        MH: 0,
        CW: 0,
        M: 0
    };
    const stats = createEtabsSmartRenameStats();

    // Columns are renamed by continuous elevation stack first.  A second line
    // reuses C1 only when its entire level-by-level section/rebar sequence is
    // identical to the first line, not merely because one storey matches.
    getEtabsSmartRenameColumnStacks()
        .sort((left, right) => left.firstSeenOrder - right.firstSeenOrder)
        .forEach((stack) => {
            const signature = getEtabsSmartRenameColumnStackSignature(stack);
            if (!signature) {
                return;
            }

            const groupKey = `C|stack|${signature}`;
            if (!groupNames.has(groupKey)) {
                prefixCounters.C += 1;
                groupNames.set(groupKey, `C${prefixCounters.C}`);
                addEtabsSmartRenameGroupToStats(stats, "column", "C");
            }

            const name = groupNames.get(groupKey);
            stack.entries.forEach((entry) => {
                entry.column.name = name;
                stats.elements += 1;
            });
        });

    // Continuous concrete/steel lines keep one V mark. Wood trusses use a
    // separate T series and reuse the same mark when section and total length match.
    const renamedContinuousBeamIds = new Set();
    projectState.levels.forEach((level) => {
        getEtabsSmartRenameContinuousBeamChains(level)
            .filter((chain) => chain.members.length > 1)
            .forEach((chain) => {
                const isWoodTruss = chain.members.every((beam) => getEtabsSmartRenamePrefix("beam", beam) === "T");
                const prefix = isWoodTruss ? "T" : "V";
                const memberIds = chain.members.map((beam) => beam.id).sort();
                const groupKey = isWoodTruss
                    ? getEtabsSmartRenameContinuousWoodTrussGroupKey(chain, level)
                    : `V|continuous|${String(level?.id ?? "")}|${memberIds.join("|")}`;

                if (!groupKey) {
                    return;
                }

                if (!groupNames.has(groupKey)) {
                    prefixCounters[prefix] = (prefixCounters[prefix] || 0) + 1;
                    groupNames.set(groupKey, `${prefix}${prefixCounters[prefix]}`);
                    addEtabsSmartRenameGroupToStats(stats, "beam", prefix);
                }

                const name = groupNames.get(groupKey);
                chain.members.forEach((beam, spanIndex) => {
                    beam.name = name;
                    beam.spanNumber = spanIndex + 1;
                    beam.spanCount = chain.members.length;
                    renamedContinuousBeamIds.add(beam.id);
                    stats.elements += 1;
                });
            });
    });

    const renameTargets = [
        { type: "beam", collection: "beams" },
        { type: "foundation", collection: "foundations" },
        { type: "slab", collection: "slabs" },
        { type: "wall", collection: "walls" }
    ];

    projectState.levels.forEach((level) => {
        renameTargets.forEach((target) => {
            const entities = Array.isArray(level?.[target.collection]) ? level[target.collection] : [];
            entities.forEach((entity) => {
                if (target.type === "beam" && renamedContinuousBeamIds.has(entity?.id)) {
                    return;
                }

                const prefix = getEtabsSmartRenamePrefix(target.type, entity);
                const groupKey = getEtabsSmartRenameGroupKey(target.type, entity, level);
                if (!prefix || !groupKey) {
                    return;
                }

                if (!groupNames.has(groupKey)) {
                    prefixCounters[prefix] = (prefixCounters[prefix] || 0) + 1;
                    groupNames.set(groupKey, `${prefix}${prefixCounters[prefix]}`);
                    addEtabsSmartRenameGroupToStats(stats, target.type, prefix);
                }

                entity.name = groupNames.get(groupKey);
                stats.elements += 1;
            });
        });
    });

    if (stats.elements > 0) {
        updateUI();
        render();
    }

    return stats;
}
function hasEtabsSmartRenameTargets() {
    return projectState.levels.some((level) => (
        (level.columns?.length || 0) > 0
        || (level.beams?.length || 0) > 0
        || (level.foundations?.length || 0) > 0
        || (level.slabs?.length || 0) > 0
        || (level.walls?.length || 0) > 0
    ));
}

async function requestEtabsSmartRenameConfirmation() {
    if (!hasEtabsSmartRenameTargets()) {
        return false;
    }

    return requestAppConfirmation({
        title: translate("dialog.etabsSmartRenameTitle"),
        message: translate("grid.etabsSmartRenameConfirm"),
        confirmLabel: translate("dialog.etabsSmartRenameApply"),
        cancelLabel: translate("dialog.etabsSmartRenameKeep")
    });
}

function formatEtabsSmartRenameStats(stats) {
    if (!stats?.elements) {
        return "";
    }

    return translate("grid.etabsSmartRenameApplied", {
        columns: stats.columns,
        beams: stats.beams,
        foundations: stats.foundations,
        slabs: stats.slabs,
        concreteWalls: stats.concreteWalls,
        masonryWalls: stats.masonryWalls
    });
}

function getReusableEntityName(type, source = {}) {
    const normalizedType = type === "col" ? "column" : type;
    const targetKey = getEntitySectionPropertiesKey(normalizedType, source);
    if (!targetKey) {
        return "";
    }

    const existing = getAllModelEntities(normalizedType).find((entity) => (
        normalizeTextValue(entity?.name)
        && getEntitySectionPropertiesKey(normalizedType, entity) === targetKey
    ));

    return normalizeTextValue(existing?.name);
}

function resolveEntityName(type, proposedName, source = {}, levelId = null) {
    const normalizedType = type === "col" ? "column" : type;
    const normalizedName = normalizeTextValue(proposedName);
    if (normalizedName) {
        return normalizedName;
    }

    if (normalizedType === "beam") {
        const normalizedBeam = source?.id ? normalizeBeamModel(source) : normalizeBeamInsertDraft(source);
        const profileName = getBeamSteelProfileDisplayName(normalizedBeam);
        if (profileName) {
            return profileName;
        }
    }

    return getNextAvailableEntityName(normalizedType, source, new Set(), levelId);
}

function getLevelById(levelId) {
    return projectState.levels.find((level) => level.id === levelId) || null;
}

function normalizeSelectedElementType(type) {
    const normalizedType = type === "col" ? "column" : type;
    return ["column", "beam", "wall", "foundation", "slab", "hole"].includes(normalizedType)
        ? normalizedType
        : "";
}

function getSelectedElementDescriptorKey(descriptor) {
    return `${descriptor?.levelId ?? ""}|${descriptor?.type ?? ""}|${descriptor?.id ?? ""}`;
}

function normalizeSelectedElementDescriptor(descriptor) {
    const type = normalizeSelectedElementType(descriptor?.type);
    const id = descriptor?.id ?? descriptor?.entity?.id ?? "";
    const levelId = Number.parseInt(String(descriptor?.levelId ?? descriptor?.level?.id ?? ""), 10);

    if (!type || !id || !Number.isFinite(levelId)) {
        return null;
    }

    return {
        type,
        id,
        levelId
    };
}

function getSelectedElementDescriptors() {
    const sourceDescriptors = Array.isArray(projectState.selectedElements) && projectState.selectedElements.length
        ? projectState.selectedElements
        : projectState.selectedElement?.id
            ? [projectState.selectedElement]
            : [];

    const descriptors = [];
    const seenKeys = new Set();

    sourceDescriptors.forEach((descriptor) => {
        const normalized = normalizeSelectedElementDescriptor(descriptor);
        if (!normalized) {
            return;
        }

        const key = getSelectedElementDescriptorKey(normalized);
        if (seenKeys.has(key)) {
            return;
        }

        seenKeys.add(key);
        descriptors.push(normalized);
    });

    return descriptors;
}

function getSelectedElementRecords() {
    return getSelectedElementDescriptors()
        .map((descriptor) => {
            const level = getLevelById(descriptor.levelId);
            if (!level) {
                return null;
            }

            const entity = getEntityCollection(level, descriptor.type).find((item) => item.id === descriptor.id) || null;
            if (!entity) {
                return null;
            }

            return {
                ...descriptor,
                level,
                entity
            };
        })
        .filter(Boolean);
}

function hasSelectedElements() {
    return getSelectedElementRecords().length > 0;
}

function hasSingleSelectedElement() {
    return getSelectedElementRecords().length === 1;
}

function getSelectedElementRecord() {
    const selectedRecords = getSelectedElementRecords();
    return selectedRecords.length === 1 ? selectedRecords[0] : null;
}

function getEntityTypePluralLabel(type) {
    const normalizedType = normalizeSelectedElementType(type);
    const pluralLabels = projectState.language === "en"
        ? {
            column: "columns",
            beam: "beams",
            wall: "walls",
            foundation: "foundations",
            slab: "slabs",
            hole: "holes"
        }
        : {
            column: "columnas",
            beam: "vigas",
            wall: "muros",
            foundation: "zapatas",
            slab: "losas",
            hole: "huecos"
        };

    return pluralLabels[normalizedType] || getEntityTypeLabel(normalizedType);
}

function getSelectedElementSelectionContext(records = getSelectedElementRecords()) {
    const selectedRecords = Array.isArray(records) ? records.filter(Boolean) : [];
    if (!selectedRecords.length) {
        return null;
    }

    const sameType = new Set(selectedRecords.map((record) => record.type)).size === 1;
    const sameLevel = new Set(selectedRecords.map((record) => record.level?.id)).size === 1;
    const primaryRecord = selectedRecords[0] || null;
    const type = sameType ? primaryRecord?.type || "" : "";
    const level = sameLevel ? primaryRecord?.level || null : null;

    return {
        records: selectedRecords,
        count: selectedRecords.length,
        sameType,
        sameLevel,
        type,
        builderType: type === "column"
            ? "col"
            : type === "hole"
                ? "slab"
                : type,
        level,
        levelId: level?.id ?? null,
        levelName: sameLevel
            ? level?.name ?? ""
            : state.language === "en"
                ? "multiple levels"
                : "varios niveles",
        primaryRecord,
        isGroupEditable: selectedRecords.length > 1 && sameType && ["column", "beam", "wall", "foundation", "slab", "hole"].includes(type),
        isMixedSelection: selectedRecords.length > 1 && !sameType
    };
}

function getSelectionGroupTitle(context) {
    if (!context?.count || !context?.type) {
        return "";
    }

    const count = String(context.count);
    const typeLabel = getEntityTypePluralLabel(context.type);
    return projectState.language === "en"
        ? `${count} ${typeLabel} selected`
        : `${count} ${typeLabel} seleccionados`;
}

function getMixedSelectionTitle(context) {
    if (!context?.count) {
        return "";
    }

    const count = String(context.count);
    return projectState.language === "en"
        ? `${count} elements selected`
        : `${count} elementos seleccionados`;
}

function getSelectionFeedbackStrings(context) {
    if (!context) {
        return null;
    }

    if (context.count === 1 && context.primaryRecord) {
        return {
            kicker: translate("workspace.selectionKicker"),
            title: translate("workspace.selectionTitle", {
                name: getSelectedElementDisplayName(context.primaryRecord)
            }),
            note: translate("workspace.selectionNote", {
                type: getEntityTypeLabel(context.primaryRecord.type),
                level: context.primaryRecord.level?.name || ""
            })
        };
    }

    if (context.isGroupEditable) {
        const typeLabel = getEntityTypePluralLabel(context.type);
        return {
            kicker: projectState.language === "en" ? "MULTIPLE SELECTION" : "SELECCION MULTIPLE",
            title: getSelectionGroupTitle(context),
            note: translate("workspace.selectionNote", {
                type: typeLabel,
                level: context.levelName
            })
        };
    }

    return {
        kicker: projectState.language === "en" ? "MULTIPLE SELECTION" : "SELECCION MULTIPLE",
        title: getMixedSelectionTitle(context),
        note: projectState.language === "en"
            ? "Different element types are selected. Only Delete is available."
            : "Hay elementos de distintos tipos seleccionados. Solo se puede borrar con Supr/Delete."
    };
}

function getDomFieldValueOrNull(fieldId) {
    const field = document.getElementById(fieldId);
    if (!field) {
        return null;
    }

    const value = String(field.value ?? "").trim();
    return value ? field.value : null;
}

function getDomCheckboxValueOrNull(fieldId) {
    const field = document.getElementById(fieldId);
    if (!field) {
        return null;
    }

    return field.indeterminate ? null : Boolean(field.checked);
}

function setDomFieldValue(fieldId, value) {
    const field = document.getElementById(fieldId);
    if (!field) {
        return;
    }

    const normalizedValue = value === null || value === undefined ? "" : String(value);
    const isMixedValue = false;
    const mixedLabel = translate("common.mixedValue") || "—";

    if (field.tagName === "SELECT") {
        const mixedOption = field.querySelector('option[data-mixed-placeholder="true"]');
        if (isMixedValue) {
            if (mixedOption) {
                mixedOption.textContent = mixedLabel;
            } else {
                const option = document.createElement("option");
                option.value = "";
                option.textContent = mixedLabel;
                option.dataset.mixedPlaceholder = "true";
                field.insertBefore(option, field.firstChild);
            }
            field.value = "";
            field.classList.add("is-mixed-value");
        } else {
            if (mixedOption) {
                mixedOption.remove();
            }
            field.value = normalizedValue;
            field.classList.remove("is-mixed-value");
        }
        return;
    }

    if (isMixedValue) {
        if (field.dataset.mixedPlaceholderOriginal === undefined) {
            field.dataset.mixedPlaceholderOriginal = field.getAttribute("placeholder") || "";
        }
        field.value = "";
        field.setAttribute("placeholder", mixedLabel);
        field.classList.add("is-mixed-value");
        return;
    }

    field.value = normalizedValue;
    if (field.dataset.mixedPlaceholderOriginal !== undefined) {
        const originalPlaceholder = field.dataset.mixedPlaceholderOriginal;
        if (originalPlaceholder) {
            field.setAttribute("placeholder", originalPlaceholder);
        } else {
            field.removeAttribute("placeholder");
        }
        delete field.dataset.mixedPlaceholderOriginal;
    }
    field.classList.remove("is-mixed-value");
}

const SELECTION_COMMON_VALUE_MIXED = Symbol("selection-common-value-mixed");

function setDomFieldMixedValue(fieldId, mixedLabel = translate("common.mixedValue") || "—") {
    const field = document.getElementById(fieldId);
    if (!field) {
        return;
    }

    if (field.tagName === "SELECT") {
        const mixedOption = field.querySelector('option[data-mixed-placeholder="true"]');
        if (mixedOption) {
            mixedOption.textContent = mixedLabel;
        } else {
            const option = document.createElement("option");
            option.value = "";
            option.textContent = mixedLabel;
            option.dataset.mixedPlaceholder = "true";
            field.insertBefore(option, field.firstChild);
        }
        field.value = "";
        field.classList.add("is-mixed-value");
        return;
    }

    if (field.dataset.mixedPlaceholderOriginal === undefined) {
        field.dataset.mixedPlaceholderOriginal = field.getAttribute("placeholder") || "";
    }
    field.value = "";
    field.setAttribute("placeholder", mixedLabel);
    field.classList.add("is-mixed-value");
}

function setDomSelectionFieldValue(fieldId, value) {
    if (value === SELECTION_COMMON_VALUE_MIXED) {
        setDomFieldMixedValue(fieldId);
        return;
    }

    setDomFieldValue(fieldId, value);
}

function setDomCheckboxValue(fieldId, value) {
    const field = document.getElementById(fieldId);
    if (!field) {
        return;
    }

    const isMixedValue = value === null || value === undefined || value === SELECTION_COMMON_VALUE_MIXED;
    field.indeterminate = isMixedValue;
    field.checked = !isMixedValue && Boolean(value);
}

function setDomRadioGroupValue(yesFieldId, noFieldId, value) {
    const yesField = document.getElementById(yesFieldId);
    const noField = document.getElementById(noFieldId);
    if (!yesField || !noField) {
        return;
    }

    if (value === SELECTION_COMMON_VALUE_MIXED || value === null || value === undefined) {
        yesField.checked = false;
        noField.checked = false;
        return;
    }

    yesField.checked = value === "x";
    noField.checked = value === "y";
}

function getSelectionComparableValue(value) {
    if (value === null || value === undefined) {
        return "";
    }

    if (typeof value === "boolean") {
        return value ? "true" : "false";
    }

    if (typeof value === "number") {
        return Number.isFinite(value) ? String(value) : "";
    }

    if (typeof value === "object") {
        return JSON.stringify(value);
    }

    return String(value);
}

function getCommonSelectionValue(records, getter) {
    if (!Array.isArray(records) || records.length === 0 || typeof getter !== "function") {
        return null;
    }

    const firstValue = getter(records[0]);
    const firstComparableValue = getSelectionComparableValue(firstValue);
    for (let index = 1; index < records.length; index += 1) {
        if (getSelectionComparableValue(getter(records[index])) !== firstComparableValue) {
            return SELECTION_COMMON_VALUE_MIXED;
        }
    }

    return firstValue;
}

