function setSelectedElementDescriptors(descriptors, { shouldRender = true } = {}) {
    const normalizedDescriptors = [];
    const seenKeys = new Set();

    (Array.isArray(descriptors) ? descriptors : []).forEach((descriptor) => {
        const normalized = normalizeSelectedElementDescriptor(descriptor);
        if (!normalized) {
            return;
        }

        const key = getSelectedElementDescriptorKey(normalized);
        if (seenKeys.has(key)) {
            return;
        }

        seenKeys.add(key);
        normalizedDescriptors.push(normalized);
    });

    projectState.selectedElements = normalizedDescriptors;
    projectState.selectedElement = normalizedDescriptors.length === 1
        ? { ...normalizedDescriptors[0] }
        : null;

    if (shouldRender) {
        updateUI();
        render();
    }
}

function clearSelectedElements({ shouldRender = true } = {}) {
    setSelectedElementDescriptors([], { shouldRender });
}

function clearSelectedElement(options = {}) {
    clearSelectedElements(options);
}

function setSelectedElement(type, entity, levelId = projectState.activeLevelId, { shouldRender = true } = {}) {
    if (!entity?.id) {
        clearSelectedElements({ shouldRender });
        return;
    }

    setSelectedElementDescriptors([{
        type: normalizeSelectedElementType(type),
        id: entity.id,
        levelId
    }], { shouldRender });
}

function addSelectedElement(type, entity, levelId = projectState.activeLevelId, { shouldRender = true } = {}) {
    if (!entity?.id) {
        return;
    }

    const descriptors = getSelectedElementDescriptors();
    descriptors.push({
        type: normalizeSelectedElementType(type),
        id: entity.id,
        levelId
    });
    setSelectedElementDescriptors(descriptors, { shouldRender });
}

function removeSelectedElement(type, id, levelId = projectState.activeLevelId, { shouldRender = true } = {}) {
    const nextDescriptors = getSelectedElementDescriptors().filter((descriptor) => !(
        descriptor.type === normalizeSelectedElementType(type)
        && descriptor.id === id
        && descriptor.levelId === levelId
    ));

    setSelectedElementDescriptors(nextDescriptors, { shouldRender });
}

function toggleSelectedElement(type, entity, levelId = projectState.activeLevelId, { shouldRender = true } = {}) {
    if (!entity?.id) {
        return;
    }

    const normalizedType = normalizeSelectedElementType(type);
    const key = getSelectedElementDescriptorKey({
        type: normalizedType,
        id: entity.id,
        levelId
    });
    const descriptors = getSelectedElementDescriptors();
    const existingIndex = descriptors.findIndex((descriptor) => getSelectedElementDescriptorKey(descriptor) === key);

    if (existingIndex >= 0) {
        descriptors.splice(existingIndex, 1);
    } else {
        descriptors.push({
            type: normalizedType,
            id: entity.id,
            levelId
        });
    }

    setSelectedElementDescriptors(descriptors, { shouldRender });
}

function isSelectedElement(type, id, levelId = projectState.activeLevelId) {
    const normalizedType = normalizeSelectedElementType(type);
    return getSelectedElementDescriptors().some((descriptor) => (
        descriptor.type === normalizedType
        && descriptor.id === id
        && descriptor.levelId === levelId
    ));
}

function createLevel(id, name, height) {
    return { id, name, height, columns: [], beams: [], braces: [], walls: [], foundations: [], slabs: [], holes: [] };
}

function normalizeColumnModel(column) {
    const sectionShape = normalizeColumnSectionShape(column?.sectionShape ?? column?.columnShape, column);
    const structuralMaterial = normalizeStructuralMaterialSpec(column?.structuralMaterial);
    const isConcreteColumn = structuralMaterial.type === "concrete";
    const longRebar = isConcreteColumn
        ? normalizeColumnLongitudinalRebar(column.longRebar ?? column.longitudinalRebar, { sectionShape })
        : null;
    const sectionDiameter = getColumnDiameter({ ...column, sectionShape });
    return {
        ...column,
        id: column?.id ?? createEntityId("column"),
        name: normalizeTextValue(column?.name),
        sectionShape,
        diameter: sectionShape === COLUMN_SECTION_SHAPE_CIRCULAR ? sectionDiameter : undefined,
        b: sectionShape === COLUMN_SECTION_SHAPE_CIRCULAR ? sectionDiameter : getColumnWidth(column),
        h: sectionShape === COLUMN_SECTION_SHAPE_CIRCULAR ? sectionDiameter : getColumnHeight(column),
        structuralMaterial,
        longRebar,
        stirrups: isConcreteColumn ? normalizeColumnTransverseRebar(column.stirrups, longRebar) : null
    };
}

function normalizeBeamModel(beam) {
    const coverTop = normalizeBeamCover(beam?.coverTop, DRAWING_COVER);
    const coverBottom = normalizeBeamCover(beam?.coverBottom, DRAWING_COVER);
    return {
        ...beam,
        name: normalizeContinuousBeamDisplayName(beam?.name, beam),
        spanNumber: getBeamSpanNumber(beam),
        spanCount: getBeamSpanCount(beam),
        b: parsePositiveNumberOrFallback(beam?.b, 0.3, 0.1),
        h: parsePositiveNumberOrFallback(beam?.h, 0.5, 0.1),
        structuralMaterial: normalizeStructuralMaterialSpec(beam?.structuralMaterial),
        topRebar: normalizeBeamMainLongitudinalRebar(beam?.topRebar),
        botRebar: normalizeBeamMainLongitudinalRebar(beam?.botRebar),
        stirrups: getRepresentativeBeamTransverseRebar(beam?.transverseRebarZones, beam?.stirrups),
        transverseRebarZones: normalizeBeamTransverseRebarZones(beam?.transverseRebarZones, beam?.stirrups),
        coverTop,
        coverBottom,
        coverSide: getBeamSideCover(coverTop, coverBottom),
        steelDemands: normalizeBeamSteelDemands(beam?.steelDemands),
        transverseSteelDemands: normalizeBeamTransverseSteelDemands(beam?.transverseSteelDemands),
        additionalRebar: normalizeBeamAdditionalRebar(beam?.additionalRebar),
        sectionCuts: normalizeSectionCuts(beam?.sectionCuts, beam)
    };
}

function normalizeBracingType(type) {
    const normalized = normalizeTextValue(type).toLowerCase().replace(/[_\s]+/g, "-");
    if (normalized === "v" || normalized === "chevron-v") {
        return "v";
    }
    if (normalized === "x" || normalized === "cross" || normalized === "cross-bracing") {
        return "x";
    }
    return "inverted-v";
}

function normalizeBracingModel(bracing) {
    const steelProfile = bracing?.steelProfile && typeof bracing.steelProfile === "object"
        ? { ...bracing.steelProfile, dimensions: bracing.steelProfile.dimensions ? { ...bracing.steelProfile.dimensions } : bracing.steelProfile.dimensions }
        : null;
    return {
        ...(bracing || {}),
        id: bracing?.id ?? createEntityId("bracing"),
        name: normalizeTextValue(bracing?.name),
        type: normalizeBracingType(bracing?.type),
        x1: roundCoordinate(parseNumberOrFallback(bracing?.x1 ?? bracing?.start?.x, 0)),
        y1: roundCoordinate(parseNumberOrFallback(bracing?.y1 ?? bracing?.start?.y, 0)),
        x2: roundCoordinate(parseNumberOrFallback(bracing?.x2 ?? bracing?.end?.x, 0)),
        y2: roundCoordinate(parseNumberOrFallback(bracing?.y2 ?? bracing?.end?.y, 0)),
        centerOffset: parseNumberOrFallback(bracing?.centerOffset ?? bracing?.center, 0),
        leftOffset: Math.max(parseNumberOrFallback(bracing?.leftOffset ?? bracing?.left, 0), 0),
        rightOffset: Math.max(parseNumberOrFallback(bracing?.rightOffset ?? bracing?.right, 0), 0),
        sourceSection: normalizeTextValue(bracing?.sourceSection || bracing?.sectionName || steelProfile?.name),
        sourceShape: normalizeTextValue(bracing?.sourceShape || steelProfile?.shape),
        steelProfile,
        b: parsePositiveNumberOrFallback(bracing?.b, 0.15, 0.03),
        h: parsePositiveNumberOrFallback(bracing?.h, 0.15, 0.03),
        structuralMaterial: {
            ...normalizeStructuralMaterialSpec(bracing?.structuralMaterial),
            type: "steel"
        },
        importedMembers: Array.isArray(bracing?.importedMembers)
            ? bracing.importedMembers.map((member) => ({ ...member }))
            : undefined
    };
}

function getBracingPlanLength(bracing) {
    const normalized = normalizeBracingModel(bracing);
    return Math.hypot(normalized.x2 - normalized.x1, normalized.y2 - normalized.y1);
}

function getBracingElevationSegments(bracing, baseZ = 0, topZ = 1) {
    const normalized = normalizeBracingModel(bracing);
    const span = getBracingPlanLength(normalized);
    if (span <= EDGE_TOLERANCE) {
        return [];
    }
    const left = Math.min(Math.max(normalized.leftOffset, 0), span);
    const right = Math.max(Math.min(span - normalized.rightOffset, span), 0);
    const center = Math.min(Math.max(span / 2 + normalized.centerOffset, 0), span);
    if (normalized.type === "x") {
        return [
            { a: 0, z1: baseZ, b: span, z2: topZ },
            { a: span, z1: baseZ, b: 0, z2: topZ }
        ];
    }
    if (normalized.type === "v") {
        return [
            { a: left, z1: topZ, b: center, z2: baseZ },
            { a: center, z1: baseZ, b: right, z2: topZ }
        ];
    }
    return [
        { a: left, z1: baseZ, b: center, z2: topZ },
        { a: center, z1: topZ, b: right, z2: baseZ }
    ];
}

function cloneBracing(bracing) {
    return normalizeBracingModel(bracing);
}

function cloneColumn(column) {
    return normalizeColumnModel(column);
}

function cloneBeam(beam) {
    return {
        ...normalizeBeamModel(beam),
        sectionCuts: [...normalizeSectionCuts(beam?.sectionCuts, beam)]
    };
}

function cloneWall(wall) {
    return normalizeWall(wall);
}

function cloneSlab(slab) {
    return normalizeSlab({
        ...slab,
        vertices: Array.isArray(slab?.vertices) ? slab.vertices.map((vertex) => ({ ...vertex })) : undefined,
        temperatureSteel: { ...slab?.temperatureSteel },
        solid: { ...slab?.solid },
        lightened: {
            ...slab?.lightened,
            xZones: { ...slab?.lightened?.xZones },
            yZones: { ...slab?.lightened?.yZones }
        },
        metalDeck: { ...slab?.metalDeck }
    });
}

function cloneFoundation(foundation) {
    return normalizeFoundation(foundation);
}

function cloneLevel(level, id, name) {
    const sourceBottomElevation = parseNumberOrFallback(level?.sourceBottomElevation, Number.NaN);
    const sourceTopElevation = parseNumberOrFallback(level?.sourceTopElevation, Number.NaN);
    return {
        id,
        name,
        height: parseNumberOrFallback(level.height, 3.0),
        ...(Number.isFinite(sourceBottomElevation) ? { sourceBottomElevation } : {}),
        ...(Number.isFinite(sourceTopElevation) ? { sourceTopElevation } : {}),
        columns: (level.columns || []).map(cloneColumn),
        beams: (level.beams || []).map(cloneBeam),
        braces: (level.braces || []).map(cloneBracing),
        walls: (level.walls || []).map(cloneWall),
        foundations: (level.foundations || []).map(cloneFoundation),
        slabs: (level.slabs || []).map(cloneSlab),
        holes: (level.holes || []).map(cloneSlab)
    };
}

function createDefaultTransverseRebar(spacing) {
    return {
        d: DEFAULT_TRANSVERSE_DIAMETER,
        spacing
    };
}

function createDefaultColumnLongitudinalRebar(count = DEFAULT_COLUMN_DIRECTION_BAR_COUNT, diameter = DEFAULT_LONGITUDINAL_DIAMETER) {
    const normalizedCount = Math.max(Number.parseInt(count, 10) || DEFAULT_COLUMN_DIRECTION_BAR_COUNT, 2);
    const normalizedDiameter = normalizeDiameterLabel(diameter) || DEFAULT_LONGITUDINAL_DIAMETER;

    return {
        xCount: normalizedCount,
        xDiameter: normalizedDiameter,
        yCount: normalizedCount,
        yDiameter: normalizedDiameter,
        cornerDiameter: normalizedDiameter,
        hasCustomCornerDiameter: false
    };
}

function createDefaultColumnTransverseRebar(longRebar = createDefaultColumnLongitudinalRebar()) {
    return normalizeColumnTransverseRebar({
        d: DEFAULT_TRANSVERSE_DIAMETER,
        spacing: DEFAULT_COLUMN_TIE_SPACING,
        count: DEFAULT_COLUMN_STIRRUP_COUNT
    }, longRebar);
}

function createDefaultMasonryTieColumnSpec() {
    const longRebar = normalizeColumnLongitudinalRebar({
        xCount: 2,
        xDiameter: '1/2"',
        yCount: 2,
        yDiameter: '1/2"',
        cornerDiameter: '1/2"',
        hasCustomCornerDiameter: false
    });
    return {
        b: 0.2,
        h: 0.2,
        longRebar,
        stirrups: normalizeColumnTransverseRebar({
            d: '3/8"',
            spacing: 0.3,
            count3Dir: 2,
            count2Dir: 2,
            cover: 0.03
        }, longRebar)
    };
}

function normalizeMasonryTieColumnSpec(spec, fallback = createDefaultMasonryTieColumnSpec()) {
    const fallbackSpec = fallback && typeof fallback === 'object' ? fallback : createDefaultMasonryTieColumnSpec();
    const longRebar = normalizeColumnLongitudinalRebar(spec?.longRebar ?? spec?.longitudinalRebar ?? fallbackSpec.longRebar);
    return {
        b: parsePositiveNumberOrFallback(spec?.b, fallbackSpec.b, 0.05),
        h: parsePositiveNumberOrFallback(spec?.h, fallbackSpec.h, 0.05),
        longRebar,
        stirrups: normalizeColumnTransverseRebar(spec?.stirrups ?? fallbackSpec.stirrups, longRebar)
    };
}


// Masonry tie beams use a compact, explicit reinforcement spec rather than
// inheriting the generic beam defaults. Keeping the values on the wall allows
// the model, DXF and downstream exports to agree on the same detailing.
function createDefaultMasonryTieBeamSpec() {
    return {
        topRebar: normalizeBeamMainLongitudinalRebar({ n: '2', d: '3/8"' }),
        botRebar: normalizeBeamMainLongitudinalRebar({ n: '2', d: '3/8"' }),
        stirrups: normalizeTransverseRebar({ d: '3/8"', spacing: 0.20 }, 0.20),
        // Masonry tie beams default to a 30 mm cover at both concrete faces.
        coverTop: 0.03,
        coverBottom: 0.03
    };
}

function normalizeMasonryTieBeamSpec(spec, fallback = createDefaultMasonryTieBeamSpec()) {
    const fallbackSpec = fallback && typeof fallback === 'object'
        ? fallback
        : createDefaultMasonryTieBeamSpec();
    return {
        topRebar: normalizeBeamMainLongitudinalRebar(
            spec?.topRebar ?? spec?.top ?? spec?.upperRebar ?? fallbackSpec.topRebar
        ),
        botRebar: normalizeBeamMainLongitudinalRebar(
            spec?.botRebar ?? spec?.bottomRebar ?? spec?.bottom ?? spec?.lowerRebar ?? fallbackSpec.botRebar
        ),
        stirrups: normalizeTransverseRebar(
            spec?.stirrups ?? spec?.transverseRebar ?? fallbackSpec.stirrups,
            parsePositiveNumberOrFallback(fallbackSpec?.stirrups?.spacing, 0.20, 0.05)
        ),
        coverTop: normalizeBeamCover(
            spec?.coverTop ?? spec?.topCover ?? spec?.upperCover ?? fallbackSpec?.coverTop,
            0.03
        ),
        coverBottom: normalizeBeamCover(
            spec?.coverBottom ?? spec?.bottomCover ?? spec?.lowerCover ?? fallbackSpec?.coverBottom,
            0.03
        )
    };
}

function normalizeMasonryEndColumnEnabled(value, fallbackEnabled = true) {
    if (typeof value === "boolean") {
        return value;
    }
    if (typeof value === "number") {
        return value !== 0;
    }
    if (typeof value === "string") {
        const normalized = value.trim().toLowerCase();
        if (["false", "0", "off", "no", "unchecked", "disabled"].includes(normalized)) {
            return false;
        }
        if (["true", "1", "on", "yes", "checked", "enabled"].includes(normalized)) {
            return true;
        }
    }
    return fallbackEnabled;
}

function normalizeMasonryEndColumnConfig(config = {}, fallbackEnabled = true) {
    const fallbackSpec = createDefaultMasonryTieColumnSpec();
    const isPrimitiveToggle = typeof config === "boolean" || typeof config === "number" || typeof config === "string";
    const rawSection = isPrimitiveToggle
        ? undefined
        : config?.section ?? config?.column ?? config;
    const rawEnabled = isPrimitiveToggle
        ? config
        : config?.enabled
            ?? config?.includeTieColumn
            ?? config?.include;
    const hasExplicitEnabled = rawEnabled !== undefined && rawEnabled !== null && rawEnabled !== "";
    return {
        // Preserve every explicit off value from saved projects. The DXF generator
        // uses this flag for the column geometry, callouts, dimensions and quantities.
        enabled: hasExplicitEnabled
            ? normalizeMasonryEndColumnEnabled(rawEnabled, fallbackEnabled)
            : fallbackEnabled,
        section: normalizeMasonryTieColumnSpec(rawSection, fallbackSpec)
    };
}

function normalizeMasonryEndColumnsConfig(source = {}) {
    const sourceConfig = source && typeof source === "object" ? source : {};
    return {
        left: normalizeMasonryEndColumnConfig(sourceConfig.left, true),
        right: normalizeMasonryEndColumnConfig(sourceConfig.right, true)
    };
}


function normalizeMasonryEndColumnsForWallWidth(source = {}, masonryBlockWidth = DEFAULT_MASONRY_BLOCK_WIDTH) {
    // Tie columns at a masonry wall end are square and match the normalized
    // block thickness: 0.15 m (6 in) or 0.20 m (8 in). Keep the reinforcement
    // configuration and enabled state, but never retain a mismatched section.
    const normalizedWallWidth = normalizeMasonryBlockWidth(
        masonryBlockWidth,
        DEFAULT_MASONRY_BLOCK_WIDTH
    );
    const endColumns = normalizeMasonryEndColumnsConfig(source);
    const normalizeSide = (side) => {
        const section = normalizeMasonryTieColumnSpec(side?.section);
        return {
            ...side,
            section: {
                ...section,
                b: normalizedWallWidth,
                h: normalizedWallWidth
            }
        };
    };
    return {
        left: normalizeSide(endColumns.left),
        right: normalizeSide(endColumns.right)
    };
}

function createDefaultWallSection(unitSystem = null) {
    const defaultSpacing = getDefaultWallRebarSpacing(unitSystem);
    const defaultCover = getDefaultConcreteWallCover(unitSystem);
    return {
        material: "concrete",
        concrete: {
            reinforcementMode: WALL_REINFORCEMENT_MODE_SPACING,
            longitudinalDiameter: DEFAULT_WALL_LONGITUDINAL_DIAMETER,
            longitudinalSpacing: defaultSpacing,
            longitudinalCount: DEFAULT_WALL_LONGITUDINAL_COUNT,
            longitudinalGrouped: DEFAULT_WALL_LONGITUDINAL_GROUPED,
            horizontalDiameter: DEFAULT_WALL_LONGITUDINAL_DIAMETER,
            horizontalSpacing: defaultSpacing,
            includeHooks: true,
            transverseDiameter: DEFAULT_WALL_TRANSVERSE_DIAMETER,
            transverseSpacing: defaultSpacing,
            transverseCount: DEFAULT_WALL_TRANSVERSE_COUNT,
            weldedWireMesh: DEFAULT_THIN_WALL_WELDED_MESH,
            cover: defaultCover
        },
        masonry: {
            blockWidth: DEFAULT_MASONRY_BLOCK_WIDTH,
            fillMode: "all",
            barDiameter: DEFAULT_MASONRY_BAR_DIAMETER,
            barsPerCell: DEFAULT_MASONRY_BARS_PER_CELL,
            horizontalBarDiameter: DEFAULT_MASONRY_BAR_DIAMETER,
            horizontalSpacing: 0.6,
            includeTieBeam: true,
            tieBeam: createDefaultMasonryTieBeamSpec(),
            wallType: "masonry",
            endColumns: normalizeMasonryEndColumnsConfig()
        }
    };
}


function normalizeWallMaterialType(value) {
    const normalized = normalizeTextValue(value).toLowerCase();
    if (normalized === "masonry") {
        return "masonry";
    }
    if (["thin_wall", "thin-wall", "thinwall", "pared_delgada", "pared-delgada", "wall_thin", "wall-thin"].includes(normalized)) {
        return "thin_wall";
    }
    return "concrete";
}

function isMasonryWallMaterial(material) {
    return normalizeWallMaterialType(material) === "masonry";
}

function isThinWallMaterial(material) {
    return normalizeWallMaterialType(material) === "thin_wall";
}

function getWallMaterialDisplayLabel(material) {
    const normalized = normalizeWallMaterialType(material);
    if (normalized === "masonry") {
        return translate("modal.wallMasonry");
    }
    if (normalized === "thin_wall") {
        return translate("modal.wallThin");
    }
    return translate("modal.wallConcrete");
}


function createColumn(x, y, draft = projectState.insertDrafts.col, levelId = null) {
    const normalizedDraft = normalizeColumnInsertDraft(draft);
    return {
        id: createEntityId("column"),
        name: resolveEntityName("column", normalizedDraft.name, {
            ...normalizedDraft,
            x,
            y
        }, levelId),
        x,
        y,
        b: normalizedDraft.b,
        h: normalizedDraft.h,
        structuralMaterial: normalizedDraft.structuralMaterial,
        longRebar: normalizedDraft.longRebar,
        stirrups: normalizedDraft.stirrups
    };
}

function getAllModelColumns() {
    return projectState.levels.flatMap((level) => level.columns || []);
}

function getColumnSectionDefinition(source) {
    const normalized = normalizeColumnInsertDraft(source);
    return {
        name: normalized.name,
        sectionShape: normalized.sectionShape,
        diameter: normalized.diameter,
        b: normalized.b,
        h: normalized.h,
        sourceSection: normalized.sourceSection,
        sourceShape: normalized.sourceShape,
        structuralMaterial: normalized.structuralMaterial,
        longRebar: normalized.longRebar,
        stirrups: normalized.stirrups
    };
}

function getColumnSectionPropertiesKey(source) {
    const section = getColumnSectionDefinition(source);
    return JSON.stringify({
        sourceSection: normalizeTextValue(source?.sourceSection),
        sourceShape: normalizeTextValue(source?.sourceShape),
        sectionShape: section.sectionShape,
        diameter: section.diameter,
        steelProfile: source?.steelProfile || null,
        b: section.b,
        h: section.h,
        structuralMaterial: section.structuralMaterial,
        longRebar: section.longRebar,
        stirrups: section.stirrups
    });
}

function getColumnSectionName(source) {
    return normalizeTextValue(source?.name);
}

function getColumnsBySectionName(name, excludedIds = new Set(), levelId = null) {
    const normalizedName = normalizeTextValue(name);
    if (!normalizedName) {
        return [];
    }

    const columns = levelId == null
        ? getAllModelColumns()
        : (projectState.levels.find((level) => String(level?.id) === String(levelId))?.columns || []);
    return columns.filter((column) => (
        getColumnSectionName(column) === normalizedName
        && !excludedIds.has(column.id)
    ));
}

function getColumnsWithConflictingSectionByName(section, excludedIds = new Set(), levelId = null) {
    const normalizedName = getColumnSectionName(section);
    if (!normalizedName) {
        return [];
    }

    const targetKey = getColumnSectionPropertiesKey(section);
    return getColumnsBySectionName(normalizedName, excludedIds, levelId).filter((column) => (
        getColumnSectionPropertiesKey(column) !== targetKey
    ));
}

function applyColumnSectionToColumn(column, section) {
    if (!column) {
        return column;
    }

    Object.assign(column, normalizeColumnModel({
        ...column,
        ...getColumnSectionDefinition(section)
    }));
    return column;
}

function updateColumnSectionsByNames(section, names = [], levelId = null) {
    const normalizedNames = Array.from(new Set(
        (Array.isArray(names) ? names : Array.from(names || []))
            .map((name) => normalizeTextValue(name))
            .filter(Boolean)
    ));
    const updatedIds = new Set();

    if (!normalizedNames.length) {
        return updatedIds;
    }

    const levels = levelId == null
        ? projectState.levels
        : projectState.levels.filter((level) => String(level?.id) === String(levelId));
    levels.forEach((level) => {
        (level.columns || []).forEach((column) => {
            if (!normalizedNames.includes(getColumnSectionName(column))) {
                return;
            }

            applyColumnSectionToColumn(column, section);
            updatedIds.add(column.id);
        });
    });

    return updatedIds;
}

function getColumnSectionGroupIds(name, levelId = null) {
    return new Set(getColumnsBySectionName(name, new Set(), levelId).map((column) => column.id));
}

function requestColumnSectionConflictResolution(name) {
    return requestAppConfirmation({
        title: translate("dialog.columnConflictTitle"),
        message: translate("dialog.columnConflictMessage", { name }),
        cancelLabel: translate("dialog.columnConflictRenameAction"),
        confirmLabel: translate("dialog.columnConflictUpdateAction")
    });
}

function getBeamSectionDefinition(source) {
    const normalized = source?.id ? normalizeBeamModel(source) : normalizeBeamInsertDraft(source);
    return {
        name: normalized.name,
        b: normalized.b,
        h: normalized.h,
        sourceSection: normalized.sourceSection || normalizeTextValue(source?.sourceSection || source?.sectionName),
        sourceShape: normalized.sourceShape || normalizeTextValue(source?.sourceShape || source?.shape),
        steelProfile: normalized.steelProfile || source?.steelProfile || null,
        structuralMaterial: normalized.structuralMaterial,
        topRebar: normalized.topRebar,
        botRebar: normalized.botRebar,
        stirrups: normalized.stirrups,
        additionalRebar: normalized.additionalRebar,
        sectionCuts: normalized.sectionCuts,
        coverTop: normalized.coverTop,
        coverBottom: normalized.coverBottom
    };
}

function getWallSectionDefinition(source) {
    const normalized = normalizeWall(source);
    return {
        name: normalized.name,
        b: normalized.b,
        h: normalized.h,
        structuralMaterial: normalized.structuralMaterial,
        material: normalized.material,
        concrete: normalized.concrete,
        masonry: normalized.masonry
    };
}

function getSlabSectionDefinition(source) {
    const normalized = source?.id ? normalizeSlab(source) : normalizeSlabInsertDraft(source);
    return {
        name: normalized.name,
        h: normalized.h,
        structuralMaterial: normalized.structuralMaterial,
        type: normalized.type,
        temperatureSteel: normalized.temperatureSteel,
        solid: normalized.solid,
        lightened: normalized.lightened,
        metalDeck: normalized.metalDeck
    };
}

function getFoundationSectionDefinition(source) {
    const normalized = source?.id ? normalizeFoundation(source) : normalizeFoundationInsertDraft(source);
    return {
        name: normalized.name,
        b: normalized.b,
        h: normalized.h,
        thickness: normalized.thickness,
        structuralMaterial: normalized.structuralMaterial,
        solid: normalized.solid
    };
}

function getEntitySectionName(type, source) {
    const normalizedType = type === "col" ? "column" : type;
    if (normalizedType === "column") {
        return getColumnSectionName(source);
    }

    return normalizeTextValue(source?.name);
}

function getEntitySectionDefinition(type, source) {
    const normalizedType = type === "col" ? "column" : type;
    switch (normalizedType) {
        case "column":
            return getColumnSectionDefinition(source);
        case "beam":
            return getBeamSectionDefinition(source);
        case "wall":
            return getWallSectionDefinition(source);
        case "foundation":
            return getFoundationSectionDefinition(source);
        case "slab":
        case "hole":
            return getSlabSectionDefinition(source);
        default:
            return { name: normalizeTextValue(source?.name) };
    }
}

function buildNormalizedEntitySection(type, entity, section) {
    const normalizedType = type === "col" ? "column" : type;
    const sectionDefinition = getEntitySectionDefinition(normalizedType, section);

    switch (normalizedType) {
        case "column":
            return normalizeColumnModel({
                ...entity,
                ...sectionDefinition
            });
        case "beam":
            return normalizeBeamModel({
                ...entity,
                ...sectionDefinition
            });
        case "wall":
            return normalizeWall({
                ...entity,
                ...sectionDefinition
            });
        case "foundation":
            return normalizeFoundation({
                ...entity,
                ...sectionDefinition
            });
        case "slab":
        case "hole":
            return normalizeSlab({
                ...entity,
                ...sectionDefinition
            });
        default:
            return {
                ...entity,
                ...sectionDefinition
            };
    }
}

function applyEntitySectionToEntity(type, entity, section) {
    if (!entity) {
        return entity;
    }

    Object.assign(entity, buildNormalizedEntitySection(type, entity, section));
    return entity;
}

function updateEntitySectionsByNames(type, section, names = [], levelId = null) {
    const normalizedType = type === "col" ? "column" : type;
    const normalizedNames = Array.from(new Set(
        (Array.isArray(names) ? names : Array.from(names || []))
            .map((name) => normalizeTextValue(name).toLowerCase())
            .filter(Boolean)
    ));
    const updatedIds = new Set();

    if (!normalizedNames.length) {
        return updatedIds;
    }

    const levels = normalizedType === "column" && levelId != null
        ? projectState.levels.filter((level) => String(level?.id) === String(levelId))
        : projectState.levels;

    levels.forEach((level) => {
        getEntityCollection(level, normalizedType).forEach((entity) => {
            if (!normalizedNames.includes(normalizeTextValue(entity?.name).toLowerCase())) {
                return;
            }

            applyEntitySectionToEntity(normalizedType, entity, section);
            updatedIds.add(entity.id);
        });
    });

    return updatedIds;
}

function getEntitySectionGroupIds(type, name, levelId = null) {
    return new Set(getEntitiesByName(type, name, new Set(), levelId).map((entity) => entity.id));
}

function openEntityNameConflictNotice(type, name) {
    openAppNoticeDialog({
        title: translate("dialog.nameConflictTitle"),
        message: translate("dialog.nameConflictMessage", {
            type: getEntityTypeLabel(type).toLowerCase(),
            name
        })
    });
}

function openSingleNamedEditRenameNotice(type, name) {
    openAppNoticeDialog({
        title: translate("dialog.singleNamedEditTitle"),
        message: translate("dialog.singleNamedEditMessage", {
            type: getEntityTypeLabel(type).toLowerCase(),
            name
        })
    });
}

function shouldRequireRenameForSingleNamedEdit(type, entity, nextSection) {
    const normalizedType = type === "col" ? "column" : type;
    const levelId = normalizedType === "column" ? getEntityLevelId(normalizedType, entity) : null;
    const originalName = getEntitySectionName(normalizedType, entity);
    const requestedName = getEntitySectionName(normalizedType, nextSection) || originalName;

    if (!originalName || normalizeTextValue(requestedName).toLowerCase() !== normalizeTextValue(originalName).toLowerCase()) {
        return false;
    }

    const peers = getEntitiesByName(normalizedType, originalName, new Set([entity?.id]), levelId);
    if (!peers.length) {
        return false;
    }

    const currentKey = getEntitySectionPropertiesKey(normalizedType, entity);
    const nextKey = getEntitySectionPropertiesKey(normalizedType, nextSection);
    return Boolean(currentKey && nextKey && currentKey !== nextKey);
}

function applySingleEntityEdits(type, entity, nextSection) {
    const normalizedType = type === "col" ? "column" : type;
    if (!entity) {
        return false;
    }

    const levelId = normalizedType === "column" ? getEntityLevelId(normalizedType, entity) : null;
    const originalName = getEntitySectionName(normalizedType, entity);
    const requestedName = getEntitySectionName(normalizedType, nextSection);
    const normalizedOriginalName = normalizeTextValue(originalName).toLowerCase();
    const normalizedRequestedName = normalizeTextValue(requestedName).toLowerCase();
    const nameChanged = Boolean(normalizedRequestedName && normalizedRequestedName !== normalizedOriginalName);

    if (requestedName && nameChanged && !canUseEntityDraftName(normalizedType, { ...entity, name: requestedName }, new Set([entity.id]), levelId)) {
        return false;
    }

    const sectionDefinition = getEntitySectionDefinition(normalizedType, nextSection);
    const propertySection = {
        ...sectionDefinition,
        name: originalName || sectionDefinition.name || getNextAvailableEntityName(normalizedType, nextSection, new Set([entity.id]), levelId)
    };

    if (originalName) {
        const matchingEntities = getEntitiesByName(normalizedType, originalName, new Set(), levelId);
        if (matchingEntities.length > 1) {
            matchingEntities.forEach((matchingEntity) => {
                applyEntitySectionToEntity(normalizedType, matchingEntity, {
                    ...propertySection,
                    name: getEntitySectionName(normalizedType, matchingEntity) || originalName
                });
            });

            if (nameChanged) {
                entity.name = requestedName;
            }

            return true;
        }
    }

    const resolvedName = requestedName || getNextAvailableEntityName(normalizedType, nextSection, new Set([entity.id]), levelId);
    if (requestedName && !nameChanged && !canUseEntityDraftName(normalizedType, nextSection, new Set([entity.id]), levelId)) {
        return false;
    }

    const normalizedNextSection = buildNormalizedEntitySection(normalizedType, entity, {
        ...sectionDefinition,
        name: resolvedName
    });
    applyEntitySectionToEntity(normalizedType, entity, normalizedNextSection);
    return true;
}

function canUseEntityDraftName(type, draft, excludedIds = new Set(), levelId = null) {
    const requestedName = getEntitySectionName(type, draft);
    if (!requestedName) {
        return true;
    }

    const matchingEntities = getEntitiesByName(type, requestedName, excludedIds, levelId);
    if (!matchingEntities.length) {
        return true;
    }

    const requestedSectionKey = getEntitySectionPropertiesKey(type, draft);
    const canReuseName = requestedSectionKey
        && matchingEntities.every((entity) => getEntitySectionPropertiesKey(type, entity) === requestedSectionKey);

    if (!canReuseName) {
        openEntityNameConflictNotice(type, requestedName);
        return false;
    }

    return true;
}

function applyEntityEdits(type, entity, nextSection) {
    const normalizedType = type === "col" ? "column" : type;
    const levelId = normalizedType === "column" ? getEntityLevelId(normalizedType, entity) : null;
    const originalName = getEntitySectionName(normalizedType, entity);
    const groupIds = originalName ? getEntitySectionGroupIds(normalizedType, originalName, levelId) : new Set([entity.id]);
    const requestedName = getEntitySectionName(normalizedType, nextSection);

    if (requestedName && hasEntityNameConflict(normalizedType, requestedName, groupIds, levelId)) {
        openEntityNameConflictNotice(normalizedType, requestedName);
        return false;
    }

    const resolvedName = requestedName || getNextAvailableEntityName(normalizedType, nextSection, groupIds, levelId);
    const normalizedNextSection = buildNormalizedEntitySection(normalizedType, entity, {
        ...getEntitySectionDefinition(normalizedType, nextSection),
        name: resolvedName
    });
    const updatedIds = originalName
        ? updateEntitySectionsByNames(normalizedType, normalizedNextSection, [originalName], levelId)
        : new Set();

    if (!updatedIds.has(entity.id)) {
        applyEntitySectionToEntity(normalizedType, entity, normalizedNextSection);
    }

    return true;
}

function createBeam(startNode, endNode, draft = projectState.insertDrafts.beam) {
    const normalizedDraft = normalizeBeamInsertDraft(draft);
    const beamGeometry = {
        x1: startNode.x,
        y1: startNode.y,
        x2: endNode.x,
        y2: endNode.y
    };
    return {
        id: createEntityId("beam"),
        name: resolveEntityName("beam", normalizedDraft.name, {
            ...normalizedDraft,
            ...beamGeometry
        }),
        ...beamGeometry,
        b: normalizedDraft.b,
        h: normalizedDraft.h,
        structuralMaterial: normalizedDraft.structuralMaterial,
        sourceSection: normalizedDraft.sourceSection,
        sourceShape: normalizedDraft.sourceShape,
        steelProfile: normalizedDraft.steelProfile,
        topRebar: normalizedDraft.topRebar,
        botRebar: normalizedDraft.botRebar,
        stirrups: normalizedDraft.stirrups,
        coverTop: normalizedDraft.coverTop,
        coverBottom: normalizedDraft.coverBottom,
        steelDemands: normalizedDraft.steelDemands,
        additionalRebar: normalizedDraft.additionalRebar,
        sectionCuts: getDefaultBeamSectionCuts(beamGeometry)
    };
}

