function getStoredModelSpaceLabelFilters() {
    if (!isBrowser) {
        return createDefaultModelSpaceLabelFilters();
    }

    try {
        return normalizeModelSpaceLabelFilters(JSON.parse(window.localStorage.getItem(MODEL_SPACE_LABEL_FILTERS_STORAGE_KEY) || "{}"));
    } catch (error) {
        return createDefaultModelSpaceLabelFilters();
    }
}

function persistModelSpaceLabelFilters(filters) {
    if (!isBrowser) {
        return;
    }

    try {
        window.localStorage.setItem(
            MODEL_SPACE_LABEL_FILTERS_STORAGE_KEY,
            JSON.stringify(normalizeModelSpaceLabelFilters(filters))
        );
    } catch (error) {
        // Ignore storage failures and keep the current in-memory preference.
    }
}

function persistModelSpaceLabelsVisible(isVisible) {
    if (!isBrowser) {
        return;
    }

    try {
        window.localStorage.setItem(MODEL_SPACE_LABELS_STORAGE_KEY, String(Boolean(isVisible)));
    } catch (error) {
        // Ignore storage failures and keep the current in-memory preference.
    }
}

function getStoredModelSpaceSteelVisible() {
    if (!isBrowser) {
        return true;
    }

    try {
        return window.localStorage.getItem(MODEL_SPACE_STEEL_STORAGE_KEY) !== "false";
    } catch (error) {
        return true;
    }
}

function persistModelSpaceSteelVisible(isVisible) {
    if (!isBrowser) {
        return;
    }

    try {
        window.localStorage.setItem(MODEL_SPACE_STEEL_STORAGE_KEY, String(Boolean(isVisible)));
    } catch (error) {
        // Ignore storage failures and keep the current in-memory preference.
    }
}

function getStoredLanguage() {
    if (!isBrowser) {
        return "en";
    }

    try {
        const storedLanguage = String(window.localStorage.getItem(LANGUAGE_STORAGE_KEY) || "").trim().toLowerCase();
        if (storedLanguage === "es" || storedLanguage === "en") {
            return storedLanguage;
        }
    } catch (error) {
        // Ignore storage failures and fall back to environment detection.
    }

    const languageCandidates = [
        ...(Array.isArray(window.navigator?.languages) ? window.navigator.languages : []),
        window.navigator?.language,
        document.documentElement?.lang
    ];

    return languageCandidates.some((value) => String(value || "").trim().toLowerCase().startsWith("es"))
        ? "es"
        : "en";
}

function persistLanguage(language) {
    if (!isBrowser) {
        return;
    }

    try {
        window.localStorage.setItem(LANGUAGE_STORAGE_KEY, language);
    } catch (error) {
        // Ignore storage failures and keep the current in-memory language.
    }
}

function getStoredOnboardingDismissed() {
    if (!isBrowser) {
        return false;
    }

    try {
        if (window.localStorage.getItem(ONBOARDING_DISMISSED_STORAGE_KEY) === "1") {
            return true;
        }

        if (window.sessionStorage.getItem(ONBOARDING_DISMISSED_STORAGE_KEY) === "1") {
            window.localStorage.setItem(ONBOARDING_DISMISSED_STORAGE_KEY, "1");
            return true;
        }
    } catch (error) {
        return false;
    }

    return false;
}

function persistOnboardingDismissed(isDismissed) {
    if (!isBrowser) {
        return;
    }

    try {
        if (isDismissed) {
            window.localStorage.setItem(ONBOARDING_DISMISSED_STORAGE_KEY, "1");
        } else {
            window.localStorage.removeItem(ONBOARDING_DISMISSED_STORAGE_KEY);
        }
    } catch (error) {
        // Ignore storage failures and keep the current in-memory onboarding preference.
    }
}

function normalizeProjectAutosaveMode(value) {
    return PROJECT_AUTOSAVE_MODES.includes(value) ? value : "off";
}

function normalizeProjectAutosaveActiveMode(value) {
    return PROJECT_AUTOSAVE_ACTIVE_MODES.includes(value) ? value : "change";
}

function getStoredProjectAutosaveMode() {
    if (!isBrowser) {
        return "change";
    }

    try {
        const storedMode = window.localStorage.getItem(PROJECT_AUTOSAVE_MODE_STORAGE_KEY);
        if (!storedMode) {
            return "change";
        }
        return normalizeProjectAutosaveMode(storedMode);
    } catch (error) {
        return "change";
    }
}

function getStoredProjectAutosaveLastMode() {
    if (!isBrowser) {
        return "change";
    }

    try {
        return normalizeProjectAutosaveActiveMode(window.localStorage.getItem(PROJECT_AUTOSAVE_LAST_MODE_STORAGE_KEY));
    } catch (error) {
        return "change";
    }
}

function persistProjectAutosaveMode(mode) {
    if (!isBrowser) {
        return;
    }

    try {
        window.localStorage.setItem(PROJECT_AUTOSAVE_MODE_STORAGE_KEY, normalizeProjectAutosaveMode(mode));
    } catch (error) {
        // Ignore storage failures and keep the current in-memory preference.
    }
}

function persistProjectAutosaveLastMode(mode) {
    if (!isBrowser) {
        return;
    }

    try {
        window.localStorage.setItem(PROJECT_AUTOSAVE_LAST_MODE_STORAGE_KEY, normalizeProjectAutosaveActiveMode(mode));
    } catch (error) {
        // Ignore storage failures and keep the current in-memory preference.
    }
}

function persistPendingProjectSnapshot() {
    if (!isBrowser) {
        return;
    }

    try {
        window.localStorage.setItem(PENDING_PROJECT_SNAPSHOT_STORAGE_KEY, JSON.stringify({
            savedAt: Date.now(),
            project: getProjectSnapshot(),
            currentProjectId: projectState.currentProjectId,
            currentProjectName: projectState.currentProjectName,
            currentProjectAccessMode: projectState.currentProjectAccessMode,
            savedProjectSignature: projectState.savedProjectSignature,
            currentProjectSavedAt: projectState.currentProjectSavedAt
        }));
    } catch (error) {
        // Ignore storage failures so the workspace can continue operating.
    }
}

function restorePendingProjectSnapshot() {
    if (!isBrowser) {
        return;
    }

    let rawValue = "";
    try {
        rawValue = window.localStorage.getItem(PENDING_PROJECT_SNAPSHOT_STORAGE_KEY) || "";
    } catch (error) {
        return;
    }

    if (!rawValue) {
        return;
    }

    try {
        const payload = JSON.parse(rawValue);
        const savedAt = Number.parseInt(payload?.savedAt, 10);
        if (Number.isFinite(savedAt) && (Date.now() - savedAt) <= 1000 * 60 * 60 && payload?.project) {
            applyProjectSnapshot(payload.project);
            projectState.currentProjectId = typeof payload?.currentProjectId === "string" && payload.currentProjectId.trim()
                ? payload.currentProjectId.trim()
                : null;
            projectState.currentProjectName = typeof payload?.currentProjectName === "string" && payload.currentProjectName.trim()
                ? payload.currentProjectName
                : getDefaultProjectName(projectState.language);
            projectState.currentProjectAccessMode = payload?.currentProjectAccessMode === "shared"
                ? "shared"
                : "owner";
            projectState.savedProjectSignature = typeof payload?.savedProjectSignature === "string"
                ? payload.savedProjectSignature
                : "";
            projectState.currentProjectSavedAt = typeof payload?.currentProjectSavedAt === "string" && payload.currentProjectSavedAt.trim()
                ? payload.currentProjectSavedAt
                : null;
            ensureDefaultModelSpaceTheme();
        }
    } catch (error) {
        // Ignore malformed snapshots and continue with a fresh workspace.
    }

    try {
        window.localStorage.removeItem(PENDING_PROJECT_SNAPSHOT_STORAGE_KEY);
    } catch (error) {
        // Ignore cleanup failures.
    }
}

function normalizeProjectNameValue(value, language = projectState.language) {
    const trimmedValue = String(value || "").trim();
    return trimmedValue || getDefaultProjectName(language === "en" ? "en" : "es");
}

function getProjectNameLookupKey(value) {
    return normalizeProjectNameValue(value).toLocaleLowerCase();
}

function hasProjectNameConflict(name = projectState.currentProjectName, currentProjectId = projectState.currentProjectId) {
    const projectNameKey = getProjectNameLookupKey(name);
    return projectState.projectList.some((project) => {
        if (!project || project.id === currentProjectId) {
            return false;
        }

        return getProjectNameLookupKey(project.name) === projectNameKey;
    });
}

function isSharedProjectAccess() {
    return projectState.currentProjectAccessMode === "shared";
}

function hasBlockingProjectNameConflict(name = projectState.currentProjectName, currentProjectId = projectState.currentProjectId) {
    return !isSharedProjectAccess() && hasProjectNameConflict(name, currentProjectId);
}

function getProjectCopySuffix(language = projectState.language) {
    return language === "en" ? " (copy)" : " (copia)";
}

function getUniqueCopiedProjectName(name = projectState.currentProjectName, existingProjects = projectState.projectList, language = projectState.language) {
    const baseName = normalizeProjectNameValue(name, language);
    const suffix = getProjectCopySuffix(language);
    const normalizedExistingProjects = Array.isArray(existingProjects) ? existingProjects : [];

    const hasNameConflict = (candidate) => normalizedExistingProjects.some((project) => {
        if (!project) {
            return false;
        }

        return getProjectNameLookupKey(project.name) === getProjectNameLookupKey(candidate);
    });

    let candidateName = `${baseName}${suffix}`;
    if (!hasNameConflict(candidateName)) {
        return candidateName;
    }

    let copyIndex = 2;
    while (copyIndex < 1000) {
        candidateName = `${baseName}${suffix} ${copyIndex}`;
        if (!hasNameConflict(candidateName)) {
            return candidateName;
        }
        copyIndex += 1;
    }

    return `${baseName}${suffix} ${Date.now()}`;
}

function isDefaultProjectName(value) {
    const normalizedValue = normalizeProjectNameValue(value, projectState.language).toLowerCase();
    return normalizedValue === getDefaultProjectName("es").toLowerCase()
        || normalizedValue === getDefaultProjectName("en").toLowerCase();
}

function getReferenceAxisSnapshot(source = projectState) {
    const normalizedReferenceAxes = {
        x: normalizeAxisValues(source?.referenceAxes?.x, []),
        y: normalizeAxisValues(source?.referenceAxes?.y, [])
    };
    const normalizedReferenceAxisLabels = {
        x: normalizeAxisLabelMap(source?.referenceAxisLabels?.x, normalizedReferenceAxes.x),
        y: normalizeAxisLabelMap(source?.referenceAxisLabels?.y, normalizedReferenceAxes.y)
    };

    if (
        normalizedReferenceAxes.x.length === 0
        && normalizedReferenceAxes.y.length === 0
        && Object.keys(normalizedReferenceAxisLabels.x).length === 0
        && Object.keys(normalizedReferenceAxisLabels.y).length === 0
    ) {
        return null;
    }

    return {
        referenceAxes: normalizedReferenceAxes,
        referenceAxisLabels: normalizedReferenceAxisLabels
    };
}

function getProjectDirtySnapshot(snapshot = null) {
    const source = snapshot && typeof snapshot === "object" ? snapshot : projectState;
    const referenceAxisSnapshot = getReferenceAxisSnapshot(source);
    return cloneSerializable({
        axes: source.axes,
        axisLabels: source.axisLabels,
        gridAxisLocationMode: normalizeGridAxisLocationMode(source.gridAxisLocationMode),
        materialPrices: normalizeMaterialPrices(source.materialPrices),
        levels: source.levels,
        etabsUploads: normalizeEtabsUploadCollection(source.etabsUploads),
        ...(referenceAxisSnapshot || {})
    });
}

function getProjectPersistenceSignature(name = projectState.currentProjectName, snapshot = null) {
    return JSON.stringify({
        name: normalizeProjectNameValue(name),
        project: getProjectDirtySnapshot(snapshot)
    });
}

function isCurrentProjectDirty() {
    if (!projectState.currentProjectId || !projectState.savedProjectSignature) {
        return true;
    }

    return getProjectPersistenceSignature() !== projectState.savedProjectSignature;
}

function shouldConfirmProjectSwitch() {
    if (projectState.currentProjectId) {
        return isCurrentProjectDirty();
    }

    return shouldConfirmEtabsGridImport() || !isDefaultProjectName(projectState.currentProjectName);
}

function formatProjectDateLabel(value) {
    const date = new Date(value);
    if (!Number.isFinite(date.getTime())) {
        return "";
    }

    try {
        return new Intl.DateTimeFormat(projectState.language === "en" ? "en-US" : "es-BO", {
            dateStyle: "medium",
            timeStyle: "short"
        }).format(date);
    } catch (error) {
        return date.toLocaleString();
    }
}

function formatProjectSavedAtLabel(value) {
    const date = new Date(value);
    if (!Number.isFinite(date.getTime())) {
        return "";
    }

    const locale = projectState.language === "en" ? "en-US" : "es-BO";
    const now = new Date();
    const isSameDay = now.getFullYear() === date.getFullYear()
        && now.getMonth() === date.getMonth()
        && now.getDate() === date.getDate();

    try {
        const timeLabel = new Intl.DateTimeFormat(locale, {
            timeStyle: "short"
        }).format(date);

        if (isSameDay) {
            return timeLabel;
        }

        const dateLabel = new Intl.DateTimeFormat(locale, {
            dateStyle: "medium"
        }).format(date);
        return `${timeLabel} (${dateLabel})`;
    } catch (error) {
        return date.toLocaleString();
    }
}

function getProjectAutosaveDelayMs(mode = projectState.projectAutosaveMode) {
    switch (normalizeProjectAutosaveMode(mode)) {
        case "change":
            return PROJECT_AUTOSAVE_CHANGE_DELAY_MS;
        case "5m":
            return 5 * 60 * 1000;
        case "10m":
            return 10 * 60 * 1000;
        case "15m":
            return 15 * 60 * 1000;
        default:
            return 0;
    }
}

function clearProjectAutosaveTimer() {
    if (!isBrowser || !projectAutosaveState.timerId) {
        projectAutosaveState.timerId = 0;
        projectAutosaveState.pendingSignature = "";
        projectAutosaveState.pendingMode = "off";
        projectAutosaveState.pendingDelayMs = 0;
        return;
    }

    window.clearTimeout(projectAutosaveState.timerId);
    projectAutosaveState.timerId = 0;
    projectAutosaveState.pendingSignature = "";
    projectAutosaveState.pendingMode = "off";
    projectAutosaveState.pendingDelayMs = 0;
}

function scheduleProjectAutosave(delayMs, signature = getProjectPersistenceSignature(), mode = projectState.projectAutosaveMode) {
    if (!isBrowser || !Number.isFinite(delayMs) || delayMs <= 0) {
        clearProjectAutosaveTimer();
        return;
    }

    clearProjectAutosaveTimer();
    projectAutosaveState.pendingSignature = signature;
    projectAutosaveState.pendingMode = normalizeProjectAutosaveMode(mode);
    projectAutosaveState.pendingDelayMs = delayMs;
    projectAutosaveState.timerId = window.setTimeout(() => {
        const expectedSignature = projectAutosaveState.pendingSignature;
        clearProjectAutosaveTimer();

        if (!projectState.authenticatedUser?.id || projectState.projectSaving || hasBlockingProjectNameConflict() || !isCurrentProjectDirty()) {
            return;
        }

        if (getProjectPersistenceSignature() !== expectedSignature) {
            syncProjectAutosave();
            return;
        }

        void saveCurrentProject({ automatic: true });
    }, delayMs);
}

function getProjectAutosaveNote() {
    const mode = normalizeProjectAutosaveMode(projectState.projectAutosaveMode);
    if (mode === "off") {
        return translate("project.autosave.note.off");
    }

    if (!projectState.authenticatedUser?.id) {
        return translate("project.autosave.note.login");
    }

    if (isSharedProjectAccess()) {
        return translate("project.autosave.note.shared");
    }

    if (hasProjectNameConflict()) {
        return translate("project.autosave.note.conflict");
    }

    if (mode === "change") {
        return translate("project.autosave.note.change");
    }

    return translate("project.autosave.note.interval", {
        interval: translate(`project.autosave.${mode}`).toLowerCase()
    });
}

function syncProjectAutosave({ forceDelayMs = null } = {}) {
    const mode = normalizeProjectAutosaveMode(projectState.projectAutosaveMode);
    if (mode === "off" || !projectState.authenticatedUser?.id || hasBlockingProjectNameConflict() || !isCurrentProjectDirty()) {
        clearProjectAutosaveTimer();
        return;
    }

    if (projectState.projectSaving) {
        return;
    }

    const delayMs = forceDelayMs ?? getProjectAutosaveDelayMs(mode);
    const signature = getProjectPersistenceSignature();

    if (
        projectAutosaveState.timerId
        && projectAutosaveState.pendingSignature === signature
        && projectAutosaveState.pendingMode === mode
        && projectAutosaveState.pendingDelayMs === delayMs
    ) {
        return;
    }

    scheduleProjectAutosave(delayMs, signature, mode);
}

function isProjectPickerOpen() {
    return dom.projectPickerOverlay?.style.display === "flex";
}

function isExportModalOpen() {
    return dom.exportModalOverlay?.style.display === "flex";
}

function isQuantitiesExportModalOpen() {
    return dom.quantitiesExportModalOverlay?.style.display === "flex";
}

function renderProjectControls() {
    if (!dom.projectSection || !dom.projectNameInput || !dom.projectStatus) {
        return;
    }

    if (dom.projectSectionKicker) {
        dom.projectSectionKicker.textContent = translate("project.current");
    }
    if (dom.projectInfoMenuTitle) {
        dom.projectInfoMenuTitle.textContent = translate("project.infoTitle");
    }
    if (dom.projectNameLabel) {
        dom.projectNameLabel.textContent = translate("project.nameLabel");
    }
    if (dom.projectLocationLabel) {
        dom.projectLocationLabel.textContent = translate("project.locationLabel");
    }
    if (dom.projectDateLabel) {
        dom.projectDateLabel.textContent = translate("project.designDateLabel");
    }
    if (dom.projectPreferencesTitle) {
        dom.projectPreferencesTitle.textContent = translate("project.preferencesTitle");
    }
    if (dom.projectLanguageLabel) {
        dom.projectLanguageLabel.textContent = translate("project.languageLabel");
    }
    if (dom.projectUnitsLabel) {
        dom.projectUnitsLabel.textContent = translate("project.unitsLabel");
    }
    if (dom.projectShortcutsLabel) {
        dom.projectShortcutsLabel.textContent = translate("project.shortcutsLabel");
    }
    document.querySelectorAll(".project-pref-group.is-disabled .field-note").forEach((element) => {
        element.textContent = translate("project.unavailable");
    });

    if (dom.projectNameInput.value !== projectState.currentProjectName) {
        dom.projectNameInput.value = projectState.currentProjectName;
    }
    dom.projectNameInput.placeholder = getDefaultProjectName(projectState.language);
    dom.projectNameInput.setAttribute("aria-label", translate("project.nameAria"));
    dom.projectLocationInput?.setAttribute("aria-label", translate("project.locationLabel"));
    dom.projectLocationInput?.setAttribute("placeholder", translate("project.locationPlaceholder"));
    dom.projectDesignDateInput?.setAttribute("aria-label", translate("project.designDateLabel"));
    const projectIsShared = isSharedProjectAccess();
    const projectHasNameConflict = hasBlockingProjectNameConflict();
    const projectIsDirty = isCurrentProjectDirty();
    dom.projectNameInput.setAttribute("aria-invalid", projectHasNameConflict ? "true" : "false");

    let projectStatusKey = "project.status.saved";
    let projectStatusState = "saved";
    let projectStatusParams = {};

    if (projectState.projectSaving) {
        projectStatusKey = "project.status.saving";
        projectStatusState = "saving";
    } else if (projectHasNameConflict) {
        projectStatusKey = "project.status.duplicate";
        projectStatusState = "conflict";
    } else if (projectIsDirty) {
        projectStatusKey = "project.status.unsaved";
        projectStatusState = "unsaved";
    } else if (projectIsShared) {
        projectStatusKey = "project.status.shared";
        projectStatusState = "shared";
    } else if (projectState.currentProjectSavedAt) {
        projectStatusKey = "project.status.savedAt";
        projectStatusParams = {
            time: formatProjectSavedAtLabel(projectState.currentProjectSavedAt)
        };
    }

    dom.projectStatus.textContent = translate(projectStatusKey, projectStatusParams);
    dom.projectStatus.dataset.status = projectStatusState;
    dom.projectStatus.classList.toggle("is-detailed", projectStatusKey === "project.status.savedAt");

    setButtonCopy(dom.projectSaveButton, translate("project.save"));
    if (dom.projectSaveButton) {
        dom.projectSaveButton.disabled = projectState.projectSaving || projectHasNameConflict;
        dom.projectSaveButton.title = projectHasNameConflict
            ? translate("project.nameExists")
            : "";
    }

    if (dom.projectAutosaveTitle) {
        dom.projectAutosaveTitle.textContent = translate("project.autosave");
    }
    if (dom.projectAutosaveLabel) {
        dom.projectAutosaveLabel.textContent = translate("project.autosaveToggle");
    }

    if (dom.projectAutosaveToggle) {
        dom.projectAutosaveToggle.checked = projectState.projectAutosaveMode !== "off";
        dom.projectAutosaveToggle.setAttribute("aria-label", translate("project.autosaveToggleAria"));
    }

    if (dom.projectAutosaveSelect) {
        const activeAutosaveMode = normalizeProjectAutosaveActiveMode(
            projectState.projectAutosaveMode === "off" ? projectState.projectAutosaveLastMode : projectState.projectAutosaveMode
        );
        dom.projectAutosaveSelect.hidden = projectState.projectAutosaveMode === "off";
        dom.projectAutosaveSelect.disabled = projectState.projectAutosaveMode === "off";
        dom.projectAutosaveSelect.value = activeAutosaveMode;
        dom.projectAutosaveSelect.setAttribute("aria-label", translate("project.autosaveAria"));
        Array.from(dom.projectAutosaveSelect.options).forEach((option) => {
            option.textContent = translate(`project.autosave.${normalizeProjectAutosaveActiveMode(option.value)}`);
        });
    }

    if (dom.projectAutosaveNote) {
        dom.projectAutosaveNote.textContent = getProjectAutosaveNote();
    }

    if (dom.projectSharedNote) {
        const sharedNoteMessage = projectIsShared
            ? translate("project.sharedNote")
            : "";
        dom.projectSharedNote.textContent = sharedNoteMessage;
        dom.projectSharedNote.hidden = !sharedNoteMessage;
    }
}

function buildProjectPickerRow(project, { shared = false } = {}) {
    if (!project) {
        return null;
    }

    const row = document.createElement("div");
    row.className = "project-picker-item";
    if (project.id === projectState.currentProjectId) {
        row.classList.add("is-current");
    }
    if (project.id === projectState.projectDeletingId) {
        row.classList.add("is-busy");
    }
    if (shared) {
        row.classList.add("is-shared");
    }

    const copy = document.createElement("div");
    copy.className = "project-picker-copy";

    const header = document.createElement("div");
    header.className = "project-picker-header";

    const name = document.createElement("div");
    name.className = "project-picker-name";
    name.textContent = normalizeProjectNameValue(project.name);

    const badgeWrap = document.createElement("div");
    badgeWrap.className = "project-picker-badges";

    if (project.id === projectState.currentProjectId) {
        const badge = document.createElement("div");
        badge.className = "project-picker-badge";
        badge.textContent = translate("project.currentBadge");
        badgeWrap.appendChild(badge);
    }

    if (shared || project.accessMode === "shared") {
        const badge = document.createElement("div");
        badge.className = "project-picker-badge";
        badge.textContent = translate("project.sharedBadge");
        badgeWrap.appendChild(badge);
    }

    const meta = document.createElement("div");
    meta.className = "project-picker-meta";
    meta.textContent = shared || project.accessMode === "shared"
        ? project.sharedAt
            ? translate("project.sharedAt", { date: formatProjectDateLabel(project.sharedAt) })
            : ""
        : project.updatedAt
            ? translate("project.updatedAt", { date: formatProjectDateLabel(project.updatedAt) })
            : "";

    appendChildrenCompat(header, name, badgeWrap);
    appendChildrenCompat(copy, header, meta);

    const actions = document.createElement("div");
    actions.className = "project-picker-actions";

    const openButton = document.createElement("button");
    openButton.type = "button";
    openButton.className = "project-action-button";
    openButton.textContent = translate("project.open");
    openButton.disabled = project.id === projectState.projectDeletingId;
    openButton.addEventListener("click", () => {
        void openSavedProject(project.id);
    });

    appendChildrenCompat(actions, openButton);

    if (!shared && project.accessMode !== "shared") {
        const shareButton = document.createElement("button");
        shareButton.type = "button";
        shareButton.className = "project-action-button project-action-button-icon";
        shareButton.setAttribute("aria-label", translate("project.shareDialogTitle"));
        shareButton.title = translate("project.shareDialogTitle");
        shareButton.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false" style="display: block;"><circle cx="18" cy="5" r="3"></circle><circle cx="6" cy="12" r="3"></circle><circle cx="18" cy="19" r="3"></circle><path d="M8.59 13.51 15.42 17.49"></path><path d="M15.41 6.51 8.59 10.49"></path></svg>';
        shareButton.disabled = Boolean(projectState.projectDeletingId);
        shareButton.addEventListener("click", () => {
            openProjectShareModal(project);
        });

        const deleteButton = document.createElement("button");
        deleteButton.type = "button";
        deleteButton.className = "project-action-button project-action-button-danger";
        deleteButton.setAttribute("aria-label", translate("project.delete"));
        deleteButton.title = translate("project.delete");
        deleteButton.innerHTML = project.id === projectState.projectDeletingId
            ? translate("project.deleting")
            : `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="display: block;"><path d="M3 6h18m-2 0v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>`;
        deleteButton.disabled = Boolean(projectState.projectDeletingId);
        deleteButton.addEventListener("click", () => {
            void deleteSavedProject(project);
        });

        appendChildrenCompat(actions, shareButton, deleteButton);
    }

    appendChildrenCompat(row, copy, actions);
    return row;
}

function renderProjectPickerList(container, projects, {
    shared = false,
    emptyMessage = "",
    loadingMessage = ""
} = {}) {
    if (!container) {
        return;
    }

    replaceChildrenCompat(container);

    const hasAuthenticatedUser = Boolean(projectState.authenticatedUser?.id);
    container.hidden = !hasAuthenticatedUser;

    if (!hasAuthenticatedUser) {
        return;
    }

    const listItems = Array.isArray(projects) ? projects.filter(Boolean) : [];
    if (projectState.projectListLoading && listItems.length === 0) {
        const loadingState = document.createElement("div");
        loadingState.className = "project-picker-empty";
        loadingState.textContent = loadingMessage || translate("project.loading");
        container.appendChild(loadingState);
        return;
    }

    if (projectState.projectListMessage && listItems.length === 0) {
        const errorState = document.createElement("div");
        errorState.className = "project-picker-empty";
        errorState.textContent = projectState.projectListMessage;
        container.appendChild(errorState);
        return;
    }

    if (listItems.length === 0) {
        const emptyState = document.createElement("div");
        emptyState.className = "project-picker-empty";
        emptyState.textContent = emptyMessage;
        container.appendChild(emptyState);
        return;
    }

    listItems.forEach((project) => {
        const row = buildProjectPickerRow(project, { shared });
        if (row) {
            container.appendChild(row);
        }
    });
}

function renderProjectPicker() {
    const hasAuthenticatedUser = Boolean(projectState.authenticatedUser?.id);
    const isAuthLoading = projectState.billingLoading || !projectState.billingStatusLoaded;
    const hasSharedProjects = Array.isArray(projectState.sharedProjectList) && projectState.sharedProjectList.length > 0;

    if (dom.projectPickerKicker) {
        dom.projectPickerKicker.textContent = translate("project.library");
    }
    if (dom.projectPickerTitle) {
        dom.projectPickerTitle.textContent = translate("project.libraryTitle");
    }
    if (dom.projectSharedTitle) {
        dom.projectSharedTitle.textContent = translate("project.sharedTitle");
    }

    if (dom.projectPickerNote) {
        const noteMessage = hasAuthenticatedUser
            ? ""
            : isAuthLoading
                ? translate("project.loading")
                : translate("project.libraryCopy");
        dom.projectPickerNote.textContent = noteMessage;
        dom.projectPickerNote.hidden = !noteMessage;
    }

    if (dom.projectSharedNote) {
        const sharedNoteMessage = !hasAuthenticatedUser
            ? isAuthLoading
                ? translate("project.loading")
                : translate("project.sharedLoginCopy")
            : projectState.projectListLoading && !hasSharedProjects
                ? translate("project.loading")
                : hasSharedProjects
                    ? ""
                    : translate("project.sharedCopy");
        dom.projectSharedNote.textContent = sharedNoteMessage;
        dom.projectSharedNote.hidden = !sharedNoteMessage;
    }

    setButtonCopy(dom.projectCreateNewButton, translate("project.new"));
    setButtonCopy(dom.projectPickerLoginButton, translate("project.login"));
    if (dom.projectPickerLoginButton) {
        dom.projectPickerLoginButton.hidden = hasAuthenticatedUser;
    }
    if (dom.projectPickerToolbar) {
        dom.projectPickerToolbar.hidden = hasAuthenticatedUser;
    }

    renderProjectPickerList(dom.projectPickerList, projectState.projectList, {
        emptyMessage: translate("project.empty"),
        loadingMessage: translate("project.loading")
    });

    renderProjectPickerList(dom.projectSharedList, projectState.sharedProjectList, {
        shared: true,
        emptyMessage: translate("project.sharedEmpty"),
        loadingMessage: translate("project.loading")
    });
}

async function syncProjectLibraryAfterAuthChange(previousUserId, nextUserId) {
    if (previousUserId === nextUserId) {
        return;
    }

    if (!nextUserId) {
        projectState.projectList = [];
        projectState.sharedProjectList = [];
        projectState.projectListLoaded = false;
        projectState.projectListLoading = false;
        projectState.projectListMessage = "";
        projectState.projectDeletingId = "";
        projectState.currentProjectAccessMode = "owner";
        renderProjectControls();
        renderProjectPicker();
        syncProjectAutosave();
        return;
    }

    await refreshProjectList({ silent: true });
    syncProjectAutosave();
}

async function refreshProjectList({ silent = false } = {}) {
    if (!projectState.authenticatedUser?.id) {
        projectState.projectList = [];
        projectState.sharedProjectList = [];
        projectState.projectListLoaded = false;
        projectState.projectListLoading = false;
        projectState.projectListMessage = "";
        projectState.currentProjectAccessMode = "owner";
        renderProjectControls();
        renderProjectPicker();
        return [];
    }

    projectState.projectListLoading = true;
    if (!silent) {
        projectState.projectListMessage = "";
    }
    renderProjectPicker();

    try {
        const response = await fetch("/api/projects", {
            method: "GET",
            credentials: "same-origin",
            headers: {
                Accept: "application/json"
            }
        });
        const payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            throw new Error(typeof payload?.error === "string" && payload.error.trim()
                ? payload.error
                : translate("errors.projectsLoadFailed"));
        }

        projectState.projectList = Array.isArray(payload?.projects) ? payload.projects : [];
        projectState.sharedProjectList = Array.isArray(payload?.sharedProjects) ? payload.sharedProjects : [];
        projectState.projectListLoaded = true;
        projectState.projectListMessage = "";
        return projectState.projectList;
    } catch (error) {
        projectState.projectListMessage = error?.message || translate("errors.projectsLoadFailed");
        return [];
    } finally {
        projectState.projectListLoading = false;
        renderProjectControls();
        renderProjectPicker();
    }
}

function openProjectPicker() {
    setSidebarMode("manage");
    renderProjectPicker();
    void refreshProjectList({ silent: true });
}

function closeProjectPicker() {
    if (dom.projectPickerOverlay) {
        dom.projectPickerOverlay.style.display = "none";
    }
}

function isProjectShareOverlayOpen() {
    return Boolean(dom.projectShareOverlay && !dom.projectShareOverlay.hidden);
}

function setProjectShareStatus(message = "", tone = "") {
    if (!dom.projectShareStatus) {
        return;
    }

    dom.projectShareStatus.textContent = message || "";
    dom.projectShareStatus.hidden = !message;
    if (tone) {
        dom.projectShareStatus.dataset.tone = tone;
    } else {
        delete dom.projectShareStatus.dataset.tone;
    }
}

function renderProjectShareModal() {
    const projectName = projectState.projectShareProjectName || "";
    const isBusy = Boolean(projectState.projectShareSubmitting);

    if (dom.projectShareTitle) {
        dom.projectShareTitle.textContent = translate("project.shareDialogTitle");
    }
    if (dom.projectShareCopy) {
        dom.projectShareCopy.textContent = translate("project.shareDialogCopy");
    }
    if (dom.projectShareProjectName) {
        dom.projectShareProjectName.textContent = projectName;
    }
    if (dom.projectShareEmailLabel) {
        dom.projectShareEmailLabel.textContent = translate("project.shareEmailLabel");
    }
    if (dom.projectShareEmailHelp) {
        dom.projectShareEmailHelp.textContent = translate("project.shareEmailHelp");
    }
    if (dom.projectShareEmailInput) {
        dom.projectShareEmailInput.placeholder = translate("project.shareEmailPlaceholder");
        dom.projectShareEmailInput.setAttribute("aria-label", translate("project.shareEmailLabel"));
        dom.projectShareEmailInput.disabled = isBusy;
    }
    if (dom.projectShareCancelButton) {
        dom.projectShareCancelButton.textContent = translate("dialog.cancel");
        dom.projectShareCancelButton.disabled = isBusy;
    }
    if (dom.projectShareSubmitButton) {
        dom.projectShareSubmitButton.textContent = isBusy
            ? translate("project.shareSaving")
            : translate("project.share");
        dom.projectShareSubmitButton.disabled = isBusy;
    }
    if (dom.projectShareTitle) {
        dom.projectShareTitle.setAttribute("aria-label", projectName ? `${translate("project.shareDialogTitle")} ${projectName}` : translate("project.shareDialogTitle"));
    }
    if (dom.projectShareForm) {
        dom.projectShareForm.setAttribute("aria-busy", isBusy ? "true" : "false");
    }
}

function closeProjectShareModal({ resetStatus = true } = {}) {
    if (!dom.projectShareOverlay) {
        return;
    }

    if (projectState.projectShareSubmitting) {
        return;
    }

    dom.projectShareOverlay.hidden = true;
    projectState.projectShareSubmitting = false;
    projectState.projectShareProjectId = "";
    projectState.projectShareProjectName = "";
    if (dom.projectShareEmailInput) {
        dom.projectShareEmailInput.value = "";
    }
    if (resetStatus) {
        setProjectShareStatus("", "");
    }
    renderProjectShareModal();
}

function openProjectShareModal(projectRecord) {
    if (!dom.projectShareOverlay || !projectRecord?.id) {
        return;
    }

    projectState.projectShareProjectId = String(projectRecord.id || "").trim();
    projectState.projectShareProjectName = normalizeProjectNameValue(projectRecord.name);
    projectState.projectShareSubmitting = false;
    setProjectShareStatus("", "");
    dom.projectShareOverlay.hidden = false;
    renderProjectShareModal();

    if (isBrowser) {
        window.requestAnimationFrame(() => {
            dom.projectShareEmailInput?.focus();
        });
    }
}

async function submitProjectShareForm(event) {
    event.preventDefault();

    if (projectState.projectShareSubmitting) {
        return;
    }

    if (!projectState.authenticatedUser?.id) {
        setProjectShareStatus(translate("project.loginRequired"), "error");
        return;
    }

    const projectId = String(projectState.projectShareProjectId || "").trim();
    if (!projectId) {
        setProjectShareStatus(translate("errors.projectShareFailed"), "error");
        return;
    }

    const emailInput = dom.projectShareEmailInput;
    const rawEmail = String(emailInput?.value || "").trim().toLowerCase();
    if (!emailInput || !rawEmail || !emailInput.checkValidity()) {
        setProjectShareStatus(translate("project.shareInvalidEmail"), "error");
        emailInput?.reportValidity?.();
        emailInput?.focus();
        return;
    }

    projectState.projectShareSubmitting = true;
    renderProjectShareModal();
    setProjectShareStatus(translate("project.shareSaving"), "info");

    try {
        const response = await fetch(`/api/projects/${encodeURIComponent(projectId)}/share`, {
            method: "POST",
            credentials: "same-origin",
            headers: {
                Accept: "application/json",
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                email: rawEmail
            })
        });
        const payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            if (payload?.code === "authentication_required") {
                closeProjectShareModal();
                beginLoginForBilling();
                return;
            }

            if (payload?.code === "project_share_invalid_email") {
                setProjectShareStatus(translate("project.shareInvalidEmail"), "error");
                emailInput?.focus();
                return;
            }

            if (payload?.code === "project_share_self") {
                setProjectShareStatus(translate("project.shareSelf"), "error");
                return;
            }

            throw new Error(typeof payload?.error === "string" && payload.error.trim()
                ? payload.error
                : translate("errors.projectShareFailed"));
        }

        closeProjectShareModal();

        const shareMessage = payload?.emailState === "send_failed" || payload?.emailConfigured === false
            ? `${translate("project.shareSuccessMessage", { email: rawEmail })}\n\n${translate("project.shareSuccessEmailFailed")}`
            : translate("project.shareSuccessMessage", { email: rawEmail });

        openAppNoticeDialog({
            title: translate("dialog.projectShareSuccessTitle"),
            message: shareMessage
        });
    } catch (error) {
        setProjectShareStatus(error?.message || translate("errors.projectShareFailed"), "error");
    } finally {
        projectState.projectShareSubmitting = false;
        renderProjectShareModal();
    }
}

async function confirmProjectSwitch() {
    if (!shouldConfirmProjectSwitch()) {
        return true;
    }

    return requestAppConfirmation({
        title: translate("project.discardChangesTitle"),
        message: translate("project.discardChangesMessage"),
        confirmLabel: translate("project.discardChangesAction")
    });
}

function applyLoadedProject(projectRecord) {
    clearProjectAutosaveTimer();
    clearPendingSlabInsertion();
    applyProjectSnapshot(projectRecord.snapshot);
    projectState.currentProjectId = projectRecord.id || null;
    projectState.currentProjectAccessMode = projectRecord.accessMode === "shared" ? "shared" : "owner";
    projectState.currentProjectName = normalizeProjectNameValue(projectRecord.name);
    projectState.savedProjectSignature = getProjectPersistenceSignature(projectRecord.name, projectRecord.snapshot);
    projectState.currentProjectSavedAt = typeof projectRecord.updatedAt === "string" && projectRecord.updatedAt.trim()
        ? projectRecord.updatedAt
        : null;
    ensureDefaultModelSpaceTheme();
    resetProjectHistoryState({ clearStacks: true });
    updateUI();
    render();
    persistPendingProjectSnapshot();
    renderProjectPicker();
}

async function openSavedProject(projectId) {
    if (!projectState.authenticatedUser?.id) {
        return;
    }

    const shouldContinue = await confirmProjectSwitch();
    if (!shouldContinue) {
        return;
    }

    try {
        const response = await fetch(`/api/projects/${encodeURIComponent(projectId)}`, {
            method: "GET",
            credentials: "same-origin",
            headers: {
                Accept: "application/json"
            }
        });
        const payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            throw new Error(typeof payload?.error === "string" && payload.error.trim()
                ? payload.error
                : translate("errors.projectOpenFailed"));
        }

        if (!payload?.project?.id) {
            throw new Error(translate("errors.projectOpenFailed"));
        }

        applyLoadedProject(payload.project);
        closeProjectPicker();
    } catch (error) {
        openAppNoticeDialog({
            title: translate("dialog.projectOpenErrorTitle"),
            message: error?.message || translate("errors.projectOpenFailed")
        });
    }
}

async function deleteSavedProject(projectRecord) {
    const projectId = String(projectRecord?.id || "").trim();
    if (!projectState.authenticatedUser?.id || !projectId || projectState.projectDeletingId) {
        return;
    }

    const projectName = normalizeProjectNameValue(projectRecord?.name);
    const deletingCurrentProject = projectId === projectState.currentProjectId;
    closeProjectPicker();
    const confirmed = await requestAppConfirmation({
        title: translate("project.deleteConfirmTitle"),
        message: translate(
            deletingCurrentProject ? "project.deleteCurrentMessage" : "project.deleteConfirmMessage",
            { name: projectName }
        ),
        confirmLabel: translate("project.deleteConfirmAction")
    });

    if (!confirmed) {
        return;
    }

    projectState.projectDeletingId = projectId;
    renderProjectPicker();

    try {
        const response = await fetch(`/api/projects/${encodeURIComponent(projectId)}`, {
            method: "DELETE",
            credentials: "same-origin",
            headers: {
                Accept: "application/json"
            }
        });
        const payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            throw new Error(typeof payload?.error === "string" && payload.error.trim()
                ? payload.error
                : translate("errors.projectDeleteFailed"));
        }

        projectState.projectList = projectState.projectList.filter((item) => item?.id !== projectId);
        projectState.projectListLoaded = true;
        projectState.projectListMessage = "";

        if (deletingCurrentProject) {
            clearProjectAutosaveTimer();
            projectState.currentProjectId = null;
            projectState.currentProjectAccessMode = "owner";
            projectState.savedProjectSignature = "";
            projectState.currentProjectSavedAt = null;
            persistPendingProjectSnapshot();
            renderProjectControls();
        }

        renderProjectPicker();
    } catch (error) {
        openAppNoticeDialog({
            title: translate("dialog.projectDeleteErrorTitle"),
            message: error?.message || translate("errors.projectDeleteFailed")
        });
    } finally {
        projectState.projectDeletingId = "";
        renderProjectControls();
        renderProjectPicker();
    }
}

async function createNewProject() {
    const shouldContinue = await confirmProjectSwitch();
    if (!shouldContinue) {
        return;
    }

    clearProjectAutosaveTimer();
    clearPendingSlabInsertion();
    applyProjectSnapshot({});
    projectState.currentProjectId = null;
    projectState.currentProjectAccessMode = "owner";
    projectState.currentProjectName = getDefaultProjectName(projectState.language);
    projectState.savedProjectSignature = "";
    projectState.currentProjectSavedAt = null;
    ensureDefaultModelSpaceTheme();
    resetProjectHistoryState({ clearStacks: true });
    updateUI();
    render();
    persistPendingProjectSnapshot();
    renderProjectPicker();
}

async function saveCurrentProject(options = {}) {
    const automatic = Boolean(options?.automatic);
    if (projectState.projectSaving) {
        return false;
    }

    projectState.currentProjectName = normalizeProjectNameValue(projectState.currentProjectName);
    renderProjectControls();

    if (!projectState.authenticatedUser?.id) {
        if (automatic) {
            clearProjectAutosaveTimer();
            return false;
        }

        const shouldLogin = await requestAppConfirmation({
            title: translate("project.save"),
            message: translate("project.loginToSave"),
            confirmLabel: translate("project.login")
        });

        if (shouldLogin) {
            beginLoginForBilling();
        }
        return false;
    }

    if (!projectState.projectListLoaded) {
        await refreshProjectList({ silent: true });
    }

    const isSharedProject = isSharedProjectAccess();
    const projectNameToSave = isSharedProject
        ? getUniqueCopiedProjectName(projectState.currentProjectName, projectState.projectList, projectState.language)
        : projectState.currentProjectName;

    if (!isSharedProject && hasProjectNameConflict()) {
        renderProjectControls();
        clearProjectAutosaveTimer();
        if (!automatic) {
            openAppNoticeDialog({
                title: translate("dialog.projectSaveErrorTitle"),
                message: translate("project.nameExists")
            });
        }
        return false;
    }

    clearProjectAutosaveTimer();
    projectState.projectSaving = true;
    renderProjectControls();
    let shouldRetryAutosave = false;
    const projectSnapshot = getProjectSnapshot();

    try {
        const requestBody = await createJsonRequestInitBody({
            name: projectNameToSave,
            project: projectSnapshot
        });
        const response = await fetch(
            isSharedProject
                ? "/api/projects"
                : projectState.currentProjectId
                ? `/api/projects/${encodeURIComponent(projectState.currentProjectId)}`
                : "/api/projects",
            {
                method: isSharedProject
                    ? "POST"
                    : projectState.currentProjectId
                        ? "PATCH"
                        : "POST",
                credentials: "same-origin",
                headers: {
                    Accept: "application/json",
                    ...requestBody.headers
                },
                body: requestBody.body
            }
        );
        const payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            if (payload?.code === "authentication_required") {
                if (automatic) {
                    return false;
                }

                const shouldLogin = await requestAppConfirmation({
                    title: translate("project.save"),
                    message: translate("project.loginToSave"),
                    confirmLabel: translate("project.login")
                });
                if (shouldLogin) {
                    beginLoginForBilling();
                }
                return false;
            }

            if (payload?.code === "project_name_exists") {
                await refreshProjectList({ silent: true });
                if (automatic) {
                    return false;
                }
            }

            if (automatic) {
                shouldRetryAutosave = true;
                return false;
            }

            throw new Error(typeof payload?.error === "string" && payload.error.trim()
                ? payload.error
                : translate("errors.projectSaveFailed"));
        }

        if (!payload?.project?.id) {
            if (automatic) {
                shouldRetryAutosave = true;
                return false;
            }
            throw new Error(translate("errors.projectSaveFailed"));
        }

        projectState.currentProjectId = payload.project.id;
        projectState.currentProjectName = normalizeProjectNameValue(payload.project.name);
        projectState.currentProjectAccessMode = "owner";
        projectState.savedProjectSignature = getProjectPersistenceSignature(projectState.currentProjectName, projectSnapshot);
        projectState.currentProjectSavedAt = typeof payload?.project?.updatedAt === "string" && payload.project.updatedAt.trim()
            ? payload.project.updatedAt
            : new Date().toISOString();
        persistPendingProjectSnapshot();
        void refreshProjectList({ silent: true });
        renderProjectPicker();
        return true;
    } catch (error) {
        if (automatic) {
            shouldRetryAutosave = true;
            return false;
        }

        openAppNoticeDialog({
            title: translate("dialog.projectSaveErrorTitle"),
            message: error?.message || translate("errors.projectSaveFailed")
        });
        return false;
    } finally {
        projectState.projectSaving = false;
        renderProjectControls();
        if (shouldRetryAutosave && projectState.authenticatedUser?.id && !hasProjectNameConflict() && isCurrentProjectDirty()) {
            scheduleProjectAutosave(
                Math.max(getProjectAutosaveDelayMs(), PROJECT_AUTOSAVE_RETRY_DELAY_MS),
                getProjectPersistenceSignature()
            );
        } else {
            syncProjectAutosave();
        }
    }
}

function translate(key, params = {}) {
    const languageTable = TRANSLATIONS[projectState.language] || TRANSLATIONS.es;
    const fallbackValue = TRANSLATIONS.es[key] ?? key;
    const rawValue = languageTable[key] ?? fallbackValue;

    return rawValue.replace(/\{(\w+)\}/g, (_, token) => {
        const replacement = params[token];
        return replacement === undefined || replacement === null ? `{${token}}` : String(replacement);
    });
}

function setButtonCopy(button, label) {
    if (!button) {
        return;
    }

    button.textContent = label;
}

function getToolShortcutLabel(tool) {
    switch (tool) {
        case "delete":
            return "Ctrl+X";
        case "beam":
            return "Ctrl+Shift+V";
        case "col":
            return "Ctrl+Shift+C";
        case "slab":
            return "Ctrl+Shift+L";
        default:
            return "";
    }
}

function clearAppDialogAutoCloseTimer() {
    if (!appDialogState.autoCloseTimer || !isBrowser) {
        return;
    }

    window.clearTimeout(appDialogState.autoCloseTimer);
    appDialogState.autoCloseTimer = 0;
}

function isAppDialogOpen() {
    return dom.appDialogOverlay?.style.display === "flex";
}

function renderAppDialog() {
    if (!isBrowser || !dom.appDialogOverlay) {
        return;
    }

    const config = appDialogState.currentConfig || {};
    if (dom.appDialogKicker) {
        dom.appDialogKicker.textContent = config.kicker || translate("dialog.kicker");
    }
    if (dom.appDialogTitle) {
        dom.appDialogTitle.textContent = config.title || translate("dialog.defaultTitle");
    }
    if (dom.appDialogMessage) {
        dom.appDialogMessage.textContent = config.message || "";
        dom.appDialogMessage.hidden = !config.message;
    }
    if (dom.appDialogBody) {
        dom.appDialogBody.innerHTML = config.bodyHtml || "";
        dom.appDialogBody.hidden = !config.bodyHtml;
    }
    if (dom.appDialogCancelButton) {
        dom.appDialogCancelButton.hidden = !config.showCancel;
        dom.appDialogCancelButton.textContent = config.cancelLabel || translate("dialog.cancel");
    }
    if (dom.appDialogConfirmButton) {
        dom.appDialogConfirmButton.textContent = config.confirmLabel || translate("dialog.ok");
    }
}

function resolveAppDialogResult(result, config = appDialogState.currentConfig || {}) {
    if (result === false) {
        return false;
    }

    if (typeof config.confirmValueGetter === "function") {
        try {
            const confirmValue = config.confirmValueGetter();
            return confirmValue === undefined || confirmValue === null || confirmValue === ""
                ? false
                : confirmValue;
        } catch (error) {
            return false;
        }
    }

    return Boolean(result);
}

function closeAppDialog(result = false) {
    clearAppDialogAutoCloseTimer();

    if (dom.appDialogOverlay) {
        dom.appDialogOverlay.style.display = "none";
    }

    const resolver = appDialogState.resolver;
    const currentConfig = appDialogState.currentConfig || {};
    appDialogState.resolver = null;
    appDialogState.currentConfig = null;

    if (typeof resolver === "function") {
        resolver(resolveAppDialogResult(result, currentConfig));
    }
}

function openAppDialog(config = {}, resolver = null) {
    clearAppDialogAutoCloseTimer();

    if (typeof appDialogState.resolver === "function") {
        const pendingResolver = appDialogState.resolver;
        appDialogState.resolver = null;
        pendingResolver(false);
    }

    appDialogState.currentConfig = {
        kicker: translate("dialog.kicker"),
        title: translate("dialog.defaultTitle"),
        message: "",
        bodyHtml: "",
        confirmLabel: translate("dialog.ok"),
        cancelLabel: translate("dialog.cancel"),
        showCancel: false,
        closeOnOverlay: true,
        closeOnEscape: true,
        autoCloseMs: 0,
        autoFocusSelector: "",
        confirmValueGetter: null,
        ...config
    };
    appDialogState.resolver = typeof resolver === "function" ? resolver : null;

    if (dom.appDialogOverlay) {
        dom.appDialogOverlay.style.display = "flex";
    }

    renderAppDialog();

    if (isBrowser && appDialogState.currentConfig.autoFocusSelector) {
        window.requestAnimationFrame(() => {
            if (!isAppDialogOpen()) {
                return;
            }

            const focusTarget = dom.appDialogOverlay?.querySelector(appDialogState.currentConfig.autoFocusSelector);
            if (focusTarget instanceof HTMLElement) {
                focusTarget.focus();
                if (typeof focusTarget.select === "function") {
                    focusTarget.select();
                }
            }
        });
    }

    if (isBrowser && Number.isFinite(appDialogState.currentConfig.autoCloseMs) && appDialogState.currentConfig.autoCloseMs > 0) {
        appDialogState.autoCloseTimer = window.setTimeout(() => {
            closeAppDialog(false);
        }, appDialogState.currentConfig.autoCloseMs);
    }
}

function openAppNoticeDialog(config = {}) {
    openAppDialog(config);
}

function requestAppConfirmation(config = {}) {
    return new Promise((resolve) => {
        openAppDialog({
            showCancel: true,
            closeOnOverlay: false,
            autoCloseMs: 0,
            ...config
        }, resolve);
    });
}

function normalizeEtabsImportLengthUnit(value) {
    const normalizedValue = String(value || "").trim().toLowerCase();
    return ETABS_IMPORT_LENGTH_UNIT_OPTIONS.some((option) => option.value === normalizedValue)
        ? normalizedValue
        : DEFAULT_ETABS_IMPORT_LENGTH_UNIT;
}

function buildEtabsImportLengthUnitDialogMarkup(selectedUnit = DEFAULT_ETABS_IMPORT_LENGTH_UNIT) {
    const normalizedSelectedUnit = normalizeEtabsImportLengthUnit(selectedUnit);

    return `
        <div class="app-dialog-form-row">
            <label class="app-dialog-form-copy" for="etabs-import-length-unit-select">
                <span class="app-dialog-form-label">${escapeHtml(translate("dialog.etabsDistanceLabel"))}</span>
                <span class="app-dialog-form-note">${escapeHtml(translate("dialog.etabsDistanceNote"))}</span>
            </label>
            <select
                id="etabs-import-length-unit-select"
                class="app-dialog-form-select"
                aria-label="${escapeHtml(translate("dialog.etabsDistanceLabel"))}"
            >
                ${ETABS_IMPORT_LENGTH_UNIT_OPTIONS.map((option) => (
                    `<option value="${escapeHtml(option.value)}"${option.value === normalizedSelectedUnit ? " selected" : ""}>${escapeHtml(option.label)}</option>`
                )).join("")}
            </select>
        </div>
    `;
}

function requestEtabsImportLengthUnit(defaultUnit = DEFAULT_ETABS_IMPORT_LENGTH_UNIT) {
    return new Promise((resolve) => {
        openAppDialog({
            kicker: translate("dialog.etabsUnitsKicker"),
            title: translate("dialog.etabsUnitsTitle"),
            message: translate("dialog.etabsUnitsMessage"),
            bodyHtml: buildEtabsImportLengthUnitDialogMarkup(defaultUnit),
            showCancel: true,
            closeOnOverlay: false,
            closeOnEscape: true,
            autoCloseMs: 0,
            confirmLabel: translate("dialog.importConfirmAction"),
            cancelLabel: translate("dialog.cancel"),
            autoFocusSelector: "#etabs-import-length-unit-select",
            confirmValueGetter: () => normalizeEtabsImportLengthUnit(
                dom.appDialogOverlay?.querySelector("#etabs-import-length-unit-select")?.value
            )
        }, (result) => {
            resolve(result === false ? null : normalizeEtabsImportLengthUnit(result));
        });
    });
}

function normalizeEtabsWallClassification(value) {
    const normalizedValue = String(value || "").trim();
    return ETABS_WALL_CLASSIFICATION_OPTIONS.some((option) => option.value === normalizedValue)
        ? normalizedValue
        : DEFAULT_ETABS_WALL_CLASSIFICATION;
}

function getEtabsWallClassificationSelectOptions() {
    return ETABS_WALL_CLASSIFICATION_OPTIONS.map((option) => ({
        value: option.value,
        label: translate(option.labelKey)
    }));
}

function getEtabsImportedWallLabel(wall) {
    return normalizeTextValue(
        wall?.sourceLabel
        || wall?.label
        || wall?.name
        || wall?.sourceId
        || wall?.id
    );
}

function getEtabsImportedWallClassificationKey(wall) {
    return normalizeImportedLookupKey(getEtabsImportedWallLabel(wall))
        || normalizeImportedLookupKey(wall?.sourceId)
        || normalizeImportedLookupKey(wall?.id);
}

function formatEtabsWallClassificationList(values, formatter = (value) => value) {
    const normalizedValues = Array.from(values || [])
        .map((value) => normalizeTextValue(formatter(value)))
        .filter(Boolean);

    if (normalizedValues.length === 0) {
        return "-";
    }

    if (normalizedValues.length <= 3) {
        return normalizedValues.join(", ");
    }

    return `${normalizedValues.slice(0, 3).join(", ")} +${normalizedValues.length - 3}`;
}

function collectEtabsImportedWallClassificationEntries(importData) {
    const elementsByStory = importData?.normalizedForStructaCAD?.elementsByStory;
    if (!elementsByStory || typeof elementsByStory !== "object") {
        return [];
    }

    const entriesByKey = new Map();
    Object.entries(elementsByStory).forEach(([storyName, storyElements]) => {
        const walls = Array.isArray(storyElements?.walls) ? storyElements.walls : [];
        walls.forEach((wall) => {
            const key = getEtabsImportedWallClassificationKey(wall);
            if (!key) {
                return;
            }

            const label = getEtabsImportedWallLabel(wall) || normalizeTextValue(wall?.sourceId) || key;
            const entry = entriesByKey.get(key) || {
                key,
                label,
                count: 0,
                stories: new Set(),
                sections: new Set(),
                thicknesses: new Set()
            };
            entry.count += 1;
            entry.stories.add(normalizeTextValue(wall?.sourceStory || storyName) || translate("dialog.etabsWallClassificationNoStory"));
            entry.sections.add(normalizeTextValue(wall?.sourceSection));
            const thickness = parsePositiveNumberOrFallback(wall?.b, Number.NaN);
            if (Number.isFinite(thickness)) {
                entry.thicknesses.add(Number(thickness.toFixed(3)));
            }
            entriesByKey.set(key, entry);
        });
    });

    return Array.from(entriesByKey.values())
        .map((entry) => ({
            ...entry,
            storiesLabel: formatEtabsWallClassificationList(entry.stories),
            sectionsLabel: formatEtabsWallClassificationList(entry.sections),
            thicknessesLabel: formatEtabsWallClassificationList(entry.thicknesses, (value) => `${Number(value).toFixed(2)}m`)
        }))
        .sort((left, right) => left.label.localeCompare(right.label, undefined, { numeric: true, sensitivity: "base" }));
}

function buildEtabsWallClassificationDialogMarkup(entries) {
    const options = getEtabsWallClassificationSelectOptions();
    const optionMarkup = options.map((option) => (
        `<option value="${escapeHtml(option.value)}"${option.value === DEFAULT_ETABS_WALL_CLASSIFICATION ? " selected" : ""}>${escapeHtml(option.label)}</option>`
    )).join("");

    return `
        <div class="etabs-wall-classification-bulk-actions" aria-label="${escapeHtml(translate("dialog.etabsWallClassificationTypeLabel"))}">
            <button type="button" class="button button-outline etabs-wall-classification-bulk-btn" data-etabs-wall-classification-bulk="nonStructural">
                ${escapeHtml(translate("dialog.etabsWallClassificationAllNonStructural"))}
            </button>
            <button type="button" class="button button-outline etabs-wall-classification-bulk-btn" data-etabs-wall-classification-bulk="concrete">
                ${escapeHtml(translate("dialog.etabsWallClassificationAllConcrete"))}
            </button>
            <button type="button" class="button button-outline etabs-wall-classification-bulk-btn" data-etabs-wall-classification-bulk="masonry">
                ${escapeHtml(translate("dialog.etabsWallClassificationAllMasonry"))}
            </button>
        </div>
        <div class="etabs-wall-classification-list">
            <div class="etabs-wall-classification-head" aria-hidden="true">
                <span>${escapeHtml(translate("dialog.etabsWallClassificationWallLabel"))}</span>
                <span>${escapeHtml(translate("dialog.etabsWallClassificationTypeLabel"))}</span>
            </div>
            ${entries.map((entry, index) => `
                <div class="etabs-wall-classification-row">
                    <div class="etabs-wall-classification-copy">
                        <span class="etabs-wall-classification-label">${escapeHtml(entry.label)}</span>
                        <span class="etabs-wall-classification-meta">${escapeHtml(translate("dialog.etabsWallClassificationMeta", {
                            count: entry.count,
                            stories: entry.storiesLabel,
                            thicknesses: entry.thicknessesLabel
                        }))}</span>
                    </div>
                    <select
                        class="app-dialog-form-select etabs-wall-classification-select"
                        data-etabs-wall-classification-key="${escapeHtml(entry.key)}"
                        id="etabs-wall-classification-${index}"
                        aria-label="${escapeHtml(`${translate("dialog.etabsWallClassificationTypeLabel")} ${entry.label}`)}"
                    >
                        ${optionMarkup}
                    </select>
                </div>
            `).join("")}
        </div>
    `;
}

function setEtabsWallClassificationSelections(classification) {
    const normalizedClassification = normalizeEtabsWallClassification(classification);
    const selects = dom.appDialogOverlay?.querySelectorAll(".etabs-wall-classification-select") || [];

    selects.forEach((select) => {
        select.value = normalizedClassification;
        select.dispatchEvent(new Event("change", { bubbles: true }));
    });
}

function bindEtabsWallClassificationBulkActions() {
    const buttons = dom.appDialogOverlay?.querySelectorAll("[data-etabs-wall-classification-bulk]") || [];

    buttons.forEach((button) => {
        button.addEventListener("click", () => {
            setEtabsWallClassificationSelections(button.dataset.etabsWallClassificationBulk);
        });
    });
}

function requestEtabsWallClassifications(importData) {
    const entries = collectEtabsImportedWallClassificationEntries(importData);
    if (entries.length === 0) {
        return Promise.resolve([]);
    }

    return new Promise((resolve) => {
        openAppDialog({
            kicker: translate("dialog.etabsWallClassificationKicker"),
            title: translate("dialog.etabsWallClassificationTitle"),
            message: translate("dialog.etabsWallClassificationMessage"),
            bodyHtml: buildEtabsWallClassificationDialogMarkup(entries),
            showCancel: true,
            closeOnOverlay: false,
            closeOnEscape: true,
            autoCloseMs: 0,
            confirmLabel: translate("dialog.importConfirmAction"),
            cancelLabel: translate("dialog.cancel"),
            autoFocusSelector: "#etabs-wall-classification-0",
            confirmValueGetter: () => entries.map((entry) => ({
                key: entry.key,
                classification: normalizeEtabsWallClassification(
                    Array.from(dom.appDialogOverlay?.querySelectorAll("[data-etabs-wall-classification-key]") || [])
                        .find((element) => element?.dataset?.etabsWallClassificationKey === entry.key)
                        ?.value
                )
            }))
        }, (result) => {
            resolve(result === false ? null : result);
        });

        bindEtabsWallClassificationBulkActions();
    });
}

function applyEtabsWallClassifications(importData, classifications) {
    const elementsByStory = importData?.normalizedForStructaCAD?.elementsByStory;
    const stats = {
        labels: Array.isArray(classifications) ? classifications.length : 0,
        imported: 0,
        nonStructural: 0,
        concrete: 0,
        masonry: 0
    };

    if (!elementsByStory || typeof elementsByStory !== "object") {
        return stats;
    }

    const classificationsByKey = new Map(
        (Array.isArray(classifications) ? classifications : []).map((entry) => ([
            normalizeImportedLookupKey(entry?.key),
            normalizeEtabsWallClassification(entry?.classification)
        ]))
    );

    Object.values(elementsByStory).forEach((storyElements) => {
        if (!Array.isArray(storyElements?.walls)) {
            return;
        }

        storyElements.walls = storyElements.walls.flatMap((wall) => {
            const key = getEtabsImportedWallClassificationKey(wall);
            const classification = classificationsByKey.get(key) || DEFAULT_ETABS_WALL_CLASSIFICATION;

            if (classification === "nonStructural") {
                stats.nonStructural += 1;
                return [];
            }

            const material = classification === "masonry" ? "masonry" : "concrete";
            stats.imported += 1;
            stats[material] += 1;
            return [{
                ...wall,
                material,
                sourceWallClassification: classification
            }];
        });
    });

    return stats;
}

function setToolButtonLanguage(button, label) {
    if (!button) {
        return;
    }

    const shortcutLabel = getToolShortcutLabel(button.dataset.tool);
    const tooltipLabel = shortcutLabel ? `${label} | ${shortcutLabel}` : label;

    button.dataset.tooltip = tooltipLabel;
    button.title = tooltipLabel;
    button.setAttribute("aria-label", tooltipLabel);
}

function getSidebarToolButtonLabel(button) {
    if (!button) {
        return "";
    }

    if (button.dataset.tool === "slab") {
        if (button.dataset.slabKind === "lightened") {
            return translate("tool.slabLightened") || translate("modal.slabLightened");
        }
        if (button.dataset.slabKind === SLAB_TYPE_SOLID_STAIR) {
            return translate("tool.slabSolidStair") || translate("modal.slabSolidStair");
        }
        return translate("tool.slabSolid") || translate("modal.slabSolid");
    }

    return translate(`tool.${button.dataset.tool}`) || "";
}

function setWorkspaceToolShortcutLanguage(button, label) {
    if (!button) {
        return;
    }

    const labelElement = button.querySelector("[data-workspace-tool-label]");
    if (labelElement) {
        labelElement.textContent = label;
    }

    const shortcutLabel = getToolShortcutLabel(button.dataset.workspaceTool);
    const tooltipLabel = shortcutLabel ? `${label} | ${shortcutLabel}` : label;
    button.title = tooltipLabel;
    button.setAttribute("aria-label", tooltipLabel);
}

function getWorkspaceShortcutSidebarMode(tool) {
    if (tool === "delete") {
        if (MODEL_SIDEBAR_MODES.includes(projectState.sidebarMode)) {
            return projectState.sidebarMode;
        }

        if (projectState.tool === "slab") {
            return "slab";
        }

        if (projectState.tool === "wall") {
            return "wall";
        }

        return "frame";
    }

    if (tool === "slab") {
        return "slab";
    }

    if (tool === "wall") {
        return "wall";
    }

    return "frame";
}

function syncWorkspaceQuickToolButtons() {
    dom.workspaceQuickToolButtons?.forEach((button) => {
        const tool = button.dataset.workspaceTool;
        let isActive = false;

        if (tool === "delete") {
            isActive = projectState.tool === "delete" && MODEL_SIDEBAR_MODES.includes(projectState.sidebarMode);
        } else {
            isActive = projectState.tool === tool && projectState.sidebarMode === getWorkspaceShortcutSidebarMode(tool);
        }

        button.classList.toggle("active-tool", isActive);
        button.setAttribute("aria-pressed", String(isActive));
    });
}

function getSidebarToolButtonActiveState(button, tool = projectState.tool) {
    if (!button || button.dataset.tool !== tool) {
        return false;
    }

    if (tool === "slab") {
        const slabKind = button.dataset.slabKind;
        if (slabKind) {
            return normalizeSlabInsertDraft(projectState.insertDrafts.slab).type === slabKind;
        }
    }

    return true;
}

function syncSidebarToolButtons() {
    dom.toolButtons.forEach((button) => {
        const modes = String(button.dataset.toolModes || "")
            .split(/\s+/)
            .filter(Boolean);
        const isVisible = modes.includes(projectState.sidebarMode);
        const isActive = isVisible && getSidebarToolButtonActiveState(button);
        button.classList.toggle("active-tool", isActive);
        button.setAttribute("aria-pressed", String(isActive));
    });
}

function setDefaultSlabInsertType(type = "solid") {
    projectState.insertDrafts.slab = normalizeSlabInsertDraft({
        ...projectState.insertDrafts.slab,
        type
    });
}

function syncModeAwareToolIcons() {
    const showFrameEditIcon = projectState.sidebarMode === "frame";
    if (dom.toolEditFrameIcon) {
        dom.toolEditFrameIcon.hidden = !showFrameEditIcon;
    }
    if (dom.toolEditGenericIcon) {
        dom.toolEditGenericIcon.hidden = showFrameEditIcon;
    }
}

function activateWorkspaceToolShortcut(tool) {
    const targetMode = getWorkspaceShortcutSidebarMode(tool);
    if (targetMode && targetMode !== projectState.sidebarMode) {
        setSidebarMode(targetMode);
    }

    if (tool === "slab") {
        setDefaultSlabInsertType("solid");
    }

    setTool(tool);
}

function applyBillingStatusPayload(payload = {}) {
    const previousUserId = projectState.authenticatedUser?.id || "";
    projectState.authenticatedUser = payload.authenticated ? (payload.user || null) : null;
    projectState.billingConfigured = Boolean(payload.configured);
    projectState.billingCanExport = Boolean(payload.canExport);
    projectState.freeDxfDownloadLimit = Number.isFinite(Number(payload.freeDxfDownloadLimit))
        ? Math.max(0, Number(payload.freeDxfDownloadLimit))
        : 10;
    projectState.freeDxfDownloadsRemaining = Number.isFinite(Number(payload.freeDxfDownloadsRemaining))
        ? Math.max(0, Number(payload.freeDxfDownloadsRemaining))
        : 0;
    projectState.billingSubscription = payload.subscription || null;
    projectState.billingPlans = Array.isArray(payload.plans) ? payload.plans : [];
    projectState.billingStatusLoaded = true;

    void syncProjectLibraryAfterAuthChange(previousUserId, projectState.authenticatedUser?.id || "");
    syncSurveyVisibility();
    renderSupportUi();
}

function applyAuthSessionPayload(payload = {}) {
    const previousUserId = projectState.authenticatedUser?.id || "";
    projectState.authenticatedUser = payload.authenticated ? (payload.user || null) : null;
    projectState.billingStatusLoaded = true;

    void syncProjectLibraryAfterAuthChange(previousUserId, projectState.authenticatedUser?.id || "");
    syncSurveyVisibility();
    renderSupportUi();
}

async function refreshAuthSession() {
    try {
        const response = await fetch("/api/auth/session", {
            method: "GET",
            credentials: "same-origin",
            headers: {
                Accept: "application/json"
            }
        });
        const payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            return null;
        }

        applyAuthSessionPayload(payload);
        return payload;
    } catch (error) {
        return null;
    }
}

function formatBillingDateLabel(value) {
    const date = new Date(value);
    if (!Number.isFinite(date.getTime())) {
        return "";
    }

    try {
        return new Intl.DateTimeFormat(projectState.language === "en" ? "en-US" : "es-BO", {
            year: "numeric",
            month: "short",
            day: "numeric"
        }).format(date);
    } catch (error) {
        return date.toLocaleDateString();
    }
}

function normalizeBillingPlanCode(planCode) {
    const normalizedPlanCode = String(planCode || "").trim().toLowerCase();
    return normalizedPlanCode === "monthly" || normalizedPlanCode === "yearly"
        ? normalizedPlanCode
        : "";
}

function getBillingCheckoutPageUrl(planCode) {
    const normalizedPlanCode = normalizeBillingPlanCode(planCode);
    return normalizedPlanCode
        ? `/checkout?plan=${encodeURIComponent(normalizedPlanCode)}&open=1`
        : "/checkout";
}

function getBillingPlanLabel(planCode) {
    return translate(planCode === "yearly" ? "billing.plan.yearly.name" : "billing.plan.monthly.name");
}

function getBillingPlanPriceLabel(planCode) {
    const matchedPlan = projectState.billingPlans.find((plan) => plan?.code === planCode);
    const amount = Number(matchedPlan?.amountUsd);
    if (!Number.isFinite(amount) || amount <= 0) {
        return translate(planCode === "yearly" ? "billing.plan.yearly.price" : "billing.plan.monthly.price");
    }

    const amountLabel = Number.isInteger(amount)
        ? String(amount)
        : amount.toFixed(2);
    const intervalLabel = matchedPlan?.interval === "year"
        ? (projectState.language === "en" ? "year" : "año")
        : (projectState.language === "en" ? "month" : "mes");

    return `$${amountLabel} / ${intervalLabel}`;
}

function getBillingPlanAvailability(planCode) {
    const normalizedPlanCode = normalizeBillingPlanCode(planCode);
    if (!normalizedPlanCode) {
        return false;
    }

    const matchedPlan = projectState.billingPlans.find((plan) => plan?.code === normalizedPlanCode);
    return matchedPlan ? matchedPlan.available !== false : true;
}

function isBillingPlanCheckoutDisabled(planCode) {
    if (!projectState.authenticatedUser?.id) {
        return Boolean(projectState.billingBusyAction);
    }

    return Boolean(projectState.billingBusyAction)
        || projectState.billingCanExport
        || !normalizeBillingPlanCode(planCode);
}

async function runPendingFreeDxfExportAction() {
    const pendingAction = projectState.pendingFreeDxfExportAction;
    projectState.pendingFreeDxfExportAction = null;
    if (typeof pendingAction !== "function") {
        return false;
    }

    projectState.billingFreeExportConfirmed = true;
    try {
        await pendingAction();
    } finally {
        projectState.billingFreeExportConfirmed = false;
        renderBillingUi();
    }

    return true;
}

function persistPendingBillingCheckoutPlan(planCode) {
    if (!isBrowser) {
        return;
    }

    const normalizedPlanCode = normalizeBillingPlanCode(planCode);
    if (!normalizedPlanCode) {
        return;
    }

    try {
        window.sessionStorage.setItem(PENDING_BILLING_CHECKOUT_STORAGE_KEY, normalizedPlanCode);
    } catch (error) {
        // Ignore storage failures; the user can still choose the plan again after login.
    }
}

function consumePendingBillingCheckoutPlan() {
    if (!isBrowser) {
        return "";
    }

    try {
        const planCode = normalizeBillingPlanCode(window.sessionStorage.getItem(PENDING_BILLING_CHECKOUT_STORAGE_KEY));
        window.sessionStorage.removeItem(PENDING_BILLING_CHECKOUT_STORAGE_KEY);
        return planCode;
    } catch (error) {
        return "";
    }
}

function getBillingScheduleCopy(subscription = projectState.billingSubscription) {
    if (!subscription || typeof subscription !== "object") {
        return "";
    }

    const dateLabel = formatBillingDateLabel(subscription.status === "cancelled" ? subscription.endsAt : subscription.renewsAt || subscription.endsAt);
    if (!dateLabel) {
        return "";
    }

    if (subscription.status === "cancelled" && subscription.endsAt) {
        return translate("billing.schedule.endsOn", { date: dateLabel });
    }

    return translate("billing.schedule.renewsOn", { date: dateLabel });
}

function getExportAccessNoteText() {
    if (!projectState.billingStatusLoaded && projectState.billingLoading) {
        return translate("billing.status.loading");
    }

    if (projectState.billingCanExport && projectState.billingSubscription) {
        const schedule = getBillingScheduleCopy(projectState.billingSubscription) || translate("billing.status.active");
        return translate("export.access.active", {
            plan: getBillingPlanLabel(projectState.billingSubscription.planCode),
            schedule
        });
    }

    if (projectState.authenticatedUser?.id && projectState.freeDxfDownloadsRemaining > 0) {
        return translate("export.access.freeDownloadsRemaining", {
            count: projectState.freeDxfDownloadsRemaining
        });
    }

    if (!projectState.authenticatedUser?.id) {
        return translate("export.access.loginRequired");
    }

    return translate("export.access.subscribeRequired");
}

function getDefaultBillingModalMessage() {
    if (!projectState.billingStatusLoaded && projectState.billingLoading) {
        return translate("billing.status.loading");
    }

    if (projectState.billingBusyAction) {
        return translate("billing.status.redirecting");
    }

    if (!projectState.authenticatedUser?.id) {
        return translate("billing.status.loginFirst");
    }

    if (projectState.billingCanExport) {
        const schedule = getBillingScheduleCopy(projectState.billingSubscription);
        return schedule ? `${translate("billing.status.active")} ${schedule}` : translate("billing.status.active");
    }

    if (projectState.freeDxfDownloadsRemaining > 0) {
        return translate("export.access.freeDownloadsRemaining", {
            count: projectState.freeDxfDownloadsRemaining
        });
    }

    return translate("billing.status.subscriptionRequired");
}

function getBillingTrialCopy() {
    if (!projectState.authenticatedUser?.id) {
        return translate("billing.plan.trial.copyLogin");
    }

    if (projectState.freeDxfDownloadsRemaining > 0) {
        return translate("billing.plan.trial.copyRemaining", {
            count: projectState.freeDxfDownloadsRemaining
        });
    }

    return translate("billing.plan.trial.copyExhausted");
}

function isBillingModalOpen() {
    return dom.billingModalOverlay?.style.display === "flex";
}

function renderBillingModalMessage() {
    if (!dom.billingModalStatus) {
        return;
    }

    const message = projectState.billingModalMessage || getDefaultBillingModalMessage();
    dom.billingModalStatus.hidden = !message;
    dom.billingModalStatus.textContent = message || "";
}

function renderBillingUi() {
    if (!isBrowser || !dom.exportAccessNote) {
        return;
    }

    dom.exportAccessNote.textContent = getExportAccessNoteText();
    if (dom.exportFreeDownloadsNote) {
        const showFreeDownloads = Boolean(
            projectState.authenticatedUser
            && !projectState.billingCanExport
            && projectState.freeDxfDownloadsRemaining > 0
        );
        dom.exportFreeDownloadsNote.hidden = !showFreeDownloads;
        dom.exportFreeDownloadsNote.textContent = showFreeDownloads
            ? translate("export.freeDownloadsRemaining", {
                count: projectState.freeDxfDownloadsRemaining
            })
            : "";
    }

    if (dom.billingManageButton) {
        const canManage = Boolean(projectState.authenticatedUser?.id && projectState.billingCanExport && projectState.billingSubscription?.hasPortal);
        dom.billingManageButton.hidden = !canManage;
        dom.billingManageButton.textContent = translate("billing.manageButton");
    }

    if (dom.billingModalKicker) {
        dom.billingModalKicker.textContent = translate("billing.kicker");
    }
    if (dom.billingModalTitle) {
        dom.billingModalTitle.textContent = translate("billing.title");
    }
    if (dom.billingModalCopy) {
        dom.billingModalCopy.textContent = translate("billing.copy");
    }
    const isTrialExhausted = Boolean(
        projectState.authenticatedUser?.id
        && !projectState.billingCanExport
        && projectState.freeDxfDownloadsRemaining <= 0
    );
    if (dom.billingPlanTrialName) {
        dom.billingPlanTrialName.textContent = translate(isTrialExhausted
            ? "billing.plan.trial.nameExhausted"
            : "billing.plan.trial.name");
    }
    if (dom.billingPlanTrialPrice) {
        dom.billingPlanTrialPrice.textContent = translate("billing.plan.trial.price");
    }
    if (dom.billingPlanTrialCopy) {
        dom.billingPlanTrialCopy.textContent = getBillingTrialCopy();
    }
    if (dom.billingPlanTrialButton) {
        dom.billingPlanTrialButton.classList.toggle("is-exhausted", isTrialExhausted);
        dom.billingPlanTrialButton.disabled = Boolean(projectState.billingBusyAction);
    }
    if (dom.billingLoginButton) {
        dom.billingLoginButton.textContent = translate("billing.login");
        dom.billingLoginButton.hidden = Boolean(projectState.authenticatedUser?.id);
        dom.billingLoginButton.disabled = Boolean(projectState.billingBusyAction);
    }
    if (dom.billingPortalButton) {
        dom.billingPortalButton.textContent = translate("billing.portal");
        dom.billingPortalButton.hidden = !(projectState.authenticatedUser?.id && projectState.billingSubscription?.hasPortal);
        dom.billingPortalButton.disabled = Boolean(projectState.billingBusyAction) || !projectState.billingCanExport;
    }
    if (dom.billingModalCloseButton) {
        dom.billingModalCloseButton.textContent = translate("billing.close");
        dom.billingModalCloseButton.disabled = Boolean(projectState.billingBusyAction);
    }

    if (dom.billingPlanMonthlyName) {
        dom.billingPlanMonthlyName.textContent = translate("billing.plan.monthly.name");
    }
    if (dom.billingPlanMonthlyPrice) {
        dom.billingPlanMonthlyPrice.textContent = getBillingPlanPriceLabel("monthly");
    }
    if (dom.billingPlanMonthlyCopy) {
        dom.billingPlanMonthlyCopy.textContent = translate("billing.plan.monthly.copy");
    }
    if (dom.billingPlanYearlyName) {
        dom.billingPlanYearlyName.textContent = translate("billing.plan.yearly.name");
    }
    if (dom.billingPlanYearlyPrice) {
        dom.billingPlanYearlyPrice.textContent = getBillingPlanPriceLabel("yearly");
    }
    if (dom.billingPlanYearlyCopy) {
        dom.billingPlanYearlyCopy.textContent = translate("billing.plan.yearly.copy");
    }

    const disableMonthlyPlan = isBillingPlanCheckoutDisabled("monthly");
    const disableYearlyPlan = isBillingPlanCheckoutDisabled("yearly");
    if (dom.billingPlanMonthlyButton) {
        dom.billingPlanMonthlyButton.disabled = disableMonthlyPlan;
    }
    if (dom.billingPlanYearlyButton) {
        dom.billingPlanYearlyButton.disabled = disableYearlyPlan;
    }

    renderBillingModalMessage();
    renderWorkspaceSessionControl();
}

function renderWorkspaceSessionControl() {
    const hasAuthenticatedUser = Boolean(projectState.authenticatedUser?.id);

    if (dom.workspaceAuthAccessRow) {
        dom.workspaceAuthAccessRow.hidden = !projectState.billingStatusLoaded || hasAuthenticatedUser;
    }

    if (dom.workspaceLogoutRow) {
        dom.workspaceLogoutRow.hidden = !hasAuthenticatedUser;
    }

    if (dom.topPanelSignupLink) {
        dom.topPanelSignupLink.hidden = hasAuthenticatedUser;
    }
    if (dom.topPanelLoginLink) {
        dom.topPanelLoginLink.hidden = hasAuthenticatedUser;
    }
    if (dom.topPanelAuthSeparator) {
        dom.topPanelAuthSeparator.hidden = hasAuthenticatedUser;
    }
    if (dom.topPanelLogoutButton) {
        dom.topPanelLogoutButton.hidden = !hasAuthenticatedUser;
    }

    const shouldShowUpgradePro = Boolean(
        hasAuthenticatedUser
        && projectState.billingStatusLoaded
        && !projectState.billingCanExport
    );

    if (dom.workspaceUpgradeProButton) {
        dom.workspaceUpgradeProButton.hidden = !shouldShowUpgradePro;
        dom.workspaceUpgradeProButton.disabled = !shouldShowUpgradePro || Boolean(projectState.billingBusyAction);
    }
    if (dom.workspaceUpgradeProSeparator) {
        dom.workspaceUpgradeProSeparator.hidden = !shouldShowUpgradePro;
    }

    if (!dom.workspaceLogoutButton) {
        return;
    }

    if (dom.workspaceMainMenuButton) {
        dom.workspaceMainMenuButton.textContent = translate("workspace.mainMenu");
    }
    if (dom.workspaceAnalysisOpenButton) {
        dom.workspaceAnalysisOpenButton.textContent = translate("workspace.structuralAnalysisButton");
    }
    dom.workspaceLogoutButton.textContent = translate("workspace.logout");
}

function openBillingModal(message = "") {
    projectState.billingModalMessage = message ? String(message) : "";
    if (dom.billingModalOverlay) {
        dom.billingModalOverlay.style.display = "flex";
    }
    renderBillingUi();
}

function closeBillingModal() {
    projectState.billingModalMessage = "";
    projectState.pendingFreeDxfExportAction = null;
    if (dom.billingModalOverlay) {
        dom.billingModalOverlay.style.display = "none";
    }
    renderBillingUi();
}

async function refreshBillingStatus({ silent = false } = {}) {
    if (!silent) {
        projectState.billingLoading = true;
        renderBillingUi();
    } else {
        projectState.billingLoading = true;
    }

    try {
        const response = await fetch("/api/billing/status", {
            method: "GET",
            credentials: "same-origin",
            headers: {
                Accept: "application/json"
            }
        });
        const payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            throw new Error(typeof payload?.error === "string" && payload.error.trim() ? payload.error : translate("errors.billingStatusFailed"));
        }

        applyBillingStatusPayload(payload);
        if (!payload.authenticated) {
            await refreshAuthSession();
        }
        return payload;
    } catch (error) {
        await refreshAuthSession();
        projectState.billingStatusLoaded = true;
        if (!silent) {
            projectState.billingModalMessage = error?.message || translate("errors.billingStatusFailed");
        }
        return null;
    } finally {
        projectState.billingLoading = false;
        renderBillingUi();
        renderProjectPicker();
    }
}

function beginLoginForBilling(options = {}) {
    const checkoutPlan = normalizeBillingPlanCode(options?.checkoutPlan);
    if (checkoutPlan) {
        persistPendingBillingCheckoutPlan(checkoutPlan);
    }

    persistPendingProjectSnapshot();
    window.location.href = checkoutPlan
        ? `/login?checkout=${encodeURIComponent(checkoutPlan)}`
        : "/login";
}

function beginSignupForWorkspaceAccess() {
    persistPendingProjectSnapshot();
    window.location.href = "/login?mode=signup";
}

function returnToMainMenu() {
    persistPendingProjectSnapshot();
    window.location.href = "/";
}

async function handleWorkspaceLogout() {
    if (!projectState.authenticatedUser?.id) {
        return;
    }

    if (dom.workspaceLogoutButton) {
        dom.workspaceLogoutButton.disabled = true;
    }
    if (dom.topPanelLogoutButton) {
        dom.topPanelLogoutButton.disabled = true;
    }

    openAppNoticeDialog({
        title: translate("workspace.logout"),
        message: translate("dialog.logoutPending"),
        closeOnOverlay: false,
        closeOnEscape: false
    });

    try {
        const response = await fetch("/api/auth/logout", {
            method: "POST",
            credentials: "same-origin",
            headers: {
                Accept: "application/json"
            }
        });
        const payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            throw new Error(typeof payload?.error === "string" && payload.error.trim() ? payload.error : translate("errors.logoutFailed"));
        }

        closeBillingModal();
        await refreshBillingStatus({ silent: true });
        openAppNoticeDialog({
            title: translate("dialog.logoutSuccessTitle"),
            message: translate("dialog.logoutSuccessMessage")
        });
    } catch (error) {
        openAppNoticeDialog({
            title: translate("workspace.logout"),
            message: error?.message || translate("errors.logoutFailed")
        });
    } finally {
        if (dom.workspaceLogoutButton) {
            dom.workspaceLogoutButton.disabled = false;
        }
        if (dom.topPanelLogoutButton) {
            dom.topPanelLogoutButton.disabled = false;
        }
    }
}

async function resumePendingBillingCheckout() {
    if (!projectState.authenticatedUser?.id || projectState.billingBusyAction || projectState.billingCanExport) {
        return;
    }

    const pendingPlanCode = consumePendingBillingCheckoutPlan();
    if (!pendingPlanCode) {
        return;
    }

    openBillingModal(translate("billing.status.redirecting"));
    await beginCheckout(pendingPlanCode);
}

async function beginCheckout(planCode, triggerElement = null) {
    const normalizedPlanCode = normalizeBillingPlanCode(planCode);
    if (!normalizedPlanCode) {
        projectState.billingModalMessage = translate("errors.checkoutFailed");
        renderBillingUi();
        return;
    }

    if (!projectState.authenticatedUser?.id) {
        beginLoginForBilling({ checkoutPlan: normalizedPlanCode });
        return;
    }

    projectState.billingBusyAction = `checkout:${normalizedPlanCode}`;
    projectState.billingModalMessage = translate("billing.status.redirecting");
    renderBillingUi();

    persistPendingProjectSnapshot();
    window.location.href = getBillingCheckoutPageUrl(normalizedPlanCode);
}

async function openBillingPortal() {
    if (!projectState.authenticatedUser?.id) {
        beginLoginForBilling();
        return;
    }

    projectState.billingBusyAction = "portal";
    renderBillingUi();

    try {
        const response = await fetch("/api/billing/portal", {
            method: "GET",
            credentials: "same-origin",
            headers: {
                Accept: "application/json"
            }
        });
        const payload = await response.json().catch(() => ({}));

        if (!response.ok) {
            if (payload?.code === "authentication_required") {
                beginLoginForBilling();
                return;
            }

            throw new Error(typeof payload?.error === "string" && payload.error.trim() ? payload.error : translate("errors.portalFailed"));
        }

        if (typeof payload?.url !== "string" || !payload.url.trim()) {
            throw new Error(translate("errors.portalFailed"));
        }

        persistPendingProjectSnapshot();
        window.location.href = payload.url;
    } catch (error) {
        openBillingModal(error?.message || translate("errors.portalFailed"));
    } finally {
        projectState.billingBusyAction = "";
        renderBillingUi();
    }
}

async function recordDownloadLimitAttempt(context = {}) {
    if (!projectState.authenticatedUser?.id) {
        return;
    }

    const payload = {
        intent: "download-limit-attempt",
        exportKind: context.exportKind || "dxf",
        exportFormat: context.exportFormat || "dxf",
        outputMode: context.outputMode,
        selection: context.selection,
        fileName: context.fileName,
        exportConfig: context.exportConfig
    };

    try {
        await fetch("/api/health?intent=download-limit-attempt", {
            method: "POST",
            credentials: "same-origin",
            keepalive: true,
            headers: {
                "Content-Type": "application/json",
                Accept: "application/json"
            },
            body: JSON.stringify(payload)
        });
    } catch (error) {
        // Limit-attempt tracking should never block the export UI.
    }
}

async function ensureBillingStatusReady(limitAttemptContext = {}) {
    await refreshBillingStatus({ silent: true });

    if (!projectState.authenticatedUser?.id) {
        openBillingModal(translate("errors.loginRequired"));
        return false;
    }

    if (!projectState.billingCanExport && projectState.freeDxfDownloadsRemaining > 0) {
        if (projectState.billingFreeExportConfirmed) {
            projectState.billingFreeExportConfirmed = false;
            projectState.pendingFreeDxfExportAction = null;
            return true;
        }

        if (limitAttemptContext.requireBillingChoice) {
            projectState.pendingFreeDxfExportAction = typeof limitAttemptContext.pendingFreeDxfExportAction === "function"
                ? limitAttemptContext.pendingFreeDxfExportAction
                : null;
            openBillingModal(translate("export.access.freeDownloadsRemaining", {
                count: projectState.freeDxfDownloadsRemaining
            }));
            return false;
        }
    }

    if (!projectState.billingCanExport && projectState.freeDxfDownloadsRemaining <= 0) {
        const limitAttemptPromise = limitAttemptContext.trackDownloadLimitAttempt !== false
            ? recordDownloadLimitAttempt(limitAttemptContext)
            : Promise.resolve();
        openBillingModal(translate("billing.status.freeExportsExhausted"));
        await limitAttemptPromise;
        return false;
    }

    return true;
}

