function resizeCanvas() {
    const canvasContainer = dom.canvasStage || dom.workspace;
    dom.canvas.width = canvasContainer.clientWidth;
    dom.canvas.height = canvasContainer.clientHeight;
    render();
    resizeWorkspace3DRendererIfNeeded();
}

function setTool(tool) {
    clearBeamBreakMode({ shouldRender: false });

    if (projectState.sidebarMode !== "export") {
        const allowedTools = SIDEBAR_TOOLSETS[projectState.sidebarMode] || [];
        if (!allowedTools.includes(tool)) {
            return;
        }
    }

    projectState.tool = tool;
    projectState.firstNode = null;
    clearPendingSlabInsertion();
    closeOverlapPicker();
    if (tool === "section") {
        closeAiChatDrawer();
    }
    if (["col", "beam", "wall", "foundation", "slab"].includes(tool)) {
        clearSelectedElements({ shouldRender: false });
    }

    syncSidebarToolButtons();
    syncWorkspaceQuickToolButtons();

    updateCanvasCursor();
    updateToolDisplay();
    renderInsertPropertiesPanel();
    renderSectionPreviewPanel();
    notifyWorkspaceCommandModeChange();
    render();
}

function updateToolDisplay() {
    if (!dom.toolDisplay) {
        return;
    }

    updateToolInstructions();
}

function setModelSpaceTheme(theme) {
    projectState.modelSpaceTheme = theme === "dark" ? "dark" : "light";
    persistModelSpaceTheme(projectState.modelSpaceTheme);
    updateUI();
    render();
}

function setModelSpaceLabelsVisible(isVisible) {
    projectState.modelSpaceLabelsVisible = Boolean(isVisible);
    if (!projectState.modelSpaceLabelsVisible) {
        projectState.modelSpaceLabelsMenuOpen = false;
    }
    persistModelSpaceLabelsVisible(projectState.modelSpaceLabelsVisible);
    updateUI();
    render();
}

function setModelSpaceLabelsMenuOpen(isOpen) {
    projectState.modelSpaceLabelsMenuOpen = Boolean(isOpen);
    if (projectState.modelSpaceLabelsMenuOpen) {
        projectState.modelSpaceElementsMenuOpen = false;
    }
    renderModelSpaceElementsMenu();
    renderModelSpaceLabelsMenu();
}

function closeModelSpaceLabelsMenu() {
    if (!projectState.modelSpaceLabelsMenuOpen) {
        return false;
    }

    setModelSpaceLabelsMenuOpen(false);
    return true;
}

function pruneHiddenSelectedElements({ shouldRender = true } = {}) {
    const nextDescriptors = getSelectedElementDescriptors().filter((descriptor) => isModelSpaceElementTypeVisible(descriptor.type));
    if (nextDescriptors.length === getSelectedElementDescriptors().length) {
        return false;
    }

    setSelectedElementDescriptors(nextDescriptors, { shouldRender });
    return true;
}

function getModelSpaceElementVisibilityState(filters = projectState.modelSpaceElementFilters) {
    const normalizedFilters = normalizeModelSpaceElementFilters(filters);
    const visibleCount = MODEL_SPACE_ELEMENT_FILTER_TYPES.reduce((count, type) => count + (normalizedFilters[type] ? 1 : 0), 0);
    return {
        visibleCount,
        allVisible: visibleCount === MODEL_SPACE_ELEMENT_FILTER_TYPES.length,
        anyVisible: visibleCount > 0
    };
}

function setAllModelSpaceElementsVisible(isVisible) {
    const nextValue = Boolean(isVisible);
    projectState.modelSpaceElementFilters = normalizeModelSpaceElementFilters(
        MODEL_SPACE_ELEMENT_FILTER_TYPES.reduce((filters, type) => {
            filters[type] = nextValue;
            return filters;
        }, {})
    );
    persistModelSpaceElementFilters(projectState.modelSpaceElementFilters);
    closeOverlapPicker();
    updateUI();
    render();
}

function setModelSpaceElementsMenuOpen(isOpen) {
    projectState.modelSpaceElementsMenuOpen = Boolean(isOpen);
    if (projectState.modelSpaceElementsMenuOpen) {
        projectState.modelSpaceLabelsMenuOpen = false;
    }
    renderModelSpaceLabelsMenu();
    renderModelSpaceElementsMenu();
}

function closeModelSpaceElementsMenu() {
    if (!projectState.modelSpaceElementsMenuOpen) {
        return false;
    }

    setModelSpaceElementsMenuOpen(false);
    return true;
}

function setModelSpaceElementFilterVisible(type, isVisible) {
    if (!MODEL_SPACE_ELEMENT_FILTER_TYPES.includes(type)) {
        return;
    }

    projectState.modelSpaceElementFilters = normalizeModelSpaceElementFilters({
        ...projectState.modelSpaceElementFilters,
        [type]: Boolean(isVisible)
    });
    persistModelSpaceElementFilters(projectState.modelSpaceElementFilters);
    closeOverlapPicker();
    updateUI();
    render();
}

function isModelSpaceElementTypeVisible(type) {
    const normalizedType = normalizeSelectedElementType(type);
    const filterType = normalizedType === "hole" ? "slab" : normalizedType;
    if (!MODEL_SPACE_ELEMENT_FILTER_TYPES.includes(filterType)) {
        return true;
    }

    return normalizeModelSpaceElementFilters(projectState.modelSpaceElementFilters)[filterType] !== false;
}

function setModelSpaceLabelFilterVisible(type, isVisible) {
    if (!MODEL_SPACE_LABEL_FILTER_TYPES.includes(type)) {
        return;
    }

    projectState.modelSpaceLabelFilters = normalizeModelSpaceLabelFilters({
        ...projectState.modelSpaceLabelFilters,
        [type]: Boolean(isVisible)
    });
    persistModelSpaceLabelFilters(projectState.modelSpaceLabelFilters);
    renderModelSpaceLabelsMenu();
    render();
}

function isModelSpaceLabelTypeVisible(type) {
    return normalizeModelSpaceLabelFilters(projectState.modelSpaceLabelFilters)[type] !== false;
}

function getModelSpaceLabelFilterLabel(type) {
    return translate(
        type === "column"
            ? "workspace.labelFilterColumn"
            : type === "beam"
                ? "workspace.labelFilterBeam"
                : type === "wall"
                    ? "workspace.labelFilterWall"
                    : type === "foundation"
                        ? "workspace.labelFilterFoundation"
                        : "workspace.labelFilterSlab"
    );
}

function getModelSpaceElementFilterLabel(type) {
    return getModelSpaceLabelFilterLabel(type);
}

function setModelSpaceSteelVisible(isVisible) {
    projectState.modelSpaceSteelVisible = Boolean(isVisible);
    persistModelSpaceSteelVisible(projectState.modelSpaceSteelVisible);
    updateUI();
    render();
}

function setSidebarMode(mode) {
    const normalizedMode = mode === "quantities" ? "export" : mode;
    projectState.sidebarMode = ["manage", "system", "frame", "slab", "wall", "foundation", "export"].includes(normalizedMode) ? normalizedMode : "system";
    clearPendingSlabInsertion();
    clearBeamBreakMode({ shouldRender: false });
    closeOverlapPicker();
    syncModeAwareToolIcons();

    if (isModelSidebarMode(projectState.sidebarMode)) {
        projectState.lastModelSidebarMode = projectState.sidebarMode;
    }

    dom.sidebarModeButtons.forEach((button) => {
        const isActive = button.dataset.sidebarMode === projectState.sidebarMode;
        button.classList.toggle("is-active", isActive);
        button.setAttribute("aria-pressed", String(isActive));
    });

    const isManageMode = projectState.sidebarMode === "manage";
    const isSystemMode = projectState.sidebarMode === "system";
    const isExportMode = projectState.sidebarMode === "export";
    const isModelMode = MODEL_SIDEBAR_MODES.includes(projectState.sidebarMode);
    const hasAuthenticatedUser = Boolean(projectState.authenticatedUser?.id);

    dom.projectSection.hidden = !isManageMode;
    dom.systemSection.hidden = !isSystemMode;
    dom.toolsSection.hidden = !isModelMode;
    dom.levelsSection.hidden = !isSystemMode;
    if (dom.exportDockSection) {
        dom.exportDockSection.hidden = !isExportMode;
    }

    if (isManageMode && !hasAuthenticatedUser && !projectState.billingLoading) {
        void refreshBillingStatus({ silent: true });
    }

    if (isManageMode && hasAuthenticatedUser && !projectState.projectListLoaded && !projectState.projectListLoading) {
        void refreshProjectList({ silent: true });
    }

    if (!isModelMode) {
        projectState.tool = "";
        projectState.firstNode = null;
        clearSelectedElements({ shouldRender: false });

        dom.toolButtons.forEach((button) => {
            button.hidden = true;
            button.disabled = true;
            button.classList.remove("active-tool");
            button.setAttribute("aria-pressed", "false");
        });

        syncWorkspaceQuickToolButtons();
        renderSelectedElementIndicator();
        renderQuantitiesSection();
        renderInsertPropertiesPanel();
        renderSectionPreviewPanel();
        updateCanvasCursor();
        if (isManageMode) {
            renderProjectPicker();
        }
        notifyWorkspaceCommandModeChange();
        render();
        return;
    }

    dom.toolsPanelTitle.textContent = projectState.sidebarMode === "frame"
        ? translate("tools.title.frame")
        : projectState.sidebarMode === "slab"
            ? translate("tools.title.slab")
            : projectState.sidebarMode === "foundation"
                ? translate("tools.title.foundation")
                : translate("tools.title.wall");

    dom.toolButtons.forEach((button) => {
        const modes = String(button.dataset.toolModes || "")
            .split(/\s+/)
            .filter(Boolean);
        const isVisible = modes.includes(projectState.sidebarMode);
        button.hidden = !isVisible;
        button.disabled = !isVisible;
    });
    syncSidebarToolButtons();
    syncWorkspaceQuickToolButtons();

    const allowedTools = SIDEBAR_TOOLSETS[projectState.sidebarMode] || [];
    if (!allowedTools.includes(projectState.tool)) {
        setTool(SIDEBAR_DEFAULT_TOOLS[projectState.sidebarMode] || allowedTools[0]);
        return;
    }

    updateCanvasCursor();
    renderQuantitiesSection();
    renderInsertPropertiesPanel();
    renderSectionPreviewPanel();
    notifyWorkspaceCommandModeChange();
    render();
}

function clearPendingSlabInsertion({ shouldRender = false } = {}) {
    const hadPendingVertices = (projectState.pendingSlabVertices?.length || 0) > 0 || Boolean(projectState.slabHoverNode);
    projectState.pendingSlabVertices = [];
    projectState.slabHoverNode = null;
    if (shouldRender && hadPendingVertices) {
        render();
    }
}

function getActiveLevel() {
    return projectState.levels.find((level) => level.id === projectState.activeLevelId);
}

function getActiveLevelIndex() {
    return projectState.levels.findIndex((level) => level.id === projectState.activeLevelId);
}

function stepActiveLevel(delta) {
    const activeIndex = getActiveLevelIndex();
    if (activeIndex < 0) {
        return;
    }

    const targetLevel = projectState.levels[activeIndex + delta];
    if (targetLevel) {
        setActiveLevel(targetLevel.id);
    }
}

function setActiveLevel(levelId) {
    if (!projectState.levels.some((level) => level.id === levelId)) {
        return;
    }

    projectState.activeLevelId = levelId;
    projectState.firstNode = null;
    clearSelectedElements({ shouldRender: false });
    updateUI();
    render();
}

function setOutputMode(mode) {
    projectState.outputMode = ["frame", "slab", "column", "wall"].includes(mode) ? mode : "frame";

    dom.outputModeButtons.forEach((button) => {
        const isActive = button.dataset.outputMode === projectState.outputMode;
        button.classList.toggle("is-active", isActive);
        button.setAttribute("aria-pressed", String(isActive));
    });

    updateUI();
}

function setGridAxisLocationMode(mode) {
    const nextMode = normalizeGridAxisLocationMode(mode);
    if (projectState.gridAxisLocationMode === nextMode) {
        return;
    }

    projectState.gridAxisLocationMode = nextMode;
    updateUI();
    render();
}

function syncOutputSelectionFromControl() {
    if (projectState.outputMode === "frame") {
        projectState.frameExportSelection = dom.exportAxisSelect.value;
        return;
    }

    if (projectState.outputMode === "slab" && isAllSlabLevelsSelection(dom.exportAxisSelect.value)) {
        projectState.slabExportLevelId = SLAB_EXPORT_ALL_LEVELS_ID;
        return;
    }

    const [, rawLevelId] = dom.exportAxisSelect.value.split("|");
    const levelId = Number.parseInt(rawLevelId, 10);
    if (projectState.outputMode === "slab") {
        projectState.slabExportLevelId = levelId;
    } else if (projectState.outputMode === "column") {
        projectState.columnExportLevelId = levelId;
    } else if (projectState.outputMode === "wall") {
        projectState.wallExportLevelId = levelId;
    }
}

function setSystemModalTab(tab) {
    projectState.systemModalTab = tab === "levels" ? "levels" : "grid";

    dom.systemTabButtons.forEach((button) => {
        const isActive = button.dataset.systemTab === projectState.systemModalTab;
        button.classList.toggle("is-active", isActive);
        button.setAttribute("aria-selected", String(isActive));
    });

    const showingGrid = projectState.systemModalTab === "grid";
    const showingLevels = projectState.systemModalTab === "levels";
    dom.systemPanelGrid.classList.toggle("is-active", showingGrid);
    dom.systemPanelGrid.hidden = !showingGrid;
    dom.systemPanelLevels.classList.toggle("is-active", showingLevels);
    dom.systemPanelLevels.hidden = !showingLevels;
}

