function drawSelectionRect(x, y, width, height, palette, padding = 4) {
    ctx.save();

    const radius = Math.max(2, padding - 1);
    const glowBlur = palette.selectionGlowBlur ?? 4;
    const glowWidth = palette.selectionGlowWidth ?? 4;
    const coreWidth = palette.selectionStrokeWidth ?? 1.5;

    // Halo de selección
    ctx.beginPath();
    addRoundedRectPath(ctx, x - padding, y - padding, width + padding * 2, height + padding * 2, radius);
    ctx.fillStyle = palette.selectionFill;
    ctx.strokeStyle = palette.selectionGlow;
    ctx.lineWidth = glowWidth;
    ctx.shadowColor = palette.selectionGlow;
    ctx.shadowBlur = glowBlur;
    ctx.fill();
    ctx.stroke();

    // Outline sólido y técnico
    ctx.beginPath();
    addRoundedRectPath(ctx, x - padding, y - padding, width + padding * 2, height + padding * 2, radius);
    ctx.strokeStyle = palette.selectionStroke;
    ctx.lineWidth = coreWidth;
    ctx.shadowBlur = 0;
    ctx.stroke();

    ctx.restore();
}

function drawSelectionSegment(x1, y1, x2, y2, lineWidth, palette) {
    ctx.save();

    const glowBlur = palette.selectionGlowBlur ?? 4;
    const glowWidth = palette.selectionGlowWidth ?? 4;
    const coreWidth = palette.selectionStrokeWidth ?? 1.5;

    // Halo suave de selección
    ctx.strokeStyle = palette.selectionGlow;
    ctx.lineWidth = lineWidth + glowWidth;
    ctx.lineCap = "butt";
    ctx.shadowColor = palette.selectionGlow;
    ctx.shadowBlur = glowBlur;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();

    // Outline sólido preciso
    ctx.strokeStyle = palette.selectionStroke;
    ctx.lineWidth = Math.max(coreWidth, lineWidth + 1);
    ctx.lineCap = "butt";
    ctx.shadowBlur = 0;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();

    ctx.restore();
}

function addClosedCanvasPolygonPath(context, vertices, toCanvasX = (value) => value, toCanvasY = (value) => value) {
    if (!context || !Array.isArray(vertices) || vertices.length < 2) {
        return false;
    }

    context.beginPath();
    context.moveTo(toCanvasX(vertices[0].x), toCanvasY(vertices[0].y));
    for (let index = 1; index < vertices.length; index += 1) {
        context.lineTo(toCanvasX(vertices[index].x), toCanvasY(vertices[index].y));
    }
    context.closePath();
    return true;
}

function drawSelectionPolygon(vertices, palette, toCanvasX = (value) => value, toCanvasY = (value) => value) {
    if (!addClosedCanvasPolygonPath(ctx, vertices, toCanvasX, toCanvasY)) {
        return;
    }

    const glowBlur = palette.selectionGlowBlur ?? 4;
    const glowWidth = palette.selectionGlowWidth ?? 4;
    const coreWidth = palette.selectionStrokeWidth ?? 1.5;

    ctx.save();
    ctx.fillStyle = palette.selectionFill;
    ctx.strokeStyle = palette.selectionGlow;
    ctx.lineWidth = glowWidth;
    ctx.shadowColor = palette.selectionGlow;
    ctx.shadowBlur = glowBlur;
    ctx.fill();
    ctx.stroke();

    addClosedCanvasPolygonPath(ctx, vertices, toCanvasX, toCanvasY);
    ctx.strokeStyle = palette.selectionStroke;
    ctx.lineWidth = coreWidth;
    ctx.shadowBlur = 0;
    ctx.stroke();
    ctx.restore();
}

function render() {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, dom.canvas.width, dom.canvas.height);
    ctx.save();
    ctx.setTransform(viewport.zoom, 0, 0, viewport.zoom, viewport.offsetX, viewport.offsetY);
    drawGrid();

    const level = getActiveLevel();
    if (!level) {
        ctx.restore();
        return;
    }

    drawSlabs(level);
    drawFoundations(level);
    drawWalls(level);
    drawBeams(level);
    drawColumns(level);
    if (projectState.modelSpaceLabelsVisible) {
        drawPlanElementNames(level);
    }
    drawPendingSlabPlacement();
    ctx.restore();
    drawCanvasSelectionMarquee();
    updateCanvasCursor();
}

function getGridBadgeRadius(label) {
    return Math.max(11, Math.ceil(ctx.measureText(label).width / 2) + 6);
}

function drawGridBadge(x, y, label, radius, palette) {
    ctx.save();
    ctx.setLineDash([]);
    ctx.fillStyle = palette.gridBadgeFill;
    ctx.strokeStyle = palette.gridBadgeStroke;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = palette.gridText;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(label, x, y + 0.5);
    ctx.restore();
}

function getScreenLockedZoomScale(zoomScale = 1) {
    return Number.isFinite(zoomScale) && zoomScale > 0 ? zoomScale : 1;
}

function formatGridSpacingValue(value) {
    if (!Number.isFinite(value)) {
        return "";
    }

    return `${value.toFixed(2).replace(/\.?0+$/, "")}m`;
}

function getGridAxisLocationDisplayValue(axisValues, index, value, mode = projectState.gridAxisLocationMode) {
    if (normalizeGridAxisLocationMode(mode) !== "relative") {
        return formatGridSpacingValue(value);
    }

    if (index <= 0) {
        return formatGridSpacingValue(value);
    }

    const previousValue = Array.isArray(axisValues) ? axisValues[index - 1] : Number.NaN;
    if (!Number.isFinite(previousValue)) {
        return formatGridSpacingValue(value);
    }

    return `+${formatGridSpacingValue(value - previousValue)}`;
}

function getGridAxisAbsoluteInputValue(axisValues, inputValue, mode = projectState.gridAxisLocationMode) {
    const numericValue = Number.parseFloat(String(inputValue ?? "").replace(",", "."));
    if (!Number.isFinite(numericValue)) {
        return Number.NaN;
    }

    if (normalizeGridAxisLocationMode(mode) !== "relative" || !Array.isArray(axisValues) || axisValues.length === 0) {
        return numericValue;
    }

    if (numericValue <= 0) {
        return Number.NaN;
    }

    const previousValue = axisValues[axisValues.length - 1];
    return Number.isFinite(previousValue) ? previousValue + numericValue : numericValue;
}

function drawGridSpacingLabel(x, y, label, palette) {
    if (!label) {
        return;
    }

    ctx.save();
    ctx.setLineDash([]);
    ctx.font = '600 11px "Segoe UI", sans-serif';
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    const textWidth = ctx.measureText(label).width;
    const labelWidth = Math.max(textWidth + 14, 28);
    const labelHeight = 18;

    ctx.beginPath();
    addRoundedRectPath(ctx, x - labelWidth / 2, y - labelHeight / 2, labelWidth, labelHeight, labelHeight / 2);
    ctx.fillStyle = palette.gridDimensionFill;
    ctx.strokeStyle = palette.gridDimensionStroke;
    ctx.lineWidth = 1;
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = palette.gridDimensionText;
    ctx.fillText(label, x, y + 0.5);
    ctx.restore();
}

function drawGridSpacingDimensions(sortedXAxes, sortedYAxes, horizontalLineEndX, verticalLineEndY, palette, mode = projectState.gridAxisLocationMode) {
    const minimumScreenSpan = 24;
    const tickSize = 4;
    const horizontalBaselineY = verticalLineEndY + 22;
    const horizontalLabelY = horizontalBaselineY + 12;
    const verticalBaselineX = horizontalLineEndX + 24;
    const verticalLabelX = verticalBaselineX + 20;

    ctx.save();
    ctx.setLineDash([]);
    ctx.strokeStyle = palette.gridDimensionStroke;
    ctx.lineWidth = 1;

    for (let index = 1; index < sortedXAxes.length; index += 1) {
        const startX = margin + sortedXAxes[index - 1] * scale;
        const endX = margin + sortedXAxes[index] * scale;
        if ((endX - startX) * viewport.zoom < minimumScreenSpan) {
            continue;
        }

        ctx.beginPath();
        ctx.moveTo(startX, verticalLineEndY);
        ctx.lineTo(startX, horizontalBaselineY);
        ctx.moveTo(endX, verticalLineEndY);
        ctx.lineTo(endX, horizontalBaselineY);
        ctx.moveTo(startX, horizontalBaselineY);
        ctx.lineTo(endX, horizontalBaselineY);
        ctx.moveTo(startX, horizontalBaselineY - tickSize);
        ctx.lineTo(startX, horizontalBaselineY + tickSize);
        ctx.moveTo(endX, horizontalBaselineY - tickSize);
        ctx.lineTo(endX, horizontalBaselineY + tickSize);
        ctx.stroke();

        const labelValue = mode === "relative"
            ? sortedXAxes[index] - sortedXAxes[index - 1]
            : sortedXAxes[index];
        drawGridSpacingLabel((startX + endX) / 2, horizontalLabelY, formatGridSpacingValue(labelValue), palette);
    }

    for (let index = 1; index < sortedYAxes.length; index += 1) {
        const startY = margin + sortedYAxes[index - 1] * scale;
        const endY = margin + sortedYAxes[index] * scale;
        if ((endY - startY) * viewport.zoom < minimumScreenSpan) {
            continue;
        }

        ctx.beginPath();
        ctx.moveTo(horizontalLineEndX, startY);
        ctx.lineTo(verticalBaselineX, startY);
        ctx.moveTo(horizontalLineEndX, endY);
        ctx.lineTo(verticalBaselineX, endY);
        ctx.moveTo(verticalBaselineX, startY);
        ctx.lineTo(verticalBaselineX, endY);
        ctx.moveTo(verticalBaselineX - tickSize, startY);
        ctx.lineTo(verticalBaselineX + tickSize, startY);
        ctx.moveTo(verticalBaselineX - tickSize, endY);
        ctx.lineTo(verticalBaselineX + tickSize, endY);
        ctx.stroke();

        const labelValue = mode === "relative"
            ? sortedYAxes[index] - sortedYAxes[index - 1]
            : sortedYAxes[index];
        drawGridSpacingLabel(verticalLabelX, (startY + endY) / 2, formatGridSpacingValue(labelValue), palette);
    }

    ctx.restore();
}

function drawReferenceGridAxes(horizontalLineEndX, verticalLineEndY, palette) {
    const referenceXAxes = getReferenceAxisEntries("x");
    const referenceYAxes = getReferenceAxisEntries("y");
    if (!referenceXAxes.length && !referenceYAxes.length) {
        return;
    }

    ctx.save();
    ctx.strokeStyle = palette.referenceGridStroke;
    ctx.lineWidth = 0.9;
    ctx.setLineDash([4, 7]);
    ctx.font = '10px "Segoe UI", sans-serif';

    const topBadgeCenterY = 38;
    const leftBadgeCenterX = 38;
    const badgeGap = 4;
    const badgePalette = {
        gridBadgeFill: palette.referenceGridBadgeFill,
        gridBadgeStroke: palette.referenceGridBadgeStroke,
        gridText: palette.referenceGridText
    };

    referenceXAxes.forEach((entry) => {
        const px = margin + entry.value * scale;
        const badgeRadius = Math.max(8, Math.min(Math.ceil(ctx.measureText(entry.label).width / 2) + 4, 16));
        ctx.beginPath();
        ctx.moveTo(px, topBadgeCenterY + badgeRadius + badgeGap);
        ctx.lineTo(px, verticalLineEndY);
        ctx.stroke();
        drawGridBadge(px, topBadgeCenterY, entry.label, badgeRadius, badgePalette);
    });

    referenceYAxes.forEach((entry) => {
        const py = margin + entry.value * scale;
        const badgeRadius = Math.max(8, Math.min(Math.ceil(ctx.measureText(entry.label).width / 2) + 4, 16));
        ctx.beginPath();
        ctx.moveTo(leftBadgeCenterX + badgeRadius + badgeGap, py);
        ctx.lineTo(horizontalLineEndX, py);
        ctx.stroke();
        drawGridBadge(leftBadgeCenterX, py, entry.label, badgeRadius, badgePalette);
    });

    ctx.restore();
}

function getGridLineExtension(axisValues) {
    const sortedValues = [...axisValues].sort((a, b) => a - b);
    if (sortedValues.length < 2) {
        return 0.6;
    }

    let minGap = Number.POSITIVE_INFINITY;
    for (let index = 1; index < sortedValues.length; index += 1) {
        const gap = sortedValues[index] - sortedValues[index - 1];
        if (gap > EDGE_TOLERANCE) {
            minGap = Math.min(minGap, gap);
        }
    }

    if (!Number.isFinite(minGap)) {
        return 0.6;
    }

    return Math.max(0.25, Math.min(minGap * 0.15, 0.75));
}

function drawGrid() {
    ctx.save();
    const palette = getModelSpacePalette();
    const sortedXAxes = [...projectState.axes.x].sort((a, b) => a - b);
    const sortedYAxes = [...projectState.axes.y].sort((a, b) => a - b);
    const combinedXAxes = getCombinedAxisValues("x");
    const combinedYAxes = getCombinedAxisValues("y");
    const maxX = combinedXAxes[combinedXAxes.length - 1] ?? 0;
    const maxY = combinedYAxes[combinedYAxes.length - 1] ?? 0;
    const horizontalLineEndX = margin + (maxX + getGridLineExtension(combinedXAxes)) * scale;
    const verticalLineEndY = margin + (maxY + getGridLineExtension(combinedYAxes)) * scale;
    ctx.strokeStyle = palette.gridStroke;
    ctx.fillStyle = palette.gridText;
    ctx.lineWidth = 1;
    ctx.setLineDash([8, 6]);
    ctx.font = '12px "Segoe UI", sans-serif';
    const topBadgeCenterY = 22;
    const leftBadgeCenterX = 20;
    const badgeGap = 5;

    projectState.axes.x.forEach((value, index) => {
        const px = margin + value * scale;
        const label = getAxisLabelForIndex("x", index);
        const badgeRadius = getGridBadgeRadius(label);
        ctx.beginPath();
        ctx.moveTo(px, topBadgeCenterY + badgeRadius + badgeGap);
        ctx.lineTo(px, verticalLineEndY);
        ctx.stroke();
        drawGridBadge(px, topBadgeCenterY, label, badgeRadius, palette);
    });

    projectState.axes.y.forEach((value, index) => {
        const py = margin + value * scale;
        const label = getAxisLabelForIndex("y", index);
        const badgeRadius = getGridBadgeRadius(label);
        ctx.beginPath();
        ctx.moveTo(leftBadgeCenterX + badgeRadius + badgeGap, py);
        ctx.lineTo(horizontalLineEndX, py);
        ctx.stroke();
        drawGridBadge(leftBadgeCenterX, py, label, badgeRadius, palette);
    });

    drawReferenceGridAxes(horizontalLineEndX, verticalLineEndY, palette);
    // The model view always shows inter-axis spacing relative to the previous axis.
    drawGridSpacingDimensions(sortedXAxes, sortedYAxes, horizontalLineEndX, verticalLineEndY, palette, "relative");

    ctx.restore();
}

function getCanvasEntityNameTagLayout(context, label, centerX, centerY, zoomScale = 1) {
    const normalizedLabel = normalizeTextValue(label);
    if (!normalizedLabel) {
        return null;
    }

    const safeZoomScale = getScreenLockedZoomScale(zoomScale);
    const fontSize = 10 / safeZoomScale;

    context.save();
    context.font = `600 ${fontSize}px "Segoe UI", sans-serif`;
    const textWidth = context.measureText(normalizedLabel).width;
    context.restore();

    const tagWidth = Math.max(textWidth + (14 / safeZoomScale), 26 / safeZoomScale);
    const tagHeight = 18 / safeZoomScale;
    const tagX = centerX - tagWidth / 2;
    const tagY = centerY - tagHeight / 2;

    return {
        label: normalizedLabel,
        centerX,
        centerY,
        tagWidth,
        tagHeight,
        tagX,
        tagY,
        font: `600 ${fontSize}px "Segoe UI", sans-serif`,
        lineWidth: 1.2 / safeZoomScale,
        textOffsetY: 0.5 / safeZoomScale,
        rect: {
            left: tagX,
            top: tagY,
            right: tagX + tagWidth,
            bottom: tagY + tagHeight
        }
    };
}

function drawCanvasEntityNameTag(context, label, centerX, centerY, palette, layout = null, zoomScale = 1) {
    const resolvedLayout = layout || getCanvasEntityNameTagLayout(context, label, centerX, centerY, zoomScale);
    if (!resolvedLayout) {
        return;
    }

    context.save();
    context.font = resolvedLayout.font || `600 ${10 / getScreenLockedZoomScale(zoomScale)}px "Segoe UI", sans-serif`;
    context.textAlign = "center";
    context.textBaseline = "middle";

    context.fillStyle = palette.slabBadgeFill;
    context.strokeStyle = palette.slabBadgeStroke;
    context.lineWidth = resolvedLayout.lineWidth || (1.2 / getScreenLockedZoomScale(zoomScale));
    context.beginPath();
    addRoundedRectPath(context, resolvedLayout.tagX, resolvedLayout.tagY, resolvedLayout.tagWidth, resolvedLayout.tagHeight, resolvedLayout.tagHeight / 2);
    context.fill();
    context.stroke();

    context.fillStyle = palette.slabBadgeText;
    context.fillText(resolvedLayout.label, resolvedLayout.centerX, resolvedLayout.centerY + (resolvedLayout.textOffsetY || (0.5 / getScreenLockedZoomScale(zoomScale))));
    context.restore();
}

function getCanvasSegmentLabelPoint(x1, y1, x2, y2, offset) {
    const centerX = margin + ((x1 + x2) / 2) * scale;
    const centerY = margin + ((y1 + y2) / 2) * scale;

    if (Math.abs(x2 - x1) >= Math.abs(y2 - y1)) {
        return { x: centerX, y: centerY - offset };
    }

    return { x: centerX + offset, y: centerY };
}

function getCanvasSegmentLabelCandidates(x1, y1, x2, y2, offset) {
    const centerX = margin + ((x1 + x2) / 2) * scale;
    const centerY = margin + ((y1 + y2) / 2) * scale;
    const dx = (x2 - x1) * scale;
    const dy = (y2 - y1) * scale;
    const alongOffset = Math.min(Math.max(Math.hypot(dx, dy) * 0.18, 18), 42);

    if (Math.abs(dx) >= Math.abs(dy)) {
        return [
            { x: centerX, y: centerY - offset },
            { x: centerX, y: centerY + offset },
            { x: centerX - alongOffset, y: centerY - offset },
            { x: centerX + alongOffset, y: centerY - offset },
            { x: centerX - alongOffset, y: centerY + offset },
            { x: centerX + alongOffset, y: centerY + offset }
        ];
    }

    return [
        { x: centerX + offset, y: centerY },
        { x: centerX - offset, y: centerY },
        { x: centerX + offset, y: centerY - alongOffset },
        { x: centerX + offset, y: centerY + alongOffset },
        { x: centerX - offset, y: centerY - alongOffset },
        { x: centerX - offset, y: centerY + alongOffset }
    ];
}

function getCanvasColumnLabelCandidates(column) {
    const footprint = getColumnFootprint(column);
    const centerX = margin + column.x * scale;
    const centerY = margin + column.y * scale;
    const verticalOffset = Math.max((footprint.height * scale) / 2 + 12, 16);
    const horizontalOffset = Math.max((footprint.width * scale) / 2 + 16, 18);

    return [
        { x: centerX, y: centerY - verticalOffset },
        { x: centerX + horizontalOffset, y: centerY },
        { x: centerX - horizontalOffset, y: centerY },
        { x: centerX, y: centerY + verticalOffset },
        { x: centerX + horizontalOffset * 0.8, y: centerY - verticalOffset * 0.82 },
        { x: centerX - horizontalOffset * 0.8, y: centerY - verticalOffset * 0.82 },
        { x: centerX + horizontalOffset * 0.8, y: centerY + verticalOffset * 0.82 },
        { x: centerX - horizontalOffset * 0.8, y: centerY + verticalOffset * 0.82 }
    ];
}

function getCanvasSlabLabelCandidates(slab) {
    const bounds = normalizeSlabBounds(slab);
    const centroid = getSlabCentroid(slab);
    const x = margin + bounds.x1 * scale;
    const y = margin + bounds.y1 * scale;
    const width = (bounds.x2 - bounds.x1) * scale;
    const height = (bounds.y2 - bounds.y1) * scale;
    const centerX = margin + centroid.x * scale;
    const centerY = margin + centroid.y * scale;
    const insetX = Math.max(Math.min(width * 0.18, 24), 14);
    const insetY = Math.max(Math.min(height * 0.18, 24), 14);

    return [
        { x: centerX, y: centerY },
        { x: centerX, y: y + insetY },
        { x: centerX, y: y + height - insetY },
        { x: x + insetX, y: centerY },
        { x: x + width - insetX, y: centerY },
        { x: x + insetX, y: y + insetY },
        { x: x + width - insetX, y: y + insetY },
        { x: x + insetX, y: y + height - insetY },
        { x: x + width - insetX, y: y + height - insetY }
    ];
}

function getCanvasFoundationLabelCandidates(foundation) {
    const normalizedFoundation = normalizeFoundation(foundation);
    const bounds = normalizeFoundationVertices(normalizedFoundation);
    const polygonBounds = getPolygonBounds(bounds);
    const centerX = margin + normalizedFoundation.x * scale;
    const centerY = margin + normalizedFoundation.y * scale;
    const width = Math.max((polygonBounds.x2 - polygonBounds.x1) * scale, 1);
    const height = Math.max((polygonBounds.y2 - polygonBounds.y1) * scale, 1);
    const insetX = Math.max(Math.min(width * 0.18, 24), 14);
    const insetY = Math.max(Math.min(height * 0.18, 24), 14);

    return [
        { x: centerX, y: centerY },
        { x: centerX, y: centerY - insetY },
        { x: centerX, y: centerY + insetY },
        { x: centerX - insetX, y: centerY },
        { x: centerX + insetX, y: centerY },
        { x: centerX - insetX, y: centerY - insetY },
        { x: centerX + insetX, y: centerY - insetY },
        { x: centerX - insetX, y: centerY + insetY },
        { x: centerX + insetX, y: centerY + insetY }
    ];
}

function getLabelRectOverlapArea(rectA, rectB, padding = 6) {
    const left = Math.max(rectA.left - padding, rectB.left - padding);
    const top = Math.max(rectA.top - padding, rectB.top - padding);
    const right = Math.min(rectA.right + padding, rectB.right + padding);
    const bottom = Math.min(rectA.bottom + padding, rectB.bottom + padding);

    if (right <= left || bottom <= top) {
        return 0;
    }

    return (right - left) * (bottom - top);
}

function dedupeLabelCandidates(candidates) {
    const seen = new Set();
    return candidates.filter((candidate) => {
        const key = `${Math.round(candidate.x)}|${Math.round(candidate.y)}`;
        if (seen.has(key)) {
            return false;
        }

        seen.add(key);
        return true;
    });
}

function getPlanElementNameEntries(level, palette, zoomScale = 1) {
    const safeZoomScale = getScreenLockedZoomScale(zoomScale);
    const entries = [];

    if (isModelSpaceElementTypeVisible("wall") && isModelSpaceLabelTypeVisible("wall")) {
        (level.walls || []).forEach((wall) => {
            const name = normalizeTextValue(wall.name);
            if (!name) {
                return;
            }

            entries.push({
                priority: 0,
                label: name,
                candidates: dedupeLabelCandidates(getCanvasSegmentLabelCandidates(
                    wall.x1,
                    wall.y1,
                    wall.x2,
                    wall.y2,
                    Math.max(((wall.b || DEFAULT_WALL_THICKNESS) * scale) / 2 + 12, 16)
                )),
                measure: (candidate) => getCanvasEntityNameTagLayout(ctx, name, candidate.x, candidate.y, safeZoomScale),
                draw: (layout) => drawCanvasEntityNameTag(ctx, name, layout.centerX, layout.centerY, palette, layout, safeZoomScale)
            });
        });
    }

    if (isModelSpaceElementTypeVisible("beam") && isModelSpaceLabelTypeVisible("beam")) {
        (level.beams || []).forEach((beam) => {
            const name = normalizeTextValue(beam.name);
            if (!name) {
                return;
            }

            entries.push({
                priority: 0,
                label: name,
                candidates: dedupeLabelCandidates(getCanvasSegmentLabelCandidates(
                    beam.x1,
                    beam.y1,
                    beam.x2,
                    beam.y2,
                    Math.max(((beam.b || 0.3) * scale) / 2 + 12, 16)
                )),
                measure: (candidate) => getCanvasEntityNameTagLayout(ctx, name, candidate.x, candidate.y, safeZoomScale),
                draw: (layout) => drawCanvasEntityNameTag(ctx, name, layout.centerX, layout.centerY, palette, layout, safeZoomScale)
            });
        });
    }

    if (isModelSpaceElementTypeVisible("column") && isModelSpaceLabelTypeVisible("column")) {
        (level.columns || []).forEach((column) => {
            const name = normalizeTextValue(column.name);
            if (!name) {
                return;
            }

            entries.push({
                priority: 1,
                label: name,
                candidates: dedupeLabelCandidates(getCanvasColumnLabelCandidates(column)),
                measure: (candidate) => getCanvasEntityNameTagLayout(ctx, name, candidate.x, candidate.y, safeZoomScale),
                draw: (layout) => drawCanvasEntityNameTag(ctx, name, layout.centerX, layout.centerY, palette, layout, safeZoomScale)
            });
        });
    }

    if (isModelSpaceElementTypeVisible("foundation") && isModelSpaceLabelTypeVisible("foundation")) {
        (level.foundations || []).forEach((foundation) => {
            const name = normalizeTextValue(foundation.name) || getSmartEntityName("foundation", foundation);
            if (!name) {
                return;
            }

            entries.push({
                priority: 1,
                label: name,
                candidates: dedupeLabelCandidates(getCanvasFoundationLabelCandidates(foundation)),
                measure: (candidate) => getCanvasEntityNameTagLayout(ctx, name, candidate.x, candidate.y, safeZoomScale),
                draw: (layout) => drawCanvasEntityNameTag(ctx, name, layout.centerX, layout.centerY, palette, layout, safeZoomScale)
            });
        });
    }

    if (isModelSpaceElementTypeVisible("slab") && isModelSpaceLabelTypeVisible("slab")) {
        (level.slabs || []).forEach((slab) => {
            const bounds = normalizeSlabBounds(slab);
            const centroid = getSlabCentroid(slab);
            const rawLabel = slab.name
                ? String(slab.name).slice(0, 4)
                : (slab.type === "lightened" ? "LA" : isStairSlabType(slab.type) ? "LE" : "LS");
            if (!rawLabel) {
                return;
            }

            const x = margin + bounds.x1 * scale;
            const y = margin + bounds.y1 * scale;
            const width = (bounds.x2 - bounds.x1) * scale;
            const height = (bounds.y2 - bounds.y1) * scale;
            const slabSize = Math.min(width, height);

            entries.push({
                priority: 2,
                label: rawLabel,
                candidates: dedupeLabelCandidates(getCanvasSlabLabelCandidates(slab)),
                measure: (candidate) => getCanvasSlabNameBadgeLayout(rawLabel, candidate.x, candidate.y, slabSize, true, safeZoomScale),
                draw: (layout) => drawCanvasSlabNameBadge(
                    ctx,
                    rawLabel,
                    layout.centerX,
                    layout.centerY,
                    slabSize,
                    {
                        fillStyle: palette.slabBadgeFill,
                        strokeStyle: palette.slabBadgeStroke,
                        textStyle: palette.slabBadgeText
                    },
                    true,
                    layout,
                    safeZoomScale
                )
            });

            if (centroid) {
                entries[entries.length - 1].candidates.unshift({
                    x: margin + centroid.x * scale,
                    y: margin + centroid.y * scale
                });
                entries[entries.length - 1].candidates = dedupeLabelCandidates(entries[entries.length - 1].candidates);
            }
        });
    }

    return entries;
}

function resolvePlanElementNameLayouts(level, palette, zoomScale = 1) {
    const safeZoomScale = getScreenLockedZoomScale(zoomScale);
    const occupiedRects = [];
    const overlapPadding = 6 / safeZoomScale;

    return getPlanElementNameEntries(level, palette, safeZoomScale)
        .map((entry) => {
            const firstLayout = entry.measure(entry.candidates[0] || { x: 0, y: 0 });
            return {
                ...entry,
                estimatedArea: firstLayout?.rect
                    ? (firstLayout.rect.right - firstLayout.rect.left) * (firstLayout.rect.bottom - firstLayout.rect.top)
                    : 0
            };
        })
        .sort((left, right) => (
            left.priority - right.priority
            || right.estimatedArea - left.estimatedArea
            || String(right.label || "").length - String(left.label || "").length
        ))
        .map((entry) => {
            let bestLayout = null;
            let bestScore = Number.POSITIVE_INFINITY;

            entry.candidates.forEach((candidate, index) => {
                const layout = entry.measure(candidate);
                if (!layout?.rect) {
                    return;
                }

                const overlapScore = occupiedRects.reduce((sum, rect) => (
                    sum + getLabelRectOverlapArea(layout.rect, rect, overlapPadding)
                ), 0);
                const distanceScore = Math.hypot(
                    candidate.x - entry.candidates[0].x,
                    candidate.y - entry.candidates[0].y
                ) * safeZoomScale;
                const score = overlapScore * safeZoomScale * safeZoomScale * 1000 + distanceScore + index * 2;

                if (score < bestScore) {
                    bestScore = score;
                    bestLayout = layout;
                }
            });

            if (bestLayout?.rect) {
                occupiedRects.push(bestLayout.rect);
            }

            return bestLayout ? { entry, layout: bestLayout } : null;
        })
        .filter(Boolean);
}

function drawPlanElementNames(level) {
    const palette = getModelSpacePalette();
    resolvePlanElementNameLayouts(level, palette, viewport.zoom).forEach(({ entry, layout }) => {
        entry.draw(layout);
    });
}

function drawColumns(level) {
    if (!isModelSpaceElementTypeVisible("column")) {
        return;
    }

    const palette = getModelSpacePalette();
    level.columns.forEach((column) => {
        const isSelectedBeamNode = projectState.firstNode
            && (projectState.tool === "beam" || projectState.tool === "wall")
            && Math.abs(projectState.firstNode.x - column.x) < 0.01
            && Math.abs(projectState.firstNode.y - column.y) < 0.01;
        const isSelected = isSelectedElement("column", column.id, level.id);
        const footprint = getColumnFootprint(column);
        const width = footprint.width * scale;
        const height = footprint.height * scale;
        const rectX = margin + column.x * scale - width / 2;
        const rectY = margin + column.y * scale - height / 2;

        if (isSelected) {
            drawSelectionRect(rectX, rectY, width, height, palette, 5);
        }

        ctx.fillStyle = isSelectedBeamNode ? palette.nodeSelectedFill : palette.columnFill;
        ctx.strokeStyle = palette.columnStroke;
        ctx.lineWidth = 2;
        ctx.fillRect(
            rectX,
            rectY,
            width,
            height
        );
        ctx.strokeRect(rectX, rectY, width, height);
    });

    if ((projectState.tool === "beam" || projectState.tool === "wall") && projectState.firstNode) {
        const hasColumnAtNode = level.columns.some((column) => (
            Math.abs(column.x - projectState.firstNode.x) < 0.01
            && Math.abs(column.y - projectState.firstNode.y) < 0.01
        ));

        if (!hasColumnAtNode) {
            ctx.save();
            ctx.strokeStyle = palette.nodeSelectedFill;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(
                margin + projectState.firstNode.x * scale,
                margin + projectState.firstNode.y * scale,
                8,
                0,
                Math.PI * 2
            );
            ctx.stroke();
            ctx.restore();
        }
    }
}

function drawWalls(level) {
    if (!isModelSpaceElementTypeVisible("wall")) {
        return;
    }

    const palette = getModelSpacePalette();
    level.walls.forEach((wall) => {
        const normalizedWall = normalizeWall(wall);
        const isSelected = isSelectedElement("wall", wall.id, level.id);
        const startX = margin + normalizedWall.x1 * scale;
        const startY = margin + normalizedWall.y1 * scale;
        const endX = margin + normalizedWall.x2 * scale;
        const endY = margin + normalizedWall.y2 * scale;
        const wallWidth = Math.max((normalizedWall.b || DEFAULT_WALL_THICKNESS) * scale, 6);

        if (isSelected) {
            drawSelectionSegment(startX, startY, endX, endY, wallWidth, palette);
        }

        ctx.save();
        ctx.strokeStyle = normalizedWall.material === "masonry"
            ? (palette.wallMasonryStroke || palette.wallStroke)
            : (palette.wallConcreteStroke || palette.wallStroke);
        ctx.lineWidth = wallWidth;
        ctx.lineCap = "butt";
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
        ctx.restore();
    });
}

function drawSlabs(level) {
    if (!isModelSpaceElementTypeVisible("slab")) {
        return;
    }

    const palette = getModelSpacePalette();
    const labelsVisible = projectState.modelSpaceLabelsVisible !== false;
    const slabLabelsVisible = labelsVisible && isModelSpaceLabelTypeVisible("slab");
    const steelVisible = projectState.modelSpaceSteelVisible !== false;
    level.slabs.forEach((slab) => {
        const normalizedSlab = normalizeSlab(slab);
        const bounds = normalizeSlabBounds(normalizedSlab);
        const vertices = normalizedSlab.vertices;
        const isSelected = isSelectedElement("slab", slab.id, level.id);
        const toCanvasX = (value) => margin + value * scale;
        const toCanvasY = (value) => margin + value * scale;

        ctx.save();
        ctx.fillStyle = normalizedSlab.type === "lightened" ? palette.slabLightenedFill : palette.slabSolidFill;
        ctx.strokeStyle = normalizedSlab.type === "lightened" ? palette.slabLightenedStroke : palette.slabSolidStroke;
        ctx.lineWidth = 1.25;
        addClosedCanvasPolygonPath(ctx, vertices, toCanvasX, toCanvasY);
        ctx.fill();
        ctx.stroke();

        if (isSelected) {
            drawSelectionPolygon(vertices, palette, toCanvasX, toCanvasY);
        }

        ctx.save();
        addClosedCanvasPolygonPath(ctx, vertices, toCanvasX, toCanvasY);
        ctx.clip();

        if (normalizedSlab.type === "lightened") {
            getLightenedCassetteRects(normalizedSlab).forEach((cassette) => {
                const hatchSegments = getAnsi31RectHatchSegments(cassette.x1, cassette.y1, cassette.x2, cassette.y2);
                ctx.strokeStyle = palette.slabCassetteStroke;
                ctx.lineWidth = 0.8;
                hatchSegments.forEach((segment) => {
                    ctx.beginPath();
                    ctx.moveTo(toCanvasX(segment.x1), toCanvasY(segment.y1));
                    ctx.lineTo(toCanvasX(segment.x2), toCanvasY(segment.y2));
                    ctx.stroke();
                });
                ctx.strokeStyle = palette.slabCassetteStroke;
                ctx.lineWidth = 1;
                ctx.strokeRect(
                    toCanvasX(cassette.x1),
                    toCanvasY(cassette.y1),
                    (cassette.x2 - cassette.x1) * scale,
                    (cassette.y2 - cassette.y1) * scale
                );
            });
        } else {
            const xBars = getSolidSlabRepresentativeBars(level.slabs, normalizedSlab, "x");
            const yBars = getSolidSlabRepresentativeBars(level.slabs, normalizedSlab, "y");

            if (steelVisible) {
                ctx.lineCap = "round";
                ctx.lineJoin = "round";

                xBars.forEach((bar) => {
                    ctx.strokeStyle = bar.primary ? palette.solidBarPrimaryX : palette.solidBarSecondaryX;
                    ctx.lineWidth = bar.primary ? 1.65 : 1.15;
                    drawSolidSlabPreviewBar(ctx, bar, normalizedSlab, toCanvasX, toCanvasY);
                });

                yBars.forEach((bar) => {
                    ctx.strokeStyle = bar.primary ? palette.solidBarPrimaryY : palette.solidBarSecondaryY;
                    ctx.lineWidth = bar.primary ? 1.65 : 1.15;
                    drawSolidSlabPreviewBar(ctx, bar, normalizedSlab, toCanvasX, toCanvasY);
                });
                drawSlabTemperatureBars(ctx, normalizedSlab, toCanvasX, toCanvasY);
            }

            if (steelVisible && slabLabelsVisible) {
                ["x", "y"].forEach((axis) => {
                    const callout = getSolidSlabCallout(level.slabs, normalizedSlab, axis);
                    if (!callout) {
                        return;
                    }

                    drawPreviewLeaderLabel(
                        ctx,
                        callout.label,
                        margin + callout.labelCenterX * scale,
                        margin + callout.labelY * scale,
                        margin + callout.targetX * scale,
                        margin + callout.targetY * scale,
                        callout.placement,
                        {
                            textColor: palette.steelCalloutText,
                            lineColor: palette.steelCalloutLine,
                            screenScale: viewport.zoom
                        }
                    );
                });
            }
        }

        ctx.restore();
        ctx.restore();
    });
}

function drawFoundations(level) {
    if (!isModelSpaceElementTypeVisible("foundation")) {
        return;
    }

    const palette = getModelSpacePalette();
    const steelVisible = projectState.modelSpaceSteelVisible !== false;
    const toCanvasX = (value) => margin + value * scale;
    const toCanvasY = (value) => margin + value * scale;

    (level?.foundations || []).forEach((foundation) => {
        const normalizedFoundation = normalizeFoundation(foundation);
        const vertices = normalizedFoundation.vertices;
        const isSelected = isSelectedElement("foundation", normalizedFoundation.id, level.id);

        ctx.save();
        addClosedCanvasPolygonPath(ctx, vertices, toCanvasX, toCanvasY);
        ctx.fillStyle = palette.foundationFill;
        ctx.strokeStyle = palette.foundationStroke;
        ctx.lineWidth = 1.25;
        ctx.fill();
        ctx.stroke();
        ctx.restore();

        if (isSelected) {
            drawSelectionPolygon(vertices, palette, toCanvasX, toCanvasY);
        }

        if (!steelVisible) {
            return;
        }

        ctx.save();
        addClosedCanvasPolygonPath(ctx, vertices, toCanvasX, toCanvasY);
        ctx.clip();
        ctx.lineCap = "round";

        const drawSteelLayer = (factor, alpha) => {
            const xSteelY = normalizedFoundation.y1 + (normalizedFoundation.y2 - normalizedFoundation.y1) * factor;
            const ySteelX = normalizedFoundation.x1 + (normalizedFoundation.x2 - normalizedFoundation.x1) * factor;

            ctx.globalAlpha = alpha;
            ctx.strokeStyle = palette.solidBarPrimaryX;
            ctx.lineWidth = Math.max(Math.min(1.5, 3.5 / viewport.zoom), 0.75);
            ctx.beginPath();
            ctx.moveTo(toCanvasX(normalizedFoundation.x1 + 0.04), toCanvasY(xSteelY));
            ctx.lineTo(toCanvasX(normalizedFoundation.x2 - 0.04), toCanvasY(xSteelY));
            ctx.stroke();

            ctx.strokeStyle = palette.solidBarPrimaryY;
            ctx.beginPath();
            ctx.moveTo(toCanvasX(ySteelX), toCanvasY(normalizedFoundation.y1 + 0.04));
            ctx.lineTo(toCanvasX(ySteelX), toCanvasY(normalizedFoundation.y2 - 0.04));
            ctx.stroke();
            ctx.globalAlpha = 1;
        };

        drawSteelLayer(0.28, 0.72);
        drawSteelLayer(0.72, 1);

        ctx.restore();
    });
}

function drawPendingSlabPlacement() {
    if (projectState.sidebarMode !== "slab" || projectState.tool !== "slab" || !Array.isArray(projectState.pendingSlabVertices) || !projectState.pendingSlabVertices.length) {
        return;
    }

    const palette = getModelSpacePalette();
    const previewVertices = [...projectState.pendingSlabVertices];
    const hoverNode = projectState.slabHoverNode;
    if (hoverNode && !areMetricPointsEqual(hoverNode, previewVertices[previewVertices.length - 1])) {
        previewVertices.push(hoverNode);
    }

    ctx.save();
    ctx.strokeStyle = palette.selectionStroke;
    ctx.fillStyle = "rgba(96, 165, 250, 0.12)";
    ctx.lineWidth = 1.3;
    ctx.setLineDash([8 / viewport.zoom, 6 / viewport.zoom]);
    ctx.beginPath();
    ctx.moveTo(margin + previewVertices[0].x * scale, margin + previewVertices[0].y * scale);
    for (let index = 1; index < previewVertices.length; index += 1) {
        ctx.lineTo(margin + previewVertices[index].x * scale, margin + previewVertices[index].y * scale);
    }
    if (projectState.pendingSlabVertices.length >= 3) {
        ctx.closePath();
        ctx.fill();
    }
    ctx.stroke();
    ctx.setLineDash([]);

    projectState.pendingSlabVertices.forEach((vertex, index) => {
        ctx.beginPath();
        ctx.fillStyle = index === 0 ? palette.gridBadgeFill : palette.selectionStroke;
        ctx.strokeStyle = index === 0 ? palette.gridBadgeStroke : palette.selectionGlow;
        ctx.lineWidth = 1;
        ctx.arc(margin + vertex.x * scale, margin + vertex.y * scale, 4.5 / viewport.zoom, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
    });
    ctx.restore();
}

function drawCanvasSelectionMarquee() {
    if (!canvasGesture.selectionActive) {
        return;
    }

    const startX = canvasGesture.selectionStartScreenX;
    const startY = canvasGesture.selectionStartScreenY;
    const currentX = canvasGesture.selectionCurrentScreenX;
    const currentY = canvasGesture.selectionCurrentScreenY;
    const left = Math.min(startX, currentX);
    const top = Math.min(startY, currentY);
    const width = Math.max(Math.abs(currentX - startX), 1);
    const height = Math.max(Math.abs(currentY - startY), 1);

    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    drawSelectionRect(left, top, width, height, getModelSpacePalette(), 4);
    ctx.restore();
}

function drawBeams(level) {
    if (!isModelSpaceElementTypeVisible("beam")) {
        return;
    }

    const palette = getModelSpacePalette();
    level.beams.forEach((beam) => {
        const isSelected = isSelectedElement("beam", beam.id, level.id);
        const startX = margin + beam.x1 * scale;
        const startY = margin + beam.y1 * scale;
        const endX = margin + beam.x2 * scale;
        const endY = margin + beam.y2 * scale;
        const beamWidth = (beam.b || 0.3) * scale;

        if (isSelected) {
            drawSelectionSegment(startX, startY, endX, endY, beamWidth, palette);
        }

        ctx.strokeStyle = palette.beamStroke;
        ctx.lineWidth = beamWidth;
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
    });
}

function updateAxisCollection(axisCollection, labelCollection, type, value, label) {
    if (type !== "x" && type !== "y") {
        return false;
    }

    if (!axisCollection[type]) {
        axisCollection[type] = [];
    }
    if (!labelCollection[type]) {
        labelCollection[type] = {};
    }

    const axisKey = getAxisValueKey(value);
    let shouldRerender = false;

    if (!axisCollection[type].includes(value)) {
        axisCollection[type].push(value);
        axisCollection[type].sort((left, right) => left - right);
        shouldRerender = true;
    }

    if (label) {
        if (labelCollection[type][axisKey] !== label) {
            labelCollection[type][axisKey] = label;
            shouldRerender = true;
        }
    } else if (Object.prototype.hasOwnProperty.call(labelCollection[type], axisKey)) {
        delete labelCollection[type][axisKey];
        shouldRerender = true;
    }

    return shouldRerender;
}

function removeAxisFromCollection(axisCollection, labelCollection, type, value) {
    if (type !== "x" && type !== "y") {
        return false;
    }

    const axisKey = getAxisValueKey(value);
    let shouldRerender = false;

    if (labelCollection?.[type] && Object.prototype.hasOwnProperty.call(labelCollection[type], axisKey)) {
        delete labelCollection[type][axisKey];
        shouldRerender = true;
    }

    if (Array.isArray(axisCollection?.[type]) && axisCollection[type].some((axisValue) => axisValue === value)) {
        axisCollection[type] = axisCollection[type].filter((axisValue) => axisValue !== value);
        shouldRerender = true;
    }

    return shouldRerender;
}

function setAxisLabelInCollection(labelCollection, type, value, label) {
    if (type !== "x" && type !== "y") {
        return false;
    }

    const axisKey = getAxisValueKey(value);
    const normalizedLabel = normalizeTextValue(label);
    const currentLabel = labelCollection?.[type]?.[axisKey] || "";

    if (normalizedLabel === currentLabel) {
        return false;
    }

    if (!labelCollection[type]) {
        labelCollection[type] = {};
    }

    if (normalizedLabel) {
        labelCollection[type][axisKey] = normalizedLabel;
    } else {
        delete labelCollection[type][axisKey];
    }

    return true;
}

function addNewAxis(type = "x", valueInput, nameInput) {
    const normalizedType = type === "y" ? "y" : "x";
    const axisValues = projectState.axes?.[normalizedType] || [];
    const value = getGridAxisAbsoluteInputValue(axisValues, valueInput?.value);

    if (Number.isNaN(value)) {
        return;
    }

    const label = normalizeTextValue(nameInput?.value);
    const shouldRerender = updateAxisCollection(projectState.axes, projectState.axisLabels, normalizedType, value, label);

    if (shouldRerender) {
        updateUI();
        render();
    }

    if (valueInput) {
        valueInput.value = "";
    }
    if (nameInput) {
        nameInput.value = "";
    }
}

function addNewReferenceAxis() {
    const type = dom.referenceAxisTypeSelect?.value || "x";
    const normalizedType = type === "y" ? "y" : "x";
    const axisValues = projectState.referenceAxes?.[normalizedType] || [];
    const value = getGridAxisAbsoluteInputValue(axisValues, dom.referenceAxisValueInput?.value);

    if (Number.isNaN(value)) {
        return;
    }

    const label = normalizeTextValue(dom.referenceAxisNameInput?.value);
    const shouldRerender = updateAxisCollection(projectState.referenceAxes, projectState.referenceAxisLabels, normalizedType, value, label);

    if (shouldRerender) {
        updateUI();
        render();
    }

    if (dom.referenceAxisValueInput) {
        dom.referenceAxisValueInput.value = "";
    }
    if (dom.referenceAxisNameInput) {
        dom.referenceAxisNameInput.value = "";
    }
}

function removeAxis(type, value) {
    if (removeAxisFromCollection(projectState.axes, projectState.axisLabels, type, value)) {
        updateUI();
        render();
    }
}

function removeReferenceAxis(type, value) {
    if (removeAxisFromCollection(projectState.referenceAxes, projectState.referenceAxisLabels, type, value)) {
        updateUI();
        render();
    }
}

function setAxisLabel(type, value, label) {
    if (setAxisLabelInCollection(projectState.axisLabels, type, value, label)) {
        updateUI();
        render();
    }
}

function setReferenceAxisLabel(type, value, label) {
    if (setAxisLabelInCollection(projectState.referenceAxisLabels, type, value, label)) {
        updateUI();
        render();
    }
}

function buildAxisLabelsFromImportedLines(lines) {
    const labels = {};

    (Array.isArray(lines) ? lines : []).forEach((line) => {
        const axisLabel = normalizeTextValue(line?.label || line?.id || line?.name);
        const axisValue = Number.parseFloat(line?.normalizedOrdinate);
        if (!axisLabel || !Number.isFinite(axisValue)) {
            return;
        }

        labels[getAxisValueKey(axisValue)] = axisLabel;
    });

    return labels;
}

const importedStoryNameCollator = typeof Intl !== "undefined"
    ? new Intl.Collator(undefined, { numeric: true, sensitivity: "base" })
    : null;

function compareImportedStoryNames(leftName, rightName) {
    const left = String(leftName || "").trim();
    const right = String(rightName || "").trim();
    if (importedStoryNameCollator) {
        return importedStoryNameCollator.compare(left, right);
    }

    return left.localeCompare(right);
}

function normalizeFoundationStoryName(value) {
    const normalized = normalizeTextValue(value).toLowerCase();
    const withoutMarks = typeof normalized.normalize === "function"
        ? normalized.normalize("NFD").replace(/[\u0300-\u036f]/g, "")
        : normalized;

    return withoutMarks.replace(/[^a-z0-9]+/g, "");
}

function isImportedFoundationStoryName(storyName) {
    return ["base", "foundation", "foundations", "fundacion", "fundaciones"].includes(
        normalizeFoundationStoryName(storyName)
    );
}

function hasEtabsSlabImportSignature(slab) {
    return normalizeTextValue(slab?.sourceImportType).toLowerCase() === "etabs"
        || normalizeTextValue(slab?.sourceStory)
        || normalizeTextValue(slab?.sourceId)
        || String(slab?.id || "").toLowerCase().startsWith("etabs-");
}

function convertImportedSlabToFoundation(slab) {
    const normalizedSlab = normalizeSlab({
        ...slab,
        id: slab?.id || createEntityId("foundation"),
        vertices: Array.isArray(slab?.vertices) && slab.vertices.length >= 3
            ? slab.vertices
            : slab?.sourceBoundary
    });
    const bounds = normalizeSlabBounds(normalizedSlab);
    const width = Math.max(bounds.x2 - bounds.x1, 0.1);
    const height = Math.max(bounds.y2 - bounds.y1, 0.1);

    return normalizeFoundation({
        id: normalizedSlab.id,
        name: normalizedSlab.name,
        x: (bounds.x1 + bounds.x2) / 2,
        y: (bounds.y1 + bounds.y2) / 2,
        b: width,
        h: height,
        thickness: normalizedSlab.h,
        vertices: normalizedSlab.vertices,
        sourceBoundary: Array.isArray(normalizedSlab.sourceBoundary)
            ? normalizedSlab.sourceBoundary
            : normalizedSlab.vertices,
        sourceId: normalizedSlab.sourceId,
        sourceStory: normalizedSlab.sourceStory,
        sourceSection: normalizedSlab.sourceSection,
        sourceImportType: "etabs",
        sourceElementType: "slab",
        sourceSlabType: normalizedSlab.type,
        structuralMaterial: normalizedSlab.structuralMaterial,
        solid: normalizedSlab.solid
    });
}

function moveImportedFoundationStorySlabsToFoundations(level, { requireEtabsSignature = true } = {}) {
    if (!level || !isImportedFoundationStoryName(level.name) || !Array.isArray(level.slabs) || !level.slabs.length) {
        return 0;
    }

    const remainingSlabs = [];
    const convertedFoundations = [];
    level.slabs.forEach((slab) => {
        if (requireEtabsSignature && !hasEtabsSlabImportSignature(slab)) {
            remainingSlabs.push(slab);
            return;
        }

        convertedFoundations.push(convertImportedSlabToFoundation(slab));
    });

    if (!convertedFoundations.length) {
        return 0;
    }

    level.foundations = [
        ...(Array.isArray(level.foundations) ? level.foundations : []),
        ...convertedFoundations
    ];
    level.slabs = remainingSlabs;
    return convertedFoundations.length;
}


function hasEtabsBeamImportSignature(beam) {
    return normalizeTextValue(beam?.sourceImportType).toLowerCase() === "etabs"
        || normalizeTextValue(beam?.sourceStory)
        || normalizeTextValue(beam?.sourceId)
        || normalizeTextValue(beam?.sourceLabel)
        || normalizeTextValue(beam?.sourceUniqueId)
        || String(beam?.id || "").toLowerCase().startsWith("etabs-");
}

function getEtabsImportedBeamOriginalKey(beam) {
    const story = normalizeTextValue(beam?.sourceStory);
    const uniqueId = normalizeTextValue(beam?.sourceUniqueId);
    const label = normalizeTextValue(beam?.sourceLabel || beam?.sourceId || beam?.name);
    const sourceId = normalizeTextValue(beam?.sourceId || beam?.id);
    return [story, uniqueId || label || sourceId].filter(Boolean).join("|");
}

function getEtabsBeamSupportPointParameter(startPoint, endPoint, point) {
    const spanLength = getSegmentLength(startPoint, endPoint);
    if (!(spanLength > ETABS_BEAM_SUPPORT_SPLIT_MIN_LENGTH)) {
        return Number.NaN;
    }

    const projectedPoint = getClosestPointOnSegment(startPoint, endPoint, point);
    const distance = Math.hypot(projectedPoint.x - point.x, projectedPoint.y - point.y);
    if (distance > ETABS_BEAM_SUPPORT_SPLIT_TOLERANCE) {
        return Number.NaN;
    }

    const station = getPointParameterOnSegment(startPoint, endPoint, projectedPoint);
    return station > ETABS_BEAM_SUPPORT_SPLIT_MIN_LENGTH
        && station < spanLength - ETABS_BEAM_SUPPORT_SPLIT_MIN_LENGTH
        ? station
        : Number.NaN;
}

function getEtabsColumnSupportSplitPointsOnBeam(columns, startPoint, endPoint) {
    return (Array.isArray(columns) ? columns : [])
        .map((column) => normalizeColumnModel(column))
        .flatMap((column) => {
            const center = { x: parseNumberOrFallback(column?.x, 0), y: parseNumberOrFallback(column?.y, 0) };
            const projectedPoint = getClosestPointOnSegment(startPoint, endPoint, center);
            const distance = Math.hypot(projectedPoint.x - center.x, projectedPoint.y - center.y);
            const supportRadius = Math.max(
                parsePositiveNumberOrFallback(column?.b, 0, 0) / 2,
                parsePositiveNumberOrFallback(column?.h, 0, 0) / 2,
                ETABS_BEAM_SUPPORT_SPLIT_TOLERANCE
            ) + ETABS_BEAM_SUPPORT_SPLIT_TOLERANCE;
            if (distance > supportRadius) {
                return [];
            }

            const station = getEtabsBeamSupportPointParameter(startPoint, endPoint, projectedPoint);
            return Number.isFinite(station) ? [projectedPoint] : [];
        });
}

function getEtabsWallSupportSplitPointsOnBeam(walls, startPoint, endPoint) {
    const beamSegment = { x1: startPoint.x, y1: startPoint.y, x2: endPoint.x, y2: endPoint.y };
    return (Array.isArray(walls) ? walls : [])
        .filter(isWallEligibleForFrameOutput)
        .map((wall) => normalizeWall(wall))
        .flatMap((wall) => {
            const wallSegment = { x1: wall.x1, y1: wall.y1, x2: wall.x2, y2: wall.y2 };
            const wallLength = getSegmentLength({ x: wallSegment.x1, y: wallSegment.y1 }, { x: wallSegment.x2, y: wallSegment.y2 });
            if (!(wallLength > ETABS_BEAM_SUPPORT_SPLIT_MIN_LENGTH)) {
                return [];
            }

            // Do not split a frame beam only because a wall crosses it in plan.
            // A crossing masonry/non-frame wall is not a pórtico support. Only walls that are
            // collinear with the beam axis may create a beam support split.
            const overlapInterval = getCollinearSegmentOverlapInterval(
                beamSegment,
                wallSegment,
                ETABS_BEAM_SUPPORT_SPLIT_TOLERANCE
            );
            if (!overlapInterval) {
                return [];
            }

            const midpointStation = (overlapInterval.startDistance + overlapInterval.endDistance) / 2;
            const midpoint = getSegmentPointAtDistance(beamSegment, midpointStation);
            const station = getEtabsBeamSupportPointParameter(startPoint, endPoint, midpoint);
            return Number.isFinite(station) ? [midpoint] : [];
        });
}

function buildEtabsContinuousBeamSegmentMetadata(beam, originalLength, stationStart, stationEnd, segmentIndex, segmentCount) {
    const originalKey = getEtabsImportedBeamOriginalKey(beam);
    return {
        key: originalKey,
        id: normalizeTextValue(beam?.sourceEtabsOriginalId || beam?.sourceId || beam?.id),
        sourceId: normalizeTextValue(beam?.sourceId),
        sourceLabel: normalizeTextValue(beam?.sourceLabel),
        sourceUniqueId: normalizeTextValue(beam?.sourceUniqueId),
        sourceStory: normalizeTextValue(beam?.sourceStory),
        length: roundCoordinate(originalLength),
        stationStart: roundCoordinate(stationStart),
        stationEnd: roundCoordinate(stationEnd),
        segmentIndex,
        segmentCount
    };
}

function buildEtabsContinuousBeamSegment(beam, startEntry, endEntry, segmentIndex, segmentCount, originalLength) {
    const sourceCuts = normalizeSectionCuts(beam?.sectionCuts, beam);
    const stationStart = startEntry.parameter;
    const stationEnd = endEntry.parameter;
    const normalizedAdditional = normalizeBeamAdditionalRebar(beam?.additionalRebar);
    const baseId = normalizeTextValue(beam?.id) || createEntityId("beam");
    const baseName = normalizeTextValue(beam?.name);
    const metadata = buildEtabsContinuousBeamSegmentMetadata(
        beam,
        originalLength,
        stationStart,
        stationEnd,
        segmentIndex,
        segmentCount
    );

    return normalizeBeamModel({
        ...beam,
        id: `${baseId}-seg-${segmentIndex + 1}`,
        // Name stays common across spans; source IDs remain untouched for steel import.
        name: baseName,
        spanNumber: segmentIndex + 1,
        spanCount: segmentCount,
        x1: startEntry.point.x,
        y1: startEntry.point.y,
        x2: endEntry.point.x,
        y2: endEntry.point.y,
        sourceImportType: "etabs",
        sourceEtabsOriginalId: metadata.id,
        sourceEtabsOriginalKey: metadata.key,
        sourceEtabsOriginalLength: metadata.length,
        sourceEtabsStationStart: metadata.stationStart,
        sourceEtabsStationEnd: metadata.stationEnd,
        sourceEtabsSegmentIndex: segmentIndex,
        sourceEtabsSegmentCount: segmentCount,
        etabsContinuousBeamSource: metadata,
        sectionCuts: sourceCuts
            .filter((value) => value > stationStart + EDGE_TOLERANCE && value < stationEnd - EDGE_TOLERANCE)
            .map((value) => roundCoordinate(value - stationStart)),
        additionalRebar: buildBeamSegmentAdditionalRebar(normalizedAdditional, {
            preserveIEnd: segmentIndex === 0,
            preserveJEnd: segmentIndex === segmentCount - 1
        })
    });
}

function splitEtabsImportedBeamAtSupportPoints(beam, supportPoints = []) {
    const normalizedBeam = normalizeBeamModel(beam);
    const startPoint = { x: normalizedBeam.x1, y: normalizedBeam.y1 };
    const endPoint = { x: normalizedBeam.x2, y: normalizedBeam.y2 };
    const originalLength = getSegmentLength(startPoint, endPoint);
    if (!(originalLength > ETABS_BEAM_SUPPORT_SPLIT_MIN_LENGTH)) {
        return [normalizedBeam];
    }

    const orderedEntries = getSortedUniquePointsOnSegment(startPoint, endPoint, supportPoints)
        .filter((entry) => entry.parameter >= -EDGE_TOLERANCE && entry.parameter <= originalLength + EDGE_TOLERANCE)
        .map((entry) => ({
            point: {
                x: roundCoordinate(entry.point.x),
                y: roundCoordinate(entry.point.y)
            },
            parameter: Math.max(0, Math.min(originalLength, entry.parameter))
        }))
        .filter((entry, index, entries) => (
            index === 0
            || Math.abs(entry.parameter - entries[index - 1].parameter) > ETABS_BEAM_SUPPORT_SPLIT_MIN_LENGTH
        ));

    if (orderedEntries.length <= 2) {
        return [normalizedBeam];
    }

    const segmentEntries = [];
    for (let index = 0; index < orderedEntries.length - 1; index += 1) {
        const startEntry = orderedEntries[index];
        const endEntry = orderedEntries[index + 1];
        if (endEntry.parameter - startEntry.parameter > ETABS_BEAM_SUPPORT_SPLIT_MIN_LENGTH) {
            segmentEntries.push({ startEntry, endEntry });
        }
    }

    if (segmentEntries.length <= 1) {
        return [normalizedBeam];
    }

    return segmentEntries.map(({ startEntry, endEntry }, index) => buildEtabsContinuousBeamSegment(
        normalizedBeam,
        startEntry,
        endEntry,
        index,
        segmentEntries.length,
        originalLength
    ));
}

function splitLevelEtabsContinuousBeamsAtSupports(level) {
    if (!level || !Array.isArray(level.beams) || level.beams.length === 0) {
        return 0;
    }

    const columns = Array.isArray(level.columns) ? level.columns : [];
    const walls = Array.isArray(level.walls) ? level.walls : [];
    let addedSegments = 0;
    const nextBeams = [];

    level.beams.forEach((beam) => {
        const normalizedBeam = normalizeBeamModel(beam);
        if (!hasEtabsBeamImportSignature(normalizedBeam) || parseNumberOrFallback(normalizedBeam?.sourceEtabsSegmentCount, 1) > 1) {
            nextBeams.push(normalizedBeam);
            return;
        }

        const startPoint = { x: normalizedBeam.x1, y: normalizedBeam.y1 };
        const endPoint = { x: normalizedBeam.x2, y: normalizedBeam.y2 };
        const supportPoints = [
            ...getEtabsColumnSupportSplitPointsOnBeam(columns, startPoint, endPoint),
            ...getEtabsWallSupportSplitPointsOnBeam(walls, startPoint, endPoint)
        ];
        const pieces = splitEtabsImportedBeamAtSupportPoints(normalizedBeam, supportPoints);
        addedSegments += Math.max(0, pieces.length - 1);
        nextBeams.push(...pieces);
    });

    level.beams = nextBeams;
    return addedSegments;
}

function buildImportedLevelsFromStories(stories, elementsByStory = {}) {
    const fallbackPrefix = projectState.language === "en" ? "Level" : "Nivel";
    const explicitStories = Array.isArray(stories) ? stories : [];
    const explicitStoryNames = new Set(
        explicitStories
            .map((story) => String(story?.name || "").trim())
            .filter(Boolean)
    );
    const extraStoryNames = Object.keys(elementsByStory || {})
        .map((name) => String(name || "").trim())
        .filter((name) => name && !explicitStoryNames.has(name))
        .sort(compareImportedStoryNames);
    const orderedStories = explicitStories.length > 0
        ? [
            ...[...explicitStories].reverse(),
            ...extraStoryNames.map((name) => ({
                name,
                height: 3.0
            }))
        ]
        : extraStoryNames.map((name) => ({
            name,
            height: 3.0
        }));

    if (orderedStories.length === 0) {
        return [createLevel(1, `${fallbackPrefix} 1`, 3.5)];
    }

    return orderedStories.map((story, index) => {
        const storyName = String(story?.name || "").trim();
        const level = createLevel(
            index + 1,
            storyName || `${fallbackPrefix} ${index + 1}`,
            Math.max(parseNumberOrFallback(story?.height, 3.0), 0.1)
        );

        const elements = elementsByStory[storyName];
        if (elements) {
            level.columns = (elements.columns || []).map((column) => normalizeColumnModel({
                ...column,
                id: column.id || createEntityId("column")
            }));
            level.beams = (elements.beams || []).map((beam) => normalizeBeamModel({
                ...beam,
                id: beam.id || createEntityId("beam"),
                x1: beam.start?.x ?? beam.x1 ?? 0,
                y1: beam.start?.y ?? beam.y1 ?? 0,
                x2: beam.end?.x ?? beam.x2 ?? 0,
                y2: beam.end?.y ?? beam.y2 ?? 0
            }));
            level.walls = (elements.walls || []).map((wall) => normalizeWall({
                ...wall,
                id: wall.id || createEntityId("wall"),
                h: wall.h ?? level.height
            }));
            level.foundations = (elements.foundations || []).map((foundation) => normalizeFoundation({
                ...foundation,
                id: foundation.id || createEntityId("foundation")
            }));
            level.slabs = (elements.slabs || []).map((slab) => normalizeSlab({
                ...slab,
                id: slab.id || createEntityId("slab"),
                sourceImportType: slab.sourceImportType || "etabs",
                vertices: Array.isArray(slab?.vertices) && slab.vertices.length >= 3
                    ? slab.vertices
                    : slab.sourceBoundary
            }));
            moveImportedFoundationStorySlabsToFoundations(level, { requireEtabsSignature: false });
        }

        return level;
    });
}

function hasProjectElements() {
    return projectState.levels.some((level) => (
        (level.columns?.length || 0) > 0
        || (level.beams?.length || 0) > 0
        || (level.walls?.length || 0) > 0
        || (level.foundations?.length || 0) > 0
        || (level.slabs?.length || 0) > 0
    ));
}

function arraysMatchWithinTolerance(leftValues, rightValues, tolerance = 0.0001) {
    if (leftValues.length !== rightValues.length) {
        return false;
    }

    return leftValues.every((value, index) => Math.abs(value - rightValues[index]) <= tolerance);
}

function shouldConfirmEtabsGridImport() {
    const hasImportedLabels = Object.keys(projectState.axisLabels.x).length > 0 || Object.keys(projectState.axisLabels.y).length > 0;
    const hasCustomGrid = !arraysMatchWithinTolerance(projectState.axes.x, DEFAULT_GRID_AXIS_VALUES)
        || !arraysMatchWithinTolerance(projectState.axes.y, DEFAULT_GRID_AXIS_VALUES);
    const hasCustomLevels = projectState.levels.length !== 1
        || Math.abs(parseNumberOrFallback(projectState.levels[0]?.height, 3.5) - 3.5) > 0.0001
        || !["Nivel 1", "Level 1"].includes(String(projectState.levels[0]?.name || "").trim());

    return hasProjectElements() || hasImportedLabels || hasCustomGrid || hasCustomLevels;
}

function isEtabsImportedWallOfThickness(wall, targetThickness, tolerance = 0.0001) {
    const thickness = parsePositiveNumberOrFallback(wall?.b, Number.NaN);
    return Number.isFinite(thickness) && Math.abs(thickness - targetThickness) <= tolerance;
}

function isEtabsImportedWallAtOrBelowThickness(wall, targetThickness, tolerance = 0.0001) {
    const thickness = parsePositiveNumberOrFallback(wall?.b, Number.NaN);
    return Number.isFinite(thickness) && thickness <= targetThickness + tolerance;
}

function countEtabsImportedWallsByThickness(importData, targetThickness, tolerance = 0.0001) {
    const elementsByStory = importData?.normalizedForStructaCAD?.elementsByStory;
    if (!elementsByStory || typeof elementsByStory !== "object") {
        return 0;
    }

    return Object.values(elementsByStory).reduce((total, storyElements) => {
        const walls = Array.isArray(storyElements?.walls) ? storyElements.walls : [];
        return total + walls.filter((wall) => isEtabsImportedWallOfThickness(wall, targetThickness, tolerance)).length;
    }, 0);
}

function countEtabsImportedWallsAtOrBelowThickness(importData, targetThickness, tolerance = 0.0001) {
    const elementsByStory = importData?.normalizedForStructaCAD?.elementsByStory;
    if (!elementsByStory || typeof elementsByStory !== "object") {
        return 0;
    }

    return Object.values(elementsByStory).reduce((total, storyElements) => {
        const walls = Array.isArray(storyElements?.walls) ? storyElements.walls : [];
        return total + walls.filter((wall) => isEtabsImportedWallAtOrBelowThickness(wall, targetThickness, tolerance)).length;
    }, 0);
}

function removeEtabsImportedWallsByThickness(importData, targetThickness, tolerance = 0.0001) {
    const elementsByStory = importData?.normalizedForStructaCAD?.elementsByStory;
    if (!elementsByStory || typeof elementsByStory !== "object") {
        return 0;
    }

    let removedCount = 0;
    Object.values(elementsByStory).forEach((storyElements) => {
        if (!Array.isArray(storyElements?.walls)) {
            return;
        }

        const originalCount = storyElements.walls.length;
        storyElements.walls = storyElements.walls.filter((wall) => !isEtabsImportedWallOfThickness(wall, targetThickness, tolerance));
        removedCount += originalCount - storyElements.walls.length;
    });

    return removedCount;
}

function removeEtabsImportedWallsAtOrBelowThickness(importData, targetThickness, tolerance = 0.0001) {
    const elementsByStory = importData?.normalizedForStructaCAD?.elementsByStory;
    if (!elementsByStory || typeof elementsByStory !== "object") {
        return 0;
    }

    let removedCount = 0;
    Object.values(elementsByStory).forEach((storyElements) => {
        if (!Array.isArray(storyElements?.walls)) {
            return;
        }

        const originalCount = storyElements.walls.length;
        storyElements.walls = storyElements.walls.filter((wall) => !isEtabsImportedWallAtOrBelowThickness(wall, targetThickness, tolerance));
        removedCount += originalCount - storyElements.walls.length;
    });

    return removedCount;
}

