function readSlabLightenedFields(fieldPrefix = "slab", source = {}) {
    const readFieldValue = (fieldId, fallback = "") => {
        const field = document.getElementById(fieldId);
        const value = String(field?.value ?? "").trim();
        return value ? field.value : fallback;
    };

    const xZones = LIGHTENED_SLAB_ZONE_KEYS.reduce((zones, zoneKey) => {
        zones[zoneKey] = {
            bars: readFieldValue(getSlabLightenedZoneBarsFieldId(fieldPrefix, zoneKey, "x"), source?.xZones?.[zoneKey]?.bars),
            diameter: readFieldValue(getSlabLightenedZoneDiameterFieldId(fieldPrefix, zoneKey, "x"), source?.xZones?.[zoneKey]?.diameter)
        };
        return zones;
    }, {});
    const yZones = LIGHTENED_SLAB_ZONE_KEYS.reduce((zones, zoneKey) => {
        zones[zoneKey] = {
            bars: readFieldValue(getSlabLightenedZoneBarsFieldId(fieldPrefix, zoneKey, "y"), source?.yZones?.[zoneKey]?.bars),
            diameter: readFieldValue(getSlabLightenedZoneDiameterFieldId(fieldPrefix, zoneKey, "y"), source?.yZones?.[zoneKey]?.diameter)
        };
        return zones;
    }, {});

    return normalizeLightenedSlabConfig({
        cassetteWidth: readFieldValue(`${fieldPrefix}-light-w`, source?.cassetteWidth),
        cassetteHeight: readFieldValue(`${fieldPrefix}-light-h`, source?.cassetteHeight),
        cassetteThickness: readFieldValue(`${fieldPrefix}-light-thickness`, source?.cassetteThickness),
        cassetteGap: readFieldValue(`${fieldPrefix}-light-gap`, source?.cassetteGap),
        xZones,
        yZones
    });
}

function buildSlabReinforcementPanelMarkup(slab, options = {}) {
    const normalizedSlab = normalizeSlab(slab);
    const {
        fieldPrefix = "slab",
        panelClassName = "",
        showNotes = true
    } = options;
    const isOneWaySlab = normalizedSlab.actionType === SLAB_ACTION_ONE_WAY;
    const mainSteelAxis = normalizeTextValue(normalizedSlab.solid.topSteelDirection).toLowerCase() === "y" ? "y" : "x";
    const solidFieldsHidden = isSolidSlabType(normalizedSlab.type) ? "" : " hidden";
    const lightenedFieldsHidden = normalizedSlab.type === "lightened" ? "" : " hidden";
    const solidXHidden = isOneWaySlab && mainSteelAxis !== "x" ? " hidden" : "";
    const solidYHidden = isOneWaySlab && mainSteelAxis !== "y" ? " hidden" : "";

    if (normalizedSlab.type === "hole") {
        return `
        <details class="reinforcement-panel${panelClassName ? ` ${panelClassName}` : ""}" data-reinforcement-panel="true" data-panel-disabled="true">
            <summary class="reinforcement-panel-summary">${translate("modal.reinforcementSteel")}</summary>
            <div class="reinforcement-panel-body">
                <small class="field-note">${translate("modal.holeNote")}</small>
            </div>
        </details>
    `;
    }

    const solidSection = `
        <div class="modal-subsection slab-fields-group" data-slab-fields="solid"${solidFieldsHidden}>
            <div class="column-rebar-grid slab-solid-rebar-grid">
                <div class="column-rebar-card slab-solid-rebar-card" data-slab-main-rebar-card="x"${solidXHidden}>
                    <div class="column-rebar-card-title">Dir X</div>
                    <div class="inline-row column-inline-row slab-solid-rebar-row">
                        ${buildDiameterSelect(`${fieldPrefix}-solid-x-d`, normalizedSlab.solid.xBarDiameter, DEFAULT_SLAB_BAR_DIAMETER, 'class="column-diameter-select slab-solid-diameter-select"')}
                        <input type="number" id="${fieldPrefix}-solid-x-s" class="slab-solid-spacing-input" value="${escapeHtml(String(normalizedSlab.solid.xSpacing))}" step="0.05" min="0.01" placeholder="S">
                    </div>
                </div>
                <div class="column-rebar-card slab-solid-rebar-card" data-slab-main-rebar-card="y"${solidYHidden}>
                    <div class="column-rebar-card-title">Dir Y</div>
                    <div class="inline-row column-inline-row slab-solid-rebar-row">
                        ${buildDiameterSelect(`${fieldPrefix}-solid-y-d`, normalizedSlab.solid.yBarDiameter, DEFAULT_SLAB_BAR_DIAMETER, 'class="column-diameter-select slab-solid-diameter-select"')}
                        <input type="number" id="${fieldPrefix}-solid-y-s" class="slab-solid-spacing-input" value="${escapeHtml(String(normalizedSlab.solid.ySpacing))}" step="0.05" min="0.01" placeholder="S">
                    </div>
                </div>
            </div>
            <label for="${fieldPrefix}-solid-top-dir">${translate("modal.slabTopSteelDirection")}</label>
            <select id="${fieldPrefix}-solid-top-dir">
                <option value="x"${normalizedSlab.solid.topSteelDirection === "x" ? " selected" : ""}>${translate("modal.slabTopSteelDirX")}</option>
                <option value="y"${normalizedSlab.solid.topSteelDirection === "y" ? " selected" : ""}>${translate("modal.slabTopSteelDirY")}</option>
            </select>
            ${showNotes ? `<small class="field-note">${translate("modal.slabSolidNote")}</small>` : ""}
        </div>
    `;

    const lightenedSection = `
        <div class="modal-subsection slab-fields-group" data-slab-fields="lightened"${lightenedFieldsHidden}>
            <label>${translate("modal.slabCassettes")}</label>
            <div class="slab-cassette-grid" style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-bottom: 12px;">
                <div class="cassette-field">
                    <span style="display: block; font-size: 9px; color: var(--text-soft); text-transform: uppercase;">${escapeHtml(translate("modal.slabCassetteWidth"))}</span>
                    <input type="number" id="${fieldPrefix}-light-w" value="${escapeHtml(String(normalizedSlab.lightened.cassetteWidth))}" step="0.05" min="0.2" style="margin-top: 4px;">
                </div>
                <div class="cassette-field">
                    <span style="display: block; font-size: 9px; color: var(--text-soft); text-transform: uppercase;">${escapeHtml(translate("modal.slabCassetteLength"))}</span>
                    <input type="number" id="${fieldPrefix}-light-h" value="${escapeHtml(String(normalizedSlab.lightened.cassetteHeight))}" step="0.05" min="0.2" style="margin-top: 4px;">
                </div>
                <div class="cassette-field">
                    <span style="display: block; font-size: 9px; color: var(--text-soft); text-transform: uppercase;">${escapeHtml(translate("modal.slabCassetteThickness"))}</span>
                    <input type="number" id="${fieldPrefix}-light-thickness" value="${escapeHtml(String(normalizedSlab.lightened.cassetteThickness))}" step="0.01" min="0.02" style="margin-top: 4px;">
                </div>
                <div class="cassette-field">
                    <span style="display: block; font-size: 9px; color: var(--text-soft); text-transform: uppercase;">${escapeHtml(translate("modal.slabCassetteGap"))}</span>
                    <input type="number" id="${fieldPrefix}-light-gap" value="${escapeHtml(String(normalizedSlab.lightened.cassetteGap))}" step="0.05" min="0.05" style="margin-top: 4px;">
                </div>
            </div>
            <label>${translate("modal.slabRibReinforcement") || "Refuerzo de nervios"}</label>
            <div class="slab-lightened-zone-grid">
                <div class="slab-lightened-zone-grid-header">${translate("modal.slabZone") || "Zona"}</div>
                <div class="slab-lightened-zone-grid-header">${translate("modal.slabDirX")}</div>
                <div class="slab-lightened-zone-grid-header">${translate("modal.slabDirY")}</div>
                ${LIGHTENED_SLAB_ZONE_KEYS.map((zoneKey) => buildSlabLightenedRebarRowMarkup(fieldPrefix, zoneKey, normalizedSlab.lightened)).join("")}
            </div>
            ${showNotes ? `<small class="field-note">${translate("modal.slabLightenedNote", {
        gap: normalizedSlab.lightened.cassetteGap.toFixed(2),
        edgeGap: SLAB_CASSETTE_EDGE_GAP.toFixed(2)
    })}</small>` : ""}
        </div>
    `;

    return `
        <details class="reinforcement-panel${panelClassName ? ` ${panelClassName}` : ""}" data-reinforcement-panel="true">
            <summary class="reinforcement-panel-summary">${translate("modal.reinforcementSteel")}</summary>
            <div class="reinforcement-panel-body">
                ${solidSection}
                ${lightenedSection}
                ${buildSlabTemperatureSectionMarkup(normalizedSlab.temperatureSteel, fieldPrefix)}
            </div>
        </details>
    `;
}

