function readSlabTemperatureFields(fieldPrefix = "slab", source = {}) {
    const enabledInput = document.getElementById(`${fieldPrefix}-temp-enabled`);
    const dirXInput = document.getElementById(`${fieldPrefix}-temp-dir-x`);
    const dirYInput = document.getElementById(`${fieldPrefix}-temp-dir-y`);
    const diameterInput = document.getElementById(`${fieldPrefix}-temp-d`);
    const spacingInput = document.getElementById(`${fieldPrefix}-temp-s`);
    const isMixedState = Boolean(enabledInput?.indeterminate);
    const enabled = isMixedState
        ? source?.enabled
        : enabledInput?.checked;
    const direction = isMixedState
        ? source?.direction
        : dirYInput?.checked
            ? "y"
            : dirXInput?.checked
                ? "x"
                : source?.direction;

    return normalizeSlabTemperatureSteel({
        enabled,
        direction: direction || "x",
        barDiameter: diameterInput?.value || source?.barDiameter || source?.diameter,
        spacing: spacingInput?.value || source?.spacing || source?.barSpacing
    });
}

function wireSlabTemperatureFields(fieldPrefix = "slab", root = dom.modalFields, onChange = null, options = {}) {
    const enabledInput = document.getElementById(`${fieldPrefix}-temp-enabled`);
    const dirXInput = document.getElementById(`${fieldPrefix}-temp-dir-x`);
    const dirYInput = document.getElementById(`${fieldPrefix}-temp-dir-y`);
    const diameterInput = document.getElementById(`${fieldPrefix}-temp-d`);
    const spacingInput = document.getElementById(`${fieldPrefix}-temp-s`);
    const section = enabledInput?.closest(".slab-temperature-section");
    const controls = section?.querySelector(`[data-slab-temperature-controls="${fieldPrefix}"]`)
        || root?.querySelector(`[data-slab-temperature-controls="${fieldPrefix}"]`)
        || document.querySelector(`[data-slab-temperature-controls="${fieldPrefix}"]`);
    const preserveBlankDirection = options.preserveBlankDirection === true;

    if (!enabledInput || !dirXInput || !dirYInput) {
        return;
    }

    const refreshSlabTemperatureState = () => {
        const isEnabled = Boolean(enabledInput.checked);
        if (isEnabled && !dirXInput.checked && !dirYInput.checked && !preserveBlankDirection) {
            dirXInput.checked = true;
        }

        [dirXInput, dirYInput, diameterInput, spacingInput].forEach((input) => {
            if (input) {
                input.disabled = !isEnabled;
                input.toggleAttribute("aria-disabled", !isEnabled);
            }
        });

        if (controls) {
            controls.classList.toggle("is-disabled", !isEnabled);
            controls.dataset.enabled = String(isEnabled);
            controls.setAttribute("aria-disabled", String(!isEnabled));
        }

        section?.classList.toggle("is-temperature-disabled", !isEnabled);
        section?.classList.toggle("is-temperature-enabled", isEnabled);

        if (typeof onChange === "function") {
            onChange();
        }
    };

    enabledInput.addEventListener("change", refreshSlabTemperatureState);
    [dirXInput, dirYInput, diameterInput, spacingInput].forEach((input) => {
        input?.addEventListener("change", refreshSlabTemperatureState);
        input?.addEventListener("input", refreshSlabTemperatureState);
    });
    refreshSlabTemperatureState();
}

function wireColumnLongitudinalFields(fieldPrefix = "edit-col", onChange = null) {
    const xCountInput = document.getElementById(`${fieldPrefix}-x-count`);
    const yCountInput = document.getElementById(`${fieldPrefix}-y-count`);
    const xDiameterSelect = document.getElementById(`${fieldPrefix}-x-d`);
    const yDiameterSelect = document.getElementById(`${fieldPrefix}-y-d`);
    const cornerCheckbox = document.getElementById(`${fieldPrefix}-corner-custom`);
    const cornerDiameterSelect = document.getElementById(`${fieldPrefix}-corner-d`);
    if (!xCountInput || !yCountInput || !xDiameterSelect || !yDiameterSelect || !cornerCheckbox || !cornerDiameterSelect) {
        return;
    }

    const refreshColumnLongitudinalState = () => {
        const normalized = normalizeColumnLongitudinalRebar({
            xCount: xCountInput.value,
            xDiameter: xDiameterSelect.value,
            yCount: yCountInput.value,
            yDiameter: yDiameterSelect.value,
            cornerDiameter: cornerDiameterSelect.value,
            hasCustomCornerDiameter: cornerCheckbox.checked
        });

        cornerDiameterSelect.disabled = !cornerCheckbox.checked;
        cornerDiameterSelect.closest(".column-rebar-card")?.classList.toggle("is-disabled", !cornerCheckbox.checked);
        if (!cornerCheckbox.checked) {
            cornerDiameterSelect.value = normalized.cornerDiameter;
        }

        syncColumnConfinementCountSelects(fieldPrefix, normalized);

        if (typeof onChange === "function") {
            onChange(normalized);
        }
    };

    [xCountInput, yCountInput].forEach((input) => {
        input.addEventListener("input", refreshColumnLongitudinalState);
        input.addEventListener("change", refreshColumnLongitudinalState);
    });
    [xDiameterSelect, yDiameterSelect, cornerCheckbox, cornerDiameterSelect].forEach((input) => input.addEventListener("change", refreshColumnLongitudinalState));
    refreshColumnLongitudinalState();
}

function openEditModal(element, type) {
    projectState.editingElement = { data: element, type };
    dom.modalTitle.textContent = type === "beam"
        ? translate("modal.editBeam")
        : type === "wall"
            ? translate("modal.editWall")
            : translate("modal.editColumn");

    const columnLongRebar = type === "col"
        ? normalizeColumnLongitudinalRebar(element.longRebar ?? element.longitudinalRebar)
        : null;
    const transverseRebar = type !== "wall"
        ? type === "col"
            ? ensureColumnTransverseRebar(element, columnLongRebar)
            : ensureTransverseRebar(element, DEFAULT_BEAM_STIRRUP_SPACING)
        : null;
    let fields = `
        <label>${translate("modal.name")}</label>
        <input type="text" id="edit-name" value="${escapeHtml(element.name || "")}" placeholder="${getModalNamePlaceholder(type)}">
        <label>${type === "wall" ? translate("modal.thickness") : translate("modal.width")}</label>
        <input type="number" id="edit-b" value="${escapeHtml(String(element.b))}" step="0.05" min="${type === "wall" ? "0.08" : "0.05"}">
    `;

    if (type === "beam" || type === "col") {
        const heightLabel = type === "beam" ? translate("modal.depth") : translate("modal.height");
        fields += `<label>${heightLabel}</label><input type="number" id="edit-h" value="${escapeHtml(String(element.h ?? ""))}" step="0.05" min="0.05">`;
    }

    if (type === "beam") {
        const topRebar = normalizeBeamMainLongitudinalRebar(element.topRebar);
        const bottomRebar = normalizeBeamMainLongitudinalRebar(element.botRebar);
        fields += `
            <label>${translate("modal.topSteel")}</label>
            <div class="inline-row">
                <input type="text" id="edit-ts-n" value="${escapeHtml(topRebar.n)}" placeholder="${translate("modal.numberOfBarsPlaceholder")}">
                ${buildBeamLongitudinalDiameterSelect("edit-ts-d", topRebar.d, DEFAULT_LONGITUDINAL_DIAMETER)}
            </div>
        `;
        fields += `
            <label>${translate("modal.bottomSteel")}</label>
            <div class="inline-row">
                <input type="text" id="edit-bi-n" value="${escapeHtml(bottomRebar.n)}" placeholder="${translate("modal.numberOfBarsPlaceholder")}">
                ${buildBeamLongitudinalDiameterSelect("edit-bi-d", bottomRebar.d, DEFAULT_LONGITUDINAL_DIAMETER)}
            </div>
        `;
    }
    if (type === "col") {
        fields += buildColumnReinforcementPanelMarkup({
            longRebar: columnLongRebar,
            stirrups: transverseRebar,
            fieldPrefix: "edit-col",
            transverseDiameterId: "edit-tr-d",
            transverseSpacingId: "edit-tr-s",
            transverseCountXId: "edit-tr-x",
            transverseCountYId: "edit-tr-y"
        });
    }
    if (type === "beam") {
        fields += `
            <label>${translate("modal.transverseReinforcement")}</label>
            <div class="inline-row">
                ${buildDiameterSelect("edit-tr-d", transverseRebar.d, DEFAULT_TRANSVERSE_DIAMETER)}
                <input type="number" id="edit-tr-s" value="${escapeHtml(String(transverseRebar.spacing))}" step="0.05" min="0.05" placeholder="${translate("modal.spacingPlaceholder")}">
            </div>
        `;
    }

    dom.modalFields.innerHTML = fields;
    if (type === "col") {
        wireColumnLongitudinalFields();
    }
    dom.modalOverlay.style.display = "flex";
}

function openSectionCutsModal(beam, suggestedCutOffset) {
    const existingCuts = normalizeSectionCuts(beam.sectionCuts, beam);
    const initialCuts = suggestedCutOffset === null || Number.isNaN(suggestedCutOffset)
        ? existingCuts
        : normalizeSectionCuts([...existingCuts, suggestedCutOffset], beam);

    projectState.editingElement = { data: beam, type: "beam-section" };
    dom.modalTitle.textContent = translate("modal.addBeamSections");
    dom.modalFields.innerHTML = `
        <label>${translate("modal.sectionCuts")}</label>
        <textarea id="edit-sc" rows="4" placeholder="${translate("modal.sectionCutsPlaceholder")}">${escapeHtml(formatSectionCuts(initialCuts, beam))}</textarea>
        <small class="field-note">${translate("modal.sectionCutsNote")}</small>
    `;
    dom.modalOverlay.style.display = "flex";
}

function openSlabSectionModal(slab, isNew = false, levelId = projectState.activeLevelId) {
    const normalizedSlab = normalizeSlab(slab);
    projectState.editingElement = { data: normalizedSlab, type: "slab-section", isNew, levelId };
    dom.modalTitle.textContent = normalizedSlab.type === "hole" ? translate("modal.editHole") : translate("modal.editSlab");
    dom.modalFields.innerHTML = buildSlabSectionFields(normalizedSlab);
    wireSlabTypeFields();
    wireSlabTemperatureFields();
    dom.modalOverlay.style.display = "flex";
}

function buildSlabSectionFields(slab) {
    const solidSection = `
        <div class="modal-subsection slab-fields-group" data-slab-fields="solid">
            <label>${translate("modal.slabSteelX")}</label>
            <div class="inline-row">
                ${buildDiameterSelect("slab-solid-x-d", slab.solid.xBarDiameter, DEFAULT_SLAB_BAR_DIAMETER)}
                <input type="number" id="slab-solid-x-s" value="${escapeHtml(String(slab.solid.xSpacing))}" step="0.05" min="0.05" placeholder="${translate("modal.slabSpacingX")}">
            </div>
            <label>${translate("modal.slabSteelY")}</label>
            <div class="inline-row">
                ${buildDiameterSelect("slab-solid-y-d", slab.solid.yBarDiameter, DEFAULT_SLAB_BAR_DIAMETER)}
                <input type="number" id="slab-solid-y-s" value="${escapeHtml(String(slab.solid.ySpacing))}" step="0.05" min="0.05" placeholder="${translate("modal.slabSpacingY")}">
            </div>
            <small class="field-note">La vista previa y el DXF muestran un par por direccion, separado 0.20m, alternando entre 1/4 y 3/4 del paño para evitar sobrelapes. Los ganchos van a 45 grados y la barra de continuidad puede prolongarse L/4 en la losa vecina a cualquiera de los lados.</small>
        </div>
    `;

    const lightenedSection = `
        <div class="modal-subsection slab-fields-group" data-slab-fields="lightened">
            <label>${translate("modal.slabCassettes")}</label>
            <div class="inline-row">
                <input type="number" id="slab-light-w" value="${escapeHtml(String(slab.lightened.cassetteWidth))}" step="0.05" min="0.2" placeholder="${translate("modal.slabCassetteWidth")}">
                <input type="number" id="slab-light-h" value="${escapeHtml(String(slab.lightened.cassetteHeight))}" step="0.05" min="0.2" placeholder="${translate("modal.slabCassetteLength")}">
            </div>
            <label>${translate("modal.slabRibSteelX")}</label>
            <div class="inline-row">
                <input type="number" id="slab-light-x-bars" value="${escapeHtml(String(slab.lightened.xBarsPerRib))}" step="1" min="1" placeholder="${translate("modal.slabBarsX")}">
                ${buildDiameterSelect("slab-light-x-d", slab.lightened.xBarDiameter, DEFAULT_LIGHTENED_CASSETTE_BAR_DIAMETER)}
            </div>
            <label>${translate("modal.slabRibSteelY")}</label>
            <div class="inline-row">
                <input type="number" id="slab-light-y-bars" value="${escapeHtml(String(slab.lightened.yBarsPerRib))}" step="1" min="1" placeholder="${translate("modal.slabBarsY")}">
                ${buildDiameterSelect("slab-light-y-d", slab.lightened.yBarDiameter, DEFAULT_LIGHTENED_CASSETTE_BAR_DIAMETER)}
            </div>
            <small class="field-note">Se dibuja un solo nervio representativo por direccion, con llamada de acero en X y en Y. Las bovedillas mantienen 0.20m libres entre ellas y respecto a los bordes.</small>
        </div>
    `;

    return `
        <label>${translate("modal.slabName")}</label>
        <input type="text" id="slab-name" value="${escapeHtml(slab.name || "")}" placeholder="${getModalNamePlaceholder(slab.type === "hole" ? "hole" : "slab")}">
        <label>${translate("modal.depth")}</label>
        <input type="number" id="slab-h" value="${escapeHtml(String(slab.h))}" step="0.05" min="0.05">
        <label>${translate("modal.slabType")}</label>
        <select id="slab-type">
            <option value="solid"${slab.type === "solid" ? " selected" : ""}>${translate("modal.slabSolid")}</option>
            <option value="${SLAB_TYPE_SOLID_STAIR}"${slab.type === SLAB_TYPE_SOLID_STAIR ? " selected" : ""}>${translate("modal.slabSolidStair")}</option>
            <option value="lightened"${slab.type === "lightened" ? " selected" : ""}>${translate("modal.slabLightened")}</option>
            <option value="hole"${slab.type === "hole" ? " selected" : ""}>${translate("modal.hole")}</option>
        </select>
        <label class="column-checkbox-row" for="slab-cantilever" style="margin-top: 6px;">
            <input type="checkbox" id="slab-cantilever"${slab.cantilever ? " checked" : ""}>
            <span>${translate("modal.slabCantilever") || "Losa en voladizo"}</span>
        </label>
        <small class="field-note">Paño: ${slab.x1.toFixed(2)}m x ${slab.y1.toFixed(2)}m a ${slab.x2.toFixed(2)}m x ${slab.y2.toFixed(2)}m.</small>
        ${solidSection}
        ${lightenedSection}
    `;
}

function wireSlabTypeFields(typeSelectId = "slab-type", root = dom.modalFields) {
    const typeSelect = document.getElementById(typeSelectId);
    const fieldPrefix = typeSelectId === "insert-slab-type" ? "insert-slab" : "slab";
    const actionTypeSelect = document.getElementById(typeSelectId === "insert-slab-type" ? "insert-slab-action-type" : "slab-action-type");
    const topSteelSelect = document.getElementById(`${fieldPrefix}-solid-top-dir`);
    const actionTypeField = actionTypeSelect?.closest("[data-slab-action-type-field]");
    const fieldGroups = Array.from(root?.querySelectorAll("[data-slab-fields]") || []);
    if (!typeSelect) {
        return;
    }

    const refreshVisibility = () => {
        const selectedType = normalizeSlabType(typeSelect.value);
        const actionTypeEnabled = supportsSlabActionType(selectedType);
        fieldGroups.forEach((group) => {
            const fieldType = group.dataset.slabFields;
            const shouldShow = fieldType === selectedType
                || (fieldType === "solid" && selectedType === SLAB_TYPE_SOLID_STAIR);
            group.hidden = !shouldShow;
        });
        if (actionTypeSelect) {
            actionTypeSelect.disabled = !actionTypeEnabled;
            if (!actionTypeEnabled) {
                actionTypeSelect.value = SLAB_ACTION_TWO_WAY;
            } else if (!actionTypeSelect.value) {
                actionTypeSelect.value = SLAB_ACTION_TWO_WAY;
            }
        }
        actionTypeField?.classList.toggle("is-disabled", !actionTypeEnabled);
        applyOneWaySlabActionDefaultsToFields(fieldPrefix, fieldPrefix === "insert-slab" ? projectState.insertDrafts.slab : projectState.editingElement?.data);
        syncOneWaySlabReinforcementUi(fieldPrefix, fieldPrefix === "insert-slab" ? projectState.insertDrafts.slab : projectState.editingElement?.data);
    };

    typeSelect.addEventListener("change", refreshVisibility);
    actionTypeSelect?.addEventListener("change", refreshVisibility);
    topSteelSelect?.addEventListener("change", refreshVisibility);
    refreshVisibility();
}

function openWallSectionModal(wall, levelId = projectState.activeLevelId) {
    const normalizedWall = normalizeWall(wall);
    projectState.editingElement = { data: normalizedWall, type: "wall-section", levelId };
    dom.modalTitle.textContent = translate("modal.editWall");
    dom.modalFields.innerHTML = buildWallSectionFields(normalizedWall);
    wireWallTypeFields();
    dom.modalOverlay.style.display = "flex";
}

function buildWallSectionFields(wall) {
    const normalizedWall = normalizeWall(wall);
    return `
        <label>${translate("modal.name")}</label>
        <input type="text" id="wall-name" value="${escapeHtml(normalizedWall.name || "")}" placeholder="${getModalNamePlaceholder("wall")}">
        <label>${translate("modal.wallThickness")}</label>
        <input type="number" id="wall-b" value="${escapeHtml(String(normalizedWall.b))}" step="0.05" min="0.08">
        <label>${translate("modal.wallType")}</label>
        <select id="wall-material">
            <option value="concrete"${normalizedWall.material === "concrete" ? " selected" : ""}>${translate("modal.wallConcrete")}</option>
            <option value="thin_wall"${normalizedWall.material === "thin_wall" ? " selected" : ""}>${translate("modal.wallThin")}</option>
            <option value="masonry"${normalizedWall.material === "masonry" ? " selected" : ""}>${translate("modal.wallMasonry")}</option>
        </select>
        <div class="modal-subsection wall-fields-group" data-wall-fields="masonry">
            ${buildMasonryBlockWidthFieldMarkup("wall-masonry-block-width", normalizedWall.masonry.blockWidth)}
        </div>
        <div class="modal-subsection wall-fields-group" data-wall-fields="masonry">
            ${buildMasonryTieColumnControlsMarkup("wall", normalizedWall.masonry)}
        </div>
        ${buildWallReinforcementPanelMarkup(normalizedWall, {
        fieldPrefix: "wall",
        showNotes: true
    })}
    `;
}

function wireWallTypeFields(materialSelectId = "wall-material", root = dom.modalFields, options = {}) {
    const materialSelect = document.getElementById(materialSelectId);
    const fieldGroups = Array.from(root?.querySelectorAll("[data-wall-fields]") || []);
    const materialPanels = Array.from(root?.querySelectorAll("[data-wall-material-panel]") || []);
    const isInsertContext = materialSelectId === "insert-wall-material";
    const thicknessInputId = options.thicknessInputId || (isInsertContext ? "insert-b" : "wall-b");
    const blockWidthInputId = options.blockWidthInputId || (isInsertContext ? "insert-wall-masonry-block-width" : "wall-masonry-block-width");
    const coverInputId = options.coverInputId || (isInsertContext ? "insert-wall-conc-cover" : "wall-conc-cover");
    const masonryDiameterInputId = options.masonryDiameterInputId || (isInsertContext ? "insert-wall-masonry-d" : "wall-masonry-d");
    const thicknessInput = document.getElementById(thicknessInputId);
    const blockWidthInput = document.getElementById(blockWidthInputId);
    const coverInput = document.getElementById(coverInputId);
    const masonryDiameterInput = document.getElementById(masonryDiameterInputId);
    if (!materialSelect) {
        return;
    }

    let previousMaterial = normalizeWallMaterialType(materialSelect.value);

    const refreshVisibility = () => {
        const selectedMaterial = normalizeWallMaterialType(materialSelect.value);
        const isMasonry = selectedMaterial === "masonry";
        fieldGroups.forEach((group) => {
            const groupType = group.dataset.wallFields;
            const shouldShow = groupType === "masonry"
                ? isMasonry
                : !isMasonry;
            group.hidden = !shouldShow;
        });
        materialPanels.forEach((panel) => {
            const panelType = panel.dataset.wallMaterialPanel;
            const shouldShow = panelType === "masonry"
                ? isMasonry
                : !isMasonry;
            panel.hidden = !shouldShow;
        });
        if (thicknessInput) {
            if (isMasonry && blockWidthInput) {
                thicknessInput.value = blockWidthInput.value;
            }
            thicknessInput.readOnly = isMasonry;
            thicknessInput.setAttribute("aria-readonly", String(isMasonry));
        }
    };

    materialSelect.addEventListener("change", () => {
        const selectedMaterial = normalizeWallMaterialType(materialSelect.value);
        if (previousMaterial !== "masonry" && selectedMaterial === "masonry" && masonryDiameterInput) {
            // A newly selected masonry wall always starts with the standard 3/8 in. bar.
            // Existing masonry walls retain their explicitly assigned reinforcement.
            masonryDiameterInput.value = getDiameterLabelForActiveBarSet(
                DEFAULT_MASONRY_BAR_DIAMETER,
                DEFAULT_MASONRY_BAR_DIAMETER
            );
        }
        previousMaterial = selectedMaterial;
        refreshVisibility();
    });
    blockWidthInput?.addEventListener("change", refreshVisibility);
    refreshVisibility();
}

function saveSlabSectionEdits() {
    const slabType = document.getElementById("slab-type").value;
    applyOneWaySlabActionDefaultsToFields("slab", projectState.editingElement.data);
    const slab = normalizeSlab({
        ...projectState.editingElement.data,
        name: document.getElementById("slab-name").value,
        h: document.getElementById("slab-h").value,
        type: slabType,
        actionType: document.getElementById("slab-action-type")?.value,
        cantilever: document.getElementById("slab-cantilever")?.checked,
        temperatureSteel: readSlabTemperatureFields("slab"),
        solid: {
            xBarDiameter: document.getElementById("slab-solid-x-d").value,
            xSpacing: document.getElementById("slab-solid-x-s").value,
            yBarDiameter: document.getElementById("slab-solid-y-d").value,
            ySpacing: document.getElementById("slab-solid-y-s").value,
            topSteelDirection: document.getElementById("slab-solid-top-dir")?.value
        },
        lightened: readSlabLightenedFields("slab")
    });

    const level = projectState.levels.find((item) => item.id === projectState.editingElement.levelId);
    if (!level) {
        closeModal();
        return;
    }

    level.slabs = level.slabs || [];
    level.holes = level.holes || [];
    const sourceType = normalizeSlab(projectState.editingElement.data).type === "hole" ? "hole" : "slab";
    const targetType = slab.type === "hole" ? "hole" : "slab";
    const sourceCollection = getSlabLikeCollection(level, sourceType);
    const targetCollection = getSlabLikeCollection(level, targetType);
    const targetNameType = targetType;

    const placeHole = (candidate, ignoreHoleIds = new Set([candidate.id])) => {
        if (!canPlaceHoleInLevel(level, candidate, ignoreHoleIds)) {
            openAppNoticeDialog({
                title: translate("dialog.invalidActionTitle") || "Accion invalida",
                message: translate("errors.holeMustBeInsideSlab")
            });
            return false;
        }
        return true;
    };

    if (projectState.editingElement.isNew) {
        const existing = findSlabByBounds(targetCollection, slab);
        if (existing) {
            if (!applySingleEntityEdits(targetNameType, existing, slab)) {
                return;
            }
        } else {
            if (!canUseEntityDraftName(targetNameType, slab)) {
                return;
            }

            if (targetType === "hole" && !placeHole(slab)) {
                return;
            }

            targetCollection.push(normalizeSlab({
                ...slab,
                name: resolveEntityName(targetNameType, slab.name, slab)
            }));
        }
    } else {
        const existing = sourceCollection.find((item) => item.id === slab.id);
        if (!existing) {
            closeModal();
            return;
        }

        if (targetType === "hole" && !placeHole(slab, new Set([projectState.editingElement.data?.id || slab.id]))) {
            return;
        }

        if (sourceType === targetType) {
            if (!applySingleEntityEdits(targetNameType, existing, slab)) {
                return;
            }
        } else {
            if (!canUseEntityDraftName(targetNameType, slab, new Set([existing.id]))) {
                return;
            }

            if (targetType === "hole" && !placeHole(slab, new Set([existing.id]))) {
                return;
            }

            sourceCollection.splice(sourceCollection.findIndex((item) => item.id === existing.id), 1);
            targetCollection.push(normalizeSlab({
                ...slab,
                id: existing.id,
                name: resolveEntityName(targetNameType, slab.name, slab)
            }));
        }
    }

    closeModal();
    updateUI();
    render();
}

function saveWallSectionEdits() {
    const wall = normalizeWall({
        ...projectState.editingElement.data,
        name: document.getElementById("wall-name")?.value ?? projectState.editingElement.data.name,
        b: document.getElementById("wall-b").value,
        material: document.getElementById("wall-material").value,
        concrete: {
            longitudinalDiameter: document.getElementById("wall-conc-long-d")?.value ?? DEFAULT_WALL_LONGITUDINAL_DIAMETER,
            longitudinalSpacing: document.getElementById("wall-conc-long-s")?.value ?? DEFAULT_WALL_LONGITUDINAL_SPACING,
            transverseDiameter: document.getElementById("wall-conc-trans-d")?.value ?? DEFAULT_WALL_TRANSVERSE_DIAMETER,
            transverseSpacing: document.getElementById("wall-conc-trans-s")?.value ?? DEFAULT_WALL_TRANSVERSE_SPACING
        },
        masonry: {
            blockWidth: document.getElementById("wall-masonry-block-width")?.value ?? DEFAULT_MASONRY_BLOCK_WIDTH,
            fillMode: document.getElementById("wall-masonry-fill")?.value ?? "all",
            barsPerCell: document.getElementById("wall-masonry-bars")?.value ?? DEFAULT_MASONRY_BARS_PER_CELL,
            barDiameter: document.getElementById("wall-masonry-d")?.value ?? DEFAULT_MASONRY_BAR_DIAMETER
        }
    });

    const level = projectState.levels.find((item) => item.id === projectState.editingElement.levelId);
    if (!level) {
        closeModal();
        return;
    }

    const existingWall = level.walls.find((item) => item.id === wall.id);
    if (existingWall && !applySingleEntityEdits("wall", existingWall, wall)) {
        return;
    }

    closeModal();
    updateUI();
    render();
}

async function saveColumnEdits(element, nextColumn) {
    const levelId = getEntityLevelId("column", element);
    const originalName = getColumnSectionName(element);
    const nextName = getColumnSectionName(nextColumn);
    const originalGroupIds = originalName ? getColumnSectionGroupIds(originalName, levelId) : new Set([element.id]);
    const conflictingColumns = nextName
        ? getColumnsWithConflictingSectionByName(nextColumn, originalGroupIds, levelId)
        : [];
    let updatedIds = new Set();

    if (conflictingColumns.length > 0) {
        const shouldUpdateExisting = await requestColumnSectionConflictResolution(nextName);
        if (!shouldUpdateExisting) {
            return false;
        }

        updatedIds = updateColumnSectionsByNames(nextColumn, [originalName, nextName], levelId);
    } else if (originalName) {
        updatedIds = updateColumnSectionsByNames(nextColumn, [originalName], levelId);
    }

    if (!updatedIds.has(element.id)) {
        applyColumnSectionToColumn(element, nextColumn);
    }

    return true;
}

function saveSelectedElementGroupEdits(selectionContext) {
    const records = Array.isArray(selectionContext?.records) ? selectionContext.records : [];
    if (!selectionContext?.isGroupEditable || !records.length) {
        return false;
    }

    const levelsSnapshot = cloneSerializable(projectState.levels);
    const sourceSnapshots = new Map(records.map((record) => ([
        getSelectedElementDescriptorKey(record),
        cloneSerializable(record.entity || {})
    ])));
    const readField = (fieldId, fallback = null) => {
        const value = getDomFieldValueOrNull(fieldId);
        return value === null ? fallback : value;
    };
    const readCheckbox = (fieldId, fallback = null) => {
        const value = getDomCheckboxValueOrNull(fieldId);
        return value === null ? fallback : value;
    };
    const rollbackAndRender = () => {
        projectState.levels = levelsSnapshot;
        updateUI();
        render();
        return false;
    };

    for (const record of records) {
        const source = sourceSnapshots.get(getSelectedElementDescriptorKey(record)) || cloneSerializable(record.entity || {});
        const level = record.level;
        const element = record.entity;

        if (!source?.id || !level || !element) {
            return rollbackAndRender();
        }

        const type = record.type === "column" ? "col" : record.type;

        if (type === "beam") {
            const nextBeam = normalizeBeamModel({
                ...source,
                name: readField("insert-name", source.name),
                b: readField("insert-b", source.b),
                h: readField("insert-h", source.h),
                structuralMaterial: readStructuralMaterialFields(source),
                topRebar: {
                    n: readField("insert-top-n", source.topRebar?.n),
                    d: readField("insert-top-d", source.topRebar?.d)
                },
                botRebar: {
                    n: readField("insert-bot-n", source.botRebar?.n),
                    d: readField("insert-bot-d", source.botRebar?.d)
                },
                stirrups: {
                    d: readField("insert-beam-tr-d", source.stirrups?.d),
                    spacing: readField("insert-beam-tr-s", source.stirrups?.spacing)
                },
                coverTop: readField("insert-beam-cover-top", source.coverTop),
                coverBottom: readField("insert-beam-cover-bottom", source.coverBottom),
                steelDemands: normalizeBeamSteelDemands({
                    iEndTop: readField("insert-beam-demand-i-top", source.steelDemands?.iEndTop),
                    iEndBottom: readField("insert-beam-demand-i-bottom", source.steelDemands?.iEndBottom),
                    midTop: readField("insert-beam-demand-mid-top", source.steelDemands?.midTop),
                    midBottom: readField("insert-beam-demand-mid-bottom", source.steelDemands?.midBottom),
                    jEndTop: readField("insert-beam-demand-j-top", source.steelDemands?.jEndTop),
                    jEndBottom: readField("insert-beam-demand-j-bottom", source.steelDemands?.jEndBottom)
                }),
                additionalRebar: normalizeBeamAdditionalRebar({
                    iEndTop: {
                        n: readField("insert-beam-add-iEnd-top-n", source.additionalRebar?.iEndTop?.n),
                        d: readField("insert-beam-add-iEnd-top-d", source.additionalRebar?.iEndTop?.d)
                    },
                    iEndBottom: {
                        n: readField("insert-beam-add-iEnd-bottom-n", source.additionalRebar?.iEndBottom?.n),
                        d: readField("insert-beam-add-iEnd-bottom-d", source.additionalRebar?.iEndBottom?.d)
                    },
                    midTop: {
                        n: readField("insert-beam-add-mid-top-n", source.additionalRebar?.midTop?.n),
                        d: readField("insert-beam-add-mid-top-d", source.additionalRebar?.midTop?.d)
                    },
                    midBottom: {
                        n: readField("insert-beam-add-mid-bottom-n", source.additionalRebar?.midBottom?.n),
                        d: readField("insert-beam-add-mid-bottom-d", source.additionalRebar?.midBottom?.d)
                    },
                    jEndTop: {
                        n: readField("insert-beam-add-jEnd-top-n", source.additionalRebar?.jEndTop?.n),
                        d: readField("insert-beam-add-jEnd-top-d", source.additionalRebar?.jEndTop?.d)
                    },
                    jEndBottom: {
                        n: readField("insert-beam-add-jEnd-bottom-n", source.additionalRebar?.jEndBottom?.n),
                        d: readField("insert-beam-add-jEnd-bottom-d", source.additionalRebar?.jEndBottom?.d)
                    }
                }),
                sectionCuts: readBeamSectionDetailFields("insert-beam", source)
            });

            if (!applyEntityEdits("beam", element, nextBeam)) {
                return rollbackAndRender();
            }

            element.steelDemands = nextBeam.steelDemands;
            element.additionalRebar = nextBeam.additionalRebar;
            element.sectionCuts = nextBeam.sectionCuts;
            syncBeamAdditionalRebarToConnectedBeams(level, element);

            if (typeof generateAutomaticSectionsForBeam === "function") {
                generateAutomaticSectionsForBeam(element, level.id);
            }
            continue;
        }

        if (type === "col") {
            const nextColumn = normalizeColumnModel({
                ...source,
                name: readField("insert-name", source.name),
                b: readField("insert-b", source.b),
                h: readField("insert-h", source.h),
                structuralMaterial: readStructuralMaterialFields(source),
                longRebar: normalizeColumnLongitudinalRebar({
                    xCount: readField("insert-col-x-count", source.longRebar?.xCount),
                    xDiameter: readField("insert-col-x-d", source.longRebar?.xDiameter),
                    yCount: readField("insert-col-y-count", source.longRebar?.yCount),
                    yDiameter: readField("insert-col-y-d", source.longRebar?.yDiameter),
                    cornerDiameter: readField("insert-col-corner-d", source.longRebar?.cornerDiameter),
                    hasCustomCornerDiameter: readCheckbox("insert-col-corner-custom", source.longRebar?.hasCustomCornerDiameter)
                }),
                stirrups: {
                    d: readField("insert-col-tr-d", source.stirrups?.d),
                    spacing: readField("insert-col-tr-s", source.stirrups?.spacing),
                    count3Dir: readField("insert-col-tr-x", source.stirrups?.count3Dir),
                    count2Dir: readField("insert-col-tr-y", source.stirrups?.count2Dir)
                }
            });

            if (!applyEntityEdits("column", element, nextColumn)) {
                return rollbackAndRender();
            }
            continue;
        }

        if (type === "wall") {
            const nextWall = normalizeWall({
                ...source,
                name: readField("insert-name", source.name),
                b: readField("insert-b", source.b),
                structuralMaterial: readStructuralMaterialFields(source),
                material: readField("insert-wall-material", source.material),
                concrete: {
                    longitudinalDiameter: readField("insert-wall-conc-long-d", source.concrete?.longitudinalDiameter),
                    longitudinalSpacing: readField("insert-wall-conc-long-s", source.concrete?.longitudinalSpacing),
                    transverseDiameter: readField("insert-wall-conc-trans-d", source.concrete?.transverseDiameter),
                    transverseSpacing: readField("insert-wall-conc-trans-s", source.concrete?.transverseSpacing),
                    cover: readField("insert-wall-conc-cover", source.concrete?.cover)
                },
                masonry: {
                    blockWidth: readField("insert-wall-masonry-block-width", source.masonry?.blockWidth),
                    fillMode: readField("insert-wall-masonry-fill", source.masonry?.fillMode),
                    barsPerCell: readField("insert-wall-masonry-bars", source.masonry?.barsPerCell),
                    barDiameter: readField("insert-wall-masonry-d", source.masonry?.barDiameter),
                    horizontalBarDiameter: readField("insert-wall-masonry-h-d", source.masonry?.horizontalBarDiameter),
                    horizontalSpacing: getDomFieldUnitAwareValue("insert-wall-masonry-h-s", source.masonry?.horizontalSpacing),
                    includeTieBeam: document.getElementById("insert-wall-masonry-tie-beam")?.checked !== false
                }
            });

            if (!applyEntityEdits("wall", element, nextWall)) {
                return rollbackAndRender();
            }
            continue;
        }

        if (type === "foundation") {
            const nextFoundation = normalizeFoundation({
                ...source,
                name: readField("insert-name", source.name),
                b: readField("insert-b", source.b),
                h: readField("insert-h", source.h),
                thickness: readField("insert-foundation-thickness", source.thickness),
                structuralMaterial: readStructuralMaterialFields(source),
                solid: readFoundationReinforcementFields("insert-foundation", source)
            });

            if (!applyEntityEdits("foundation", element, nextFoundation)) {
                return rollbackAndRender();
            }
            continue;
        }

        if (type === "slab" || type === "hole") {
            const nextSlab = normalizeSlab({
                ...source,
                name: readField("insert-name", source.name),
                h: readField("insert-h", source.h),
                structuralMaterial: readStructuralMaterialFields(source),
                type: readField("insert-slab-type", source.type),
                actionType: readField("insert-slab-action-type", source.actionType),
                cantilever: document.getElementById("insert-slab-cantilever")?.checked ?? source.cantilever,
                temperatureSteel: readSlabTemperatureFields("insert-slab", source.temperatureSteel),
                solid: {
                    xBarDiameter: readField("insert-slab-solid-x-d", source.solid?.xBarDiameter),
                    xSpacing: readField("insert-slab-solid-x-s", source.solid?.xSpacing),
                    yBarDiameter: readField("insert-slab-solid-y-d", source.solid?.yBarDiameter),
                    ySpacing: readField("insert-slab-solid-y-s", source.solid?.ySpacing),
                    topSteelDirection: readField("insert-slab-solid-top-dir", source.solid?.topSteelDirection)
                },
                lightened: readSlabLightenedFields("insert-slab", source.lightened)
            });

            const sourceType = normalizeSlab(source).type === "hole" ? "hole" : "slab";
            const targetType = nextSlab.type === "hole" ? "hole" : "slab";
            const sourceCollection = getSlabLikeCollection(level, sourceType);
            const targetCollection = getSlabLikeCollection(level, targetType);
            const existing = sourceCollection.find((item) => item.id === element.id);

            if (!existing) {
                return rollbackAndRender();
            }

            if (targetType === "hole" && !canPlaceHoleInLevel(level, nextSlab, new Set([existing.id]))) {
                openAppNoticeDialog({
                    title: translate("dialog.invalidActionTitle") || "Accion invalida",
                    message: translate("errors.holeMustBeInsideSlab")
                });
                return rollbackAndRender();
            }

            if (sourceType === targetType) {
                if (!applyEntityEdits(targetType, element, nextSlab)) {
                    return rollbackAndRender();
                }
            } else {
                if (!canUseEntityDraftName(targetType, nextSlab, new Set([existing.id]))) {
                    return rollbackAndRender();
                }

                const originalIndex = sourceCollection.findIndex((item) => item.id === existing.id);
                if (originalIndex >= 0) {
                    sourceCollection.splice(originalIndex, 1);
                }
                targetCollection.push(normalizeSlab({
                    ...nextSlab,
                    id: existing.id,
                    name: resolveEntityName(targetType, nextSlab.name, nextSlab)
                }));
            }
        }
    }

    clearSelectedElements({ shouldRender: false });
    updateUI();
    render();
    return true;
}

function saveSelectedElementEdits() {
    const selectionContext = getSelectedElementSelectionContext();
    if (selectionContext?.isGroupEditable) {
        saveSelectedElementGroupEdits(selectionContext);
        return;
    }

    const selectedRecord = selectionContext?.primaryRecord || getSelectedElementRecord();
    if (!selectedRecord) {
        return;
    }

    const element = selectedRecord.entity;
    const type = selectedRecord.type === "column" ? "col" : selectedRecord.type;
    const level = selectedRecord.level;

    if (type === "beam") {
        const nextBeam = normalizeBeamModel({
            ...element,
            name: document.getElementById("insert-name")?.value,
            b: document.getElementById("insert-b")?.value,
            h: document.getElementById("insert-h")?.value,
            structuralMaterial: readStructuralMaterialFields(element),
            topRebar: { n: document.getElementById("insert-top-n")?.value, d: document.getElementById("insert-top-d")?.value },
            botRebar: { n: document.getElementById("insert-bot-n")?.value, d: document.getElementById("insert-bot-d")?.value },
            stirrups: { d: document.getElementById("insert-beam-tr-d")?.value, spacing: Number.parseFloat(document.getElementById("insert-beam-tr-s")?.value) },
            coverTop: document.getElementById("insert-beam-cover-top")?.value,
            coverBottom: document.getElementById("insert-beam-cover-bottom")?.value,
            steelDemands: normalizeBeamSteelDemands({
                iEndTop: document.getElementById("insert-beam-demand-i-top")?.value,
                iEndBottom: document.getElementById("insert-beam-demand-i-bottom")?.value,
                midTop: document.getElementById("insert-beam-demand-mid-top")?.value,
                midBottom: document.getElementById("insert-beam-demand-mid-bottom")?.value,
                jEndTop: document.getElementById("insert-beam-demand-j-top")?.value,
                jEndBottom: document.getElementById("insert-beam-demand-j-bottom")?.value
            }),
            additionalRebar: normalizeBeamAdditionalRebar({
                iEndTop: {
                    n: document.getElementById("insert-beam-add-iEnd-top-n")?.value,
                    d: document.getElementById("insert-beam-add-iEnd-top-d")?.value
                },
                iEndBottom: {
                    n: document.getElementById("insert-beam-add-iEnd-bottom-n")?.value,
                    d: document.getElementById("insert-beam-add-iEnd-bottom-d")?.value
                },
                midTop: {
                    n: document.getElementById("insert-beam-add-mid-top-n")?.value,
                    d: document.getElementById("insert-beam-add-mid-top-d")?.value
                },
                midBottom: {
                    n: document.getElementById("insert-beam-add-mid-bottom-n")?.value,
                    d: document.getElementById("insert-beam-add-mid-bottom-d")?.value
                },
                jEndTop: {
                    n: document.getElementById("insert-beam-add-jEnd-top-n")?.value,
                    d: document.getElementById("insert-beam-add-jEnd-top-d")?.value
                },
                jEndBottom: {
                    n: document.getElementById("insert-beam-add-jEnd-bottom-n")?.value,
                    d: document.getElementById("insert-beam-add-jEnd-bottom-d")?.value
                }
            })
        });

        if (!applySingleEntityEdits("beam", element, nextBeam)) {
            return;
        }

        element.steelDemands = nextBeam.steelDemands;
        element.additionalRebar = nextBeam.additionalRebar;
        element.sectionCuts = readBeamSectionDetailFields("insert-beam", element);
        syncBeamAdditionalRebarToConnectedBeams(level, element);

        if (typeof generateAutomaticSectionsForBeam === "function") {
            generateAutomaticSectionsForBeam(element, level.id);
        }
    } else if (type === "col") {
        const longRebar = normalizeColumnLongitudinalRebar({
            xCount: document.getElementById("insert-col-x-count")?.value,
            xDiameter: document.getElementById("insert-col-x-d")?.value,
            yCount: document.getElementById("insert-col-y-count")?.value,
            yDiameter: document.getElementById("insert-col-y-d")?.value,
            cornerDiameter: document.getElementById("insert-col-corner-d")?.value,
            hasCustomCornerDiameter: document.getElementById("insert-col-corner-custom")?.checked
        });
        const stirrups = {
            d: document.getElementById("insert-col-tr-d")?.value,
            spacing: document.getElementById("insert-col-tr-s")?.value,
            count3Dir: document.getElementById("insert-col-tr-x")?.value,
            count2Dir: document.getElementById("insert-col-tr-y")?.value
        };
        const nextColumn = normalizeColumnModel({
            ...element,
            name: document.getElementById("insert-name")?.value,
            b: document.getElementById("insert-b")?.value,
            h: document.getElementById("insert-h")?.value,
            structuralMaterial: readStructuralMaterialFields(element),
            longRebar,
            stirrups
        });

        if (!applySingleEntityEdits("column", element, nextColumn)) {
            return;
        }
    } else if (type === "wall") {
        const nextWall = normalizeWall({
            ...element,
            name: document.getElementById("insert-name")?.value,
            b: document.getElementById("insert-b")?.value,
            structuralMaterial: readStructuralMaterialFields(element),
            material: document.getElementById("insert-wall-material")?.value,
            concrete: {
                longitudinalDiameter: document.getElementById("insert-wall-conc-long-d")?.value,
                longitudinalSpacing: document.getElementById("insert-wall-conc-long-s")?.value,
                transverseDiameter: document.getElementById("insert-wall-conc-trans-d")?.value,
                transverseSpacing: document.getElementById("insert-wall-conc-trans-s")?.value
            },
            masonry: {
                blockWidth: document.getElementById("insert-wall-masonry-block-width")?.value,
                fillMode: document.getElementById("insert-wall-masonry-fill")?.value,
                barsPerCell: document.getElementById("insert-wall-masonry-bars")?.value,
                barDiameter: document.getElementById("insert-wall-masonry-d")?.value
            }
        });

        if (!applySingleEntityEdits("wall", element, nextWall)) {
            return;
        }
    } else if (type === "foundation") {
        const nextFoundation = normalizeFoundation({
            ...element,
            name: document.getElementById("insert-name")?.value,
            b: document.getElementById("insert-b")?.value,
            h: document.getElementById("insert-h")?.value,
            thickness: document.getElementById("insert-foundation-thickness")?.value,
            structuralMaterial: readStructuralMaterialFields(element),
            solid: readFoundationReinforcementFields("insert-foundation", element)
        });

        if (!applySingleEntityEdits("foundation", element, nextFoundation)) {
            return;
        }
    } else if (type === "slab" || type === "hole") {
        const nextSlab = normalizeSlab({
            ...element,
            name: document.getElementById("insert-name")?.value,
            h: document.getElementById("insert-h")?.value,
            structuralMaterial: readStructuralMaterialFields(element),
            type: document.getElementById("insert-slab-type")?.value,
            cantilever: document.getElementById("insert-slab-cantilever")?.checked,
            temperatureSteel: typeof readSlabTemperatureFields === "function" ? readSlabTemperatureFields("insert-slab") : undefined,
            solid: {
                xBarDiameter: document.getElementById("insert-slab-solid-x-d")?.value,
                xSpacing: document.getElementById("insert-slab-solid-x-s")?.value,
                yBarDiameter: document.getElementById("insert-slab-solid-y-d")?.value,
                ySpacing: document.getElementById("insert-slab-solid-y-s")?.value,
                topSteelDirection: document.getElementById("insert-slab-solid-top-dir")?.value
            },
            lightened: readSlabLightenedFields("insert-slab")
        });

        level.slabs = level.slabs || [];
        level.holes = level.holes || [];
        const sourceType = normalizeSlab(element).type === "hole" ? "hole" : "slab";
        const targetType = nextSlab.type === "hole" ? "hole" : "slab";
        const sourceCollection = getSlabLikeCollection(level, sourceType);
        const targetCollection = getSlabLikeCollection(level, targetType);
        const existing = sourceCollection.find((item) => item.id === element.id);
        if (!existing) {
            clearSelectedElements({ shouldRender: false });
            updateUI();
            render();
            return;
        }

        if (targetType === "hole" && !canPlaceHoleInLevel(level, nextSlab, new Set([existing.id]))) {
            openAppNoticeDialog({
                title: translate("dialog.invalidActionTitle") || "Accion invalida",
                message: translate("errors.holeMustBeInsideSlab")
            });
            return;
        }

        if (sourceType === targetType) {
            if (!applySingleEntityEdits(targetType, element, nextSlab)) {
                return;
            }
        } else {
            if (!canUseEntityDraftName(targetType, nextSlab, new Set([existing.id]))) {
                return;
            }

            const originalIndex = sourceCollection.findIndex((item) => item.id === existing.id);
            if (originalIndex >= 0) {
                sourceCollection.splice(originalIndex, 1);
            }
            targetCollection.push(normalizeSlab({
                ...nextSlab,
                id: existing.id,
                name: resolveEntityName(targetType, nextSlab.name, nextSlab)
            }));
        }
    }

    clearSelectedElements({ shouldRender: false });
    updateUI();
    render();
}

async function saveElementEdits() {
    if (!projectState.editingElement) {
        return;
    }

    const element = projectState.editingElement.data;
    if (projectState.editingElement.type === "beam-section") {
        element.sectionCuts = parseSectionCutsInput(document.getElementById("edit-sc").value, element);
        closeModal();
        updateUI();
        render();
        return;
    }

    if (projectState.editingElement.type === "slab-section") {
        saveSlabSectionEdits();
        return;
    }

    if (projectState.editingElement.type === "wall-section") {
        saveWallSectionEdits();
        return;
    }

    if (projectState.editingElement.type === "wall") {
        const nextWall = normalizeWall({
            ...element,
            name: document.getElementById("edit-name")?.value,
            b: document.getElementById("edit-b").value
        });
        if (!applySingleEntityEdits("wall", element, nextWall)) {
            return;
        }
        closeModal();
        updateUI();
        render();
        return;
    }

    const nextName = document.getElementById("edit-name")?.value ?? element.name;
    const nextWidth = document.getElementById("edit-b").value;

    if (projectState.editingElement.type === "beam") {
        const nextBeam = normalizeBeamModel({
            ...element,
            name: nextName,
            b: nextWidth,
            h: document.getElementById("edit-h").value,
            stirrups: {
                d: document.getElementById("edit-tr-d").value,
                spacing: document.getElementById("edit-tr-s").value
            },
            topRebar: {
                n: document.getElementById("edit-ts-n").value,
                d: document.getElementById("edit-ts-d").value
            },
            botRebar: {
                n: document.getElementById("edit-bi-n").value,
                d: document.getElementById("edit-bi-d").value
            }
        });

        if (!applySingleEntityEdits("beam", element, nextBeam)) {
            return;
        }
    } else if (projectState.editingElement.type === "col") {
        const longRebar = normalizeColumnLongitudinalRebar({
            xCount: document.getElementById("edit-col-x-count").value,
            xDiameter: document.getElementById("edit-col-x-d").value,
            yCount: document.getElementById("edit-col-y-count").value,
            yDiameter: document.getElementById("edit-col-y-d").value,
            cornerDiameter: document.getElementById("edit-col-corner-d").value,
            hasCustomCornerDiameter: document.getElementById("edit-col-corner-custom").checked
        });
        const nextColumn = normalizeColumnModel({
            ...element,
            name: nextName,
            b: nextWidth,
            h: document.getElementById("edit-h").value,
            longRebar,
            stirrups: {
                ...(element?.stirrups || {}),
                d: document.getElementById("edit-tr-d").value,
                spacing: document.getElementById("edit-tr-s").value,
                count3Dir: document.getElementById("edit-tr-x").value,
                count2Dir: document.getElementById("edit-tr-y").value
            }
        });

        if (!applySingleEntityEdits("column", element, nextColumn)) {
            return;
        }
    }

    closeModal();
    updateUI();
    render();
}

function closeModal() {
    dom.modalOverlay.style.display = "none";
    projectState.editingElement = null;
}

function generateLevelId() {
    return projectState.levels.reduce((maxId, level) => Math.max(maxId, Number(level.id) || 0), 0) + 1;
}

function getNextLevelName() {
    const nextIndex = projectState.levels.reduce((maxIndex, level) => {
        const match = String(level.name || "").match(/Nivel\s+(\d+)/i);
        return Math.max(maxIndex, match ? Number.parseInt(match[1], 10) : 0);
    }, 0) + 1;

    return `Nivel ${nextIndex}`;
}

function getSuggestedLevelHeight(referenceLevel = getActiveLevel()) {
    const fallback = projectState.levels[projectState.levels.length - 1]?.height ?? 3.0;
    return Math.max(parseNumberOrFallback(referenceLevel?.height, fallback), 0.1);
}

function addLevel() {
    const newLevel = createLevel(generateLevelId(), getNextLevelName(), getSuggestedLevelHeight());
    projectState.levels.push(newLevel);
    projectState.activeLevelId = newLevel.id;
    projectState.firstNode = null;
    updateUI();
    render();
}

function duplicateLevel(levelId) {
    const sourceIndex = projectState.levels.findIndex((level) => level.id === levelId);
    if (sourceIndex < 0) {
        return;
    }

    const sourceLevel = projectState.levels[sourceIndex];
    const duplicate = cloneLevel(sourceLevel, generateLevelId(), getNextLevelName());
    projectState.levels.splice(sourceIndex + 1, 0, duplicate);
    projectState.activeLevelId = duplicate.id;
    projectState.firstNode = null;
    updateUI();
    render();
}

function deleteLevel(levelId) {
    if (projectState.levels.length <= 1) {
        return;
    }

    const sourceIndex = projectState.levels.findIndex((level) => level.id === levelId);
    if (sourceIndex < 0) {
        return;
    }

    if (levelQuickHeightEditorState.levelId === levelId) {
        levelQuickHeightEditorState.levelId = null;
        levelQuickHeightEditorState.draftValue = "";
        levelQuickHeightEditorState.errorMessage = "";
    }

    const wasActive = projectState.activeLevelId === levelId;
    projectState.levels.splice(sourceIndex, 1);

    if (wasActive) {
        const fallbackLevel = projectState.levels[Math.max(0, sourceIndex - 1)] || projectState.levels[0];
        projectState.activeLevelId = fallbackLevel?.id ?? null;
        projectState.firstNode = null;
    }

    updateUI();
    render();
}

function updateLevelName(levelId, value) {
    const level = projectState.levels.find((item) => item.id === levelId);
    if (!level) {
        return;
    }

    const nextName = String(value ?? "").trim();
    if (!nextName) {
        renderLevelsManager();
        return;
    }

    level.name = nextName;
    updateUI();
    render();
}

function moveLevel(levelId, direction) {
    const currentIndex = projectState.levels.findIndex((level) => level.id === levelId);
    if (currentIndex < 0) {
        return;
    }

    const targetIndex = currentIndex + direction;
    if (targetIndex < 0 || targetIndex >= projectState.levels.length) {
        return;
    }

    const [movedLevel] = projectState.levels.splice(currentIndex, 1);
    projectState.levels.splice(targetIndex, 0, movedLevel);
    updateUI();
    render();
}

function updateLevelHeight(levelId, value) {
    const level = projectState.levels.find((item) => item.id === levelId);
    const parsedValue = Number.parseFloat(String(value).replace(",", "."));

    if (!level || Number.isNaN(parsedValue) || parsedValue <= 0) {
        renderLevelsManager();
        return;
    }

    if (levelQuickHeightEditorState.levelId === levelId) {
        levelQuickHeightEditorState.levelId = null;
        levelQuickHeightEditorState.draftValue = "";
        levelQuickHeightEditorState.errorMessage = "";
    }

    level.height = Number(parsedValue.toFixed(2));
    updateUI();
    render();
}

function resetLevelQuickHeightEditorState() {
    levelQuickHeightEditorState.levelId = null;
    levelQuickHeightEditorState.draftValue = "";
    levelQuickHeightEditorState.errorMessage = "";
}

function closeLevelQuickHeightEditor(options = {}) {
    const shouldRender = options.shouldRender !== false;
    if (levelQuickHeightEditorState.levelId === null) {
        return false;
    }

    resetLevelQuickHeightEditorState();
    if (shouldRender) {
        renderLevelList();
    }

    return true;
}

function focusLevelQuickHeightEditor(levelId) {
    if (!isBrowser) {
        return;
    }

    window.requestAnimationFrame(() => {
        const input = document.getElementById(`level-quick-height-input-${levelId}`);
        if (!(input instanceof HTMLInputElement)) {
            return;
        }

        input.focus();
        input.select();
    });
}

function openLevelQuickHeightEditor(levelId) {
    const level = projectState.levels.find((item) => item.id === levelId);
    if (!level) {
        return;
    }

    levelQuickHeightEditorState.levelId = levelId;
    levelQuickHeightEditorState.draftValue = level.height.toFixed(2);
    levelQuickHeightEditorState.errorMessage = "";
    renderLevelList();
    focusLevelQuickHeightEditor(levelId);
}

function toggleLevelQuickHeightEditor(levelId) {
    if (levelQuickHeightEditorState.levelId === levelId) {
        closeLevelQuickHeightEditor();
        return;
    }

    openLevelQuickHeightEditor(levelId);
}

function submitLevelQuickHeightEditor(levelId) {
    const level = projectState.levels.find((item) => item.id === levelId);
    if (!level) {
        closeLevelQuickHeightEditor();
        return;
    }

    const parsedValue = Number.parseFloat(String(levelQuickHeightEditorState.draftValue).replace(",", "."));
    if (!Number.isFinite(parsedValue) || parsedValue <= 0) {
        levelQuickHeightEditorState.errorMessage = translate("levels.invalidHeightMessage");
        renderLevelList();
        focusLevelQuickHeightEditor(levelId);
        return;
    }

    closeLevelQuickHeightEditor({ shouldRender: false });
    updateLevelHeight(levelId, parsedValue);
}

function updateUI() {
    normalizeOutputSelections();
    pruneHiddenSelectedElements({ shouldRender: false });
    renderProjectControls();
    renderMaterialPricesMenu();
    renderModelSpaceThemeControl();
    renderModelSpaceLabelsControl();
    renderModelSpaceLabelsMenu();
    renderModelSpaceElementsControl();
    renderModelSpaceElementsMenu();
    renderModelSpaceSteelControl();
    renderWorkspaceLevelNavigator();
    renderSelectedElementIndicator();
    renderInsertPropertiesPanel();
    renderSectionPreviewPanel();
    renderQuantitiesSection();
    renderAxisList("x", dom.axisListX);
    renderAxisList("y", dom.axisListY);
    renderReferenceAxisList("x", dom.referenceAxisListX);
    renderReferenceAxisList("y", dom.referenceAxisListY);
    renderLevelList();
    renderLevelsManager();
    renderExportOptions();
    renderExportDockPanel();
    renderBillingUi();
    renderSupportUi();
    renderDownloadFeedbackUi();
    renderWorkspaceEntryChoice();
    renderWorkspaceGuide();
    captureProjectHistoryCheckpoint();
    renderProjectHistoryControls();
    renderWorkspace3DUi();
    renderStructuralAnalysisUi();
    renderApuElementUi();
    syncWorkspace3DScene();
    syncProjectAutosave();
}

function getInsertPanelConfig() {
    const selectionContext = getSelectedElementSelectionContext();
    if (selectionContext?.isGroupEditable) {
        return {
            mode: "edit",
            type: selectionContext.builderType,
            levelId: selectionContext.levelId,
            title: getSelectionGroupTitle(selectionContext),
            draft: selectionContext.primaryRecord?.entity,
            isSelectionGroup: true,
            selectionContext
        };
    }

    if (selectionContext?.isMixedSelection) {
        return null;
    }

    const selectedRecord = selectionContext?.primaryRecord || getSelectedElementRecord();
    if (selectedRecord && ["col", "column", "beam", "wall", "foundation", "slab", "hole"].includes(selectedRecord.type)) {
        const type = selectedRecord.type === "column"
            ? "col"
            : selectedRecord.type === "hole"
                ? "slab"
                : selectedRecord.type;
        const titleKey = type === "col" ? "modal.editColumn"
            : type === "wall" ? "modal.editWall"
                : type === "foundation" ? "modal.editFoundation"
                    : type === "slab" && selectedRecord.type === "hole" ? "modal.editHole"
                        : type === "slab" ? "modal.editSlab"
                        : "modal.editBeam";

        return {
            mode: "edit",
            type: type,
            levelId: selectedRecord.level.id,
            title: translate(titleKey) || `Editar ${type}`,
            draft: selectedRecord.entity,
            selectionContext: selectionContext || null
        };
    }

    if (!MODEL_SIDEBAR_MODES.includes(projectState.sidebarMode)) {
        return null;
    }

    if (!["col", "beam", "wall", "foundation", "slab"].includes(projectState.tool)) {
        return null;
    }

    return {
        mode: "insert",
        type: projectState.tool,
        title: projectState.tool === "slab" && projectState.insertDrafts.slab?.type === "hole"
            ? translate("insert.title.hole")
            : translate(`insert.title.${projectState.tool}`),
        draft: projectState.insertDrafts[projectState.tool]
    };
}

function renderInsertPropertiesPanel() {
    if (!dom.insertPropertiesDock || !dom.insertPropertiesFields || !dom.insertPropertiesTitle || !dom.insertPropertiesNote || !dom.insertPropertiesKicker) {
        return;
    }

    const config = getInsertPanelConfig();
    if (!config) {
        dom.insertPropertiesDock.hidden = true;
        replaceChildrenCompat(dom.insertPropertiesFields);
        return;
    }

    dom.insertPropertiesDock.hidden = false;
    const selectionContext = config.selectionContext || getSelectedElementSelectionContext();
    const selectionFeedback = config.mode === "edit" ? getSelectionFeedbackStrings(selectionContext) : null;
    dom.insertPropertiesKicker.textContent = config.mode === "edit"
        ? config.isSelectionGroup
            ? selectionFeedback?.kicker || (projectState.language === "en" ? "MULTIPLE SELECTION" : "SELECCION MULTIPLE")
            : "PROPIEDADES"
        : translate("insert.kicker");
    dom.insertPropertiesTitle.textContent = config.title;
    const isHoleDraft = config.draft?.type === "hole";
    dom.insertPropertiesNote.hidden = config.mode === "edit" && !isHoleDraft && !config.isSelectionGroup;
    if (config.mode === "insert") {
        dom.insertPropertiesNote.textContent = isHoleDraft
            ? translate("insert.note.hole")
            : config.type === "foundation"
            ? translate("insert.note.foundation")
            : translate("insert.autoNameHint");
    } else if (config.isSelectionGroup) {
        dom.insertPropertiesNote.textContent = selectionFeedback?.note || "";
    } else if (isHoleDraft) {
        dom.insertPropertiesNote.textContent = translate("modal.holeNote");
    }

    let markup = buildInsertPropertiesFieldsMarkup(config.type, config.draft);
    if (config.mode === "edit") {
        markup += `
            <div class="insert-properties-actions" style="margin-top: 16px; display: flex; gap: 8px;">
                <button type="button" class="button" id="edit-panel-save" style="flex: 1; min-height: 32px; font-size: 13px;">Guardar</button>
                <button type="button" class="button button-outline" id="edit-panel-cancel" style="flex: 1; min-height: 32px; font-size: 13px;">Cancelar</button>
            </div>
        `;
    }

    dom.insertPropertiesFields.innerHTML = markup;
    if (config.isSelectionGroup) {
        applySelectionGroupFieldStates(selectionContext?.records || []);
    }

    if (config.isSelectionGroup) {
        const hideActionBlock = (selector) => {
            const target = dom.insertPropertiesFields.querySelector(selector);
            if (!target) {
                return;
            }

            const actionBlock = target.closest(".insert-properties-block");
            if (actionBlock) {
                actionBlock.hidden = true;
            } else {
                target.hidden = true;
            }
        };

        hideActionBlock("#edit-panel-section");
        if (config.type === "beam") {
            dom.insertPropertiesFields.querySelector(".beam-section-details-block")?.setAttribute("hidden", "");
        }
    }

    const reinforcementPanel = dom.insertPropertiesFields.querySelector("[data-reinforcement-panel='true']");
    if (reinforcementPanel) {
        if (reinforcementPanel.dataset.panelDisabled !== "true") {
            reinforcementPanel.open = projectState.insertPropertiesReinforcementOpen;
            reinforcementPanel.addEventListener("toggle", () => {
                projectState.insertPropertiesReinforcementOpen = reinforcementPanel.open;
            });
        } else {
            reinforcementPanel.open = false;
        }
    }

    if (!config.isSelectionGroup) {
        bindSectionPreviewLiveUpdates();
    }
    wireStructuralMaterialFields(dom.insertPropertiesFields);

    if (config.mode === "edit") {
        if (config.type === "col") {
            wireColumnLongitudinalFields("insert-col", config.isSelectionGroup ? null : () => {
                renderSectionPreviewPanel();
            });
        }
        if (config.type === "beam") {
            if (!config.isSelectionGroup) {
                const syncBeamDraftFromPanel = (sectionCuts = readBeamSectionDetailFields("insert-beam", config.draft)) => {
                    Object.assign(config.draft, normalizeBeamModel({
                        ...config.draft,
                        name: document.getElementById("insert-name")?.value,
                        b: document.getElementById("insert-b")?.value,
                        h: document.getElementById("insert-h")?.value,
                        topRebar: {
                            n: document.getElementById("insert-top-n")?.value,
                            d: document.getElementById("insert-top-d")?.value
                        },
                        botRebar: {
                            n: document.getElementById("insert-bot-n")?.value,
                            d: document.getElementById("insert-bot-d")?.value
                        },
                        stirrups: {
                            d: document.getElementById("insert-beam-tr-d")?.value,
                            spacing: document.getElementById("insert-beam-tr-s")?.value
                        },
                        coverTop: document.getElementById("insert-beam-cover-top")?.value,
                        coverBottom: document.getElementById("insert-beam-cover-bottom")?.value,
                        steelDemands: normalizeBeamSteelDemands({
                            iEndTop: document.getElementById("insert-beam-demand-i-top")?.value,
                            iEndBottom: document.getElementById("insert-beam-demand-i-bottom")?.value,
                            midTop: document.getElementById("insert-beam-demand-mid-top")?.value,
                            midBottom: document.getElementById("insert-beam-demand-mid-bottom")?.value,
                            jEndTop: document.getElementById("insert-beam-demand-j-top")?.value,
                            jEndBottom: document.getElementById("insert-beam-demand-j-bottom")?.value
                        }),
                        additionalRebar: normalizeBeamAdditionalRebar({
                            iEndTop: {
                                n: document.getElementById("insert-beam-add-iEnd-top-n")?.value,
                                d: document.getElementById("insert-beam-add-iEnd-top-d")?.value
                            },
                            iEndBottom: {
                                n: document.getElementById("insert-beam-add-iEnd-bottom-n")?.value,
                                d: document.getElementById("insert-beam-add-iEnd-bottom-d")?.value
                            },
                            midTop: {
                                n: document.getElementById("insert-beam-add-mid-top-n")?.value,
                                d: document.getElementById("insert-beam-add-mid-top-d")?.value
                            },
                            midBottom: {
                                n: document.getElementById("insert-beam-add-mid-bottom-n")?.value,
                                d: document.getElementById("insert-beam-add-mid-bottom-d")?.value
                            },
                            jEndTop: {
                                n: document.getElementById("insert-beam-add-jEnd-top-n")?.value,
                                d: document.getElementById("insert-beam-add-jEnd-top-d")?.value
                            },
                            jEndBottom: {
                                n: document.getElementById("insert-beam-add-jEnd-bottom-n")?.value,
                                d: document.getElementById("insert-beam-add-jEnd-bottom-d")?.value
                            }
                        }),
                        sectionCuts
                    }));
                };

                Array.from(dom.insertPropertiesFields.querySelectorAll("[data-beam-section-detail-delete]")).forEach((button) => {
                    button.addEventListener("click", () => {
                        const deleteIndex = Number.parseInt(button.dataset.beamSectionDetailDelete || "-1", 10);
                        const nextCuts = readBeamSectionDetailFields("insert-beam", config.draft);
                        syncBeamDraftFromPanel(normalizeSectionCuts(
                            nextCuts.filter((_, index) => index !== deleteIndex),
                            config.draft
                        ));
                        updateUI();
                        render();
                    });
                });
            }
        }
        if (config.type === "wall") {
            wireWallTypeFields("insert-wall-material", dom.insertPropertiesFields);
        }
        if (config.type === "slab") {
            wireSlabTypeFields("insert-slab-type", dom.insertPropertiesFields);
            wireSlabTemperatureFields("insert-slab", dom.insertPropertiesFields, null, {
                preserveBlankDirection: Boolean(config.isSelectionGroup)
            });
        }
        document.getElementById("edit-panel-save")?.addEventListener("click", saveSelectedElementEdits);
        document.getElementById("edit-panel-cancel")?.addEventListener("click", () => {
            clearSelectedElements({ shouldRender: false });
            updateUI();
            render();
        });
        if (!config.isSelectionGroup) {
            document.getElementById("edit-panel-section")?.addEventListener("click", () => {
                if (config.type === "beam") {
                    openSectionCutsModal(config.draft, 0.5);
                } else if (config.type === "wall") {
                    openWallSectionModal(config.draft, config.levelId);
                } else if (config.type === "slab") {
                    openSlabSectionModal(config.draft, false, config.levelId);
                }
            });
        }
    } else {
        wireInsertPropertiesFields(config.type);
    }

    if (config.isSelectionGroup && config.type === "col") {
        applySelectionGroupFieldStates(selectionContext?.records || []);
    }
}

function bindSectionPreviewLiveUpdates() {
    if (!dom.insertPropertiesFields) {
        return;
    }

    const refreshSectionPreview = () => renderSectionPreviewPanel();
    Array.from(dom.insertPropertiesFields.querySelectorAll("input, select, textarea")).forEach((field) => {
        field.addEventListener("input", refreshSectionPreview);
        field.addEventListener("change", refreshSectionPreview);
    });
}

function getSectionPreviewConfig() {
    const config = getInsertPanelConfig();
    if (!config || config.isSelectionGroup || !["col", "beam", "wall", "foundation", "slab"].includes(config.type)) {
        return null;
    }

    return {
        ...config,
        draft: readSectionPreviewDraft(config)
    };
}

function readSectionPreviewDraft(config) {
    if (!config) {
        return null;
    }

    if (config.type === "col") {
        return readColumnSectionPreviewDraft(config);
    }

    if (config.type === "beam") {
        return readBeamSectionPreviewDraft(config);
    }

    if (config.type === "wall") {
        return readWallSectionPreviewDraft(config);
    }

    if (config.type === "foundation") {
        return readFoundationSectionPreviewDraft(config);
    }

    if (config.type === "slab") {
        return readSlabSectionPreviewDraft(config);
    }

    return null;
}

function readColumnSectionPreviewDraft(config) {
    const source = config?.draft || {};
    if (!dom.insertPropertiesFields || dom.insertPropertiesDock?.hidden) {
        return normalizeColumnInsertDraft(source);
    }

    const longRebar = normalizeColumnLongitudinalRebar({
        xCount: document.getElementById("insert-col-x-count")?.value ?? source?.longRebar?.xCount,
        xDiameter: document.getElementById("insert-col-x-d")?.value ?? source?.longRebar?.xDiameter,
        yCount: document.getElementById("insert-col-y-count")?.value ?? source?.longRebar?.yCount,
        yDiameter: document.getElementById("insert-col-y-d")?.value ?? source?.longRebar?.yDiameter,
        cornerDiameter: document.getElementById("insert-col-corner-d")?.value ?? source?.longRebar?.cornerDiameter,
        hasCustomCornerDiameter: document.getElementById("insert-col-corner-custom")?.checked ?? source?.longRebar?.hasCustomCornerDiameter
    });

    return normalizeColumnInsertDraft({
        ...source,
        name: document.getElementById("insert-name")?.value ?? source.name,
        b: document.getElementById("insert-b")?.value ?? source.b,
        h: document.getElementById("insert-h")?.value ?? source.h,
        structuralMaterial: readStructuralMaterialFields(source),
        longRebar,
        stirrups: {
            ...(source?.stirrups || {}),
            d: document.getElementById("insert-col-tr-d")?.value ?? source?.stirrups?.d,
            spacing: document.getElementById("insert-col-tr-s")?.value ?? source?.stirrups?.spacing,
            count3Dir: document.getElementById("insert-col-tr-x")?.value ?? source?.stirrups?.count3Dir,
            count2Dir: document.getElementById("insert-col-tr-y")?.value ?? source?.stirrups?.count2Dir,
            count: source?.stirrups?.count
        }
    });
}

function readBeamSectionPreviewDraft(config) {
    const source = config?.draft || {};
    if (!dom.insertPropertiesFields || dom.insertPropertiesDock?.hidden) {
        return source?.id ? normalizeBeamModel(source) : normalizeBeamInsertDraft(source);
    }

    const nextBeam = {
        ...source,
        name: document.getElementById("insert-name")?.value ?? source.name,
        b: document.getElementById("insert-b")?.value ?? source.b,
        h: document.getElementById("insert-h")?.value ?? source.h,
        structuralMaterial: readStructuralMaterialFields(source),
        topRebar: {
            n: document.getElementById("insert-top-n")?.value ?? source?.topRebar?.n,
            d: document.getElementById("insert-top-d")?.value ?? source?.topRebar?.d
        },
        botRebar: {
            n: document.getElementById("insert-bot-n")?.value ?? source?.botRebar?.n,
            d: document.getElementById("insert-bot-d")?.value ?? source?.botRebar?.d
        },
        stirrups: {
            d: document.getElementById("insert-beam-tr-d")?.value ?? source?.stirrups?.d,
            spacing: document.getElementById("insert-beam-tr-s")?.value ?? source?.stirrups?.spacing
        },
        coverTop: document.getElementById("insert-beam-cover-top")?.value ?? source?.coverTop,
        coverBottom: document.getElementById("insert-beam-cover-bottom")?.value ?? source?.coverBottom,
        steelDemands: normalizeBeamSteelDemands({
            iEndTop: document.getElementById("insert-beam-demand-i-top")?.value ?? source?.steelDemands?.iEndTop,
            iEndBottom: document.getElementById("insert-beam-demand-i-bottom")?.value ?? source?.steelDemands?.iEndBottom,
            midTop: document.getElementById("insert-beam-demand-mid-top")?.value ?? source?.steelDemands?.midTop,
            midBottom: document.getElementById("insert-beam-demand-mid-bottom")?.value ?? source?.steelDemands?.midBottom,
            jEndTop: document.getElementById("insert-beam-demand-j-top")?.value ?? source?.steelDemands?.jEndTop,
            jEndBottom: document.getElementById("insert-beam-demand-j-bottom")?.value ?? source?.steelDemands?.jEndBottom
        }),
        additionalRebar: normalizeBeamAdditionalRebar({
            iEndTop: {
                n: document.getElementById("insert-beam-add-iEnd-top-n")?.value ?? source?.additionalRebar?.iEndTop?.n,
                d: document.getElementById("insert-beam-add-iEnd-top-d")?.value ?? source?.additionalRebar?.iEndTop?.d
            },
            iEndBottom: {
                n: document.getElementById("insert-beam-add-iEnd-bottom-n")?.value ?? source?.additionalRebar?.iEndBottom?.n,
                d: document.getElementById("insert-beam-add-iEnd-bottom-d")?.value ?? source?.additionalRebar?.iEndBottom?.d
            },
            midTop: {
                n: document.getElementById("insert-beam-add-mid-top-n")?.value ?? source?.additionalRebar?.midTop?.n,
                d: document.getElementById("insert-beam-add-mid-top-d")?.value ?? source?.additionalRebar?.midTop?.d
            },
            midBottom: {
                n: document.getElementById("insert-beam-add-mid-bottom-n")?.value ?? source?.additionalRebar?.midBottom?.n,
                d: document.getElementById("insert-beam-add-mid-bottom-d")?.value ?? source?.additionalRebar?.midBottom?.d
            },
            jEndTop: {
                n: document.getElementById("insert-beam-add-jEnd-top-n")?.value ?? source?.additionalRebar?.jEndTop?.n,
                d: document.getElementById("insert-beam-add-jEnd-top-d")?.value ?? source?.additionalRebar?.jEndTop?.d
            },
            jEndBottom: {
                n: document.getElementById("insert-beam-add-jEnd-bottom-n")?.value ?? source?.additionalRebar?.jEndBottom?.n,
                d: document.getElementById("insert-beam-add-jEnd-bottom-d")?.value ?? source?.additionalRebar?.jEndBottom?.d
            }
        })
    };

    return source?.id ? normalizeBeamModel(nextBeam) : normalizeBeamInsertDraft(nextBeam);
}

function readWallSectionPreviewDraft(config) {
    const source = config?.draft || {};
    if (!dom.insertPropertiesFields || dom.insertPropertiesDock?.hidden) {
        return normalizeWall(source);
    }

    return normalizeWall({
        ...source,
        name: document.getElementById("insert-name")?.value ?? source.name,
        b: document.getElementById("insert-b")?.value ?? source.b,
        structuralMaterial: readStructuralMaterialFields(source),
        material: document.getElementById("insert-wall-material")?.value ?? source.material,
        concrete: {
            longitudinalDiameter: document.getElementById("insert-wall-conc-long-d")?.value ?? source?.concrete?.longitudinalDiameter,
            longitudinalSpacing: document.getElementById("insert-wall-conc-long-s")?.value ?? source?.concrete?.longitudinalSpacing,
            transverseDiameter: document.getElementById("insert-wall-conc-trans-d")?.value ?? source?.concrete?.transverseDiameter,
            transverseSpacing: document.getElementById("insert-wall-conc-trans-s")?.value ?? source?.concrete?.transverseSpacing
        },
        masonry: {
            blockWidth: document.getElementById("insert-wall-masonry-block-width")?.value ?? source?.masonry?.blockWidth,
            fillMode: document.getElementById("insert-wall-masonry-fill")?.value ?? source?.masonry?.fillMode,
            barsPerCell: document.getElementById("insert-wall-masonry-bars")?.value ?? source?.masonry?.barsPerCell,
            barDiameter: document.getElementById("insert-wall-masonry-d")?.value ?? source?.masonry?.barDiameter,
            horizontalBarDiameter: document.getElementById("insert-wall-masonry-h-d")?.value ?? source?.masonry?.horizontalBarDiameter,
            horizontalSpacing: getDomFieldUnitAwareValue("insert-wall-masonry-h-s", source?.masonry?.horizontalSpacing),
            includeTieBeam: document.getElementById("insert-wall-masonry-tie-beam")?.checked !== false
        }
    });
}

function readFoundationSectionPreviewDraft(config) {
    const source = config?.draft || {};
    if (!dom.insertPropertiesFields || dom.insertPropertiesDock?.hidden) {
        return source?.id ? normalizeFoundation(source) : normalizeFoundationInsertDraft(source);
    }

    const nextFoundation = {
        ...source,
        name: document.getElementById("insert-name")?.value ?? source.name,
        b: document.getElementById("insert-b")?.value ?? source.b,
        h: document.getElementById("insert-h")?.value ?? source.h,
        thickness: document.getElementById("insert-foundation-thickness")?.value ?? source.thickness,
        structuralMaterial: readStructuralMaterialFields(source),
        solid: readFoundationReinforcementFields("insert-foundation", source)
    };

    return source?.id ? normalizeFoundation(nextFoundation) : normalizeFoundationInsertDraft(nextFoundation);
}

function readSlabSectionPreviewDraft(config) {
    const source = config?.draft || {};
    if (!dom.insertPropertiesFields || dom.insertPropertiesDock?.hidden) {
        return source?.id ? normalizeSlab(source) : normalizeSlabInsertDraft(source);
    }

    const nextSlab = {
        ...source,
        name: document.getElementById("insert-name")?.value ?? source.name,
        h: document.getElementById("insert-h")?.value ?? source.h,
        structuralMaterial: readStructuralMaterialFields(source),
        type: document.getElementById("insert-slab-type")?.value ?? source.type,
        actionType: document.getElementById("insert-slab-action-type")?.value ?? source.actionType,
        cantilever: document.getElementById("insert-slab-cantilever")?.checked ?? source.cantilever,
        temperatureSteel: readSlabTemperatureFields("insert-slab"),
        solid: {
            xBarDiameter: document.getElementById("insert-slab-solid-x-d")?.value ?? source?.solid?.xBarDiameter,
            xSpacing: document.getElementById("insert-slab-solid-x-s")?.value ?? source?.solid?.xSpacing,
            yBarDiameter: document.getElementById("insert-slab-solid-y-d")?.value ?? source?.solid?.yBarDiameter,
            ySpacing: document.getElementById("insert-slab-solid-y-s")?.value ?? source?.solid?.ySpacing,
            topSteelDirection: document.getElementById("insert-slab-solid-top-dir")?.value ?? source?.solid?.topSteelDirection
        },
        lightened: readSlabLightenedFields("insert-slab")
    };

    return source?.id ? normalizeSlab(nextSlab) : normalizeSlabInsertDraft(nextSlab);
}

function normalizePreviewLabelText(label) {
    return String(label || "").replace(/:\s*$/, "").trim();
}

function buildSectionPreviewPillsMarkup(width, height) {
    return `
        <span class="section-preview-pill">b ${escapeHtml(width.toFixed(2))} m</span>
        <span class="section-preview-pill">h ${escapeHtml(height.toFixed(2))} m</span>
    `;
}

function buildSectionPreviewRowMarkup(label, value) {
    if (!value) {
        return "";
    }

    return `
        <div class="section-preview-row">
            <div class="section-preview-row-label">${escapeHtml(normalizePreviewLabelText(label))}</div>
            <div class="section-preview-row-value">${escapeHtml(value)}</div>
        </div>
    `;
}

function getSectionPreviewDisplayTitle(config, section) {
    const sectionName = normalizeTextValue(section?.name);
    if (sectionName) {
        return `${getEntityTypeLabel(config.type)} ${sectionName}`;
    }

    return config.mode === "insert" ? config.title : getEntityTypeLabel(config.type);
}

function getGenericSectionPreviewRect(width, height, maxWidth = 176, maxHeight = 124) {
    const normalizedWidth = Math.max(parsePositiveNumberOrFallback(width, 0.3), 0.1);
    const normalizedHeight = Math.max(parsePositiveNumberOrFallback(height, 0.3), 0.1);
    const scaleFactor = Math.min(maxWidth / normalizedWidth, maxHeight / normalizedHeight);

    return {
        width: normalizedWidth * scaleFactor,
        height: normalizedHeight * scaleFactor
    };
}

function getSectionPreviewScaleFactor(sectionRect, width, height) {
    const normalizedWidth = Math.max(parsePositiveNumberOrFallback(width, 0.3), 0.1);
    const normalizedHeight = Math.max(parsePositiveNumberOrFallback(height, 0.3), 0.1);
    return Math.min(sectionRect.width / normalizedWidth, sectionRect.height / normalizedHeight);
}

function getSectionPreviewBarRadius(diameterLabel, pixelsPerMeter, minimumRadius = 1.2) {
    return Math.max((parseDiameterInMeters(diameterLabel) * pixelsPerMeter) / 2, minimumRadius);
}

function buildSectionPreviewDimensionMarkup(left, top, right, bottom, widthText, heightText) {
    const horizontalY = top - 18;
    const verticalX = right + 22;
    const centerX = (left + right) / 2;
    const centerY = (top + bottom) / 2;
    const verticalLabelX = verticalX + 12;

    return `
        <line class="section-preview-diagram-dim" x1="${left}" y1="${horizontalY}" x2="${right}" y2="${horizontalY}"></line>
        <line class="section-preview-diagram-dim" x1="${left}" y1="${horizontalY + 6}" x2="${left}" y2="${top}"></line>
        <line class="section-preview-diagram-dim" x1="${right}" y1="${horizontalY + 6}" x2="${right}" y2="${top}"></line>
        <text class="section-preview-diagram-text" x="${centerX}" y="${horizontalY - 6}" text-anchor="middle">${escapeHtml(widthText)}</text>
        <line class="section-preview-diagram-dim" x1="${verticalX}" y1="${top}" x2="${verticalX}" y2="${bottom}"></line>
        <line class="section-preview-diagram-dim" x1="${right + 6}" y1="${top}" x2="${verticalX}" y2="${top}"></line>
        <line class="section-preview-diagram-dim" x1="${right + 6}" y1="${bottom}" x2="${verticalX}" y2="${bottom}"></line>
        <text class="section-preview-diagram-text" x="${verticalLabelX}" y="${centerY}" text-anchor="middle" dominant-baseline="middle" transform="rotate(90 ${verticalLabelX} ${centerY})">${escapeHtml(heightText)}</text>
    `;
}

function buildSectionPreviewHorizontalDimensionMarkup(left, top, right, label) {
    const dimensionY = top - 18;
    const centerX = (left + right) / 2;

    return `
        <line class="section-preview-diagram-dim" x1="${left}" y1="${dimensionY}" x2="${right}" y2="${dimensionY}"></line>
        <line class="section-preview-diagram-dim" x1="${left}" y1="${dimensionY + 6}" x2="${left}" y2="${top}"></line>
        <line class="section-preview-diagram-dim" x1="${right}" y1="${dimensionY + 6}" x2="${right}" y2="${top}"></line>
        <text class="section-preview-diagram-text" x="${centerX}" y="${dimensionY - 6}" text-anchor="middle">${escapeHtml(label)}</text>
    `;
}

function buildSectionPreviewVerticalDimensionMarkup(left, top, bottom, label) {
    const dimensionX = left + 22;
    const centerY = (top + bottom) / 2;
    const labelX = dimensionX + 12;

    return `
        <line class="section-preview-diagram-dim" x1="${dimensionX}" y1="${top}" x2="${dimensionX}" y2="${bottom}"></line>
        <line class="section-preview-diagram-dim" x1="${left + 6}" y1="${top}" x2="${dimensionX}" y2="${top}"></line>
        <line class="section-preview-diagram-dim" x1="${left + 6}" y1="${bottom}" x2="${dimensionX}" y2="${bottom}"></line>
        <text class="section-preview-diagram-text" x="${labelX}" y="${centerY}" text-anchor="middle" dominant-baseline="middle" transform="rotate(90 ${labelX} ${centerY})">${escapeHtml(label)}</text>
    `;
}

function formatStructuralStrengthLabel(value) {
    return formatMaterialStrengthForUnit(value) || "--";
}

function getStructuralMaterialTypeLabel(materialSpec) {
    const normalized = normalizeStructuralMaterialSpec(materialSpec);
    return normalized.type === "steel"
        ? translate("modal.materialSteel")
        : translate("modal.materialConcrete");
}

function buildStructuralMaterialSummaryRows(materialSpec) {
    const normalized = normalizeStructuralMaterialSpec(materialSpec);
    const rows = [
        buildSectionPreviewRowMarkup(translate("modal.materialType"), getStructuralMaterialTypeLabel(normalized))
    ];

    if (normalized.type !== "steel") {
        rows.push(
            buildSectionPreviewRowMarkup(translate("modal.concreteStrength"), formatStructuralStrengthLabel(normalized.concreteStrength)),
            buildSectionPreviewRowMarkup(translate("modal.longitudinalSteelStrength"), formatStructuralStrengthLabel(normalized.longitudinalSteelStrength)),
            buildSectionPreviewRowMarkup(translate("modal.transverseSteelStrength"), formatStructuralStrengthLabel(normalized.transverseSteelStrength))
        );
    }

    return rows;
}

function buildColumnSectionPreviewFigure(column) {
    const normalizedColumn = normalizeColumnInsertDraft(column);
    const structuralMaterial = normalizeStructuralMaterialSpec(normalizedColumn.structuralMaterial);
    const longRebar = normalizeColumnLongitudinalRebar(normalizedColumn.longRebar);
    const stirrups = normalizeColumnTransverseRebar(normalizedColumn.stirrups, longRebar);
    const sectionRect = getColumnPreviewSectionRect(normalizedColumn, 176, 124);
    const pixelsPerMeter = getSectionPreviewScaleFactor(sectionRect, getColumnWidth(normalizedColumn), getColumnHeight(normalizedColumn));
    const left = 44 + (176 - sectionRect.width) / 2;
    const top = 54 + (124 - sectionRect.height) / 2;
    const right = left + sectionRect.width;
    const bottom = top + sectionRect.height;
    const cover = Math.min(
        getColumnSectionClearCover(stirrups) * pixelsPerMeter,
        Math.max(Math.min(sectionRect.width, sectionRect.height) / 2 - 6, 2)
    );
    const stirrupLeft = left + cover;
    const stirrupRight = right - cover;
    const stirrupTop = top + cover;
    const stirrupBottom = bottom - cover;
    const confinementLayout = getColumnConfinementLayout(stirrups, longRebar, stirrupLeft, stirrupBottom, stirrupRight, stirrupTop);
    const barPositions = getColumnBarPositions(
        longRebar,
        stirrupLeft,
        stirrupBottom,
        stirrupRight,
        stirrupTop,
        (diameter) => getSectionPreviewBarRadius(diameter, pixelsPerMeter)
    );

    return `
        <svg viewBox="0 0 320 220" role="img" aria-label="${escapeHtml(formatSectionDimensionsText(getColumnWidth(normalizedColumn), getColumnHeight(normalizedColumn)))}">
            ${buildSectionPreviewDimensionMarkup(
        left,
        top,
        right,
        bottom,
        `b = ${getColumnWidth(normalizedColumn).toFixed(2)}m`,
        `h = ${getColumnHeight(normalizedColumn).toFixed(2)}m`
    )}
            <rect class="section-preview-diagram-concrete" x="${left}" y="${top}" width="${sectionRect.width}" height="${sectionRect.height}"></rect>
            ${structuralMaterial.type === "steel" ? `
                <text class="section-preview-diagram-text" x="${(left + right) / 2}" y="${(top + bottom) / 2}" text-anchor="middle" dominant-baseline="middle">${escapeHtml(translate("modal.materialSteel"))}</text>
            ` : `
            ${getColumnConfinementSegments(confinementLayout, barPositions).map((segment) => (
            `<line class="section-preview-diagram-tie" x1="${segment.x1}" y1="${segment.y1}" x2="${segment.x2}" y2="${segment.y2}"></line>`
        )).join("")}
            ${barPositions.map((position) => (
        `<circle class="section-preview-diagram-bar" fill="#000000" stroke="#000000" cx="${position.x}" cy="${position.y}" r="${position.radius}"></circle>`
    )).join("")}
            `}
        </svg>
    `;
}

function buildBeamSectionPreviewFigure(beam) {
    const normalizedBeam = beam?.id ? normalizeBeamModel(beam) : normalizeBeamInsertDraft(beam);
    const structuralMaterial = normalizeStructuralMaterialSpec(normalizedBeam.structuralMaterial);
    const sectionRect = getGenericSectionPreviewRect(normalizedBeam.b, normalizedBeam.h, 176, 124);
    const pixelsPerMeter = getSectionPreviewScaleFactor(sectionRect, normalizedBeam.b, normalizedBeam.h);
    const left = 44 + (176 - sectionRect.width) / 2;
    const top = 54 + (124 - sectionRect.height) / 2;
    const right = left + sectionRect.width;
    const bottom = top + sectionRect.height;
    const sideCover = Math.min(
        getBeamSideCover(normalizedBeam.coverTop, normalizedBeam.coverBottom) * pixelsPerMeter,
        Math.max(sectionRect.width / 2 - 6, 2)
    );
    const topCover = Math.min(
        normalizedBeam.coverTop * pixelsPerMeter,
        Math.max(sectionRect.height / 2 - 6, 2)
    );
    const bottomCover = Math.min(
        normalizedBeam.coverBottom * pixelsPerMeter,
        Math.max(sectionRect.height / 2 - 6, 2)
    );
    const stirrupLeft = left + sideCover;
    const stirrupRight = right - sideCover;
    const stirrupTop = top + topCover;
    const stirrupBottom = bottom - bottomCover;
    const stirrupHookLength = Math.max(Math.min(stirrupRight - stirrupLeft, stirrupBottom - stirrupTop) * 0.18, 0.1);
    const stirrupSegments = createColumnConfinementRectangleSegments(
        stirrupLeft,
        stirrupBottom,
        stirrupRight,
        stirrupTop,
        stirrupHookLength
    );
    const longitudinalLayout = getBeamSectionLongitudinalBarLayout(normalizedBeam);
    const coverNote = Math.abs(normalizedBeam.coverTop - normalizedBeam.coverBottom) <= 1e-3
        ? `Rec. = ${normalizedBeam.coverTop.toFixed(2)}m`
        : `Rec. sup/inf = ${normalizedBeam.coverTop.toFixed(2)}/${normalizedBeam.coverBottom.toFixed(2)}m`;

    return `
        <svg viewBox="0 0 320 220" role="img" aria-label="${escapeHtml(formatSectionDimensionsText(normalizedBeam.b, normalizedBeam.h))}">
            ${buildSectionPreviewDimensionMarkup(
        left,
        top,
        right,
        bottom,
        `b = ${normalizedBeam.b.toFixed(2)}m`,
        `h = ${normalizedBeam.h.toFixed(2)}m`
    )}
            <rect class="section-preview-diagram-concrete" x="${left}" y="${top}" width="${sectionRect.width}" height="${sectionRect.height}"></rect>
            ${structuralMaterial.type === "steel" ? `
                <text class="section-preview-diagram-text" x="${(left + right) / 2}" y="${(top + bottom) / 2}" text-anchor="middle" dominant-baseline="middle">${escapeHtml(translate("modal.materialSteel"))}</text>
            ` : `
            ${stirrupSegments.map((segment) => `<line class="section-preview-diagram-tie" x1="${segment.x1}" y1="${segment.y1}" x2="${segment.x2}" y2="${segment.y2}"></line>`).join("")}
            ${longitudinalLayout.bars.map((bar) => {
        const x = left + (bar.xMeters / normalizedBeam.b) * sectionRect.width;
        const y = bottom - (bar.yMeters / normalizedBeam.h) * sectionRect.height;
        const radius = getSectionPreviewBarRadius(bar.diameterLabel, pixelsPerMeter);
        return `<circle class="section-preview-diagram-bar" fill="#000000" stroke="#000000" cx="${x}" cy="${y}" r="${radius}"></circle>`;
    }).join("")}
            <text class="section-preview-diagram-note" x="24" y="204">${escapeHtml(coverNote)}</text>
            `}
        </svg>
    `;
}

function getSlabAxisSectionPreviewSpec(slab, axis) {
    const normalizedSlab = slab?.id ? normalizeSlab(slab) : normalizeSlabInsertDraft(slab);
    if (normalizedSlab.type === "lightened") {
        const axisRebar = getLightenedAxisRebar(normalizedSlab.lightened, axis);
        const representativeSpacing = (
            axis === "x"
                ? normalizedSlab.lightened.cassetteHeight
                : normalizedSlab.lightened.cassetteWidth
        ) + normalizedSlab.lightened.cassetteGap;

        return {
            diameter: axisRebar.diameter,
            spacing: representativeSpacing,
            totalDepth: normalizedSlab.h,
            note: `${formatDxfRebarCountLabel(axisRebar.bars, axisRebar.diameter)}@${representativeSpacing.toFixed(2)}m`,
            isLightened: true,
            topLayerDepth: Math.max(normalizedSlab.h - normalizedSlab.lightened.cassetteThickness, 0.02),
            barLayer: "bottom"
        };
    }

    return {
        diameter: axis === "x" ? normalizedSlab.solid.xBarDiameter : normalizedSlab.solid.yBarDiameter,
        spacing: axis === "x" ? normalizedSlab.solid.xSpacing : normalizedSlab.solid.ySpacing,
        totalDepth: normalizedSlab.h,
        note: formatSlabSpacingLabel(
            axis === "x" ? normalizedSlab.solid.xBarDiameter : normalizedSlab.solid.yBarDiameter,
            axis === "x" ? normalizedSlab.solid.xSpacing : normalizedSlab.solid.ySpacing
        ),
        isLightened: false,
        topLayerDepth: normalizedSlab.h,
        barLayer: normalizedSlab.solid.topSteelDirection === axis ? "top" : "bottom"
    };
}

function getSlabPreviewSpacingPositions(left, right, spacing) {
    const clearLeft = left + 14;
    const clearRight = right - 14;
    const clearWidth = clearRight - clearLeft;
    if (clearWidth <= 6) {
        return [(left + right) / 2];
    }

    const representativeStripWidth = 1.2;
    const normalizedSpacing = Math.max(parsePositiveNumberOrFallback(spacing, DEFAULT_SLAB_BAR_SPACING, 0.05), 0.05);
    const stepPx = normalizedSpacing * (clearWidth / representativeStripWidth);
    const count = Math.max(Math.min(Math.floor(clearWidth / Math.max(stepPx, 1)) + 1, 10), 2);
    const usedWidth = stepPx * Math.max(count - 1, 0);
    const start = clearLeft + Math.max((clearWidth - usedWidth) / 2, 0);

    return Array.from({ length: count }, (_, index) => start + stepPx * index)
        .filter((value) => value >= clearLeft - 0.5 && value <= clearRight + 0.5);
}

function buildLightenedSlabDirectionSectionPreviewMarkup(normalizedSlab, axis, top) {
    const structuralMaterial = normalizeStructuralMaterialSpec(normalizedSlab.structuralMaterial);
    const title = axis === "x" ? translate("modal.directionX") : translate("modal.directionY");
    const left = 34;
    const width = 228;
    const right = left + width;
    const titleX = 20;
    const titleY = top - 10;
    const boxTop = top + 26;
    const totalDepth = Math.max(parsePositiveNumberOrFallback(normalizedSlab.h, 0.2, 0.02), 0.02);
    const boxHeight = Math.max(Math.min(totalDepth * 300, 66), 34);
    const boxBottom = boxTop + boxHeight;
    const cassettePlanDimension = Math.max(
        parsePositiveNumberOrFallback(
            axis === "x" ? normalizedSlab.lightened.cassetteWidth : normalizedSlab.lightened.cassetteHeight,
            DEFAULT_LIGHTENED_CASSETTE_WIDTH,
            0.05
        ),
        0.05
    );
    const cassetteThickness = Math.min(
        Math.max(parsePositiveNumberOrFallback(normalizedSlab.lightened.cassetteThickness, totalDepth * 0.7, 0.02), 0.02),
        totalDepth
    );
    const cassetteGap = Math.max(parsePositiveNumberOrFallback(normalizedSlab.lightened.cassetteGap, DEFAULT_LIGHTENED_CASSETTE_GAP, 0.01), 0.01);
    const topLayerDepth = Math.max(totalDepth - cassetteThickness, 0);
    const pixelsPerMeterY = boxHeight / totalDepth;
    const voidTop = boxTop + (topLayerDepth * pixelsPerMeterY);
    const voidHeight = Math.max(boxBottom - voidTop, 0);
    const moduleWidthMeters = cassettePlanDimension * 2 + cassetteGap * 3;
    const pixelsPerMeterX = width / Math.max(moduleWidthMeters, 0.05);
    const edgeGap = cassetteGap * pixelsPerMeterX;
    const gapWidth = cassetteGap * pixelsPerMeterX;
    const cassetteWidth = cassettePlanDimension * pixelsPerMeterX;
    const firstCassetteX = left + edgeGap;
    const secondCassetteX = firstCassetteX + cassetteWidth + gapWidth;
    const cassetteRects = [
        { x: firstCassetteX, width: cassetteWidth },
        { x: secondCassetteX, width: cassetteWidth }
    ];
    const ribCenters = [
        left + edgeGap / 2,
        firstCassetteX + cassetteWidth + gapWidth / 2,
        secondCassetteX + cassetteWidth + edgeGap / 2
    ];
    const axisRebar = getLightenedAxisRebar(normalizedSlab.lightened, axis);
    const barRadius = getSectionPreviewBarRadius(axisRebar.diameter, pixelsPerMeterY, 2);
    const barY = boxBottom - Math.max(barRadius * 1.8, 7);
    const cassetteLabel = formatLengthForUnit(cassettePlanDimension, "model");
    const gapLabel = formatLengthForUnit(cassetteGap, "spacing");
    const cassetteDimension = buildSectionPreviewHorizontalDimensionMarkup(firstCassetteX, boxTop, firstCassetteX + cassetteWidth, cassetteLabel);
    const gapDimensionY = boxBottom + 12;
    const gapCenterX = firstCassetteX + cassetteWidth + gapWidth / 2;
    const gapDimension = `
        <line class="section-preview-diagram-dim" x1="${firstCassetteX + cassetteWidth}" y1="${gapDimensionY}" x2="${secondCassetteX}" y2="${gapDimensionY}"></line>
        <line class="section-preview-diagram-dim" x1="${firstCassetteX + cassetteWidth}" y1="${gapDimensionY - 4}" x2="${firstCassetteX + cassetteWidth}" y2="${gapDimensionY + 4}"></line>
        <line class="section-preview-diagram-dim" x1="${secondCassetteX}" y1="${gapDimensionY - 4}" x2="${secondCassetteX}" y2="${gapDimensionY + 4}"></line>
        <text class="section-preview-diagram-text" x="${gapCenterX}" y="${gapDimensionY + 12}" text-anchor="middle">${escapeHtml(gapLabel)}</text>
    `;

    return `
        <text class="section-preview-diagram-note" x="${titleX}" y="${titleY}" font-weight="700">${escapeHtml(title)}</text>
        ${buildSectionPreviewVerticalDimensionMarkup(right, boxTop, boxBottom, formatLengthForUnit(totalDepth, "section"))}
        ${cassetteDimension}
        <rect class="section-preview-diagram-concrete" x="${left}" y="${boxTop}" width="${width}" height="${boxHeight}"></rect>
        ${voidHeight > 0 ? cassetteRects.map((cassette) => (`<rect x="${cassette.x}" y="${voidTop}" width="${cassette.width}" height="${voidHeight}" rx="2.5" fill="rgba(226, 232, 240, 0.72)" stroke="rgba(148, 163, 184, 0.9)" stroke-width="1.1"></rect>`)).join("") : ""}
        ${structuralMaterial.type === "steel" ? `
            <text class="section-preview-diagram-text" x="${(left + right) / 2}" y="${(boxTop + boxBottom) / 2}" text-anchor="middle" dominant-baseline="middle">${escapeHtml(translate("modal.materialSteel"))}</text>
        ` : `
            ${ribCenters.map((x) => `<circle class="section-preview-diagram-bar" fill="#000000" stroke="#000000" cx="${x}" cy="${barY}" r="${barRadius}"></circle>`).join("")}
        `}
        ${gapDimension}
    `;
}

function buildSlabDirectionSectionPreviewMarkup(normalizedSlab, axis, top) {
    const structuralMaterial = normalizeStructuralMaterialSpec(normalizedSlab.structuralMaterial);
    if (normalizedSlab.type === "hole") {
        const title = axis === "x" ? translate("modal.directionX") : translate("modal.directionY");
        const left = 34;
        const width = 228;
        const right = left + width;
        const boxTop = top + 18;
        const boxHeight = Math.max(Math.min(normalizedSlab.h * 300, 66), 30);
        const boxBottom = boxTop + boxHeight;
        return `
            <text class="section-preview-diagram-note" x="${left}" y="${top}" font-weight="700">${escapeHtml(title)}</text>
            ${buildSectionPreviewVerticalDimensionMarkup(right, boxTop, boxBottom, `h = ${normalizedSlab.h.toFixed(2)}m`)}
            <rect class="section-preview-diagram-concrete" x="${left}" y="${boxTop}" width="${width}" height="${boxHeight}" fill="rgba(13, 18, 24, 0.08)" stroke="rgba(244, 246, 248, 0.68)" stroke-dasharray="6 4"></rect>
            <text class="section-preview-diagram-text" x="${(left + right) / 2}" y="${(boxTop + boxBottom) / 2}" text-anchor="middle" dominant-baseline="middle">${escapeHtml(translate("modal.hole"))}</text>
        `;
    }
    if (normalizedSlab.type === "lightened") {
        return buildLightenedSlabDirectionSectionPreviewMarkup(normalizedSlab, axis, top);
    }
    const spec = getSlabAxisSectionPreviewSpec(normalizedSlab, axis);
    const title = axis === "x" ? translate("modal.directionX") : translate("modal.directionY");
    const left = 34;
    const width = 228;
    const right = left + width;
    const boxTop = top + 18;
    const boxHeight = Math.max(Math.min(spec.totalDepth * 300, 66), 30);
    const boxBottom = boxTop + boxHeight;
    const pixelsPerMeter = boxHeight / Math.max(spec.totalDepth, 0.05);
    const barRadius = getSectionPreviewBarRadius(spec.diameter, pixelsPerMeter, 2);
    const topBarY = boxTop + Math.max(barRadius * 1.8, 7);
    const bottomBarY = boxBottom - Math.max(barRadius * 1.8, 7);
    const barY = spec.barLayer === "top" ? topBarY : bottomBarY;
    const barXs = getSlabPreviewSpacingPositions(left, right, spec.spacing);
    const voidTop = boxTop + (spec.topLayerDepth * pixelsPerMeter);
    const voidLeft = left + width * 0.22;
    const voidWidth = width * 0.56;
    const voidHeight = Math.max(boxBottom - voidTop - 4, 0);

    return `
        <text class="section-preview-diagram-note" x="${left}" y="${top}" font-weight="700">${escapeHtml(title)}</text>
        ${buildSectionPreviewVerticalDimensionMarkup(right, boxTop, boxBottom, `h = ${spec.totalDepth.toFixed(2)}m`)}
        <rect class="section-preview-diagram-concrete" x="${left}" y="${boxTop}" width="${width}" height="${boxHeight}"></rect>
        ${spec.isLightened && voidHeight > 0 ? `<rect x="${voidLeft}" y="${voidTop}" width="${voidWidth}" height="${voidHeight}" fill="rgba(226, 232, 240, 0.72)" stroke="rgba(148, 163, 184, 0.9)" stroke-width="1.2"></rect>` : ""}
        ${structuralMaterial.type === "steel" ? `
            <text class="section-preview-diagram-text" x="${(left + right) / 2}" y="${(boxTop + boxBottom) / 2}" text-anchor="middle" dominant-baseline="middle">${escapeHtml(translate("modal.materialSteel"))}</text>
        ` : `
            ${barXs.map((x) => `<circle class="section-preview-diagram-bar" fill="#000000" stroke="#000000" cx="${x}" cy="${barY}" r="${barRadius}"></circle>`).join("")}
            <text class="section-preview-diagram-note" x="${left}" y="${boxBottom + 18}">${escapeHtml(spec.note)}</text>
        `}
    `;
}

function buildSlabSectionPreviewFigure(slab) {
    const normalizedSlab = slab?.id ? normalizeSlab(slab) : normalizeSlabInsertDraft(slab);
    const ariaLabel = normalizedSlab.type === "hole"
        ? translate("modal.hole")
        : `h = ${normalizedSlab.h.toFixed(2)}m`;
    const viewHeight = normalizedSlab.type === "lightened" ? 294 : 250;

    return `
        <svg viewBox="0 0 320 ${viewHeight}" role="img" aria-label="${escapeHtml(ariaLabel)}">
            ${buildSlabDirectionSectionPreviewMarkup(normalizedSlab, "x", 34)}
            ${buildSlabDirectionSectionPreviewMarkup(normalizedSlab, "y", 170)}
        </svg>
    `;
}

function buildFoundationSectionPreviewFigure(foundation) {
    const normalizedFoundation = foundation?.id ? normalizeFoundation(foundation) : normalizeFoundationInsertDraft(foundation);
    const structuralMaterial = normalizeStructuralMaterialSpec(normalizedFoundation.structuralMaterial);
    const left = 64;
    const top = 50;
    const width = 172;
    const height = 118;
    const right = left + width;
    const bottom = top + height;
    const centerX = (left + right) / 2;
    const centerY = (top + bottom) / 2;
    const pairSpacing = 20;
    const halfPairSpacing = pairSpacing / 2;
    const horizontalBars = [centerY - halfPairSpacing, centerY + halfPairSpacing];
    const verticalBars = [centerX - halfPairSpacing, centerX + halfPairSpacing];
    const xBarWidth = Math.max((width - 28) * 0.014, 1.8);
    const yBarWidth = Math.max((height - 28) * 0.014, 1.8);

    return `
        <svg viewBox="0 0 320 220" role="img" aria-label="${escapeHtml(formatSectionDimensionsText(normalizedFoundation.b, normalizedFoundation.h))}">
            ${buildSectionPreviewDimensionMarkup(
        left,
        top,
        right,
        bottom,
        `b = ${normalizedFoundation.b.toFixed(2)}m`,
        `h = ${normalizedFoundation.h.toFixed(2)}m`
    )}
            <rect class="section-preview-diagram-concrete" x="${left}" y="${top}" width="${width}" height="${height}"></rect>
            ${structuralMaterial.type === "steel" ? `
                <text class="section-preview-diagram-text" x="${centerX}" y="${centerY}" text-anchor="middle" dominant-baseline="middle">${escapeHtml(translate("modal.materialSteel"))}</text>
            ` : `
                ${horizontalBars.map((barY) => `<line class="section-preview-diagram-bar section-preview-diagram-foundation-bar" stroke-linecap="round" x1="${left + 14}" y1="${barY}" x2="${right - 14}" y2="${barY}" stroke-width="${xBarWidth}"></line>`).join("")}
                ${verticalBars.map((barX) => `<line class="section-preview-diagram-bar section-preview-diagram-foundation-bar" stroke-linecap="round" x1="${barX}" y1="${top + 14}" x2="${barX}" y2="${bottom - 14}" stroke-width="${yBarWidth}"></line>`).join("")}
            `}
        </svg>
    `;
}

function buildWallSectionPreviewFigure(wall) {
    const normalizedWall = normalizeWall(wall);
    const structuralMaterial = normalizeStructuralMaterialSpec(normalizedWall.structuralMaterial);
    const left = 66;
    const top = 56;
    const width = 164;
    const height = 112;
    const right = left + width;
    const bottom = top + height;

    if (normalizedWall.material === "masonry") {
        const previewLeft = 34;
        const previewTop = 72;
        const previewLength = 252;
        const previewThickness = Math.min(Math.max(normalizedWall.b * 280, 42), 66);
        const previewBottom = previewTop + previewThickness;
        const previewRight = previewLeft + previewLength;
        const previewCenterY = previewTop + previewThickness / 2;
        const previewModelLength = 1.0;
        const blockModelLength = 0.4;
        const scaleX = previewLength / previewModelLength;
        const blockLengthPx = blockModelLength * scaleX;
        const shell = Math.min(Math.max(previewThickness * 0.16, 7), 11);
        const cellGap = Math.min(Math.max(previewThickness * 0.08, 5), 8);
        const fillRight = normalizedWall.masonry.fillMode === "all";
        const radius = Math.max(parseDiameterInMeters(normalizedWall.masonry.barDiameter) * 230, 2.4);
        const blocks = [];
        const hatchLines = (x, y, w, h, spacing = 9) => {
            const lines = [];
            for (let offset = -h; offset <= w; offset += spacing) {
                const x1 = x + Math.max(offset, 0);
                const y1 = y + Math.max(-offset, 0);
                const x2 = x + Math.min(offset + h, w);
                const y2 = y + Math.min(h + offset, h);
                if (x2 - x1 > 1 && y2 - y1 > 1) {
                    lines.push(`<line x1="${x1.toFixed(2)}" y1="${y1.toFixed(2)}" x2="${x2.toFixed(2)}" y2="${y2.toFixed(2)}" stroke="#64748b" stroke-width="0.8" opacity="0.65"></line>`);
                }
            }
            return lines.join("");
        };
        const filledCoreMarkup = (x, y, w, h) => `
            <rect x="${x}" y="${y}" width="${w}" height="${h}" fill="rgba(148, 163, 184, 0.28)" stroke="#94a3b8" stroke-width="0.8"></rect>
            ${hatchLines(x, y, w, h)}`;
        const openCoreMarkup = (x, y, w, h) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#ffffff" stroke="#94a3b8" stroke-width="0.8"></rect>`;
        for (let blockIndex = 0, blockX = previewLeft; blockX < previewRight - 1; blockIndex += 1, blockX += blockLengthPx) {
            const blockW = Math.min(blockLengthPx, previewRight - blockX);
            if (blockW < 18) {
                continue;
            }
            const coreY = previewTop + shell;
            const coreH = Math.max(previewThickness - shell * 2, 14);
            const coreW = Math.max((blockW - shell * 2 - cellGap) / 2, 8);
            const leftCoreX = blockX + shell;
            const rightCoreX = blockX + shell + coreW + cellGap;
            const coreBars = (x, y, w, h) => getCellBarPositions(normalizedWall.masonry.barsPerCell, x + 5, y + 5, x + w - 5, y + h - 5, radius)
                .map((position) => `<circle class="section-preview-diagram-bar" fill="#000000" stroke="#000000" cx="${position.x}" cy="${position.y}" r="${radius}"></circle>`)
                .join("");
            blocks.push(`
                <rect x="${blockX.toFixed(2)}" y="${previewTop}" width="${blockW.toFixed(2)}" height="${previewThickness}" fill="#fffaf5" stroke="#8f5b34" stroke-width="1.4"></rect>
                ${filledCoreMarkup(leftCoreX, coreY, coreW, coreH)}
                ${coreBars(leftCoreX, coreY, coreW, coreH)}
                ${rightCoreX + coreW <= blockX + blockW - shell + 1 ? (fillRight ? filledCoreMarkup(rightCoreX, coreY, coreW, coreH) + coreBars(rightCoreX, coreY, coreW, coreH) : openCoreMarkup(rightCoreX, coreY, coreW, coreH)) : ""}
            `);
        }

        return `
            <svg viewBox="0 0 320 220" role="img" aria-label="${escapeHtml(formatWallSectionText(normalizedWall))}">
                <rect x="${previewLeft - 6}" y="${previewTop - 10}" width="${previewLength + 12}" height="${previewThickness + 20}" rx="6" fill="rgba(255,255,255,0.82)" stroke="rgba(148,163,184,0.28)"></rect>
                ${blocks.join("")}
                <line x1="${previewLeft}" y1="${previewCenterY}" x2="${previewRight}" y2="${previewCenterY}" stroke="#8f5b34" stroke-width="0.9" opacity="0.45"></line>
                <text class="section-preview-diagram-note" x="${previewLeft}" y="184">${escapeHtml(
                    getMasonryFillModeLabel(normalizedWall.masonry.fillMode)
                )}</text>
                <text class="section-preview-diagram-note" x="${previewLeft}" y="202">${escapeHtml(`${normalizedWall.masonry.barsPerCell} ${TRANSVERSE_SYMBOL}${normalizedWall.masonry.barDiameter}`)}</text>
            </svg>
        `;
    }

    const longitudinalXs = getRepresentativeSpacingPositions(left + 12, right - 12, normalizedWall.concrete.longitudinalSpacing, 0, 2, 6);
    const transverseYs = getRepresentativeSpacingPositions(top + 12, bottom - 12, normalizedWall.concrete.transverseSpacing, 0, 2, 6);
    const longitudinalWidth = Math.max(parseDiameterInMeters(normalizedWall.concrete.longitudinalDiameter) * 190, 1.6);
    const transverseWidth = Math.max(parseDiameterInMeters(normalizedWall.concrete.transverseDiameter) * 190, 1.3);

    return `
        <svg viewBox="0 0 320 220" role="img" aria-label="${escapeHtml(formatWallSectionText(normalizedWall))}">
            ${buildSectionPreviewHorizontalDimensionMarkup(left, top, right, `e = ${normalizedWall.b.toFixed(2)}m`)}
            <rect class="section-preview-diagram-concrete" x="${left}" y="${top}" width="${width}" height="${height}"></rect>
            ${structuralMaterial.type === "steel" ? `
                <text class="section-preview-diagram-text" x="${(left + right) / 2}" y="${(top + bottom) / 2}" text-anchor="middle" dominant-baseline="middle">${escapeHtml(translate("modal.materialSteel"))}</text>
            ` : `
                ${longitudinalXs.map((barX) => `<line x1="${barX}" y1="${top + 10}" x2="${barX}" y2="${bottom - 10}" stroke="#000000" stroke-width="${longitudinalWidth}" stroke-linecap="round"></line>`).join("")}
                ${transverseYs.map((barY) => `<line x1="${left + 10}" y1="${barY}" x2="${right - 10}" y2="${barY}" stroke="#0ea5e9" stroke-width="${transverseWidth}" stroke-linecap="round"></line>`).join("")}
                <text class="section-preview-diagram-note" x="${left}" y="196">${escapeHtml(`${TRANSVERSE_SYMBOL}${normalizedWall.concrete.longitudinalDiameter} / ${TRANSVERSE_SYMBOL}${normalizedWall.concrete.transverseDiameter}`)}</text>
            `}
        </svg>
    `;
}

function buildSectionPreviewSummaryMarkup(type, draft) {
    const rows = [];

    if (type === "col") {
        const normalizedColumn = normalizeColumnInsertDraft(draft);
        const structuralMaterial = normalizeStructuralMaterialSpec(normalizedColumn.structuralMaterial);
        const longRebar = normalizeColumnLongitudinalRebar(normalizedColumn.longRebar);
        const stirrups = normalizeColumnTransverseRebar(normalizedColumn.stirrups, longRebar);

        rows.push(...buildStructuralMaterialSummaryRows(structuralMaterial));
        if (structuralMaterial.type !== "steel") {
            rows.push(
                buildSectionPreviewRowMarkup(translate("modal.longitudinalSteel"), formatColumnLongitudinalRebar(longRebar)),
                buildSectionPreviewRowMarkup(translate("modal.cornerBars"), formatColumnCornerRebar(longRebar)),
                buildSectionPreviewRowMarkup(translate("modal.stirrups"), formatColumnTransverseRebar(stirrups, longRebar))
            );
        }

        return rows.join("");
    }

    if (type === "beam") {
        const normalizedBeam = draft?.id ? normalizeBeamModel(draft) : normalizeBeamInsertDraft(draft);
        const structuralMaterial = normalizeStructuralMaterialSpec(normalizedBeam.structuralMaterial);

        rows.push(...buildStructuralMaterialSummaryRows(structuralMaterial));
        if (structuralMaterial.type !== "steel") {
            rows.push(
                buildSectionPreviewRowMarkup(translate("modal.mainTopSteel"), formatRebar(normalizedBeam.topRebar)),
                buildSectionPreviewRowMarkup(translate("modal.mainBottomSteel"), formatRebar(normalizedBeam.botRebar)),
                buildSectionPreviewRowMarkup(translate("modal.stirrups"), formatTransverseRebar(normalizedBeam.stirrups, DEFAULT_BEAM_STIRRUP_SPACING)),
                buildSectionPreviewRowMarkup(translate("modal.coverTop"), `${normalizedBeam.coverTop.toFixed(2)} m`),
                buildSectionPreviewRowMarkup(translate("modal.coverBottom"), `${normalizedBeam.coverBottom.toFixed(2)} m`)
            );
        }

        return rows.join("");
    }

    if (type === "wall") {
        const normalizedWall = normalizeWall(draft);
        const structuralMaterial = normalizeStructuralMaterialSpec(normalizedWall.structuralMaterial);

        if (normalizedWall.material === "masonry") {
            rows.push(
                buildSectionPreviewRowMarkup(translate("modal.wallType"), translate("modal.wallMasonry")),
                buildSectionPreviewRowMarkup(translate("modal.wallBlockWidth"), `${normalizedWall.masonry.blockWidth.toFixed(2)} m`)
            );
        } else {
            rows.push(
                ...buildStructuralMaterialSummaryRows(structuralMaterial),
                buildSectionPreviewRowMarkup(translate("modal.wallType"), getWallMaterialDisplayLabel(normalizedWall.material))
            );
        }

        if (normalizedWall.material === "masonry") {
            rows.push(
                buildSectionPreviewRowMarkup(translate("modal.wallFillPattern"), getMasonryFillModeLabel(normalizedWall.masonry.fillMode)),
                buildSectionPreviewRowMarkup(translate("modal.wallSteelPerCell"), `${normalizedWall.masonry.barsPerCell} ${TRANSVERSE_SYMBOL}${normalizedWall.masonry.barDiameter}`),
                buildSectionPreviewRowMarkup(translate("modal.wallHorizontalSteel"), `${normalizedWall.masonry.horizontalBarDiameter} @ ${formatLengthForUnit(normalizedWall.masonry.horizontalSpacing, "spacing")}`)
            );
        } else if (structuralMaterial.type !== "steel") {
                rows.push(
                    buildSectionPreviewRowMarkup(translate("modal.wallLongitudinalSteel"), formatWallRebarLayoutLabel(normalizedWall.concrete, "longitudinal"))
                );
                if (normalizedWall.concrete.includeHooks !== false) {
                    rows.push(buildSectionPreviewRowMarkup(translate("modal.wallIncludeHooks"), formatWallRebarLayoutLabel(normalizedWall.concrete, "transverse")));
                }
        }

        return rows.join("");
    }

    if (type === "slab") {
        const normalizedSlab = draft?.id ? normalizeSlab(draft) : normalizeSlabInsertDraft(draft);
        const structuralMaterial = normalizeStructuralMaterialSpec(normalizedSlab.structuralMaterial);

        if (normalizedSlab.type === "hole") {
            rows.push(
                buildSectionPreviewRowMarkup(translate("modal.slabType"), translate("modal.hole")),
                buildSectionPreviewRowMarkup(translate("modal.depth"), `${normalizedSlab.h.toFixed(2)} m`),
                buildSectionPreviewRowMarkup(
                    translate("modal.holeNote"),
                    `${(normalizedSlab.x2 - normalizedSlab.x1).toFixed(2)} x ${(normalizedSlab.y2 - normalizedSlab.y1).toFixed(2)} m`
                )
            );
            return rows.join("");
        }

        rows.push(
            ...buildStructuralMaterialSummaryRows(structuralMaterial),
            buildSectionPreviewRowMarkup(
                translate("modal.slabType"),
                getSlabTypeLabel(normalizedSlab.type)
            )
        );

        if (structuralMaterial.type !== "steel") {
            if (normalizedSlab.type === "lightened") {
                if (normalizedSlab.actionType === SLAB_ACTION_ONE_WAY) {
                    const axis = normalizedSlab.solid.topSteelDirection === "y" ? "y" : "x";
                    rows.push(buildSectionPreviewRowMarkup(
                        axis === "y" ? translate("modal.slabSteelY") : translate("modal.slabSteelX"),
                        formatLightenedAxisRebarLabel(normalizedSlab.lightened, axis)
                    ));
                } else {
                    rows.push(
                        buildSectionPreviewRowMarkup(translate("modal.slabSteelX"), formatLightenedAxisRebarLabel(normalizedSlab.lightened, "x")),
                        buildSectionPreviewRowMarkup(translate("modal.slabSteelY"), formatLightenedAxisRebarLabel(normalizedSlab.lightened, "y"))
                    );
                }
            } else {
                rows.push(
                    buildSectionPreviewRowMarkup(translate("modal.slabSteelX"), formatSlabSpacingLabel(normalizedSlab.solid.xBarDiameter, normalizedSlab.solid.xSpacing)),
                    buildSectionPreviewRowMarkup(translate("modal.slabSteelY"), formatSlabSpacingLabel(normalizedSlab.solid.yBarDiameter, normalizedSlab.solid.ySpacing)),
                    buildSectionPreviewRowMarkup(translate("modal.topSteel"), formatSlabTopSteelDirectionLabel(normalizedSlab.solid.topSteelDirection))
                );
            }

            if (normalizedSlab.temperatureSteel.enabled) {
                rows.push(
                    buildSectionPreviewRowMarkup(translate("modal.slabTemperatureEnabled"), formatSlabTemperatureSteelLabel(normalizedSlab.temperatureSteel))
                );
            }
        }

        return rows.join("");
    }

    if (type === "foundation") {
        const normalizedFoundation = draft?.id ? normalizeFoundation(draft) : normalizeFoundationInsertDraft(draft);
        const structuralMaterial = normalizeStructuralMaterialSpec(normalizedFoundation.structuralMaterial);

        rows.push(
            ...buildStructuralMaterialSummaryRows(structuralMaterial),
            buildSectionPreviewRowMarkup(translate("modal.depth"), `${normalizedFoundation.thickness.toFixed(2)} m`)
        );

        if (structuralMaterial.type !== "steel") {
            rows.push(
                buildSectionPreviewRowMarkup(`${translate("modal.foundationTopSteel")} X`, formatSlabSpacingLabel(normalizedFoundation.solid.top.xBarDiameter, normalizedFoundation.solid.top.xSpacing)),
                buildSectionPreviewRowMarkup(`${translate("modal.foundationTopSteel")} Y`, formatSlabSpacingLabel(normalizedFoundation.solid.top.yBarDiameter, normalizedFoundation.solid.top.ySpacing)),
                buildSectionPreviewRowMarkup(`${translate("modal.foundationBottomSteel")} X`, formatSlabSpacingLabel(normalizedFoundation.solid.bottom.xBarDiameter, normalizedFoundation.solid.bottom.xSpacing)),
                buildSectionPreviewRowMarkup(`${translate("modal.foundationBottomSteel")} Y`, formatSlabSpacingLabel(normalizedFoundation.solid.bottom.yBarDiameter, normalizedFoundation.solid.bottom.ySpacing))
            );
        }

        return rows.join("");
    }

    return "";
}

function buildSectionPreviewFigureMarkup(type, draft) {
    if (type === "col") {
        return buildColumnSectionPreviewFigure(draft);
    }

    if (type === "beam") {
        return buildBeamSectionPreviewFigure(draft);
    }

    if (type === "wall") {
        return buildWallSectionPreviewFigure(draft);
    }

    if (type === "foundation") {
        return buildFoundationSectionPreviewFigure(draft);
    }

    return buildSlabSectionPreviewFigure(draft);
}

function renderSectionPreviewPanel() {
    if (
        !dom.workspaceSectionPreviewCard
        || !dom.workspaceSectionPreviewKicker
        || !dom.workspaceSectionPreviewTitle
        || !dom.workspaceSectionPreviewDimensions
        || !dom.workspaceSectionPreviewFigure
        || !dom.workspaceSectionPreviewSummary
    ) {
        return;
    }

    const wasHidden = dom.workspaceSectionPreviewCard.hidden;
    const config = getSectionPreviewConfig();
    if (!config?.draft) {
        dom.workspaceSectionPreviewCard.hidden = true;
        dom.workspaceSectionPreviewDimensions.innerHTML = "";
        dom.workspaceSectionPreviewFigure.innerHTML = "";
        dom.workspaceSectionPreviewSummary.innerHTML = "";
        return;
    }

    if (wasHidden) {
        closeAiChatDrawer();
    }

    dom.workspaceSectionPreviewCard.hidden = false;
    dom.workspaceSectionPreviewKicker.textContent = translate("workspace.sectionPreviewKicker");
    dom.workspaceSectionPreviewTitle.textContent = getSectionPreviewDisplayTitle(config, config.draft);
    dom.workspaceSectionPreviewDimensions.innerHTML = "";
    dom.workspaceSectionPreviewFigure.innerHTML = buildSectionPreviewFigureMarkup(config.type, config.draft);
    dom.workspaceSectionPreviewSummary.innerHTML = buildSectionPreviewSummaryMarkup(config.type, config.draft);
}

function buildInsertFieldMarkup({ id, label, value = "", type = "text", placeholder = "", step = "", min = "", options = null, wide = false }) {
    const wrapperClass = wide ? "insert-properties-field insert-properties-field-wide" : "insert-properties-field";
    if (Array.isArray(options)) {
        return `
            <label class="${wrapperClass}" for="${id}">
                <span>${label}</span>
                <select id="${id}">
                    ${options.map((option) => `<option value="${escapeHtml(option.value)}"${option.value === value ? " selected" : ""}>${escapeHtml(option.label)}</option>`).join("")}
                </select>
            </label>
        `;
    }

    const stepAttribute = step ? ` step="${escapeHtml(String(step))}"` : "";
    const minAttribute = min ? ` min="${escapeHtml(String(min))}"` : "";
    const placeholderAttribute = placeholder ? ` placeholder="${escapeHtml(placeholder)}"` : "";
    return `
        <label class="${wrapperClass}" for="${id}">
            <span>${label}</span>
            <input id="${id}" type="${type}" value="${escapeHtml(String(value ?? ""))}"${placeholderAttribute}${stepAttribute}${minAttribute}>
        </label>
    `;
}

function buildSlabActionTypeFieldMarkup(id, actionType, slabType) {
    const normalizedActionType = normalizeSlabActionType(actionType);
    const isEnabled = supportsSlabActionType(slabType);
    return `
        <label class="insert-properties-field insert-properties-field-wide slab-action-type-field${isEnabled ? "" : " is-disabled"}" data-slab-action-type-field for="${escapeHtml(id)}">
            <span>${translate("insert.slabActionType")}</span>
            <select id="${escapeHtml(id)}"${isEnabled ? "" : " disabled"}>
                <option value="${SLAB_ACTION_ONE_WAY}"${normalizedActionType === SLAB_ACTION_ONE_WAY ? " selected" : ""}>${escapeHtml(translate("modal.slabOneWay"))}</option>
                <option value="${SLAB_ACTION_TWO_WAY}"${normalizedActionType === SLAB_ACTION_TWO_WAY ? " selected" : ""}>${escapeHtml(translate("modal.slabTwoWay"))}</option>
            </select>
        </label>
    `;
}

function getSlabActionFormBounds(source = {}) {
    const vertices = Array.isArray(source?.vertices) && source.vertices.length >= 3
        ? normalizeSlabVertices(source)
        : [];
    if (vertices.length >= 3) {
        return getPolygonBounds(vertices);
    }

    const planWidth = parsePositiveNumberOrFallback(source?.planWidth ?? source?.width ?? source?.b, 1, 0.1);
    const planLength = parsePositiveNumberOrFallback(source?.planLength ?? source?.length, 1, 0.1);
    return {
        x1: 0,
        y1: 0,
        x2: planWidth,
        y2: planLength
    };
}

function syncOneWaySlabReinforcementUi(fieldPrefix = "slab", source = {}) {
    const actionTypeSelect = document.getElementById(fieldPrefix === "insert-slab" ? "insert-slab-action-type" : "slab-action-type");
    const topSteelSelect = document.getElementById(`${fieldPrefix}-solid-top-dir`);
    const isOneWay = normalizeSlabActionType(actionTypeSelect?.value ?? source?.actionType) === SLAB_ACTION_ONE_WAY;
    const fallbackMainAxis = normalizeTextValue(source?.solid?.topSteelDirection).toLowerCase() === "y"
        ? "y"
        : getSlabShortAxisFromBounds(getSlabActionFormBounds(source));
    const mainAxis = topSteelSelect?.value === "y" ? "y" : topSteelSelect?.value === "x" ? "x" : fallbackMainAxis;

    document.querySelectorAll(`[data-slab-main-rebar-card]`).forEach((card) => {
        const cardAxis = card.dataset.slabMainRebarCard;
        const titleNode = card.querySelector(".column-rebar-card-title");
        if (titleNode) {
            titleNode.textContent = cardAxis === "y"
                ? translate("modal.slabTopSteelDirY")
                : translate("modal.slabTopSteelDirX");
        }
        card.hidden = isOneWay && cardAxis !== mainAxis;
    });

    return { isOneWay, mainAxis };
}

function applyOneWaySlabActionDefaultsToFields(fieldPrefix = "slab", source = {}) {
    const { isOneWay, mainAxis } = syncOneWaySlabReinforcementUi(fieldPrefix, source);
    const actionTypeSelect = document.getElementById(fieldPrefix === "insert-slab" ? "insert-slab-action-type" : "slab-action-type");
    if (!actionTypeSelect || !isOneWay) {
        return;
    }

    const enabledInput = document.getElementById(`${fieldPrefix}-temp-enabled`);
    const dirXInput = document.getElementById(`${fieldPrefix}-temp-dir-x`);
    const dirYInput = document.getElementById(`${fieldPrefix}-temp-dir-y`);
    const diameterInput = document.getElementById(`${fieldPrefix}-temp-d`);
    const spacingInput = document.getElementById(`${fieldPrefix}-temp-s`);
    if (!enabledInput || !dirXInput || !dirYInput) {
        return;
    }

    const temperatureAxis = getOppositeSlabAxis(mainAxis);
    enabledInput.checked = true;
    dirXInput.checked = temperatureAxis === "x";
    dirYInput.checked = temperatureAxis === "y";
    [dirXInput, dirYInput, diameterInput, spacingInput].forEach((input) => {
        if (input) {
            input.disabled = false;
        }
    });
    document.querySelector(`[data-slab-temperature-controls="${fieldPrefix}"]`)?.classList.remove("is-disabled");
}

function buildInsertBlockMarkup(content) {
    return `<div class="insert-properties-block">${content}</div>`;
}

function buildInsertFieldRowMarkup(fieldsMarkup) {
    return buildInsertBlockMarkup(`<div class="insert-properties-inline-grid">${fieldsMarkup}</div>`);
}

function getSuggestedBeamSectionCutOffset(beam, preferredOffset = 0.5) {
    const normalizedBeam = normalizeBeamModel(beam);
    const span = getBeamSpan(normalizedBeam);
    if (span <= 0) {
        return 0;
    }

    const existingCuts = normalizeSectionCuts(normalizedBeam.sectionCuts, normalizedBeam);
    const candidates = [
        preferredOffset,
        span / 2,
        span * 0.25,
        span * 0.75
    ]
        .map((value) => Math.min(Math.max(parseNumberOrFallback(value, 0), 0), span))
        .filter((value, index, values) => index === values.findIndex((entry) => Math.abs(entry - value) < 0.01));

    const firstAvailableCandidate = candidates.find((value) => !existingCuts.some((cut) => Math.abs(cut - value) < 0.01));
    if (typeof firstAvailableCandidate === "number") {
        return firstAvailableCandidate;
    }

    const step = Math.max(Math.min(span / 8, 0.25), 0.05);
    for (let current = step; current < span; current += step) {
        if (!existingCuts.some((cut) => Math.abs(cut - current) < 0.01)) {
            return current;
        }
    }

    return span;
}

function buildBeamSectionDetailsPanelMarkup(beam, fieldPrefix = "insert-beam") {
    if (!beam?.id) {
        return "";
    }

    const normalizedBeam = normalizeBeamModel(beam);
    const cuts = normalizeSectionCuts(normalizedBeam.sectionCuts, normalizedBeam);
    if (!cuts.length) {
        return "";
    }

    return `
        <div class="insert-properties-block beam-section-details-block">
            <details class="beam-section-details-panel">
                <summary class="beam-section-details-summary">${translate("modal.beamSectionDetails") || "Detalles de secciones de viga"}</summary>
                <div class="beam-section-details-body">
                    ${cuts.map((cutOffset, index) => `
                        <div class="beam-section-detail-row" data-beam-section-detail-row>
                            <label class="beam-section-detail-field" for="${fieldPrefix}-section-cut-${index}">
                                <span>${translate("modal.beamSectionDistance") || "Distancia (m)"}</span>
                                <input
                                    type="number"
                                    id="${fieldPrefix}-section-cut-${index}"
                                    class="beam-section-detail-input"
                                    data-beam-section-cut-input
                                    value="${escapeHtml(cutOffset.toFixed(2))}"
                                    step="0.05"
                                    min="0"
                                    max="${escapeHtml(String(getBeamSpan(normalizedBeam).toFixed(2)))}"
                                >
                            </label>
                            <button
                                type="button"
                                class="button button-outline beam-section-detail-delete"
                                data-beam-section-detail-delete="${index}"
                            >${translate("modal.removeSectionDetail") || "Eliminar seccion"}</button>
                        </div>
                    `).join("")}
                </div>
            </details>
        </div>
    `;
}

function readBeamSectionDetailFields(fieldPrefix = "insert-beam", beam = null, root = dom.insertPropertiesFields) {
    const inputs = Array.from(root?.querySelectorAll("[data-beam-section-cut-input]") || []);
    if (!inputs.length) {
        return normalizeSectionCuts(beam?.sectionCuts, beam);
    }

    return normalizeSectionCuts(
        inputs.map((input) => input?.value),
        beam
    );
}

