function buildInsertPropertiesFieldsMarkup(tool, draft) {
    if (tool === "col") {
        return buildInsertColumnFields(draft);
    }

    if (tool === "beam") {
        return buildInsertBeamFields(draft);
    }

    if (tool === "foundation") {
        return buildInsertFoundationFields(draft);
    }

    if (tool === "wall") {
        return buildInsertWallFields(draft);
    }

    if (tool === "slab") {
        return buildInsertSlabFields(draft);
    }

    return "";
}

function wireInsertPropertiesFields(tool) {
    if (tool === "col") {
        const syncColumnDraft = () => {
            const longRebar = normalizeColumnLongitudinalRebar({
                xCount: document.getElementById("insert-col-x-count")?.value,
                xDiameter: document.getElementById("insert-col-x-d")?.value,
                yCount: document.getElementById("insert-col-y-count")?.value,
                yDiameter: document.getElementById("insert-col-y-d")?.value,
                cornerDiameter: document.getElementById("insert-col-corner-d")?.value,
                hasCustomCornerDiameter: document.getElementById("insert-col-corner-custom")?.checked
            });

            projectState.insertDrafts.col = normalizeColumnInsertDraft({
                ...projectState.insertDrafts.col,
                name: document.getElementById("insert-name")?.value,
                b: document.getElementById("insert-b")?.value,
                h: document.getElementById("insert-h")?.value,
                structuralMaterial: readStructuralMaterialFields(projectState.insertDrafts.col),
                longRebar,
                stirrups: {
                    ...(projectState.insertDrafts.col?.stirrups || {}),
                    d: document.getElementById("insert-col-tr-d")?.value,
                    spacing: document.getElementById("insert-col-tr-s")?.value,
                    count3Dir: document.getElementById("insert-col-tr-x")?.value,
                    count2Dir: document.getElementById("insert-col-tr-y")?.value
                }
            });
        };

        ["insert-name", "insert-b", "insert-h", "insert-col-tr-s"].forEach((id) => {
            document.getElementById(id)?.addEventListener("input", syncColumnDraft);
        });
        ["insert-col-tr-d", "insert-col-tr-x", "insert-col-tr-y"].forEach((id) => {
            document.getElementById(id)?.addEventListener("change", syncColumnDraft);
        });
        ["insert-material-type", "insert-material-fc", "insert-material-fy-long", "insert-material-fy-trans"].forEach((id) => {
            document.getElementById(id)?.addEventListener("change", syncColumnDraft);
        });
        wireColumnLongitudinalFields("insert-col", syncColumnDraft);
        syncColumnDraft();
        return;
    }

    if (tool === "beam") {
        const syncBeamDraft = () => {
            projectState.insertDrafts.beam = normalizeBeamInsertDraft({
                ...projectState.insertDrafts.beam,
                name: document.getElementById("insert-name")?.value,
                b: document.getElementById("insert-b")?.value,
                h: document.getElementById("insert-h")?.value,
                structuralMaterial: readStructuralMaterialFields(projectState.insertDrafts.beam),
                topRebar: {
                    n: document.getElementById("insert-top-n")?.value,
                    d: document.getElementById("insert-top-d")?.value
                },
                botRebar: {
                    n: document.getElementById("insert-bot-n")?.value,
                    d: document.getElementById("insert-bot-d")?.value
                },
                stirrups: {
                    d: document.getElementById("insert-beam-tr-d")?.value,
                    spacing: document.getElementById("insert-beam-tr-s")?.value
                },
                coverTop: document.getElementById("insert-beam-cover-top")?.value,
                coverBottom: document.getElementById("insert-beam-cover-bottom")?.value,
                steelDemands: normalizeBeamSteelDemands({
                    iEndTop: document.getElementById("insert-beam-demand-i-top")?.value,
                    iEndBottom: document.getElementById("insert-beam-demand-i-bottom")?.value,
                    midTop: document.getElementById("insert-beam-demand-mid-top")?.value,
                    midBottom: document.getElementById("insert-beam-demand-mid-bottom")?.value,
                    jEndTop: document.getElementById("insert-beam-demand-j-top")?.value,
                    jEndBottom: document.getElementById("insert-beam-demand-j-bottom")?.value
                }),
                additionalRebar: normalizeBeamAdditionalRebar({
                    iEndTop: {
                        n: document.getElementById("insert-beam-add-iEnd-top-n")?.value,
                        d: document.getElementById("insert-beam-add-iEnd-top-d")?.value
                    },
                    iEndBottom: {
                        n: document.getElementById("insert-beam-add-iEnd-bottom-n")?.value,
                        d: document.getElementById("insert-beam-add-iEnd-bottom-d")?.value
                    },
                    midTop: {
                        n: document.getElementById("insert-beam-add-mid-top-n")?.value,
                        d: document.getElementById("insert-beam-add-mid-top-d")?.value
                    },
                    midBottom: {
                        n: document.getElementById("insert-beam-add-mid-bottom-n")?.value,
                        d: document.getElementById("insert-beam-add-mid-bottom-d")?.value
                    },
                    jEndTop: {
                        n: document.getElementById("insert-beam-add-jEnd-top-n")?.value,
                        d: document.getElementById("insert-beam-add-jEnd-top-d")?.value
                    },
                    jEndBottom: {
                        n: document.getElementById("insert-beam-add-jEnd-bottom-n")?.value,
                        d: document.getElementById("insert-beam-add-jEnd-bottom-d")?.value
                    }
                })
            });
        };

        [
            "insert-name",
            "insert-b",
            "insert-h",
            "insert-top-n",
            "insert-bot-n",
            "insert-beam-tr-s",
            "insert-beam-cover-top",
            "insert-beam-cover-bottom",
            "insert-beam-demand-i-top",
            "insert-beam-demand-i-bottom",
            "insert-beam-demand-mid-top",
            "insert-beam-demand-mid-bottom",
            "insert-beam-demand-j-top",
            "insert-beam-demand-j-bottom",
            "insert-beam-add-iEnd-top-n",
            "insert-beam-add-iEnd-bottom-n",
            "insert-beam-add-mid-top-n",
            "insert-beam-add-mid-bottom-n",
            "insert-beam-add-jEnd-top-n",
            "insert-beam-add-jEnd-bottom-n"
        ].forEach((id) => {
            document.getElementById(id)?.addEventListener("input", syncBeamDraft);
        });
        [
            "insert-top-d",
            "insert-bot-d",
            "insert-beam-tr-d",
            "insert-beam-add-iEnd-top-d",
            "insert-beam-add-iEnd-bottom-d",
            "insert-beam-add-mid-top-d",
            "insert-beam-add-mid-bottom-d",
            "insert-beam-add-jEnd-top-d",
            "insert-beam-add-jEnd-bottom-d"
        ].forEach((id) => {
            document.getElementById(id)?.addEventListener("change", syncBeamDraft);
        });
        ["insert-material-type", "insert-material-fc", "insert-material-fy-long", "insert-material-fy-trans"].forEach((id) => {
            document.getElementById(id)?.addEventListener("change", syncBeamDraft);
        });
        syncBeamDraft();
        return;
    }

    if (tool === "foundation") {
        const syncFoundationDraft = () => {
            projectState.insertDrafts.foundation = normalizeFoundationInsertDraft({
                ...projectState.insertDrafts.foundation,
                name: document.getElementById("insert-name")?.value,
                b: document.getElementById("insert-b")?.value,
                h: document.getElementById("insert-h")?.value,
                thickness: document.getElementById("insert-foundation-thickness")?.value,
                structuralMaterial: readStructuralMaterialFields(projectState.insertDrafts.foundation),
                solid: readFoundationReinforcementFields("insert-foundation", projectState.insertDrafts.foundation)
            });
        };

        ["insert-name", "insert-b", "insert-h", "insert-foundation-thickness"].forEach((id) => {
            document.getElementById(id)?.addEventListener("input", syncFoundationDraft);
        });
        [
            "insert-material-type",
            "insert-material-fc",
            "insert-material-fy-long",
            "insert-material-fy-trans",
            "insert-foundation-solid-top-x-d",
            "insert-foundation-solid-top-x-s",
            "insert-foundation-solid-top-y-d",
            "insert-foundation-solid-top-y-s",
            "insert-foundation-solid-bottom-x-d",
            "insert-foundation-solid-bottom-x-s",
            "insert-foundation-solid-bottom-y-d",
            "insert-foundation-solid-bottom-y-s",
            "insert-foundation-solid-x-d",
            "insert-foundation-solid-x-s",
            "insert-foundation-solid-y-d",
            "insert-foundation-solid-y-s"
        ].forEach((id) => {
            document.getElementById(id)?.addEventListener("change", syncFoundationDraft);
        });
        syncFoundationDraft();
        return;
    }

    if (tool === "wall") {
        const syncWallDraft = () => {
            projectState.insertDrafts.wall = normalizeWallInsertDraft({
                ...projectState.insertDrafts.wall,
                name: document.getElementById("insert-name")?.value,
                b: document.getElementById("insert-b")?.value,
                structuralMaterial: readStructuralMaterialFields(projectState.insertDrafts.wall),
                material: document.getElementById("insert-wall-material")?.value,
                concrete: {
                    longitudinalDiameter: document.getElementById("insert-wall-conc-long-d")?.value,
                    longitudinalSpacing: document.getElementById("insert-wall-conc-long-s")?.value,
                    transverseDiameter: document.getElementById("insert-wall-conc-trans-d")?.value,
                    transverseSpacing: document.getElementById("insert-wall-conc-trans-s")?.value
                },
                masonry: {
                    blockWidth: document.getElementById("insert-wall-masonry-block-width")?.value,
                    fillMode: document.getElementById("insert-wall-masonry-fill")?.value,
                    barsPerCell: document.getElementById("insert-wall-masonry-bars")?.value,
                    barDiameter: document.getElementById("insert-wall-masonry-d")?.value
                }
            });
        };

        ["insert-name", "insert-b", "insert-wall-conc-long-s", "insert-wall-conc-trans-s", "insert-wall-conc-cover", "insert-wall-masonry-bars", "insert-wall-masonry-h-s"].forEach((id) => {
            document.getElementById(id)?.addEventListener("input", syncWallDraft);
        });
        ["insert-wall-material", "insert-wall-conc-long-d", "insert-wall-conc-trans-d", "insert-wall-masonry-fill", "insert-wall-masonry-d", "insert-wall-masonry-block-width"].forEach((id) => {
            document.getElementById(id)?.addEventListener("change", syncWallDraft);
        });
        ["insert-material-type", "insert-material-fc", "insert-material-fy-long", "insert-material-fy-trans"].forEach((id) => {
            document.getElementById(id)?.addEventListener("change", syncWallDraft);
        });
        wireWallTypeFields("insert-wall-material", dom.insertPropertiesFields);
        syncWallDraft();
        return;
    }

    if (tool === "slab") {
        const syncSlabDraft = () => {
            applyOneWaySlabActionDefaultsToFields("insert-slab", projectState.insertDrafts.slab);
            projectState.insertDrafts.slab = normalizeSlabInsertDraft({
                ...projectState.insertDrafts.slab,
                name: document.getElementById("insert-name")?.value,
                h: document.getElementById("insert-h")?.value,
                structuralMaterial: readStructuralMaterialFields(projectState.insertDrafts.slab),
                type: document.getElementById("insert-slab-type")?.value,
                actionType: document.getElementById("insert-slab-action-type")?.value,
                cantilever: document.getElementById("insert-slab-cantilever")?.checked,
                temperatureSteel: readSlabTemperatureFields("insert-slab"),
                solid: {
                    xBarDiameter: document.getElementById("insert-slab-solid-x-d")?.value,
                    xSpacing: document.getElementById("insert-slab-solid-x-s")?.value,
                    yBarDiameter: document.getElementById("insert-slab-solid-y-d")?.value,
                    ySpacing: document.getElementById("insert-slab-solid-y-s")?.value,
                    topSteelDirection: document.getElementById("insert-slab-solid-top-dir")?.value
                },
                lightened: readSlabLightenedFields("insert-slab")
            });
            syncSidebarToolButtons();
        };

        const lightenedInputIds = [
            "insert-slab-light-w",
            "insert-slab-light-h",
            "insert-slab-light-thickness",
            "insert-slab-light-gap",
            ...LIGHTENED_SLAB_ZONE_KEYS.flatMap((zoneKey) => ([
                getSlabLightenedZoneBarsFieldId("insert-slab", zoneKey, "x"),
                getSlabLightenedZoneBarsFieldId("insert-slab", zoneKey, "y")
            ]))
        ];
        const lightenedSelectIds = LIGHTENED_SLAB_ZONE_KEYS.flatMap((zoneKey) => ([
            getSlabLightenedZoneDiameterFieldId("insert-slab", zoneKey, "x"),
            getSlabLightenedZoneDiameterFieldId("insert-slab", zoneKey, "y")
        ]));

        ["insert-name", "insert-h", "insert-slab-solid-x-s", "insert-slab-solid-y-s", ...lightenedInputIds].forEach((id) => {
            document.getElementById(id)?.addEventListener("input", syncSlabDraft);
        });
        ["insert-slab-type", "insert-slab-action-type", "insert-slab-solid-x-d", "insert-slab-solid-y-d", "insert-slab-solid-top-dir", "insert-slab-cantilever", ...lightenedSelectIds].forEach((id) => {
            document.getElementById(id)?.addEventListener("change", syncSlabDraft);
        });
        ["insert-material-type", "insert-material-fc", "insert-material-fy-long", "insert-material-fy-trans"].forEach((id) => {
            document.getElementById(id)?.addEventListener("change", syncSlabDraft);
        });
        wireSlabTypeFields("insert-slab-type", dom.insertPropertiesFields);
        wireSlabTemperatureFields("insert-slab", dom.insertPropertiesFields, syncSlabDraft);
        syncSlabDraft();
    }
}

function renderModelSpaceThemeControl() {
    const isDarkMode = projectState.modelSpaceTheme === "dark";

    if (document.body) {
        document.body.dataset.uiTheme = projectState.modelSpaceTheme;
    }

    if (dom.canvasStage) {
        dom.canvasStage.dataset.modelSpaceTheme = projectState.modelSpaceTheme;
    }

    if (!dom.modelSpaceThemeToggle || !dom.modelSpaceThemeLabel) {
        return;
    }

    dom.modelSpaceThemeToggle.setAttribute("aria-checked", String(isDarkMode));
    dom.modelSpaceThemeToggle.setAttribute("title", isDarkMode ? translate("theme.switchToLight") : translate("theme.switchToDark"));
    dom.modelSpaceThemeLabel.textContent = isDarkMode ? translate("theme.dark") : translate("theme.light");
}

function renderModelSpaceLabelsControl() {
    if (!dom.modelSpaceLabelsToggle || !dom.modelSpaceLabelsLabel) {
        return;
    }

    const labelsVisible = projectState.modelSpaceLabelsVisible !== false;
    dom.modelSpaceLabelsToggle.setAttribute("aria-checked", String(labelsVisible));
    dom.modelSpaceLabelsToggle.setAttribute("title", labelsVisible ? translate("workspace.hideLabels") : translate("workspace.showLabels"));
    dom.modelSpaceLabelsLabel.textContent = labelsVisible ? translate("workspace.labelsVisible") : translate("workspace.labelsHidden");
}

function positionWorkspaceLightMenu(menuElement, anchorElement, isOpen) {
    if (!menuElement) {
        return;
    }

    if (isOpen && anchorElement) {
        const anchorRect = anchorElement.getBoundingClientRect();
        const viewportPadding = 12;
        const menuWidth = Math.max(menuElement.offsetWidth || 0, 210);
        const clampedLeft = Math.min(
            Math.max(anchorRect.left, viewportPadding),
            Math.max(viewportPadding, window.innerWidth - menuWidth - viewportPadding)
        );

        menuElement.style.position = "fixed";
        menuElement.style.top = `${Math.round(anchorRect.bottom + 8)}px`;
        menuElement.style.left = `${Math.round(clampedLeft)}px`;
        menuElement.style.right = "auto";
        menuElement.style.maxWidth = `calc(100vw - ${viewportPadding * 2}px)`;
        menuElement.style.maxHeight = "calc(100vh - 24px)";
        menuElement.style.overflowY = "auto";
        menuElement.style.zIndex = "2200";
        return;
    }

    menuElement.style.position = "";
    menuElement.style.top = "";
    menuElement.style.left = "";
    menuElement.style.right = "";
    menuElement.style.maxWidth = "";
    menuElement.style.maxHeight = "";
    menuElement.style.overflowY = "";
    menuElement.style.zIndex = "";
}

function mountWorkspaceLightMenu(menuElement) {
    if (!menuElement || !dom.canvasStage || menuElement.parentElement === dom.canvasStage) {
        return;
    }

    dom.canvasStage.appendChild(menuElement);
}

function isTargetWithinWorkspaceLightMenu(target, groupElement, menuElement) {
    return Boolean(
        target
        && (
            groupElement?.contains(target)
            || menuElement?.contains(target)
        )
    );
}

