function syncColumnStirrupHookMenuInputs() {
    const hookLengths = normalizeColumnStirrupHookLengths(projectState.columnStirrupHookLengths);
    projectState.columnStirrupHookLengths = hookLengths;
    persistColumnStirrupHookLengths(hookLengths);

    dom.quantitiesContent?.querySelectorAll("[data-column-hook-length-input]").forEach((input) => {
        const diameter = normalizeDiameterLabel(input.dataset.columnHookDiameter);
        if (!diameter) {
            return;
        }

        input.value = String(hookLengths[diameter] ?? DEFAULT_COLUMN_STIRRUP_HOOK_LENGTHS_CM[diameter] ?? DEFAULT_COLUMN_STIRRUP_HOOK_LENGTHS_CM[DEFAULT_TRANSVERSE_DIAMETER]);
    });
}

function updateColumnStirrupHookLengthFromInput(input, shouldSyncInput = false) {
    const diameter = normalizeDiameterLabel(input?.dataset?.columnHookDiameter);
    if (!diameter || !COLUMN_STIRRUP_HOOK_DIAMETERS.includes(diameter)) {
        return false;
    }

    const parsed = Number.parseFloat(String(input.value ?? "").replace(",", "."));
    if (!Number.isFinite(parsed) || parsed <= 0) {
        return false;
    }

    projectState.columnStirrupHookLengths = normalizeColumnStirrupHookLengths({
        ...normalizeColumnStirrupHookLengths(projectState.columnStirrupHookLengths),
        [diameter]: parsed
    });
    persistColumnStirrupHookLengths(projectState.columnStirrupHookLengths);
    if (shouldSyncInput) {
        input.value = String(projectState.columnStirrupHookLengths[diameter]);
    }
    return true;
}

function resetColumnStirrupHookLengths() {
    projectState.columnStirrupHookLengths = createDefaultColumnStirrupHookLengths();
    persistColumnStirrupHookLengths(projectState.columnStirrupHookLengths);
    syncColumnStirrupHookMenuInputs();
}

function escapeWorkbookXml(value) {
    return String(value ?? "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&apos;");
}

function sanitizeWorkbookSheetName(name, fallback, usedNames) {
    const reservedNames = usedNames || new Set();
    const baseName = String(name || fallback || "Sheet")
        .replace(/[\\/*?:[\]]/g, " ")
        .replace(/\s+/g, " ")
        .trim()
        .slice(0, 31) || fallback || "Sheet";

    let candidate = baseName;
    let suffix = 2;
    while (reservedNames.has(candidate.toLowerCase())) {
        const trimmedBase = baseName.slice(0, Math.max(31 - String(suffix).length - 1, 1)).trim() || fallback || "Sheet";
        candidate = `${trimmedBase}_${suffix}`.slice(0, 31);
        suffix += 1;
    }

    reservedNames.add(candidate.toLowerCase());
    return candidate;
}

const WORKBOOK_NUMBER_STYLE_ID = "number2";
const WORKBOOK_INTEGER_STYLE_ID = "number0";
const WORKBOOK_XLSX_NUMBER_STYLE_INDEX = 5;
const WORKBOOK_XLSX_INTEGER_STYLE_INDEX = 6;

function getWorkbookCellDescriptor(value, options = {}) {
    const hasCellObject = value && typeof value === "object" && !Array.isArray(value) && Object.prototype.hasOwnProperty.call(value, "value");
    const cellValue = hasCellObject ? value.value : value;
    const mergedOptions = hasCellObject
        ? {
            ...value,
            ...options
        }
        : options;
    const cellType = mergedOptions.type === "number" || typeof cellValue === "number"
        ? "number"
        : "string";

    return { cellValue, mergedOptions, cellType };
}

function formatWorkbookNumericValue(value) {
    const numericValue = Number(value);
    if (!Number.isFinite(numericValue)) {
        return "0";
    }

    const roundedValue = Math.round((numericValue + Number.EPSILON) * 1000000) / 1000000;
    return String(roundedValue);
}

function createWorkbookIntegerCell(value) {
    const numericValue = Number.parseInt(String(value ?? 0), 10);
    return {
        value: Number.isFinite(numericValue) ? Math.max(numericValue, 0) : 0,
        styleId: WORKBOOK_INTEGER_STYLE_ID,
        styleIndex: WORKBOOK_XLSX_INTEGER_STYLE_INDEX
    };
}

function buildWorkbookCellXml(value, options = {}) {
    const { cellValue, mergedOptions, cellType } = getWorkbookCellDescriptor(value, options);
    const styleAttribute = mergedOptions.styleId
        ? ` ss:StyleID="${mergedOptions.styleId}"`
        : cellType === "number"
            ? ` ss:StyleID="${WORKBOOK_NUMBER_STYLE_ID}"`
            : "";
    const mergeAttribute = Number.isInteger(mergedOptions.mergeAcross) && mergedOptions.mergeAcross > 0
        ? ` ss:MergeAcross="${mergedOptions.mergeAcross}"`
        : "";
    if (cellType === "number") {
        return `<Cell${styleAttribute}${mergeAttribute}><Data ss:Type="Number">${formatWorkbookNumericValue(cellValue)}</Data></Cell>`;
    }

    return `<Cell${styleAttribute}${mergeAttribute}><Data ss:Type="String">${escapeWorkbookXml(cellValue)}</Data></Cell>`;
}

function buildWorkbookRowXml(cells) {
    return `<Row>${cells.map((cell) => (
        cell && typeof cell === "object" && !Array.isArray(cell) && Object.prototype.hasOwnProperty.call(cell, "value")
            ? buildWorkbookCellXml(cell.value, cell)
            : buildWorkbookCellXml(cell)
    )).join("")}</Row>`;
}

function getWorkbookColumnWidths(sheet) {
    return Array.isArray(sheet?.columnWidths)
        ? sheet.columnWidths
            .map((width) => Math.max(parseNumberOrFallback(width, 0), 0))
            .filter((width) => width > 0)
        : [];
}

function buildWorkbookWorksheetXml(sheet, usedNames) {
    const headers = Array.isArray(sheet.headers) ? sheet.headers : [];
    const rows = Array.isArray(sheet.rows) ? sheet.rows : [];
    const columnWidths = getWorkbookColumnWidths(sheet);
    const columnCount = Math.max(headers.length, columnWidths.length, 2);
    const mergedColumns = Math.max(columnCount - 1, 0);
    const titleRow = buildWorkbookRowXml([
        { value: sheet.title || sheet.name || "Sheet", styleId: "title", mergeAcross: mergedColumns }
    ]);
    const totalRow = buildWorkbookRowXml([
        { value: sheet.totalLabel || "", styleId: "label" },
        sheet.totalValue ?? ""
    ]);
    const spacerRow = "<Row/>";
    const headerRow = buildWorkbookRowXml(headers.map((header) => ({ value: header, styleId: "header" })));
    const bodyRows = rows.map((row) => buildWorkbookRowXml(row));
    const sheetName = sanitizeWorkbookSheetName(sheet.name, "Sheet", usedNames);
    const columnMarkup = columnWidths.length > 0
        ? columnWidths.map((width) => `<Column ss:Width="${width.toFixed(2)}" ss:AutoFitWidth="0"/>`).join("")
        : "";

    return `
        <Worksheet ss:Name="${escapeWorkbookXml(sheetName)}">
            <Table>
                ${columnMarkup}
                ${titleRow}
                ${totalRow}
                ${spacerRow}
                ${headerRow}
                ${bodyRows.join("")}
            </Table>
        </Worksheet>
    `;
}

function buildQuantitiesWorkbookXml(sheets) {
    const usedSheetNames = new Set();
    return `<?xml version="1.0" encoding="UTF-8"?>
<?mso-application progid="Excel.Sheet"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:o="urn:schemas-microsoft-com:office:office"
 xmlns:x="urn:schemas-microsoft-com:office:excel"
 xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"
 xmlns:html="http://www.w3.org/TR/REC-html40">
    <Styles>
        <Style ss:ID="Default" ss:Name="Normal">
            <Alignment ss:Vertical="Center"/>
            <Font ss:FontName="Calibri" ss:Size="11"/>
        </Style>
        <Style ss:ID="title">
            <Font ss:FontName="Calibri" ss:Size="14" ss:Bold="1"/>
        </Style>
        <Style ss:ID="label">
            <Font ss:FontName="Calibri" ss:Size="11" ss:Bold="1"/>
        </Style>
        <Style ss:ID="header">
            <Font ss:FontName="Calibri" ss:Size="11" ss:Bold="1"/>
            <Interior ss:Color="#E8EEF5" ss:Pattern="Solid"/>
        </Style>
        <Style ss:ID="wrap">
            <Font ss:FontName="Calibri" ss:Size="11"/>
            <Alignment ss:Vertical="Center" ss:WrapText="1"/>
        </Style>
        <Style ss:ID="number2">
            <NumberFormat ss:Format="0.00"/>
        </Style>
        <Style ss:ID="number0">
            <NumberFormat ss:Format="0"/>
        </Style>
    </Styles>
    ${sheets.map((sheet) => buildWorkbookWorksheetXml(sheet, usedSheetNames)).join("")}
</Workbook>`;
}

function getWorkbookColumnLabel(index) {
    let value = Math.max(0, Number.parseInt(index, 10) || 0) + 1;
    let label = "";

    while (value > 0) {
        const remainder = (value - 1) % 26;
        label = String.fromCharCode(65 + remainder) + label;
        value = Math.floor((value - 1) / 26);
    }

    return label || "A";
}

function buildWorkbookXlsxCellXml(reference, value, styleIndex = 0) {
    const { cellValue, cellType } = getWorkbookCellDescriptor(value);
    const cellStyleIndex = value && typeof value === "object" && !Array.isArray(value) && Number.isInteger(value.styleIndex)
        ? value.styleIndex
        : styleIndex;
    const resolvedStyleIndex = cellType === "number" && cellStyleIndex === 0
        ? WORKBOOK_XLSX_NUMBER_STYLE_INDEX
        : cellStyleIndex;

    if (cellType === "number") {
        return `<c r="${reference}" s="${resolvedStyleIndex}" t="n"><v>${formatWorkbookNumericValue(cellValue)}</v></c>`;
    }

    return `<c r="${reference}" s="${cellStyleIndex}" t="inlineStr"><is><t xml:space="preserve">${escapeWorkbookXml(cellValue)}</t></is></c>`;
}

function buildWorkbookXlsxRowXml(rowIndex, values, styleIndex = 0) {
    const cells = values.map((value, columnIndex) => (
        buildWorkbookXlsxCellXml(`${getWorkbookColumnLabel(columnIndex)}${rowIndex}`, value, styleIndex)
    ));
    return `<row r="${rowIndex}">${cells.join("")}</row>`;
}

function buildWorkbookXlsxWorksheetXml(sheet, usedNames) {
    const headers = Array.isArray(sheet.headers) ? sheet.headers : [];
    const rows = Array.isArray(sheet.rows) ? sheet.rows : [];
    const columnWidths = getWorkbookColumnWidths(sheet);
    const sheetName = sanitizeWorkbookSheetName(sheet.name, "Sheet", usedNames);
    const columnCount = Math.max(headers.length, columnWidths.length, 2);
    const lastColumn = getWorkbookColumnLabel(columnCount - 1);
    const worksheetRows = [
        buildWorkbookXlsxRowXml(1, [sheet.title || sheetName], 1),
        `<row r="2">${buildWorkbookXlsxCellXml("A2", sheet.totalLabel || "", 2)}${buildWorkbookXlsxCellXml("B2", sheet.totalValue ?? "", 0)}</row>`,
        "<row r=\"3\"/>",
        buildWorkbookXlsxRowXml(4, headers, 3),
        ...rows.map((row, index) => buildWorkbookXlsxRowXml(5 + index, row, 0))
    ];
    const columnsXml = columnWidths.length > 0
        ? `<cols>${columnWidths.map((width, index) => `<col min="${index + 1}" max="${index + 1}" width="${width.toFixed(2)}" customWidth="1"/>`).join("")}</cols>`
        : "";
    const mergeCells = columnCount > 1
        ? `<mergeCells count="1"><mergeCell ref="A1:${lastColumn}1"/></mergeCells>`
        : "";
    const lastRowIndex = Math.max(4 + rows.length, 4);

    return {
        sheetName,
        xml: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
    <dimension ref="A1:${lastColumn}${lastRowIndex}"/>
    <sheetViews>
        <sheetView workbookViewId="0"/>
    </sheetViews>
    <sheetFormatPr defaultRowHeight="15"/>
    ${columnsXml}
    <sheetData>
        ${worksheetRows.join("")}
    </sheetData>
    ${mergeCells}
</worksheet>`
    };
}

