function getWorkbookZipTextEncoder() {
    if (!getWorkbookZipTextEncoder.encoder) {
        getWorkbookZipTextEncoder.encoder = new TextEncoder();
    }

    return getWorkbookZipTextEncoder.encoder;
}

function encodeWorkbookZipText(value) {
    return getWorkbookZipTextEncoder().encode(String(value ?? ""));
}

function getWorkbookZipCrcTable() {
    if (getWorkbookZipCrcTable.table) {
        return getWorkbookZipCrcTable.table;
    }

    const table = new Uint32Array(256);
    for (let index = 0; index < 256; index += 1) {
        let crc = index;
        for (let bit = 0; bit < 8; bit += 1) {
            crc = (crc & 1) ? (0xEDB88320 ^ (crc >>> 1)) : (crc >>> 1);
        }
        table[index] = crc >>> 0;
    }

    getWorkbookZipCrcTable.table = table;
    return table;
}

function computeWorkbookZipCrc32(bytes) {
    const table = getWorkbookZipCrcTable();
    let crc = 0xFFFFFFFF;

    for (let index = 0; index < bytes.length; index += 1) {
        crc = table[(crc ^ bytes[index]) & 0xFF] ^ (crc >>> 8);
    }

    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function createWorkbookZipHeader(byteLength) {
    const buffer = new ArrayBuffer(byteLength);
    return {
        buffer,
        view: new DataView(buffer),
        bytes: new Uint8Array(buffer)
    };
}

function getWorkbookZipDosDateTime(date = new Date()) {
    const safeDate = date instanceof Date && Number.isFinite(date.getTime()) ? date : new Date();
    const year = Math.max(safeDate.getFullYear(), 1980);

    return {
        date: (((year - 1980) & 0x7F) << 9) | (((safeDate.getMonth() + 1) & 0x0F) << 5) | (safeDate.getDate() & 0x1F),
        time: ((safeDate.getHours() & 0x1F) << 11) | ((safeDate.getMinutes() & 0x3F) << 5) | Math.floor((safeDate.getSeconds() || 0) / 2)
    };
}

function buildWorkbookXlsxZipBlob(files) {
    const localParts = [];
    const centralParts = [];
    let offset = 0;

    files.forEach((file) => {
        const fileNameBytes = encodeWorkbookZipText(file.path);
        const fileBytes = file.bytes instanceof Uint8Array ? file.bytes : encodeWorkbookZipText(file.bytes);
        const crc32 = computeWorkbookZipCrc32(fileBytes);
        const { date, time } = getWorkbookZipDosDateTime(file.date);

        const localHeader = createWorkbookZipHeader(30);
        localHeader.view.setUint32(0, 0x04034B50, true);
        localHeader.view.setUint16(4, 20, true);
        localHeader.view.setUint16(6, 0, true);
        localHeader.view.setUint16(8, 0, true);
        localHeader.view.setUint16(10, time, true);
        localHeader.view.setUint16(12, date, true);
        localHeader.view.setUint32(14, crc32, true);
        localHeader.view.setUint32(18, fileBytes.length, true);
        localHeader.view.setUint32(22, fileBytes.length, true);
        localHeader.view.setUint16(26, fileNameBytes.length, true);
        localHeader.view.setUint16(28, 0, true);
        localParts.push(localHeader.bytes, fileNameBytes, fileBytes);

        const centralHeader = createWorkbookZipHeader(46);
        centralHeader.view.setUint32(0, 0x02014B50, true);
        centralHeader.view.setUint16(4, 20, true);
        centralHeader.view.setUint16(6, 20, true);
        centralHeader.view.setUint16(8, 0, true);
        centralHeader.view.setUint16(10, 0, true);
        centralHeader.view.setUint16(12, time, true);
        centralHeader.view.setUint16(14, date, true);
        centralHeader.view.setUint32(16, crc32, true);
        centralHeader.view.setUint32(20, fileBytes.length, true);
        centralHeader.view.setUint32(24, fileBytes.length, true);
        centralHeader.view.setUint16(28, fileNameBytes.length, true);
        centralHeader.view.setUint16(30, 0, true);
        centralHeader.view.setUint16(32, 0, true);
        centralHeader.view.setUint16(34, 0, true);
        centralHeader.view.setUint16(36, 0, true);
        centralHeader.view.setUint32(38, 0, true);
        centralHeader.view.setUint32(42, offset, true);
        centralParts.push(centralHeader.bytes, fileNameBytes);

        offset += localHeader.bytes.length + fileNameBytes.length + fileBytes.length;
    });

    const centralDirectorySize = centralParts.reduce((sum, part) => sum + part.length, 0);
    const endRecord = createWorkbookZipHeader(22);
    endRecord.view.setUint32(0, 0x06054B50, true);
    endRecord.view.setUint16(4, 0, true);
    endRecord.view.setUint16(6, 0, true);
    endRecord.view.setUint16(8, files.length, true);
    endRecord.view.setUint16(10, files.length, true);
    endRecord.view.setUint32(12, centralDirectorySize, true);
    endRecord.view.setUint32(16, offset, true);
    endRecord.view.setUint16(20, 0, true);

    return new Blob(
        [...localParts, ...centralParts, endRecord.bytes],
        { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }
    );
}

function buildQuantitiesWorkbookXlsxBlob(sheets) {
    const usedSheetNames = new Set();
    const worksheets = sheets.map((sheet) => buildWorkbookXlsxWorksheetXml(sheet, usedSheetNames));
    const workbookFiles = [
        { path: "[Content_Types].xml", bytes: encodeWorkbookZipText(buildWorkbookXlsxContentTypesXml(worksheets.length)) },
        { path: "_rels/.rels", bytes: encodeWorkbookZipText(buildWorkbookXlsxRootRelsXml()) },
        { path: "docProps/app.xml", bytes: encodeWorkbookZipText(buildWorkbookXlsxAppPropsXml(worksheets)) },
        { path: "docProps/core.xml", bytes: encodeWorkbookZipText(buildWorkbookXlsxCorePropsXml()) },
        { path: "xl/workbook.xml", bytes: encodeWorkbookZipText(buildWorkbookXlsxWorkbookXml(worksheets)) },
        { path: "xl/_rels/workbook.xml.rels", bytes: encodeWorkbookZipText(buildWorkbookXlsxWorkbookRelsXml(worksheets.length)) },
        { path: "xl/styles.xml", bytes: encodeWorkbookZipText(buildWorkbookXlsxStylesXml()) },
        ...worksheets.map((sheet, index) => ({
            path: `xl/worksheets/sheet${index + 1}.xml`,
            bytes: encodeWorkbookZipText(sheet.xml)
        }))
    ];

    return buildWorkbookXlsxZipBlob(workbookFiles);
}

function getQuantityWorkbookSheets(summary, selections) {
    const sheets = [];
    const beamDetailItems = selections.steel || selections.breakdown
        ? getBeamSectionDetailWorkbookItems()
        : [];

    if (selections.concrete) {
        sheets.push({
            name: translate("quantities.report.concrete"),
            title: translate("quantities.report.concrete"),
            totalLabel: translate("quantities.totalConcrete"),
            totalValue: summary.concreteTotal,
            columnWidths: [18, 18, 28, 14, 18],
            headers: [
                translate("quantities.level"),
                translate("quantities.element"),
                translate("quantities.name"),
                translate("quantities.multiplicator"),
                translate("quantities.quantityConcrete")
            ],
            rows: buildGroupedQuantityWorkbookRows(summary.concreteGroups)
        });
    }

    if (selections.steel) {
        sheets.push({
            name: translate("quantities.report.steel"),
            title: translate("quantities.report.steel"),
            totalLabel: translate("quantities.totalSteel"),
            totalValue: summary.steelTotalTon,
            columnWidths: [18, 18, 28, 14, 18],
            headers: [
                translate("quantities.level"),
                translate("quantities.element"),
                translate("quantities.name"),
                translate("quantities.multiplicator"),
                translate("quantities.quantitySteel")
            ],
            rows: buildGroupedQuantityWorkbookRows(summary.steelGroups)
        });
    }

    if (beamDetailItems.length > 0) {
        sheets.push({
            name: translate("quantities.report.beamDetail"),
            title: translate("quantities.report.beamDetail"),
            totalLabel: translate("quantities.beamDetailSections"),
            totalValue: beamDetailItems.length,
            columnWidths: [12, 18, 18, 22, 38, 22, 38, 18],
            headers: [
                translate("quantities.level"),
                translate("quantities.beamDetailBeam"),
                translate("quantities.beamDetailZones"),
                translate("quantities.beamDetailTop"),
                translate("quantities.beamDetailTopDetail"),
                translate("quantities.beamDetailBottom"),
                translate("quantities.beamDetailBottomDetail"),
                translate("quantities.beamDetailStirrups")
            ],
            rows: beamDetailItems.map((item) => ([
                item.levelName,
                item.beamName,
                item.zoneSummary,
                item.topSummary,
                { value: item.topDetail, styleIndex: 4 },
                item.bottomSummary,
                { value: item.bottomDetail, styleIndex: 4 },
                item.stirrups
            ]))
        });
    }

    if (selections.breakdown) {
        sheets.push({
            name: translate("quantities.report.breakdown"),
            title: translate("quantities.report.breakdown"),
            totalLabel: translate("quantities.totalSteel"),
            totalValue: summary.steelTotalTon,
            headers: [
                translate("quantities.level"),
                translate("quantities.element"),
                translate("quantities.name"),
                translate("quantities.breakdownItem"),
                translate("quantities.count"),
                translate("quantities.diameter"),
                translate("quantities.unitLength"),
                translate("quantities.totalLength"),
                translate("quantities.totalWeight")
            ],
            rows: summary.steelBreakdownItems.map((item) => ([
                item.levelName,
                item.typeLabel,
                item.name,
                item.label,
                item.count,
                item.diameter,
                item.unitLength,
                item.totalLength,
                item.weightTon
            ]))
        });
    }

    if (selections.blocks) {
        sheets.push({
            name: translate("quantities.report.blocks"),
            title: translate("quantities.report.blocks"),
            totalLabel: translate("quantities.totalBlocks"),
            totalValue: summary.blockTotalUnits,
            columnWidths: [18, 18, 28, 18, 14, 18],
            headers: [
                translate("quantities.level"),
                translate("quantities.element"),
                translate("quantities.name"),
                translate("quantities.blockWidth"),
                translate("quantities.multiplicator"),
                translate("quantities.quantityBlocks")
            ],
            rows: buildGroupedQuantityWorkbookRows(summary.blockGroups, { includeBlockWidth: true })
        });
    }

    if (selections.apu) {
        const groupedApuWorkbookRows = buildGroupedApuWorkbookRows(summary.apuWorkbookRows);
        const pricedApuWorkbookRows = buildPricedApuWorkbookRows(groupedApuWorkbookRows);
        sheets.push({
            name: translate("quantities.report.apu"),
            title: translate("quantities.report.apu"),
            totalLabel: translate("quantities.apuSummaryLabel"),
            totalValue: summary.apuItems.length,
            columnWidths: [12, 14, 22, 12, 16, 18, 16, 14, 12, 12, 48, 22, 10, 14, 14, 14, 18, 16],
            headers: [
                translate("quantities.level"),
                translate("quantities.element"),
                translate("quantities.name"),
                translate("quantities.multiplicator"),
                translate("quantities.apuLength"),
                translate("quantities.apuSection"),
                translate("quantities.apuSteelType"),
                translate("quantities.apuDirection"),
                translate("quantities.apuRib"),
                translate("quantities.apuLayer"),
                translate("quantities.apuSteelSummary"),
                translate("quantities.apuMaterial"),
                translate("quantities.apuUnit"),
                translate("quantities.apuQuantity"),
                translate("quantities.apuUnitPrice"),
                translate("quantities.apuAmount"),
                translate("quantities.apuConcreteVolume"),
                translate("quantities.apuSteelTotal")
            ],
            rows: pricedApuWorkbookRows.map((item) => ([
                item.levelName,
                item.typeLabel,
                item.name,
                createWorkbookIntegerCell(item.multiplicator),
                Math.max(parseNumberOrFallback(item.length, 0), 0),
                item.sectionLabel,
                item.steelTypeLabel || "",
                item.steelDirectionLabel || "",
                item.steelZoneLabel || "",
                item.steelLayerLabel || "",
                {
                    value: item.steelSummary,
                    styleId: "wrap",
                    styleIndex: 4
                },
                item.materialLabel || "",
                item.materialUnit || "",
                Math.max(parseNumberOrFallback(item.materialQuantity, 0), 0),
                Math.max(parseNumberOrFallback(item.unitPrice, 0), 0),
                Math.max(parseNumberOrFallback(item.amount, 0), 0),
                Math.max(parseNumberOrFallback(item.concreteVolume, 0), 0),
                Math.max(parseNumberOrFallback(item.steelWeightQq, 0), 0)
            ]))
        });
    }

    return sheets;
}

async function requestQuantitiesApi(payload) {
    const requestBody = await createJsonRequestInitBody({
        project: getProjectSnapshot(),
        hookLengths: projectState.columnStirrupHookLengths,
        ...payload
    });
    const response = await fetch("/api/quantities", {
        method: "POST",
        headers: requestBody.headers,
        body: requestBody.body
    });

    if (!response.ok) {
        let message = translate("quantities.loadError");

        try {
            const payload = await response.json();
            if (typeof payload?.error === "string" && payload.error.trim()) {
                message = payload.error;
            }
        } catch (error) {
            // Keep translated fallback.
        }

        throw new Error(message);
    }

    return response;
}

async function fetchQuantitiesSummary() {
    const response = await requestQuantitiesApi({ action: "summary" });
    const payload = await response.json();
    return payload?.summary || createEmptyQuantitySummary();
}

async function downloadQuantitiesWorkbook(selectedReports = projectState.quantityReportSelections || {}) {
    const projectName = String(dom.projectNameInput?.value || projectState.currentProjectName || getDefaultProjectName(projectState.language)).trim()
        || getDefaultProjectName(projectState.language);
    const projectStem = toSafeFileStem(projectName, "project");
    try {
        const response = await requestQuantitiesApi({
            action: "xlsx",
            selections: selectedReports,
            projectName
        });
        const blob = await response.blob();
        if (!blob || blob.size <= 0) {
            throw new Error(translate("quantities.loadError"));
        }

        const fileName = parseContentDispositionFileName(response.headers.get("content-disposition"))
            ?? `${projectStem}_${toSafeFileStem(translate("quantities.fileName"), "quantities")}.xlsx`;
        downloadBlobFile(blob, fileName);
        trackDownloadEvent({
            intent: "download",
            exportKind: "excel",
            exportFormat: "xlsx",
            fileName,
            selection: "quantities",
            downloadedPlans: Object.entries(selectedReports || {})
                .filter(([, selected]) => Boolean(selected))
                .map(([key]) => key)
        });
    } catch (error) {
        openAppNoticeDialog({
            title: translate("dialog.exportErrorTitle"),
            message: error?.message || translate("quantities.loadError")
        });
    }
}

function downloadAllQuantitiesWorkbook() {
    void downloadQuantitiesWorkbook({
        concrete: true,
        steel: true,
        breakdown: true,
        blocks: true,
        apu: true
    });
}

function bindQuantitiesSectionEvents() {
    Array.from(dom.quantitiesContent.querySelectorAll("[data-quantity-panel]")).forEach((panel) => {
        panel.addEventListener("toggle", () => {
            const key = panel.dataset.quantityPanel;
            if (key) {
                projectState.quantityPanelsOpen[key] = panel.open;
            }
        });
    });

    Array.from(dom.quantitiesContent.querySelectorAll("[data-quantity-report]")).forEach((checkbox) => {
        checkbox.addEventListener("change", () => {
            const key = checkbox.dataset.quantityReport;
            if (key) {
                projectState.quantityReportSelections[key] = checkbox.checked;
                void renderQuantitiesSection();
            }
        });
    });

    dom.quantitiesContent.querySelectorAll("[data-column-hook-length-input]").forEach((input) => {
        input.addEventListener("input", () => {
            updateColumnStirrupHookLengthFromInput(input);
        });

        input.addEventListener("change", () => {
            updateColumnStirrupHookLengthFromInput(input, true);
            syncColumnStirrupHookMenuInputs();
        });
    });

    dom.quantitiesContent.querySelector("[data-column-hook-reset-btn]")?.addEventListener("click", () => {
        resetColumnStirrupHookLengths();
    });

    syncColumnStirrupHookMenuInputs();

    dom.quantitiesContent.querySelector("#quantities-export-csv-btn")?.addEventListener("click", () => {
        void downloadQuantitiesWorkbook();
    });
}

async function renderQuantitiesSection() {
    if (!dom.quantitiesSection || !dom.quantitiesSectionTitle || !dom.quantitiesSectionCopy || !dom.quantitiesContent) {
        return;
    }

    dom.quantitiesSectionTitle.textContent = translate("quantities.sectionTitle");
    if (dom.quantitiesSectionChip) {
        dom.quantitiesSectionChip.textContent = translate("quantities.sectionChip");
    }
    dom.quantitiesSectionCopy.textContent = translate("quantities.sectionCopy");

    const requestId = (projectState.quantitiesRenderRequestId || 0) + 1;
    projectState.quantitiesRenderRequestId = requestId;
    dom.quantitiesContent.innerHTML = buildQuantitiesSectionMarkup(createEmptyQuantitySummary(), "");
    bindQuantitiesSectionEvents();

    try {
        const summary = await fetchQuantitiesSummary();
        if (projectState.quantitiesRenderRequestId !== requestId) {
            return;
        }

        dom.quantitiesContent.innerHTML = buildQuantitiesSectionMarkup(summary, "");
    } catch (error) {
        if (projectState.quantitiesRenderRequestId !== requestId) {
            return;
        }

        console.error("Failed to compute quantities summary.", error);
        dom.quantitiesContent.innerHTML = buildQuantitiesSectionMarkup(createEmptyQuantitySummary(), translate("quantities.loadError"));
    }

    bindQuantitiesSectionEvents();
}

function parseContentDispositionFileName(headerValue) {
    if (!headerValue) {
        return null;
    }

    const utf8Match = headerValue.match(/filename\*=UTF-8''([^;]+)/i);
    if (utf8Match?.[1]) {
        return decodeURIComponent(utf8Match[1]);
    }

    const simpleMatch = headerValue.match(/filename="([^"]+)"/i);
    if (simpleMatch?.[1]) {
        return simpleMatch[1];
    }

    return null;
}

function getDefaultExportFileName(outputMode, selection) {
    if (outputMode === "custom") {
        return "Exportacion_estructural.dxf";
    }

    if (outputMode === "slab") {
        return getLevelExportFileName("Plano_de_losa", selection);
    }

    if (outputMode === "column") {
        return getLevelExportFileName("Columnas", selection);
    }

    if (outputMode === "wall") {
        return getLevelExportFileName("Muros", selection);
    }

    return getFrameExportFileName(selection);
}

function getExportDockRequestConfig() {
    const groups = {};

    Object.keys(EXPORT_DOCK_GROUP_DEFINITIONS).forEach((groupKey) => {
        groups[groupKey] = getExportDockResolvedItems(groupKey);
    });

    return {
        groups,
        drawingPreferences: normalizeExportDockDrawingPreferences(projectState.exportDock?.drawingPreferences),
        frameScope: projectState.exportDock?.frameScope || "all",
        frames: getExportDockSelectedFrames(),
        customFrames: Array.isArray(projectState.exportDock?.customFrames) ? [...projectState.exportDock.customFrames] : [],
        slabLevelScope: "all",
        slabLevelIds: projectState.levels
            .filter((level) => hasSlabExportContent(level))
            .map((level) => level.id)
    };
}

function hasAnyExportDockRequestItems(exportConfig) {
    return Object.values(exportConfig?.groups || {}).some((items) => Object.values(items || {}).some(Boolean));
}

function getExportDockValidationMessage(exportConfig) {
    if (!hasAnyExportDockRequestItems(exportConfig)) {
        return translate("exportDock.errors.empty");
    }

    return "";
}

function hasSteelSummaryTableData() {
    return getProjectQuantityEntries().some((entry) => (
        getSteelBreakdownForQuantityEntry(entry.type, entry.element, entry.level)
            .some((item) => {
                const totalLength = Math.max(parseNumberOrFallback(item?.totalLength, 0), 0);
                const diameterMeters = Math.max(parseDiameterInMeters(item?.diameter), 0);
                return totalLength > 0 && diameterMeters > 0;
            })
    ));
}

function getExportDockWarnings(exportConfig) {
    const warnings = [];
    const includeFrameBeamIndividualDetails = normalizeExportDockDrawingPreferences(exportConfig?.drawingPreferences).frameElevation.includeFrameBeamIndividualDetails === true;
    const detailGroup = exportConfig.groups?.details || {};
    const slabGroup = exportConfig.groups?.slabs || {};
    const frameGroup = exportConfig.groups?.frames || {};
    const beamGroup = exportConfig.groups?.beams || {};
    const concreteGroup = exportConfig.groups?.concrete || {};
    const masonryGroup = exportConfig.groups?.masonry || {};
    const roofGroup = exportConfig.groups?.roof || {};
    const foundationGroup = exportConfig.groups?.foundations || {};

    if ((frameGroup.elevation || frameGroup.sections) && (!Array.isArray(exportConfig.frames) || exportConfig.frames.length === 0)) {
        warnings.push(translate("exportDock.errors.noFrames"));
    }

    if ((beamGroup.detail || beamGroup.sections) && getStandaloneBeamExportEntries(projectState.levels, { includeFrameBeams: includeFrameBeamIndividualDetails }).length === 0) {
        warnings.push(translate("exportDock.errors.noStandaloneBeams"));
    }

    if ((concreteGroup.columnPlan || concreteGroup.columnElevation || concreteGroup.columnSections) && !projectState.levels.some((level) => (level.columns?.length || 0) > 0)) {
        warnings.push(translate("exportDock.errors.noColumnContent"));
    }

    if (concreteGroup.wallPlan && !projectState.levels.some((level) => (level.walls || []).some((wall) => {
        const material = normalizeWall(wall).material;
        return material === "concrete" || material === "thin_wall";
    }))) {
        warnings.push(translate("exportDock.errors.noWallContent"));
    }

    if (concreteGroup.wallSections && !projectState.levels.some((level) => (level.walls || []).some((wall) => normalizeWall(wall).material === "concrete"))) {
        warnings.push(translate("exportDock.errors.noConcreteWallContent"));
    }

    if (concreteGroup.thinWallSections && !projectState.levels.some((level) => (level.walls || []).some((wall) => normalizeWall(wall).material === "thin_wall"))) {
        warnings.push(translate("exportDock.errors.noThinWallContent"));
    }

    if ((masonryGroup.wallSections || masonryGroup.longitudinal || masonryGroup.reinforcementDetail || masonryGroup.wallIntersections) && !projectState.levels.some((level) => (level.walls || []).some((wall) => normalizeWall(wall).material === "masonry"))) {
        warnings.push(translate("exportDock.errors.noMasonryWallContent"));
    }

    if (roofGroup.framingPlan && !projectHasRoofTrusses()) {
        warnings.push(translate("exportDock.errors.noRoofTrussContent"));
    }

    if ((slabGroup.plan || slabGroup.bovedillaQuantity || slabGroup.table || slabGroup.solidTable || slabGroup.slabThickness) && !projectState.levels.some((level) => hasSlabExportContent(level))) {
        warnings.push(translate("exportDock.errors.noSlabContent"));
    }

    if ((detailGroup.bovedillaQuantity || slabGroup.bovedillaQuantity) && !projectState.levels.some((level) => (
        (level?.slabs || []).some((slab) => normalizeSlabType(normalizeSlab(slab).type) === "lightened")
    ))) {
        warnings.push(translate("exportDock.errors.noBovedillaQuantity"));
    }

    if ((foundationGroup.plan || foundationGroup.sections) && !projectState.levels.some((level) => hasFoundationExportContent(level))) {
        warnings.push(translate("exportDock.errors.noFoundationContent"));
    }

    if (detailGroup.steelSummary && !hasSteelSummaryTableData()) {
        warnings.push(translate("exportDock.errors.noSteelSummary"));
    }

    if (slabGroup.slabThickness && !projectState.levels.some((level) => getSolidSlabThicknessTableRows(level).length > 0)) {
        warnings.push(translate("exportDock.errors.noSolidSlabs"));
    }

    if (slabGroup.solidTable && !projectState.levels.some((level) => getSolidSlabReinforcementTableRows(level).length > 0)) {
        warnings.push(translate("exportDock.errors.noSolidSlabReinforcement"));
    }

    return Array.from(new Set(warnings.filter(Boolean)));
}

function projectHasBeamElements() {
    return projectState.levels.some((level) => (level?.beams?.length || 0) > 0);
}

function projectHasConcreteBeamElements() {
    return projectState.levels.some((level) => (
        (level?.beams || []).some((beam) => !isStructuralSteelElement(beam))
    ));
}

function hasImportedEtabsBeamSteel() {
    return projectState.levels.some((level) => (
        (level?.beams || []).some((beam) => !isStructuralSteelElement(beam) && hasBeamSteelDemands(beam))
    ));
}

function shouldPromptForEtabsBeamSteelBeforeDxfExport() {
    return projectHasConcreteBeamElements()
        && !hasImportedEtabsBeamSteel();
}

function buildEtabsBeamSteelImportInstructionsMarkup() {
    const prefix = getEtabsHelpTranslationPrefix("steel");
    const steps = [1, 2, 3, 4, 5, 6].map((step) => (
        `<li>${escapeHtml(translate(`${prefix}Step${step}`))}</li>`
    )).join("");

    return `
        <div class="app-dialog-form-copy">
            <span class="app-dialog-form-label">${escapeHtml(translate(`${prefix}Summary`))}</span>
            <ol class="etabs-help-steps">${steps}</ol>
            <span class="app-dialog-form-note">${escapeHtml(translate(`${prefix}Footnote`))}</span>
        </div>
    `;
}

async function requestEtabsBeamSteelBeforeDxfExport() {
    if (!shouldPromptForEtabsBeamSteelBeforeDxfExport()) {
        return true;
    }

    const continueWithoutImport = await requestAppConfirmation({
        title: translate("dialog.beamSteelMissingTitle"),
        message: translate("dialog.beamSteelMissingMessage"),
        confirmLabel: translate("dialog.beamSteelMissingContinue"),
        cancelLabel: translate("dialog.beamSteelMissingImport"),
        closeOnOverlay: false,
        closeOnEscape: false,
        autoFocusSelector: "#app-dialog-confirm-btn"
    });

    if (continueWithoutImport) {
        return true;
    }

    const shouldImport = await requestAppConfirmation({
        title: translate("dialog.beamSteelImportTitle"),
        message: translate("dialog.beamSteelImportMessage"),
        bodyHtml: buildEtabsBeamSteelImportInstructionsMarkup(),
        confirmLabel: translate("dialog.beamSteelImportAction"),
        cancelLabel: translate("dialog.cancel"),
        closeOnOverlay: false,
        closeOnEscape: true,
        autoFocusSelector: "#app-dialog-confirm-btn"
    });

    if (shouldImport) {
        triggerEtabsBeamSteelImport();
    }

    return false;
}

const JSON_REQUEST_COMPRESSION_MIN_BYTES = 64 * 1024;

function getUtf8ByteLength(value) {
    const text = String(value ?? "");

    if (typeof TextEncoder !== "undefined") {
        return new TextEncoder().encode(text).byteLength;
    }

    if (typeof Blob !== "undefined") {
        return new Blob([text]).size;
    }

    return text.length;
}

function canCompressJsonRequest() {
    return typeof CompressionStream === "function"
        && typeof Blob === "function"
        && typeof Response === "function";
}

async function gzipTextForRequest(text) {
    const source = new Blob([text], { type: "application/json" }).stream();
    const compressedStream = source.pipeThrough(new CompressionStream("gzip"));
    return new Response(compressedStream).arrayBuffer();
}

async function createJsonRequestInitBody(payload) {
    const json = JSON.stringify(payload);
    const headers = {
        "Content-Type": "application/json"
    };
    const rawByteLength = getUtf8ByteLength(json);

    if (rawByteLength >= JSON_REQUEST_COMPRESSION_MIN_BYTES && canCompressJsonRequest()) {
        try {
            const compressedBody = await gzipTextForRequest(json);
            if (compressedBody.byteLength > 0 && compressedBody.byteLength < rawByteLength) {
                headers["Content-Encoding"] = "gzip";
                return {
                    body: compressedBody,
                    headers
                };
            }
        } catch (error) {
            // Fall back to plain JSON when browser compression is unavailable.
        }
    }

    return {
        body: json,
        headers
    };
}

async function exportDockSelectionToDXF() {
    const exportConfig = getExportDockRequestConfig();
    const validationMessage = getExportDockValidationMessage(exportConfig);
    const exportWarnings = getExportDockWarnings(exportConfig);
    if (validationMessage) {
        openAppNoticeDialog({
            title: translate("dialog.exportErrorTitle"),
            message: validationMessage
        });
        return;
    }

    const canExport = await ensureBillingStatusReady({
        outputMode: "custom",
        selection: "custom|dock",
        exportConfig,
        requireBillingChoice: true,
        pendingFreeDxfExportAction: exportDockSelectionToDXF
    });
    if (!canExport) {
        return;
    }

    const canContinueWithBeamSteel = await requestEtabsBeamSteelBeforeDxfExport();
    if (!canContinueWithBeamSteel) {
        return;
    }

    const originalLabel = dom.exportDockRunButton?.textContent || translate("exportDock.run");
    if (dom.exportDockRunButton) {
        dom.exportDockRunButton.disabled = true;
        dom.exportDockRunButton.textContent = translate("buttons.generating");
    }

    try {
        const requestBody = await createJsonRequestInitBody({
            project: getProjectSnapshot(),
            projectName: String(projectState.currentProjectName || dom.projectNameInput?.value || "").trim(),
            outputMode: "custom",
            selection: "custom|dock",
            exportConfig
        });
        const response = await fetch("/api/export", {
            method: "POST",
            headers: requestBody.headers,
            body: requestBody.body
        });

        if (!response.ok) {
            let message = `No se pudo generar el DXF (${response.status}).`;

            try {
                const payload = await response.json();
                if (typeof payload?.error === "string" && payload.error.trim()) {
                    message = payload.error;
                }
            } catch (error) {
                // Keep generic message.
            }

            throw new Error(message);
        }

        const blob = await response.blob();
        if (!blob || blob.size <= 0) {
            throw new Error(projectState.language === "en"
                ? "The downloaded file is empty."
                : "El archivo descargado esta vacio.");
        }
        const fileName = parseContentDispositionFileName(response.headers.get("content-disposition"))
            ?? getDefaultExportFileName("custom", "");
        const downloadId = String(response.headers.get("x-download-id") || "").trim();
        downloadBlobFile(blob, fileName);
        if (exportWarnings.length > 0) {
            window.setTimeout(() => {
                openAppNoticeDialog({
                    title: translate("dialog.exportWarningTitle"),
                    message: exportWarnings.join("\n"),
                    autoCloseMs: 4200
                });
            }, 180);
        }
        await refreshBillingStatus({ silent: true });
        openDownloadFeedbackOverlay({
            downloadId,
            fileName,
            outputMode: "custom",
            selection: "custom|dock"
        });
    } catch (error) {
        openAppNoticeDialog({
            title: translate("dialog.exportErrorTitle"),
            message: error?.message || translate("errors.exportFailed")
        });
    } finally {
        if (dom.exportDockRunButton) {
            dom.exportDockRunButton.disabled = !hasExportDockSelection();
            dom.exportDockRunButton.textContent = originalLabel;
        }
    }
}

/* SERVER_ONLY_START */
function downloadDxfFile(dxf, fileName) {
    const blob = new Blob([dxf.join("\n")], { type: "application/dxf" });
    const objectUrl = URL.createObjectURL(blob);
    triggerObjectUrlDownload(objectUrl, fileName);
}

function exportToDXF() {
    if (projectState.outputMode === "slab") {
        exportSlabPlanToDXF();
        return;
    }

    if (projectState.outputMode === "column") {
        exportColumnDetailsToDXF();
        return;
    }

    if (projectState.outputMode === "wall") {
        exportWallDetailsToDXF();
        return;
    }

    const selection = dom.exportAxisSelect;
    if (!selection.value) {
        return;
    }
    const result = buildFrameDxfExport(selection.value);
    downloadDxfFile(result.dxf, result.fileName);
}
/* SERVER_ONLY_END */

function getColumnDetailLabelKey(column) {
    return normalizeTextValue(column?.name).toLowerCase();
}

function getUniqueColumnsForDetailExport(level) {
    const uniqueColumns = [];
    const seenNames = new Set();

    (level?.columns || []).forEach((column) => {
        const normalizedName = getColumnDetailLabelKey(column);
        if (!normalizedName) {
            uniqueColumns.push(column);
            return;
        }

        if (seenNames.has(normalizedName)) {
            return;
        }

        seenNames.add(normalizedName);
        uniqueColumns.push(column);
    });

    return uniqueColumns;
}

function buildColumnDetailEntries(level) {
    const uniqueColumns = getUniqueColumnsForDetailExport(level);

    return uniqueColumns
        .map((column, index) => ({
            tag: `C${index + 1}`,
            column,
            levelName: level.name
        }));
}

function buildWallDetailEntries(level) {
    const detailItems = ["concrete", "thin_wall", "masonry"]
        .flatMap((material) => getGroupedWallDetailItemsForLevel(level, material));
    const seenNamedWallDetails = new Set();
    const filteredDetailItems = detailItems.filter((wall) => {
        const normalizedWall = normalizeWall(wall);
        if (normalizedWall.material === "masonry") {
            return true;
        }
        const nameKey = normalizeTextValue(getWallDetailDisplayName(normalizedWall)).toLowerCase();
        if (!nameKey) {
            return true;
        }
        if (seenNamedWallDetails.has(nameKey)) {
            return false;
        }
        seenNamedWallDetails.add(nameKey);
        return true;
    });

    return filteredDetailItems.map((wall, index) => ({
        tag: `M${index + 1}`,
        wall,
        groupWalls: Array.isArray(wall?.detailWalls)
            ? wall.detailWalls.map((item) => normalizeWall(item))
            : null,
        levelName: level?.name || ""
    }));
}

function getDetailMetricKey(value, decimals = 3) {
    return parseNumberOrFallback(value, 0).toFixed(decimals);
}

function getSpanishOrdinalLabel(number) {
    if (number === 1) {
        return "1ER";
    }
    if (number === 2) {
        return "2DO";
    }
    if (number === 3) {
        return "3ER";
    }
    if (number === 7) {
        return "7MO";
    }
    if (number === 8) {
        return "8VO";
    }
    if (number === 9) {
        return "9NO";
    }
    return `${number}TO`;
}

function getEnglishOrdinalLabel(number) {
    const modHundred = number % 100;
    if (modHundred >= 11 && modHundred <= 13) {
        return `${number}TH`;
    }

    switch (number % 10) {
        case 1:
            return `${number}ST`;
        case 2:
            return `${number}ND`;
        case 3:
            return `${number}RD`;
        default:
            return `${number}TH`;
    }
}

function getExportLevelRangeLabel(startLevelIndex, endLevelIndex) {
    if (startLevelIndex === endLevelIndex) {
        return projectState.levels[startLevelIndex]?.name || "";
    }

    const startNumber = startLevelIndex + 1;
    const endNumber = endLevelIndex + 1;
    if (projectState.language === "en") {
        return `${getEnglishOrdinalLabel(startNumber)}@${getEnglishOrdinalLabel(endNumber)} Level`;
    }

    return `${getSpanishOrdinalLabel(startNumber)}@${getSpanishOrdinalLabel(endNumber)} Nivel`;
}

function buildAnchoredConsecutiveDetailEntries(levels, getItemsForLevel, getIdentityKey, getSignature, tagPrefix, createEntry) {
    const anchoredGroupsByLevelId = new Map((levels || []).map((level) => [level.id, []]));
    const activeGroupsByIdentity = new Map();
    let tagIndex = 1;

    (levels || []).forEach((level, levelIndex) => {
        (getItemsForLevel(level, levelIndex) || []).forEach((item) => {
            const identityKey = getIdentityKey(item, level, levelIndex);
            const signature = getSignature(item, level, levelIndex);
            const currentGroup = activeGroupsByIdentity.get(identityKey);

            if (currentGroup && currentGroup.endLevelIndex === levelIndex - 1 && currentGroup.signature === signature) {
                currentGroup.endLevelIndex = levelIndex;
                return;
            }

            const nextGroup = {
                tag: `${tagPrefix}${tagIndex}`,
                item,
                signature,
                startLevelIndex: levelIndex,
                endLevelIndex: levelIndex
            };
            tagIndex += 1;
            activeGroupsByIdentity.set(identityKey, nextGroup);
            anchoredGroupsByLevelId.get(level.id)?.push(nextGroup);
        });
    });

    const byLevel = new Map((levels || []).map((level) => [level.id, []]));
    const flatEntries = [];

    (levels || []).forEach((level) => {
        const groups = anchoredGroupsByLevelId.get(level.id) || [];
        const entries = groups.map((group) => {
            const levelLabel = getExportLevelRangeLabel(group.startLevelIndex, group.endLevelIndex);
            return createEntry({
                tag: group.tag,
                item: group.item,
                levelLabel,
                startLevelIndex: group.startLevelIndex,
                endLevelIndex: group.endLevelIndex
            });
        });
        byLevel.set(level.id, entries);
        for (let index = 0; index < entries.length; index += 1) {
            flatEntries.push(entries[index]);
        }
    });

    return {
        byLevel,
        flatEntries
    };
}

function getColumnDetailIdentityKey(column) {
    const labelKey = getColumnDetailLabelKey(column);
    if (labelKey) {
        return `label|${labelKey}`;
    }

    const normalized = normalizeColumnModel(column);
    return [
        "position",
        getDetailMetricKey(normalized.x),
        getDetailMetricKey(normalized.y)
    ].join("|");
}

function getColumnDetailBaseSectionSignature(column) {
    const normalized = normalizeColumnModel(column);
    return JSON.stringify(canonicalizeSmartRenameValue({
        b: getDetailMetricKey(normalized.b),
        h: getDetailMetricKey(normalized.h),
        steelProfile: isStructuralSteelElement(normalized) ? getDxfSteelProfileDetailKey(normalized) : null,
        longRebar: normalized.longRebar,
        structuralMaterial: normalized.structuralMaterial
    }));
}

function getColumnDetailSignature(column) {
    // Stirrups are documented in the elevation.  They do not split an
    // otherwise identical column section into separate detail drawings.
    return getColumnDetailBaseSectionSignature(column);
}

function getWallDetailIdentityKey(wall) {
    const normalized = normalizeWall(wall);
    return [
        getDetailMetricKey(Math.min(normalized.x1, normalized.x2)),
        getDetailMetricKey(Math.min(normalized.y1, normalized.y2)),
        getDetailMetricKey(Math.max(normalized.x1, normalized.x2)),
        getDetailMetricKey(Math.max(normalized.y1, normalized.y2))
    ].join("|");
}

function getWallDetailSignature(wall) {
    const normalized = normalizeWall(wall);
    return JSON.stringify({
        b: getDetailMetricKey(normalized.b),
        h: getDetailMetricKey(normalized.h),
        material: normalized.material,
        concrete: normalized.concrete,
        masonry: normalized.masonry,
        structuralMaterial: normalized.structuralMaterial
    });
}

function isPointInsideWallPlanFootprint(x, y, wall, tolerance = 0.08) {
    const normalized = normalizeWall(wall);
    const thickness = Math.max(parsePositiveNumberOrFallback(normalized.b, DEFAULT_WALL_THICKNESS, 0.08), 0.08);
    const halfThickness = thickness / 2;
    const orientation = getWallPlanOrientation(normalized);

    if (orientation === "horizontal") {
        const minX = Math.min(normalized.x1, normalized.x2) - tolerance;
        const maxX = Math.max(normalized.x1, normalized.x2) + tolerance;
        const centerY = (normalized.y1 + normalized.y2) / 2;
        return x >= minX && x <= maxX && y >= centerY - halfThickness - tolerance && y <= centerY + halfThickness + tolerance;
    }

    const minY = Math.min(normalized.y1, normalized.y2) - tolerance;
    const maxY = Math.max(normalized.y1, normalized.y2) + tolerance;
    const centerX = (normalized.x1 + normalized.x2) / 2;
    return y >= minY && y <= maxY && x >= centerX - halfThickness - tolerance && x <= centerX + halfThickness + tolerance;
}

function areWallsTouchingInPlan(leftWall, rightWall) {
    const left = normalizeWall(leftWall);
    const right = normalizeWall(rightWall);
    const tolerance = Math.max(Math.min(left.b, right.b) * 0.2, 0.06);
    const leftEndpoints = [
        { x: left.x1, y: left.y1 },
        { x: left.x2, y: left.y2 }
    ];
    const rightEndpoints = [
        { x: right.x1, y: right.y1 },
        { x: right.x2, y: right.y2 }
    ];

    return leftEndpoints.some((point) => isPointInsideWallPlanFootprint(point.x, point.y, right, tolerance))
        || rightEndpoints.some((point) => isPointInsideWallPlanFootprint(point.x, point.y, left, tolerance));
}

function getWallDetailDisplayName(wall) {
    return normalizeTextValue(wall?.name) || getSmartEntityName("wall", wall) || translate("naming.wall");
}

function getWallDetailEntryIdentityKey(item) {
    if (Array.isArray(item?.detailWalls) && item.detailWalls.length) {
        return item.detailWalls
            .map((wall) => getWallDetailIdentityKey(wall))
            .sort()
            .join("||");
    }

    return getWallDetailIdentityKey(item);
}

function getWallDetailEntrySignature(item) {
    if (Array.isArray(item?.detailWalls) && item.detailWalls.length) {
        return JSON.stringify({
            name: normalizeTextValue(item.name).toLowerCase(),
            material: item.material,
            childSignatures: item.detailWalls
                .map((wall) => ({
                    identity: getWallDetailIdentityKey(wall),
                    signature: getWallDetailSignature(wall)
                }))
                .sort((left, right) => left.identity.localeCompare(right.identity))
        });
    }

    return getWallDetailSignature(item);
}

function getUniqueWallDetailSourceWalls(level, material = "") {
    const targetMaterial = normalizeTextValue(material).toLowerCase();
    const seen = new Set();

    return (level?.walls || [])
        .map((wall) => normalizeWall(wall))
        .filter((wall) => !targetMaterial || wall.material === targetMaterial)
        .filter((wall) => {
            const key = [
                normalizeTextValue(getWallDetailDisplayName(wall)).toLowerCase(),
                getWallDetailIdentityKey(wall),
                getWallDetailSignature(wall)
            ].join("|");
            if (seen.has(key)) {
                return false;
            }
            seen.add(key);
            return true;
        });
}

function getConnectedWallDetailComponents(walls) {
    const normalizedWalls = (Array.isArray(walls) ? walls : []).map((wall) => normalizeWall(wall));
    const visited = new Set();
    const components = [];

    normalizedWalls.forEach((wall, index) => {
        if (visited.has(index)) {
            return;
        }

        const stack = [index];
        const componentIndexes = [];
        visited.add(index);

        while (stack.length) {
            const currentIndex = stack.pop();
            componentIndexes.push(currentIndex);
            const currentWall = normalizedWalls[currentIndex];

            normalizedWalls.forEach((candidateWall, candidateIndex) => {
                if (visited.has(candidateIndex) || candidateIndex === currentIndex) {
                    return;
                }
                if (areWallsTouchingInPlan(currentWall, candidateWall)) {
                    visited.add(candidateIndex);
                    stack.push(candidateIndex);
                }
            });
        }

        components.push(componentIndexes
            .map((componentIndex) => normalizedWalls[componentIndex])
            .sort((left, right) => getWallDetailIdentityKey(left).localeCompare(getWallDetailIdentityKey(right))));
    });

    return components;
}

function buildConnectedWallDetailItem(componentWalls) {
    const walls = (Array.isArray(componentWalls) ? componentWalls : [])
        .map((wall) => normalizeWall(wall))
        .sort((left, right) => getWallDetailIdentityKey(left).localeCompare(getWallDetailIdentityKey(right)));
    const primaryWall = walls[0] || normalizeWall({});
    if (walls.length <= 1) {
        return primaryWall;
    }

    const wallNames = Array.from(new Set(walls
        .map((wall) => normalizeTextValue(getWallDetailDisplayName(wall)))
        .filter(Boolean)));

    return {
        ...primaryWall,
        detailWalls: walls,
        name: wallNames.join(" / ") || getWallDetailDisplayName(primaryWall)
    };
}

function getGroupedWallDetailItemsForLevel(level, material) {
    const walls = getUniqueWallDetailSourceWalls(level, material);
    if (!walls.length) {
        return [];
    }

    // A concrete-wall reinforcement detail represents the complete connected
    // plan component. Wall names and reinforcement variations must not split
    // the same physical L/T/cross-shaped wall system into duplicate details.
    if (normalizeTextValue(material).toLowerCase() === "concrete") {
        return getConnectedWallDetailComponents(walls)
            .map((componentWalls) => buildConnectedWallDetailItem(componentWalls))
            .sort((left, right) => (
                getWallDetailEntryIdentityKey(left).localeCompare(getWallDetailEntryIdentityKey(right))
            ));
    }

    const buckets = new Map();
    walls.forEach((wall) => {
        const labelKey = normalizeTextValue(getWallDetailDisplayName(wall)).toLowerCase();
        const signatureKey = getWallDetailSignature(wall);
        const bucketKey = `${labelKey}|${signatureKey}`;
        if (!buckets.has(bucketKey)) {
            buckets.set(bucketKey, []);
        }
        buckets.get(bucketKey).push(wall);
    });

    const groupedItems = [];
    buckets.forEach((bucketWalls) => {
        const visited = new Set();
        bucketWalls.forEach((wall, index) => {
            if (visited.has(index)) {
                return;
            }

            const stack = [index];
            const componentIndexes = [];
            visited.add(index);

            while (stack.length) {
                const currentIndex = stack.pop();
                componentIndexes.push(currentIndex);
                const currentWall = bucketWalls[currentIndex];

                bucketWalls.forEach((candidateWall, candidateIndex) => {
                    if (visited.has(candidateIndex) || candidateIndex === currentIndex) {
                        return;
                    }
                    if (areWallsTouchingInPlan(currentWall, candidateWall)) {
                        visited.add(candidateIndex);
                        stack.push(candidateIndex);
                    }
                });
            }

            const componentWalls = componentIndexes
                .map((componentIndex) => normalizeWall(bucketWalls[componentIndex]))
                .sort((left, right) => getWallDetailIdentityKey(left).localeCompare(getWallDetailIdentityKey(right)));

            if (componentWalls.length === 1) {
                groupedItems.push(componentWalls[0]);
                return;
            }

            const primaryWall = componentWalls[0];
            groupedItems.push({
                ...primaryWall,
                detailWalls: componentWalls,
                name: getWallDetailDisplayName(primaryWall)
            });
        });
    });

    return groupedItems.sort((left, right) => {
        const leftName = normalizeTextValue(getWallDetailDisplayName(left)).toLowerCase();
        const rightName = normalizeTextValue(getWallDetailDisplayName(right)).toLowerCase();
        return leftName.localeCompare(rightName, undefined, { numeric: true, sensitivity: "base" })
            || getWallDetailEntryIdentityKey(left).localeCompare(getWallDetailEntryIdentityKey(right));
    });
}

function getBeamDetailIdentityKey(beam) {
    const normalized = normalizeBeamModel(beam);
    const labelKey = normalizeTextValue(getBeamImportLookupLabel(normalized)).toLowerCase();
    return [
        `label|${labelKey}`,
        getDetailMetricKey(Math.min(normalized.x1, normalized.x2)),
        getDetailMetricKey(Math.min(normalized.y1, normalized.y2)),
        getDetailMetricKey(Math.max(normalized.x1, normalized.x2)),
        getDetailMetricKey(Math.max(normalized.y1, normalized.y2))
    ].join("|");
}

function getBeamDetailSignature(beam) {
    const normalized = normalizeBeamModel(beam);
    return JSON.stringify(canonicalizeSmartRenameValue({
        b: getDetailMetricKey(normalized.b),
        h: getDetailMetricKey(normalized.h),
        length: getBeamDetailLengthKey(normalized),
        topRebar: normalized.topRebar,
        botRebar: normalized.botRebar,
        stirrups: normalized.stirrups,
        additionalRebar: normalized.additionalRebar,
        sectionCuts: normalized.sectionCuts,
        coverTop: normalized.coverTop,
        coverBottom: normalized.coverBottom,
        structuralMaterial: normalized.structuralMaterial
    }));
}

function stripFinalParentheticalLabel(value) {
    return normalizeTextValue(value).replace(/\s*\([^()]+\)\s*$/, "").trim();
}

function getFinalParentheticalDifferentiator(value) {
    const match = normalizeTextValue(value).match(/\(([^()]+)\)\s*$/);
    return match ? normalizeTextValue(match[1]) : "";
}

function getBeamDetailBaseExportName(beam) {
    const normalized = normalizeBeamModel(beam);
    const displayName = stripFinalParentheticalLabel(
        normalizeContinuousBeamDisplayName(normalized.name, normalized)
    );
    return displayName
        || stripLegacyBeamSpanSuffix(getBeamImportLookupLabel(normalized))
        || getSmartEntityName("beam", normalized)
        || translate("naming.beam");
}

function getBeamDetailLengthKey(beam) {
    return getDetailMetricKey(getBeamSpanLength(beam));
}

function getBeamEtabsExportDifferentiator(beam) {
    const normalized = normalizeBeamModel(beam);
    const baseName = getBeamDetailBaseExportName(normalized).toLowerCase();
    const segmentIndex = Number.parseInt(normalized?.sourceEtabsSegmentIndex, 10);
    const segmentCount = Number.parseInt(normalized?.sourceEtabsSegmentCount, 10);
    const segmentSuffix = Number.isFinite(segmentIndex) && Number.isFinite(segmentCount) && segmentCount > 1
        ? `-${segmentIndex + 1}`
        : "";
    const parentheticalDifferentiator = [
        normalized?.name,
        normalized?.sourceLabel,
        normalized?.sourceId,
        normalized?.sourceUniqueId,
        normalized?.sourceEtabsOriginalId
    ]
        .map((candidate) => getFinalParentheticalDifferentiator(candidate))
        .find(Boolean);
    if (parentheticalDifferentiator) {
        return `${parentheticalDifferentiator}${segmentSuffix}`.trim();
    }

    const candidates = [
        normalizeTextValue(normalized?.sourceUniqueId),
        normalizeTextValue(normalized?.sourceEtabsOriginalId),
        normalizeTextValue(normalized?.sourceId),
        normalizeTextValue(normalized?.id)
    ].filter(Boolean);
    const rawValue = candidates.find((candidate) => {
        const candidateKey = normalizeTextValue(candidate).toLowerCase();
        return candidateKey && candidateKey !== baseName && stripFinalParentheticalLabel(candidate).toLowerCase() !== baseName;
    }) || getBeamDetailLengthKey(normalized);
    const cleanDifferentiator = getFinalParentheticalDifferentiator(rawValue) || stripFinalParentheticalLabel(rawValue) || normalizeTextValue(rawValue);
    return `${cleanDifferentiator}${segmentSuffix}`.trim();
}

function getBeamDetailExportDetailKey(beam) {
    const baseName = getBeamDetailBaseExportName(beam).toLowerCase();
    const spanKey = isContinuousBeamSpan(beam) ? `span-${getBeamSpanNumber(beam)}` : "";
    return [baseName, spanKey, getBeamDetailSignature(beam)].filter(Boolean).join("|");
}

function shouldIncludeBeamInIndividualDetailExport(level, beam, options = {}) {
    return options?.includeFrameBeams === true || !isBeamPartOfFrame(level, beam);
}

function buildBeamDetailExportLabelResolver(levels = projectState.levels, options = {}) {
    const groupsByBaseName = new Map();

    (levels || []).forEach((level) => {
        (level?.beams || []).forEach((beam) => {
            if (!shouldIncludeBeamInIndividualDetailExport(level, beam, options)) {
                return;
            }

            const baseName = getBeamDetailBaseExportName(beam);
            const baseKey = baseName.toLowerCase();
            const signature = getBeamDetailSignature(beam);
            const detailKey = getBeamDetailExportDetailKey(beam);
            if (!groupsByBaseName.has(baseKey)) {
                groupsByBaseName.set(baseKey, {
                    baseName,
                    signatures: new Map()
                });
            }

            const group = groupsByBaseName.get(baseKey);
            if (!group.signatures.has(signature)) {
                group.signatures.set(signature, {
                    detailKey,
                    representative: beam
                });
            }
        });
    });

    const exportedDetailKeys = new Set();

    return {
        resolve(beam) {
            const baseName = getBeamDetailBaseExportName(beam);
            const baseKey = baseName.toLowerCase();
            const signature = getBeamDetailSignature(beam);
            const group = groupsByBaseName.get(baseKey);
            const detailKey = getBeamDetailExportDetailKey(beam) || group?.signatures.get(signature)?.detailKey || [baseKey, signature].join("|");
            const cleanBaseName = stripFinalParentheticalLabel(group?.baseName || baseName) || baseName;
            const representative = group?.signatures.get(signature)?.representative || beam;
            const needsDifferentiator = Boolean(group && group.signatures.size > 1) && !isContinuousBeamSpan(beam);
            const differentiator = needsDifferentiator ? getBeamEtabsExportDifferentiator(representative) : "";
            return {
                // A span number must never become part of the displayed beam name.
                label: needsDifferentiator && differentiator ? `${cleanBaseName} (${differentiator})` : cleanBaseName,
                detailKey
            };
        },
        claim(detailKey) {
            const key = normalizeTextValue(detailKey);
            if (!key) {
                return true;
            }
            if (exportedDetailKeys.has(key)) {
                return false;
            }
            exportedDetailKeys.add(key);
            return true;
        }
    };
}

function getUniqueStandaloneBeamsForDetailExport(level, labelResolver, options = {}) {
    const uniqueBeams = [];
    const seenDetailKeys = new Set();

    (level?.beams || []).forEach((beam) => {
        if (!shouldIncludeBeamInIndividualDetailExport(level, beam, options)) {
            return;
        }

        const resolution = typeof labelResolver?.resolve === "function"
            ? labelResolver.resolve(beam)
            : { label: typeof labelResolver === "function" ? labelResolver(beam) : getBeamDetailBaseExportName(beam), detailKey: getBeamDetailExportDetailKey(beam) };
        const detailKey = normalizeTextValue(resolution.detailKey || getBeamDetailExportDetailKey(beam));
        if (detailKey && seenDetailKeys.has(detailKey)) {
            return;
        }
        if (detailKey) {
            seenDetailKeys.add(detailKey);
        }
        if (typeof labelResolver?.claim === "function" && !labelResolver.claim(detailKey)) {
            return;
        }

        uniqueBeams.push({
            ...beam,
            displayName: resolution.label || getBeamDetailBaseExportName(beam)
        });
    });

    return uniqueBeams;
}


function getAnchoredColumnDetailEntries(levels = projectState.levels) {
    return buildAnchoredConsecutiveDetailEntries(
        levels,
        (level) => getUniqueColumnsForDetailExport(level),
        (column) => getColumnDetailIdentityKey(column),
        (column) => getColumnDetailSignature(column),
        "C",
        ({ tag, item, levelLabel, startLevelIndex, endLevelIndex }) => ({
            tag,
            column: item,
            levelName: levelLabel,
            positionKey: getColumnElevationPositionKey(item),
            elevationKey: getColumnElevationIdentityKey(item),
            startLevelIndex,
            endLevelIndex
        })
    );
}

function getAnchoredWallDetailEntries(levels = projectState.levels) {
    return buildAnchoredConsecutiveDetailEntries(
        levels,
        (level) => getUniqueWallDetailSourceWalls(level),
        (wall) => getWallDetailIdentityKey(wall),
        (wall) => getWallDetailSignature(wall),
        "M",
        ({ tag, item, levelLabel }) => ({
            tag,
            wall: item,
            levelName: levelLabel
        })
    );
}

function getWallsByMaterial(level, material) {
    const targetMaterial = normalizeTextValue(material).toLowerCase();
    return (level?.walls || [])
        .map((wall) => normalizeWall(wall))
        .filter((wall) => wall.material === targetMaterial);
}

function hasWallsByMaterial(level, material) {
    return getWallsByMaterial(level, material).length > 0;
}

function createLevelWithFilteredWalls(level, material) {
    const materials = Array.isArray(material)
        ? material.map((item) => normalizeTextValue(item).toLowerCase())
        : [normalizeTextValue(material).toLowerCase()];

    return {
        ...level,
        walls: (level?.walls || [])
            .map((wall) => normalizeWall(wall))
            .filter((wall) => materials.includes(normalizeTextValue(wall.material).toLowerCase()))
    };
}

function getAnchoredWallDetailEntriesByMaterial(material, levels = projectState.levels) {
    const tagPrefix = material === "concrete" ? "MC" : (material === "thin_wall" ? "MPD" : "M");
    return buildAnchoredConsecutiveDetailEntries(
        levels,
        (level) => getGroupedWallDetailItemsForLevel(level, material),
        (wallEntry) => getWallDetailEntryIdentityKey(wallEntry),
        (wallEntry) => getWallDetailEntrySignature(wallEntry),
        tagPrefix,
        ({ tag, item, levelLabel }) => ({
            tag,
            wall: item,
            groupWalls: Array.isArray(item?.detailWalls) ? item.detailWalls.map((wall) => normalizeWall(wall)) : null,
            levelName: levelLabel
        })
    );
}

function getStandaloneBeamDetailNameKey(beam = {}) {
    return normalizeTextValue(
        stripLegacyBeamSpanSuffix(getBeamDetailBaseExportName(beam))
    ).toLowerCase();
}

function buildStandaloneBeamContinuousDetailGroups(level, options = {}) {
    const includeFrameBeams = options?.includeFrameBeams === true;
    const groups = [];
    const assignedBeamIds = new Set();
    const allChains = getContinuousBeamChainsForLevel(level);

    allChains.forEach((chain) => {
        const orderedMembers = (chain?.segments || [])
            .filter((segment) => shouldIncludeBeamInIndividualDetailExport(level, segment?.beam, { includeFrameBeams }))
            .slice()
            .sort((left, right) => (left.start - right.start) || (left.end - right.end));
        let currentGroup = null;

        orderedMembers.forEach((segment) => {
            const beam = segment?.beam;
            if (!beam) return;
            const nameKey = getStandaloneBeamDetailNameKey(beam);
            const canAppend = currentGroup
                && currentGroup.nameKey === nameKey
                && Math.abs(segment.start - currentGroup.end) <= 0.12;
            if (!canAppend) {
                currentGroup = {
                    nameKey,
                    displayName: stripLegacyBeamSpanSuffix(getBeamDetailBaseExportName(beam)),
                    axisType: chain.axisType,
                    axisValue: chain.axisValue,
                    members: [],
                    start: segment.start,
                    end: segment.end
                };
                groups.push(currentGroup);
            }
            currentGroup.members.push({ ...segment, beam });
            currentGroup.start = Math.min(currentGroup.start, segment.start);
            currentGroup.end = Math.max(currentGroup.end, segment.end);
            if (beam?.id) assignedBeamIds.add(beam.id);
        });
    });

    // Keep non-orthogonal or otherwise unassigned beams exportable as their own detail.
    (level?.beams || []).forEach((beam) => {
        if (!shouldIncludeBeamInIndividualDetailExport(level, beam, { includeFrameBeams }) || assignedBeamIds.has(beam?.id)) {
            return;
        }
        const axisType = getBeamLocalAxisType(beam);
        const bounds = getBeamBoundsForFrame(beam, axisType);
        groups.push({
            nameKey: getStandaloneBeamDetailNameKey(beam),
            displayName: stripLegacyBeamSpanSuffix(getBeamDetailBaseExportName(beam)),
            axisType,
            axisValue: axisType === "x" ? beam.x1 : beam.y1,
            members: [{ beam, ...bounds }],
            start: bounds.start,
            end: bounds.end
        });
    });

    return groups
        .filter((group) => group.members.length > 0)
        .sort((left, right) => left.displayName.localeCompare(right.displayName, undefined, { numeric: true, sensitivity: "base" })
            || left.axisType.localeCompare(right.axisType)
            || left.axisValue - right.axisValue
            || left.start - right.start);
}

function getStandaloneBeamContinuousDetailGroupSignature(group = {}) {
    const members = Array.isArray(group.members) ? group.members : [];
    return JSON.stringify(canonicalizeSmartRenameValue({
        nameKey: normalizeTextValue(group.nameKey).toLowerCase(),
        totalLength: getDetailMetricKey(parseNumberOrFallback(group.end, 0) - parseNumberOrFallback(group.start, 0)),
        members: members
            .slice()
            .sort((left, right) => (
                parseNumberOrFallback(left?.start, 0) - parseNumberOrFallback(right?.start, 0)
                || parseNumberOrFallback(left?.end, 0) - parseNumberOrFallback(right?.end, 0)
            ))
            .map((member, index) => ({
                index,
                length: getDetailMetricKey(parseNumberOrFallback(member?.end, 0) - parseNumberOrFallback(member?.start, 0)),
                signature: getBeamDetailSignature(member?.beam)
            }))
    }));
}

function getAnchoredStandaloneBeamDetailEntries(levels = projectState.levels, options = {}) {
    const includeFrameBeams = options?.includeFrameBeams === true;
    const beamEntries = [];
    const seenGroupSignatures = new Set();
    let detailIndex = 1;

    (levels || []).forEach((level) => {
        buildStandaloneBeamContinuousDetailGroups(level, { includeFrameBeams }).forEach((group) => {
            const groupSignature = getStandaloneBeamContinuousDetailGroupSignature(group);
            if (seenGroupSignatures.has(groupSignature)) {
                return;
            }
            seenGroupSignatures.add(groupSignature);

            const beams = group.members.map((member) => member.beam);
            const representative = beams[0];
            const detailKey = [
                group.nameKey,
                groupSignature
            ].join("|");
            beamEntries.push({
                tag: `V${detailIndex}`,
                beam: representative,
                beams,
                beamSegments: group.members,
                displayName: group.displayName || getBeamDetailBaseExportName(representative),
                detailKey,
                levelId: level?.id ?? "",
                axisType: group.axisType,
                axisValue: group.axisValue,
                chainStart: group.start,
                chainEnd: group.end,
                levelName: level?.name || ""
            });
            detailIndex += 1;
        });
    });

    const sectionEntries = buildStandaloneBeamSectionEntries(beamEntries, {
        sectionTagStartIndex: options?.sectionTagStartIndex,
        beamSectionPreferences: normalizeBeamSectionDrawingPreferences(options?.beamSectionPreferences)
    });

    return { beamEntries, sectionEntries };
}

function getBeamSpanLength(beam) {
    return Math.hypot(
        Number.parseFloat(beam?.x2 ?? 0) - Number.parseFloat(beam?.x1 ?? 0),
        Number.parseFloat(beam?.y2 ?? 0) - Number.parseFloat(beam?.y1 ?? 0)
    );
}

function isBeamPartOfFrame(level, beam) {
    if (!level || !beam || isFoundationLevel(level)) {
        return false;
    }

    const startColumn = findColumnAtPosition(level.columns, beam.x1, beam.y1);
    const endColumn = findColumnAtPosition(level.columns, beam.x2, beam.y2);
    return Boolean(startColumn && endColumn);
}

function normalizeDxfSteelProfile(profile, fallbackName = "") {
    const source = profile && typeof profile === "object" ? profile : {};
    const raw = source.dimensions && typeof source.dimensions === "object" ? source.dimensions : source;
    const value = (...keys) => keys.map((key) => Number.parseFloat(raw?.[key])).find((entry) => Number.isFinite(entry) && entry > 0) || 0;
    const name = normalizeTextValue(source.name || source.sectionName || source.sourceSection || fallbackName);
    const shape = normalizeTextValue(source.shape || source.sourceShape || source.type || "");
    const dimensions = {
        d: value("d", "D", "depth", "h", "t3"),
        b: value("b", "B", "width", "bf", "BF", "t2"),
        bfTop: value("bfTop", "BFTop", "bf", "BF"),
        bfBottom: value("bfBottom", "BFBottom", "bfb", "BFB", "bf", "BF"),
        tfTop: value("tfTop", "TFTop", "tf", "TF"),
        tfBottom: value("tfBottom", "TFBottom", "tfb", "TFB", "tf", "TF"),
        tw: value("tw", "TW"),
        t: value("wallThickness", "WallThickness", "t", "T", "tnom", "TNOM", "tdes", "TDES"),
        od: value("od", "OD")
    };
    const hssMatch = normalizeTextValue(name || shape).toUpperCase().replace(/\s+/g, "").match(/^HSS([^X]+)X([^X]+)X(.+)$/);
    if (hssMatch) {
        dimensions.d = parseStructuralShapeDimensionLabelInMeters(hssMatch[1]) || dimensions.d;
        dimensions.b = parseStructuralShapeDimensionLabelInMeters(hssMatch[2]) || dimensions.b;
        dimensions.t = parseStructuralShapeDimensionLabelInMeters(hssMatch[3]) || dimensions.t;
    }
    return {
        name,
        shape,
        dimensions: Object.fromEntries(Object.entries(dimensions).filter(([, entry]) => entry > 0))
    };
}

function getDxfSteelProfileCompleteness(profile = {}) {
    return Object.keys(normalizeDxfSteelProfile(profile).dimensions || {}).length;
}

function getDxfSteelProfileForElement(element = {}) {
    const direct = normalizeDxfSteelProfile(element.steelProfile, element.sourceSection || element.sectionName || "");
    const requestedName = direct.name.toLowerCase();
    const projectProfiles = Array.isArray(projectState.steelProfiles) ? projectState.steelProfiles : [];
    const matchingProfiles = [...projectProfiles, ...DEFAULT_STEEL_PROFILES]
        .filter((entry) => normalizeDxfSteelProfile(entry).name.toLowerCase() === requestedName)
        .sort((left, right) => getDxfSteelProfileCompleteness(right) - getDxfSteelProfileCompleteness(left));
    const selected = matchingProfiles[0] || null;

    // A steel member is dimensioned exclusively from the selected profile. Concrete b/h values
    // are deliberately never used as a fallback for steel section geometry.
    return selected ? normalizeDxfSteelProfile(selected, direct.name) : direct;
}

function getDxfSteelProfileForBeam(beam = {}) {
    return getDxfSteelProfileForElement(beam);
}

function getBeamSteelProfileDisplayName(beam = {}) {
    const profile = getDxfSteelProfileForBeam(beam);
    return normalizeTextValue(profile?.name || beam?.sourceSection || beam?.sectionName || "");
}

function hasBeamSteelProfileDisplayName(beam = {}) {
    return Boolean(getBeamSteelProfileDisplayName(beam));
}

function getSlabPlanBeamDisplayLabel(beam = {}) {
    return normalizeTextValue(beam?.name)
        || getBeamSteelProfileDisplayName(beam)
        || normalizeTextValue(beam?.sourceSection)
        || normalizeTextValue(beam?.sectionName)
        || getSmartEntityName("beam", beam);
}

function isDxfSteelBeam(beam = {}) {
    // A concrete ETABS/MIDAS section can also have sourceSection/sectionName.
    // Do not treat that section name as a steel profile unless the element
    // material itself is steel; otherwise concrete frame and standalone beam
    // cuts are exported as W/I-shaped metallic profiles.
    return isStructuralSteelElement(beam);
}

function getDxfSteelProfileForColumn(column = {}) {
    return getDxfSteelProfileForElement(column);
}

function getDxfSteelProfileWidth(profile) {
    const dimensions = profile?.dimensions || {};
    return parsePositiveNumberOrFallback(
        dimensions.b || dimensions.bfTop || dimensions.bfBottom || dimensions.od,
        0,
        0
    );
}

function getDxfSteelProfileDepth(profile) {
    const dimensions = profile?.dimensions || {};
    return parsePositiveNumberOrFallback(
        dimensions.d || dimensions.od,
        0,
        0
    );
}

function parseStructuralShapeDimensionLabelInMeters(label) {
    const normalized = normalizeTextValue(label).trim();
    if (!normalized) {
        return 0;
    }
    if (/\d+\s*\/\s*\d+|\d+(?:\.\d+)?/.test(normalized)) {
        return parseInchDiameterLabelInMeters(normalized);
    }
    return 0;
}

function getDxfHssWallThicknessFromName(profileName = "") {
    const normalizedName = normalizeTextValue(profileName).toUpperCase().replace(/\s+/g, "");
    if (!normalizedName.startsWith("HSS")) {
        return 0;
    }
    const segments = normalizedName.split("X");
    const thicknessLabel = segments[segments.length - 1] || "";
    return parseStructuralShapeDimensionLabelInMeters(thicknessLabel);
}

function isDxfRectangularHssProfile(profile = {}) {
    const normalized = normalizeDxfSteelProfile(profile);
    const descriptor = `${normalized.name} ${normalized.shape}`.toUpperCase().replace(/\s+/g, "");
    return /^HSS[^X]+X[^X]+X.+/.test(descriptor)
        || /HSSRECTANGULAR|RECTANGULARHSS|HOLLOWSTRUCTURALSECTION/.test(descriptor);
}

function getDxfSteelProfileWallThickness(profile = {}) {
    const dimensions = profile?.dimensions || {};
    const directThickness = parsePositiveNumberOrFallback(
        dimensions.t || dimensions.wallThickness || dimensions.tw || dimensions.tfTop || dimensions.tfBottom,
        0,
        0
    );
    if (directThickness > EDGE_TOLERANCE) {
        return directThickness;
    }
    return getDxfHssWallThicknessFromName(profile?.name || profile?.shape || "");
}

function getReadableLineAngleDegrees(dx, dy) {
    if (!hasFiniteNumbers(dx, dy)) {
        return 0;
    }
    let angle = (Math.atan2(dy, dx) * 180) / Math.PI;
    while (angle > 180) {
        angle -= 360;
    }
    while (angle <= -180) {
        angle += 360;
    }
    if (angle > 90) {
        angle -= 180;
    } else if (angle < -90) {
        angle += 180;
    }
    return angle;
}

function getDxfSteelProfileFootprint(element = {}) {
    const profile = getDxfSteelProfileForElement(element);
    const width = getDxfSteelProfileWidth(profile);
    const height = getDxfSteelProfileDepth(profile);
    return { profile, width, height };
}

function getSlabPlanBeamDisplayWidth(beam = {}) {
    const normalizedBeam = normalizeBeamModel(beam || {});
    if (isStructuralSteelElement(normalizedBeam)) {
        const steelProfile = getDxfSteelProfileForBeam(normalizedBeam);
        const profileWidth = getDxfSteelProfileWidth(steelProfile);
        if (profileWidth > EDGE_TOLERANCE) {
            return profileWidth;
        }
    }
    return parsePositiveNumberOrFallback(normalizedBeam?.b, 0.3, 0.1);
}

// A profile detail represents a catalog section, not an individual member.  This
// stable key lets the export draw the profile once even when it is assigned to
// multiple beams or columns.
function getDxfSteelProfileDetailKey(element = {}) {
    const profile = getDxfSteelProfileForElement(element);
    const dimensions = profile?.dimensions || {};
    const profileName = normalizeTextValue(profile?.name || element?.sourceSection || element?.sectionName)
        .replace(/\s+/g, "")
        .toLowerCase();
    const shape = normalizeTextValue(profile?.shape || element?.sourceShape)
        .replace(/\s+/g, "")
        .toLowerCase();
    // Section names are catalog identifiers.  A repeated named profile must
    // produce one detail even if a source file contains a partial duplicate
    // dimensional record.  Dimensions are used only when no profile name exists.
    if (profileName) {
        return `steel-profile|${profileName}|${shape}`;
    }

    const dimensionKey = [
        "d", "b", "bfTop", "bfBottom", "tfTop", "tfBottom", "tw", "t", "od"
    ].map((key) => getDetailMetricKey(dimensions?.[key], 6)).join("|");

    return `steel-profile|unnamed|${shape}|${dimensionKey}`;
}

function getDxfWideFlangeProfileDrawingParts(profile, width, height) {
    const dims = profile?.dimensions || {};
    const safeWidth = Math.max(parsePositiveNumberOrFallback(width, 0.001, 0.001), 0.001);
    const safeHeight = Math.max(parsePositiveNumberOrFallback(height, 0.001, 0.001), 0.001);
    const profileWidth = Math.max(dims.b || dims.bfTop || dims.bfBottom || safeWidth, 0.001);
    const profileDepth = Math.max(dims.d || dims.od || safeHeight, 0.001);
    const scaleX = safeWidth / profileWidth;
    const scaleY = safeHeight / profileDepth;
    const clamp = (value, upperBound) => Math.min(Math.max(value, 0.000001), Math.max(upperBound, 0.000001));
    const topW = clamp((dims.bfTop || dims.b || profileWidth) * scaleX, safeWidth);
    const botW = clamp((dims.bfBottom || dims.b || profileWidth) * scaleX, safeWidth);
    const topT = clamp((dims.tfTop || profileDepth * 0.08) * scaleY, safeHeight * 0.4);
    const botT = clamp((dims.tfBottom || profileDepth * 0.08) * scaleY, safeHeight * 0.4);
    const webT = clamp((dims.tw || profileWidth * 0.05) * scaleX, Math.min(topW, botW));
    const webH = Math.max(safeHeight - topT - botT, 0.000001);

    return { safeWidth, safeHeight, topW, botW, topT, botT, webT, webH };
}

function getRotatedPlanRectangleVertices(left, bottom, width, height, rotationRadians = 0) {
    const centerX = left + width / 2;
    const centerY = bottom + height / 2;
    const cosine = Math.cos(rotationRadians);
    const sine = Math.sin(rotationRadians);
    return [
        { x: left, y: bottom },
        { x: left + width, y: bottom },
        { x: left + width, y: bottom + height },
        { x: left, y: bottom + height }
    ].map((point) => {
        const relativeX = point.x - centerX;
        const relativeY = point.y - centerY;
        return {
            x: centerX + relativeX * cosine - relativeY * sine,
            y: centerY + relativeX * sine + relativeY * cosine
        };
    });
}

function drawDxfHssProfileToPlan(plan, profile, left, bottom, width, height, options = {}) {
    const safeWidth = Math.max(parsePositiveNumberOrFallback(width, 0.001, 0.001), 0.001);
    const safeHeight = Math.max(parsePositiveNumberOrFallback(height, 0.001, 0.001), 0.001);
    const profileWidth = Math.max(getDxfSteelProfileWidth(profile), 0.001);
    const profileDepth = Math.max(getDxfSteelProfileDepth(profile), 0.001);
    const wallThickness = Math.min(
        Math.max(getDxfSteelProfileWallThickness(profile), 0.001),
        Math.min(profileWidth, profileDepth) / 2 - 0.0001
    );
    const insetX = Math.min((wallThickness / profileWidth) * safeWidth, safeWidth / 2 - 0.0001);
    const insetY = Math.min((wallThickness / profileDepth) * safeHeight, safeHeight / 2 - 0.0001);
    const rotationRadians = Number.isFinite(options?.rotationRadians) ? options.rotationRadians : 0;
    const drawRectangle = (rectLeft, rectBottom, rectWidth, rectHeight) => {
        if (Math.abs(rotationRadians) <= 1e-8) {
            plan.addRectangle("PERFILES_METALICOS", rectLeft, rectBottom, rectWidth, rectHeight);
            return;
        }
        const vertices = getRotatedPlanRectangleVertices(rectLeft, rectBottom, rectWidth, rectHeight, rotationRadians);
        getPolygonSegments(vertices).forEach((segment) => {
            plan.addLine("PERFILES_METALICOS", segment.x1, segment.y1, segment.x2, segment.y2);
        });
    };
    drawRectangle(left, bottom, safeWidth, safeHeight);
    if (safeWidth - 2 * insetX > EDGE_TOLERANCE && safeHeight - 2 * insetY > EDGE_TOLERANCE) {
        drawRectangle(left + insetX, bottom + insetY, safeWidth - 2 * insetX, safeHeight - 2 * insetY);
    }
}

function drawDxfSteelProfileToPlan(plan, profile, left, bottom, width, height, options = {}) {
    if (isDxfRectangularHssProfile(profile)) {
        drawDxfHssProfileToPlan(plan, profile, left, bottom, width, height, options);
        return;
    }
    drawDxfWideFlangeProfileToPlan(plan, profile, left, bottom, width, height, options);
}

function drawDxfWideFlangeProfileToPlan(plan, profile, left, bottom, width, height, options = {}) {
    const parts = getDxfWideFlangeProfileDrawingParts(profile, width, height);
    const rotationRadians = Number.isFinite(options?.rotationRadians) ? options.rotationRadians : 0;
    const isRotated = Math.abs(Math.sin(rotationRadians)) > 1e-8;
    const drawProfileRectangle = (rectLeft, rectBottom, rectWidth, rectHeight) => {
        if (!isRotated) {
            plan.addRectangle("PERFILES_METALICOS", rectLeft, rectBottom, rectWidth, rectHeight);
            return;
        }
        const vertices = getRotatedPlanRectangleVertices(rectLeft, rectBottom, rectWidth, rectHeight, rotationRadians);
        getPolygonSegments(vertices).forEach((segment) => {
            plan.addLine("PERFILES_METALICOS", segment.x1, segment.y1, segment.x2, segment.y2);
        });
    };

    drawProfileRectangle(left + (parts.safeWidth - parts.topW) / 2, bottom + parts.safeHeight - parts.topT, parts.topW, parts.topT);
    drawProfileRectangle(left + (parts.safeWidth - parts.webT) / 2, bottom + parts.botT, parts.webT, parts.webH);
    drawProfileRectangle(left + (parts.safeWidth - parts.botW) / 2, bottom, parts.botW, parts.botT);
}

function drawDxfWideFlangeProfileSectionDefinitionLines(dxf, parts, left, bottom) {
    // The catalog profile is drawn as three rectangles for plans.  In a section
    // detail, explicitly mark the four flange-to-web transitions as well.  These
    // short lines keep the W/I shape legible in CAD even when the three rectangle
    // outlines visually merge at small plot scales.
    const topLeft = left + (parts.safeWidth - parts.topW) / 2;
    const topRight = topLeft + parts.topW;
    const bottomLeft = left + (parts.safeWidth - parts.botW) / 2;
    const bottomRight = bottomLeft + parts.botW;
    const webLeft = left + (parts.safeWidth - parts.webT) / 2;
    const webRight = webLeft + parts.webT;
    const topFlangeBottom = bottom + parts.safeHeight - parts.topT;
    const bottomFlangeTop = bottom + parts.botT;

    // Top flange: its two exposed underside segments end where the web begins.
    addLine(dxf, "SECCION_CORTE", topLeft, topFlangeBottom, webLeft, topFlangeBottom);
    addLine(dxf, "SECCION_CORTE", webRight, topFlangeBottom, topRight, topFlangeBottom);
    // Bottom flange: its two exposed upper segments end where the web begins.
    addLine(dxf, "SECCION_CORTE", bottomLeft, bottomFlangeTop, webLeft, bottomFlangeTop);
    addLine(dxf, "SECCION_CORTE", webRight, bottomFlangeTop, bottomRight, bottomFlangeTop);

    // Reinforce the two faces of the web between flanges.  The lines are kept in
    // the section layer so they remain clear if the metallic-profile layer color
    // is changed by the user in AutoCAD.
    addLine(dxf, "SECCION_CORTE", webLeft, bottomFlangeTop, webLeft, topFlangeBottom);
    addLine(dxf, "SECCION_CORTE", webRight, bottomFlangeTop, webRight, topFlangeBottom);
}

function drawDxfWideFlangeProfile(dxf, profile, left, bottom, width, height, { showSectionDefinitionLines = false } = {}) {
    const parts = getDxfWideFlangeProfileDrawingParts(profile, width, height);
    addRectangle(dxf, "PERFILES_METALICOS", left + (parts.safeWidth - parts.topW) / 2, bottom + parts.safeHeight - parts.topT, parts.topW, parts.topT);
    addRectangle(dxf, "PERFILES_METALICOS", left + (parts.safeWidth - parts.webT) / 2, bottom + parts.botT, parts.webT, parts.webH);
    addRectangle(dxf, "PERFILES_METALICOS", left + (parts.safeWidth - parts.botW) / 2, bottom, parts.botW, parts.botT);

    if (showSectionDefinitionLines) {
        drawDxfWideFlangeProfileSectionDefinitionLines(dxf, parts, left, bottom);
    }
}

function drawDxfHssProfile(dxf, profile, left, bottom, width, height) {
    const safeWidth = Math.max(parsePositiveNumberOrFallback(width, 0.001, 0.001), 0.001);
    const safeHeight = Math.max(parsePositiveNumberOrFallback(height, 0.001, 0.001), 0.001);
    const profileWidth = Math.max(getDxfSteelProfileWidth(profile), 0.001);
    const profileDepth = Math.max(getDxfSteelProfileDepth(profile), 0.001);
    const wallThickness = Math.min(
        Math.max(getDxfSteelProfileWallThickness(profile), 0.001),
        Math.min(profileWidth, profileDepth) / 2 - 0.0001
    );
    const insetX = Math.min((wallThickness / profileWidth) * safeWidth, safeWidth / 2 - 0.0001);
    const insetY = Math.min((wallThickness / profileDepth) * safeHeight, safeHeight / 2 - 0.0001);
    addRectangle(dxf, "PERFILES_METALICOS", left, bottom, safeWidth, safeHeight);
    if (safeWidth - 2 * insetX > EDGE_TOLERANCE && safeHeight - 2 * insetY > EDGE_TOLERANCE) {
        addRectangle(dxf, "PERFILES_METALICOS", left + insetX, bottom + insetY, safeWidth - 2 * insetX, safeHeight - 2 * insetY);
    }
}

function drawDxfSteelProfile(dxf, profile, left, bottom, width, height, options = {}) {
    if (isDxfRectangularHssProfile(profile)) {
        drawDxfHssProfile(dxf, profile, left, bottom, width, height);
        return;
    }
    drawDxfWideFlangeProfile(dxf, profile, left, bottom, width, height, options);
}

function drawSteelBeamSectionDetail(dxf, detail, originX, originY, detailSize) {
    const { beam, tag } = detail;
    const left = originX + 0.45;
    const bottom = originY - detailSize.sectionHeight - 1.05;
    const right = left + detailSize.sectionWidth;
    const top = bottom + detailSize.sectionHeight;
    const profile = getDxfSteelProfileForBeam(beam);
    const profileWidth = getDxfSteelProfileWidth(profile, beam);
    const profileDepth = getDxfSteelProfileDepth(profile, beam);
    drawDxfSteelProfile(dxf, profile, left, bottom, detailSize.sectionWidth, detailSize.sectionHeight, { showSectionDefinitionLines: true });
    addDimension(dxf, "COTAS_SECCION", left, right, top + 0.36, formatLengthForUnit(profileWidth, "section"), top);
    addVerticalDimension(dxf, "COTAS_SECCION", left - 0.35, bottom, top, profileDepth, left);
    const name = normalizeTextValue(profile.name || beam.sourceSection || beam.name || "PERFIL W");
    const sectionTag = normalizeTextValue(tag) || name;
    const isFrameSection = detail?.detailContext === "frame";
    const sectionMarkerTag = isFrameSection ? sectionTag : "SV";
    const standaloneSectionNumber = Math.max(
        1,
        Math.floor(parseNumberOrFallback(detail?.sectionNumber, 1))
    );
    const beamDetailName = normalizeTextValue(detail?.detailBeamName || beam?.displayName || beam?.name) || name;
    addCenteredText(dxf, "SECCION_TEXTO", (left + right) / 2, bottom - 0.65, name, 0.14);
    drawDetailTitleMarker(
        dxf,
        left + 0.15,
        bottom - 1.45,
        sectionMarkerTag,
        "E-00",
        isFrameSection
            ? `SECCIÓN ${sectionTag}`
            : `SECCIÓN ${standaloneSectionNumber} DE VIGA ${beamDetailName}`
    );
}

function drawSteelBeamElevationDetail(dxf, detail, originX, originY) {
    const beam = detail.beam;
    const span = Math.max(getBeamSpanLength(beam), 0.6);
    const left = originX + 0.45;
    const top = originY - 1.05;
    const profile = getDxfSteelProfileForBeam(beam);
    const profileDepth = getDxfSteelProfileDepth(profile, beam);
    const height = Math.max(profileDepth, 0.01);
    const bottom = top - height;
    const right = left + span;
    const name = normalizeTextValue(profile.name || beam.sourceSection || beam.name || "PERFIL W");
    drawBeamDetailNameMarker(dxf, left + 0.15, bottom - 1.35, beam.name || name, "E-00");
    addRectangle(dxf, "PERFILES_METALICOS", left, bottom, span, height);
    if (isDxfRectangularHssProfile(profile)) {
        const wallThickness = Math.min(getDxfSteelProfileWallThickness(profile), height / 2 - 0.0001);
        if (wallThickness > EDGE_TOLERANCE) {
            addLine(dxf, "SECCION_CORTE", left, top - wallThickness, right, top - wallThickness);
            addLine(dxf, "SECCION_CORTE", left, bottom + wallThickness, right, bottom + wallThickness);
        }
    } else {
        const profileParts = getDxfWideFlangeProfileDrawingParts(profile, 1, height);
        const topFlangeBottomY = bottom + profileParts.safeHeight - profileParts.topT;
        const bottomFlangeTopY = bottom + profileParts.botT;
        // Show the flange thicknesses and the clear web height in the longitudinal steel-beam detail.
        addLine(dxf, "SECCION_CORTE", left, topFlangeBottomY, right, topFlangeBottomY);
        addLine(dxf, "SECCION_CORTE", left, bottomFlangeTopY, right, bottomFlangeTopY);
    }
    addVerticalDimension(dxf, "COTAS_SECCION", right + 0.35, bottom, top, profileDepth, right);
    addDimension(dxf, "COTAS_SECCION", left, right, bottom - 0.72, span.toFixed(2), bottom);
    addCenteredText(dxf, "SECCION_TEXTO", (left + right) / 2, top + 0.36, name, 0.14);
}

function getStandaloneBeamExportEntries(levels = projectState.levels, options = {}) {
    const entries = [];
    const includeFrameBeams = options?.includeFrameBeams === true;
    let beamIndex = 1;

    (levels || []).forEach((level) => {
        (level?.beams || []).forEach((beam) => {
            if (!includeFrameBeams && isBeamPartOfFrame(level, beam)) {
                return;
            }

            entries.push({
                tag: `V${beamIndex}`,
                beam,
                levelName: level?.name || ""
            });
            beamIndex += 1;
        });
    });

    return entries;
}

function getStandaloneBeamSectionSlabReferenceKey(detail = {}) {
    const slabContext = getBeamSectionAdjacentSlabContext(detail);
    const getSideKey = (sideData) => {
        if (!sideData) {
            return "none";
        }
        return JSON.stringify({
            type: sideData.type === "lightened" ? "lightened" : "solid",
            thickness: getDetailMetricKey(sideData.thickness),
            cassetteThickness: getDetailMetricKey(sideData.cassetteThickness),
            meshLabel: normalizeTextValue(sideData.meshLabel)
        });
    };

    return JSON.stringify({
        left: getSideKey(slabContext?.left),
        right: getSideKey(slabContext?.right)
    });
}

function getStandaloneBeamSectionReferenceKey(detail = {}) {
    const beam = detail?.beam || {};
    const sectionSpec = detail?.sectionSpec || getBeamEffectiveSectionDetailData(beam, detail?.zone || "mid");
    const preferences = normalizeBeamSectionDrawingPreferences(detail?.beamSectionPreferences ?? detail?.sectionPreferences);
    const referenceKey = {
        b: getDetailMetricKey(beam?.b),
        h: getDetailMetricKey(beam?.h),
        slabContext: getStandaloneBeamSectionSlabReferenceKey(detail)
    };
    if (isDxfSteelBeam(beam)) {
        const steelProfile = getDxfSteelProfileForBeam(beam);
        referenceKey.steelProfile = normalizeTextValue(
            steelProfile?.name || beam?.sourceSection || beam?.sectionName || beam?.name
        ).toUpperCase();
        referenceKey.steelDimensions = canonicalizeSmartRenameValue(steelProfile?.dimensions || {});
    }
    if (preferences.createSectionPerDistinctLongitudinalReinforcement) {
        referenceKey.longitudinalReinforcement = getFrameSectionLongitudinalReinforcementKey(sectionSpec);
    }
    if (preferences.createSectionPerDistinctTransverseReinforcement) {
        referenceKey.transverseReinforcement = getFrameSectionTransverseReinforcementKey(sectionSpec);
    }
    return JSON.stringify(referenceKey);
}

function getStandaloneBeamSectionMemberLabel(entry = {}) {
    return normalizeTextValue(entry?.beam?.displayName || entry?.beam?.name || entry?.memberLabel || entry?.tag);
}

function buildStandaloneBeamSectionEntries(beamEntries, { fallbackMidspan = true, sectionTagStartIndex = 0, beamSectionPreferences = null } = {}) {
    const sectionEntries = [];
    const tagStartIndex = Math.max(0, Math.floor(parseNumberOrFallback(sectionTagStartIndex, 0)));

    // A continuous standalone-beam elevation only needs one cut for each
    // genuinely distinct span condition.  Repeated spans reuse the same cut
    // and transverse section.  Section geometry always participates in the
    // identity; longitudinal/transverse reinforcement participates only when
    // the corresponding drawing preference is enabled.
    (beamEntries || []).forEach((entry) => {
        const members = Array.isArray(entry?.beamSegments) && entry.beamSegments.length
            ? entry.beamSegments.slice().sort((left, right) => left.start - right.start || left.end - right.end)
            : [{ beam: entry?.beam || {}, ...getBeamBoundsForFrame(entry?.beam || {}, entry?.axisType || getBeamLocalAxisType(entry?.beam || {})) }];
        const level = findLevelByName(entry?.levelName);
        const chainStart = entry?.chainStart ?? (members[0]?.start ?? 0);
        const blockedCutRanges = getStandaloneBeamDetailSupportEntries(level, entry, members).map((support) => ({
            start: support.position - support.width / 2 - chainStart,
            end: support.position + support.width / 2 - chainStart
        }));
        const sectionsByReferenceKey = new Map();
        let sectionNumber = 1;

        members.forEach((member) => {
            const beam = member?.beam || {};
            const isSteel = isDxfSteelBeam(beam);
            const span = getBeamSpanLength(beam);
            if (!(span > EDGE_TOLERANCE)) {
                return;
            }

            const memberLabel = getStandaloneBeamSectionMemberLabel({ ...entry, beam });
            const sectionSpec = isSteel ? null : getBeamEffectiveSectionDetailData(beam, "mid");
            const sectionIdentity = {
                beam,
                levelName: entry.levelName,
                detailBeamName: normalizeTextValue(entry?.displayName) || getBeamDetailBaseExportName(beam),
                zone: "mid",
                detailContext: "standalone",
                beamSectionPreferences,
                sectionSpec
            };
            const referenceKey = getStandaloneBeamSectionReferenceKey(sectionIdentity);
            const existingEntry = sectionsByReferenceKey.get(referenceKey);

            if (existingEntry) {
                if (!existingEntry.memberBeams.some((candidate) => candidate === beam || (candidate?.id && beam?.id && candidate.id === beam.id))) {
                    existingEntry.memberBeams.push(beam);
                }
                if (memberLabel && !existingEntry.memberLabels.includes(memberLabel)) {
                    existingEntry.memberLabels.push(memberLabel);
                }
                existingEntry.referenceCount += 1;
                return;
            }

            const requestedCuts = isSteel
                ? [span / 2]
                : normalizeSectionCuts(beam?.sectionCuts, beam);
            const cutCandidates = (requestedCuts.length > 0
                ? requestedCuts
                : (fallbackMidspan ? [span / 2] : []))
                .filter((cutOffset) => Number.isFinite(cutOffset) && cutOffset > EDGE_TOLERANCE && cutOffset < span - EDGE_TOLERANCE)
                .sort((left, right) => Math.abs(left - span / 2) - Math.abs(right - span / 2));

            let selectedCut = null;
            let selectedChainCutOffset = Number.NaN;
            for (const cutOffset of cutCandidates) {
                const chainCutOffset = Math.max(member.start - chainStart, 0) + cutOffset;
                const isBlockedBySupport = blockedCutRanges.some((range) => (
                    chainCutOffset >= range.start - EDGE_TOLERANCE && chainCutOffset <= range.end + EDGE_TOLERANCE
                ));
                if (!isBlockedBySupport) {
                    selectedCut = cutOffset;
                    selectedChainCutOffset = chainCutOffset;
                    break;
                }
            }

            if (!Number.isFinite(selectedCut) && fallbackMidspan) {
                const fallbackCut = span / 2;
                const chainCutOffset = Math.max(member.start - chainStart, 0) + fallbackCut;
                const isBlockedBySupport = blockedCutRanges.some((range) => (
                    chainCutOffset >= range.start - EDGE_TOLERANCE && chainCutOffset <= range.end + EDGE_TOLERANCE
                ));
                if (!isBlockedBySupport) {
                    selectedCut = fallbackCut;
                    selectedChainCutOffset = chainCutOffset;
                }
            }

            if (!Number.isFinite(selectedCut)) {
                return;
            }

            const sectionEntry = {
                ...sectionIdentity,
                cutOffset: selectedCut,
                chainCutOffset: selectedChainCutOffset,
                parentDetailKey: entry?.detailKey || "",
                memberLabel,
                memberBeams: [beam],
                // Only the representative span receives a cut marker.  Other
                // identical spans increment referenceCount and reuse this section.
                memberCuts: [{ beam, cutOffset: selectedCut }],
                memberLabels: memberLabel ? [memberLabel] : [],
                referenceCount: 1,
                sectionNumber: sectionNumber++
            };
            sectionsByReferenceKey.set(referenceKey, sectionEntry);
            sectionEntries.push(sectionEntry);
        });
    });

    return sectionEntries.map((entry, index) => ({
        ...entry,
        tag: formatFrameSectionTag(tagStartIndex + index),
        sectionNumber: tagStartIndex + index + 1
    }));
}

/* SERVER_ONLY_START */
function exportColumnDetailsToDXF() {
    const level = getExportLevelFromSelection(dom.exportAxisSelect.value);
    if (!level || !level.columns.length) {
        window.alert("Vacío");
        return;
    }

    const dxf = createBaseDxfDocument();

    drawStandaloneDetailSheet(
        dxf,
        buildColumnDetailEntries(level),
        `Detalles de columnas | ${level.name}`,
        getColumnSectionDetailBoxSize,
        drawColumnSectionDetail,
        {
            drawHeader: (sheetDxf, layout) => drawColumnPlanHeaderDetail(sheetDxf, level, layout.startX, layout.startY - 0.18, 7.0, 3.25)
        }
    );

    downloadDxfFile(finalizeDxfDocument(dxf), `Columnas_${level.name.replace(/\s+/g, "_")}.dxf`);
}

function exportWallDetailsToDXF() {
    const level = getExportLevelFromSelection(dom.exportAxisSelect.value);
    if (!level || !level.walls.length) {
        window.alert("Vacío");
        return;
    }

    const dxf = createBaseDxfDocument();

    drawStandaloneDetailSheet(
        dxf,
        buildWallDetailEntries(level),
        `Detalles de muros | ${level.name}`,
        (detail) => getWallDetailBoxSize(detail.wall),
        drawWallSectionDetail,
        {
            startY: 10.8 + WALL_PLAN_TITLE_DROP,
            bottomLimit: 0.8,
            titleTextSize: WALL_DETAIL_TEXT_SIZE,
            emptyTextSize: WALL_DETAIL_TEXT_SIZE,
            drawHeader: (sheetDxf, layout) => drawWallLevelPlanDetail(sheetDxf, level, layout.startX, layout.startY - 0.18, 7.0, 3.25, { fitToContentBox: true })
        }
    );

    downloadDxfFile(finalizeDxfDocument(dxf), `Muros_${level.name.replace(/\s+/g, "_")}.dxf`);
}

function drawStandaloneDetailSheet(dxf, details, title, getSize, drawDetail, options = {}) {
    const startX = options.startX ?? 0.6;
    const startY = options.startY ?? 10.8;
    const bottomLimit = options.bottomLimit ?? 0.8;
    const titleTextSize = options.titleTextSize ?? 0.18;
    const emptyTextSize = options.emptyTextSize ?? 0.14;
    const markerTopText = normalizeTextValue(options.markerTopText) || "DT";
    const markerDetailCode = normalizeTextValue(options.markerDetailCode) || "E-00";
    const titleMarkerY = Number.isFinite(options.titleMarkerY) ? options.titleMarkerY : (startY + 0.45);
    const titleToDetailGap = Math.max(parseNumberOrFallback(options.titleToDetailGap, 0.95), 0.45);
    const shouldDrawTitleMarker = options.drawTitleMarker !== false;
    let cursorX = startX;
    let cursorY = shouldDrawTitleMarker ? (titleMarkerY - titleToDetailGap) : startY;
    let currentColumnWidth = 0;

    if (shouldDrawTitleMarker) {
        drawDetailTitleMarker(dxf, startX + 0.35, titleMarkerY, markerTopText, markerDetailCode, title, { titleTextSize });
    }
    if (typeof options.drawHeader === "function") {
        const nextCursorY = options.drawHeader(dxf, { startX, startY, bottomLimit, titleMarkerY });
        if (Number.isFinite(nextCursorY)) {
            cursorY = Math.min(cursorY, nextCursorY);
        }
    }
    const detailStartY = cursorY;
    if (!details.length) {
        addText(dxf, "SECCION_TEXTO", startX, detailStartY + 0.2, "Vacío", emptyTextSize);
        return;
    }

    details.forEach((detail) => {
        const detailSize = getSize(detail);
        if (cursorY - detailSize.height < bottomLimit) {
            cursorX += currentColumnWidth + SECTION_DETAIL_MARGIN;
            cursorY = detailStartY;
            currentColumnWidth = 0;
        }

        drawDetail(dxf, detail, cursorX, cursorY, detailSize);
        cursorY -= detailSize.height + SECTION_DETAIL_MARGIN;
        currentColumnWidth = Math.max(currentColumnWidth, detailSize.width);
    });
}

function drawPlanAxisSet(dxf, axisType, entries, sourceStart, sourceEnd, diagramLeft, diagramRight, diagramTop, diagramBottom, options = {}) {
    if (!Array.isArray(entries) || !entries.length) {
        return;
    }

    const axisEntries = entries.slice().sort((left, right) => left.value - right.value);
    const axisLayer = DXF_AXIS_LINE_LAYER;
    const labelLayer = DXF_AXIS_CIRCLE_LAYER;
    const dimensionLayer = options.dimensionLayer || "COTAS_EJES";
    const bubbleScale = Math.max(parseNumberOrFallback(options.bubbleScale, 1), 0.05);
    const axisLineScale = Math.max(parseNumberOrFallback(options.axisLineScale, bubbleScale), 0.05);
    const dimensionScale = Math.max(parseNumberOrFallback(options.dimensionScale, bubbleScale), 0.05);
    const bubbleTextMinSize = Math.max(parseNumberOrFallback(options.bubbleTextMinSize, 0), 0);
    const bubbleRadius = Math.max(parsePositiveNumberOrFallback(options.bubbleRadius, DXF_AXIS_CIRCLE_RADIUS, 0.001), 0.001);
    const bubbleOffset = (options.bubbleOffset ?? SLAB_PLAN_AXIS_BUBBLE_OFFSET) * bubbleScale;
    const bubbleTextSize = Math.max(parsePositiveNumberOrFallback(options.bubbleTextSize, getPlanAnnotationTextHeight(), 0.001), 0.001);
    const dimensionTextHeight = Math.max(parsePositiveNumberOrFallback(options.dimensionTextHeight, getPlanAnnotationTextHeight(), 0.001), 0.001);
    const lineInset = (options.lineInset ?? 0.06) * bubbleScale;
    const dimensionOffset = (options.dimensionOffset ?? SLAB_PLAN_AXIS_DIMENSION_OFFSET) * bubbleScale;
    const dimensionOriginOffset = (options.dimensionOriginOffset ?? SLAB_PLAN_AXIS_DIMENSION_ORIGIN_OFFSET) * bubbleScale;

    if (axisType === "x") {
        const axisPositions = axisEntries.map((entry) => mapLinearValue(entry.value, sourceStart, sourceEnd, diagramLeft, diagramRight));
        const bubbleY = diagramTop + bubbleOffset;
        const axisLineEndY = bubbleY - bubbleRadius;

        axisEntries.forEach((entry, index) => {
            const axisX = axisPositions[index];
            addLine(dxf, axisLayer, axisX, diagramBottom - lineInset, axisX, axisLineEndY, DXF_AXIS_LINE_TYPE, axisLineScale);
            addAxisBubbleBlock(dxf, axisX, bubbleY, entry.label, {
                layer: labelLayer,
                radius: bubbleRadius,
                textHeight: bubbleTextSize
            });
        });

        for (let index = 0; index < axisPositions.length - 1; index += 1) {
            addDimension(
                dxf,
                dimensionLayer,
                axisPositions[index],
                axisPositions[index + 1],
                diagramTop + dimensionOffset,
                Math.abs(axisEntries[index + 1].value - axisEntries[index].value).toFixed(2),
                diagramTop + dimensionOriginOffset,
                {
                    visualScale: dimensionScale,
                    textHeight: dimensionTextHeight,
                    architecturalDenominator: options.architecturalDenominator
                        ?? DXF_IMPERIAL_DETAIL_DENOMINATOR
                }
            );
        }
        return;
    }

    const axisPositions = axisEntries.map((entry) => mapLinearValue(entry.value, sourceStart, sourceEnd, diagramTop, diagramBottom));
    const bubbleX = diagramLeft - bubbleOffset;
    const axisLineStartX = bubbleX + bubbleRadius;

    axisEntries.forEach((entry, index) => {
        const axisY = axisPositions[index];
        addLine(dxf, axisLayer, axisLineStartX, axisY, diagramRight + lineInset, axisY, DXF_AXIS_LINE_TYPE, axisLineScale);
        addAxisBubbleBlock(dxf, bubbleX, axisY, entry.label, {
            layer: labelLayer,
            radius: bubbleRadius,
            textHeight: bubbleTextSize
        });
    });

    for (let index = 0; index < axisPositions.length - 1; index += 1) {
        addVerticalDimension(
            dxf,
            dimensionLayer,
            diagramLeft - dimensionOffset,
            axisPositions[index],
            axisPositions[index + 1],
            Math.abs(axisEntries[index + 1].value - axisEntries[index].value).toFixed(2),
            diagramLeft - dimensionOriginOffset,
            {
                visualScale: dimensionScale,
                textHeight: dimensionTextHeight,
                architecturalDenominator: options.architecturalDenominator
                    ?? DXF_IMPERIAL_DETAIL_DENOMINATOR
            }
        );
    }
}

function formatPlanViewDimensionValue(value) {
    const numericValue = parseNumberOrFallback(value, 0);
    return Math.abs(numericValue) < EDGE_TOLERANCE ? "0.00" : Math.abs(numericValue).toFixed(2);
}

function formatColumnPlanDimensionValue(
    valueMeters,
    unitSystem = null,
    denominator = DXF_IMPERIAL_GENERAL_PLAN_DENOMINATOR
) {
    const numericValue = Math.abs(parseNumberOrFallback(valueMeters, 0));
    const normalizedUnitSystem = normalizeUnitSystem(unitSystem || getCurrentUnitSystem());
    if (normalizedUnitSystem !== "imperial") {
        return formatPlanViewDimensionValue(numericValue);
    }

    return formatArchitecturalInchesOnly(
        numericValue,
        normalizeArchitecturalDenominator(
            denominator,
            DXF_IMPERIAL_GENERAL_PLAN_DENOMINATOR
        )
    );
}

function drawPlanViewRectDimensions(dxf, left, right, bottom, top, options = {}) {
    const dimensionLayer = options.dimensionLayer || "COTAS_SECCION";
    const dimensionOffset = Math.max(parseNumberOrFallback(options.dimensionOffset, PLAN_VIEW_ELEMENT_DIMENSION_OFFSET), 0.08);
    const visualScale = Math.max(parseNumberOrFallback(options.visualScale, PLAN_VIEW_ELEMENT_DIMENSION_VISUAL_SCALE), 0.05);
    const textHeight = Math.max(parsePositiveNumberOrFallback(options.textHeight, getPlanAnnotationTextHeight(), 0.001), 0.001);
    const normalizedLeft = Math.min(left, right);
    const normalizedRight = Math.max(left, right);
    const normalizedBottom = Math.min(bottom, top);
    const normalizedTop = Math.max(bottom, top);
    const width = Math.abs(normalizedRight - normalizedLeft);
    const height = Math.abs(normalizedTop - normalizedBottom);
    const xDimensionSide = options.xDimensionSide === "bottom" ? "bottom" : "top";
    const yDimensionSide = options.yDimensionSide === "right" ? "right" : "left";
    const xDimensionOffset = dimensionOffset * Math.max(parseNumberOrFallback(options.xDimensionOffsetMultiplier, 1), 0.4);
    const yDimensionOffset = dimensionOffset * Math.max(parseNumberOrFallback(options.yDimensionOffsetMultiplier, 1), 0.4);

    if (width > EDGE_TOLERANCE) {
        const xDimensionOriginY = xDimensionSide === "bottom" ? normalizedBottom : normalizedTop;
        const xDimensionLineY = xDimensionSide === "bottom"
            ? normalizedBottom - xDimensionOffset
            : normalizedTop + xDimensionOffset;
        addDimension(
            dxf,
            dimensionLayer,
            normalizedLeft,
            normalizedRight,
            xDimensionLineY,
            options.xLabel || formatPlanViewDimensionValue(width),
            xDimensionOriginY,
            {
                visualScale,
                textHeight,
                architecturalDenominator: options.architecturalDenominator
                    ?? DXF_IMPERIAL_DETAIL_DENOMINATOR,
                ...(options.arrowSize != null ? { arrowSize: options.arrowSize } : {})
            }
        );
    }

    if (height > EDGE_TOLERANCE) {
        const yDimensionOriginX = yDimensionSide === "right" ? normalizedRight : normalizedLeft;
        const yDimensionLineX = yDimensionSide === "right"
            ? normalizedRight + yDimensionOffset
            : normalizedLeft - yDimensionOffset;
        addVerticalDimension(
            dxf,
            dimensionLayer,
            yDimensionLineX,
            normalizedBottom,
            normalizedTop,
            options.yLabel || formatPlanViewDimensionValue(height),
            yDimensionOriginX,
            {
                visualScale,
                textHeight,
                architecturalDenominator: options.architecturalDenominator
                    ?? DXF_IMPERIAL_DETAIL_DENOMINATOR,
                ...(options.arrowSize != null ? { arrowSize: options.arrowSize } : {})
            }
        );
    }
}

function getColumnPlanBounds(level) {
    const columns = (level?.columns || []).map((column) => normalizeColumnModel(column));
    const xValues = [];
    const yValues = [];

    columns.forEach((column) => {
        const isSteel = isStructuralSteelElement(column);
        const steelFootprint = isSteel ? getDxfSteelProfileFootprint(column) : null;
        const footprint = isSteel && steelFootprint?.width > EDGE_TOLERANCE && steelFootprint?.height > EDGE_TOLERANCE
            ? { width: steelFootprint.width, height: steelFootprint.height }
            : getColumnFootprint(column);
        xValues.push(column.x - footprint.width / 2, column.x + footprint.width / 2);
        yValues.push(column.y - footprint.height / 2, column.y + footprint.height / 2);
    });

    const xBounds = getPlanAxisBounds("x", xValues, columns[0]?.x || 0);
    const yBounds = getPlanAxisBounds("y", yValues, columns[0]?.y || 0);
    return {
        minX: xBounds.min,
        maxX: xBounds.max,
        minY: yBounds.min,
        maxY: yBounds.max,
        xAxisEntries: xBounds.axisEntries,
        yAxisEntries: yBounds.axisEntries
    };
}

function getWallPlanBounds(level) {
    const walls = (level?.walls || []).map((wall) => normalizeWall(wall));
    const xValues = [];
    const yValues = [];

    walls.forEach((wall) => {
        const connectedBounds = getConnectedWallPlanBounds(walls, wall);
        xValues.push(connectedBounds.left, connectedBounds.right);
        yValues.push(connectedBounds.bottom, connectedBounds.top);
    });

    const xBounds = getPlanAxisBounds("x", xValues, 0);
    const yBounds = getPlanAxisBounds("y", yValues, 0);
    return {
        minX: xBounds.min,
        maxX: xBounds.max,
        minY: yBounds.min,
        maxY: yBounds.max,
        xAxisEntries: xBounds.axisEntries,
        yAxisEntries: yBounds.axisEntries
    };
}

function getPlanViewSheetMetrics(bounds, options = {}) {
    const width = Math.max((bounds?.maxX ?? 0) - (bounds?.minX ?? 0), EDGE_TOLERANCE);
    const height = Math.max((bounds?.maxY ?? 0) - (bounds?.minY ?? 0), EDGE_TOLERANCE);
    const leftClearance = options.leftClearance ?? (SLAB_PLAN_AXIS_BUBBLE_OFFSET + SLAB_PLAN_AXIS_BUBBLE_RADIUS + 0.45);
    const rightClearance = options.rightClearance ?? 0.8;
    const bottomClearance = options.bottomClearance ?? 1.25;
    const topClearance = options.topClearance ?? (SLAB_PLAN_AXIS_BUBBLE_OFFSET + SLAB_PLAN_AXIS_BUBBLE_RADIUS + 0.45);

    return {
        width: leftClearance + width + rightClearance,
        height: bottomClearance + height + topClearance,
        planWidth: width,
        planHeight: height,
        leftClearance,
        rightClearance,
        bottomClearance,
        topClearance
    };
}

function drawOutsideWallPlanLabel(dxf, label, left, right, bottom, top, orientation, diagramLeft, diagramRight, diagramBottom, diagramTop, symbolScale, options = {}) {
    if (!label) {
        return;
    }

    const textSize = Math.max(parsePositiveNumberOrFallback(options.textSize, getPlanAnnotationTextHeight(), 0.001), 0.001);
    const textWidth = estimateDxfTextWidth(label, textSize);
    const textHeight = textSize;
    const margin = Math.max(parseNumberOrFallback(options.margin, 0.08 * symbolScale), 0.06);
    const centerX = (left + right) / 2;
    const centerY = (bottom + top) / 2;

    if (orientation === "horizontal") {
        const baselineOffset = textHeight * 0.7;
        const preferredBelowY = bottom - margin - baselineOffset;
        const minimumBelowY = diagramBottom + baselineOffset + 0.02;
        if (preferredBelowY >= minimumBelowY) {
            addCenteredText(dxf, "SECCION_TEXTO", centerX, preferredBelowY, label, textSize);
            return;
        }

        const preferredAboveY = top + margin + baselineOffset;
        addCenteredText(dxf, "SECCION_TEXTO", centerX, preferredAboveY, label, textSize);
        return;
    }

    const edgeGap = Math.max(parseNumberOrFallback(options.edgeGap, 0.03), 0);
    const desiredLabelY = Number.isFinite(options.positionY)
        ? options.positionY
        : (bottom + (top - bottom) / 3);
    const labelBaselineY = desiredLabelY;

    if (options.alignRightToWall === true) {
        const preferredLeftX = left - textWidth - Math.max(margin, edgeGap);
        const minimumLeftX = diagramLeft + 0.02;
        if (preferredLeftX >= minimumLeftX) {
            addText(dxf, "SECCION_TEXTO", preferredLeftX, labelBaselineY, label, textSize);
            return;
        }

        const preferredRightX = right + Math.max(margin, edgeGap);
        addText(dxf, "SECCION_TEXTO", preferredRightX, labelBaselineY, label, textSize);
        return;
    }

    const preferredX = left - margin - textWidth / 2;
    const minimumX = diagramLeft + textWidth / 2 + 0.04;
    const maximumX = Math.min(left - margin - textWidth / 2, diagramRight - textWidth / 2 - 0.04);
    addCenteredText(dxf, "SECCION_TEXTO", Math.max(minimumX, maximumX), centerY, label, textSize);
}

function getWallAxisBubbleRadius(label, textSize, minimumRadius = WALL_DETAIL_AXIS_BUBBLE_RADIUS) {
    return DXF_AXIS_CIRCLE_RADIUS;
}

function getWallPlanOrientation(wall) {
    return Math.abs(wall.x1 - wall.x2) >= Math.abs(wall.y1 - wall.y2)
        ? "horizontal"
        : "vertical";
}


function getWallDetailReferenceWalls(detailOrWall) {
    if (Array.isArray(detailOrWall?.groupWalls) && detailOrWall.groupWalls.length) {
        return detailOrWall.groupWalls.map((item) => normalizeWall(item));
    }
    if (Array.isArray(detailOrWall?.detailWalls) && detailOrWall.detailWalls.length) {
        return detailOrWall.detailWalls.map((item) => normalizeWall(item));
    }
    if (detailOrWall?.wall) {
        return [normalizeWall(detailOrWall.wall)];
    }
    return detailOrWall ? [normalizeWall(detailOrWall)] : [];
}

function resolveWallDetailLevel(detailOrWall, levels = projectState.levels) {
    const referenceWalls = getWallDetailReferenceWalls(detailOrWall);
    if (!referenceWalls.length) {
        return null;
    }
    const referenceKeys = new Set(referenceWalls.map((wall) => getWallDetailIdentityKey(wall)));
    return (levels || []).find((level) => (
        (level?.walls || []).some((candidate) => referenceKeys.has(getWallDetailIdentityKey(candidate)))
    )) || null;
}

function getWallEndpointColumnConnection(wall, endpointKind, columns = []) {
    const normalizedWall = normalizeWall(wall);
    const orientation = getWallPlanOrientation(normalizedWall);
    const wallThickness = Math.max(parsePositiveNumberOrFallback(normalizedWall.b, DEFAULT_WALL_THICKNESS, 0.08), 0.08);
    const tolerance = Math.max(0.05, wallThickness * 0.2);
    const endpointX = endpointKind === "start"
        ? (orientation === "horizontal" ? Math.min(normalizedWall.x1, normalizedWall.x2) : (normalizedWall.x1 + normalizedWall.x2) / 2)
        : (orientation === "horizontal" ? Math.max(normalizedWall.x1, normalizedWall.x2) : (normalizedWall.x1 + normalizedWall.x2) / 2);
    const endpointY = endpointKind === "start"
        ? (orientation === "vertical" ? Math.min(normalizedWall.y1, normalizedWall.y2) : (normalizedWall.y1 + normalizedWall.y2) / 2)
        : (orientation === "vertical" ? Math.max(normalizedWall.y1, normalizedWall.y2) : (normalizedWall.y1 + normalizedWall.y2) / 2);
    let best = null;
    let bestDistance = Number.POSITIVE_INFINITY;

    (columns || []).forEach((columnSource) => {
        const column = normalizeColumnModel(columnSource);
        const footprint = getColumnFootprint(column);
        const left = column.x - footprint.width / 2;
        const right = column.x + footprint.width / 2;
        const bottom = column.y - footprint.height / 2;
        const top = column.y + footprint.height / 2;

        if (orientation === "horizontal") {
            if (endpointY < bottom - tolerance || endpointY > top + tolerance) {
                return;
            }
            if (endpointX < left - tolerance || endpointX > right + tolerance) {
                return;
            }
            const faceX = endpointKind === "start" ? right : left;
            const distance = Math.abs(endpointX - faceX);
            if (distance < bestDistance) {
                best = { column, faceX, rect: { left, right, bottom, top } };
                bestDistance = distance;
            }
            return;
        }

        if (endpointX < left - tolerance || endpointX > right + tolerance) {
            return;
        }
        if (endpointY < bottom - tolerance || endpointY > top + tolerance) {
            return;
        }
        const faceY = endpointKind === "start" ? top : bottom;
        const distance = Math.abs(endpointY - faceY);
        if (distance < bestDistance) {
            best = { column, faceY, rect: { left, right, bottom, top } };
            bestDistance = distance;
        }
    });

    return best;
}

function getWallDetailAttachedColumns(detailOrWall, walls = null, levels = projectState.levels) {
    const level = resolveWallDetailLevel(detailOrWall, levels);
    if (!level) {
        return [];
    }
    const columns = (level?.columns || []).map((column) => normalizeColumnModel(column));
    if (!columns.length) {
        return [];
    }
    const referenceWalls = Array.isArray(walls) && walls.length
        ? walls.map((wall) => normalizeWall(wall))
        : getWallDetailReferenceWalls(detailOrWall);
    const attached = new Map();
    referenceWalls.forEach((wall) => {
        ["start", "end"].forEach((endpointKind) => {
            const connection = getWallEndpointColumnConnection(wall, endpointKind, columns);
            if (connection?.column?.id && !attached.has(connection.column.id)) {
                attached.set(connection.column.id, connection.column);
            }
        });
    });
    return Array.from(attached.values());
}

function getConnectedWallPlanBounds(walls, wall) {
    const normalizedWall = normalizeWall(wall);
    const orientation = getWallPlanOrientation(normalizedWall);
    const thickness = Math.max(parsePositiveNumberOrFallback(normalizedWall.b, DEFAULT_WALL_THICKNESS, 0.08), 0.08);
    const connectionTolerance = Math.max(0.06, thickness * 0.2);
    const overlapAllowance = Math.max(0.02, thickness * 0.06);
    const fixedValue = orientation === "horizontal"
        ? (normalizedWall.y1 + normalizedWall.y2) / 2
        : (normalizedWall.x1 + normalizedWall.x2) / 2;
    const originalStartValue = orientation === "horizontal"
        ? Math.min(normalizedWall.x1, normalizedWall.x2)
        : Math.min(normalizedWall.y1, normalizedWall.y2);
    const originalEndValue = orientation === "horizontal"
        ? Math.max(normalizedWall.x1, normalizedWall.x2)
        : Math.max(normalizedWall.y1, normalizedWall.y2);
    let startValue = originalStartValue;
    let endValue = originalEndValue;
    let startConnected = false;
    let endConnected = false;
    let startConnectionKind = null;
    let endConnectionKind = null;
    let startConnection = null;
    let endConnection = null;

    const findEndpointConnection = (endpointValue, endpointKind) => {
        let bestConnection = null;
        let bestDistance = Number.POSITIVE_INFINITY;
        const extensionDirection = endpointKind === "start" ? -1 : 1;
        const currentRunDirection = endpointKind === "start" ? 1 : -1;

        (walls || []).forEach((otherWall) => {
            const other = normalizeWall(otherWall);
            if (other.id === normalizedWall.id) {
                return;
            }

            const otherOrientation = getWallPlanOrientation(other);
            const otherThickness = Math.max(parsePositiveNumberOrFallback(other.b, DEFAULT_WALL_THICKNESS, 0.08), 0.08);
            const tolerance = Math.max(connectionTolerance, Math.max(0.06, otherThickness * 0.2));

            if (otherOrientation === orientation) {
                const otherFixedValue = orientation === "horizontal"
                    ? (other.y1 + other.y2) / 2
                    : (other.x1 + other.x2) / 2;
                if (!areClose(otherFixedValue, fixedValue, tolerance)) {
                    return;
                }

                const otherStartValue = orientation === "horizontal"
                    ? Math.min(other.x1, other.x2)
                    : Math.min(other.y1, other.y2);
                const otherEndValue = orientation === "horizontal"
                    ? Math.max(other.x1, other.x2)
                    : Math.max(other.y1, other.y2);

                [otherStartValue, otherEndValue].forEach((candidateValue) => {
                    const distance = Math.abs(candidateValue - endpointValue);
                    if (distance <= tolerance && distance < bestDistance) {
                        bestConnection = {
                            value: candidateValue + extensionDirection * overlapAllowance,
                            distance,
                            kind: "collinear",
                            currentRunDirection
                        };
                        bestDistance = distance;
                    }
                });
                return;
            }

            if (orientation === "horizontal") {
                const otherCenter = (other.x1 + other.x2) / 2;
                const otherHalfThickness = otherThickness / 2;
                const otherMinY = Math.min(other.y1, other.y2);
                const otherMaxY = Math.max(other.y1, other.y2);
                const endpointInsideOtherThickness = endpointValue >= otherCenter - otherHalfThickness - tolerance
                    && endpointValue <= otherCenter + otherHalfThickness + tolerance;
                const fixedInsideOtherLength = fixedValue >= otherMinY - tolerance
                    && fixedValue <= otherMaxY + tolerance;

                if (endpointInsideOtherThickness && fixedInsideOtherLength) {
                    const distance = Math.max(Math.abs(otherCenter - endpointValue) - otherHalfThickness, 0);
                    if (distance <= tolerance && distance < bestDistance) {
                        const otherStartDistance = Math.abs(fixedValue - otherMinY);
                        const otherEndDistance = Math.abs(fixedValue - otherMaxY);
                        const otherSpanDirection = otherStartDistance <= otherEndDistance ? 1 : -1;
                        const otherEndpointTolerance = Math.max(tolerance, Math.min(otherThickness * 0.5, 0.18));
                        bestConnection = {
                            value: otherCenter - extensionDirection * otherHalfThickness,
                            distance,
                            kind: "perpendicular",
                            currentRunDirection,
                            otherCenter,
                            otherHalfThickness,
                            otherSpanDirection,
                            // An L connection reaches the end of the perpendicular wall. In a T
                            // connection the perpendicular wall continues past both faces, so both
                            // contours must stop at the first (nearest) face instead.
                            intersectsOtherEndpoint: Math.min(otherStartDistance, otherEndDistance) <= otherEndpointTolerance
                        };
                        bestDistance = distance;
                    }
                }
                return;
            }

            const otherCenter = (other.y1 + other.y2) / 2;
            const otherHalfThickness = otherThickness / 2;
            const otherMinX = Math.min(other.x1, other.x2);
            const otherMaxX = Math.max(other.x1, other.x2);
            const endpointInsideOtherThickness = endpointValue >= otherCenter - otherHalfThickness - tolerance
                && endpointValue <= otherCenter + otherHalfThickness + tolerance;
            const fixedInsideOtherLength = fixedValue >= otherMinX - tolerance
                && fixedValue <= otherMaxX + tolerance;

            if (endpointInsideOtherThickness && fixedInsideOtherLength) {
                const distance = Math.max(Math.abs(otherCenter - endpointValue) - otherHalfThickness, 0);
                if (distance <= tolerance && distance < bestDistance) {
                    const otherStartDistance = Math.abs(fixedValue - otherMinX);
                    const otherEndDistance = Math.abs(fixedValue - otherMaxX);
                    const otherSpanDirection = otherStartDistance <= otherEndDistance ? 1 : -1;
                    const otherEndpointTolerance = Math.max(tolerance, Math.min(otherThickness * 0.5, 0.18));
                    bestConnection = {
                        value: otherCenter - extensionDirection * otherHalfThickness,
                        distance,
                        kind: "perpendicular",
                        currentRunDirection,
                        otherCenter,
                        otherHalfThickness,
                        otherSpanDirection,
                        // See the horizontal branch above: only L corners use separate faces.
                        intersectsOtherEndpoint: Math.min(otherStartDistance, otherEndDistance) <= otherEndpointTolerance
                    };
                    bestDistance = distance;
                }
            }
        });

        return bestConnection;
    };

    const connectedStart = findEndpointConnection(startValue, "start");
    if (connectedStart && Number.isFinite(connectedStart.value)) {
        startValue = connectedStart.value;
        startConnected = true;
        startConnectionKind = connectedStart.kind;
        startConnection = connectedStart;
    }

    const connectedEnd = findEndpointConnection(endValue, "end");
    if (connectedEnd && Number.isFinite(connectedEnd.value)) {
        endValue = connectedEnd.value;
        endConnected = true;
        endConnectionKind = connectedEnd.kind;
        endConnection = connectedEnd;
    }

    let dimensionStartValue = startValue;
    let dimensionEndValue = endValue;
    if (startConnection?.kind === "perpendicular") {
        dimensionStartValue = startConnection.otherCenter + startConnection.currentRunDirection * startConnection.otherHalfThickness;
    }
    if (endConnection?.kind === "perpendicular") {
        dimensionEndValue = endConnection.otherCenter + endConnection.currentRunDirection * endConnection.otherHalfThickness;
    }

    if (orientation === "horizontal") {
        return {
            left: Math.min(startValue, endValue),
            right: Math.max(startValue, endValue),
            bottom: fixedValue - thickness / 2,
            top: fixedValue + thickness / 2,
            orientation,
            startConnected,
            endConnected,
            startConnectionKind,
            endConnectionKind,
            startConnection,
            endConnection,
            originalStartValue,
            originalEndValue,
            dimensionStartValue: Math.min(dimensionStartValue, dimensionEndValue),
            dimensionEndValue: Math.max(dimensionStartValue, dimensionEndValue)
        };
    }

    return {
        left: fixedValue - thickness / 2,
        right: fixedValue + thickness / 2,
        bottom: Math.min(startValue, endValue),
        top: Math.max(startValue, endValue),
        orientation,
        startConnected,
        endConnected,
        startConnectionKind,
        endConnectionKind,
        startConnection,
        endConnection,
        originalStartValue,
        originalEndValue,
        dimensionStartValue: Math.min(dimensionStartValue, dimensionEndValue),
        dimensionEndValue: Math.max(dimensionStartValue, dimensionEndValue)
    };
}

function getWallPlanPerpendicularEdgeJoinValue(connection, edgeSign) {
    if (!connection || connection.kind !== "perpendicular") {
        return null;
    }

    // At a T connection both faces end on the first face of the crossing wall.
    // At an L connection, however, the two faces belong to different exterior /
    // interior corners, so each face must continue independently to the face it
    // actually intersects. This avoids both premature stops and diagonal closures.
    if (!connection.intersectsOtherEndpoint) {
        return Number.isFinite(connection.value) ? connection.value : null;
    }

    const { otherCenter, currentRunDirection, otherSpanDirection, otherHalfThickness } = connection;
    if (![otherCenter, currentRunDirection, otherSpanDirection, otherHalfThickness].every(Number.isFinite)) {
        return Number.isFinite(connection.value) ? connection.value : null;
    }

    return otherCenter
        + currentRunDirection * otherSpanDirection * edgeSign * otherHalfThickness;
}

function getFittedPlanDetailLayout(bounds, contentLeft, planTop, contentWidth, planHeight, options = {}) {
    const minX = bounds.minX;
    const maxX = bounds.maxX;
    const minY = bounds.minY;
    const maxY = bounds.maxY;
    const sourceWidth = Math.max(maxX - minX, EDGE_TOLERANCE);
    const sourceHeight = Math.max(maxY - minY, EDGE_TOLERANCE);
    const fitToContentBox = Boolean(options.fitToContentBox);

    if (!fitToContentBox) {
        const diagramLeft = contentLeft + 0.55;
        const diagramRight = diagramLeft + sourceWidth;
        const diagramTop = planTop - 0.18;
        const diagramBottom = diagramTop - sourceHeight;
        return {
            minX,
            maxX,
            minY,
            maxY,
            diagramLeft,
            diagramRight,
            diagramTop,
            diagramBottom,
            axisScale: 1,
            labelScale: 1,
            dimensionVisualScale: options.dimensionVisualScale ?? PLAN_VIEW_ELEMENT_DIMENSION_VISUAL_SCALE,
            returnGap: options.returnBottomGap ?? 0.55
        };
    }

    const contentBoxWidth = Math.max(parsePositiveNumberOrFallback(contentWidth, sourceWidth, EDGE_TOLERANCE), EDGE_TOLERANCE);
    const contentBoxHeight = Math.max(parsePositiveNumberOrFallback(planHeight, sourceHeight, EDGE_TOLERANCE), EDGE_TOLERANCE);
    const axisScale = Math.max(
        Math.min(parseNumberOrFallback(options.axisScale, DETAIL_HEADER_PLAN_AXIS_SCALE), 1),
        DETAIL_HEADER_PLAN_MIN_AXIS_SCALE
    );
    const leftClearance = (SLAB_PLAN_AXIS_BUBBLE_OFFSET + SLAB_PLAN_AXIS_BUBBLE_RADIUS + 0.45) * axisScale;
    const topClearance = (SLAB_PLAN_AXIS_BUBBLE_OFFSET + SLAB_PLAN_AXIS_BUBBLE_RADIUS + 0.45) * axisScale;
    const rightClearance = Math.max(parseNumberOrFallback(options.rightClearance, DETAIL_HEADER_PLAN_RIGHT_CLEARANCE), 0.08);
    const bottomClearance = Math.max(parseNumberOrFallback(options.bottomClearance, DETAIL_HEADER_PLAN_BOTTOM_CLEARANCE), 0.08);
    const availableWidth = Math.max(contentBoxWidth - leftClearance - rightClearance, EDGE_TOLERANCE);
    const availableHeight = Math.max(contentBoxHeight - topClearance - bottomClearance, EDGE_TOLERANCE);
    const drawingScale = Math.min(availableWidth / sourceWidth, availableHeight / sourceHeight, 1);
    const diagramWidth = sourceWidth * drawingScale;
    const diagramHeight = sourceHeight * drawingScale;
    const diagramLeft = contentLeft + leftClearance;
    const diagramRight = diagramLeft + diagramWidth;
    const diagramTop = planTop - topClearance;
    const diagramBottom = diagramTop - diagramHeight;
    const labelScale = Math.max(Math.min(axisScale, drawingScale, 1), 0.22);

    return {
        minX,
        maxX,
        minY,
        maxY,
        diagramLeft,
        diagramRight,
        diagramTop,
        diagramBottom,
        axisScale,
        labelScale,
        dimensionVisualScale: axisScale,
        returnGap: options.returnBottomGap ?? DETAIL_HEADER_PLAN_RETURN_GAP
    };
}

function drawColumnPlanDetail(dxf, level, contentLeft, planTop, contentWidth, planHeight, options = {}) {
    const columns = (level?.columns || []).map((column) => normalizeColumnModel(column));
    const bounds = getColumnPlanBounds(level);
    const xAxisEntries = bounds.xAxisEntries;
    const yAxisEntries = bounds.yAxisEntries;
    const layout = getFittedPlanDetailLayout(bounds, contentLeft, planTop, contentWidth, planHeight, options);
    const minX = layout.minX;
    const maxX = layout.maxX;
    const minY = layout.minY;
    const maxY = layout.maxY;
    const diagramLeft = layout.diagramLeft;
    const diagramRight = layout.diagramRight;
    const diagramTop = layout.diagramTop;
    const diagramBottom = layout.diagramBottom;
    const axisScale = layout.axisScale;
    const labelScale = layout.labelScale;
    const elementLabelTextSize = getPlanElementLabelTextSize(options.elementLabelTextSize, getPlanAnnotationTextHeight());
    const dimensionVisualScale = layout.dimensionVisualScale;
    const architecturalDenominator = options.architecturalDenominator
        ?? (options.fitToContentBox
            ? DXF_IMPERIAL_DETAIL_DENOMINATOR
            : DXF_IMPERIAL_GENERAL_PLAN_DENOMINATOR);
    const toDrawingX = (value) => mapLinearValue(value, minX, maxX, diagramLeft, diagramRight);
    const toDrawingY = (value) => mapLinearValue(value, minY, maxY, diagramTop, diagramBottom);

    drawPlanAxisSet(dxf, "x", xAxisEntries, minX, maxX, diagramLeft, diagramRight, diagramTop, diagramBottom, {
        bubbleScale: axisScale,
        bubbleRadius: SLAB_PLAN_AXIS_BUBBLE_RADIUS,
        bubbleOffset: SLAB_PLAN_AXIS_BUBBLE_OFFSET,
        axisLineScale: axisScale,
        dimensionScale: dimensionVisualScale,
        bubbleTextSize: getPlanAnnotationTextHeight(),
        bubbleTextMinSize: getPlanAnnotationTextHeight(),
        dimensionTextHeight: elementLabelTextSize,
        dimensionOffset: SLAB_PLAN_AXIS_DIMENSION_OFFSET,
        dimensionOriginOffset: SLAB_PLAN_AXIS_DIMENSION_ORIGIN_OFFSET,
        architecturalDenominator
    });
    drawPlanAxisSet(dxf, "y", yAxisEntries, minY, maxY, diagramLeft, diagramRight, diagramTop, diagramBottom, {
        bubbleScale: axisScale,
        bubbleRadius: SLAB_PLAN_AXIS_BUBBLE_RADIUS,
        bubbleOffset: SLAB_PLAN_AXIS_BUBBLE_OFFSET,
        axisLineScale: axisScale,
        dimensionScale: dimensionVisualScale,
        bubbleTextSize: getPlanAnnotationTextHeight(),
        bubbleTextMinSize: getPlanAnnotationTextHeight(),
        dimensionTextHeight: elementLabelTextSize,
        dimensionOffset: SLAB_PLAN_AXIS_DIMENSION_OFFSET,
        dimensionOriginOffset: SLAB_PLAN_AXIS_DIMENSION_ORIGIN_OFFSET,
        architecturalDenominator
    });

    columns.forEach((column) => {
        const isSteel = isStructuralSteelElement(column);
        const sectionDesigner = !isSteel ? getDxfSectionDesignerConcrete(column) : null;
        const sectionDesignerPlanBounds = sectionDesigner ? getDxfSectionDesignerPlanBounds(column) : null;
        const steelFootprint = isSteel ? getDxfSteelProfileFootprint(column) : null;
        const isCircularConcreteColumn = !isSteel && !sectionDesignerPlanBounds && isCircularColumnSection(column);
        const regularColumnPlanPoints = !isSteel && !sectionDesignerPlanBounds && !isCircularConcreteColumn
            ? getDxfRegularColumnPlanPoints(column)
            : null;
        const regularColumnPlanBounds = regularColumnPlanPoints
            ? getDxfPlanBoundsFromPoints(regularColumnPlanPoints)
            : null;
        const footprint = sectionDesignerPlanBounds
            ? { width: sectionDesignerPlanBounds.width, height: sectionDesignerPlanBounds.height }
            : (isSteel && steelFootprint?.width > EDGE_TOLERANCE && steelFootprint?.height > EDGE_TOLERANCE
                ? { width: steelFootprint.width, height: steelFootprint.height }
                : getColumnFootprint(column));
        const columnLabel = isSteel
            ? normalizeTextValue(steelFootprint?.profile?.name || column.sourceSection || column.sectionName || column.name)
            : (normalizeTextValue(column.name) || getSmartEntityName("column", column));
        const sourceBounds = sectionDesignerPlanBounds || regularColumnPlanBounds || {
            minX: column.x - footprint.width / 2,
            maxX: column.x + footprint.width / 2,
            minY: column.y - footprint.height / 2,
            maxY: column.y + footprint.height / 2
        };
        const leftX = toDrawingX(sourceBounds.minX);
        const rightX = toDrawingX(sourceBounds.maxX);
        const bottomY = toDrawingY(sourceBounds.minY);
        const topY = toDrawingY(sourceBounds.maxY);
        const centerX = toDrawingX(column.x);
        const centerY = toDrawingY(column.y);
        const rectLeft = Math.min(leftX, rightX);
        const rectRight = Math.max(leftX, rightX);
        const rectBottom = Math.min(bottomY, topY);
        const rectTop = Math.max(bottomY, topY);
        const rectWidth = Math.max(rectRight - rectLeft, 0.08 * labelScale);
        const rectHeight = Math.max(rectTop - rectBottom, 0.08 * labelScale);
        const drawLeft = centerX - rectWidth / 2;
        const drawBottom = centerY - rectHeight / 2;
        const drawRight = drawLeft + rectWidth;
        const drawTop = drawBottom + rectHeight;

        if (isSteel && steelFootprint?.profile) {
            drawDxfSteelProfile(dxf, steelFootprint.profile, drawLeft, drawBottom, rectWidth, rectHeight);
        } else if (sectionDesignerPlanBounds) {
            drawDxfSectionDesignerPlanProfile(dxf, column, toDrawingX, toDrawingY);
            drawPlanViewRectDimensions(dxf, rectLeft, rectRight, rectBottom, rectTop, {
                visualScale: dimensionVisualScale,
                textHeight: elementLabelTextSize,
                architecturalDenominator,
                xLabel: formatColumnPlanDimensionValue(footprint.width, null, architecturalDenominator),
                yLabel: formatColumnPlanDimensionValue(footprint.height, null, architecturalDenominator)
            });
        } else if (isCircularConcreteColumn) {
            const radius = Math.max(Math.min(rectWidth, rectHeight) / 2, 0.04 * labelScale);
            addFilledCircle(dxf, "CONCRETO_COLUMNAS", centerX, centerY, radius, 7, 32);
            addCircle(dxf, "CONCRETO_COLUMNAS", centerX, centerY, radius);
            drawPlanViewRectDimensions(dxf, drawLeft, drawRight, drawBottom, drawTop, {
                visualScale: dimensionVisualScale,
                textHeight: elementLabelTextSize,
                architecturalDenominator,
                xLabel: `D=${formatColumnPlanDimensionValue(getColumnDiameter(column), null, architecturalDenominator)}`,
                yLabel: `D=${formatColumnPlanDimensionValue(getColumnDiameter(column), null, architecturalDenominator)}`
            });
        } else {
            const rotation = getDxfSectionDesignerAngle(column);
            if (regularColumnPlanPoints && Math.abs(rotation) > 1e-8) {
                const mappedPoints = regularColumnPlanPoints.map((point) => ({ x: toDrawingX(point.x), y: toDrawingY(point.y) }));
                addFilledQuadrilateral(dxf, "CONCRETO_COLUMNAS", mappedPoints, 7);
                getPolygonSegments(mappedPoints).forEach((segment) => {
                    addLine(dxf, "CONCRETO_COLUMNAS", segment.x1, segment.y1, segment.x2, segment.y2);
                });
            } else {
                addFilledRectangle(dxf, "CONCRETO_COLUMNAS", drawLeft, drawBottom, rectWidth, rectHeight, 7);
                addRectangle(dxf, "CONCRETO_COLUMNAS", drawLeft, drawBottom, rectWidth, rectHeight);
            }
            drawPlanViewRectDimensions(dxf, drawLeft, drawRight, drawBottom, drawTop, {
                visualScale: dimensionVisualScale,
                textHeight: elementLabelTextSize,
                architecturalDenominator,
                xLabel: formatColumnPlanDimensionValue(getColumnWidth(column), null, architecturalDenominator),
                yLabel: formatColumnPlanDimensionValue(getColumnHeight(column), null, architecturalDenominator)
            });
        }

        if (columnLabel) {
            const textSize = elementLabelTextSize;
            const labelGap = Math.max(0.08 * labelScale, 0.03);
            const labelX = rectRight + labelGap;
            const labelY = Math.min(Math.max(centerY + 0.04 * labelScale, diagramBottom + 0.12 * labelScale), diagramTop - 0.04 * labelScale);
            addText(dxf, "SECCION_TEXTO", labelX, labelY, columnLabel, textSize);
        }
    });

    return diagramBottom - layout.returnGap;
}

function doWallPlanBoundsTouchOrOverlap(boundsA, boundsB, tolerance = EDGE_TOLERANCE) {
    if (!boundsA || !boundsB) {
        return false;
    }

    return boundsA.left <= boundsB.right + tolerance
        && boundsA.right >= boundsB.left - tolerance
        && boundsA.bottom <= boundsB.top + tolerance
        && boundsA.top >= boundsB.bottom - tolerance;
}

function getConnectedWallPlanLabelGroupKey(entries, entryIndex) {
    const sourceEntry = entries[entryIndex];
    if (!sourceEntry?.labelKey) {
        return `wall-${entryIndex}`;
    }

    const visited = new Set([entryIndex]);
    const queue = [entryIndex];

    while (queue.length) {
        const currentIndex = queue.shift();
        const currentEntry = entries[currentIndex];
        entries.forEach((candidateEntry, candidateIndex) => {
            if (visited.has(candidateIndex) || candidateEntry.labelKey !== sourceEntry.labelKey) {
                return;
            }

            if (!doWallPlanBoundsTouchOrOverlap(currentEntry.connectedBounds, candidateEntry.connectedBounds, Math.max(EDGE_TOLERANCE, 0.02))) {
                return;
            }

            visited.add(candidateIndex);
            queue.push(candidateIndex);
        });
    }

    return Array.from(visited).sort((left, right) => left - right).join("|");
}

function getWallPlanDimensionPlacementOptions(wallEntry) {
    const connectedBounds = wallEntry?.connectedBounds || {};
    const orientation = wallEntry?.orientation || connectedBounds.orientation || "horizontal";

    if (orientation === "vertical") {
        return {
            dimensionOffset: WALL_PLAN_ELEMENT_DIMENSION_OFFSET,
            xDimensionSide: "bottom",
            xDimensionOffsetMultiplier: 1,
            yDimensionSide: "right",
            yDimensionOffsetMultiplier: 1
        };
    }

    return {
        dimensionOffset: WALL_PLAN_ELEMENT_DIMENSION_OFFSET,
        xDimensionSide: "top",
        xDimensionOffsetMultiplier: 1,
        yDimensionSide: "right",
        yDimensionOffsetMultiplier: 1
    };
}

function drawConnectedWallPlanOutline(dxf, entry) {
    if (!entry) {
        return;
    }

    const { wallLayer, orientation, rectLeft, rectRight, rectBottom, rectTop, outline, connectedBounds } = entry;
    const startColumnConnection = entry.startColumnConnection || null;
    const endColumnConnection = entry.endColumnConnection || null;
    const overlap = 0.001;
    const alignedTolerance = 0.002;

    if (orientation === "horizontal") {
        addLine(dxf, wallLayer, outline.topStartX - overlap, rectTop, outline.topEndX + overlap, rectTop);
        addLine(dxf, wallLayer, outline.bottomStartX - overlap, rectBottom, outline.bottomEndX + overlap, rectBottom);
        if (!connectedBounds.startConnected && !startColumnConnection) {
            addLine(dxf, wallLayer, rectLeft, rectBottom, rectLeft, rectTop);
        } else if (!startColumnConnection && Math.abs((outline.topStartX ?? rectLeft) - (outline.bottomStartX ?? rectLeft)) <= alignedTolerance) {
            const joinX = ((outline.topStartX ?? rectLeft) + (outline.bottomStartX ?? rectLeft)) / 2;
            addLine(dxf, wallLayer, joinX, rectBottom, joinX, rectTop);
        }
        if (!connectedBounds.endConnected && !endColumnConnection) {
            addLine(dxf, wallLayer, rectRight, rectBottom, rectRight, rectTop);
        } else if (!endColumnConnection && Math.abs((outline.topEndX ?? rectRight) - (outline.bottomEndX ?? rectRight)) <= alignedTolerance) {
            const joinX = ((outline.topEndX ?? rectRight) + (outline.bottomEndX ?? rectRight)) / 2;
            addLine(dxf, wallLayer, joinX, rectBottom, joinX, rectTop);
        }
        return;
    }

    addLine(dxf, wallLayer, rectLeft, outline.leftStartY - overlap, rectLeft, outline.leftEndY + overlap);
    addLine(dxf, wallLayer, rectRight, outline.rightStartY - overlap, rectRight, outline.rightEndY + overlap);
    if (!connectedBounds.startConnected && !startColumnConnection) {
        addLine(dxf, wallLayer, rectLeft, rectBottom, rectRight, rectBottom);
    } else if (!startColumnConnection && Math.abs((outline.leftStartY ?? rectBottom) - (outline.rightStartY ?? rectBottom)) <= alignedTolerance) {
        const joinY = ((outline.leftStartY ?? rectBottom) + (outline.rightStartY ?? rectBottom)) / 2;
        addLine(dxf, wallLayer, rectLeft, joinY, rectRight, joinY);
    }
    if (!connectedBounds.endConnected && !endColumnConnection) {
        addLine(dxf, wallLayer, rectLeft, rectTop, rectRight, rectTop);
    } else if (!endColumnConnection && Math.abs((outline.leftEndY ?? rectTop) - (outline.rightEndY ?? rectTop)) <= alignedTolerance) {
        const joinY = ((outline.leftEndY ?? rectTop) + (outline.rightEndY ?? rectTop)) / 2;
        addLine(dxf, wallLayer, rectLeft, joinY, rectRight, joinY);
    }
}

function addWallPlanConcreteWallHatch(dxf, vertices) {
    if (!Array.isArray(vertices) || vertices.length < 3) {
        return;
    }

    // Keep the wall-plan concrete fill identical to the slab-plan convention:
    // native AutoCAD AR-CONC geometry on the concrete-wall layer.  Each wall
    // footprint is a valid closed boundary, and a shared WCS origin keeps
    // connected walls visually continuous.
    addHatch(dxf, "CONCRETO_MUROS", vertices, {
        patternName: SLAB_PLAN_CONCRETE_HATCH_PATTERN,
        patternScale: SLAB_PLAN_CONCRETE_HATCH_SCALE,
        patternAngle: 0
    });
}

function drawWallLevelPlanDetail(dxf, level, contentLeft, planTop, contentWidth, planHeight, options = {}) {
    const walls = (level?.walls || []).map((wall) => normalizeWall(wall));
    const bounds = getWallPlanBounds(level);
    const xAxisEntries = bounds.xAxisEntries;
    const yAxisEntries = bounds.yAxisEntries;
    const layout = getFittedPlanDetailLayout(bounds, contentLeft, planTop, contentWidth, planHeight, options);
    const minX = layout.minX;
    const maxX = layout.maxX;
    const minY = layout.minY;
    const maxY = layout.maxY;
    const diagramLeft = layout.diagramLeft;
    const diagramRight = layout.diagramRight;
    const diagramTop = layout.diagramTop;
    const diagramBottom = layout.diagramBottom;
    const axisScale = layout.axisScale;
    const labelScale = layout.labelScale;
    const elementLabelTextSize = getPlanElementLabelTextSize(options.elementLabelTextSize, getPlanAnnotationTextHeight());
    const dimensionVisualScale = layout.dimensionVisualScale;
    const architecturalDenominator = options.architecturalDenominator
        ?? (options.fitToContentBox
            ? DXF_IMPERIAL_DETAIL_DENOMINATOR
            : DXF_IMPERIAL_GENERAL_PLAN_DENOMINATOR);
    const toDrawingX = (value) => mapLinearValue(value, minX, maxX, diagramLeft, diagramRight);
    const toDrawingY = (value) => mapLinearValue(value, minY, maxY, diagramTop, diagramBottom);

    drawPlanAxisSet(dxf, "x", xAxisEntries, minX, maxX, diagramLeft, diagramRight, diagramTop, diagramBottom, {
        bubbleScale: axisScale,
        bubbleRadius: SLAB_PLAN_AXIS_BUBBLE_RADIUS,
        bubbleOffset: SLAB_PLAN_AXIS_BUBBLE_OFFSET,
        axisLineScale: PLAN_DRAWING_AXIS_LINE_TYPE_SCALE,
        dimensionScale: dimensionVisualScale,
        bubbleTextSize: getPlanAnnotationTextHeight(),
        bubbleTextMinSize: getPlanAnnotationTextHeight(),
        dimensionTextHeight: elementLabelTextSize,
        dimensionOffset: SLAB_PLAN_AXIS_DIMENSION_OFFSET,
        dimensionOriginOffset: SLAB_PLAN_AXIS_DIMENSION_ORIGIN_OFFSET,
        architecturalDenominator
    });
    drawPlanAxisSet(dxf, "y", yAxisEntries, minY, maxY, diagramLeft, diagramRight, diagramTop, diagramBottom, {
        bubbleScale: axisScale,
        bubbleRadius: SLAB_PLAN_AXIS_BUBBLE_RADIUS,
        bubbleOffset: SLAB_PLAN_AXIS_BUBBLE_OFFSET,
        axisLineScale: PLAN_DRAWING_AXIS_LINE_TYPE_SCALE,
        dimensionScale: dimensionVisualScale,
        bubbleTextSize: getPlanAnnotationTextHeight(),
        bubbleTextMinSize: getPlanAnnotationTextHeight(),
        dimensionTextHeight: elementLabelTextSize,
        dimensionOffset: SLAB_PLAN_AXIS_DIMENSION_OFFSET,
        dimensionOriginOffset: SLAB_PLAN_AXIS_DIMENSION_ORIGIN_OFFSET,
        architecturalDenominator
    });

    const wallDrawingPreferences = getWallDrawingPreferences();
    const wallEntries = walls.map((wall) => {
        const wallLayer = wall.material === "masonry"
            ? "MAMPOSTERIA_MUROS"
            : CONCRETE_WALL_PLAN_OUTLINE_LAYER;
        const wallLabel = normalizeTextValue(wall.name) || getSmartEntityName("wall", wall) || translate("naming.wall");
        const connectedBounds = getConnectedWallPlanBounds(walls, wall);
        const left = toDrawingX(connectedBounds.left);
        const right = toDrawingX(connectedBounds.right);
        const bottom = toDrawingY(connectedBounds.bottom);
        const top = toDrawingY(connectedBounds.top);
        const rectLeft = Math.min(left, right);
        const rectRight = Math.max(left, right);
        const rectBottom = Math.min(bottom, top);
        const rectTop = Math.max(bottom, top);
        const rectWidth = Math.max(rectRight - rectLeft, 0.08 * labelScale);
        const rectHeight = Math.max(rectTop - rectBottom, 0.08 * labelScale);
        const orientation = connectedBounds.orientation || (rectWidth >= rectHeight ? "horizontal" : "vertical");
        const dimensionLeft = orientation === "horizontal"
            ? Math.min(toDrawingX(connectedBounds.dimensionStartValue), toDrawingX(connectedBounds.dimensionEndValue))
            : rectLeft;
        const dimensionRight = orientation === "horizontal"
            ? Math.max(toDrawingX(connectedBounds.dimensionStartValue), toDrawingX(connectedBounds.dimensionEndValue))
            : rectRight;
        const dimensionBottom = orientation === "vertical"
            ? Math.min(toDrawingY(connectedBounds.dimensionStartValue), toDrawingY(connectedBounds.dimensionEndValue))
            : rectBottom;
        const dimensionTop = orientation === "vertical"
            ? Math.max(toDrawingY(connectedBounds.dimensionStartValue), toDrawingY(connectedBounds.dimensionEndValue))
            : rectTop;
        const outline = orientation === "horizontal"
            ? {
                topStartX: connectedBounds.startConnection?.kind === "perpendicular"
                    ? toDrawingX(getWallPlanPerpendicularEdgeJoinValue(connectedBounds.startConnection, 1))
                    : rectLeft,
                bottomStartX: connectedBounds.startConnection?.kind === "perpendicular"
                    ? toDrawingX(getWallPlanPerpendicularEdgeJoinValue(connectedBounds.startConnection, -1))
                    : rectLeft,
                topEndX: connectedBounds.endConnection?.kind === "perpendicular"
                    ? toDrawingX(getWallPlanPerpendicularEdgeJoinValue(connectedBounds.endConnection, 1))
                    : rectRight,
                bottomEndX: connectedBounds.endConnection?.kind === "perpendicular"
                    ? toDrawingX(getWallPlanPerpendicularEdgeJoinValue(connectedBounds.endConnection, -1))
                    : rectRight
            }
            : {
                leftStartY: connectedBounds.startConnection?.kind === "perpendicular"
                    ? toDrawingY(getWallPlanPerpendicularEdgeJoinValue(connectedBounds.startConnection, -1))
                    : rectBottom,
                rightStartY: connectedBounds.startConnection?.kind === "perpendicular"
                    ? toDrawingY(getWallPlanPerpendicularEdgeJoinValue(connectedBounds.startConnection, 1))
                    : rectBottom,
                leftEndY: connectedBounds.endConnection?.kind === "perpendicular"
                    ? toDrawingY(getWallPlanPerpendicularEdgeJoinValue(connectedBounds.endConnection, -1))
                    : rectTop,
                rightEndY: connectedBounds.endConnection?.kind === "perpendicular"
                    ? toDrawingY(getWallPlanPerpendicularEdgeJoinValue(connectedBounds.endConnection, 1))
                    : rectTop
            };

        return {
            wall,
            wallLayer,
            wallLabel,
            labelKey: normalizeTextValue(wallLabel).toLowerCase(),
            connectedBounds,
            orientation,
            rectLeft,
            rectRight,
            rectBottom,
            rectTop,
            rectWidth,
            rectHeight,
            dimensionLeft,
            dimensionRight,
            dimensionBottom,
            dimensionTop,
            outline
        };
    });

    // Wall fills and contour lines are calculated from the geometric union of
    // the wall footprints. Doing this once per material removes interior edges
    // at T/L connections and guarantees that the corner itself is filled.
    const wallGeometryGroups = new Map();
    wallEntries.forEach((entry) => {
        const contour = getPlanWallFootprintContour(entry.wall, (vertex) => ({
            x: toDrawingX(vertex.x),
            y: toDrawingY(vertex.y)
        }), walls);
        if (!contour) {
            return;
        }
        const group = wallGeometryGroups.get(entry.wallLayer) || [];
        group.push({ entry, contour });
        wallGeometryGroups.set(entry.wallLayer, group);
    });

    wallGeometryGroups.forEach((group, wallLayer) => {
        const rectangular = group.filter(({ contour }) => Boolean(getSlabPlanConcreteWallContourRectangle(contour)));
        const nonRectangular = group.filter(({ contour }) => !getSlabPlanConcreteWallContourRectangle(contour));

        group.forEach(({ entry, contour }) => {
            if (entry.wall.material === "concrete") {
                addWallPlanConcreteWallHatch(dxf, contour.vertices);
            }
            if (wallLayer !== CONCRETE_WALL_PLAN_OUTLINE_LAYER) {
                addFilledQuadrilateral(dxf, wallLayer, contour.vertices);
            }
        });
        getSlabPlanConcreteWallUnionBoundarySegments(rectangular.map(({ contour }) => contour))
            .forEach((segment) => addLine(dxf, wallLayer, segment.x1, segment.y1, segment.x2, segment.y2));
        nonRectangular.forEach(({ contour }) => {
            getPolygonSegments(contour.vertices).forEach((segment) => {
                addLine(dxf, wallLayer, segment.x1, segment.y1, segment.x2, segment.y2);
            });
        });
    });

    const renderedLabelGroups = new Set();

    wallEntries.forEach((entry, index) => {
        drawPlanViewRectDimensions(
            dxf,
            entry.dimensionLeft,
            entry.dimensionRight,
            entry.dimensionBottom,
            entry.dimensionTop,
            {
                visualScale: dimensionVisualScale,
                textHeight: elementLabelTextSize,
                architecturalDenominator,
                xLabel: entry.orientation === "vertical"
                    ? formatPlanViewDimensionValue(entry.connectedBounds.right - entry.connectedBounds.left)
                    : formatPlanViewDimensionValue(entry.connectedBounds.dimensionEndValue - entry.connectedBounds.dimensionStartValue),
                yLabel: entry.orientation === "vertical"
                    ? formatPlanViewDimensionValue(entry.connectedBounds.dimensionEndValue - entry.connectedBounds.dimensionStartValue)
                    : formatPlanViewDimensionValue(entry.connectedBounds.top - entry.connectedBounds.bottom),
                ...getWallPlanDimensionPlacementOptions(entry)
            }
        );

        const labelGroupKey = `${entry.labelKey}|${getConnectedWallPlanLabelGroupKey(wallEntries, index)}`;
        if (renderedLabelGroups.has(labelGroupKey)) {
            return;
        }
        renderedLabelGroups.add(labelGroupKey);

        drawOutsideWallPlanLabel(
            dxf,
            entry.wallLabel,
            entry.rectLeft,
            entry.rectLeft + entry.rectWidth,
            entry.rectBottom,
            entry.rectBottom + entry.rectHeight,
            entry.rectWidth >= entry.rectHeight ? "horizontal" : "vertical",
            diagramLeft,
            diagramRight,
            diagramBottom,
            diagramTop,
            labelScale,
            { textSize: elementLabelTextSize }
        );
    });

    return diagramBottom - layout.returnGap;
}

/* SERVER_ONLY_END */

function drawColumnDetailPreview(selection) {
    const level = getExportLevelFromSelection(selection);
    drawStandaloneDetailPreview(
        buildColumnDetailEntries(level),
        `Columnas | ${level?.name || ""}`,
        drawColumnPreviewCard,
        { preferredHeight: 290 }
    );
}

function drawWallDetailPreview(selection) {
    const level = getExportLevelFromSelection(selection);
    drawStandaloneDetailPreview(
        buildWallDetailEntries(level),
        `Muros | ${level?.name || ""}`,
        drawWallPreviewCard,
        { preferredHeight: 340 }
    );
}

function drawStandaloneDetailPreview(entries, title, drawCard, options = {}) {
    const previewContext = dom.previewCanvas.getContext("2d");
    dom.previewCanvas.width = dom.previewCanvas.clientWidth;
    dom.previewCanvas.height = dom.previewCanvas.clientHeight;
    previewContext.clearRect(0, 0, dom.previewCanvas.width, dom.previewCanvas.height);
    previewContext.fillStyle = "#0d1218";
    previewContext.fillRect(0, 0, dom.previewCanvas.width, dom.previewCanvas.height);
    previewContext.fillStyle = "#f3f7fb";
    previewContext.font = '16px "Segoe UI", sans-serif';
    previewContext.fillText(title, 28, 34);

    if (!entries.length) {
        previewContext.font = '14px "Segoe UI", sans-serif';
        previewContext.fillText("Vacío", 28, 64);
        return;
    }

    const padding = 28;
    const topOffset = 56;
    const gap = 18;
    const preferredWidth = options.preferredWidth ?? 250;
    const preferredHeight = options.preferredHeight ?? 260;
    const availableWidth = dom.previewCanvas.width - padding * 2;
    const columns = Math.max(1, Math.floor((availableWidth + gap) / (preferredWidth + gap)));
    const cardWidth = (availableWidth - gap * (columns - 1)) / columns;

    entries.forEach((entry, index) => {
        const columnIndex = index % columns;
        const rowIndex = Math.floor(index / columns);
        const x = padding + columnIndex * (cardWidth + gap);
        const y = topOffset + rowIndex * (preferredHeight + gap);
        drawCard(previewContext, entry, x, y, cardWidth, preferredHeight);
    });
}

function drawDetailPreviewCardFrame(context, x, y, width, height, title, subtitle) {
    context.save();
    context.fillStyle = "#f8fafc";
    context.strokeStyle = "rgba(203, 213, 225, 0.65)";
    context.lineWidth = 1.2;
    context.beginPath();
    addRoundedRectPath(context, x, y, width, height, 12);
    context.fill();
    context.stroke();
    context.fillStyle = "#17202a";
    context.font = '13px "Segoe UI", sans-serif';
    context.fillText(title, x + 14, y + 20);
    context.fillStyle = "#5f6b78";
    context.font = '11px "Segoe UI", sans-serif';
    context.fillText(subtitle, x + 14, y + 38);
    context.restore();
}

function addRoundedRectPath(context, x, y, width, height, radius) {
    if (typeof context.roundRect === "function") {
        context.roundRect(x, y, width, height, radius);
        return;
    }

    const safeRadius = Math.max(0, Math.min(radius, width / 2, height / 2));
    context.moveTo(x + safeRadius, y);
    context.lineTo(x + width - safeRadius, y);
    context.quadraticCurveTo(x + width, y, x + width, y + safeRadius);
    context.lineTo(x + width, y + height - safeRadius);
    context.quadraticCurveTo(x + width, y + height, x + width - safeRadius, y + height);
    context.lineTo(x + safeRadius, y + height);
    context.quadraticCurveTo(x, y + height, x, y + height - safeRadius);
    context.lineTo(x, y + safeRadius);
    context.quadraticCurveTo(x, y, x + safeRadius, y);
    context.closePath();
}

function getColumnSectionDetailBoxSize(detail) {
    const column = detail.column || detail;
    const columnWidthMeters = Math.max(getColumnWidth(column), 0.01);
    const columnHeightMeters = Math.max(getColumnHeight(column), 0.01);

    // La geometria de la seccion debe respetar siempre la escala global.
    // Antes se forzaba un minimo de 1.20, haciendo que columnas pequeñas
    // como 0.15 x 0.15 m se dibujaran a una escala efectiva distinta.
    const sectionWidth = columnWidthMeters * COLUMN_SECTION_DETAIL_SCALE;
    const sectionHeight = columnHeightMeters * COLUMN_SECTION_DETAIL_SCALE;
    const sectionScaleX = COLUMN_SECTION_DETAIL_SCALE;
    const sectionScaleY = COLUMN_SECTION_DETAIL_SCALE;

    // Solo la caja de layout conserva un minimo para textos/cotas, sin escalar la seccion.
    const layoutSectionWidth = Math.max(sectionWidth, 1.2);
    const layoutSectionHeight = Math.max(sectionHeight, 1.2);
    const explodedStirrupCount = getColumnExplodedStirrupPieceCount(column, sectionWidth, sectionHeight);
    const explodedStirrupColumns = Math.max(Math.ceil(explodedStirrupCount / 2), 1);
    const explodedStirrupPanelWidth = 1.35 + explodedStirrupColumns * (Math.max(layoutSectionWidth, layoutSectionHeight) + 0.85);

    return {
        sectionWidth,
        sectionHeight,
        sectionScaleX,
        sectionScaleY,
        width: Math.max(layoutSectionWidth + 3.0, sectionWidth + explodedStirrupPanelWidth, 6.0),
        height: Math.max(layoutSectionHeight + 3.5, Math.min(Math.max(explodedStirrupCount, 1), 3) * 1.9 + 2.6, 6.4)
    };
}

function getDirectedLayoutPositions(count, start, end, inset) {
    const direction = Math.sign(end - start) || 1;
    const clearStart = start + direction * inset;
    const clearEnd = end - direction * inset;

    if (count <= 1 || Math.abs(clearEnd - clearStart) <= 0.01) {
        return [(start + end) / 2];
    }

    return Array.from({ length: count }, (_, index) => (
        clearStart + ((clearEnd - clearStart) * index) / (count - 1)
    ));
}

function getColumnBarPositions(longRebar, left, bottom, right, top, radiusForDiameter = getRebarDrawRadius) {
    const normalized = normalizeColumnLongitudinalRebar(longRebar);
    if (normalized.layout === "circular") {
        const centerX = (left + right) / 2;
        const centerY = (bottom + top) / 2;
        const outerRadius = Math.min(Math.abs(right - left), Math.abs(top - bottom)) / 2;
        return getCircularColumnBarPositions(normalized, centerX, centerY, outerRadius, radiusForDiameter);
    }
    const cornerRadius = radiusForDiameter(normalized.cornerDiameter);
    const xRadius = radiusForDiameter(normalized.xDiameter);
    const yRadius = radiusForDiameter(normalized.yDiameter);
    const maxRadius = Math.max(cornerRadius, xRadius, yRadius);
    const minimumInset = Math.min(Math.abs(right - left), Math.abs(bottom - top)) * 0.08;
    const inset = Math.max(maxRadius * 1.6, minimumInset);
    const xPositions = getDirectedLayoutPositions(normalized.xCount, left, right, inset);
    const yPositions = getDirectedLayoutPositions(normalized.yCount, bottom, top, inset);
    const topY = yPositions[yPositions.length - 1];
    const bottomY = yPositions[0];
    const leftX = xPositions[0];
    const rightX = xPositions[xPositions.length - 1];
    const barMap = new Map();
    const registerBar = (x, y, diameter, radius, role) => {
        const key = `${x.toFixed(4)}|${y.toFixed(4)}`;
        barMap.set(key, { x, y, diameter, radius, role });
    };

    xPositions.forEach((x, index) => {
        const isCorner = index === 0 || index === xPositions.length - 1;
        registerBar(
            x,
            topY,
            isCorner ? normalized.cornerDiameter : normalized.xDiameter,
            isCorner ? cornerRadius : xRadius,
            isCorner ? "corner" : "x"
        );
        registerBar(
            x,
            bottomY,
            isCorner ? normalized.cornerDiameter : normalized.xDiameter,
            isCorner ? cornerRadius : xRadius,
            isCorner ? "corner" : "x"
        );
    });

    yPositions.slice(1, -1).forEach((y) => {
        registerBar(leftX, y, normalized.yDiameter, yRadius, "y");
        registerBar(rightX, y, normalized.yDiameter, yRadius, "y");
    });

    return Array.from(barMap.values()).sort((a, b) => {
        if (Math.abs(a.y - b.y) > 0.0001) {
            return b.y - a.y;
        }
        return a.x - b.x;
    });
}

function getCircularColumnBarPositions(longRebar, centerX, centerY, outerRadius, radiusForDiameter = getRebarDrawRadius) {
    const normalized = normalizeColumnLongitudinalRebar(longRebar, { sectionShape: COLUMN_SECTION_SHAPE_CIRCULAR });
    const barCount = getTotalColumnBarCount(normalized);
    const barRadius = radiusForDiameter(normalized.diameter || normalized.xDiameter || normalized.cornerDiameter);
    const barCenterRadius = Math.max(parsePositiveNumberOrFallback(outerRadius, 0, 0) - barRadius * 1.8, 0.01);
    return Array.from({ length: barCount }, (_, index) => {
        const angle = (Math.PI * 2 * index) / barCount - Math.PI / 2;
        return {
            x: centerX + Math.cos(angle) * barCenterRadius,
            y: centerY + Math.sin(angle) * barCenterRadius,
            diameter: normalized.diameter,
            radius: barRadius,
            role: "circular"
        };
    });
}

function getColumnSectionClearCover(stirrups) {
    return Math.max(parsePositiveNumberOrFallback(stirrups?.cover, DRAWING_COVER, 0.01), 0.01);
}

function getColumnSectionDetailScaleX(detailSize, column) {
    const columnWidthMeters = Math.max(getColumnWidth(column), 0.01);
    const sectionWidth = Math.max(
        parsePositiveNumberOrFallback(detailSize?.sectionWidth, columnWidthMeters * COLUMN_SECTION_DETAIL_SCALE, 0.001),
        0.001
    );
    return Math.max(sectionWidth / columnWidthMeters, 0.001);
}

function getColumnSectionDetailScaleY(detailSize, column) {
    const columnHeightMeters = Math.max(getColumnHeight(column), 0.01);
    const sectionHeight = Math.max(
        parsePositiveNumberOrFallback(detailSize?.sectionHeight, columnHeightMeters * COLUMN_SECTION_DETAIL_SCALE, 0.001),
        0.001
    );
    return Math.max(sectionHeight / columnHeightMeters, 0.001);
}

function getColumnRealDimensionValueFromDrawnLength(drawnLength, drawingScale) {
    const safeScale = Math.max(parsePositiveNumberOrFallback(drawingScale, COLUMN_SECTION_DETAIL_SCALE, 0.001), 0.001);
    return Math.max(Math.abs(parseNumberOrFallback(drawnLength, 0)) / safeScale, 0);
}

function formatColumnCalculatedDimension(value, decimals = 2) {
    return Math.max(parseNumberOrFallback(value, 0), 0).toFixed(decimals);
}

function formatColumnRealDimensionFromDrawnLength(drawnLength, drawingScale, decimals = 2) {
    return formatColumnCalculatedDimension(
        getColumnRealDimensionValueFromDrawnLength(drawnLength, drawingScale),
        decimals
    );
}

function getColumnSectionDimensionVisualScale(sectionScaleX, sectionScaleY) {
    const baseScale = Math.min(
        Math.max(parsePositiveNumberOrFallback(sectionScaleX, COLUMN_SECTION_DETAIL_SCALE, 0.001), 0.001),
        Math.max(parsePositiveNumberOrFallback(sectionScaleY, COLUMN_SECTION_DETAIL_SCALE, 0.001), 0.001)
    ) / COLUMN_SECTION_DETAIL_SCALE;
    return Math.min(Math.max(baseScale, 0.75), 1.35);
}

function getColumnStirrupDrawRadius(stirrups, drawingScale = COLUMN_SECTION_DETAIL_SCALE) {
    const normalized = normalizeTransverseRebar(stirrups, DEFAULT_COLUMN_TIE_SPACING);
    const diameterMeters = Math.max(parseDiameterInMeters(normalized.d), 0.001);
    const safeScale = Math.max(parsePositiveNumberOrFallback(drawingScale, COLUMN_SECTION_DETAIL_SCALE, 0.001), 0.001);

    return Math.max((diameterMeters * safeScale) / 2, 0.001);
}

function getColumnLongitudinalDrawRadius(diameterLabel, drawingScale = COLUMN_SECTION_DETAIL_SCALE) {
    const diameterMeters = Math.max(parseDiameterInMeters(diameterLabel), 0.001);
    const safeScale = Math.max(parsePositiveNumberOrFallback(drawingScale, COLUMN_SECTION_DETAIL_SCALE, 0.001), 0.001);

    // Para columnas no se usa el minimo visual de getRebarDrawRadius(),
    // porque ese minimo fue pensado para legibilidad en otros detalles y
    // hace que barras pequenas, por ejemplo 3/8", se vean demasiado grandes
    // dentro de secciones pequenas como 0.15 x 0.15 m.
    return Math.max((diameterMeters * safeScale) / 2, 0.001);
}

function expandColumnConfinementBoundsToStirrupExterior(bounds, barRadius = DXF_STIRRUP_2D_RADIUS) {
    if (!bounds) {
        return null;
    }

    const exteriorOffset = Math.max(parsePositiveNumberOrFallback(barRadius, DXF_STIRRUP_2D_RADIUS, 0.001), 0.001);
    return {
        left: bounds.left - exteriorOffset,
        right: bounds.right + exteriorOffset,
        bottom: bounds.bottom - exteriorOffset,
        top: bounds.top + exteriorOffset
    };
}

function getColumnConfinementPieceRealMeasure(piece, scaleX, scaleY, barRadius = DXF_STIRRUP_2D_RADIUS) {
    const bounds = getColumnConfinementPieceMeasureBounds(piece, { barRadius });
    if (!bounds) {
        return null;
    }

    return {
        bounds,
        width: getColumnRealDimensionValueFromDrawnLength(bounds.right - bounds.left, scaleX),
        height: getColumnRealDimensionValueFromDrawnLength(bounds.top - bounds.bottom, scaleY)
    };
}

function getColumnExplodedStirrupPieceCount(column, sectionWidth, sectionHeight) {
    const longRebar = normalizeColumnLongitudinalRebar(column?.longRebar ?? column?.longitudinalRebar);
    const stirrups = ensureColumnTransverseRebar(column, longRebar);
    const clearCover = getColumnSectionClearCover(stirrups);
    const sectionScaleX = sectionWidth / Math.max(getColumnWidth(column), 0.01);
    const sectionScaleY = sectionHeight / Math.max(getColumnHeight(column), 0.01);
    const coverX = Math.min(clearCover * sectionScaleX, Math.max(sectionWidth / 2 - 0.06, 0.04));
    const coverY = Math.min(clearCover * sectionScaleY, Math.max(sectionHeight / 2 - 0.06, 0.04));
    const left = coverX;
    const bottom = coverY;
    const right = sectionWidth - coverX;
    const top = sectionHeight - coverY;

    if (!(right > left && top > bottom)) {
        return 1;
    }

    const layout = getColumnConfinementLayout(stirrups, longRebar, left, bottom, right, top);
    const barPositions = getColumnBarPositions(
        longRebar,
        left,
        bottom,
        right,
        top,
        (diameter) => getColumnLongitudinalDrawRadius(diameter, COLUMN_SECTION_DETAIL_SCALE)
    );

    return Math.max(
        getColumnConfinementPieces(layout, barPositions).pieces.filter((piece) => (
            Array.isArray(piece?.segments) && piece.segments.length > 0
        )).length,
        1
    );
}

function getColumnConfinementLayout(stirrups, longRebar, left, bottom, right, top) {
    const normalizedStirrups = normalizeColumnTransverseRebar(stirrups, longRebar);
    const spanX = Math.abs((right ?? 0) - (left ?? 0));
    const spanY = Math.abs((top ?? 0) - (bottom ?? 0));
    const controllingSpan = Math.min(spanX, spanY);
    const hookLength = Math.min(
        Math.max(controllingSpan * 0.18, 0.025),
        Math.max(controllingSpan * 0.25, 0.01)
    );

    return {
        outer: { left, bottom, right, top },
        confX: Math.max(Number.parseInt(normalizedStirrups.count3Dir, 10) || 0, 0),
        confY: Math.max(Number.parseInt(normalizedStirrups.count2Dir, 10) || 0, 0),
        hookLength
    };
}

function createColumnConfinementSegment(x1, y1, x2, y2) {
    return { x1, y1, x2, y2 };
}

function getColumnConfinementEvenlySpacedPositions(start, end, count) {
    const normalizedCount = Math.max(Number.parseInt(count, 10) || 0, 0);
    if (normalizedCount <= 0) {
        return [];
    }

    const length = end - start;
    const step = length / (normalizedCount + 1);
    return Array.from({ length: normalizedCount }, (_, index) => start + step * (index + 1));
}

function createColumnConfinementHookSegment(x, y, directionX, directionY, hookLength) {
    const length = Math.max(parsePositiveNumberOrFallback(hookLength, 0.1, 0.01), 0.01);
    const delta = length / Math.sqrt(2);
    return createColumnConfinementSegment(
        x,
        y,
        x + directionX * delta,
        y + directionY * delta
    );
}

function createFrameSectionTangentHookSegment(x, y, directionX, directionY, hookLength, tangentDirectionX, tangentDirectionY) {
    const segment = createColumnConfinementHookSegment(x, y, directionX, directionY, hookLength);
    return {
        ...segment,
        kind: "frame-section-tangent-hook",
        tangentDirectionX,
        tangentDirectionY
    };
}

function getColumnConfinementInternalDistribution(totalCount) {
    const normalizedCount = Math.max(Number.parseInt(totalCount, 10) || MIN_COLUMN_CONFINEMENT_COUNT, MIN_COLUMN_CONFINEMENT_COUNT);
    const remainingLines = Math.max(normalizedCount - MIN_COLUMN_CONFINEMENT_COUNT, 0);

    return {
        totalCount: normalizedCount,
        remainingLines,
        rectangleCount: Math.floor(remainingLines / 2),
        lineCount: remainingLines % 2
    };
}

function createColumnConfinementRectangleSegments(left, bottom, right, top, hookLength = 0, hookPlacement = {}) {
    const segments = [
        createColumnConfinementSegment(left, bottom, right, bottom),
        createColumnConfinementSegment(right, bottom, right, top),
        createColumnConfinementSegment(right, top, left, top),
        createColumnConfinementSegment(left, top, left, bottom)
    ];
    const normalizedHookLength = Math.max(parsePositiveNumberOrFallback(hookLength, 0, 0), 0);
    if (normalizedHookLength <= 0) {
        return segments;
    }

    const isRightAnchor = hookPlacement.anchor === "right";
    const isBottomAnchor = hookPlacement.edge === "bottom";
    const horizontalAxisDirection = Math.sign(right - left) || 1;
    const verticalAxisDirection = Math.sign(bottom - top) || 1;
    const cornerX = isRightAnchor ? right : left;
    const cornerY = isBottomAnchor ? bottom : top;
    const inwardX = isRightAnchor ? -horizontalAxisDirection : horizontalAxisDirection;
    const inwardY = isBottomAnchor ? -verticalAxisDirection : verticalAxisDirection;
    const lineOffset = Math.max(
        Math.min(normalizedHookLength * 0.4, Math.abs(right - left) * 0.2, Math.abs(bottom - top) * 0.2),
        0.02
    );

    segments.push(
        // The top/bottom-side hook leaves the outer horizontal stirrup line and
        // transitions tangentially into its 45-degree tail.
        createFrameSectionTangentHookSegment(
            cornerX + inwardX * lineOffset,
            cornerY,
            inwardX,
            inwardY,
            normalizedHookLength,
            inwardX,
            0
        ),
        // The adjacent hook starts tangent to the outer vertical stirrup line
        // and finishes in the same diagonal direction.
        createFrameSectionTangentHookSegment(
            cornerX,
            cornerY + inwardY * lineOffset,
            inwardX,
            inwardY,
            normalizedHookLength,
            0,
            inwardY
        )
    );

    return segments;
}

function getColumnConfinementAxisProfiles(barPositions, axis, start, end) {
    const normalizedBars = Array.isArray(barPositions) ? barPositions : [];
    return getColumnConfinementAxisSort(
        getColumnConfinementUniqueBarAxisValues(normalizedBars, axis),
        start,
        end
    ).map((value) => ({
        value,
        radius: normalizedBars.reduce((maxRadius, bar) => (
            Math.abs((bar?.[axis] ?? Number.NaN) - value) <= 0.0001
                ? Math.max(maxRadius, parsePositiveNumberOrFallback(bar?.radius, 0, 0))
                : maxRadius
        ), 0)
    }));
}

function getColumnConfinementInternalAxisProfiles(axisProfiles) {
    return (Array.isArray(axisProfiles) ? axisProfiles : []).slice(1, -1);
}

function getColumnConfinementBarClearance(radius, hookLength) {
    const normalizedRadius = Math.max(parsePositiveNumberOrFallback(radius, 0, 0), 0);
    return Math.max(normalizedRadius * 0.18, hookLength * 0.08, 0.01);
}

function getColumnConfinementCoordinateBesideBar(value, radius, direction, hookLength) {
    const normalizedDirection = Math.sign(direction) || 1;
    return value + normalizedDirection * (
        Math.max(parsePositiveNumberOrFallback(radius, 0, 0), 0)
        + getColumnConfinementBarClearance(radius, hookLength)
    );
}

function getColumnConfinementBoundaryNearBar(selectedValue, adjacentValue, radius = 0, hookLength = 0) {
    return getColumnConfinementCoordinateBesideBar(
        selectedValue,
        radius,
        Math.sign((adjacentValue ?? selectedValue) - selectedValue) || 1,
        hookLength
    );
}

function getColumnConfinementBodyAnchorPastBar(selectedValue, adjacentValue, radius = 0, hookLength = 0) {
    const normalizedRadius = Math.max(parsePositiveNumberOrFallback(radius, 0, 0), 0);
    const direction = Math.sign((adjacentValue ?? selectedValue) - selectedValue) || 1;
    return getColumnConfinementCoordinateBesideBar(selectedValue, normalizedRadius, direction, hookLength)
        + direction * normalizedRadius * 2;
}

function getColumnConfinementAdjacentPairStartIndexes(internalCount, pairCount) {
    const normalizedInternalCount = Math.max(Number.parseInt(internalCount, 10) || 0, 0);
    const normalizedPairCount = Math.min(
        Math.max(Number.parseInt(pairCount, 10) || 0, 0),
        Math.floor(normalizedInternalCount / 2)
    );

    if (normalizedInternalCount < 2 || normalizedPairCount <= 0) {
        return [];
    }

    const slack = normalizedInternalCount - (normalizedPairCount * 2);
    const gapCount = normalizedPairCount + 1;
    const baseGap = Math.floor(slack / gapCount);
    const extraGapIndexes = getColumnConfinementDistributedIndexes(gapCount, slack % gapCount);
    const gaps = Array.from({ length: gapCount }, (_, index) => (
        baseGap + (extraGapIndexes.includes(index) ? 1 : 0)
    ));
    const starts = [];
    let cursor = gaps[0];

    for (let index = 0; index < normalizedPairCount; index += 1) {
        starts.push(cursor);
        cursor += 2 + gaps[index + 1];
    }

    return starts;
}

function getColumnConfinementNestedBandBounds(axisValues, pairStartIndex, hookLength = 0) {
    const values = Array.isArray(axisValues) ? axisValues : [];
    const internalValues = getColumnConfinementInternalAxisProfiles(values);
    const normalizedPairStartIndex = Math.max(Number.parseInt(pairStartIndex, 10) || 0, 0);

    if (values.length < 4 || normalizedPairStartIndex + 1 >= internalValues.length) {
        return null;
    }

    const leadingProfile = internalValues[normalizedPairStartIndex];
    const trailingProfile = internalValues[normalizedPairStartIndex + 1];
    const start = getColumnConfinementBoundaryNearBar(
        leadingProfile.value,
        values[normalizedPairStartIndex]?.value,
        leadingProfile.radius,
        hookLength
    );
    const end = getColumnConfinementBoundaryNearBar(
        trailingProfile.value,
        values[normalizedPairStartIndex + 3]?.value,
        trailingProfile.radius,
        hookLength
    );
    if (!Number.isFinite(start) || !Number.isFinite(end) || Math.abs(end - start) <= 0.0001) {
        return null;
    }

    return {
        pairStartIndex: normalizedPairStartIndex,
        usedInternalIndexes: [normalizedPairStartIndex, normalizedPairStartIndex + 1],
        start,
        end
    };
}

function getColumnConfinementNestedBandLoops(axisValues, rectangleCount, hookLength = 0) {
    const internalValues = getColumnConfinementInternalAxisProfiles(axisValues);
    return getColumnConfinementAdjacentPairStartIndexes(internalValues.length, rectangleCount).map((pairStartIndex) => (
        getColumnConfinementNestedBandBounds(axisValues, pairStartIndex, hookLength)
    )).filter(Boolean);
}

function getColumnConfinementSelectedInternalAxisValues(axisValues, selectionCount, excludedInternalIndexes = []) {
    const internalValues = getColumnConfinementInternalAxisProfiles(axisValues);
    const excludedSet = new Set(
        (Array.isArray(excludedInternalIndexes) ? excludedInternalIndexes : [])
            .map((index) => Number.parseInt(index, 10))
            .filter((index) => Number.isFinite(index) && index >= 0)
    );
    const preferredValues = internalValues.filter((_, index) => !excludedSet.has(index));
    const candidateValues = preferredValues.length ? preferredValues : internalValues;

    return getColumnConfinementDistributedIndexes(candidateValues.length, selectionCount).map((index) => candidateValues[index]);
}

function getColumnConfinementPieces(layout, barPositions = []) {
    const outer = layout?.outer || {};
    const left = outer.left ?? 0;
    const right = outer.right ?? 0;
    const bottom = outer.bottom ?? 0;
    const top = outer.top ?? 0;
    const width = Math.abs(right - left);
    const height = Math.abs(top - bottom);
    const confX = Math.max(Number.parseInt(layout?.confX, 10) || 0, 0);
    const confY = Math.max(Number.parseInt(layout?.confY, 10) || 0, 0);
    const hookLength = Math.max(parsePositiveNumberOrFallback(layout?.hookLength, 0.1, 0.01), 0.01);
    const xDirection = Math.sign(right - left) || 1;
    const yDirection = Math.sign(top - bottom) || 1;
    const centerX = (left + right) / 2;
    const centerY = (top + bottom) / 2;
    const confXDistribution = getColumnConfinementInternalDistribution(confX);
    const confYDistribution = getColumnConfinementInternalDistribution(confY);
    const remX = confXDistribution.remainingLines;
    const remY = confYDistribution.remainingLines;
    const pieces = [];
    const hasBarAnchors = Array.isArray(barPositions) && barPositions.length > 0;
    const xAxisProfiles = hasBarAnchors
        ? getColumnConfinementAxisProfiles(barPositions, "x", left, right)
        : [];
    const yAxisProfiles = hasBarAnchors
        ? getColumnConfinementAxisProfiles(barPositions, "y", top, bottom)
        : [];
    const topOuterProfile = yAxisProfiles[0] ?? null;
    const bottomOuterProfile = yAxisProfiles[yAxisProfiles.length - 1] ?? null;
    const leftOuterProfile = xAxisProfiles[0] ?? null;
    const rightOuterProfile = xAxisProfiles[xAxisProfiles.length - 1] ?? null;
    const anchoredTop = topOuterProfile
        ? getColumnConfinementBoundaryNearBar(topOuterProfile.value, top, topOuterProfile.radius, hookLength)
        : top;
    const anchoredBottom = bottomOuterProfile
        ? getColumnConfinementBoundaryNearBar(bottomOuterProfile.value, bottom, bottomOuterProfile.radius, hookLength)
        : bottom;
    const anchoredLeft = leftOuterProfile
        ? getColumnConfinementBoundaryNearBar(leftOuterProfile.value, left, leftOuterProfile.radius, hookLength)
        : left;
    const anchoredRight = rightOuterProfile
        ? getColumnConfinementBoundaryNearBar(rightOuterProfile.value, right, rightOuterProfile.radius, hookLength)
        : right;
    const lineAnchoredTop = topOuterProfile
        ? getColumnConfinementBodyAnchorPastBar(topOuterProfile.value, top, topOuterProfile.radius, hookLength)
        : anchoredTop;
    const lineAnchoredBottom = bottomOuterProfile
        ? getColumnConfinementBodyAnchorPastBar(bottomOuterProfile.value, bottom, bottomOuterProfile.radius, hookLength)
        : anchoredBottom;
    const lineAnchoredLeft = leftOuterProfile
        ? getColumnConfinementBodyAnchorPastBar(leftOuterProfile.value, left, leftOuterProfile.radius, hookLength)
        : anchoredLeft;
    const lineAnchoredRight = rightOuterProfile
        ? getColumnConfinementBodyAnchorPastBar(rightOuterProfile.value, right, rightOuterProfile.radius, hookLength)
        : anchoredRight;
    const verticalAnchorTop = topOuterProfile?.value ?? anchoredTop;
    const verticalAnchorBottom = bottomOuterProfile?.value ?? anchoredBottom;
    const horizontalAnchorLeft = leftOuterProfile?.value ?? anchoredLeft;
    const horizontalAnchorRight = rightOuterProfile?.value ?? anchoredRight;
    const horizontalBandLoops = hasBarAnchors
        ? getColumnConfinementNestedBandLoops(yAxisProfiles, confXDistribution.rectangleCount, hookLength)
        : [];
    const verticalBandLoops = hasBarAnchors
        ? getColumnConfinementNestedBandLoops(xAxisProfiles, confYDistribution.rectangleCount, hookLength)
        : [];
    const horizontalBandUsedInternalIndexes = horizontalBandLoops.flatMap((loop) => loop.usedInternalIndexes || []);
    const verticalBandUsedInternalIndexes = verticalBandLoops.flatMap((loop) => loop.usedInternalIndexes || []);
    const horizontalCrosstieProfiles = hasBarAnchors
        ? getColumnConfinementSelectedInternalAxisValues(yAxisProfiles, confXDistribution.lineCount, horizontalBandUsedInternalIndexes)
        : getColumnConfinementEvenlySpacedPositions(top, bottom, confXDistribution.lineCount);
    const verticalCrosstieProfiles = hasBarAnchors
        ? getColumnConfinementSelectedInternalAxisValues(xAxisProfiles, confYDistribution.lineCount, verticalBandUsedInternalIndexes)
        : getColumnConfinementEvenlySpacedPositions(left, right, confYDistribution.lineCount);

    if (width <= 0.0001 || height <= 0.0001) {
        return {
            input: { width, height, cover: 0, confX, confY, hookLength },
            derived: { remX, remY, xMin: left, xMax: right, yMin: bottom, yMax: top },
            pieces
        };
    }

    pieces.push({
        type: "closed_outer_stirrup",
        segments: createColumnConfinementRectangleSegments(anchoredLeft, anchoredBottom, anchoredRight, anchoredTop, hookLength),
        contributes: { x: 2, y: 2 }
    });

    horizontalBandLoops.forEach((loop) => {
        pieces.push({
            type: "horizontal_inner_stirrup",
            segments: createColumnConfinementRectangleSegments(anchoredLeft, loop.end, anchoredRight, loop.start, hookLength),
            contributes: { x: 2, y: 0 },
            axis: "x",
            pairStartIndex: loop.pairStartIndex
        });
    });

    horizontalCrosstieProfiles.forEach((profile) => {
        const yValue = typeof profile === "number" ? profile : profile?.value;
        const yRadius = typeof profile === "number" ? 0 : profile?.radius;
        const hookSideY = Math.sign(centerY - yValue) || (Math.sign(bottom - top) || 1);
        const y = getColumnConfinementCoordinateBesideBar(yValue, yRadius, hookSideY, hookLength);
        const hookTowardsBarY = -hookSideY;
        const leftHookDirectionX = Math.sign(centerX - horizontalAnchorLeft) || xDirection;
        const rightHookDirectionX = Math.sign(centerX - horizontalAnchorRight) || -xDirection;
        pieces.push({
            type: "horizontal_crosstie",
            segments: [
                createColumnConfinementSegment(lineAnchoredLeft, y, lineAnchoredRight, y),
                createFrameSectionTangentHookSegment(
                    lineAnchoredLeft,
                    y,
                    leftHookDirectionX,
                    hookTowardsBarY,
                    hookLength,
                    -xDirection,
                    0
                ),
                createFrameSectionTangentHookSegment(
                    lineAnchoredRight,
                    y,
                    rightHookDirectionX,
                    hookTowardsBarY,
                    hookLength,
                    xDirection,
                    0
                )
            ],
            contributes: { x: 1, y: 0 },
            axis: "x",
            y
        });
    });

    verticalBandLoops.forEach((loop) => {
        pieces.push({
            type: "vertical_inner_stirrup",
            segments: createColumnConfinementRectangleSegments(loop.start, anchoredBottom, loop.end, anchoredTop, hookLength),
            contributes: { x: 0, y: 2 },
            axis: "y",
            pairStartIndex: loop.pairStartIndex
        });
    });

    verticalCrosstieProfiles.forEach((profile) => {
        const xValue = typeof profile === "number" ? profile : profile?.value;
        const xRadius = typeof profile === "number" ? 0 : profile?.radius;
        const hookSideX = Math.sign(centerX - xValue) || xDirection;
        const x = getColumnConfinementCoordinateBesideBar(xValue, xRadius, hookSideX, hookLength);
        const hookTowardsBarX = -hookSideX;
        const bottomHookDirectionY = Math.sign(centerY - verticalAnchorBottom) || yDirection;
        const topHookDirectionY = Math.sign(centerY - verticalAnchorTop) || -yDirection;
        pieces.push({
            type: "vertical_crosstie",
            segments: [
                createColumnConfinementSegment(x, lineAnchoredBottom, x, lineAnchoredTop),
                createFrameSectionTangentHookSegment(
                    x,
                    lineAnchoredBottom,
                    hookTowardsBarX,
                    bottomHookDirectionY,
                    hookLength,
                    0,
                    -yDirection
                ),
                createFrameSectionTangentHookSegment(
                    x,
                    lineAnchoredTop,
                    hookTowardsBarX,
                    topHookDirectionY,
                    hookLength,
                    0,
                    yDirection
                )
            ],
            contributes: { x: 0, y: 1 },
            axis: "y",
            x
        });
    });

    return {
        input: {
            width,
            height,
            cover: 0,
            confX,
            confY,
            hookLength
        },
        derived: {
            remX,
            remY,
            rectX: horizontalBandLoops.length,
            rectY: verticalBandLoops.length,
            lineX: horizontalCrosstieProfiles.length,
            lineY: verticalCrosstieProfiles.length,
            xMin: anchoredLeft,
            xMax: anchoredRight,
            yMin: anchoredBottom,
            yMax: anchoredTop
        },
        pieces
    };
}

function getColumnConfinementAxisSort(values, start, end) {
    const direction = Math.sign(end - start) || 1;
    return [...values].sort((leftValue, rightValue) => direction * (leftValue - rightValue));
}

function getColumnConfinementUniqueBarAxisValues(barPositions, axis) {
    const sortedValues = getColumnConfinementAxisSort(
        (Array.isArray(barPositions) ? barPositions : []).map((bar) => bar?.[axis]).filter((value) => Number.isFinite(value)),
        0,
        1
    );

    return sortedValues.filter((value, index) => (
        index === 0 || Math.abs(value - sortedValues[index - 1]) > 0.0001
    ));
}

function getColumnConfinementDistributedIndexes(itemCount, selectionCount) {
    const normalizedItemCount = Math.max(Number.parseInt(itemCount, 10) || 0, 0);
    const normalizedSelectionCount = Math.min(
        Math.max(Number.parseInt(selectionCount, 10) || 0, 0),
        normalizedItemCount
    );

    if (normalizedItemCount <= 0 || normalizedSelectionCount <= 0) {
        return [];
    }

    if (normalizedSelectionCount >= normalizedItemCount) {
        return Array.from({ length: normalizedItemCount }, (_, index) => index);
    }

    const indexes = [];
    for (let index = 0; index < normalizedSelectionCount; index += 1) {
        const rawIndex = normalizedSelectionCount === 1
            ? (normalizedItemCount - 1) / 2
            : (index * (normalizedItemCount - 1)) / (normalizedSelectionCount - 1);
        const minIndex = index === 0 ? 0 : indexes[index - 1] + 1;
        const maxIndex = normalizedItemCount - (normalizedSelectionCount - index);
        indexes.push(Math.min(Math.max(Math.round(rawIndex), minIndex), maxIndex));
    }

    return indexes;
}

function getColumnConfinementInnerLoopStart(axisValues, intervalIndex, outerStart) {
    return intervalIndex <= 0
        ? (outerStart + axisValues[0]) / 2
        : (axisValues[intervalIndex - 1] + axisValues[intervalIndex]) / 2;
}

function getColumnConfinementInnerLoopEnd(axisValues, intervalIndex, outerEnd) {
    const endBarIndex = intervalIndex + 1;
    return endBarIndex >= axisValues.length - 1
        ? (axisValues[axisValues.length - 1] + outerEnd) / 2
        : (axisValues[endBarIndex] + axisValues[endBarIndex + 1]) / 2;
}

function getColumnConfinementBandLoops(axisValues, loopCount, outerStart, outerEnd) {
    if (!Array.isArray(axisValues) || axisValues.length < 3) {
        return [];
    }

    return getColumnConfinementDistributedIndexes(axisValues.length - 1, loopCount).map((intervalIndex) => ({
        intervalIndex,
        start: getColumnConfinementInnerLoopStart(axisValues, intervalIndex, outerStart),
        end: getColumnConfinementInnerLoopEnd(axisValues, intervalIndex, outerEnd)
    })).filter((loop) => Math.abs(loop.end - loop.start) > 0.0001);
}

function getColumnConfinementLoopSegments(loop, referenceSize, hookPlacement = {}) {
    const left = loop?.left ?? 0;
    const right = loop?.right ?? 0;
    const top = loop?.top ?? 0;
    const bottom = loop?.bottom ?? 0;
    const isRightAnchor = hookPlacement.anchor === "right";
    const isBottomAnchor = hookPlacement.edge === "bottom";
    const horizontalAxisDirection = Math.sign(right - left) || 1;
    const verticalAxisDirection = Math.sign(bottom - top) || 1;
    const cornerX = isRightAnchor ? right : left;
    const cornerY = isBottomAnchor ? bottom : top;
    const inwardX = isRightAnchor ? -horizontalAxisDirection : horizontalAxisDirection;
    const inwardY = isBottomAnchor ? -verticalAxisDirection : verticalAxisDirection;
    const lineOffset = Math.max(referenceSize * 0.05, 0.035);
    const lineLength = Math.max(referenceSize * 0.18, 0.1);
    const firstHookStart = {
        x: cornerX + inwardX * lineOffset,
        y: cornerY
    };
    const secondHookStart = {
        x: cornerX,
        y: cornerY + inwardY * lineOffset
    };

    return [
        { x1: left, y1: top, x2: right, y2: top },
        { x1: right, y1: top, x2: right, y2: bottom },
        { x1: right, y1: bottom, x2: left, y2: bottom },
        { x1: left, y1: bottom, x2: left, y2: top },
        {
            x1: firstHookStart.x,
            y1: firstHookStart.y,
            x2: firstHookStart.x + inwardX * lineLength,
            y2: firstHookStart.y + inwardY * lineLength
        },
        {
            x1: secondHookStart.x,
            y1: secondHookStart.y,
            x2: secondHookStart.x + inwardX * lineLength,
            y2: secondHookStart.y + inwardY * lineLength
        }
    ];
}

function dedupeColumnConfinementSegments(segments) {
    const seen = new Set();
    return (Array.isArray(segments) ? segments : []).filter((segment) => {
        const normalizedKey = [
            segment.x1.toFixed(4),
            segment.y1.toFixed(4),
            segment.x2.toFixed(4),
            segment.y2.toFixed(4)
        ].join("|");
        const reverseKey = [
            segment.x2.toFixed(4),
            segment.y2.toFixed(4),
            segment.x1.toFixed(4),
            segment.y1.toFixed(4)
        ].join("|");
        if (seen.has(normalizedKey) || seen.has(reverseKey)) {
            return false;
        }

        seen.add(normalizedKey);
        return true;
    });
}

function getColumnConfinementSegments(layout, barPositions = []) {
    return getColumnConfinementPieces(layout, barPositions).pieces.flatMap((piece) => piece.segments);
}

function drawColumnConfinementPreview(context, layout, barPositions = []) {
    context.beginPath();
    getColumnConfinementSegments(layout, barPositions).forEach((segment) => {
        context.moveTo(segment.x1, segment.y1);
        context.lineTo(segment.x2, segment.y2);
    });
    context.stroke();
}

/* SERVER_ONLY_START */
function getColumnSectionStirrupHookDrawingOptions(barRadius = DXF_STIRRUP_2D_RADIUS, hookLength = 0.1) {
    const safeBarRadius = Math.max(parsePositiveNumberOrFallback(barRadius, DXF_STIRRUP_2D_RADIUS, 0.001), 0.001);
    const safeHookLength = Math.max(parsePositiveNumberOrFallback(hookLength, 0.1, 0.01), 0.01);
    // Use the same tangent-arc method as frame stirrups, but size the bend to
    // the actual column tie and cap it by the available 45-degree hook tail.
    const minimumInnerRadius = Math.max(safeBarRadius * 0.90, 0.004);
    const preferredCenterlineRadius = Math.max(safeBarRadius * 2.75, 0.014);
    const maximumCenterlineRadius = Math.max(safeHookLength * 0.48, safeBarRadius + minimumInnerRadius);
    const centerlineRadius = Math.min(preferredCenterlineRadius, maximumCenterlineRadius);

    return {
        barRadius: safeBarRadius,
        frameSectionTangentHooks: true,
        frameSectionHookInnerRadius: Math.max(centerlineRadius - safeBarRadius, 0.001),
        frameSectionHookOuterRadius: centerlineRadius + safeBarRadius,
        frameSectionHookScale: COLUMN_SECTION_DETAIL_SCALE
    };
}

function drawColumnConfinementDetail(dxf, layout, layer = "ACERO_TRANSVERSAL", barPositions = [], options = {}) {
    const confinement = getColumnConfinementPieces(layout, barPositions);
    confinement.pieces.forEach((piece) => {
        drawDxfConfinementSegmentsWithRoundedCorners(dxf, layer, piece.segments, options);
    });
}

function drawCircularColumnStirrupDetail(dxf, layer, centerX, centerY, centerlineRadius, barRadius) {
    const safeBarRadius = Math.max(parsePositiveNumberOrFallback(barRadius, DXF_STIRRUP_2D_RADIUS, 0.001), 0.001);
    const safeCenterlineRadius = Math.max(parsePositiveNumberOrFallback(centerlineRadius, 0, 0), safeBarRadius + 0.001);
    addFilledAnnularSector(
        dxf,
        layer,
        centerX,
        centerY,
        Math.max(safeCenterlineRadius - safeBarRadius, 0.0001),
        safeCenterlineRadius + safeBarRadius,
        0,
        360,
        DXF_REBAR_SOLID_COLOR,
        96,
        { fillStyle: "hatch" }
    );
}
/* SERVER_ONLY_END */

function drawColumnPreviewCard(context, entry, x, y, width, height) {
    const column = entry.column;
    const longRebar = normalizeColumnLongitudinalRebar(column.longRebar ?? column.longitudinalRebar);
    const stirrups = ensureColumnTransverseRebar(column, longRebar);
    const cardHeader = getNamedCardHeader("Columna", entry.tag, column.name, entry.levelName);
    drawDetailPreviewCardFrame(context, x, y, width, height, cardHeader.title, cardHeader.subtitle);

    const previewRect = getColumnPreviewSectionRect(column, Math.min(width - 84, 118), Math.min(height - 176, 118));
    const pixelsPerMeter = getSectionPreviewScaleFactor(previewRect, getColumnWidth(column), getColumnHeight(column));
    const left = x + (width - previewRect.width) / 2;
    const top = y + 58;
    const right = left + previewRect.width;
    const bottom = top + previewRect.height;
    const cover = Math.min(
        getColumnSectionClearCover(stirrups) * pixelsPerMeter,
        Math.max(Math.min(previewRect.width, previewRect.height) / 2 - 4, 3)
    );
    const stirrupLeft = left + cover;
    const stirrupRight = right - cover;
    const stirrupTop = top + cover;
    const stirrupBottom = bottom - cover;
    const confinementLayout = getColumnConfinementLayout(stirrups, longRebar, stirrupLeft, stirrupBottom, stirrupRight, stirrupTop);
    const positions = getColumnBarPositions(
        longRebar,
        stirrupLeft,
        stirrupBottom,
        stirrupRight,
        stirrupTop,
        (diameter) => Math.max(getRebarDrawRadius(diameter) * 16, 3.5)
    );

    context.save();
    context.strokeStyle = "#334155";
    context.lineWidth = 1.5;
    context.strokeRect(left, top, previewRect.width, previewRect.height);
    context.strokeStyle = "#2563eb";
    context.lineWidth = 1.3;
    drawColumnConfinementPreview(context, confinementLayout, positions);
    context.fillStyle = "#000000";
    positions.forEach((position) => {
        context.beginPath();
        context.arc(position.x, position.y, position.radius, 0, Math.PI * 2);
        context.fill();
    });
    context.fillStyle = "#17202a";
    context.font = '10px "Segoe UI", sans-serif';
    context.fillText(`Long: ${formatColumnLongitudinalDetailLabel(longRebar)}`, x + 14, y + height - 56);
    context.fillText(`Estr: ${formatColumnTransverseDetailLabel(stirrups, longRebar)}`, x + 14, y + height - 38);
    context.fillText(`${formatSectionDimensionsText(getColumnWidth(column), getColumnHeight(column))}`, x + 14, y + height - 20);
    context.restore();
}

/* SERVER_ONLY_START */
function getColumnConfinementSegmentBounds(segments) {
    const normalizedSegments = Array.isArray(segments) ? segments : [];
    const xValues = normalizedSegments.flatMap((segment) => [segment?.x1, segment?.x2]).filter(Number.isFinite);
    const yValues = normalizedSegments.flatMap((segment) => [segment?.y1, segment?.y2]).filter(Number.isFinite);

    if (!xValues.length || !yValues.length) {
        return null;
    }

    return {
        left: Math.min(...xValues),
        right: Math.max(...xValues),
        bottom: Math.min(...yValues),
        top: Math.max(...yValues)
    };
}

function getColumnConfinementPieceMeasureBounds(piece, options = {}) {
    const segments = Array.isArray(piece?.segments) ? piece.segments : [];
    const centerlineBounds = getAxisAlignedRectangleFromSegments(segments) || getColumnConfinementSegmentBounds(segments);
    return expandColumnConfinementBoundsToStirrupExterior(centerlineBounds, options.barRadius);
}

function translateColumnConfinementSegments(segments, deltaX, deltaY) {
    return (Array.isArray(segments) ? segments : []).map((segment) => ({
        ...segment,
        x1: segment.x1 + deltaX,
        y1: segment.y1 + deltaY,
        x2: segment.x2 + deltaX,
        y2: segment.y2 + deltaY
    }));
}

function formatColumnExplodedStirrupDimension(value) {
    return Math.max(parseNumberOrFallback(value, 0), 0).toFixed(2);
}

function isColumnConfinementSingleLinePiece(piece) {
    if (!piece || !Array.isArray(piece.segments) || !piece.segments.length) {
        return false;
    }

    if (["horizontal_crosstie", "vertical_crosstie"].includes(piece.type)) {
        return true;
    }

    return !getAxisAlignedRectangleFromSegments(piece.segments)
        && piece.segments.some((segment) => (
            hasFiniteNumbers(segment?.x1, segment?.y1, segment?.x2, segment?.y2)
            && (
                Math.abs(segment.x2 - segment.x1) > 0.0001
                || Math.abs(segment.y2 - segment.y1) > 0.0001
            )
        ));
}

function getColumnConfinementSingleLineMainSegment(piece) {
    const segments = Array.isArray(piece?.segments) ? piece.segments : [];
    if (!segments.length) {
        return null;
    }

    const preferredAxis = piece?.axis === "y" ? "y" : piece?.axis === "x" ? "x" : null;
    const candidates = segments
        .filter((segment) => hasFiniteNumbers(segment?.x1, segment?.y1, segment?.x2, segment?.y2))
        .map((segment) => {
            const dx = segment.x2 - segment.x1;
            const dy = segment.y2 - segment.y1;
            const axis = Math.abs(dx) >= Math.abs(dy) ? "x" : "y";
            return {
                segment,
                axis,
                length: Math.hypot(dx, dy),
                axisLength: axis === "x" ? Math.abs(dx) : Math.abs(dy)
            };
        })
        .filter((candidate) => candidate.axisLength > 0.0001);

    const axisCandidates = preferredAxis
        ? candidates.filter((candidate) => candidate.axis === preferredAxis)
        : candidates;

    return (axisCandidates.length ? axisCandidates : candidates)
        .sort((left, right) => right.length - left.length)[0]
        || null;
}

function getColumnConfinementSingleLineLengthMeasure(piece, scaleX, scaleY, barRadius = DXF_STIRRUP_2D_RADIUS) {
    const main = getColumnConfinementSingleLineMainSegment(piece);
    if (!main) {
        return null;
    }

    const safeRadius = Math.max(parsePositiveNumberOrFallback(barRadius, DXF_STIRRUP_2D_RADIUS, 0.001), 0.001);
    if (main.axis === "x") {
        const left = Math.min(main.segment.x1, main.segment.x2) - safeRadius;
        const right = Math.max(main.segment.x1, main.segment.x2) + safeRadius;
        return {
            axis: "x",
            left,
            right,
            bottom: Math.min(main.segment.y1, main.segment.y2) - safeRadius,
            top: Math.max(main.segment.y1, main.segment.y2) + safeRadius,
            value: getColumnRealDimensionValueFromDrawnLength(right - left, scaleX)
        };
    }

    const bottom = Math.min(main.segment.y1, main.segment.y2) - safeRadius;
    const top = Math.max(main.segment.y1, main.segment.y2) + safeRadius;
    return {
        axis: "y",
        left: Math.min(main.segment.x1, main.segment.x2) - safeRadius,
        right: Math.max(main.segment.x1, main.segment.x2) + safeRadius,
        bottom,
        top,
        value: getColumnRealDimensionValueFromDrawnLength(top - bottom, scaleY)
    };
}

function drawColumnSingleLineStirrupLengthDimension(dxf, lengthMeasure, dimensionOffset, dimensionVisualScale) {
    if (!lengthMeasure) {
        return;
    }

    if (lengthMeasure.axis === "x") {
        addDimension(
            dxf,
            "COTAS_SECCION",
            lengthMeasure.left,
            lengthMeasure.right,
            lengthMeasure.bottom - dimensionOffset,
            formatColumnCalculatedDimension(lengthMeasure.value),
            lengthMeasure.bottom,
            { visualScale: dimensionVisualScale, textHeight: COLUMN_SECTION_TEXT_SIZE }
        );
        return;
    }

    addVerticalDimension(
        dxf,
        "COTAS_SECCION",
        lengthMeasure.right + dimensionOffset,
        lengthMeasure.bottom,
        lengthMeasure.top,
        formatColumnCalculatedDimension(lengthMeasure.value),
        lengthMeasure.right,
        { visualScale: dimensionVisualScale, textHeight: COLUMN_SECTION_TEXT_SIZE }
    );
}

function drawColumnExplodedStirrupDetails(dxf, confinementLayout, barPositions, startX, topLimit, bottomLimit, sectionScaleX = COLUMN_SECTION_DETAIL_SCALE, sectionScaleY = COLUMN_SECTION_DETAIL_SCALE, barRadius = DXF_STIRRUP_2D_RADIUS, hookDrawingOptions = {}) {
    const pieces = getColumnConfinementPieces(confinementLayout, barPositions).pieces.filter((piece) => (
        Array.isArray(piece?.segments) && piece.segments.length > 0
    ));
    if (!pieces.length) {
        return;
    }

    const verticalGap = 0.55;
    const horizontalGap = 0.85;
    const dimensionOffset = COLUMN_SECTION_DIMENSION_OFFSET;
    const minimumPanelHeight = 1.6;
    const detailScaleX = Math.max(parsePositiveNumberOrFallback(sectionScaleX, COLUMN_SECTION_DETAIL_SCALE, 0.001), 0.001);
    const detailScaleY = Math.max(parsePositiveNumberOrFallback(sectionScaleY, COLUMN_SECTION_DETAIL_SCALE, 0.001), 0.001);
    const stirrupBarRadius = Math.max(parsePositiveNumberOrFallback(barRadius, DXF_STIRRUP_2D_RADIUS, 0.001), 0.001);
    const dimensionVisualScale = getColumnSectionDimensionVisualScale(detailScaleX, detailScaleY);
    const safeBottom = Math.min(bottomLimit, topLimit - minimumPanelHeight);
    let cursorX = startX;
    let cursorY = topLimit;
    let currentColumnWidth = 0;

    pieces.forEach((piece) => {
        const fullBounds = getColumnConfinementSegmentBounds(piece.segments);
        const realMeasure = getColumnConfinementPieceRealMeasure(piece, detailScaleX, detailScaleY, stirrupBarRadius);
        const measureBounds = realMeasure?.bounds || null;
        if (!fullBounds || !measureBounds || !realMeasure) {
            return;
        }

        const pieceWidth = Math.max(measureBounds.right - measureBounds.left, 0.01);
        const pieceHeight = Math.max(measureBounds.top - measureBounds.bottom, 0.01);
        const requiredHeight = pieceHeight + dimensionOffset + verticalGap;

        if (cursorY - requiredHeight < safeBottom && cursorY < topLimit - 0.001) {
            cursorX += currentColumnWidth + horizontalGap;
            cursorY = topLimit;
            currentColumnWidth = 0;
        }

        const deltaX = cursorX - measureBounds.left;
        const deltaY = cursorY - measureBounds.top;
        const translatedSegments = translateColumnConfinementSegments(piece.segments, deltaX, deltaY);
        const dimensionLeft = measureBounds.left + deltaX;
        const dimensionRight = measureBounds.right + deltaX;
        const dimensionBottom = measureBounds.bottom + deltaY;
        const dimensionTop = measureBounds.top + deltaY;

        drawDxfConfinementSegmentsWithRoundedCorners(dxf, "ACERO_TRANSVERSAL", translatedSegments, {
            ...hookDrawingOptions,
            barRadius: stirrupBarRadius
        });

        if (isColumnConfinementSingleLinePiece(piece)) {
            const lengthMeasure = getColumnConfinementSingleLineLengthMeasure(
                { ...piece, segments: translatedSegments },
                detailScaleX,
                detailScaleY,
                stirrupBarRadius
            );
            drawColumnSingleLineStirrupLengthDimension(
                dxf,
                lengthMeasure,
                dimensionOffset,
                dimensionVisualScale
            );
        } else {
            addDimension(
                dxf,
                "COTAS_SECCION",
                dimensionLeft,
                dimensionRight,
                dimensionBottom - dimensionOffset,
                formatColumnCalculatedDimension(realMeasure.width),
                dimensionBottom,
                { visualScale: dimensionVisualScale, textHeight: COLUMN_SECTION_TEXT_SIZE }
            );
            addVerticalDimension(
                dxf,
                "COTAS_SECCION",
                dimensionRight + dimensionOffset,
                dimensionBottom,
                dimensionTop,
                formatColumnCalculatedDimension(realMeasure.height),
                dimensionRight,
                { visualScale: dimensionVisualScale, textHeight: COLUMN_SECTION_TEXT_SIZE }
            );
        }

        currentColumnWidth = Math.max(currentColumnWidth, pieceWidth + dimensionOffset + 0.32);
        cursorY = dimensionBottom - dimensionOffset - verticalGap;
    });
}

function getColumnSectionStirrupSignature(column) {
    const normalized = normalizeColumnModel(column);
    const longRebar = normalizeColumnLongitudinalRebar(normalized.longRebar ?? normalized.longitudinalRebar);
    return JSON.stringify(canonicalizeSmartRenameValue(
        ensureColumnTransverseRebar(normalized, longRebar)
    ));
}

function shouldColumnSectionReferToElevationForStirrups(detail = {}) {
    const column = detail?.column;
    if (!column) {
        return false;
    }

    const startLevelIndex = Number.parseInt(detail?.startLevelIndex, 10);
    const endLevelIndex = Number.parseInt(detail?.endLevelIndex, 10);
    if (!Number.isFinite(startLevelIndex) || !Number.isFinite(endLevelIndex) || endLevelIndex <= startLevelIndex) {
        return false;
    }

    const targetPositionKey = getColumnElevationPositionKey(column);
    const targetSectionSignature = getColumnDetailBaseSectionSignature(column);
    const stirrupSignatures = new Set();

    for (let levelIndex = startLevelIndex; levelIndex <= endLevelIndex; levelIndex += 1) {
        const level = projectState.levels[levelIndex];
        const candidate = (level?.columns || []).find((entry) => (
            getColumnElevationPositionKey(entry) === targetPositionKey
            && getColumnDetailBaseSectionSignature(entry) === targetSectionSignature
        ));
        if (candidate) {
            stirrupSignatures.add(getColumnSectionStirrupSignature(candidate));
        }
    }

    return stirrupSignatures.size > 1;
}

function drawColumnSectionDetail(dxf, detail, originX, originY, detailSize) {
    const { column, tag, levelName } = detail;
    const columnTitle = normalizeTextValue(column?.name) || `COLUMNA ${tag}`;
    const sectionWidth = detailSize.sectionWidth;
    if (isStructuralSteelElement(column)) {
        const left = originX + 0.45;
        const bottom = originY - detailSize.sectionHeight - 1.05;
        const right = left + detailSize.sectionWidth;
        const top = bottom + detailSize.sectionHeight;
        const profile = getDxfSteelProfileForColumn(column);
        const profileWidth = getDxfSteelProfileWidth(profile);
        const profileDepth = getDxfSteelProfileDepth(profile);
        drawDxfSteelProfile(dxf, profile, left, bottom, detailSize.sectionWidth, detailSize.sectionHeight, { showSectionDefinitionLines: true });
        addDimension(dxf, "COTAS_SECCION", left, right, bottom - COLUMN_SECTION_DIMENSION_OFFSET, formatLengthForUnit(profileWidth, "section"), bottom, { textHeight: COLUMN_SECTION_TEXT_SIZE });
        addVerticalDimension(dxf, "COTAS_SECCION", left - COLUMN_SECTION_DIMENSION_OFFSET, bottom, top, profileDepth, left, { textHeight: COLUMN_SECTION_TEXT_SIZE });
        const name = normalizeTextValue(profile.name || column.sourceSection || column.name || "PERFIL W");
        const wallThickness = getDxfSteelProfileWallThickness(profile);
        addCenteredText(dxf, "SECCION_TEXTO", (left + right) / 2, bottom - 0.65, name, COLUMN_SECTION_TEXT_SIZE);
        if (wallThickness > EDGE_TOLERANCE) {
            addCenteredText(
                dxf,
                "SECCION_TEXTO",
                (left + right) / 2,
                bottom - 0.88,
                `t=${formatLengthForUnit(wallThickness, "section")}`,
                COLUMN_SECTION_TEXT_SIZE
            );
        }
        drawDetailTitleMarker(
            dxf,
            left + 0.15,
            bottom - 0.30,
            normalizeTextValue(tag) || name,
            "E-00",
            `SECCIÓN DE PERFIL ${name}${levelName ? ` | ${levelName}` : ""}`.trim(),
            COLUMN_SECTION_TITLE_MARKER_OPTIONS
        );
        return;
    }
    const sectionDesigner = getDxfSectionDesignerConcrete(column);
    if (sectionDesigner) {
        const sectionHeight = detailSize.sectionHeight;
        const left = originX + 0.45;
        const bottom = originY - sectionHeight - 1.05;
        const sectionScaleX = getColumnSectionDetailScaleX(detailSize, column);
        const sectionScaleY = getColumnSectionDetailScaleY(detailSize, column);
        const dimensionVisualScale = getColumnSectionDimensionVisualScale(sectionScaleX, sectionScaleY);
        const markerCenterX = left + 0.15;
        const markerCenterY = bottom - 0.30;
        const drawn = drawDxfSectionDesignerColumnDetail(
            dxf,
            detail,
            left,
            bottom,
            sectionWidth,
            sectionHeight,
            dimensionVisualScale
        );
        if (drawn) {
            drawDetailTitleMarker(
                dxf,
                markerCenterX,
                markerCenterY,
                normalizeTextValue(column?.name) || columnTitle,
                "E-00",
                `DETALLE DE COLUMNA ${normalizeTextValue(column?.name) || columnTitle}${levelName ? ` | ${levelName}` : ""}`.trim(),
                COLUMN_SECTION_TITLE_MARKER_OPTIONS
            );
            return;
        }
    }
    const sectionHeight = detailSize.sectionHeight;
    const left = originX + 0.45;
    const bottom = originY - sectionHeight - 1.05;
    const right = left + sectionWidth;
    const top = bottom + sectionHeight;
    const longRebar = normalizeColumnLongitudinalRebar(column.longRebar ?? column.longitudinalRebar);
    const stirrups = ensureColumnTransverseRebar(column, longRebar);
    const clearCover = getColumnSectionClearCover(stirrups);
    const sectionScaleX = getColumnSectionDetailScaleX(detailSize, column);
    const sectionScaleY = getColumnSectionDetailScaleY(detailSize, column);
    const dimensionVisualScale = getColumnSectionDimensionVisualScale(sectionScaleX, sectionScaleY);
    const stirrupBarRadius = getColumnStirrupDrawRadius(stirrups, COLUMN_SECTION_DETAIL_SCALE);
    const coverX = Math.min(clearCover * sectionScaleX, Math.max(sectionWidth / 2 - 0.06, 0.04));
    const coverY = Math.min(clearCover * sectionScaleY, Math.max(sectionHeight / 2 - 0.06, 0.04));
    const stirrupLeft = left + coverX;
    const stirrupRight = right - coverX;
    const stirrupBottom = bottom + coverY;
    const stirrupTop = top - coverY;
    const confinementLayout = getColumnConfinementLayout(stirrups, longRebar, stirrupLeft, stirrupBottom, stirrupRight, stirrupTop);
    const barPositions = getColumnBarPositions(
        longRebar,
        stirrupLeft,
        stirrupBottom,
        stirrupRight,
        stirrupTop,
        (diameter) => getColumnLongitudinalDrawRadius(diameter, COLUMN_SECTION_DETAIL_SCALE)
    );
    // Keep the exploded stirrup schedule close to the section while leaving
    // clearance for the right-hand dimension.
    const explodedStirrupOriginX = right + 0.35;
    const topTextX = left;
    const topLongTextY = top + COLUMN_SECTION_LONG_TEXT_OFFSET;
    const topStirrupTextY = top + COLUMN_SECTION_STIRRUP_TEXT_OFFSET;
    const markerCenterX = left + 0.15;
    const markerCenterY = bottom - 0.30;

    if (isCircularColumnSection(column)) {
        const centerX = (left + right) / 2;
        const centerY = (bottom + top) / 2;
        const radius = Math.min(sectionWidth, sectionHeight) / 2;
        const sectionScale = Math.min(sectionScaleX, sectionScaleY);
        const stirrupRadius = Math.max(radius - clearCover * sectionScale, 0.06);
        const circularBarPositions = getCircularColumnBarPositions(
            longRebar,
            centerX,
            centerY,
            stirrupRadius,
            (diameter) => getColumnLongitudinalDrawRadius(diameter, COLUMN_SECTION_DETAIL_SCALE)
        );

        addCircle(dxf, "CONCRETO_COLUMNAS", centerX, centerY, radius);
        drawCircularColumnStirrupDetail(dxf, "ACERO_TRANSVERSAL", centerX, centerY, stirrupRadius, stirrupBarRadius);
        circularBarPositions.forEach((position) => addRepresentativeRebarCircle(dxf, "ACERO_LONGITUDINAL", position.x, position.y, position.radius));
        addDimension(
            dxf,
            "COTAS_SECCION",
            left,
            right,
            bottom - COLUMN_SECTION_DIMENSION_OFFSET,
            `D=${formatLengthForUnit(getColumnDiameter(column), "section")}`,
            bottom,
            { visualScale: dimensionVisualScale, textHeight: COLUMN_SECTION_TEXT_SIZE }
        );
        addVerticalDimension(
            dxf,
            "COTAS_SECCION",
            left - COLUMN_SECTION_DIMENSION_OFFSET,
            bottom,
            top,
            `D=${formatLengthForUnit(getColumnDiameter(column), "section")}`,
            left,
            { visualScale: dimensionVisualScale, textHeight: COLUMN_SECTION_TEXT_SIZE }
        );
        addText(dxf, "TEXTO_ACERO", topTextX, topLongTextY, `LONG: ${formatColumnLongitudinalDetailLabel(longRebar)}`, COLUMN_SECTION_TEXT_SIZE);
        const circularStirrupSectionLabel = shouldColumnSectionReferToElevationForStirrups(detail)
            ? "EST.: VER ELEVACIÃ“N"
            : `EST: ${formatColumnTransverseDetailLabel(stirrups, longRebar)}`;
        addText(dxf, "TEXTO_ESTRIBOS", topTextX, topStirrupTextY, circularStirrupSectionLabel, COLUMN_SECTION_TEXT_SIZE);
        drawDetailTitleMarker(
            dxf,
            markerCenterX,
            markerCenterY,
            normalizeTextValue(column?.name) || columnTitle,
            "E-00",
            `DETALLE DE COLUMNA ${normalizeTextValue(column?.name) || columnTitle}${levelName ? ` | ${levelName}` : ""}`.trim(),
            COLUMN_SECTION_TITLE_MARKER_OPTIONS
        );
        return;
    }

    addPolylineRectangle(dxf, "CONCRETO_COLUMNAS", left, bottom, sectionWidth, sectionHeight);
    const stirrupHookDrawingOptions = getColumnSectionStirrupHookDrawingOptions(
        stirrupBarRadius,
        confinementLayout.hookLength
    );
    drawColumnConfinementDetail(
        dxf,
        confinementLayout,
        "ACERO_TRANSVERSAL",
        barPositions,
        stirrupHookDrawingOptions
    );
    barPositions.forEach((position) => addRepresentativeRebarCircle(dxf, "ACERO_LONGITUDINAL", position.x, position.y, position.radius));

    addDimension(
        dxf,
        "COTAS_SECCION",
        left,
        right,
        bottom - COLUMN_SECTION_DIMENSION_OFFSET,
        formatColumnRealDimensionFromDrawnLength(right - left, sectionScaleX),
        bottom,
        { visualScale: dimensionVisualScale, textHeight: COLUMN_SECTION_TEXT_SIZE }
    );
    addVerticalDimension(
        dxf,
        "COTAS_SECCION",
        left - COLUMN_SECTION_DIMENSION_OFFSET,
        bottom,
        top,
        formatColumnRealDimensionFromDrawnLength(top - bottom, sectionScaleY),
        left,
        { visualScale: dimensionVisualScale, textHeight: COLUMN_SECTION_TEXT_SIZE }
    );
    addText(
        dxf,
        "TEXTO_ACERO",
        topTextX,
        topLongTextY,
        `LONG: ${formatColumnLongitudinalDetailLabel(longRebar)}`,
        COLUMN_SECTION_TEXT_SIZE
    );
    const stirrupSectionLabel = shouldColumnSectionReferToElevationForStirrups(detail)
        ? "EST.: VER ELEVACIÓN"
        : `EST: ${formatColumnTransverseDetailLabel(stirrups, longRebar)}`;
    addText(
        dxf,
        "TEXTO_ESTRIBOS",
        topTextX,
        topStirrupTextY,
        stirrupSectionLabel,
        COLUMN_SECTION_TEXT_SIZE
    );
    drawColumnExplodedStirrupDetails(
        dxf,
        confinementLayout,
        barPositions,
        explodedStirrupOriginX,
        top + 0.18,
        bottom - 0.05,
        sectionScaleX,
        sectionScaleY,
        stirrupBarRadius,
        stirrupHookDrawingOptions
    );
    drawDetailTitleMarker(
        dxf,
        markerCenterX,
        markerCenterY,
        normalizeTextValue(column?.name) || columnTitle,
        "E-00",
        `DETALLE DE COLUMNA ${normalizeTextValue(column?.name) || columnTitle}${levelName ? ` | ${levelName}` : ""}`.trim(),
        COLUMN_SECTION_TITLE_MARKER_OPTIONS
    );
}

function getColumnElevationPositionKey(column) {
    const normalized = normalizeColumnModel(column);
    return [
        getDetailMetricKey(normalized.x),
        getDetailMetricKey(normalized.y)
    ].join("|");
}

function getColumnElevationNameKey(column) {
    const normalizedName = getColumnDetailLabelKey(column);
    return normalizedName ? `name|${normalizedName}` : "";
}

function getColumnElevationIdentityKey(column) {
    const nameKey = getColumnElevationNameKey(column);
    if (nameKey) {
        return nameKey;
    }

    return `position|${getColumnElevationPositionKey(column)}`;
}

function getColumnElevationLocationLabel(column) {
    const normalized = normalizeColumnModel(column);
    return `${getAxisLabelForValue("x", normalized.x)}-${getAxisLabelForValue("y", normalized.y)}`;
}

function getColumnElevationTitleLabel(stack) {
    const entries = Array.isArray(stack?.entries) ? stack.entries : [];
    const columnNames = Array.from(new Set(
        entries
            .map((entry) => normalizeTextValue(entry?.column?.name))
            .filter(Boolean)
    ));

    if (columnNames.length > 0) {
        return columnNames.join(" / ");
    }

    return stack?.locationLabel || (projectState.language === "en" ? "COLUMN" : "COLUMNA");
}

function getColumnElevationStacks(levels = projectState.levels) {
    const stackByKey = new Map();
    let baseElevation = 0;

    (levels || []).forEach((level, levelIndex) => {
        const levelHeight = getLevelHeightForQuantities(level);
        const topElevation = baseElevation + levelHeight;
        const seenElevationKeys = new Set();

        (level?.columns || []).forEach((column) => {
            const normalized = normalizeColumnModel(column);
            if (isStructuralSteelElement(normalized)) {
                return;
            }
            const elevationKey = getColumnElevationIdentityKey(normalized);
            const positionKey = getColumnElevationPositionKey(normalized);
            if (seenElevationKeys.has(elevationKey)) {
                return;
            }

            seenElevationKeys.add(elevationKey);

            let stack = stackByKey.get(elevationKey);
            if (!stack) {
                stack = {
                    key: elevationKey,
                    positionKey,
                    nameKey: getColumnElevationNameKey(normalized),
                    x: normalized.x,
                    y: normalized.y,
                    locationLabel: getColumnElevationLocationLabel(normalized),
                    entries: []
                };
                stackByKey.set(elevationKey, stack);
            }

            stack.entries.push({
                level,
                levelIndex,
                baseElevation,
                topElevation,
                column: normalized,
                positionKey,
                elevationKey
            });
        });

        baseElevation = topElevation;
    });

    return Array.from(stackByKey.values())
        .map((stack) => {
            const entries = stack.entries.sort((left, right) => left.levelIndex - right.levelIndex);
            const maxColumnWidth = entries.reduce((max, entry) => Math.max(max, getColumnWidth(entry.column)), 0.1);
            const maxColumnHeight = entries.reduce((max, entry) => Math.max(max, getColumnHeight(entry.column)), 0.1);

            return {
                ...stack,
                entries,
                maxColumnWidth,
                maxColumnHeight
            };
        })
        .sort((left, right) => (
            getColumnElevationTitleLabel(left).localeCompare(getColumnElevationTitleLabel(right), undefined, { sensitivity: "base", numeric: true })
            || left.y - right.y
            || left.x - right.x
            || left.locationLabel.localeCompare(right.locationLabel, undefined, { sensitivity: "base" })
        ));
}

function getColumnElevationDrawableLevels(stack, levels = projectState.levels) {
    const safeLevels = Array.isArray(levels) ? levels : [];
    const entries = Array.isArray(stack?.entries) ? stack.entries : [];
    const lastEntryLevelIndex = entries.reduce((maxIndex, entry) => {
        const entryLevelIndex = parseNumberOrFallback(entry?.levelIndex, -1);
        return Math.max(maxIndex, entryLevelIndex);
    }, -1);

    if (lastEntryLevelIndex < 0) {
        return safeLevels;
    }

    return safeLevels.slice(0, Math.min(lastEntryLevelIndex + 1, safeLevels.length));
}

function getColumnElevationSlabThickness(level, x, y) {
    const slabs = (level?.slabs || [])
        .map((slab) => normalizeSlab(slab))
        .filter((slab) => slab.type !== "hole");

    if (!slabs.length) {
        return 0.15;
    }

    const point = {
        x: parseNumberOrFallback(x, 0),
        y: parseNumberOrFallback(y, 0)
    };
    const containingSlabs = slabs.filter((slab) => isPointInPolygon(point, slab.vertices, { includeBoundary: true }));
    const candidates = containingSlabs.length > 0 ? containingSlabs : slabs;
    const selectedSlab = candidates.sort((left, right) => (
        Math.abs(getSlabPolygonArea(left)) - Math.abs(getSlabPolygonArea(right))
        || left.h - right.h
    ))[0];

    return Math.max(parsePositiveNumberOrFallback(selectedSlab?.h, 0.15, 0.05), 0.05);
}

function getColumnElevationSlabFragmentWidth(stack) {
    const maxColumnWidth = parsePositiveNumberOrFallback(stack?.maxColumnWidth, 0.4, 0.1);
    return Math.min(Math.max(maxColumnWidth * 5, 2.0), 3.6);
}

function getColumnElevationLongitudinalBarXs(column, segmentLeft, segmentWidth, longRebar) {
    const normalizedColumn = normalizeColumnModel(column);
    const sectionWidth = Math.max(parsePositiveNumberOrFallback(segmentWidth, getColumnWidth(normalizedColumn), 0.1), 0.1);
    const sectionDepth = Math.max(getColumnHeight(normalizedColumn), 0.1);
    const barPositions = getColumnBarPositions(longRebar, 0, 0, sectionWidth, sectionDepth);
    const uniqueXs = Array.from(new Set(
        barPositions.map((bar) => Number((segmentLeft + bar.x).toFixed(4)))
    ));

    return uniqueXs.sort((left, right) => left - right);
}

// Column elevations deliberately show only the two edge longitudinal bars.  Their
// centerlines are resolved from the clear concrete cover, the stirrup diameter,
// and their own radius so the elevation follows the same physical layering used
// by the 1:1 column section detail.
function getColumnElevationLongitudinalBars(column, columnLeft, columnWidth, stirrups, longRebar) {
    const normalizedColumn = normalizeColumnModel(column);
    const normalizedStirrups = normalizeColumnTransverseRebar(stirrups, longRebar);
    const normalizedLongitudinal = normalizeColumnLongitudinalRebar(longRebar);
    const safeWidth = Math.max(parsePositiveNumberOrFallback(columnWidth, getColumnWidth(normalizedColumn), 0.1), 0.1);
    const clearCover = getColumnSectionClearCover(normalizedStirrups);
    const stirrupDiameter = Math.max(parseDiameterInMeters(normalizedStirrups.d), 0.001);
    const longitudinalDiameter = Math.max(parseDiameterInMeters(normalizedLongitudinal.cornerDiameter), 0.001);
    const physicalInset = clearCover + stirrupDiameter + longitudinalDiameter / 2;
    const visualRadius = Math.max(longitudinalDiameter / 2, DXF_REBAR_2D_RADIUS);
    const maximumInset = Math.max(safeWidth / 2 - visualRadius - 0.01, visualRadius);
    const inset = Math.min(Math.max(physicalInset, visualRadius), maximumInset);
    const leftX = columnLeft + inset;
    const rightX = columnLeft + safeWidth - inset;

    if (!(rightX > leftX + visualRadius * 1.5)) {
        return [{ x: columnLeft + safeWidth / 2, radius: visualRadius, diameter: longitudinalDiameter }];
    }

    return [
        { x: leftX, radius: visualRadius, diameter: longitudinalDiameter },
        { x: rightX, radius: visualRadius, diameter: longitudinalDiameter }
    ];
}

function getColumnElevationLongitudinalStyleOptions() {
    return {
        roundStart: true,
        roundEnd: true,
        capStyle: "semicircle",
        fillStyle: "hatch",
        hatchLayer: FRAME_LONGITUDINAL_HATCH_LAYER,
        hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
        hatchPatternScale: FRAME_REBAR_HATCH_SCALE
    };
}

function getColumnElevationStirrupStyleOptions() {
    return {
        roundStart: true,
        roundEnd: true,
        capStyle: "semicircle",
        fillStyle: "hatch",
        hatchLayer: FRAME_STIRRUP_HATCH_LAYER,
        hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
        hatchPatternScale: FRAME_REBAR_HATCH_SCALE
    };
}

function drawColumnElevationLongitudinalBars(dxf, bars, startY, endY) {
    const bottomY = Math.min(startY, endY);
    const topY = Math.max(startY, endY);
    if (!(topY > bottomY + EDGE_TOLERANCE)) {
        return;
    }

    const styleOptions = getColumnElevationLongitudinalStyleOptions();
    (Array.isArray(bars) ? bars : []).forEach((bar) => {
        if (!Number.isFinite(bar?.x)) {
            return;
        }
        addFilledBarSegment(
            dxf,
            "ACERO_LONGITUDINAL",
            bar.x,
            bottomY,
            bar.x,
            topY,
            Math.max(parsePositiveNumberOrFallback(bar.radius, DXF_REBAR_2D_RADIUS, 0.001), 0.001),
            DXF_REBAR_SOLID_COLOR,
            styleOptions
        );
    });
}

function drawColumnElevationLongitudinalBarsWithTopTermination(dxf, bars, startY, hookY, hookLength = 0.20, centerX = 0) {
    const bottomY = Math.min(startY, hookY);
    const topY = Math.max(startY, hookY);
    if (!(topY > bottomY + EDGE_TOLERANCE)) {
        return;
    }

    const styleOptions = getColumnElevationLongitudinalStyleOptions();
    const safeHookLength = Math.max(parsePositiveNumberOrFallback(hookLength, 0.20, 0.01), 0.01);
    (Array.isArray(bars) ? bars : []).forEach((bar) => {
        if (!Number.isFinite(bar?.x)) {
            return;
        }
        const barRadius = Math.max(parsePositiveNumberOrFallback(bar.radius, DXF_REBAR_2D_RADIUS, 0.001), 0.001);
        const direction = bar.x < centerX ? -1 : 1;
        const requestedBendRadius = Math.max(barRadius * 2.8, 0.03);
        const bendRadius = Math.min(
            Math.max(requestedBendRadius, barRadius + 0.002),
            Math.max((topY - bottomY) * 0.24, 0),
            Math.max(safeHookLength * 0.42, 0)
        );

        if (!(bendRadius > barRadius + 0.001)) {
            addFilledBarSegment(
                dxf,
                "ACERO_LONGITUDINAL",
                bar.x,
                bottomY,
                bar.x,
                topY,
                barRadius,
                DXF_REBAR_SOLID_COLOR,
                { ...styleOptions, roundStart: true, roundEnd: false, drawFlatCaps: false }
            );
            addFilledBarSegment(
                dxf,
                "ACERO_LONGITUDINAL",
                bar.x,
                topY,
                bar.x + direction * safeHookLength,
                topY,
                barRadius,
                DXF_REBAR_SOLID_COLOR,
                { ...styleOptions, roundStart: false, roundEnd: true, drawFlatCaps: false }
            );
            return;
        }

        const verticalTopY = topY - bendRadius;
        const horizontalStartX = bar.x + direction * bendRadius;
        const horizontalEndX = bar.x + direction * safeHookLength;
        addFilledBarSegment(
            dxf,
            "ACERO_LONGITUDINAL",
            bar.x,
            bottomY,
            bar.x,
            verticalTopY,
            barRadius,
            DXF_REBAR_SOLID_COLOR,
            { ...styleOptions, roundStart: true, roundEnd: false, drawFlatCaps: false }
        );

        addFilledAnnularSector(
            dxf,
            "ACERO_LONGITUDINAL",
            bar.x + direction * bendRadius,
            topY - bendRadius,
            Math.max(bendRadius - barRadius, 0.001),
            bendRadius + barRadius,
            direction < 0 ? 0 : 90,
            direction < 0 ? 90 : 180,
            DXF_REBAR_SOLID_COLOR,
            null,
            { ...styleOptions, drawRadialEdges: false }
        );

        addFilledBarSegment(
            dxf,
            "ACERO_LONGITUDINAL",
            horizontalStartX,
            topY,
            horizontalEndX,
            topY,
            barRadius,
            DXF_REBAR_SOLID_COLOR,
            { ...styleOptions, roundStart: false, roundEnd: true, drawFlatCaps: false }
        );
    });
}

function drawColumnElevationStirrups(dxf, columnLeft, columnRight, clearCover, stirrups, positions) {
    const normalizedStirrups = normalizeColumnTransverseRebar(stirrups);
    const stirrupDiameter = Math.max(parseDiameterInMeters(normalizedStirrups.d), 0.001);
    const physicalRadius = stirrupDiameter / 2;
    const visualRadius = Math.max(physicalRadius, DXF_REBAR_2D_RADIUS);
    const left = columnLeft + clearCover + physicalRadius;
    const right = columnRight - clearCover - physicalRadius;
    if (!(right > left + EDGE_TOLERANCE)) {
        return;
    }

    const styleOptions = getColumnElevationStirrupStyleOptions();
    (Array.isArray(positions) ? positions : []).forEach((y) => {
        if (!Number.isFinite(y)) {
            return;
        }
        addFilledBarSegment(
            dxf,
            "ACERO_TRANSVERSAL",
            left,
            y,
            right,
            y,
            visualRadius,
            DXF_REBAR_SOLID_COLOR,
            styleOptions
        );
    });
}

function getColumnElevationLapSpliceRegion(centralZone, edgeInset = 0.02) {
    if (!centralZone) {
        return null;
    }

    const zoneStartY = parseNumberOrFallback(centralZone.startY, Number.NaN);
    const zoneEndY = parseNumberOrFallback(centralZone.endY, Number.NaN);
    if (!(zoneEndY > zoneStartY + EDGE_TOLERANCE)) {
        return null;
    }

    const safeInset = Math.max(parsePositiveNumberOrFallback(edgeInset, 0.02, 0), 0);
    const availableStartY = zoneStartY + safeInset;
    const availableEndY = zoneEndY - safeInset;
    if (!(availableEndY > availableStartY + EDGE_TOLERANCE)) {
        return null;
    }

    const availableLength = availableEndY - availableStartY;
    const spliceLength = Math.min(1.0, availableLength);
    if (!(spliceLength > EDGE_TOLERANCE)) {
        return null;
    }

    const centerY = (availableStartY + availableEndY) / 2;
    const halfLength = spliceLength / 2;
    return {
        centerY,
        length: spliceLength,
        bottomY: centerY - halfLength,
        topY: centerY + halfLength,
        zoneStartY,
        zoneEndY,
        availableStartY,
        availableEndY
    };
}

function drawColumnElevationSmoothBarCurve(dxf, startPoint, endPoint, barRadius, styleOptions = {}) {
    if (!Number.isFinite(startPoint?.x) || !Number.isFinite(startPoint?.y) || !Number.isFinite(endPoint?.x) || !Number.isFinite(endPoint?.y)) {
        return;
    }

    const span = Math.hypot(endPoint.x - startPoint.x, endPoint.y - startPoint.y);
    if (!(span > EDGE_TOLERANCE)) {
        return;
    }

    const verticalSpan = Math.abs(endPoint.y - startPoint.y);
    if (!(verticalSpan > 0.01) || Math.abs(endPoint.x - startPoint.x) < 0.002) {
        addFilledBarSegment(
            dxf,
            "ACERO_LONGITUDINAL",
            startPoint.x,
            startPoint.y,
            endPoint.x,
            endPoint.y,
            barRadius,
            DXF_REBAR_SOLID_COLOR,
            { ...styleOptions, roundStart: false, roundEnd: false, drawFlatCaps: false }
        );
        return;
    }

    const c1 = {
        x: startPoint.x,
        y: startPoint.y + (endPoint.y - startPoint.y) * 0.46
    };
    const c2 = {
        x: endPoint.x,
        y: endPoint.y - (endPoint.y - startPoint.y) * 0.46
    };
    const sampleCount = 10;
    const points = Array.from({ length: sampleCount + 1 }, (_, index) => {
        const t = index / sampleCount;
        const mt = 1 - t;
        return {
            x: mt * mt * mt * startPoint.x
                + 3 * mt * mt * t * c1.x
                + 3 * mt * t * t * c2.x
                + t * t * t * endPoint.x,
            y: mt * mt * mt * startPoint.y
                + 3 * mt * mt * t * c1.y
                + 3 * mt * t * t * c2.y
                + t * t * t * endPoint.y
        };
    });

    for (let index = 0; index < points.length - 1; index += 1) {
        const start = points[index];
        const end = points[index + 1];
        addFilledBarSegment(
            dxf,
            "ACERO_LONGITUDINAL",
            start.x,
            start.y,
            end.x,
            end.y,
            barRadius,
            DXF_REBAR_SOLID_COLOR,
            { ...styleOptions, roundStart: false, roundEnd: false, drawFlatCaps: false }
        );
    }
}

function drawColumnElevationContinuousLongitudinalBars(dxf, lowerBars, upperBars, options = {}) {
    const resolvedLowerBars = Array.isArray(lowerBars) ? lowerBars.filter((bar) => Number.isFinite(bar?.x)) : [];
    const resolvedUpperBars = Array.isArray(upperBars) && upperBars.length
        ? upperBars.filter((bar) => Number.isFinite(bar?.x))
        : resolvedLowerBars;
    const bottomY = parseNumberOrFallback(options.bottomY, Number.NaN);
    const slabBottom = parseNumberOrFallback(options.slabBottom, Number.NaN);
    const upperStartY = parseNumberOrFallback(options.upperStartY, Number.NaN);
    if (!resolvedLowerBars.length || !resolvedUpperBars.length || !Number.isFinite(bottomY)
        || !Number.isFinite(slabBottom) || !Number.isFinite(upperStartY)) {
        return;
    }

    const styleOptions = getColumnElevationLongitudinalStyleOptions();
    resolvedLowerBars.forEach((lowerBar, index) => {
        const pairedUpperIndex = resolvedLowerBars.length <= 1 || resolvedUpperBars.length <= 1
            ? 0
            : Math.round((index / (resolvedLowerBars.length - 1)) * (resolvedUpperBars.length - 1));
        const upperBar = resolvedUpperBars[Math.min(Math.max(pairedUpperIndex, 0), resolvedUpperBars.length - 1)] || lowerBar;
        const barRadius = Math.max(
            parsePositiveNumberOrFallback(lowerBar.radius ?? upperBar.radius, DXF_REBAR_2D_RADIUS, 0.001),
            0.001
        );

        if (slabBottom > bottomY + EDGE_TOLERANCE) {
            addFilledBarSegment(
                dxf,
                "ACERO_LONGITUDINAL",
                lowerBar.x,
                bottomY,
                lowerBar.x,
                slabBottom,
                barRadius,
                DXF_REBAR_SOLID_COLOR,
                { ...styleOptions, roundStart: true, roundEnd: false, drawFlatCaps: false }
            );
        }

        drawColumnElevationSmoothBarCurve(
            dxf,
            { x: lowerBar.x, y: slabBottom },
            { x: upperBar.x, y: upperStartY },
            barRadius,
            styleOptions
        );
    });
}

// Draw the starter bar coming from the upper storey. The 1.00 m lap splice is
// centered in the middle of the central zone, never inside the confinement
// zones. The incoming bar descends through the slab, bends smoothly, and then
// overlaps the lower-storey bar over the centered splice region.
function drawColumnElevationLapSplices(dxf, lowerBars, options = {}) {
    const slabTop = parseNumberOrFallback(options.slabTop, Number.NaN);
    const columnWidth = Math.max(parsePositiveNumberOrFallback(options.columnWidth, 0.1, 0.1), 0.1);
    const lowerClearCover = Math.max(parsePositiveNumberOrFallback(options.clearCover, DRAWING_COVER, 0.01), 0.01);
    const incomingClearCover = Math.max(parsePositiveNumberOrFallback(options.incomingClearCover, lowerClearCover, 0.01), 0.01);
    const resolvedLowerBars = Array.isArray(lowerBars) ? lowerBars.filter((bar) => Number.isFinite(bar?.x)) : [];
    const incomingBars = Array.isArray(options.incomingBars) && options.incomingBars.length
        ? options.incomingBars.filter((bar) => Number.isFinite(bar?.x))
        : resolvedLowerBars;
    const centralZone = options.centralZone || null;
    const spliceRegion = options.spliceRegion || getColumnElevationLapSpliceRegion(centralZone, Math.max(lowerClearCover * 0.45, 0.02));
    if (!Number.isFinite(slabTop) || !spliceRegion || !resolvedLowerBars.length || !incomingBars.length) {
        return;
    }

    const styleOptions = getColumnElevationLongitudinalStyleOptions();
    incomingBars.forEach((incomingBar, index) => {
        const lowerBar = resolvedLowerBars[Math.min(index, resolvedLowerBars.length - 1)];
        const barRadius = Math.max(parsePositiveNumberOrFallback(incomingBar.radius, DXF_REBAR_2D_RADIUS, 0.001), 0.001);
        const directionToCenter = lowerBar.x < options.centerX ? 1 : -1;
        const lateralOffset = Math.min(
            Math.max(0.045, barRadius * 3.6),
            Math.max(columnWidth * 0.16, 0.045)
        );
        const shiftedX = lowerBar.x + directionToCenter * lateralOffset;
        const incomingStartY = slabTop + incomingClearCover;
        const curveStartY = Math.min(
            spliceRegion.availableEndY,
            spliceRegion.topY + Math.max(0.18, Math.abs(shiftedX - incomingBar.x) * 3.0)
        );
        const resolvedCurveStartY = Math.max(curveStartY, spliceRegion.topY + 0.04);

        if (incomingStartY > resolvedCurveStartY + EDGE_TOLERANCE) {
            addFilledBarSegment(
                dxf,
                "ACERO_LONGITUDINAL",
                incomingBar.x,
                incomingStartY,
                incomingBar.x,
                resolvedCurveStartY,
                barRadius,
                DXF_REBAR_SOLID_COLOR,
                { ...styleOptions, roundStart: true, roundEnd: false, drawFlatCaps: false }
            );
        }

        drawColumnElevationSmoothBarCurve(
            dxf,
            { x: incomingBar.x, y: resolvedCurveStartY },
            { x: shiftedX, y: spliceRegion.topY },
            barRadius,
            styleOptions
        );

        addFilledBarSegment(
            dxf,
            "ACERO_LONGITUDINAL",
            shiftedX,
            spliceRegion.topY,
            shiftedX,
            spliceRegion.bottomY,
            barRadius,
            DXF_REBAR_SOLID_COLOR,
            { ...styleOptions, roundStart: false, roundEnd: true, drawFlatCaps: false }
        );
    });
}

function drawColumnElevationBreakSymbol(dxf, layer, left, right, bottom, top, options = {}) {
    const thickness = Math.max(top - bottom, 0);
    if (!(thickness > 0)) {
        return;
    }

    const symbolLayer = options.layer || (layer === "CORTE_SIMBOLO" ? "CONTINUIDAD_SIMBOLO" : (layer || "CONTINUIDAD_SIMBOLO"));
    const drawOpenPolyline = (points) => {
        for (let index = 0; index < points.length - 1; index += 1) {
            const start = points[index];
            const end = points[index + 1];
            addLine(dxf, symbolLayer, start.x, start.y, end.x, end.y);
        }
    };

    // The slab cut symbol is drawn on its own layer and extends 0.10 m
    // beyond the slab faces so the upper vertical leg rises and the lower leg drops.
    drawOpenPolyline(getColumnElevationStyleBreakPoints(left, bottom, top, false, options));
    drawOpenPolyline(getColumnElevationStyleBreakPoints(right, bottom, top, true, options));
}


function drawColumnElevationSlabBoundaryToColumnLines(dxf, layer, slabLeft, slabRight, columnLeft, columnRight, y) {
    if (!hasFiniteNumbers(slabLeft, slabRight, columnLeft, columnRight, y)) {
        return;
    }

    const left = Math.min(slabLeft, slabRight);
    const right = Math.max(slabLeft, slabRight);
    const columnMinX = Math.min(columnLeft, columnRight);
    const columnMaxX = Math.max(columnLeft, columnRight);
    const leftSegmentEnd = Math.min(Math.max(columnMinX, left), right);
    const rightSegmentStart = Math.min(Math.max(columnMaxX, left), right);

    // Draw each slab boundary only up to the column faces so the slab line
    // intersects the column outline without crossing through the column footprint.
    if (leftSegmentEnd > left + EDGE_TOLERANCE) {
        addLine(dxf, layer, left, y, leftSegmentEnd, y);
    }
    if (right > rightSegmentStart + EDGE_TOLERANCE) {
        addLine(dxf, layer, rightSegmentStart, y, right, y);
    }
}

function drawColumnElevationColumnLinesToSlab(dxf, layer, columnLeft, columnRight, startY, slabBottomY) {
    if (!hasFiniteNumbers(columnLeft, columnRight, startY, slabBottomY)) {
        return;
    }

    const bottom = Math.min(startY, slabBottomY);
    const top = Math.max(startY, slabBottomY);
    if (!(top > bottom + EDGE_TOLERANCE)) {
        return;
    }

    // Draw only the visible concrete segment up to the lower slab line.
    // The next level resumes the column from the upper slab line so the
    // slab remains open between its bottom and top boundaries.
    addLine(dxf, layer, columnLeft, bottom, columnLeft, top);
    addLine(dxf, layer, columnRight, bottom, columnRight, top);
}

function drawColumnElevationLevelAnnotations(dxf, entry, labelX, labelTopY, targetX, targetY) {
    if (!entry?.level || !hasFiniteNumbers(labelX, labelTopY, targetX, targetY)) {
        return;
    }

    const levelAnnotation = getFrameLevelAnnotation(entry.level.name, entry.topElevation);
    const noteText = `${levelAnnotation.title} | ${levelAnnotation.subtitle}`;
    const noteTextSize = 0.06;
    // Keep the N.P.T text to the left of its leader so the dashed callout is
    // visibly longer without displacing the arrow away from the slab level.
    const noteTextShiftX = 0;
    const noteArrowShiftX = 3.2;
    const shiftedLabelX = labelX + noteTextShiftX;
    const shiftedTargetX = targetX + noteArrowShiftX;
    const noteTextWidth = estimateDxfTextWidth(noteText, noteTextSize);
    const noteLineStartX = shiftedLabelX + noteTextWidth + 0.08;
    const noteLineEndX = shiftedTargetX - 0.08;
    const noteLineY = targetY + 0.01;
    const noteMarkerX = shiftedTargetX - 0.14;
    const noteArrowHalfWidth = 0.04;
    const noteArrowHeight = 0.08;

    addText(dxf, "SECCION_TEXTO", shiftedLabelX, labelTopY, noteText, noteTextSize);
    addLine(dxf, "COTAS_ALTURAS", noteLineStartX, noteLineY, noteLineEndX, noteLineY, "DASHED2", 0.1);
    addSolid(
        dxf,
        "COTAS_ALTURAS",
        noteMarkerX - noteArrowHalfWidth,
        noteLineY + noteArrowHeight,
        noteMarkerX + noteArrowHalfWidth,
        noteLineY + noteArrowHeight,
        noteMarkerX,
        noteLineY
    );
}

function drawColumnElevationStirrupInfo(dxf, stirrups, longRebar, textX, textY, targetX, targetY) {
    const label = `EST: ${formatColumnTransverseDetailLabel(stirrups, longRebar)}`;
    addText(dxf, "TEXTO_ESTRIBOS", textX, textY, label, COLUMN_SECTION_TEXT_SIZE);
    drawSteelDenotationPolyline(dxf, textX, textY + COLUMN_SECTION_TEXT_SIZE * 0.22, targetX, targetY);
}

function drawColumnElevationSplitStoryDimensions(dxf, dimensionX, startY, endY, originX) {
    const safeStartY = Math.min(startY, endY);
    const safeEndY = Math.max(startY, endY);
    const totalHeight = safeEndY - safeStartY;
    if (!(totalHeight > EDGE_TOLERANCE)) {
        return;
    }

    const firstBreakY = safeStartY + totalHeight * 0.25;
    const secondBreakY = safeStartY + totalHeight * 0.75;
    const segments = [
        [safeStartY, firstBreakY],
        [firstBreakY, secondBreakY],
        [secondBreakY, safeEndY]
    ];

    segments.forEach(([segmentStartY, segmentEndY]) => {
        addVerticalDimension(
            dxf,
            "COTAS_ALTURAS",
            dimensionX,
            segmentStartY,
            segmentEndY,
            (segmentEndY - segmentStartY).toFixed(2),
            originX,
            { visualScale: 0.75 }
        );
    });
}


function getColumnElevationStirrupZones(column, clearStartY, clearEndY, stirrups) {
    const normalized = normalizeColumnTransverseRebar(stirrups, column?.longRebar ?? column?.longitudinalRebar);
    const clearHeight = Math.max(clearEndY - clearStartY, 0);
    const largestColumnDimension = Math.max(getColumnWidth(column), getColumnHeight(column), 0);
    // Both end zones use the governing confinement length: max(Ln/6, largest section dimension, 0.50 m).
    // Clamp only so the two end zones never cross when the free length is short.
    const confinementLength = Math.min(
        Math.max(clearHeight / 6, largestColumnDimension, 0.50),
        clearHeight / 2
    );
    const centralLength = Math.max(clearHeight - confinementLength * 2, 0);
    const centralStirrups = normalized.useCentralZoneSpacing
        ? normalizeTransverseRebar(normalized.centralZone, normalized.spacing)
        : normalizeTransverseRebar(normalized, normalized.spacing);
    const lowerEndY = clearStartY + confinementLength;
    const centralEndY = lowerEndY + centralLength;

    return [
        { key: "lower", startY: clearStartY, endY: lowerEndY, length: confinementLength, stirrups: normalized },
        { key: "central", startY: lowerEndY, endY: centralEndY, length: centralLength, stirrups: centralStirrups },
        { key: "upper", startY: centralEndY, endY: clearEndY, length: confinementLength, stirrups: normalized }
    ].filter((zone) => zone.length > EDGE_TOLERANCE);
}

function getColumnElevationStirrupZoneLabel(stirrups) {
    const normalized = normalizeTransverseRebar(stirrups, DEFAULT_COLUMN_TIE_SPACING);
    return `ESTR.: ${TRANSVERSE_SYMBOL}${formatDxfRebarDiameterLabel(normalized.d)}@${formatFrameElevationStirrupSpacing(normalized.spacing)}`;
}

function drawColumnElevationStirrupZoneDimensions(dxf, zones, dimensionX, anchorX, options = {}) {
    const dimensionLayer = options.dimensionLayer || "COTAS_ALTURAS";
    const visualScale = parsePositiveNumberOrFallback(options.visualScale, 0.78, 0.05);
    const labelX = parseNumberOrFallback(options.labelX, dimensionX - 1.16);
    const textSize = parsePositiveNumberOrFallback(options.textSize, 0.05, 0.01);

    (Array.isArray(zones) ? zones : []).forEach((zone) => {
        if (!(zone?.endY > zone?.startY + EDGE_TOLERANCE)) {
            return;
        }
        addVerticalDimension(
            dxf,
            dimensionLayer,
            dimensionX,
            zone.startY,
            zone.endY,
            zone.length.toFixed(2),
            anchorX,
            { visualScale }
        );
        addText(
            dxf,
            "TEXTO_ESTRIBOS",
            labelX,
            (zone.startY + zone.endY) / 2,
            getColumnElevationStirrupZoneLabel(zone.stirrups),
            textSize
        );
    });
}

function drawColumnElevationOnlySheet(dxf, stack, originY = 0, originX = 0, options = {}) {
    return drawColumnElevationDetailSheet(dxf, stack, originY, originX, options);

    const levels = getColumnElevationDrawableLevels(stack, Array.isArray(projectState.levels) ? projectState.levels : []);
    const totalHeight = levels.reduce((sum, level) => sum + getLevelHeightForQuantities(level), 0);
    const sheetHeight = totalHeight + 3.2;
    const sheetTop = originY + sheetHeight;
    const diagramBaseY = originY + 1.0;
    const diagramTopY = diagramBaseY + totalHeight;
    const titleX = originX + 0.6;
    const labelX = originX + 0.6;
    const diagramLeft = originX + 2.35;
    const diagramRight = originX + 6.65;
    const dimensionX = 7.45;
    const centerX = (diagramLeft + diagramRight) / 2;
    const titleLabel = getColumnElevationTitleLabel(stack);
    const entriesByLevelId = new Map((stack?.entries || []).map((entry) => [entry.level.id, entry]));
    let previousDimensionTopY = null;
    let previousEntryLevelIndex = null;

    addText(dxf, "SECCION_TEXTO", titleX, sheetTop - 0.45, `Detalle en elevaciÃ³n de columnas | ${titleLabel}`, 0.18);
    addText(
        dxf,
        "SECCION_TEXTO",
        titleX,
        sheetTop - 0.72,
        `Continuidad por niveles | ${entriesByLevelId.size} niveles`,
        0.12
    );
    addLine(dxf, DXF_AXIS_LINE_LAYER, centerX, diagramBaseY, centerX, diagramTopY, DXF_AXIS_LINE_TYPE);

    let cursorY = diagramBaseY;
    levels.forEach((level, levelIndex) => {
        const levelHeight = getLevelHeightForQuantities(level);
        const baseY = cursorY;
        const topY = baseY + levelHeight;
        const entry = entriesByLevelId.get(level.id) || null;

        if (entry) {
            const column = entry.column;
            if (isStructuralSteelElement(column)) {
                const profile = getDxfSteelProfileForColumn(column);
                const profileWidth = Math.max(getDxfSteelProfileWidth(profile), getColumnWidth(column), 0.05);
                const columnLeft = centerX - profileWidth / 2;
                const columnRight = centerX + profileWidth / 2;
                const slabThickness = getColumnElevationSlabThickness(level, column.x, column.y);
                const slabWidth = Math.min(
                    getColumnElevationSlabFragmentWidth(stack),
                    Math.max(diagramRight - diagramLeft - 0.2, profileWidth + 0.4)
                );
                const slabLeft = centerX - slabWidth / 2;
                const slabRight = centerX + slabWidth / 2;
                const slabBottom = topY - slabThickness / 2;
                const slabTop = slabBottom + slabThickness;
                const nextLevel = levels[levelIndex + 1] || null;
                const nextEntry = nextLevel ? (entriesByLevelId.get(nextLevel.id) || null) : null;
                const upperColumn = nextEntry?.column || column;
                const upperProfile = getDxfSteelProfileForColumn(upperColumn);
                const upperWidth = Math.max(getDxfSteelProfileWidth(upperProfile), getColumnWidth(upperColumn), 0.05);
                const upperColumnLeft = centerX - upperWidth / 2;
                const upperColumnRight = centerX + upperWidth / 2;
                const dimensionStartY = previousEntryLevelIndex === levelIndex - 1 && Number.isFinite(previousDimensionTopY)
                    ? previousDimensionTopY
                    : baseY;
                const clearHeight = Math.max(slabBottom - dimensionStartY, 0);
                const dimensionX = columnLeft - 1.20;

                drawColumnElevationSlabBoundaryToColumnLines(dxf, "COTAS_SECCION", slabLeft, slabRight, columnLeft, columnRight, slabBottom);
                drawColumnElevationSlabBoundaryToColumnLines(dxf, "COTAS_SECCION", slabLeft, slabRight, upperColumnLeft, upperColumnRight, slabTop);
                drawColumnElevationBreakSymbol(dxf, "CORTE_SIMBOLO", slabLeft, slabRight, slabBottom, slabTop);
                drawColumnElevationColumnLinesToSlab(dxf, "PERFILES_METALICOS", columnLeft, columnRight, dimensionStartY, slabBottom);

                if (isDxfRectangularHssProfile(profile)) {
                    const wallThickness = Math.min(getDxfSteelProfileWallThickness(profile), profileWidth / 2 - 0.0001);
                    if (wallThickness > EDGE_TOLERANCE) {
                        addLine(dxf, "SECCION_CORTE", columnLeft + wallThickness, dimensionStartY, columnLeft + wallThickness, slabBottom);
                        addLine(dxf, "SECCION_CORTE", columnRight - wallThickness, dimensionStartY, columnRight - wallThickness, slabBottom);
                    }
                } else {
                    const parts = getDxfWideFlangeProfileDrawingParts(profile, profileWidth, 1);
                    const webLeft = centerX - parts.webT / 2;
                    const webRight = centerX + parts.webT / 2;
                    addLine(dxf, "SECCION_CORTE", webLeft, dimensionStartY, webLeft, slabBottom);
                    addLine(dxf, "SECCION_CORTE", webRight, dimensionStartY, webRight, slabBottom);
                }

                const profileName = normalizeTextValue(profile?.name || column.sourceSection || column.name || "PERFIL");
                const thickness = getDxfSteelProfileWallThickness(profile);
                addText(
                    dxf,
                    "SECCION_TEXTO",
                    columnRight + 0.18,
                    dimensionStartY + Math.max(clearHeight * 0.55, 0.25),
                    `${profileName}${thickness > EDGE_TOLERANCE ? ` | t=${formatLengthForUnit(thickness, "section")}` : ""}`,
                    0.08
                );
                drawColumnElevationLevelAnnotations(dxf, entry, labelX, slabTop + 0.16, diagramLeft, slabTop);
                addVerticalDimension(
                    dxf,
                    "COTAS_ALTURAS",
                    dimensionX,
                    dimensionStartY,
                    slabBottom,
                    clearHeight.toFixed(2),
                    columnLeft,
                    { visualScale: 0.9 }
                );
                addVerticalDimension(
                    dxf,
                    "COTAS_ALTURAS",
                    dimensionX,
                    slabBottom,
                    slabTop,
                    slabThickness.toFixed(2),
                    columnLeft,
                    { visualScale: 0.9 }
                );

                previousDimensionTopY = slabTop;
                previousEntryLevelIndex = levelIndex;
                cursorY = topY;
                return;
            }
            const columnWidth = Math.max(getColumnWidth(column), 0.1);
            const columnLeft = centerX - columnWidth / 2;
            const slabThickness = getColumnElevationSlabThickness(level, column.x, column.y);
            const slabTop = topY;
            const slabBottom = Math.max(slabTop - slabThickness, baseY + 0.05);
            const columnTop = Math.max(slabBottom, baseY + 0.05);
            const columnHeight = Math.max(columnTop - baseY, 0.05);
            const slabWidth = Math.min(
                getColumnElevationSlabFragmentWidth(stack),
                Math.max(diagramRight - diagramLeft - 0.2, columnWidth + 0.4)
            );
            const slabLeft = centerX - slabWidth / 2;
            const slabRight = centerX + slabWidth / 2;
            const longRebar = normalizeColumnLongitudinalRebar(column.longRebar ?? column.longitudinalRebar);
            const stirrups = ensureColumnTransverseRebar(column, longRebar);
            const cover = Math.min(
                Math.max(parsePositiveNumberOrFallback(stirrups.cover, DRAWING_COVER, 0.01), 0.01),
                Math.max(columnWidth / 2 - 0.02, 0.01)
            );
            const barBottom = baseY + cover;
            const barTop = slabTop - cover;
            const stirrupBottom = baseY + cover;
            const stirrupTop = Math.max(columnTop - cover, stirrupBottom + 0.05);
            const stirrupSpacing = parsePositiveNumberOrFallback(stirrups.spacing, DEFAULT_COLUMN_TIE_SPACING, 0.05);
            const stirrupPositions = getMarkerPositions(
                stirrupBottom,
                stirrupTop,
                stirrupSpacing,
                Math.min(Math.max(stirrupSpacing * 0.55, cover * 1.4), 0.25)
            );
            const barXs = getColumnElevationLongitudinalBarXs(column, columnLeft, columnWidth, longRebar);
            const storyDimensionX = 1.08;
            const slabDimensionX = 1.52;
            const columnRight = columnLeft + columnWidth;
            const nextLevel = levels[levelIndex + 1] || null;
            const nextEntry = nextLevel ? (entriesByLevelId.get(nextLevel.id) || null) : null;
            const upperColumn = nextEntry?.column || column;
            const upperColumnWidth = Math.max(getColumnWidth(upperColumn), 0.1);
            const upperColumnLeft = centerX - upperColumnWidth / 2;
            const upperColumnRight = upperColumnLeft + upperColumnWidth;
            const columnStartY = previousEntryLevelIndex === levelIndex - 1 && Number.isFinite(previousDimensionTopY)
                ? previousDimensionTopY
                : baseY;

            // Lower column lines must stop at the lower slab line, while the upper slab
            // line must extend until it meets the column lines of the level above.
            drawColumnElevationSlabBoundaryToColumnLines(dxf, "COTAS_SECCION", slabLeft, slabRight, columnLeft, columnRight, slabBottom);
            drawColumnElevationSlabBoundaryToColumnLines(dxf, "COTAS_SECCION", slabLeft, slabRight, upperColumnLeft, upperColumnRight, slabTop);
            drawColumnElevationBreakSymbol(dxf, "CORTE_SIMBOLO", slabLeft, slabRight, slabBottom, slabTop);
            drawColumnElevationColumnLinesToSlab(dxf, "CONCRETO_COLUMNAS", columnLeft, columnRight, columnStartY, slabBottom);

            stirrupPositions.forEach((y) => {
                addLine(dxf, "ACERO_TRANSVERSAL", columnLeft + cover, y, columnLeft + columnWidth - cover, y);
            });

            barXs.forEach((x) => {
                addLine(dxf, "ACERO_SUPERIOR", x, barBottom, x, barTop);
            });

            drawColumnElevationLevelAnnotations(dxf, entry, labelX, slabTop + 0.16, diagramLeft, slabTop);
            drawColumnElevationStirrupInfo(
                dxf,
                stirrups,
                longRebar,
                columnRight + 0.28,
                baseY + columnHeight * 0.50,
                columnLeft + columnWidth * 0.50,
                stirrupBottom + (stirrupTop - stirrupBottom) * 0.50
            );
            drawColumnElevationSplitStoryDimensions(
                dxf,
                storyDimensionX,
                baseY,
                topY,
                diagramLeft
            );
            addVerticalDimension(
                dxf,
                "COTAS_ALTURAS",
                slabDimensionX,
                slabBottom,
                slabTop,
                slabThickness.toFixed(2),
                diagramLeft,
                { visualScale: 0.75 }
            );
            previousDimensionTopY = slabTop;
            previousEntryLevelIndex = levelIndex;
        }

        cursorY = topY;
    });

    return {
        height: sheetHeight
    };
}

function drawColumnElevationDetailSheet(dxf, stack, originY = 0, originX = 0, options = {}) {
    const columnElevationPreferences = normalizeColumnElevationDrawingPreferences(options.columnElevationPreferences ?? options.drawingPreferences);
    const showLapSplices = columnElevationPreferences.showLapSplices !== false;
    const levels = getColumnElevationDrawableLevels(stack, Array.isArray(projectState.levels) ? projectState.levels : []);
    const totalHeight = levels.reduce((sum, level) => sum + getLevelHeightForQuantities(level), 0);
    const sheetHeight = totalHeight + 3.2;
    const diagramBaseY = originY + 1.0;
    const diagramTopY = diagramBaseY + totalHeight;
    const titleX = originX + 0.6;
    const labelX = originX + 0.6;
    const diagramLeft = originX + 2.35;
    const diagramRight = originX + 6.65;
    const centerX = (diagramLeft + diagramRight) / 2;
    const titleLabel = getColumnElevationTitleLabel(stack);
    const entriesByLevelId = new Map((stack?.entries || []).map((entry) => [entry.level.id, entry]));
    const bottomTitleText = projectState.language === "en"
        ? `COLUMN DETAIL ${titleLabel}`
        : `Detalle de columna ${titleLabel}`;

    addLine(dxf, DXF_AXIS_LINE_LAYER, centerX, diagramBaseY, centerX, diagramTopY, DXF_AXIS_LINE_TYPE);

    // Overall clear-storey dimensions and the three confinement/central-zone
    // dimensions use separate chains. The final X positions are resolved per
    // column below so zone dimensions always sit closer to the column.
    let previousDimensionTopY = null;
    let previousEntryLevelIndex = null;

    let cursorY = diagramBaseY;
    levels.forEach((level, levelIndex) => {
        const levelHeight = getLevelHeightForQuantities(level);
        const baseY = cursorY;
        const topY = baseY + levelHeight;
        const entry = entriesByLevelId.get(level.id) || null;

        if (entry) {
            const column = entry.column;
            const columnWidth = Math.max(getColumnWidth(column), 0.1);
            const columnLeft = centerX - columnWidth / 2;
            const columnRight = columnLeft + columnWidth;
            const slabThickness = getColumnElevationSlabThickness(level, column.x, column.y);
            const slabWidth = Math.min(
                getColumnElevationSlabFragmentWidth(stack),
                Math.max(diagramRight - diagramLeft - 0.2, columnWidth + 0.4)
            );
            const slabLeft = centerX - slabWidth / 2;
            const slabRight = centerX + slabWidth / 2;
            const slabBottom = topY - slabThickness / 2;
            const slabTop = slabBottom + slabThickness;
            const longRebar = normalizeColumnLongitudinalRebar(column.longRebar ?? column.longitudinalRebar);
            const stirrups = ensureColumnTransverseRebar(column, longRebar);
            const cover = Math.min(
                Math.max(parsePositiveNumberOrFallback(stirrups.cover, DRAWING_COVER, 0.01), 0.01),
                Math.max(columnWidth / 2 - 0.02, 0.01)
            );
            const nextLevel = levels[levelIndex + 1] || null;
            const nextEntry = nextLevel ? (entriesByLevelId.get(nextLevel.id) || null) : null;
            const upperColumn = nextEntry?.column || column;
            const upperColumnWidth = Math.max(getColumnWidth(upperColumn), 0.1);
            const upperColumnLeft = centerX - upperColumnWidth / 2;
            const upperColumnRight = upperColumnLeft + upperColumnWidth;
            const upperLongRebar = nextEntry
                ? normalizeColumnLongitudinalRebar(upperColumn.longRebar ?? upperColumn.longitudinalRebar)
                : longRebar;
            const upperStirrups = nextEntry
                ? ensureColumnTransverseRebar(upperColumn, upperLongRebar)
                : stirrups;
            const dimensionStartY = previousEntryLevelIndex === levelIndex - 1 && Number.isFinite(previousDimensionTopY)
                ? previousDimensionTopY
                : baseY;
            // With lap splices enabled, each storey gets its own lower bars and
            // the starter bars from the storey above overlap them in the central zone.
            // With lap splices disabled, each bar runs continuously through the slab
            // and joins the bar layout of the level above without a duplicated lap.
            const stirrupZones = getColumnElevationStirrupZones(column, dimensionStartY, slabBottom, stirrups);
            const centralZone = stirrupZones.find((zone) => zone.key === "central") || null;
            const lapSpliceRegion = showLapSplices && nextEntry
                ? getColumnElevationLapSpliceRegion(centralZone, Math.max(cover * 0.45, 0.02))
                : null;
            const terminalHookY = slabTop - Math.max(cover, 0.02);
            const barBottom = dimensionStartY + cover;
            const barTop = lapSpliceRegion
                ? lapSpliceRegion.topY
                : terminalHookY;
            const longitudinalBars = getColumnElevationLongitudinalBars(
                column,
                columnLeft,
                columnWidth,
                stirrups,
                longRebar
            );
            const upperLongitudinalBars = nextEntry
                ? getColumnElevationLongitudinalBars(
                    upperColumn,
                    upperColumnLeft,
                    upperColumnWidth,
                    upperStirrups,
                    upperLongRebar
                )
                : longitudinalBars;
            const clearHeight = Math.max(slabBottom - dimensionStartY, 0);
            // Zone dimensions must be the inner chain, nearest the column.
            // Leave enough room on their right for the horizontal stirrup labels
            // while keeping the full clear-storey dimensions on the outer chain.
            const zoneDimensionX = columnLeft - 1.55;
            const dimensionX = columnLeft - 1.80;

            drawColumnElevationSlabBoundaryToColumnLines(dxf, "COTAS_SECCION", slabLeft, slabRight, columnLeft, columnRight, slabBottom);
            drawColumnElevationSlabBoundaryToColumnLines(dxf, "COTAS_SECCION", slabLeft, slabRight, upperColumnLeft, upperColumnRight, slabTop);
            drawColumnElevationBreakSymbol(dxf, "CORTE_SIMBOLO", slabLeft, slabRight, slabBottom, slabTop);
            drawColumnElevationColumnLinesToSlab(dxf, "CONCRETO_COLUMNAS", columnLeft, columnRight, dimensionStartY, slabBottom);

            stirrupZones.forEach((zone) => {
                const zoneStart = Math.max(zone.startY + cover, dimensionStartY + cover);
                const upperStirrupTerminationY = slabTop - Math.max(cover * 0.35, 0.02);
                const zoneEnd = zone.key === "upper"
                    ? Math.max(zoneStart, upperStirrupTerminationY)
                    : Math.min(zone.endY - cover, slabBottom - cover);
                const zoneSpacing = parsePositiveNumberOrFallback(zone.stirrups?.spacing, DEFAULT_COLUMN_TIE_SPACING, 0.05);
                const stirrupPositions = getMarkerPositions(
                    zoneStart,
                    zoneEnd,
                    zoneSpacing,
                    Math.min(Math.max(zoneSpacing * 0.55, cover * 1.4), 0.25)
                );
                drawColumnElevationStirrups(
                    dxf,
                    columnLeft,
                    columnRight,
                    cover,
                    zone.stirrups,
                    stirrupPositions
                );
            });

            if (nextEntry) {
                if (showLapSplices) {
                    drawColumnElevationLongitudinalBars(dxf, longitudinalBars, barBottom, barTop);
                } else {
                    drawColumnElevationContinuousLongitudinalBars(dxf, longitudinalBars, upperLongitudinalBars, {
                        bottomY: barBottom,
                        slabBottom,
                        slabTop,
                        upperStartY: slabTop + getColumnSectionClearCover(upperStirrups)
                    });
                }
            } else {
                drawColumnElevationLongitudinalBarsWithTopTermination(dxf, longitudinalBars, barBottom, barTop, 0.20, centerX);
            }

            // When another storey exists above, center the 1.00 m lap splice in
            // the middle of the central zone. The upper bars come down through the
            // slab, bend gently, and overlap the lower-storey bars without placing
            // the splice in either confinement zone.
            if (showLapSplices && nextEntry && lapSpliceRegion && centralZone) {
                drawColumnElevationLapSplices(dxf, longitudinalBars, {
                    slabTop,
                    columnWidth,
                    clearCover: cover,
                    incomingBars: upperLongitudinalBars,
                    incomingClearCover: getColumnSectionClearCover(upperStirrups),
                    centerX,
                    centralZone,
                    spliceRegion: lapSpliceRegion
                });
            }

            drawColumnElevationLevelAnnotations(dxf, entry, labelX, slabTop + 0.16, diagramLeft, slabTop);
            drawColumnElevationStirrupZoneDimensions(dxf, stirrupZones, zoneDimensionX, columnLeft, {
                visualScale: 0.78,
                // Place the ESTR. note immediately to the right of the zone dimension chain.
                labelX: zoneDimensionX + 0.12,
                textSize: 0.05
            });
            addVerticalDimension(
                dxf,
                "COTAS_ALTURAS",
                dimensionX,
                dimensionStartY,
                slabBottom,
                clearHeight.toFixed(2),
                columnLeft,
                { visualScale: 0.9 }
            );
            addVerticalDimension(
                dxf,
                "COTAS_ALTURAS",
                dimensionX,
                slabBottom,
                slabTop,
                slabThickness.toFixed(2),
                columnLeft,
                { visualScale: 0.9 }
            );

            previousDimensionTopY = slabTop;
            previousEntryLevelIndex = levelIndex;
        }

        cursorY = topY;
    });

    drawDetailTitleMarker(dxf, titleX + 0.35, originY + 0.45, titleLabel, "E-00", bottomTitleText);

    return {
        height: sheetHeight,
        width: 7.25
    };
}

/* SERVER_ONLY_END */

function getWallDetailBoxSize(wall) {
    const normalizedWall = normalizeWall(wall);
    if (normalizedWall.material === "masonry") {
        return {
            sectionWidth: 3.4,
            sectionHeight: 2.1,
            width: 5.8,
            height: 6.1
        };
    }

    return {
        sectionWidth: 3.0,
        sectionHeight: 3.6,
        width: 5.8,
        height: 6.1
    };
}

function getRepresentativeSpacingPositions(start, end, spacing, edgeOffset = 0, minimumCount = 2, maximumCount = 18) {
    const clearStart = start + edgeOffset;
    const clearEnd = end - edgeOffset;
    const span = clearEnd - clearStart;
    if (span <= 0.01) {
        return [(start + end) / 2];
    }

    const normalizedSpacing = parsePositiveNumberOrFallback(spacing, 0.2, 0.05);
    const rawCount = Math.floor(span / normalizedSpacing) + 1;
    const count = Math.max(minimumCount, Math.min(rawCount, maximumCount));
    if (count <= 1) {
        return [(clearStart + clearEnd) / 2];
    }

    return Array.from({ length: count }, (_, index) => (
        clearStart + ((clearEnd - clearStart) * index) / (count - 1)
    ));
}

function getCellBarPositions(count, left, bottom, right, top, radius) {
    const total = Math.max(Number.parseInt(count, 10) || 1, 1);
    const rows = total > 2 ? 2 : 1;
    const firstRowCount = Math.ceil(total / rows);
    const secondRowCount = total - firstRowCount;
    const positions = [];
    const yPositions = rows === 1
        ? [(bottom + top) / 2]
        : [top - radius * 1.6, bottom + radius * 1.6];

    getBarLayoutPositions(firstRowCount, left, right, radius).forEach((x) => {
        positions.push({ x, y: yPositions[0] });
    });

    if (secondRowCount > 0) {
        getBarLayoutPositions(secondRowCount, left, right, radius).forEach((x) => {
            positions.push({ x, y: yPositions[1] });
        });
    }

    return positions;
}

function drawWallPreviewCard(context, entry, x, y, width, height) {
    const wall = normalizeWall(entry.wall);
    drawDetailPreviewCardFrame(context, x, y, width, height, `Muro ${entry.tag}`, `${entry.levelName} | ${getWallMaterialDisplayLabel(wall.material)}`);

    context.save();
    context.strokeStyle = "#334155";
    context.lineWidth = 1.4;

    if (wall.material === "concrete") {
        const left = x + 28;
        const top = y + 58;
        const sectionWidth = width - 56;
        const sectionHeight = 112;
        const right = left + sectionWidth;
        const bottom = top + sectionHeight;
        const verticalXs = getWallRebarLayoutPositions(wall.concrete, "longitudinal", left, right, wall.concrete.longitudinalSpacing, 12, 2, 16);
        const horizontalYs = getWallRebarLayoutPositions(wall.concrete, "transverse", top, bottom, wall.concrete.transverseSpacing, 12, 2, 18);
        const longLineWidth = Math.max(parseDiameterInMeters(wall.concrete.longitudinalDiameter) * 120, 1.5);
        const transLineWidth = Math.max(parseDiameterInMeters(wall.concrete.transverseDiameter) * 120, 1.2);

        context.strokeRect(left, top, sectionWidth, sectionHeight);
        context.strokeStyle = "#000000";
        context.lineWidth = longLineWidth;
        verticalXs.forEach((barX) => {
            context.beginPath();
            context.moveTo(barX, top + 10);
            context.lineTo(barX, bottom - 10);
            context.stroke();
        });
        context.strokeStyle = "#0ea5e9";
        context.lineWidth = transLineWidth;
        horizontalYs.forEach((barY) => {
            context.beginPath();
            context.moveTo(left + 10, barY);
            context.lineTo(right - 10, barY);
            context.stroke();
        });

        context.fillStyle = "#17202a";
        context.font = '11px "Segoe UI", sans-serif';
        context.fillText(`e = ${wall.b.toFixed(2)}m`, x + 14, y + height - 56);
        context.fillText(`${formatDxfWallRebarLayoutLabel(wall.concrete, "longitudinal")}`, x + 14, y + height - 38);
        context.fillText(`${formatDxfWallRebarLayoutLabel(wall.concrete, "transverse")}`, x + 14, y + height - 20);
    } else {
        const left = x + 28;
        const top = y + 70;
        const outerWidth = width - 56;
        const outerHeight = 86;
        const cellGap = 10;
        const cellWidth = (outerWidth - cellGap) / 2;
        const fillRight = isMasonryCellReinforced(wall.masonry.fillMode, 1);

        context.strokeRect(left, top, outerWidth, outerHeight);
        context.beginPath();
        context.moveTo(left + cellWidth + cellGap / 2, top);
        context.lineTo(left + cellWidth + cellGap / 2, top + outerHeight);
        context.stroke();

        context.fillStyle = "rgba(148, 163, 184, 0.35)";
        context.fillRect(left + 2, top + 2, cellWidth - 4, outerHeight - 4);
        if (fillRight) {
            context.fillRect(left + cellWidth + cellGap + 2, top + 2, cellWidth - 4, outerHeight - 4);
        }

        context.fillStyle = "#000000";
        const radius = 4;
        const leftBars = getCellBarPositions(wall.masonry.barsPerCell, left + 10, top + 10, left + cellWidth - 10, top + outerHeight - 10, radius);
        const rightBars = getCellBarPositions(wall.masonry.barsPerCell, left + cellWidth + cellGap + 10, top + 10, left + outerWidth - 10, top + outerHeight - 10, radius);
        leftBars.forEach((position) => {
            context.beginPath();
            context.arc(position.x, position.y, radius, 0, Math.PI * 2);
            context.fill();
        });
        if (fillRight) {
            rightBars.forEach((position) => {
                context.beginPath();
                context.arc(position.x, position.y, radius, 0, Math.PI * 2);
                context.fill();
            });
        }

        context.fillStyle = "#17202a";
        context.font = '11px "Segoe UI", sans-serif';
        context.fillText(`e = ${wall.b.toFixed(2)}m`, x + 14, y + height - 56);
        context.fillText(getMasonryFillModeLabel(wall.masonry.fillMode), x + 14, y + height - 38);
        context.fillText(`${wall.masonry.barsPerCell} barras/cámara ${TRANSVERSE_SYMBOL}${formatDxfRebarDiameterLabel(wall.masonry.barDiameter)}`, x + 14, y + height - 20);
    }

    context.restore();
}

/* SERVER_ONLY_START */
function drawWallSectionDetail(dxf, detail, originX, originY, detailSize) {
    const wall = normalizeWall(detail.wall);
    if (wall.material === "masonry") {
        drawMasonryWallDetail(dxf, detail, originX, originY, detailSize);
        return;
    }

    drawConcreteWallDetail(dxf, detail, originX, originY, detailSize);
}

function drawConcreteWallDetail(dxf, detail, originX, originY, detailSize) {
    const wall = normalizeWall(detail.wall);
    const sectionWidth = detailSize.sectionWidth;
    const sectionHeight = detailSize.sectionHeight;
    const left = originX + 0.45;
    const bottom = originY - sectionHeight - 1.05;
    const right = left + sectionWidth;
    const top = bottom + sectionHeight;
    const verticalXs = getRepresentativeSpacingPositions(left, right, wall.concrete.longitudinalSpacing, 0.24, 2, 16);
    const horizontalYs = getRepresentativeSpacingPositions(bottom, top, wall.concrete.transverseSpacing, 0.24, 2, 18);

    addText(dxf, "SECCION_TEXTO", left, top + 0.7, `MURO ${detail.tag}`, WALL_DETAIL_TEXT_SIZE);
    addText(dxf, "SECCION_TEXTO", left, top + 0.42, `${detail.levelName} | Concreto`, WALL_DETAIL_TEXT_SIZE);
    addPolylineRectangle(dxf, "CONCRETO_MUROS", left, bottom, sectionWidth, sectionHeight);

    verticalXs.forEach((x) => addPolylineLine(dxf, "ACERO_MURO_LONG", x, bottom + 0.18, x, top - 0.18, { color: 7 }));
    horizontalYs.forEach((y) => addPolylineLine(dxf, "ACERO_MURO_TRANS", left + 0.18, y, right - 0.18, y));

    addText(dxf, "SECCION_TEXTO", left, bottom - 0.65, formatWallSectionText(wall), WALL_DETAIL_TEXT_SIZE);
    addText(dxf, "TEXTO_ACERO", left, bottom - 0.9, formatDxfWallRebarLayoutLabel(wall.concrete, "longitudinal"), WALL_DETAIL_TEXT_SIZE);
    addText(dxf, "TEXTO_ESTRIBOS", left, bottom - 1.15, formatDxfWallRebarLayoutLabel(wall.concrete, "transverse"), WALL_DETAIL_TEXT_SIZE);
}

function drawMasonryWallDetail(dxf, detail, originX, originY, detailSize) {
    const wall = normalizeWall(detail.wall);
    const sectionWidth = detailSize.sectionWidth;
    const sectionHeight = detailSize.sectionHeight;
    const left = originX + 0.45;
    const bottom = originY - sectionHeight - 1.05;
    const right = left + sectionWidth;
    const top = bottom + sectionHeight;
    const cellCount = 3;
    const cellGap = 0.10;
    const cellWidth = (sectionWidth - cellGap * (cellCount - 1)) / cellCount;
    const fillMode = normalizeMasonryFillMode(wall.masonry.fillMode);
    const radius = getRebarDrawRadius(wall.masonry.barDiameter);

    addText(dxf, "SECCION_TEXTO", left, top + 0.7, `MURO ${detail.tag}`, WALL_DETAIL_TEXT_SIZE);
    addText(dxf, "SECCION_TEXTO", left, top + 0.42, `${detail.levelName} | Mampostería`, WALL_DETAIL_TEXT_SIZE);
    addPolylineRectangle(dxf, "MAMPOSTERIA_MUROS", left, bottom, sectionWidth, sectionHeight);

    for (let cellIndex = 0; cellIndex < cellCount; cellIndex += 1) {
        const cellLeft = left + cellIndex * (cellWidth + cellGap);
        const cellRight = cellLeft + cellWidth;
        if (cellIndex > 0) {
            const separatorX = cellLeft - cellGap / 2;
            addPolylineLine(dxf, "MAMPOSTERIA_MUROS", separatorX, bottom, separatorX, top);
        }
        if (!isMasonryCellReinforced(fillMode, cellIndex)) {
            continue;
        }
        addMasonryReferenceHatch(dxf, "MAMPOSTERIA_MUROS", [
            { x: cellLeft + 0.05, y: bottom + 0.05 },
            { x: cellRight - 0.05, y: bottom + 0.05 },
            { x: cellRight - 0.05, y: top - 0.05 },
            { x: cellLeft + 0.05, y: top - 0.05 }
        ], {
            patternName: MASONRY_ELEVATION_HATCH_PATTERN,
            patternScale: MASONRY_ELEVATION_HATCH_SCALE,
            patternAngle: 0,
            color: 8
        });
        getCellBarPositions(wall.masonry.barsPerCell, cellLeft + 0.16, bottom + 0.18, cellRight - 0.16, top - 0.18, radius)
            .forEach((position) => addFilledCircle(dxf, "ACERO_MURO_LONG", position.x, position.y, radius));
    }

    addText(dxf, "SECCION_TEXTO", left, bottom - 0.65, formatWallSectionText(wall), WALL_DETAIL_TEXT_SIZE);
    addText(dxf, "SECCION_TEXTO", left, bottom - 0.9, getMasonryFillModeLabel(fillMode), WALL_DETAIL_TEXT_SIZE);
    addText(dxf, "TEXTO_ACERO", left, bottom - 1.15, `${wall.masonry.barsPerCell} barras/cámara ${TRANSVERSE_SYMBOL}${formatDxfRebarDiameterLabel(wall.masonry.barDiameter)}`, WALL_DETAIL_TEXT_SIZE);
}
/* SERVER_ONLY_END */

function drawPreview(selection) {
    const previewContext = dom.previewCanvas.getContext("2d");
    dom.previewCanvas.width = dom.previewCanvas.clientWidth;
    dom.previewCanvas.height = dom.previewCanvas.clientHeight;

    const [type, rawValue] = selection.split("|");
    const value = Number.parseFloat(rawValue);
    const previewScale = 40;
    const previewOffsetX = 100;
    const previewOffsetY = dom.previewCanvas.height - 100;
    const frameContentPlan = getFrameLevelContentPlan(type, value);
    let baseElevation = 0;

    previewContext.clearRect(0, 0, dom.previewCanvas.width, dom.previewCanvas.height);
    previewContext.font = '12px "Segoe UI", sans-serif';

    frameContentPlan.levels.forEach((level) => {
        const topElevation = baseElevation + level.height;
        const beams = frameContentPlan.beamsByLevel.get(level.id) || [];
        const frameSupports = frameContentPlan.mergedSupportsByLevel.get(level.id) || [];
        const levelAnnotation = getFrameLevelAnnotation(level.name, topElevation);
        const levelLineY = previewOffsetY - (topElevation - 0.05) * previewScale;
        const levelTextX = 28;
        const levelTitleWidth = previewContext.measureText(levelAnnotation.title).width;
        const levelSubtitleWidth = previewContext.measureText(levelAnnotation.subtitle).width;
        const levelLineStartX = levelTextX + Math.max(levelTitleWidth, levelSubtitleWidth) + 18;

        previewContext.fillStyle = "#fff";
        previewContext.fillText(levelAnnotation.title, levelTextX, levelLineY - 20);
        previewContext.fillText(levelAnnotation.subtitle, levelTextX, levelLineY - 8);

        frameSupports.forEach((support) => {
            if (!(support.width > 0) || !(support.height > 0)) {
                return;
            }

            const left = previewOffsetX + (support.position - support.width / 2) * previewScale;

            previewContext.strokeStyle = "#555";
            previewContext.lineWidth = 1;
            previewContext.strokeRect(
                left,
                previewOffsetY - topElevation * previewScale,
                support.width * previewScale,
                support.height * previewScale
            );
        });

        if (beams.length > 0) {
            const coordinates = beams
                .map((beam) => (type === "x" ? [beam.y1, beam.y2] : [beam.x1, beam.x2]))
                .flat();
            const coordinateBounds = getNumericArrayBounds(coordinates);
            const minCoordinate = coordinateBounds?.min ?? 0;
            const maxCoordinate = coordinateBounds?.max ?? 0;

            previewContext.save();
            previewContext.strokeStyle = "rgba(255, 255, 255, 0.85)";
            previewContext.lineWidth = 1;
            previewContext.setLineDash([8, 6]);
            previewContext.beginPath();
            previewContext.moveTo(levelLineStartX, levelLineY);
            previewContext.lineTo(previewOffsetX + (maxCoordinate + 0.1) * previewScale, levelLineY);
            previewContext.stroke();
            previewContext.restore();

            previewContext.save();
            previewContext.fillStyle = "#fff";
            previewContext.beginPath();
            previewContext.moveTo(levelLineStartX - 10, levelLineY - 2);
            previewContext.lineTo(levelLineStartX + 6, levelLineY - 2);
            previewContext.lineTo(levelLineStartX - 2, levelLineY + 10);
            previewContext.closePath();
            previewContext.fill();
            previewContext.restore();

            previewContext.strokeStyle = "#00ffff";
            previewContext.lineWidth = 2;
            previewContext.beginPath();
            previewContext.moveTo(previewOffsetX + (minCoordinate - 0.1) * previewScale, previewOffsetY - (topElevation - 0.05) * previewScale);
            previewContext.lineTo(previewOffsetX + (maxCoordinate + 0.1) * previewScale, previewOffsetY - (topElevation - 0.05) * previewScale);
            previewContext.stroke();

            beams.forEach((beam) => {
                const start = type === "x" ? Math.min(beam.y1, beam.y2) : Math.min(beam.x1, beam.x2);
                const end = type === "x" ? Math.max(beam.y1, beam.y2) : Math.max(beam.x1, beam.x2);
                const span = end - start;
                const transverseRebar = ensureTransverseRebar(beam, DEFAULT_BEAM_STIRRUP_SPACING);
                const stirrupPositions = getMarkerPositions(
                    start + DRAWING_COVER,
                    end - DRAWING_COVER,
                    transverseRebar.spacing,
                    Math.min(0.25, (end - start) / 3)
                );

                previewContext.strokeStyle = "#ffff00";
                previewContext.beginPath();
                previewContext.moveTo(previewOffsetX + (start + 0.05) * previewScale, previewOffsetY - (topElevation - beam.h + 0.05) * previewScale);
                previewContext.lineTo(previewOffsetX + (end - 0.05) * previewScale, previewOffsetY - (topElevation - beam.h + 0.05) * previewScale);
                previewContext.stroke();

                previewContext.strokeStyle = "#777";
                previewContext.strokeRect(
                    previewOffsetX + start * previewScale,
                    previewOffsetY - topElevation * previewScale,
                    (end - start) * previewScale,
                    beam.h * previewScale
                );

                previewContext.strokeStyle = "#ff66cc";
                previewContext.lineWidth = 1;
                stirrupPositions.forEach((position) => {
                    previewContext.beginPath();
                    previewContext.moveTo(previewOffsetX + position * previewScale, previewOffsetY - (topElevation - DRAWING_COVER) * previewScale);
                    previewContext.lineTo(previewOffsetX + position * previewScale, previewOffsetY - (topElevation - beam.h + DRAWING_COVER) * previewScale);
                    previewContext.stroke();
                });

                const topTargetX = previewOffsetX + ((start + end) / 2) * previewScale;
                const topTargetY = previewOffsetY - (topElevation - 0.05) * previewScale;
                const bottomTargetX = previewOffsetX + (start + span * 0.32) * previewScale;
                const bottomTargetY = previewOffsetY - (topElevation - beam.h + 0.05) * previewScale;
                const stirrupTargetMetric = getClosestValue(stirrupPositions, start + span * 0.7) ?? ((start + end) / 2);
                const stirrupTargetX = previewOffsetX + stirrupTargetMetric * previewScale;
                const stirrupTargetY = previewOffsetY - (topElevation - beam.h / 2) * previewScale;

                drawPreviewLeaderLabel(
                    previewContext,
                    formatRebar(beam.topRebar),
                    topTargetX,
                    previewOffsetY - (topElevation + 0.45) * previewScale,
                    topTargetX,
                    topTargetY,
                    "above"
                );
                drawPreviewLeaderLabel(
                    previewContext,
                    formatRebar(beam.botRebar),
                    previewOffsetX + (start + span * 0.28) * previewScale,
                    previewOffsetY - (topElevation - beam.h - 0.45) * previewScale,
                    bottomTargetX,
                    bottomTargetY,
                    "below"
                );
                drawPreviewLeaderLabel(
                    previewContext,
                    formatBeamTransverseRebarZones(beam),
                    previewOffsetX + (start + span * 0.74) * previewScale,
                    previewOffsetY - (topElevation - beam.h - 0.85) * previewScale,
                    stirrupTargetX,
                    stirrupTargetY,
                    "below"
                );
            });
        }

        baseElevation += level.height;
    });
}

function drawSlabPreview(selection) {
    const previewContext = dom.previewCanvas.getContext("2d");
    dom.previewCanvas.width = dom.previewCanvas.clientWidth;
    dom.previewCanvas.height = dom.previewCanvas.clientHeight;
    previewContext.clearRect(0, 0, dom.previewCanvas.width, dom.previewCanvas.height);

    const [, rawLevelId] = selection.split("|");
    const levelId = Number.parseInt(rawLevelId, 10);
    const level = projectState.levels.find((item) => item.id === levelId);
    if (!level) {
        return;
    }

    const bounds = getSlabPlanSheetBounds(level);
    const minX = bounds.minX;
    const maxX = bounds.maxX;
    const minY = bounds.minY;
    const maxY = bounds.maxY;
    const width = Math.max(maxX - minX, 1);
    const height = Math.max(maxY - minY, 1);
    const padding = 84;
    const previewScale = Math.min(
        (dom.previewCanvas.width - padding * 2) / width,
        (dom.previewCanvas.height - padding * 2) / height
    );

    const toCanvasX = (x) => padding + (x - minX) * previewScale;
    const toCanvasY = (y) => padding + (y - minY) * previewScale;

    previewContext.fillStyle = "#0d1218";
    previewContext.fillRect(0, 0, dom.previewCanvas.width, dom.previewCanvas.height);
    previewContext.font = '12px "Segoe UI", sans-serif';

    previewContext.strokeStyle = "rgba(173, 184, 194, 0.32)";
    previewContext.lineWidth = 1;
    previewContext.setLineDash([8, 6]);
    bounds.xAxisEntries.forEach((entry) => {
        const x = toCanvasX(entry.value);
        const label = entry.label;
        previewContext.beginPath();
        previewContext.moveTo(x, padding - 24);
        previewContext.lineTo(x, dom.previewCanvas.height - padding + 24);
        previewContext.stroke();
        previewContext.fillStyle = "#f3f7fb";
        previewContext.fillText(label, x - previewContext.measureText(label).width / 2, padding - 34);
    });

    bounds.yAxisEntries.forEach((entry) => {
        const y = toCanvasY(entry.value);
        const label = entry.label;
        previewContext.beginPath();
        previewContext.moveTo(padding - 24, y);
        previewContext.lineTo(dom.previewCanvas.width - padding + 24, y);
        previewContext.stroke();
        previewContext.fillStyle = "#f3f7fb";
        previewContext.fillText(label, padding - 18 - previewContext.measureText(label).width, y + 4);
    });
    previewContext.setLineDash([]);

    level.slabs.forEach((slab) => {
        drawSlabPreviewPanel(previewContext, slab, level.slabs, toCanvasX, toCanvasY, previewScale);
    });
    (level.holes || []).forEach((hole) => {
        drawSlabPreviewPanel(previewContext, hole, level.slabs, toCanvasX, toCanvasY, previewScale);
    });

    previewContext.strokeStyle = "#facc15";
    previewContext.setLineDash([8, 6]);
    level.beams.forEach((beam) => {
        previewContext.lineWidth = Math.max(beam.b * previewScale, 4);
        previewContext.lineCap = "square";
        previewContext.beginPath();
        previewContext.moveTo(toCanvasX(beam.x1), toCanvasY(beam.y1));
        previewContext.lineTo(toCanvasX(beam.x2), toCanvasY(beam.y2));
        previewContext.stroke();
    });
    previewContext.setLineDash([]);

    level.columns.forEach((column) => {
        const normalizedColumn = normalizeColumnModel(column);
        const footprint = getColumnFootprint(normalizedColumn);
        const width = Math.max(footprint.width * previewScale, 10);
        const height = Math.max(footprint.height * previewScale, 10);
        const columnCenterX = toCanvasX(normalizedColumn.x);
        const columnCenterY = toCanvasY(normalizedColumn.y);
        previewContext.fillStyle = "#f2f5f7";
        previewContext.fillRect(
            columnCenterX - width / 2,
            columnCenterY - height / 2,
            width,
            height
        );
        previewContext.strokeStyle = "#0d1218";
        previewContext.lineWidth = 1.5;
        previewContext.strokeRect(
            columnCenterX - width / 2,
            columnCenterY - height / 2,
            width,
            height
        );

        const columnLabel = normalizeTextValue(normalizedColumn.name) || getSmartEntityName("column", normalizedColumn);
        if (columnLabel) {
            previewContext.font = '12px "Segoe UI", sans-serif';
            previewContext.fillStyle = "#f3f7fb";
            previewContext.textAlign = "left";
            previewContext.textBaseline = "bottom";
            previewContext.fillText(columnLabel, columnCenterX + width / 2, columnCenterY - height / 2);
        }
    });

    previewContext.fillStyle = "#f3f7fb";
    previewContext.font = '16px "Segoe UI", sans-serif';
    previewContext.fillText(`Plano de losa | ${level.name}`, padding, 34);
}

function drawSlabPreviewPanel(context, slab, slabs, toCanvasX, toCanvasY, previewScale) {
    const normalizedSlab = normalizeSlab(slab);
    const bounds = normalizeSlabBounds(normalizedSlab);
    const vertices = normalizedSlab.vertices;
    const centroid = getSlabCentroid(normalizedSlab);
    const x = toCanvasX(bounds.x1);
    const y = toCanvasY(bounds.y1);
    const width = (bounds.x2 - bounds.x1) * previewScale;
    const height = (bounds.y2 - bounds.y1) * previewScale;
    const centerX = toCanvasX(centroid.x);
    const centerY = toCanvasY(centroid.y);

    if (normalizedSlab.type === "hole") {
        context.save();
        addClosedCanvasPolygonPath(context, vertices, toCanvasX, toCanvasY);
        context.clip();
        context.clearRect(x - 2, y - 2, width + 4, height + 4);
        context.restore();

        context.save();
        addClosedCanvasPolygonPath(context, vertices, toCanvasX, toCanvasY);
        context.strokeStyle = "rgba(244, 246, 248, 0.92)";
        context.lineWidth = 1.5;
        context.setLineDash([7, 5]);
        context.stroke();
        context.setLineDash([]);
        context.restore();

        context.save();
        context.fillStyle = "#f3f7fb";
        context.font = '11px "Segoe UI", sans-serif';
        context.textAlign = "center";
        context.textBaseline = "middle";
        if (normalizedSlab.name) {
            drawCanvasSlabNameBadge(
                context,
                normalizedSlab.name,
                centerX,
                centerY,
                Math.min(width, height),
                {
                    fillStyle: "rgba(13, 18, 24, 0.9)",
                    strokeStyle: "#f3f7fb",
                    textStyle: "#f3f7fb"
                },
                true
            );
        } else {
            context.fillText(translate("modal.hole"), centerX, centerY);
        }
        context.restore();
        return;
    }

    context.save();
    context.fillStyle = normalizedSlab.type === "lightened" ? "rgba(219, 180, 82, 0.12)" : "rgba(96, 165, 250, 0.12)";
    context.strokeStyle = normalizedSlab.type === "lightened" ? "rgba(227, 186, 86, 0.65)" : "rgba(96, 165, 250, 0.6)";
    context.lineWidth = 1.25;
    addClosedCanvasPolygonPath(context, vertices, toCanvasX, toCanvasY);
    context.fill();
    context.stroke();

    context.save();
    addClosedCanvasPolygonPath(context, vertices, toCanvasX, toCanvasY);
    context.clip();

    if (isSolidSlabType(normalizedSlab.type)) {
        drawSolidSlabPreviewBars(context, normalizedSlab, slabs, toCanvasX, toCanvasY);
        drawSlabTemperatureBars(context, normalizedSlab, toCanvasX, toCanvasY);
    } else if (normalizedSlab.type === "lightened") {
        getLightenedCassetteRects(normalizedSlab).forEach((cassette) => {
            const hatchSegments = getAnsi31RectHatchSegments(cassette.x1, cassette.y1, cassette.x2, cassette.y2);
            context.strokeStyle = "rgba(227, 186, 86, 0.32)";
            context.lineWidth = 0.9;
            hatchSegments.forEach((segment) => {
                context.beginPath();
                context.moveTo(toCanvasX(segment.x1), toCanvasY(segment.y1));
                context.lineTo(toCanvasX(segment.x2), toCanvasY(segment.y2));
                context.stroke();
            });
            context.strokeStyle = "rgba(227, 186, 86, 0.55)";
            context.lineWidth = 1;
            context.strokeRect(
                toCanvasX(cassette.x1),
                toCanvasY(cassette.y1),
                (cassette.x2 - cassette.x1) * previewScale,
                (cassette.y2 - cassette.y1) * previewScale
            );
        });
    }
    context.restore();

    const hasSlabName = Boolean(normalizedSlab.name);
    context.fillStyle = "#f3f7fb";
    context.font = '11px "Segoe UI", sans-serif';
    context.textAlign = "center";
    if (hasSlabName) {
        drawCanvasSlabNameBadge(
            context,
            normalizedSlab.name,
            centerX,
            centerY - 4,
            Math.min(width, height),
            {
                fillStyle: "rgba(13, 18, 24, 0.9)",
                strokeStyle: "#f3f7fb",
                textStyle: "#f3f7fb"
            }
        );
    } else {
        context.fillText(
            normalizedSlab.type === "lightened"
                ? `Aligerada ${normalizedSlab.lightened.cassetteWidth.toFixed(2)}x${normalizedSlab.lightened.cassetteHeight.toFixed(2)} | e ${normalizedSlab.h.toFixed(2)}`
                : "Losa maciza",
            centerX,
            centerY - 8
        );
    }
    context.font = '10px "Segoe UI", sans-serif';
    context.fillText(getSlabDetailNote(normalizedSlab), centerX, centerY + (hasSlabName ? 20 : 10));
    context.restore();
}

function drawSolidSlabPreviewBars(context, slab, slabs, toCanvasX, toCanvasY) {
    const xBars = getSolidSlabRepresentativeBars(slabs, slab, "x");
    const yBars = getSolidSlabRepresentativeBars(slabs, slab, "y");

    context.lineCap = "round";
    context.lineJoin = "round";

    xBars.forEach((bar) => {
        context.strokeStyle = bar.primary ? "rgba(96, 165, 250, 0.82)" : "rgba(96, 165, 250, 0.55)";
        context.lineWidth = bar.primary ? 1.8 : 1.3;
        drawSolidSlabPreviewBar(context, bar, slab, toCanvasX, toCanvasY);
    });

    yBars.forEach((bar) => {
        context.strokeStyle = bar.primary ? "rgba(125, 211, 252, 0.9)" : "rgba(125, 211, 252, 0.58)";
        context.lineWidth = bar.primary ? 1.8 : 1.3;
        drawSolidSlabPreviewBar(context, bar, slab, toCanvasX, toCanvasY);
    });
}

