function drawPreviewLeaderLabel(context, text, labelX, labelY, targetX, targetY, placement, options = {}) {
    const screenScale = getScreenLockedZoomScale(options.screenScale);
    const anchorY = placement === "above" ? labelY + (6 / screenScale) : labelY - (6 / screenScale);
    const textColor = options.textColor || "#ffffff";
    const lineColor = options.lineColor || textColor;

    context.save();
    context.font = `${12 / screenScale}px "Segoe UI", sans-serif`;
    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillStyle = textColor;
    context.strokeStyle = lineColor;
    context.lineWidth = 1 / screenScale;
    context.fillText(text, labelX, labelY);
    drawCanvasLeaderArrow(context, labelX, anchorY, targetX, targetY, 8 / screenScale);
    context.restore();
}

function drawCanvasLeaderArrow(context, x1, y1, x2, y2, arrowSize = 8) {
    const angle = Math.atan2(y2 - y1, x2 - x1);
    const arrowAngle = Math.PI / 7;

    context.beginPath();
    context.moveTo(x1, y1);
    context.lineTo(x2, y2);
    context.stroke();

    context.beginPath();
    context.moveTo(x2, y2);
    context.lineTo(
        x2 - Math.cos(angle - arrowAngle) * arrowSize,
        y2 - Math.sin(angle - arrowAngle) * arrowSize
    );
    context.moveTo(x2, y2);
    context.lineTo(
        x2 - Math.cos(angle + arrowAngle) * arrowSize,
        y2 - Math.sin(angle + arrowAngle) * arrowSize
    );
    context.stroke();
}

/* SERVER_ONLY_START */
function buildFrameDxfExport(selection, exportConfig = {}) {
    const dxf = createBaseDxfDocument();
    drawFrameExportSheet(dxf, selection, {
        originX: 0.6,
        originY: 0,
        includeElevation: true,
        includeSectionDetails: true,
        includeTitle: true,
        drawingPreferences: projectState.exportDock?.drawingPreferences?.frameElevation,
        frameSectionPreferences: projectState.exportDock?.drawingPreferences?.frameSections,
        exportConfig
    });

    return {
        fileName: getFrameExportFileName(selection),
        dxf: finalizeDxfDocument(dxf)
    };
}

function mergeCoordinateIntervals(intervals, tolerance = 1e-6) {
    const safeTolerance = Math.max(Number.isFinite(tolerance) ? tolerance : 1e-6, 1e-6);
    const normalizedIntervals = (Array.isArray(intervals) ? intervals : [])
        .map((interval) => {
            const start = parseNumberOrFallback(interval?.start, NaN);
            const end = parseNumberOrFallback(interval?.end, NaN);
            return {
                start: Math.min(start, end),
                end: Math.max(start, end)
            };
        })
        .filter((interval) => Number.isFinite(interval.start) && Number.isFinite(interval.end) && interval.end > interval.start + safeTolerance)
        .sort((left, right) => (left.start - right.start) || (left.end - right.end));

    const mergedIntervals = [];
    normalizedIntervals.forEach((interval) => {
        const currentInterval = mergedIntervals[mergedIntervals.length - 1];
        if (!currentInterval || interval.start > currentInterval.end + safeTolerance) {
            mergedIntervals.push({ ...interval });
            return;
        }

        currentInterval.end = Math.max(currentInterval.end, interval.end);
    });

    return mergedIntervals;
}

function subtractCoordinateIntervals(start, end, blockedIntervals = [], tolerance = 1e-6) {
    const safeTolerance = Math.max(Number.isFinite(tolerance) ? tolerance : 1e-6, 1e-6);
    const safeStart = Math.min(start, end);
    const safeEnd = Math.max(start, end);

    if (!(safeEnd > safeStart + safeTolerance)) {
        return [];
    }

    const mergedIntervals = mergeCoordinateIntervals(blockedIntervals, safeTolerance);
    const visibleIntervals = [];
    let cursor = safeStart;

    mergedIntervals.forEach((interval) => {
        if (interval.end <= safeStart + safeTolerance || interval.start >= safeEnd - safeTolerance) {
            return;
        }

        const clippedStart = Math.max(interval.start, safeStart);
        const clippedEnd = Math.min(interval.end, safeEnd);
        if (clippedStart > cursor + safeTolerance) {
            visibleIntervals.push({
                start: cursor,
                end: clippedStart
            });
        }

        cursor = Math.max(cursor, clippedEnd);
    });

    if (cursor < safeEnd - safeTolerance) {
        visibleIntervals.push({
            start: cursor,
            end: safeEnd
        });
    }

    return visibleIntervals.filter((interval) => interval.end > interval.start + safeTolerance);
}

function clipSegmentAgainstRectangles(segment, rectangles = [], tolerance = 1e-6) {
    const safeTolerance = Math.max(Number.isFinite(tolerance) ? tolerance : 1e-6, 1e-6);
    const x1 = parseNumberOrFallback(segment?.x1, NaN);
    const y1 = parseNumberOrFallback(segment?.y1, NaN);
    const x2 = parseNumberOrFallback(segment?.x2, NaN);
    const y2 = parseNumberOrFallback(segment?.y2, NaN);

    if (!Number.isFinite(x1) || !Number.isFinite(y1) || !Number.isFinite(x2) || !Number.isFinite(y2)) {
        return [];
    }

    const isHorizontal = Math.abs(y1 - y2) <= safeTolerance;
    const isVertical = Math.abs(x1 - x2) <= safeTolerance;

    if (!isHorizontal && !isVertical) {
        return [{ x1, y1, x2, y2 }];
    }

    const blockedIntervals = [];
    (Array.isArray(rectangles) ? rectangles : []).forEach((rect) => {
        const rectX1 = parseNumberOrFallback(rect?.x1, NaN);
        const rectY1 = parseNumberOrFallback(rect?.y1, NaN);
        const rectX2 = parseNumberOrFallback(rect?.x2, NaN);
        const rectY2 = parseNumberOrFallback(rect?.y2, NaN);

        if (!Number.isFinite(rectX1) || !Number.isFinite(rectY1) || !Number.isFinite(rectX2) || !Number.isFinite(rectY2)) {
            return;
        }

        const left = Math.min(rectX1, rectX2);
        const right = Math.max(rectX1, rectX2);
        const bottom = Math.min(rectY1, rectY2);
        const top = Math.max(rectY1, rectY2);

        if (isVertical) {
            if (x1 < left - safeTolerance || x1 > right + safeTolerance) {
                return;
            }

            const overlapStart = Math.max(Math.min(y1, y2), bottom);
            const overlapEnd = Math.min(Math.max(y1, y2), top);
            if (overlapEnd > overlapStart + safeTolerance) {
                blockedIntervals.push({
                    start: overlapStart,
                    end: overlapEnd
                });
            }
            return;
        }

        if (y1 < bottom - safeTolerance || y1 > top + safeTolerance) {
            return;
        }

        const overlapStart = Math.max(Math.min(x1, x2), left);
        const overlapEnd = Math.min(Math.max(x1, x2), right);
        if (overlapEnd > overlapStart + safeTolerance) {
            blockedIntervals.push({
                start: overlapStart,
                end: overlapEnd
            });
        }
    });

    const primaryStart = isVertical ? Math.min(y1, y2) : Math.min(x1, x2);
    const primaryEnd = isVertical ? Math.max(y1, y2) : Math.max(x1, x2);
    const axisCoordinate = isVertical ? x1 : y1;

    return subtractCoordinateIntervals(primaryStart, primaryEnd, blockedIntervals, safeTolerance)
        .map((interval) => (
            isVertical
                ? { x1: axisCoordinate, y1: interval.start, x2: axisCoordinate, y2: interval.end }
                : { x1: interval.start, y1: axisCoordinate, x2: interval.end, y2: axisCoordinate }
        ));
}

function clipSupportSegmentAgainstBeamRects(segment, beamRects = [], tolerance = 1e-6) {
    return clipSegmentAgainstRectangles(segment, beamRects, tolerance);
}

function drawClippedRectangleBorder(dxf, layer, x, y, width, height, clipRects = [], lineTypeScale = null, skipEdges = []) {
    if (!(width > 0) || !(height > 0)) {
        return;
    }

    const skippedEdges = new Set(Array.isArray(skipEdges) ? skipEdges : [skipEdges].filter(Boolean));
    [
        { key: "bottom", x1: x, y1: y, x2: x + width, y2: y },
        { key: "right", x1: x + width, y1: y, x2: x + width, y2: y + height },
        { key: "top", x1: x + width, y1: y + height, x2: x, y2: y + height },
        { key: "left", x1: x, y1: y + height, x2: x, y2: y }
    ].forEach((edge) => {
        if (skippedEdges.has(edge.key)) {
            return;
        }

        clipSegmentAgainstRectangles(edge, clipRects).forEach((segment) => {
            addPolylineLine(dxf, layer, segment.x1, segment.y1, segment.x2, segment.y2, { lineTypeScale });
        });
    });
}
function drawClippedLineSegment(dxf, layer, x1, y1, x2, y2, clipRects = [], lineTypeScale = null) {
    clipSegmentAgainstRectangles({ x1, y1, x2, y2 }, clipRects).forEach((segment) => {
        addPolylineLine(dxf, layer, segment.x1, segment.y1, segment.x2, segment.y2, { lineTypeScale });
    });
}
function drawClippedFrameSupportRectangle(dxf, layer, x, y, width, height, beamRects = [], skipEdges = []) {
    const supportTop = y + height;
    const hasBeamContactAtTop = (Array.isArray(beamRects) ? beamRects : []).some((beamRect) => {
        const beamLeft = Math.min(
            parseNumberOrFallback(beamRect?.x1, Number.NaN),
            parseNumberOrFallback(beamRect?.x2, Number.NaN)
        );
        const beamRight = Math.max(
            parseNumberOrFallback(beamRect?.x1, Number.NaN),
            parseNumberOrFallback(beamRect?.x2, Number.NaN)
        );
        const beamTop = Math.max(
            parseNumberOrFallback(beamRect?.y1, Number.NaN),
            parseNumberOrFallback(beamRect?.y2, Number.NaN)
        );

        return Number.isFinite(beamLeft)
            && Number.isFinite(beamRight)
            && Number.isFinite(beamTop)
            && Math.abs(beamTop - supportTop) <= EDGE_TOLERANCE
            && beamRight >= x - EDGE_TOLERANCE
            && beamLeft <= x + width + EDGE_TOLERANCE;
    });

    const clipRects = Array.isArray(beamRects) ? [...beamRects] : [];
    if (hasBeamContactAtTop) {
        const topClipHalfHeight = Math.max(Math.min(height * 0.01, 0.03), 0.01);
        clipRects.push({
            x1: x,
            y1: supportTop - topClipHalfHeight,
            x2: x + width,
            y2: supportTop + topClipHalfHeight
        });
    }

    drawClippedRectangleBorder(
        dxf,
        layer,
        x,
        y,
        width,
        height,
        clipRects,
        (layer === "CONCRETO_COLUMNAS_OCULTAS" || layer === "CONCRETO_PORTICO_OCULTO") ? 0.5 : null,
        skipEdges
    );
}


function getFrameClipRectangles(rectangles = []) {
    return (Array.isArray(rectangles) ? rectangles : [])
        .map((rect) => {
            const x1 = parseNumberOrFallback(rect?.x1, Number.NaN);
            const y1 = parseNumberOrFallback(rect?.y1, Number.NaN);
            const x2 = parseNumberOrFallback(rect?.x2, Number.NaN);
            const y2 = parseNumberOrFallback(rect?.y2, Number.NaN);

            if (!Number.isFinite(x1) || !Number.isFinite(y1) || !Number.isFinite(x2) || !Number.isFinite(y2)) {
                return null;
            }

            return {
                x1: Math.min(x1, x2),
                y1: Math.min(y1, y2),
                x2: Math.max(x1, x2),
                y2: Math.max(y1, y2)
            };
        })
        .filter(Boolean);
}

function getFrameSupportClipRectangles(supports = [], localizePosition = (position) => position, bottomY = 0) {
    return (Array.isArray(supports) ? supports : [])
        .map((support) => {
            const position = parseNumberOrFallback(support?.position, Number.NaN);
            const width = parsePositiveNumberOrFallback(support?.width, 0, 0);
            const bottomOffset = parseNumberOrFallback(support?.verticalBottomOffset, 0);
            const topOffset = parseNumberOrFallback(
                support?.verticalTopOffset,
                bottomOffset + parsePositiveNumberOrFallback(support?.height, 0, 0)
            );
            const height = topOffset - bottomOffset;

            if (!Number.isFinite(position) || !(width > 0) || !(height > 0)) {
                return null;
            }

            const left = localizePosition(position) - width / 2;
            return {
                x1: left,
                y1: bottomY + bottomOffset,
                x2: left + width,
                y2: bottomY + topOffset
            };
        })
        .filter(Boolean);
}

function doFrameRectanglesTouchHorizontalEdge(rectangles = [], left = 0, right = 0, edgeY = 0, tolerance = EDGE_TOLERANCE) {
    const safeTolerance = Math.max(Number.isFinite(tolerance) ? tolerance : EDGE_TOLERANCE, 1e-6);
    const edgeLeft = Math.min(left, right);
    const edgeRight = Math.max(left, right);

    if (!Number.isFinite(edgeLeft) || !Number.isFinite(edgeRight) || !Number.isFinite(edgeY) || edgeRight <= edgeLeft + safeTolerance) {
        return false;
    }

    return getFrameClipRectangles(rectangles).some((rect) => {
        const hasHorizontalOverlap = rect.x2 > edgeLeft + safeTolerance && rect.x1 < edgeRight - safeTolerance;
        const touchesEdge = Math.abs(rect.y1 - edgeY) <= safeTolerance || Math.abs(rect.y2 - edgeY) <= safeTolerance;
        return hasHorizontalOverlap && touchesEdge;
    });
}

function getFrameElevationConcreteLayer(sourceLayer = "") {
    return sourceLayer === "CONCRETO_COLUMNAS_OCULTAS"
        ? "CONCRETO_PORTICO_OCULTO"
        : "CONCRETO_PORTICO";
}

function drawFrameBeamConcreteRectangle(dxf, layer, x, y, width, height, options = {}) {
    if (!(width > 0) || !(height > 0)) {
        return;
    }

    const bottomSupportRects = getFrameClipRectangles(options.bottomSupportRects || options.lowerSupportRects || []);
    const topSupportRects = getFrameClipRectangles(options.topSupportRects || options.upperSupportRects || []);
    const verticalSupportRects = getFrameClipRectangles([
        ...bottomSupportRects,
        ...topSupportRects
    ]);
    const top = y + height;
    const right = x + width;
    // Beam endpoints are trimmed to the faces of the supports below. The top beam outline,
    // however, must continue across those supports whenever no wall or column exists above.
    // Use the original beam-centerline span for that edge and clip it only where an upper
    // support actually occupies the line.
    const requestedTopLineStart = parseNumberOrFallback(options.topLineStart, x);
    const requestedTopLineEnd = parseNumberOrFallback(options.topLineEnd, right);
    const topLineStart = Math.min(requestedTopLineStart, requestedTopLineEnd);
    const topLineEnd = Math.max(requestedTopLineStart, requestedTopLineEnd);
    const drawLeftEnd = options.drawLeftEnd !== false;
    const drawRightEnd = options.drawRightEnd !== false;

    clipSegmentAgainstRectangles({ x1: x, y1: y, x2: right, y2: y }, bottomSupportRects, EDGE_TOLERANCE)
        .forEach((segment) => addPolylineLine(dxf, layer, segment.x1, segment.y1, segment.x2, segment.y2));
    // Close only the actual terminal ends of the continuous beam chain. At an
    // interior support, the support sides—not a duplicate beam-end line—define the
    // joint and must remain visually clean.
    if (drawRightEnd) {
        addPolylineLine(dxf, layer, right, y, right, top);
    }
    clipSegmentAgainstRectangles({ x1: topLineEnd, y1: top, x2: topLineStart, y2: top }, topSupportRects, EDGE_TOLERANCE)
        .forEach((segment) => addPolylineLine(dxf, layer, segment.x1, segment.y1, segment.x2, segment.y2));
    if (drawLeftEnd) {
        addPolylineLine(dxf, layer, x, top, x, y);
    }
}

function drawFrameSupportConcreteRectangle(dxf, layer, x, y, width, height, options = {}) {
    if (!(width > 0) || !(height > 0)) {
        return;
    }

    const skippedEdges = new Set(Array.isArray(options.skipEdges) ? options.skipEdges : [options.skipEdges].filter(Boolean));
    // At a terminal frame support, the outside concrete face is the elevation's
    // continuous silhouette. Keep that one face uninterrupted through the beam
    // depth; the inside face remains clipped so it cannot cut through the beam.
    const continuousVerticalEdges = new Set(
        Array.isArray(options.continuousVerticalEdges)
            ? options.continuousVerticalEdges
            : [options.continuousVerticalEdges].filter(Boolean)
    );
    const beamRectsBelow = getFrameClipRectangles(options.beamRectsBelow || options.lowerBeamRects || []);
    const beamRectsAbove = getFrameClipRectangles(options.beamRectsAbove || options.upperBeamRects || []);
    const beamContactRectsBelow = getFrameClipRectangles(options.beamContactRectsBelow || options.lowerBeamContactRects || beamRectsBelow);
    const beamContactRectsAbove = getFrameClipRectangles(options.beamContactRectsAbove || options.upperBeamContactRects || beamRectsAbove);
    const verticalClipRects = getFrameClipRectangles([
        ...beamRectsBelow,
        ...beamRectsAbove
    ]);
    // In frame elevations, columns and walls must stop at the beam faces instead of
    // visually crossing the beam depth.  Keep the previous opt-out available only for
    // callers that explicitly need uninterrupted vertical edges.
    const clipVerticalEdgesThroughBeams = options.clipVerticalEdgesThroughBeams !== false;
    const top = y + height;
    const right = x + width;
    const lineTypeScale = (layer === "CONCRETO_COLUMNAS_OCULTAS" || layer === "CONCRETO_PORTICO_OCULTO") ? 0.5 : null;

    // If a support shares its bottom/top edge with a beam, hide that whole support edge.
    // This prevents duplicate joint lines between columns/walls and beams in frame elevations.
    if (doFrameRectanglesTouchHorizontalEdge(beamContactRectsBelow, x, right, y, EDGE_TOLERANCE)) {
        skippedEdges.add("bottom");
    }

    if (doFrameRectanglesTouchHorizontalEdge(beamContactRectsAbove, x, right, top, EDGE_TOLERANCE)) {
        skippedEdges.add("top");
    }

    if (!skippedEdges.has("bottom")) {
        clipSegmentAgainstRectangles({ x1: x, y1: y, x2: right, y2: y }, beamRectsBelow, EDGE_TOLERANCE)
            .forEach((segment) => addPolylineLine(dxf, layer, segment.x1, segment.y1, segment.x2, segment.y2, { lineTypeScale }));
    }

    if (!skippedEdges.has("right")) {
        const rightSegments = clipVerticalEdgesThroughBeams && !continuousVerticalEdges.has("right")
            ? clipSegmentAgainstRectangles({ x1: right, y1: y, x2: right, y2: top }, verticalClipRects, EDGE_TOLERANCE)
            : [{ x1: right, y1: y, x2: right, y2: top }];
        rightSegments.forEach((segment) => addPolylineLine(dxf, layer, segment.x1, segment.y1, segment.x2, segment.y2, { lineTypeScale }));
    }

    if (!skippedEdges.has("top")) {
        clipSegmentAgainstRectangles({ x1: right, y1: top, x2: x, y2: top }, beamRectsAbove, EDGE_TOLERANCE)
            .forEach((segment) => addPolylineLine(dxf, layer, segment.x1, segment.y1, segment.x2, segment.y2, { lineTypeScale }));
    }

    if (!skippedEdges.has("left")) {
        const leftSegments = clipVerticalEdgesThroughBeams && !continuousVerticalEdges.has("left")
            ? clipSegmentAgainstRectangles({ x1: x, y1: top, x2: x, y2: y }, verticalClipRects, EDGE_TOLERANCE)
            : [{ x1: x, y1: top, x2: x, y2: y }];
        leftSegments.forEach((segment) => addPolylineLine(dxf, layer, segment.x1, segment.y1, segment.x2, segment.y2, { lineTypeScale }));
    }
}

function clipPolygonToRectangle(points, rectangle = null) {
    const source = (Array.isArray(points) ? points : [])
        .map((point) => ({ x: Number.parseFloat(point?.x), y: Number.parseFloat(point?.y) }))
        .filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y));
    if (!rectangle || source.length < 3) {
        return source;
    }

    const minX = Number.parseFloat(rectangle.minX);
    const maxX = Number.parseFloat(rectangle.maxX);
    const minY = Number.parseFloat(rectangle.minY);
    const maxY = Number.parseFloat(rectangle.maxY);
    if (![minX, maxX, minY, maxY].every(Number.isFinite) || maxX <= minX || maxY <= minY) {
        return source;
    }

    const clipAgainstEdge = (input, isInside, getIntersection) => {
        if (!input.length) {
            return [];
        }
        const output = [];
        let previous = input[input.length - 1];
        let previousInside = isInside(previous);
        input.forEach((current) => {
            const currentInside = isInside(current);
            if (currentInside) {
                if (!previousInside) {
                    output.push(getIntersection(previous, current));
                }
                output.push(current);
            } else if (previousInside) {
                output.push(getIntersection(previous, current));
            }
            previous = current;
            previousInside = currentInside;
        });
        return output.filter((point) => Number.isFinite(point?.x) && Number.isFinite(point?.y));
    };

    const intersectVertical = (from, to, x) => {
        const denominator = to.x - from.x;
        const ratio = Math.abs(denominator) <= 1e-12 ? 0 : (x - from.x) / denominator;
        return { x, y: from.y + (to.y - from.y) * ratio };
    };
    const intersectHorizontal = (from, to, y) => {
        const denominator = to.y - from.y;
        const ratio = Math.abs(denominator) <= 1e-12 ? 0 : (y - from.y) / denominator;
        return { x: from.x + (to.x - from.x) * ratio, y };
    };

    let clipped = source;
    clipped = clipAgainstEdge(clipped, (point) => point.x >= minX - 1e-9, (from, to) => intersectVertical(from, to, minX));
    clipped = clipAgainstEdge(clipped, (point) => point.x <= maxX + 1e-9, (from, to) => intersectVertical(from, to, maxX));
    clipped = clipAgainstEdge(clipped, (point) => point.y >= minY - 1e-9, (from, to) => intersectHorizontal(from, to, minY));
    clipped = clipAgainstEdge(clipped, (point) => point.y <= maxY + 1e-9, (from, to) => intersectHorizontal(from, to, maxY));
    return clipped;
}

function getBracingCenterlineTopForInnerFaceContact(bottomPoint, contactPoint, halfWidth, innerSideSign) {
    const bottom = {
        x: Number.parseFloat(bottomPoint?.x),
        y: Number.parseFloat(bottomPoint?.y)
    };
    const contact = {
        x: Number.parseFloat(contactPoint?.x),
        y: Number.parseFloat(contactPoint?.y)
    };
    if (![bottom.x, bottom.y, contact.x, contact.y, halfWidth, innerSideSign].every(Number.isFinite)) {
        return contact;
    }

    let top = { ...contact };
    for (let iteration = 0; iteration < 5; iteration += 1) {
        const dx = top.x - bottom.x;
        const dy = top.y - bottom.y;
        const length = Math.hypot(dx, dy);
        if (!(length > EDGE_TOLERANCE)) {
            break;
        }
        const normalX = -dy / length;
        const normalY = dx / length;
        top = {
            x: contact.x - innerSideSign * normalX * halfWidth,
            y: contact.y - innerSideSign * normalY * halfWidth
        };
    }
    return top;
}

function drawFrameBracingProfile(dxf, x1, y1, x2, y2, width, options = {}) {
    const layer = typeof options === "string"
        ? options
        : (options?.layer || DXF_BRACING_LAYER);
    const wallThickness = typeof options === "string"
        ? 0
        : parsePositiveNumberOrFallback(options?.wallThickness, 0, 0);
    const label = typeof options === "string" ? "" : normalizeTextValue(options?.label);
    const textSize = typeof options === "string"
        ? 0.07
        : Math.max(parsePositiveNumberOrFallback(options?.textSize, 0.07, 0.02), 0.02);
    const hiddenLineTypeScale = typeof options === "string"
        ? 0.1
        : Math.max(parsePositiveNumberOrFallback(options?.hiddenLineTypeScale, 0.1, 0.01), 0.01);
    const labelColor = typeof options === "string"
        ? 7
        : Number.parseInt(options?.labelColor ?? 7, 10);
    const clipRectangle = typeof options === "string" ? null : options?.clipRectangle;
    const labelSide = typeof options === "string"
        ? 1
        : (parseNumberOrFallback(options?.labelSide, 1) < 0 ? -1 : 1);

    const dx = x2 - x1;
    const dy = y2 - y1;
    const length = Math.hypot(dx, dy);
    if (!(length > EDGE_TOLERANCE)) {
        return;
    }
    const memberWidth = Math.max(parsePositiveNumberOrFallback(width, 0.12, 0.02), 0.02);
    const halfWidth = memberWidth / 2;
    const unitNormalX = -dy / length;
    const unitNormalY = dx / length;
    const normalX = unitNormalX * halfWidth;
    const normalY = unitNormalY * halfWidth;
    const p1 = { x: x1 + normalX, y: y1 + normalY };
    const p2 = { x: x2 + normalX, y: y2 + normalY };
    const p3 = { x: x2 - normalX, y: y2 - normalY };
    const p4 = { x: x1 - normalX, y: y1 - normalY };
    const outerPolygon = clipPolygonToRectangle([p1, p2, p3, p4], clipRectangle);
    if (outerPolygon.length >= 3) {
        addPolyline(dxf, layer, outerPolygon, { closed: true });
    }

    const innerHalfWidth = halfWidth - wallThickness;
    if (wallThickness > EDGE_TOLERANCE && innerHalfWidth > EDGE_TOLERANCE) {
        const innerNormalX = unitNormalX * innerHalfWidth;
        const innerNormalY = unitNormalY * innerHalfWidth;
        const i1 = { x: x1 + innerNormalX, y: y1 + innerNormalY };
        const i2 = { x: x2 + innerNormalX, y: y2 + innerNormalY };
        const i3 = { x: x2 - innerNormalX, y: y2 - innerNormalY };
        const i4 = { x: x1 - innerNormalX, y: y1 - innerNormalY };
        const innerPolygon = clipPolygonToRectangle([i1, i2, i3, i4], clipRectangle);
        if (innerPolygon.length >= 3) {
            addPolyline(dxf, layer, innerPolygon, {
                closed: true,
                lineType: "HIDDEN2",
                lineTypeScale: hiddenLineTypeScale
            });
        }
    }

    if (label) {
        const labelFaceStart = labelSide > 0 ? p1 : p4;
        const labelFaceEnd = labelSide > 0 ? p2 : p3;
        const labelCenterX = (labelFaceStart.x + labelFaceEnd.x) / 2 + unitNormalX * labelSide * (textSize * 0.35);
        const labelCenterY = (labelFaceStart.y + labelFaceEnd.y) / 2 + unitNormalY * labelSide * (textSize * 0.35);
        addRotatedCenteredText(
            dxf,
            layer,
            labelCenterX,
            labelCenterY,
            label,
            textSize,
            getReadableLineAngleDegrees(labelFaceEnd.x - labelFaceStart.x, labelFaceEnd.y - labelFaceStart.y),
            Number.isFinite(labelColor) ? labelColor : 7
        );
    }
}

function drawFrameExportSheet(dxf, selection, options = {}) {
    const [type, rawValue] = String(selection || "").split("|");
    const value = type === "o" ? rawValue : Number.parseFloat(rawValue);

    if (type === "o") {
        if (!getObliqueFrameReference(selection)) {
            throw new Error("Seleccion de portico invalida.");
        }
    } else if ((type !== "x" && type !== "y") || !Number.isFinite(value)) {
        throw new Error("Seleccion de portico invalida.");
    }

    const originX = options.originX ?? 0;
    const originY = options.originY ?? 0;
    const includeElevation = options.includeElevation !== false;
    const includeSectionDetails = options.includeSectionDetails !== false;
    const includeTitle = options.includeTitle !== false;
    const frameElevationPreferences = normalizeFrameElevationDrawingPreferences(
        options.frameElevationPreferences || options.drawingPreferences?.frameElevation || options.drawingPreferences
    );
    const includeLongitudinalSteelFill = frameElevationPreferences.includeLongitudinalSteelFill !== false;
    const includeTransverseSteelFill = frameElevationPreferences.includeTransverseSteelFill !== false;
    const frameSectionPreferences = normalizeFrameSectionDrawingPreferences(
        options.frameSectionPreferences || options.drawingPreferences?.frameSections
    );
    // Principal and additional longitudinal callouts, as well as the stirrup callouts,
    // use the same plotted 0.06 m height in every frame elevation.
    const frameDetailTextHeight = 0.06;
    const frameStirrupDetailTextHeight = 0.06;
    const frameBeamSpanDimensionOffsetFromBottom = normalizeFrameElevationAnnotationOffsetFromBottom(
        frameElevationPreferences.beamSpanDimensionOffsetFromBottom,
        FRAME_ELEVATION_BEAM_SPAN_DIMENSION_OFFSET_FROM_BOTTOM_DEFAULT
    );
    const frameStirrupDetailOffsetFromBottom = normalizeFrameElevationAnnotationOffsetFromBottom(
        frameElevationPreferences.stirrupDetailOffsetFromBottom,
        FRAME_ELEVATION_STIRRUP_DETAIL_OFFSET_FROM_BOTTOM_DEFAULT
    );
    const sectionMarkerStyle = normalizeFrameElevationSectionMarkerStyle(frameElevationPreferences.sectionMarkerStyle);
    const sectionMarkerDetailCode = normalizeTextValue(options.sectionMarkerDetailCode ?? options.detailCode ?? options.sheetCode ?? options.drawingCode) || "E-00";
    const frameDetailDimensionScale = frameDetailTextHeight / DETAIL_DIMENSION_TEXT_HEIGHT;
    const frameContentPlan = getFrameLevelContentPlan(type, value);
    const axisIndex = type === "o" ? -1 : (projectState.axes[type]?.findIndex((axisValue) => Math.abs(axisValue - value) < 0.0001) ?? -1);
    const obliqueReference = type === "o" ? getObliqueFrameReference(selection) : null;
    const axisLabel = obliqueReference?.label || (axisIndex >= 0 ? getAxisLabelForIndex(type, axisIndex) : rawValue);

    if (!frameContentPlan.hasBeamContent) {
        return drawExportNoticeSheet(
            dxf,
            `${translate("exportDock.group.frames")} | ${translate("exportDock.frameOption", { label: axisLabel })}`,
            translate("exportDock.errors.noFrames"),
            originY
        );
    }

    const frameLevels = frameContentPlan.levels;
    const totalHeight = frameContentPlan.totalHeight;
    const concreteCover = DRAWING_COVER;
    const barThickness = 0.0254;
    const sectionDetails = [];
    const sectionTagAllocator = options?.sectionTagAllocator && typeof options.sectionTagAllocator === "object"
        ? options.sectionTagAllocator
        : null;
    // A frame section is reusable when its concrete dimensions and the slab
    // condition immediately to each side of the cut are the same. Keep a
    // sheet-local map so repeated cuts within this portico share one detail.
    const sectionDetailByKey = new Map();
    // Combined exports pass one allocator through all selected porticos. The
    // registry shares S-number tags globally, while each portico still draws
    // its own copy of the matching section detail.
    const sharedFrameSectionTagByKey = sectionTagAllocator
        ? (sectionTagAllocator.frameSectionTagByKey instanceof Map
            ? sectionTagAllocator.frameSectionTagByKey
            : (sectionTagAllocator.frameSectionTagByKey = new Map()))
        : null;
    const sectionMarkerPlacementsByLevel = new Map();
    const frameBeamsByLevel = frameContentPlan.beamsByLevel;
    const frameBracesByLevel = frameContentPlan.bracesByLevel;
    const supportEntriesByLevel = frameContentPlan.supportsByLevel;
    const mergedSupportEntriesByLevel = frameContentPlan.mergedSupportsByLevel;
    const frameBeamRectsByLevel = new Map();
    const frameBeamEnvelopeRectsByLevel = new Map();
    const frameBeamContactRectsByLevel = new Map();
    const frameBoundaryPositions = [];
    let sectionIndex = Math.max(0, Math.floor(parseNumberOrFallback(sectionTagAllocator?.nextIndex, 0)));
    let baseElevation = 0;
    const frameSpanAxisType = type === "o" ? "o" : (type === "x" ? "y" : "x");
    const sectionMarkerOffsetPattern = [0, -0.24, 0.24, -0.42, 0.42];
    const FRAME_REBAR_LABEL_SPAN_RATIO = 3 / 8;
    const FRAME_TERMINAL_STIRRUP_OFFSET = 0.17;
    const FRAME_TOP_LONGITUDINAL_END_CLEARANCE = 0.05;
    // Keep the lower principal bar hook 0.10 m from the actual beam end.
    // The end coordinate includes the adjoining support face, so this inset is
    // measured from the concrete beam termination rather than from its centerline.
    const FRAME_BOTTOM_LONGITUDINAL_END_CLEARANCE = 0.10;
    const getFrameEndFaceOffset = (support) => Math.max((support?.width || 0) / 2, 0);
    const registerSectionMarkerPlacement = (levelId, position, tag) => {
        const placements = sectionMarkerPlacementsByLevel.get(levelId) || [];
        const duplicate = placements.find((placement) => (
            placement.tag === tag
            && Math.abs(placement.position - position) <= 0.08
        ));

        if (duplicate) {
            return null;
        }

        const nearbyCount = placements.filter((placement) => Math.abs(placement.position - position) <= 0.35).length;
        const labelOffsetX = sectionMarkerOffsetPattern[Math.min(nearbyCount, sectionMarkerOffsetPattern.length - 1)];
        placements.push({ position, tag });
        sectionMarkerPlacementsByLevel.set(levelId, placements);
        return {
            labelOffsetX
        };
    };

    const getFrameSupportIntervals = (supports = []) => (Array.isArray(supports) ? supports : [])
        .map((support) => ({
            start: support.position - support.width / 2,
            end: support.position + support.width / 2
        }))
        .filter((interval) => Number.isFinite(interval.start) && Number.isFinite(interval.end) && interval.end > interval.start + EDGE_TOLERANCE);

    const getFrameClearIntervals = (start, end, supportIntervals, padding = 0.04) => subtractCoordinateIntervals(
        Math.min(start, end),
        Math.max(start, end),
        supportIntervals,
        EDGE_TOLERANCE
    )
        .map((interval) => ({
            start: interval.start + padding,
            end: interval.end - padding
        }))
        .filter((interval) => interval.end > interval.start + EDGE_TOLERANCE);

    const resolveFrameClearCutPosition = (desiredPosition, clearIntervals = []) => {
        if (!Number.isFinite(desiredPosition) || !Array.isArray(clearIntervals) || clearIntervals.length === 0) {
            return Number.NaN;
        }

        const containing = clearIntervals.find((interval) => desiredPosition >= interval.start - EDGE_TOLERANCE && desiredPosition <= interval.end + EDGE_TOLERANCE);
        if (containing) {
            return Math.min(Math.max(desiredPosition, containing.start), containing.end);
        }

        let best = null;
        clearIntervals.forEach((interval) => {
            const clamped = Math.min(Math.max(desiredPosition, interval.start), interval.end);
            const distance = Math.abs(clamped - desiredPosition);
            if (!best || distance < best.distance) {
                best = { position: clamped, distance };
            }
        });

        return Number.isFinite(best?.position) ? best.position : Number.NaN;
    };

    frameLevels.forEach((level) => {
        const beams = frameBeamsByLevel.get(level.id) || [];
        beams.forEach((beam) => {
            const bounds = getBeamBoundsForFrame(beam, type);
            if (!Number.isFinite(bounds.start) || !Number.isFinite(bounds.end)) {
                return;
            }

            frameBoundaryPositions.push(bounds.start, bounds.end);
        });
        (frameBracesByLevel.get(level.id) || []).forEach((bracing) => {
            const bounds = getBracingBoundsForFrame(bracing, type);
            if (Number.isFinite(bounds.start) && Number.isFinite(bounds.end)) {
                frameBoundaryPositions.push(bounds.start, bounds.end);
            }
        });

        const supportEntries = supportEntriesByLevel.get(level.id) || [];
        supportEntries.forEach((support) => {
            if (!Number.isFinite(support?.position)) {
                return;
            }

            frameBoundaryPositions.push(
                support.position - support.width / 2,
                support.position + support.width / 2
            );
        });
    });

    const frameBoundaryBounds = getNumericArrayBounds(frameBoundaryPositions);
    const minPosition = frameBoundaryBounds?.min;
    const maxPosition = frameBoundaryBounds?.max;
    if (!Number.isFinite(minPosition) || !Number.isFinite(maxPosition)) {
        return drawExportNoticeSheet(
            dxf,
            `${translate("exportDock.group.frames")} | ${translate("exportDock.frameOption", { label: axisLabel })}`,
            translate("exportDock.errors.noFrames"),
            originY
        );
    }

    const axisEntries = frameSpanAxisType === "o" ? [] : getAxisEntriesBetween(frameSpanAxisType, minPosition, maxPosition);
    const localSpan = Math.max(maxPosition - minPosition, 0.6);
    const localizePosition = (position) => originX + position - minPosition;
    const frameTitleClearance = includeTitle ? 1.15 : 0;
    const contentOriginY = originY + frameTitleClearance;

    if (includeTitle) {
        drawDetailTitleMarker(
            dxf,
            originX + 0.35,
            originY + 0.45,
            `P${axisLabel}`,
            "E-00",
            `DETALLE ESTRUCTURAL DE PÓRTICO ${axisLabel}`,
            { rightLineLength: 4.9 }
        );
    }

    if (includeElevation) {
        const frameAxisAnnotationOffset = 1.4;
        const frameAxisDimensionOffset = 1.1;
        const frameAxisLineTopY = contentOriginY + totalHeight + frameAxisAnnotationOffset;
        const frameLevelBaseElevationById = new Map();
        let runningFrameBaseElevation = 0;
        frameLevels.forEach((level) => {
            frameLevelBaseElevationById.set(level.id, runningFrameBaseElevation);
            runningFrameBaseElevation += Math.max(parseNumberOrFallback(level.height, 0), 0);
        });
        const getFrameAxisLineBottomY = (axisEntry) => {
            let lowestSupportBottomY = Number.POSITIVE_INFINITY;

            frameLevels.forEach((level) => {
                const levelBaseElevation = frameLevelBaseElevationById.get(level.id) ?? 0;
                const supports = mergedSupportEntriesByLevel.get(level.id) || supportEntriesByLevel.get(level.id) || [];
                supports.forEach((support) => {
                    if (!Number.isFinite(support?.position) || !(support?.width > 0)) {
                        return;
                    }

                    const supportHalfWidth = support.width / 2;
                    if (axisEntry.value < support.position - supportHalfWidth - EDGE_TOLERANCE
                        || axisEntry.value > support.position + supportHalfWidth + EDGE_TOLERANCE) {
                        return;
                    }

                    const supportBottomOffset = parseNumberOrFallback(support?.verticalBottomOffset, 0);
                    lowestSupportBottomY = Math.min(
                        lowestSupportBottomY,
                        contentOriginY + levelBaseElevation + supportBottomOffset
                    );
                });
            });

            return Number.isFinite(lowestSupportBottomY) ? lowestSupportBottomY : contentOriginY;
        };

        axisEntries.forEach((entry) => {
            const axisLineBottomY = getFrameAxisLineBottomY(entry);
            drawAxisBubble(
                dxf,
                localizePosition(entry.value),
                frameAxisLineTopY,
                entry.label,
                Math.max(frameAxisLineTopY - axisLineBottomY, 0),
                { lineTypeScale: 0.5 }
            );
        });

        for (let index = 0; index < axisEntries.length - 1; index += 1) {
            addDimension(
                dxf,
                "COTAS_EJES",
                localizePosition(axisEntries[index].value),
                localizePosition(axisEntries[index + 1].value),
                contentOriginY + totalHeight + frameAxisDimensionOffset,
                Math.abs(axisEntries[index + 1].value - axisEntries[index].value).toFixed(2),
                contentOriginY + totalHeight + frameAxisAnnotationOffset
            );
        }
    }

    frameLevels.forEach((level, levelIndex) => {
        const topElevation = baseElevation + level.height;
        const frameSupports = supportEntriesByLevel.get(level.id) || [];
        const mergedFrameSupports = mergedSupportEntriesByLevel.get(level.id) || frameSupports;
        const nextLevel = frameLevels[levelIndex + 1] || null;
        const nextFrameSupports = nextLevel
            ? (mergedSupportEntriesByLevel.get(nextLevel.id) || supportEntriesByLevel.get(nextLevel.id) || [])
            : [];
        const lowerSupportRects = includeElevation
            ? getFrameSupportClipRectangles(mergedFrameSupports, localizePosition, contentOriginY + baseElevation)
            : [];
        const upperSupportRects = includeElevation && nextLevel
            ? getFrameSupportClipRectangles(nextFrameSupports, localizePosition, contentOriginY + topElevation)
            : [];
        const beamRects = [];
        const beamEnvelopeRects = [];
        const beamContactRects = [];
        // Stores which exterior support faces must remain continuous across the
        // depth of a terminal beam. Keys are the merged support records later
        // used for drawing, so no geometry or support grouping is changed.
        const terminalSupportContinuousEdges = new Map();
        const registerTerminalSupportContinuousEdge = (support, edge) => {
            if (!support || (edge !== "left" && edge !== "right")) {
                return;
            }
            const edges = terminalSupportContinuousEdges.get(support) || new Set();
            edges.add(edge);
            terminalSupportContinuousEdges.set(support, edges);
        };
        const beams = frameBeamsByLevel.get(level.id) || [];
        const braces = frameBracesByLevel.get(level.id) || [];
        const frameTextResolver = createDxfTextCollisionResolver();
        // A source model may contain overlapping fragments around a support. Keep a
        // principal-bar callout to one clear beam interval, never inside a column/wall.
        const drawnFrameRebarCalloutKeys = new Set();
        // When a frame beam terminates at a concrete wall, its longitudinal steel must
        // continue to the exterior wall face. The model can terminate at the wall
        // centreline, a graphic extension, or anywhere within the aligned wall span,
        // so resolve that wall by its actual base range instead of its centre only.
        const resolveFrameLongitudinalTerminalAnchor = (position, outwardDirection, fallbackHookInset) => {
            const safeDirection = outwardDirection < 0 ? -1 : 1;
            const safeFallbackInset = Math.max(parseNumberOrFallback(fallbackHookInset, 0), 0);
            const matchingWall = (Array.isArray(mergedFrameSupports) ? mergedFrameSupports : [])
                .map((support) => {
                    if (support?.kind !== "wall" || normalizeWallMaterialType(support?.entity?.material) !== "concrete") {
                        return null;
                    }

                    const physicalStart = Number.isFinite(support.baseStart)
                        ? Math.min(support.baseStart, support.baseEnd)
                        : support.position - support.width / 2;
                    const physicalEnd = Number.isFinite(support.baseEnd)
                        ? Math.max(support.baseStart, support.baseEnd)
                        : support.position + support.width / 2;
                    const graphicStart = support.position - support.width / 2;
                    const graphicEnd = support.position + support.width / 2;
                    const matchingStart = Math.min(physicalStart, graphicStart);
                    const matchingEnd = Math.max(physicalEnd, graphicEnd);
                    const clampedPosition = Math.min(Math.max(position, matchingStart), matchingEnd);
                    const distance = Math.abs(position - clampedPosition);

                    return distance <= 0.06
                        ? { support, physicalStart, physicalEnd, distance }
                        : null;
                })
                .filter(Boolean)
                .sort((left, right) => left.distance - right.distance || (right.physicalEnd - right.physicalStart) - (left.physicalEnd - left.physicalStart))[0] || null;

            if (matchingWall) {
                return {
                    position: safeDirection < 0 ? matchingWall.physicalStart : matchingWall.physicalEnd,
                    // The hook/bend stays inside the concrete wall by the drawing cover.
                    hookInset: concreteCover,
                    isConcreteWall: true
                };
            }

            const support = getFrameSupportAtPosition(mergedFrameSupports, position);
            return {
                position: position + safeDirection * getFrameEndFaceOffset(support),
                hookInset: safeFallbackInset,
                isConcreteWall: false
            };
        };

        if (includeElevation) {
            const levelAnnotation = getFrameLevelAnnotation(level.name, topElevation);
            const titleSize = 0.06;
            const subtitleSize = 0.06;
            const noteShiftRight = 1.15;
            // Keep the note fully outside the structural frame so it does not sit on top of the beams or supports.
            const noteTextWidth = Math.max(
                estimateDxfTextWidth(levelAnnotation.title, titleSize),
                estimateDxfTextWidth(levelAnnotation.subtitle, subtitleSize)
            );
            const noteTextX = originX - noteTextWidth - 0.95 + noteShiftRight;
            const noteLineStartX = originX - 0.34 + noteShiftRight;
            const noteLineEndX = originX - 0.12 + noteShiftRight;
            // Align the frame N.P.T. callout with the lowered column-elevation convention.
            const noteLineY = contentOriginY + topElevation + 0.01;
            const noteMarkerX = originX - 0.18 + noteShiftRight;
            const noteArrowHalfWidth = 0.045;
            const noteArrowHeight = 0.09;

            addDashedLine(dxf, "COTAS_ALTURAS", noteLineStartX, noteLineY, noteLineEndX, noteLineY);
            addSolid(dxf, "COTAS_ALTURAS", noteMarkerX - noteArrowHalfWidth, noteLineY + noteArrowHeight, noteMarkerX + noteArrowHalfWidth, noteLineY + noteArrowHeight, noteMarkerX, noteLineY);
            addText(dxf, "COTAS_ALTURAS", noteTextX, noteLineY + 0.10, levelAnnotation.title, titleSize);
            frameTextResolver.registerLeftText(levelAnnotation.title, noteTextX, noteLineY + 0.10, titleSize, { layer: "COTAS_ALTURAS", kind: "level" });
            addText(dxf, "COTAS_ALTURAS", noteTextX, noteLineY - 0.02, levelAnnotation.subtitle, subtitleSize);
            frameTextResolver.registerLeftText(levelAnnotation.subtitle, noteTextX, noteLineY - 0.02, subtitleSize, { layer: "COTAS_ALTURAS", kind: "level" });
        }

        if (beams.length > 0) {
            const beamBounds = beams.map((beam) => getBeamBoundsForFrame(beam, type));
            const beamSegments = beams.map((beam, beamIndex) => ({
                beam,
                ...beamBounds[beamIndex]
            }));
            // Frame reinforcement is only applicable to concrete beams. Steel members are
            // rendered as profiles below and deliberately never enter rebar chains.
            const concreteBeamSegments = beamSegments.filter((segment) => isConcreteStructuralMaterial(segment?.beam?.structuralMaterial));
            // Treat beams that meet at opposite faces of the same interior support
            // as one physical frame chain. Terminal-edge treatment must apply only
            // at the true exterior ends of that chain.
            const frameChains = getContinuousFrameBeamChains(concreteBeamSegments, 0.12, mergedFrameSupports);
            const frameAnnotationChains = getFrameBeamAnnotationChains(concreteBeamSegments, mergedFrameSupports);
            const chainByBeamId = new Map();

            frameChains.forEach((chain) => {
                (chain.members || []).forEach((member) => {
                    if (member?.beam?.id) {
                        chainByBeamId.set(member.beam.id, chain);
                    }
                });
            });

            const frameAdditionalRebarSegments = [];
            const directJointAdditionalRebarPlan = includeElevation
                ? buildDirectFrameJointAdditionalRebarSegments({
                    beamSegments: concreteBeamSegments,
                    supports: mergedFrameSupports,
                    localizePosition,
                    contentOriginY,
                    topElevation,
                    concreteCover,
                    barThickness,
                    axisType: type
                })
                : { segments: [], consumedZoneKeys: new Set() };
            const consumedDirectAdditionalZoneKeys = directJointAdditionalRebarPlan.consumedZoneKeys || new Set();
            frameAdditionalRebarSegments.push(...(directJointAdditionalRebarPlan.segments || []).map((segment) => ({
                ...segment,
                labelSize: frameDetailTextHeight
            })));

            if (includeElevation) {
                frameChains.forEach((chain) => {
                    const depthRuns = groupContiguousBeamDepthRuns(chain.members || []);
                    const depthDevelopmentPlan = getBeamDepthTransitionDevelopmentPlan(depthRuns, {
                        exportConfig: options.exportConfig,
                        supports: mergedFrameSupports
                    });
                    const chainStartAnchor = resolveFrameLongitudinalTerminalAnchor(
                        chain.start,
                        -1,
                        FRAME_TOP_LONGITUDINAL_END_CLEARANCE
                    );
                    const chainEndAnchor = resolveFrameLongitudinalTerminalAnchor(
                        chain.end,
                        1,
                        FRAME_TOP_LONGITUDINAL_END_CLEARANCE
                    );
                    const beamDepths = (chain.members || [])
                        .map((segment) => parsePositiveNumberOrFallback(segment.beam?.h, 0.4, 0.1))
                        .filter((beamDepth) => Number.isFinite(beamDepth) && beamDepth > 0);
                    const maxBeamDepth = getNumericArrayBounds(beamDepths)?.max ?? 0.4;
                    const topBarTopY = contentOriginY + topElevation - 0.04;
                    const topBarBottomY = topBarTopY - barThickness;
                    chain.bottomBarYByBeamId = new Map();
                    chain.bottomDevelopmentExtensionsByBeamId = depthDevelopmentPlan.beamExtensionsById;

                    drawSmartRebar(
                        dxf,
                        "ACERO_SUPERIOR",
                        localizePosition(chainStartAnchor.position),
                        localizePosition(chainEndAnchor.position),
                        topBarTopY,
                        topBarBottomY,
                        contentOriginY + topElevation - maxBeamDepth + 0.1,
                        true,
                        true,
                        {
                            leftHookInnerOffset: chainStartAnchor.hookInset,
                            rightHookInnerOffset: chainEndAnchor.hookInset,
                            hookLength: Math.max((getDiameterMetersFromBarLabel(chain.members?.[0]?.beam?.topRebar?.d, getActiveBarSetForDiameters()) || 0) * 16, 0),
                            as2d: includeLongitudinalSteelFill,
                            fillStyle: "hatch",
                            hatchLayer: FRAME_LONGITUDINAL_HATCH_LAYER,
                            hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
                            hatchPatternScale: FRAME_REBAR_HATCH_SCALE,
                            capStyle: "semicircle"
                        }
                    );
                    depthRuns.forEach((run) => {
                        const developmentExtension = depthDevelopmentPlan.runExtensions.get(run) || {};
                        const developmentExtensionDetails = depthDevelopmentPlan.runExtensionDetails?.get(run) || {};
                        const isChainStart = run.start <= chain.start + EDGE_TOLERANCE;
                        const isChainEnd = run.end >= chain.end - EDGE_TOLERANCE;
                        const runStartAnchor = isChainStart
                            ? resolveFrameLongitudinalTerminalAnchor(
                                run.start,
                                -1,
                                FRAME_BOTTOM_LONGITUDINAL_END_CLEARANCE
                            )
                            : { position: run.start, hookInset: FRAME_BOTTOM_LONGITUDINAL_END_CLEARANCE };
                        const runEndAnchor = isChainEnd
                            ? resolveFrameLongitudinalTerminalAnchor(
                                run.end,
                                1,
                                FRAME_BOTTOM_LONGITUDINAL_END_CLEARANCE
                            )
                            : { position: run.end, hookInset: FRAME_BOTTOM_LONGITUDINAL_END_CLEARANCE };
                        const runBottomBarBottomY = contentOriginY + topElevation - run.depth + 0.04;
                        const runBottomBarTopY = runBottomBarBottomY + barThickness;
                        const runBottomBarCenterY = (runBottomBarTopY + runBottomBarBottomY) / 2;
                        const runStartExtension = isChainStart ? 0 : Math.max(parseNumberOrFallback(developmentExtension.start, 0), 0);
                        const runEndExtension = isChainEnd ? 0 : Math.max(parseNumberOrFallback(developmentExtension.end, 0), 0);
                        const runStartDimensionLength = Math.max(
                            parseNumberOrFallback(developmentExtensionDetails.start?.dimensionLength, runStartExtension),
                            0
                        );
                        const runEndDimensionLength = Math.max(
                            parseNumberOrFallback(developmentExtensionDetails.end?.dimensionLength, runEndExtension),
                            0
                        );
                        const runStartCriticalPosition = parseNumberOrFallback(
                            developmentExtensionDetails.start?.criticalPosition,
                            runStartAnchor.position
                        );
                        const runEndCriticalPosition = parseNumberOrFallback(
                            developmentExtensionDetails.end?.criticalPosition,
                            runEndAnchor.position
                        );
                        const runStartBarEndPosition = parseNumberOrFallback(
                            developmentExtensionDetails.start?.barEndPosition,
                            runStartAnchor.position - runStartExtension
                        );
                        const runEndBarEndPosition = parseNumberOrFallback(
                            developmentExtensionDetails.end?.barEndPosition,
                            runEndAnchor.position + runEndExtension
                        );
                        const hasRunStartDevelopment = runStartDimensionLength > EDGE_TOLERANCE;
                        const hasRunEndDevelopment = runEndDimensionLength > EDGE_TOLERANCE;
                        const runStartX = localizePosition(hasRunStartDevelopment ? runStartBarEndPosition : runStartAnchor.position);
                        const runEndX = localizePosition(hasRunEndDevelopment ? runEndBarEndPosition : runEndAnchor.position);

                        drawSmartRebar(
                            dxf,
                            "ACERO_INFERIOR",
                            runStartX,
                            runEndX,
                            runBottomBarTopY,
                            runBottomBarBottomY,
                            contentOriginY + topElevation - 0.15,
                            !hasRunStartDevelopment,
                            !hasRunEndDevelopment,
                            {
                                leftHookInnerOffset: runStartAnchor.hookInset,
                                rightHookInnerOffset: runEndAnchor.hookInset,
                                hookLength: Math.max((getDiameterMetersFromBarLabel(run.members?.[0]?.beam?.botRebar?.d, getActiveBarSetForDiameters()) || 0) * 16, 0),
                                as2d: includeLongitudinalSteelFill,
                                fillStyle: "hatch",
                                hatchLayer: FRAME_LONGITUDINAL_HATCH_LAYER,
                                hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
                                hatchPatternScale: FRAME_REBAR_HATCH_SCALE,
                                capStyle: "semicircle"
                            }
                        );

                        if (hasRunStartDevelopment) {
                            drawDevelopmentInsertionDimension(dxf, {
                                x1: localizePosition(runStartBarEndPosition),
                                x2: localizePosition(runStartCriticalPosition),
                                dimensionY: runBottomBarBottomY - 0.28,
                                originY: runBottomBarCenterY,
                                length: runStartDimensionLength,
                                visualScale: frameDetailDimensionScale
                            });
                        }

                        if (hasRunEndDevelopment) {
                            drawDevelopmentInsertionDimension(dxf, {
                                x1: localizePosition(runEndCriticalPosition),
                                x2: localizePosition(runEndBarEndPosition),
                                dimensionY: runBottomBarBottomY - 0.28,
                                originY: runBottomBarCenterY,
                                length: runEndDimensionLength,
                                visualScale: frameDetailDimensionScale
                            });
                        }

                        (run.members || []).forEach((member) => {
                            if (member?.beam?.id) {
                                chain.bottomBarYByBeamId.set(member.beam.id, runBottomBarCenterY);
                            }
                        });
                    });
                });
            }

            const chainAnnotationPlanByBeamId = new Map();
            frameAnnotationChains.forEach((chain) => {
                const members = Array.isArray(chain.members)
                    ? [...chain.members].sort((left, right) => left.start - right.start || left.end - right.end)
                    : [];
                const representativeMember = getLongestFrameChainMember(members) || members[0];
                const representativeBeamId = representativeMember?.beam?.id || null;

                if (!representativeBeamId) {
                    return;
                }

                const topUniformInfo = getUniformFrameChainSignature(members, (member) => formatRebar(member?.beam?.topRebar));
                const bottomUniformInfo = getUniformFrameChainSignature(
                    members,
                    (member) => `${formatRebar(member?.beam?.botRebar)}|${getDetailMetricKey(member?.beam?.h)}`
                );
                const stirrupUniformInfo = getUniformFrameChainSignature(
                    members,
                    (member) => formatBeamTransverseRebarZones(member?.beam)
                );
                const plan = {
                    representativeBeamId,
                    // Annotation chains are split only by real frame supports. Adjacent beam pieces
                    // created by a crossing wall are annotated once so they do not produce stacked
                    // rebar labels or section markers in the pórtico detail.
                    uniformTopLabel: topUniformInfo.uniform && members.length > 1
                        ? formatRebar(representativeMember?.beam?.topRebar)
                        : "",
                    uniformBottomLabel: bottomUniformInfo.uniform && members.length > 1
                        ? formatRebar(representativeMember?.beam?.botRebar)
                        : "",
                    uniformStirrupLabel: stirrupUniformInfo.uniform
                        ? formatBeamTransverseRebarZones(representativeMember?.beam)
                        : ""
                };

                members.forEach((member) => {
                    if (member?.beam?.id) {
                        chainAnnotationPlanByBeamId.set(member.beam.id, plan);
                    }
                });
            });

            if (includeElevation) {
                braces.forEach((sourceBracing) => {
                    const bracing = normalizeBracingModel(sourceBracing);
                    const bounds = getBracingBoundsForFrame(sourceBracing, type);
                    const start = Math.min(bounds.start, bounds.end);
                    const end = Math.max(bounds.start, bounds.end);
                    const frameSpan = end - start;
                    if (!(frameSpan > EDGE_TOLERANCE)) {
                        return;
                    }
                    const geometryBracing = {
                        ...bracing,
                        x1: 0,
                        y1: 0,
                        x2: frameSpan,
                        y2: 0
                    };
                    const profile = getDxfSteelProfileForElement(bracing);
                    const profileWidth = Math.max(
                        getDxfSteelProfileWidth(profile),
                        getDxfSteelProfileDepth(profile),
                        parsePositiveNumberOrFallback(bracing.b, 0.12, 0.02),
                        parsePositiveNumberOrFallback(bracing.h, 0.12, 0.02)
                    );
                    const braceWallThickness = getDxfSteelProfileWallThickness(profile)
                        || getDxfHssWallThicknessFromName(profile?.name || bracing?.sourceSection || "");
                    const braceLabel = normalizeTextValue(profile?.name || bracing?.sourceSection || bracing?.sourceShape);
                    const hiddenLineTypeScale = 0.1;

                    if (bracing.type === "inverted-v") {
                        const centerMetric = Math.min(
                            Math.max(start + frameSpan / 2 + bracing.centerOffset, start),
                            end
                        );
                        const matchingTopBeam = beamSegments
                            .map((segment) => {
                                const segmentStart = Math.min(segment.start, segment.end);
                                const segmentEnd = Math.max(segment.start, segment.end);
                                const closestPosition = Math.min(Math.max(centerMetric, segmentStart), segmentEnd);
                                return {
                                    ...segment,
                                    braceDistance: Math.abs(centerMetric - closestPosition),
                                    braceCenterDistance: Math.abs(((segmentStart + segmentEnd) / 2) - centerMetric)
                                };
                            })
                            .sort((left, right) => (
                                left.braceDistance - right.braceDistance
                                || left.braceCenterDistance - right.braceCenterDistance
                            ))[0] || null;
                        const matchingBeam = matchingTopBeam?.beam || null;
                        const matchingBeamProfile = matchingBeam && isStructuralSteelElement(matchingBeam)
                            ? getDxfSteelProfileForBeam(matchingBeam)
                            : null;
                        const matchingBeamDepth = matchingBeam
                            ? (isStructuralSteelElement(matchingBeam)
                                ? Math.max(getDxfSteelProfileDepth(matchingBeamProfile), parsePositiveNumberOrFallback(matchingBeam.h, 0.4, 0.1))
                                : parsePositiveNumberOrFallback(matchingBeam.h, 0.4, 0.1))
                            : 0;
                        const braceTopElevation = topElevation - matchingBeamDepth;
                        const resolveBracingSupport = (position) => (
                            getFrameSupportAtPosition(mergedFrameSupports, position)
                            || [...mergedFrameSupports]
                                .filter((support) => Number.isFinite(support?.position))
                                .sort((left, right) => Math.abs(left.position - position) - Math.abs(right.position - position))[0]
                            || null
                        );
                        const leftSupport = resolveBracingSupport(start);
                        const rightSupport = resolveBracingSupport(end);
                        const leftSupportFace = start + Math.max(parsePositiveNumberOrFallback(leftSupport?.width, 0, 0) / 2, 0);
                        const rightSupportFace = end - Math.max(parsePositiveNumberOrFallback(rightSupport?.width, 0, 0) / 2, 0);
                        const connectionInset = 0.08;
                        const minimumHalfSpan = Math.max(profileWidth / 2 + 0.02, 0.04);
                        const leftBottomMetric = Math.min(leftSupportFace + connectionInset, centerMetric - minimumHalfSpan);
                        const rightBottomMetric = Math.max(rightSupportFace - connectionInset, centerMetric + minimumHalfSpan);
                        const bottomY = contentOriginY + baseElevation;
                        const topContact = {
                            x: localizePosition(centerMetric),
                            y: contentOriginY + braceTopElevation
                        };
                        const leftBottom = { x: localizePosition(leftBottomMetric), y: bottomY };
                        const rightBottom = { x: localizePosition(rightBottomMetric), y: bottomY };
                        const halfProfileWidth = profileWidth / 2;
                        const leftTopCenter = getBracingCenterlineTopForInnerFaceContact(
                            leftBottom,
                            topContact,
                            halfProfileWidth,
                            -1
                        );
                        const rightTopCenter = getBracingCenterlineTopForInnerFaceContact(
                            rightBottom,
                            topContact,
                            halfProfileWidth,
                            1
                        );
                        const clipRectangle = {
                            minX: localizePosition(leftSupportFace),
                            maxX: localizePosition(rightSupportFace),
                            minY: bottomY,
                            maxY: topContact.y
                        };

                        drawFrameBracingProfile(
                            dxf,
                            leftBottom.x,
                            leftBottom.y,
                            leftTopCenter.x,
                            leftTopCenter.y,
                            profileWidth,
                            {
                                layer: DXF_BRACING_LAYER,
                                wallThickness: braceWallThickness,
                                hiddenLineTypeScale,
                                label: braceLabel,
                                labelColor: 7,
                                labelSide: 1,
                                textSize: 0.07,
                                clipRectangle
                            }
                        );
                        drawFrameBracingProfile(
                            dxf,
                            rightBottom.x,
                            rightBottom.y,
                            rightTopCenter.x,
                            rightTopCenter.y,
                            profileWidth,
                            {
                                layer: DXF_BRACING_LAYER,
                                wallThickness: braceWallThickness,
                                hiddenLineTypeScale,
                                label: braceLabel,
                                labelColor: 7,
                                labelSide: -1,
                                textSize: 0.07,
                                clipRectangle
                            }
                        );
                        return;
                    }

                    getBracingElevationSegments(geometryBracing, baseElevation, topElevation).forEach((segment) => {
                        drawFrameBracingProfile(
                            dxf,
                            localizePosition(start + segment.a),
                            contentOriginY + segment.z1,
                            localizePosition(start + segment.b),
                            contentOriginY + segment.z2,
                            profileWidth,
                            {
                                layer: DXF_BRACING_LAYER,
                                wallThickness: braceWallThickness,
                                hiddenLineTypeScale,
                                label: braceLabel,
                                labelColor: 7,
                                textSize: 0.07
                            }
                        );
                    });
                });
            }

            beams.forEach((beam, beamIndex) => {
                const { start, end } = beamBounds[beamIndex];
                const span = end - start;
                const isSteelBeam = isStructuralSteelElement(beam);
                const isWoodBeam = isWoodStructuralMaterial(beam?.structuralMaterial);
                const steelProfile = isSteelBeam ? getDxfSteelProfileForBeam(beam) : null;
                const steelProfileDepth = isSteelBeam ? getDxfSteelProfileDepth(steelProfile) : 0;
                const beamHeight = isSteelBeam && steelProfileDepth > EDGE_TOLERANCE
                    ? steelProfileDepth
                    : parsePositiveNumberOrFallback(beam.h, 0.4, 0.1);
                const startSupport = getFrameSupportAtPosition(mergedFrameSupports, start);
                const endSupport = getFrameSupportAtPosition(mergedFrameSupports, end);
                const hasEmbeddedColumnAtStart = hasEmbeddedFrameColumnSupportAtPosition(frameSupports, start);
                const hasEmbeddedColumnAtEnd = hasEmbeddedFrameColumnSupportAtPosition(frameSupports, end);
                const beamStartMetric = start + (startSupport?.width || 0) / 2;
                const beamEndMetric = end - (endSupport?.width || 0) / 2;
                const beamBodyStartMetric = Math.min(beamStartMetric, beamEndMetric);
                const beamBodyEndMetric = Math.max(beamStartMetric, beamEndMetric);
                const beamStart = localizePosition(beamBodyStartMetric);
                const beamEnd = localizePosition(beamBodyEndMetric);
                // The beam body stops at the inner faces of the supports below, but when
                // no support rises above it the upper outline must close at each support's
                // outer face—not at the frame axis/centreline. Any real support above is
                // still clipped out by drawFrameBeamConcreteRectangle.
                const beamTopLineStartMetric = Math.min(start, end) - getFrameEndFaceOffset(startSupport);
                const beamTopLineEndMetric = Math.max(start, end) + getFrameEndFaceOffset(endSupport);
                const beamTopLineStart = localizePosition(beamTopLineStartMetric);
                const beamTopLineEnd = localizePosition(beamTopLineEndMetric);
                const clearSpan = Math.max(beamBodyEndMetric - beamBodyStartMetric, 0);
                const beamBodyCenterX = localizePosition((beamBodyStartMetric + beamBodyEndMetric) / 2);
                const beamChain = chainByBeamId.get(beam.id) || null;
                const isBeamChainStart = !beamChain || Math.abs(Math.min(start, end) - beamChain.start) <= 0.08;
                const isBeamChainEnd = !beamChain || Math.abs(Math.max(start, end) - beamChain.end) <= 0.08;
                // A terminal beam tied to a column or wall has no exposed beam-end
                // closure at its interior face. The exterior support face is the
                // continuous frame outline; the interior face stops at the beam.
                const terminalStartSupport = isBeamChainStart
                    ? (startSupport || getFrameSupportAtBeamEndpoint(mergedFrameSupports, start))
                    : null;
                const terminalEndSupport = isBeamChainEnd
                    ? (endSupport || getFrameSupportAtBeamEndpoint(mergedFrameSupports, end))
                    : null;
                if (terminalStartSupport) {
                    registerTerminalSupportContinuousEdge(terminalStartSupport, "left");
                }
                if (terminalEndSupport) {
                    registerTerminalSupportContinuousEdge(terminalEndSupport, "right");
                }
                const chainAnnotationPlan = beamChain?.members?.length
                    ? (chainAnnotationPlanByBeamId.get(beam.id) || null)
                    : null;
                const isChainAnnotationRepresentative = chainAnnotationPlan?.representativeBeamId === beam.id;
                const supportIntervals = getFrameSupportIntervals(mergedFrameSupports);
                const beamClearIntervals = getFrameClearIntervals(beamBodyStartMetric, beamBodyEndMetric, supportIntervals, 0.04);
                const beamBottomY = contentOriginY + topElevation - beamHeight;
                const spanDimensionY = beamBottomY - frameBeamSpanDimensionOffsetFromBottom;
                const stirrupDetailTextY = beamBottomY - frameStirrupDetailOffsetFromBottom;

                if (isSteelBeam) {
                    if (includeElevation && beamEnd > beamStart + 0.01) {
                        const beamRect = {
                            x1: beamStart,
                            y1: beamBottomY,
                            x2: beamEnd,
                            y2: contentOriginY + topElevation
                        };
                        const beamEnvelopeRect = {
                            x1: Math.min(beamTopLineStart, beamTopLineEnd),
                            y1: beamBottomY,
                            x2: Math.max(beamTopLineStart, beamTopLineEnd),
                            y2: contentOriginY + topElevation
                        };
                        const beamContactRect = {
                            x1: localizePosition(start),
                            y1: beamBottomY,
                            x2: localizePosition(end),
                            y2: contentOriginY + topElevation
                        };
                        drawFrameBeamConcreteRectangle(
                            dxf,
                            "PERFILES_METALICOS",
                            beamStart,
                            beamBottomY,
                            beamEnd - beamStart,
                            beamHeight,
                            {
                                bottomSupportRects: lowerSupportRects,
                                topSupportRects: upperSupportRects,
                                topLineStart: beamTopLineStart,
                                topLineEnd: beamTopLineEnd,
                                // At actual frame supports, the terminal outline is
                                // supplied by the exterior support face, not a vertical
                                // closure across the beam at the interior face.
                                drawLeftEnd: isBeamChainStart && !terminalStartSupport,
                                drawRightEnd: isBeamChainEnd && !terminalEndSupport
                            }
                        );
                        const profileLabel = normalizeTextValue(steelProfile?.name || beam.sourceSection || beam.name);
                        if (profileLabel) {
                            addCenteredText(dxf, "SECCION_TEXTO", (beamStart + beamEnd) / 2, contentOriginY + topElevation + 0.24, profileLabel, 0.12);
                        }
                        beamRects.push(beamRect);
                        beamEnvelopeRects.push(beamEnvelopeRect);
                        beamContactRects.push(beamContactRect);
                    }
                    return;
                }

                if (isWoodBeam) {
                    if (includeElevation && beamEnd > beamStart + 0.01) {
                        const beamRect = {
                            x1: beamStart,
                            y1: beamBottomY,
                            x2: beamEnd,
                            y2: contentOriginY + topElevation
                        };
                        drawFrameBeamConcreteRectangle(
                            dxf,
                            "MADERA",
                            beamStart,
                            beamBottomY,
                            beamEnd - beamStart,
                            beamHeight,
                            {
                                bottomSupportRects: lowerSupportRects,
                                topSupportRects: upperSupportRects,
                                topLineStart: beamTopLineStart,
                                topLineEnd: beamTopLineEnd,
                                drawLeftEnd: isBeamChainStart && !terminalStartSupport,
                                drawRightEnd: isBeamChainEnd && !terminalEndSupport
                            }
                        );
                        const woodLabel = normalizeTextValue(beam.sourceSection || beam.name);
                        if (woodLabel) {
                            addCenteredText(dxf, "SECCION_TEXTO", (beamStart + beamEnd) / 2, contentOriginY + topElevation + 0.24, woodLabel, 0.12);
                        }
                        beamRects.push(beamRect);
                        beamEnvelopeRects.push({ ...beamRect, x1: Math.min(beamTopLineStart, beamTopLineEnd), x2: Math.max(beamTopLineStart, beamTopLineEnd) });
                        beamContactRects.push({ ...beamRect, x1: localizePosition(start), x2: localizePosition(end) });
                    }
                    return;
                }

                if (includeElevation) {
                    const terminalStirrupStartMetric = beamBodyStartMetric + FRAME_TERMINAL_STIRRUP_OFFSET;
                    const terminalStirrupEndMetric = beamBodyEndMetric - FRAME_TERMINAL_STIRRUP_OFFSET;
                    const stirrupIntervals = terminalStirrupEndMetric > terminalStirrupStartMetric + EDGE_TOLERANCE
                        ? getMergedBeamTransverseRebarIntervals(beam, terminalStirrupStartMetric, terminalStirrupEndMetric)
                        : [];
                    const stirrupPositions = Array.from(new Map(
                        stirrupIntervals
                            .flatMap((zoneInterval) => subtractCoordinateIntervals(
                                zoneInterval.start,
                                zoneInterval.end,
                                supportIntervals,
                                EDGE_TOLERANCE
                            ).flatMap((interval) => getMarkerPositions(
                                interval.start,
                                interval.end,
                                getDxfBeamStirrupSpacingMeters(zoneInterval.rebar.spacing),
                                0
                            )))
                            .map((position) => [getDetailMetricKey(position, 3), Number(position.toFixed(3))])
                    ).values()).sort((left, right) => left - right);
                    // Main longitudinal-steel labels sit at a consistent 0.15 m
                    // clear distance from the respective beam face. Their horizontal
                    // offset still separates the top and bottom callouts visually.
                    const FRAME_REBAR_LABEL_HORIZONTAL_OFFSET = 0.20;
                    const FRAME_MAIN_REBAR_LABEL_FACE_OFFSET = 0.15;
                    // Resolve the longest beam body that remains outside supports before
                    // placing labels. The label and leader must never target a column/wall.
                    const longestClearInterval = [...beamClearIntervals]
                        .sort((left, right) => (right.end - right.start) - (left.end - left.start))[0] || null;
                    const annotationStartX = longestClearInterval ? localizePosition(longestClearInterval.start) : Number.NaN;
                    const annotationEndX = longestClearInterval ? localizePosition(longestClearInterval.end) : Number.NaN;
                    const annotationSpan = Number.isFinite(annotationStartX) && Number.isFinite(annotationEndX)
                        ? Math.max(annotationEndX - annotationStartX, 0)
                        : 0;
                    const canAnnotatePrincipalBars = annotationSpan > 0.12;
                    const topLabelCenterX = (canAnnotatePrincipalBars ? annotationStartX : beamStart) + annotationSpan * FRAME_REBAR_LABEL_SPAN_RATIO - FRAME_REBAR_LABEL_HORIZONTAL_OFFSET;
                    const bottomLabelCenterX = (canAnnotatePrincipalBars ? annotationEndX : beamEnd) - annotationSpan * FRAME_REBAR_LABEL_SPAN_RATIO + FRAME_REBAR_LABEL_HORIZONTAL_OFFSET;

                    const additionalSegmentDrawSettings = getFrameAdditionalRebarDrawSettings(
                        contentOriginY,
                        topElevation,
                        beamHeight,
                        barThickness
                    );
                    const getAdditionalSegmentDrawKey = (segment) => {
                        const isTopSegment = segment?.face === "top";
                        return isTopSegment
                            ? [
                                "top",
                                getDetailMetricKey(additionalSegmentDrawSettings.topZ1),
                                getDetailMetricKey(additionalSegmentDrawSettings.topZ2),
                                getDetailMetricKey(additionalSegmentDrawSettings.topLabelY)
                            ].join("|")
                            : [
                                "bottom",
                                getDetailMetricKey(additionalSegmentDrawSettings.bottomZ1),
                                getDetailMetricKey(additionalSegmentDrawSettings.bottomZ2),
                                getDetailMetricKey(additionalSegmentDrawSettings.bottomLabelY)
                            ].join("|");
                    };
                    const additionalStartAnchor = resolveFrameLongitudinalTerminalAnchor(
                        start,
                        -1,
                        FRAME_ADDITIONAL_TERMINAL_END_CLEARANCE
                    );
                    const additionalEndAnchor = resolveFrameLongitudinalTerminalAnchor(
                        end,
                        1,
                        FRAME_ADDITIONAL_TERMINAL_END_CLEARANCE
                    );
                    const bottomDevelopmentExtensions = beamChain?.bottomDevelopmentExtensionsByBeamId?.get(beam.id) || { start: 0, end: 0 };
                    const additionalSegments = buildBeamAdditionalRebarSegments(beam, {
                        bodyStart: beamStart,
                        bodyEnd: beamEnd,
                        anchorStart: localizePosition(start),
                        anchorEnd: localizePosition(end),
                        // At a terminal frame end, continue the additional bars through
                        // the supporting wall/column/beam. The hook itself finishes
                        // 0.14 m before that support's exterior face.
                        terminalAnchorStart: localizePosition(additionalStartAnchor.position),
                        terminalAnchorEnd: localizePosition(additionalEndAnchor.position),
                        terminalStartHookInset: FRAME_ADDITIONAL_TERMINAL_END_CLEARANCE,
                        terminalEndHookInset: FRAME_ADDITIONAL_TERMINAL_END_CLEARANCE,
                        bottomDevelopmentStartExtension: bottomDevelopmentExtensions.start,
                        bottomDevelopmentEndExtension: bottomDevelopmentExtensions.end,
                        bottomDevelopmentStartDimensionLength: bottomDevelopmentExtensions.startDimensionLength,
                        bottomDevelopmentEndDimensionLength: bottomDevelopmentExtensions.endDimensionLength,
                        bottomDevelopmentStartCriticalX: Number.isFinite(bottomDevelopmentExtensions.startCriticalPosition)
                            ? localizePosition(bottomDevelopmentExtensions.startCriticalPosition)
                            : Number.NaN,
                        bottomDevelopmentEndCriticalX: Number.isFinite(bottomDevelopmentExtensions.endCriticalPosition)
                            ? localizePosition(bottomDevelopmentExtensions.endCriticalPosition)
                            : Number.NaN,
                        bottomDevelopmentStartBarEndX: Number.isFinite(bottomDevelopmentExtensions.startBarEndPosition)
                            ? localizePosition(bottomDevelopmentExtensions.startBarEndPosition)
                            : Number.NaN,
                        bottomDevelopmentEndBarEndX: Number.isFinite(bottomDevelopmentExtensions.endBarEndPosition)
                            ? localizePosition(bottomDevelopmentExtensions.endBarEndPosition)
                            : Number.NaN,
                        axisType: type,
                        chain: beamChain
                    })
                        .filter((segment) => !consumedDirectAdditionalZoneKeys.has(
                            getBeamAdditionalSegmentConsumptionKey(beam.id, segment.key)
                        ))
                        .map((segment) => ({
                            ...segment,
                            ...additionalSegmentDrawSettings,
                            labelSize: frameDetailTextHeight,
                            drawKey: getAdditionalSegmentDrawKey(segment)
                        }));

                    frameAdditionalRebarSegments.push(...additionalSegments);

                    if (beamEnd > beamStart + 0.01) {
                        const beamRect = {
                            x1: beamStart,
                            y1: contentOriginY + topElevation - beamHeight,
                            x2: beamEnd,
                            y2: contentOriginY + topElevation
                        };
                        const beamEnvelopeRect = {
                            x1: Math.min(beamTopLineStart, beamTopLineEnd),
                            y1: contentOriginY + topElevation - beamHeight,
                            x2: Math.max(beamTopLineStart, beamTopLineEnd),
                            y2: contentOriginY + topElevation
                        };
                        const beamContactRect = {
                            x1: localizePosition(start),
                            y1: contentOriginY + topElevation - beamHeight,
                            x2: localizePosition(end),
                            y2: contentOriginY + topElevation
                        };
                        drawFrameBeamConcreteRectangle(
                            dxf,
                            "CONCRETO_PORTICO",
                            beamStart,
                            contentOriginY + topElevation - beamHeight,
                            beamEnd - beamStart,
                            beamHeight,
                            {
                                bottomSupportRects: lowerSupportRects,
                                topSupportRects: upperSupportRects,
                                topLineStart: beamTopLineStart,
                                topLineEnd: beamTopLineEnd,
                                // At actual frame supports, the terminal outline is
                                // supplied by the exterior support face, not a vertical
                                // closure across the beam at the interior face.
                                drawLeftEnd: isBeamChainStart && !terminalStartSupport,
                                drawRightEnd: isBeamChainEnd && !terminalEndSupport
                            }
                        );
                        beamRects.push(beamRect);
                        beamEnvelopeRects.push(beamEnvelopeRect);
                        beamContactRects.push(beamContactRect);
                    }
                    stirrupPositions.forEach((position) => {
                        const localPosition = localizePosition(position);
                        if (includeTransverseSteelFill) {
                            addFilledBarSegment(dxf, "ACERO_TRANSVERSAL", localPosition, contentOriginY + topElevation - concreteCover, localPosition, contentOriginY + topElevation - beamHeight + concreteCover, barThickness / 2, DXF_REBAR_SOLID_COLOR, {
                                roundStart: true,
                                roundEnd: true,
                                capStyle: "semicircle",
                                drawFlatCaps: false,
                                fillStyle: "hatch",
                                hatchLayer: FRAME_STIRRUP_HATCH_LAYER,
                                hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
                                hatchPatternScale: FRAME_REBAR_HATCH_SCALE
                            });
                        } else {
                            addPolylineLine(dxf, "ACERO_TRANSVERSAL", localPosition, contentOriginY + topElevation - concreteCover, localPosition, contentOriginY + topElevation - beamHeight + concreteCover);
                        }
                    });

                    const bottomTargetY = beamChain?.bottomBarYByBeamId?.get(beam.id) ?? (contentOriginY + topElevation - beamHeight + 0.04 + barThickness / 2);
                    const useUniformTopLabel = Boolean(chainAnnotationPlan?.uniformTopLabel);
                    if (canAnnotatePrincipalBars && (!useUniformTopLabel || isChainAnnotationRepresentative)) {
                        const topLabelText = useUniformTopLabel
                            ? chainAnnotationPlan.uniformTopLabel
                            : formatRebar(beam.topRebar);
                        const topCalloutKey = ["top", topLabelText, getDetailMetricKey(annotationStartX, 2), getDetailMetricKey(annotationEndX, 2), getDetailMetricKey(topElevation, 2)].join("|");
                        if (!drawnFrameRebarCalloutKeys.has(topCalloutKey)) {
                            drawnFrameRebarCalloutKeys.add(topCalloutKey);
                        drawCollisionAwareLeaderText(
                            dxf,
                            frameTextResolver,
                            "TEXTO_ACERO",
                            topLabelText,
                            topLabelCenterX,
                            contentOriginY + topElevation + FRAME_MAIN_REBAR_LABEL_FACE_OFFSET,
                            topLabelCenterX,
                            contentOriginY + topElevation - 0.04,
                            frameDetailTextHeight,
                            "above",
                            {
                                axis: "x",
                                minX: annotationStartX,
                                maxX: annotationEndX,
                                followTargetX: true
                            }
                        );
                        }
                    }

                    const useUniformBottomLabel = Boolean(chainAnnotationPlan?.uniformBottomLabel);
                    if (canAnnotatePrincipalBars && (!useUniformBottomLabel || isChainAnnotationRepresentative)) {
                        const bottomLabelText = useUniformBottomLabel
                            ? chainAnnotationPlan.uniformBottomLabel
                            : formatRebar(beam.botRebar);
                        const bottomCalloutKey = ["bottom", bottomLabelText, getDetailMetricKey(annotationStartX, 2), getDetailMetricKey(annotationEndX, 2), getDetailMetricKey(bottomTargetY, 2)].join("|");
                        if (!drawnFrameRebarCalloutKeys.has(bottomCalloutKey)) {
                            drawnFrameRebarCalloutKeys.add(bottomCalloutKey);
                        drawCollisionAwareLeaderText(
                            dxf,
                            frameTextResolver,
                            "TEXTO_ACERO",
                            bottomLabelText,
                            // Shift the lower principal-steel note 0.10 m right.
                            // Keep the target fixed to the left of the label so the
                            // denotation shoulder is mirrored and exits leftward.
                            bottomLabelCenterX + 0.15,
                            contentOriginY + topElevation - beamHeight - FRAME_MAIN_REBAR_LABEL_FACE_OFFSET,
                            bottomLabelCenterX,
                            bottomTargetY,
                            frameDetailTextHeight,
                            "below",
                            {
                                axis: "x",
                                minX: annotationStartX,
                                maxX: annotationEndX
                            }
                        );
                        }
                    }

                    if (!hasEmbeddedColumnAtStart && !hasEmbeddedColumnAtEnd) {
                        const zoneIntervals = getMergedBeamTransverseRebarIntervals(beam, beamBodyStartMetric, beamBodyEndMetric);
                        const drawStirrupDimensionInterval = (interval, rebar) => {
                            if (!interval || !(interval.end - interval.start > EDGE_TOLERANCE)) {
                                return;
                            }
                            const intervalStart = localizePosition(interval.start);
                            const intervalEnd = localizePosition(interval.end);
                            const intervalCenter = (intervalStart + intervalEnd) / 2;
                            addDimension(
                                dxf,
                                "COTAS_SECCION",
                                intervalStart,
                                intervalEnd,
                                spanDimensionY,
                                (interval.end - interval.start).toFixed(2),
                                beamBottomY,
                                { visualScale: frameDetailDimensionScale }
                            );
                            addCenteredText(
                                dxf,
                                "TEXTO_ESTRIBOS",
                                intervalCenter,
                                stirrupDetailTextY,
                                formatFrameElevationStirrupLabel(rebar, DEFAULT_BEAM_STIRRUP_SPACING),
                                frameStirrupDetailTextHeight
                            );
                        };

                        if (zoneIntervals.length === 0) {
                            const midRebar = getBeamDrawingTransverseRebarForZone(beam, "mid", beam.stirrups);
                            beamClearIntervals.forEach((interval) => drawStirrupDimensionInterval(interval, midRebar));
                        } else {
                            zoneIntervals.forEach((zoneInterval) => {
                                subtractCoordinateIntervals(
                                    zoneInterval.start,
                                    zoneInterval.end,
                                    supportIntervals,
                                    EDGE_TOLERANCE
                                ).forEach((interval) => drawStirrupDimensionInterval(interval, zoneInterval.rebar));
                            });
                        }
                    }
                }

                if (includeSectionDetails) {
                    const hasClearBeamBody = clearSpan > 0.01 && beamClearIntervals.length > 0;
                    if (hasClearBeamBody) {
                        // One cut and one section detail per frame-beam span.  The cut is
                        // centered on the clear beam body even when end-zone steel or
                        // transverse reinforcement differs from the midspan condition.
                        const sectionEntry = getFrameMidspanSectionDetailEntry(beam, type);
                        const { cutOffset, zone, sectionKey, sectionSpec } = sectionEntry;
                        const scaledCutOffset = scaleSectionCutOffset(cutOffset, span, clearSpan);
                        const requestedCutPosition = getSectionCutPosition(beamBodyStartMetric, beamBodyEndMetric, scaledCutOffset);
                        const cutPosition = resolveFrameClearCutPosition(requestedCutPosition, beamClearIntervals);
                        if (Number.isFinite(cutPosition)) {
                            const safeCutOffset = Math.max(cutPosition - beamBodyStartMetric, 0);
                            // A frame section is not tied to an individual beam span.  Its identity
                            // always includes b/h and the slab condition at the left and right faces.
                            // Reinforcement is added only when the respective drawing preference is on;
                            // covers, material labels, level, span and cut coordinate never split it.
                            const frameSectionKey = getFrameSectionReferenceKey({
                                beam,
                                levelName: level.name,
                                cutOffset: safeCutOffset,
                                sectionSpec,
                                frameSectionPreferences
                            });
                            let sectionDetail = sectionDetailByKey.get(frameSectionKey) || null;

                            if (!sectionDetail) {
                                const sharedSectionTag = normalizeTextValue(sharedFrameSectionTagByKey?.get(frameSectionKey));
                                const sectionTag = sharedSectionTag || formatFrameSectionTag(sectionIndex);
                                sectionDetail = {
                                    tag: sectionTag,
                                    beam,
                                    levelName: level.name,
                                    cutOffset: safeCutOffset,
                                    zone,
                                    zones: sectionEntry.zones,
                                    sectionSpec,
                                    detailContext: "frame",
                                    // The drawing preference also controls the labels written
                                    // inside this representative cut, not only its reuse key.
                                    frameSectionPreferences,
                                    referenceCount: 0
                                };
                                sectionDetails.push(sectionDetail);
                                if (!sharedSectionTag) {
                                    sectionIndex += 1;
                                    if (sectionTagAllocator) {
                                        sectionTagAllocator.nextIndex = sectionIndex;
                                    }
                                    if (sharedFrameSectionTagByKey) {
                                        sharedFrameSectionTagByKey.set(frameSectionKey, sectionTag);
                                    }
                                }
                            }

                            // Always retain the local alias so every later cut in this sheet points
                            // to the same S-number and to this portico's locally drawn detail.
                            sectionDetailByKey.set(frameSectionKey, sectionDetail);
                            sectionDetail.referenceCount += 1;
                            if (includeElevation) {
                                const markerPosition = localizePosition(cutPosition);
                                const markerPlacement = registerSectionMarkerPlacement(level.id, markerPosition, sectionDetail.tag);
                                if (markerPlacement) {
                                    drawFrameSectionCutMarker(
                                        dxf,
                                        markerPosition,
                                        contentOriginY + topElevation,
                                        beamHeight,
                                        sectionDetail.tag,
                                        {
                                            ...markerPlacement,
                                            style: sectionMarkerStyle,
                                            detailCode: sectionMarkerDetailCode
                                        }
                                    );
                                }
                            }
                        }
                    }
                }
            });

            if (includeElevation) {
                const additionalRebarBridgeMargin = Math.max(concreteCover, 0.05);
                const additionalRebarDimensionBreakIntervals = mergedFrameSupports.map((support) => {
                    const supportCenterX = localizePosition(support.position);
                    const supportWidth = parsePositiveNumberOrFallback(support.width, 0, 0);
                    return {
                        start: supportCenterX - supportWidth / 2,
                        end: supportCenterX + supportWidth / 2
                    };
                });
                drawBeamAdditionalRebarSegments(dxf, frameAdditionalRebarSegments, {
                    // Joint bars are generated above as direct continuous segments. Keep this draw pass from
                    // inventing continuity by post-processing gaps; it should simply render the already-built bars.
                    bridgeIntervals: [],
                    tolerance: additionalRebarBridgeMargin,
                    maxBridgeGap: 0,
                    includeFill: includeLongitudinalSteelFill,
                    fillStyle: "hatch",
                    hatchLayer: FRAME_LONGITUDINAL_HATCH_LAYER,
                    hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
                    hatchPatternScale: FRAME_REBAR_HATCH_SCALE,
                    labelSize: frameDetailTextHeight,
                    textResolver: frameTextResolver,
                    drawLengthDimensions: true,
                    lengthDimensionVisualScale: frameDetailDimensionScale,
                    lengthDimensionBreakIntervals: additionalRebarDimensionBreakIntervals
                });
            }
        }

        if (includeElevation) {
            frameBeamRectsByLevel.set(level.id, beamRects);
            frameBeamEnvelopeRectsByLevel.set(level.id, beamEnvelopeRects);
            frameBeamContactRectsByLevel.set(level.id, beamContactRects);
            const previousLevel = frameLevels[levelIndex - 1] || null;
            // Use the full beam envelope, including the support width at each end,
            // when clipping column/wall sides. A support must stop at the beam face
            // even when its outer side lies outside the clear beam body.
            const beamRectsBelow = previousLevel ? (frameBeamEnvelopeRectsByLevel.get(previousLevel.id) || []) : [];
            const beamRectsAbove = beamEnvelopeRects;
            const beamContactRectsBelow = previousLevel ? (frameBeamContactRectsByLevel.get(previousLevel.id) || []) : [];
            const beamContactRectsAbove = beamContactRects;
            const supportVerticalClipRects = getFrameClipRectangles([
                ...beamRectsBelow,
                ...beamRectsAbove
            ]);
            const renderedFrameSupports = [...mergedFrameSupports].sort((left, right) => {
                const priorityDelta = getFrameSupportDrawPriority(left) - getFrameSupportDrawPriority(right);
                if (priorityDelta !== 0) {
                    return priorityDelta;
                }

                const leftStart = left.position - left.width / 2;
                const rightStart = right.position - right.width / 2;
                return leftStart - rightStart || left.width - right.width;
            });

            renderedFrameSupports.forEach((support) => {
                if (!(support.width > 0) || !(support.height > 0)) {
                    return;
                }

                const supportLeft = localizePosition(support.position) - support.width / 2;
                const supportBottomOffset = parseNumberOrFallback(support?.verticalBottomOffset, 0);
                const supportTopOffset = parseNumberOrFallback(
                    support?.verticalTopOffset,
                    supportBottomOffset + parsePositiveNumberOrFallback(support?.height, 0, 0)
                );
                const supportHeight = supportTopOffset - supportBottomOffset;
                if (!(supportHeight > EDGE_TOLERANCE)) {
                    return;
                }
                const supportBottom = contentOriginY + baseElevation + supportBottomOffset;
                const supportTop = supportBottom + supportHeight;
                const skipEdges = support.kind === "wall"
                    ? getFrameWallTerminalSkipEdges(support, renderedFrameSupports)
                    : support.kind === "column"
                        ? (Array.isArray(support.hiddenEdges) ? support.hiddenEdges : [])
                    : [];
                drawFrameSupportConcreteRectangle(
                    dxf,
                    getFrameElevationConcreteLayer(support.layer),
                    supportLeft,
                    supportBottom,
                    support.width,
                    supportHeight,
                    {
                        beamRectsBelow,
                        beamRectsAbove,
                        beamContactRectsBelow,
                        beamContactRectsAbove,
                        skipEdges,
                        continuousVerticalEdges: Array.from(terminalSupportContinuousEdges.get(support) || [])
                    }
                );

                if (support.kind === "column") {
                    if (skipEdges.includes("left")) {
                        drawClippedLineSegment(
                            dxf,
                            "CONCRETO_PORTICO_OCULTO",
                            supportLeft,
                            supportBottom,
                            supportLeft,
                            supportTop,
                            supportVerticalClipRects,
                            0.5
                        );
                    }

                    if (skipEdges.includes("right")) {
                        drawClippedLineSegment(
                            dxf,
                            "CONCRETO_PORTICO_OCULTO",
                            supportLeft + support.width,
                            supportBottom,
                            supportLeft + support.width,
                            supportTop,
                            supportVerticalClipRects,
                            0.5
                        );
                    }
                }
            });
        }

        baseElevation += level.height;
    });

    let rightExtentX = originX + localSpan + (includeElevation ? 2.8 : 1.0);
    if (includeSectionDetails) {
        if (sectionDetails.length > 0) {
            const sectionDetailsOriginX = originX + localSpan + (includeElevation ? 4.2 : 3.0);
            const sectionDetailsOriginY = contentOriginY + totalHeight + (includeElevation ? 1.15 : 1.0);
            const sectionMetrics = drawSectionDetails(dxf, sectionDetails, sectionDetailsOriginX, sectionDetailsOriginY, {
                bottomLimit: contentOriginY - 1.5
            });
            rightExtentX = Math.max(rightExtentX, sectionDetailsOriginX + (sectionMetrics?.width || 0));
        } else if (!includeElevation) {
            addText(dxf, "SECCION_TEXTO", originX, contentOriginY + 0.6, "Sin cortes de seccion definidos para este portico.", 0.14);
        }
    }

    return {
        width: Math.max(rightExtentX - originX, localSpan + 1.0),
        height: totalHeight + 3.0 + frameTitleClearance
    };
}

function getColumnSectionEntriesForElevationStack(stack, anchoredColumnEntries = getAnchoredColumnDetailEntries()) {
    const targetKey = normalizeTextValue(stack?.key);
    const targetPositionKey = normalizeTextValue(stack?.positionKey);
    if (!targetKey && !targetPositionKey) {
        return [];
    }

    return (anchoredColumnEntries?.flatEntries || [])
        .filter((entry) => {
            const entryElevationKey = normalizeTextValue(entry?.elevationKey || getColumnElevationIdentityKey(entry?.column));
            const entryPositionKey = normalizeTextValue(entry?.positionKey);
            return Boolean(
                (targetKey && entryElevationKey === targetKey)
                || (targetPositionKey && entryPositionKey === targetPositionKey)
            );
        })
        .sort((left, right) => (
            parseNumberOrFallback(left?.startLevelIndex, 0) - parseNumberOrFallback(right?.startLevelIndex, 0)
            || parseNumberOrFallback(left?.endLevelIndex, 0) - parseNumberOrFallback(right?.endLevelIndex, 0)
            || String(left?.tag || "").localeCompare(String(right?.tag || ""), undefined, { sensitivity: "base" })
        ));
}

function getColumnSectionEntriesLayoutMetrics(sectionEntries = []) {
    const safeEntries = Array.isArray(sectionEntries) ? sectionEntries : [];
    if (!safeEntries.length) {
        return {
            width: 0,
            height: 0
        };
    }

    let width = 0;
    let height = 0;
    safeEntries.forEach((entry, index) => {
        const detailSize = getColumnSectionDetailBoxSize(entry);
        width = Math.max(width, detailSize.width);
        height += detailSize.height;
        if (index < safeEntries.length - 1) {
            height += SECTION_DETAIL_MARGIN;
        }
    });

    return {
        width,
        height
    };
}

function getColumnElevationRunMidpointY(entry, levels, originY) {
    const safeLevels = Array.isArray(levels) ? levels : [];
    if (!safeLevels.length) {
        return originY;
    }

    const lastLevelIndex = safeLevels.length - 1;
    const startLevelIndex = Math.min(
        Math.max(Number.parseInt(entry?.startLevelIndex, 10) || 0, 0),
        lastLevelIndex
    );
    const endLevelIndex = Math.min(
        Math.max(Number.parseInt(entry?.endLevelIndex, 10) || startLevelIndex, startLevelIndex),
        lastLevelIndex
    );
    const baseY = originY + 1.0;
    const runBottomY = baseY + safeLevels
        .slice(0, startLevelIndex)
        .reduce((sum, level) => sum + getLevelHeightForQuantities(level), 0);
    const runHeight = safeLevels
        .slice(startLevelIndex, endLevelIndex + 1)
        .reduce((sum, level) => sum + getLevelHeightForQuantities(level), 0);

    return runBottomY + runHeight / 2;
}

function getColumnSectionDetailOriginYForElevation(entry, detailSize, levels, originY) {
    const midpointY = getColumnElevationRunMidpointY(entry, levels, originY);
    const sectionHeight = Math.max(parsePositiveNumberOrFallback(detailSize?.sectionHeight, 0, 0), 0);
    // drawColumnSectionDetail places the concrete section 1.05 m below its
    // origin. Position its actual geometric center on the elevation midpoint.
    return midpointY + 1.05 + sectionHeight / 2;
}

function drawColumnElevationWithSectionDetailsSheet(dxf, stack, sectionEntries = [], originY = 0, originX = 0, options = {}) {
    const safeSectionEntries = Array.isArray(sectionEntries) ? sectionEntries : [];
    const sectionMetrics = getColumnSectionEntriesLayoutMetrics(safeSectionEntries);
    const elevationMetrics = drawColumnElevationDetailSheet(dxf, stack, originY, originX, options);
    if (!safeSectionEntries.length) {
        return elevationMetrics;
    }

    const sectionGapX = 1.2;
    const combinedHeight = elevationMetrics.height || 0;
    const sectionStartX = originX + (elevationMetrics.width || 7.25) + sectionGapX;
    const elevationLevels = getColumnElevationDrawableLevels(stack, Array.isArray(projectState.levels) ? projectState.levels : []);

    safeSectionEntries.forEach((entry) => {
        const detailSize = getColumnSectionDetailBoxSize(entry);
        const alignedOriginY = getColumnSectionDetailOriginYForElevation(entry, detailSize, elevationLevels, originY);
        drawColumnSectionDetail(dxf, entry, sectionStartX, alignedOriginY, detailSize);
    });

    return {
        height: combinedHeight,
        width: (elevationMetrics.width || 7.25) + sectionGapX + sectionMetrics.width
    };
}

function buildColumnDetailsDxfExport(selection) {
    const level = getExportLevelFromSelection(selection);
    if (!level || !level.columns.length) {
        throw new Error("Vacio");
    }

    const dxf = createBaseDxfDocument();
    drawStandaloneDetailSheet(
        dxf,
        buildColumnDetailEntries(level),
        `Detalles de columnas | ${level.name}`,
        getColumnSectionDetailBoxSize,
        drawColumnSectionDetail,
        {
            drawHeader: (sheetDxf, layout) => drawColumnPlanHeaderDetail(sheetDxf, level, layout.startX, layout.startY - 0.18, 7.0, 3.25)
        }
    );

    return {
        fileName: getLevelExportFileName("Columnas", selection),
        dxf: finalizeDxfDocument(dxf)
    };
}

function buildWallDetailsDxfExport(selection) {
    const level = getExportLevelFromSelection(selection);
    if (!level || !level.walls.length) {
        throw new Error("Vacio");
    }

    const dxf = createBaseDxfDocument();

    drawStandaloneDetailSheet(
        dxf,
        buildWallDetailEntries(level),
        `Detalles de muros | ${level.name}`,
        (detail) => getWallDetailBoxSize(detail.wall),
        drawWallSectionDetail,
        {
            startX: 0.6,
            startY: 10.8,
            bottomLimit: 0.8,
            titleTextSize: WALL_DETAIL_TEXT_SIZE,
            emptyTextSize: WALL_DETAIL_TEXT_SIZE
        }
    );

    return {
        fileName: getLevelExportFileName("Muros", selection),
        dxf: finalizeDxfDocument(dxf)
    };
}

function getPlanViewSignatureNumber(value, decimals = 4) {
    return parseNumberOrFallback(value, 0).toFixed(decimals);
}

function getPlanViewSignaturePoint(point = {}) {
    return {
        x: getPlanViewSignatureNumber(point?.x),
        y: getPlanViewSignatureNumber(point?.y),
        ...(Number.isFinite(parseNumberOrFallback(point?.z, Number.NaN))
            ? { z: getPlanViewSignatureNumber(point?.z) }
            : {})
    };
}

function getPlanViewSignatureWall(wall) {
    const normalized = normalizeWall(wall);
    return {
        x1: getPlanViewSignatureNumber(normalized.x1),
        y1: getPlanViewSignatureNumber(normalized.y1),
        x2: getPlanViewSignatureNumber(normalized.x2),
        y2: getPlanViewSignatureNumber(normalized.y2),
        b: getPlanViewSignatureNumber(normalized.b),
        material: normalizeTextValue(normalized.material).toLowerCase(),
        name: normalizeTextValue(normalized.name).toLowerCase()
    };
}

function getPlanViewSignatureColumn(column) {
    const normalized = normalizeColumnModel(column);
    const isSteel = isStructuralSteelElement(normalized);
    const steelFootprint = isSteel ? getDxfSteelProfileFootprint(normalized) : null;
    const sectionDesigner = !isSteel ? getDxfSectionDesignerConcrete(normalized) : null;
    const label = isSteel
        ? normalizeTextValue(steelFootprint?.profile?.name || normalized.sourceSection || normalized.sectionName || normalized.name)
        : (normalizeTextValue(normalized.name) || getSmartEntityName("column", normalized));

    return canonicalizeSmartRenameValue({
        x: getPlanViewSignatureNumber(normalized.x),
        y: getPlanViewSignatureNumber(normalized.y),
        b: getPlanViewSignatureNumber(normalized.b),
        h: getPlanViewSignatureNumber(normalized.h),
        label: normalizeTextValue(label).toLowerCase(),
        structuralMaterial: normalized.structuralMaterial,
        rotation: getPlanViewSignatureNumber(getDxfSectionDesignerAngle(normalized)),
        steelProfile: steelFootprint?.profile
            ? canonicalizeSmartRenameValue(steelFootprint.profile)
            : null,
        sectionDesigner: sectionDesigner
            ? canonicalizeSmartRenameValue(sectionDesigner)
            : null
    });
}

function getPlanViewSignatureBeam(beam, level = null) {
    const normalized = normalizeBeamModel(beam);
    const isSteel = isStructuralSteelElement(normalized);
    const steelFootprint = isSteel ? getDxfSteelProfileFootprint(normalized) : null;
    const label = getSlabPlanBeamDisplayLabel(normalized);
    // The peralte (h) of a pórtico beam is not visible in a slab plan: the
    // projected footprint depends on its location and width only. Standalone
    // beams keep h in the signature because their plan label/section identity
    // can change with the member dimensions.
    const isFrameBeam = isBeamPartOfFrame(level, beam);

    return canonicalizeSmartRenameValue({
        x1: getPlanViewSignatureNumber(normalized.x1),
        y1: getPlanViewSignatureNumber(normalized.y1),
        x2: getPlanViewSignatureNumber(normalized.x2),
        y2: getPlanViewSignatureNumber(normalized.y2),
        b: getPlanViewSignatureNumber(normalized.b),
        h: isFrameBeam ? null : getPlanViewSignatureNumber(normalized.h),
        label: normalizeTextValue(label).toLowerCase(),
        structuralMaterial: normalized.structuralMaterial,
        steelProfile: steelFootprint?.profile
            ? canonicalizeSmartRenameValue(steelFootprint.profile)
            : null
    });
}

function getPlanViewSignatureSlab(slab) {
    const normalized = normalizeSlab(slab);
    return canonicalizeSmartRenameValue({
        name: normalizeTextValue(normalized.name).toLowerCase(),
        vertices: (normalized.vertices || []).map((vertex) => getPlanViewSignaturePoint(vertex)),
        b: getPlanViewSignatureNumber(normalized.b),
        h: getPlanViewSignatureNumber(normalized.h),
        structuralMaterial: normalized.structuralMaterial,
        type: normalized.type,
        actionType: normalized.actionType,
        isSloped: normalized.isSloped,
        minZ: getPlanViewSignatureNumber(normalized.minZ),
        maxZ: getPlanViewSignatureNumber(normalized.maxZ),
        slopeHeight: getPlanViewSignatureNumber(normalized.slopeHeight),
        temperatureSteel: normalized.temperatureSteel,
        solid: normalized.solid,
        lightened: normalized.lightened,
        cantilever: normalized.cantilever
    });
}

function getSortedPlanViewSignatureItems(items, getSignature) {
    return (Array.isArray(items) ? items : [])
        .map((item) => getSignature(item))
        .sort((left, right) => JSON.stringify(left).localeCompare(JSON.stringify(right)));
}

function getPlanViewLevelSignature(level, planType = "slab") {
    const normalizedType = normalizeTextValue(planType).toLowerCase();
    if (normalizedType === "column") {
        return JSON.stringify(canonicalizeSmartRenameValue({
            columns: getSortedPlanViewSignatureItems(level?.columns, getPlanViewSignatureColumn)
        }));
    }

    if (normalizedType === "wall") {
        return JSON.stringify(canonicalizeSmartRenameValue({
            walls: getSortedPlanViewSignatureItems(level?.walls, getPlanViewSignatureWall)
        }));
    }

    return JSON.stringify(canonicalizeSmartRenameValue({
        slabs: getSortedPlanViewSignatureItems(level?.slabs, getPlanViewSignatureSlab),
        holes: getSortedPlanViewSignatureItems(level?.holes, getPlanViewSignatureSlab),
        beams: getSortedPlanViewSignatureItems(level?.beams, (beam) => getPlanViewSignatureBeam(beam, level)),
        walls: getSortedPlanViewSignatureItems(level?.walls, getPlanViewSignatureWall),
        columns: getSortedPlanViewSignatureItems(level?.columns, getPlanViewSignatureColumn)
    }));
}

function groupIdenticalPlanViewLevels(levels, planType = "slab") {
    const groupsBySignature = new Map();
    const groups = [];

    (Array.isArray(levels) ? levels : []).forEach((level) => {
        const signature = getPlanViewLevelSignature(level, planType);
        let group = groupsBySignature.get(signature);
        if (!group) {
            group = { level, levels: [], signature };
            groupsBySignature.set(signature, group);
            groups.push(group);
        }
        group.levels.push(level);
    });

    return groups;
}

function getPlanTitleLevelInfo(level) {
    const rawName = normalizeTextValue(level?.name).trim().toUpperCase();
    const explicitNivelMatch = rawName.match(/^NIVEL\s+(.+)$/i);
    const numericMatch = rawName.match(/^(-?\d+(?:\.\d+)?)$/);
    const label = normalizeTextValue(explicitNivelMatch?.[1] || rawName);
    const numeric = Number.parseFloat(explicitNivelMatch?.[1] || (numericMatch ? rawName : ""));
    return {
        label,
        usesNivel: Boolean(explicitNivelMatch || numericMatch),
        numeric: Number.isFinite(numeric) ? numeric : Number.NaN
    };
}

function getGroupedPlanViewTitle(prefix, levels = []) {
    const safeLevels = Array.isArray(levels) ? levels.filter(Boolean) : [];
    if (!safeLevels.length) {
        return normalizeTextValue(prefix).trim();
    }

    const infos = safeLevels.map(getPlanTitleLevelInfo);
    const allUseNivel = infos.every((info) => info.usesNivel);
    const allConsecutive = infos.length > 1
        && infos.every((info) => Number.isFinite(info.numeric))
        && infos.every((info, index) => index === 0 || Math.abs(info.numeric - infos[index - 1].numeric - 1) < 1e-8);

    if (allUseNivel && allConsecutive) {
        return `${prefix} NIVEL ${infos[0].label}@NIVEL ${infos[infos.length - 1].label}`.trim();
    }

    if (allUseNivel) {
        return `${prefix} NIVEL ${infos.map((info) => info.label).join(", ")}`.trim();
    }

    return `${prefix} ${infos.map((info) => info.label).join(", ")}`.trim();
}

function getSlabPlanTitleText(levels) {
    return getGroupedPlanViewTitle("PLANTA DE LOSAS", levels);
}

function getColumnPlanTitleTextForLevels(levels) {
    return getGroupedPlanViewTitle("PLANTA DE COLUMNAS", levels);
}

function getWallPlanTitleTextForLevels(levels) {
    return getGroupedPlanViewTitle("PLANTA DE MUROS", levels);
}

function buildSlabPlanDxfExport(selection) {
    const levels = getSlabExportLevelsFromSelection(selection);
    if (!levels.length) {
        throw new Error(isAllSlabLevelsSelection(selection) ? "Vacio" : "Nivel invalido.");
    }

    if (!levels.some((level) => hasSlabExportContent(level))) {
        throw new Error("Vacio");
    }

    const dxf = createBaseDxfDocument();
    const slabPlanPreferences = normalizeSlabPlanDrawingPreferences(
        projectState.exportDock?.drawingPreferences?.slabPlan,
        { projectCountry: projectState.projectCountry, projectLocation: projectState.projectLocation }
    );
    const frameElevationPreferences = normalizeFrameElevationDrawingPreferences(
        projectState.exportDock?.drawingPreferences?.frameElevation
    );
    const groupedLevels = groupIdenticalPlanViewLevels(levels, "slab");
    let sheetOffsetX = 0;

    groupedLevels.forEach((group) => {
        const level = group.level;
        const bounds = getSlabPlanSheetBounds(level);
        const slabOptions = {
            includePlan: true,
            includeTable: true,
            includeLightenedSectionDetail: false,
            includeSolidReinforcementTable: true,
            includeSolidThicknessTable: true,
            showRepresentativeSteelBars: slabPlanPreferences.showRepresentativeSteelBars !== false,
            includeSteelDetailText: slabPlanPreferences.includeSteelDetailText !== false,
            columnLabelStyle: slabPlanPreferences.columnLabelStyle,
            beamLineStyle: slabPlanPreferences.beamLineStyle,
            beamLineColor: slabPlanPreferences.beamLineColor,
            beamLineTypeScale: slabPlanPreferences.beamLineTypeScale,
            beamLabelStyle: slabPlanPreferences.beamLabelStyle,
            includeFrameBeamIndividualDetails: frameElevationPreferences.includeFrameBeamIndividualDetails === true,
            elementLabelTextSize: slabPlanPreferences.elementLabelTextSize,
            axisDimensionTextSize: slabPlanPreferences.axisDimensionTextSize,
            tablePlacement: "right",
            sheetOffsetX,
            titleText: getSlabPlanTitleText(group.levels)
        };

        drawSlabPlanSheetWithOptions(
            dxf,
            level,
            bounds.minX,
            bounds.maxX,
            bounds.minY,
            bounds.maxY,
            0,
            slabOptions
        );

        sheetOffsetX += getSlabPlanSheetWidthForOptions(bounds.minX, bounds.maxX, slabOptions, level) + SLAB_PLAN_STACK_GAP;
    });

    return {
        fileName: getLevelExportFileName("Plano_de_losa", selection),
        dxf: finalizeDxfDocument(dxf)
    };
}

function getColumnPlanTitleText(level, options = {}) {
    return normalizeTextValue(options.titleText)
        || getColumnPlanTitleTextForLevels([level]);
}

function drawColumnPlanTitleBelow(dxf, level, markerCenterX, planBottom, options = {}) {
    const diameter = Math.max(parsePositiveNumberOrFallback(options.diameter, 0.7, 0.1), 0.1);
    const radius = diameter / 2;
    const titleGap = Math.max(parseNumberOrFallback(options.titleGap, COLUMN_PLAN_TITLE_GAP_BELOW_PLAN), 0.05);
    const bottomClearance = Math.max(parseNumberOrFallback(options.bottomClearance, COLUMN_PLAN_TITLE_BOTTOM_CLEARANCE), 0.05);
    const markerCenterY = planBottom - titleGap - radius;

    drawDetailTitleMarker(
        dxf,
        markerCenterX,
        markerCenterY,
        normalizeTextValue(options.topText) || "PL",
        normalizeTextValue(options.bottomText) || "E-00",
        getColumnPlanTitleText(level, options),
        { diameter }
    );

    return markerCenterY - radius - bottomClearance;
}

function drawColumnPlanHeaderDetail(dxf, level, contentLeft, planTop, contentWidth, planHeight, options = {}) {
    const planBottom = drawColumnPlanDetail(dxf, level, contentLeft, planTop, contentWidth, planHeight, {
        ...options,
        fitToContentBox: true,
        returnBottomGap: 0
    });

    return drawColumnPlanTitleBelow(
        dxf,
        level,
        contentLeft + 0.35,
        planBottom,
        {
            titleGap: options.titleGap ?? 0.16,
            bottomClearance: options.bottomClearanceAfterTitle ?? 0.45,
            topText: options.topText || "PL",
            bottomText: options.bottomText || "E-00"
        }
    );
}

function drawColumnPlanOnlySheet(dxf, level, originY = 0, originX = 0, options = {}) {
    const bounds = getColumnPlanBounds(level);
    const metrics = getPlanViewSheetMetrics(bounds, {
        bottomClearance: 1.25 + COLUMN_PLAN_TITLE_BOTTOM_CLEARANCE
    });
    const contentLeft = originX + COLUMN_PLAN_ONLY_CONTENT_LEFT;
    const diagramTop = originY + metrics.bottomClearance + metrics.planHeight;
    const planBottom = drawColumnPlanDetail(
        dxf,
        level,
        contentLeft,
        diagramTop + 0.18,
        metrics.planWidth,
        metrics.planHeight,
        {
            returnBottomGap: 0,
            elementLabelTextSize: getPlanElementLabelTextSizeForBounds(bounds)
        }
    );
    const titleBottom = drawColumnPlanTitleBelow(
        dxf,
        level,
        contentLeft + 0.35,
        planBottom,
        { topText: "PL", titleText: options.titleText }
    );
    const sheetBottom = Math.min(originY, titleBottom);
    const sheetTop = originY + metrics.height;
    const contentWidth = COLUMN_PLAN_ONLY_CONTENT_LEFT + metrics.width;
    return {
        height: Math.max(sheetTop - sheetBottom, metrics.height) + COLUMN_PLAN_SHEET_STACK_CLEARANCE,
        // `width` remains the absolute right edge for backwards-compatible
        // callers. `left`/`right` make side-by-side placement explicit.
        width: originX + contentWidth,
        left: originX,
        right: originX + contentWidth
    };
}

function drawWallPlanOnlySheet(dxf, level, originY = 0, originX = 0, options = {}) {
    const bounds = getWallPlanBounds(level);
    const metrics = getPlanViewSheetMetrics(bounds);
    const contentLeft = originX + 0.6;
    const drawingOriginY = originY + WALL_PLAN_TITLE_DROP;
    const diagramTop = drawingOriginY + metrics.bottomClearance + metrics.planHeight;
    drawWallLevelPlanDetail(dxf, level, contentLeft, diagramTop + 0.18, metrics.planWidth, metrics.planHeight, {
        elementLabelTextSize: getPlanElementLabelTextSizeForBounds(bounds)
    });
    drawDetailTitleMarker(
        dxf,
        originX + 0.95,
        originY + 0.45,
        "PL",
        "E-00",
        normalizeTextValue(options.titleText) || getWallPlanTitleTextForLevels([level])
    );
    return { height: metrics.height + WALL_PLAN_TITLE_DROP, width: originX + 0.6 + metrics.width };
}

function isFoundationBaseLevel(level) {
    return isFoundationLevel(level)
        || normalizeTextValue(level?.name).trim().toLowerCase() === "base";
}

function hasFoundationPlanSuperstructureContent(level) {
    return Boolean(level && (
        (level.columns?.length || 0) > 0
        || (level.walls?.length || 0) > 0
    ));
}

function getFoundationPlanSuperstructureLevel(foundationLevel) {
    const levels = Array.isArray(projectState?.levels) ? projectState.levels : [];

    if (!levels.length) {
        return foundationLevel || null;
    }

    const foundationLevelIndex = levels.findIndex((item) => (
        item === foundationLevel
        || (item?.id != null && foundationLevel?.id != null && String(item.id) === String(foundationLevel.id))
    ));

    // SAFE imports place zapatas on a Base level. The foundation plan must still
    // show the columns and walls from the first superstructure level above Base.
    if (foundationLevelIndex >= 0) {
        const nextNonBaseLevel = levels
            .slice(foundationLevelIndex + 1)
            .find((item) => !isFoundationBaseLevel(item));

        if (nextNonBaseLevel && hasFoundationPlanSuperstructureContent(nextNonBaseLevel)) {
            return nextNonBaseLevel;
        }
    }

    if (!isFoundationBaseLevel(foundationLevel) && hasFoundationPlanSuperstructureContent(foundationLevel)) {
        return foundationLevel;
    }

    return levels.find((item) => !isFoundationBaseLevel(item) && hasFoundationPlanSuperstructureContent(item))
        || levels.find((item) => !isFoundationBaseLevel(item))
        || foundationLevel
        || null;
}

function getFoundationPlanColumns(level) {
    const sourceLevel = getFoundationPlanSuperstructureLevel(level);
    return (sourceLevel?.columns || []).map((column) => normalizeColumnModel(column));
}

function getFoundationPlanWalls(level) {
    const sourceLevel = getFoundationPlanSuperstructureLevel(level);
    return (sourceLevel?.walls || []).map((wall) => normalizeWall(wall));
}

function getFoundationPlanBeams(level) {
    // Beams on the level carrying the footings are grade beams. Keep their
    // real footprint in the foundation plan and never borrow beams from the
    // superstructure level used for column/wall context.
    return (level?.beams || []).map((beam) => normalizeBeamModel(beam));
}

function getFoundationPlanSheetBounds(level) {
    const foundations = (level?.foundations || []).map((foundation) => normalizeFoundation(foundation));
    const columns = getFoundationPlanColumns(level);
    const walls = getFoundationPlanWalls(level);
    const beams = getFoundationPlanBeams(level);
    const xValues = [];
    const yValues = [];

    foundations.forEach((foundation) => {
        const vertices = Array.isArray(foundation.vertices) && foundation.vertices.length
            ? foundation.vertices
            : normalizeFoundationVertices(foundation);
        vertices.forEach((vertex) => {
            xValues.push(vertex.x);
            yValues.push(vertex.y);
        });
    });

    beams.forEach((beam) => {
        const footprint = getSlabPlanBeamFootprintVertices(beam, getSlabPlanBeamDisplayWidth(beam));
        if (Array.isArray(footprint) && footprint.length) {
            footprint.forEach((vertex) => {
                xValues.push(vertex.x);
                yValues.push(vertex.y);
            });
            return;
        }
        xValues.push(beam.x1, beam.x2);
        yValues.push(beam.y1, beam.y2);
    });

    columns.forEach((column) => {
        const footprint = getColumnFootprint(column);
        xValues.push(column.x - footprint.width / 2, column.x + footprint.width / 2);
        yValues.push(column.y - footprint.height / 2, column.y + footprint.height / 2);
    });

    walls.forEach((wall) => {
        getWallFootprintVertices(wall).forEach((vertex) => {
            xValues.push(vertex.x);
            yValues.push(vertex.y);
        });
    });

    const xBounds = getPlanAxisBounds("x", xValues, 0);
    const yBounds = getPlanAxisBounds("y", yValues, 0);

    return {
        minX: xBounds.min,
        maxX: xBounds.max,
        minY: yBounds.min,
        maxY: yBounds.max,
        xAxisEntries: xBounds.axisEntries,
        yAxisEntries: yBounds.axisEntries
    };
}

