function wrapDxfTextToWidth(text, maxWidth, textSize) {
    const content = sanitizeDxfText(text || "").replace(/\s+/g, " ").trim();
    if (!content) {
        return [];
    }

    const safeMaxWidth = Math.max(parseNumberOrFallback(maxWidth, 0), textSize * 3);
    const words = content.split(" ");
    const lines = [];
    let currentLine = "";

    words.forEach((word) => {
        const candidate = currentLine ? `${currentLine} ${word}` : word;
        if (!currentLine || estimateDxfTextWidth(candidate, textSize) <= safeMaxWidth) {
            currentLine = candidate;
            return;
        }

        lines.push(currentLine);
        currentLine = word;
    });

    if (currentLine) {
        lines.push(currentLine);
    }

    return lines;
}

