function getSolidSlabSectionRepresentativeThickness(level) {
    const thicknesses = (level?.slabs || [])
        .map((slab) => normalizeSlab(slab))
        .filter((slab) => isSolidSlabType(slab.type))
        .map((slab) => parsePositiveNumberOrFallback(slab.h, 0.12, 0.01))
        .filter((thickness) => Number.isFinite(thickness) && thickness > 0);

    if (!thicknesses.length) {
        return 0.12;
    }

    return Math.max(...thicknesses);
}

function getSolidSlabSectionDetailMetrics(level) {
    const representativeThickness = Math.min(
        Math.max(
            getSolidSlabSectionRepresentativeThickness(level),
            SOLID_SLAB_SECTION_MIN_REPRESENTATIVE_THICKNESS
        ),
        SOLID_SLAB_SECTION_MAX_REPRESENTATIVE_THICKNESS
    );
    const floorHeight = SOLID_SLAB_SECTION_FLOOR_THICKNESS * SOLID_SLAB_SECTION_DETAIL_SCALE;
    const mortarHeight = SOLID_SLAB_SECTION_MORTAR_THICKNESS * SOLID_SLAB_SECTION_DETAIL_SCALE;
    const slabHeight = representativeThickness * SOLID_SLAB_SECTION_DETAIL_SCALE;
    const plasterHeight = SOLID_SLAB_SECTION_PLASTER_THICKNESS * SOLID_SLAB_SECTION_DETAIL_SCALE;
    const sectionTopOffset = 0.42;
    const layerHeight = floorHeight + mortarHeight + slabHeight + plasterHeight;

    return {
        width: SOLID_SLAB_SECTION_DETAIL_WIDTH,
        height: sectionTopOffset + layerHeight + SOLID_SLAB_SECTION_TITLE_GAP + SOLID_SLAB_SECTION_BOTTOM_CLEARANCE,
        sectionTopOffset,
        sectionWidth: 5.65,
        floorHeight,
        mortarHeight,
        slabHeight,
        plasterHeight
    };
}

function getSolidSlabSectionDetailHeight(level) {
    if (!getSolidSlabThicknessTableRows(level).length) {
        return 0;
    }

    return getSolidSlabSectionDetailMetrics(level).height;
}

function getSolidSlabFinishDetailLabels() {
    if (isBoliviaProjectCountry(projectState.projectCountry)) {
        return {
            d1: "D1 = CONTRAPISO",
            d2: "D2 = REVOQUE CIELO RASO"
        };
    }

    return {
        d1: "MORTERO DE PISO (D1)",
        d2: "PANETE (D2)"
    };
}

function drawSolidSlabSectionDetail(dxf, plan, level, leftX, topY) {
    if (!getSolidSlabThicknessTableRows(level).length) {
        return 0;
    }

    const metrics = getSolidSlabSectionDetailMetrics(level);
    const finishLabels = getSolidSlabFinishDetailLabels();
    const detailLeft = leftX + 0.38;
    const detailRight = detailLeft + metrics.sectionWidth;
    const floorTopY = topY + metrics.sectionTopOffset;
    const floorBottomY = floorTopY + metrics.floorHeight;
    const mortarBottomY = floorBottomY + metrics.mortarHeight;
    const slabBottomY = mortarBottomY + metrics.slabHeight;
    const plasterBottomY = slabBottomY + metrics.plasterHeight;
    const sectionWidth = detailRight - detailLeft;

    plan.addRectangle("PLANO_LOSA", detailLeft, floorTopY, sectionWidth, metrics.floorHeight);
    plan.addRectangle("PLANO_LOSA", detailLeft, floorBottomY, sectionWidth, metrics.mortarHeight);
    plan.addRectangle("PLANO_LOSA", detailLeft, mortarBottomY, sectionWidth, metrics.slabHeight);
    plan.addRectangle("PLANO_LOSA", detailLeft, slabBottomY, sectionWidth, metrics.plasterHeight);

    // Replace the former individual 45-degree segments with one editable
    // native ANSI31 hatch.  In this writer, a zero pattern rotation produces
    // the standard ANSI31 45-degree line direction.
    plan.addHatch("PLANO_LOSA", [
        { x: detailLeft, y: floorBottomY },
        { x: detailRight, y: floorBottomY },
        { x: detailRight, y: mortarBottomY },
        { x: detailLeft, y: mortarBottomY }
    ], {
        patternName: "ANSI31",
        // ANSI31 repeats every 3.175 pattern units, so this retains the
        // 0.08 m spacing of the former manually drawn hatch.
        patternScale: ANSI31_HATCH_SPACING / 3.175,
        patternAngle: 0,
        hatchStyle: 1
    });

    const floorJointCount = 4;
    for (let index = 1; index < floorJointCount; index += 1) {
        const jointX = detailLeft + (sectionWidth * index) / floorJointCount;
        plan.addLine("PLANO_LOSA", jointX, floorTopY, jointX, floorBottomY);
    }

    plan.addVerticalDimension("COTAS_SECCION", detailLeft - 0.40, mortarBottomY, slabBottomY, "H", detailLeft, { preserveValue: true });
    plan.addVerticalDimension("COTAS_SECCION", detailRight + 0.36, floorBottomY, mortarBottomY, SOLID_SLAB_SECTION_MORTAR_THICKNESS.toFixed(2), detailRight);
    plan.addVerticalDimension("COTAS_SECCION", detailRight + 0.36, slabBottomY, plasterBottomY, SOLID_SLAB_SECTION_PLASTER_THICKNESS.toFixed(2), detailRight);

    plan.drawLeaderText(
        "SECCION_TEXTO",
        "PISO (D3)",
        detailLeft + 1.35,
        floorTopY - 0.32,
        detailLeft + 0.55,
        floorTopY + metrics.floorHeight * 0.5,
        0.12,
        "above"
    );
    plan.drawLeaderText(
        "SECCION_TEXTO",
        finishLabels.d1,
        detailRight - 1.35,
        floorTopY - 0.28,
        detailRight - 1.85,
        floorBottomY + metrics.mortarHeight * 0.52,
        0.12,
        "above"
    );
    plan.drawLeaderText(
        "SECCION_TEXTO",
        "LOSA (D0)",
        detailRight - 1.35,
        slabBottomY - 0.18,
        detailRight - 1.05,
        mortarBottomY + metrics.slabHeight * 0.55,
        0.12,
        "below"
    );
    plan.drawLeaderText(
        "SECCION_TEXTO",
        finishLabels.d2,
        detailLeft + 0.92,
        plasterBottomY + 0.34,
        detailLeft + 1.45,
        slabBottomY + metrics.plasterHeight * 0.5,
        0.12,
        "below"
    );

    const markerLogicalX = leftX + 0.36;
    const markerLogicalY = plasterBottomY + SOLID_SLAB_SECTION_TITLE_GAP;
    const markerX = plan.mapX(markerLogicalX);
    const markerY = plan.mapY(markerLogicalY);
    drawDetailTitleMarker(
        dxf,
        markerX,
        markerY,
        "DLM",
        "E-10",
        "DETALLE SECCION DE LOSA MACIZA",
        { rightLineLength: 4.9 }
    );
    addText(dxf, "SECCION_TEXTO", markerX + 0.42, markerY - 0.30, "ESC. 1:15", 0.15);

    return metrics.height;
}

function getRepresentativeLightenedSlab(level) {
    const candidates = (level?.slabs || [])
        .map((slab) => normalizeSlab(slab))
        .filter((slab) => slab.type === "lightened" && !isCantileverSlab(slab));

    if (!candidates.length) {
        return null;
    }

    return candidates.sort((left, right) => {
        const rightThickness = parsePositiveNumberOrFallback(right.h, 0, 0);
        const leftThickness = parsePositiveNumberOrFallback(left.h, 0, 0);
        if (Math.abs(rightThickness - leftThickness) > EDGE_TOLERANCE) {
            return rightThickness - leftThickness;
        }
        return String(left.name || "").localeCompare(String(right.name || ""), undefined, { numeric: true, sensitivity: "base" });
    })[0];
}

function getLightenedSlabSectionDetailMetrics(level) {
    const representativeSlab = getRepresentativeLightenedSlab(level);
    if (!representativeSlab) {
        return null;
    }

    const representativeThickness = Math.min(
        Math.max(
            parsePositiveNumberOrFallback(representativeSlab.h, DEFAULT_LIGHTENED_CASSETTE_THICKNESS + 0.05, 0.01),
            LIGHTENED_SLAB_SECTION_MIN_REPRESENTATIVE_THICKNESS
        ),
        LIGHTENED_SLAB_SECTION_MAX_REPRESENTATIVE_THICKNESS
    );
    const floorHeight = LIGHTENED_SLAB_SECTION_FLOOR_THICKNESS * LIGHTENED_SLAB_SECTION_DETAIL_SCALE;
    const mortarHeight = LIGHTENED_SLAB_SECTION_MORTAR_THICKNESS * LIGHTENED_SLAB_SECTION_DETAIL_SCALE;
    const slabHeight = representativeThickness * LIGHTENED_SLAB_SECTION_DETAIL_SCALE;
    const plasterHeight = LIGHTENED_SLAB_SECTION_PLASTER_THICKNESS * LIGHTENED_SLAB_SECTION_DETAIL_SCALE;
    const requestedCassetteThickness = parsePositiveNumberOrFallback(
        representativeSlab?.lightened?.cassetteThickness,
        DEFAULT_LIGHTENED_CASSETTE_THICKNESS,
        0.01
    );
    const cassetteThickness = Math.min(
        Math.max(requestedCassetteThickness, LIGHTENED_SLAB_SECTION_MIN_BOVEDILLA_THICKNESS),
        Math.max(representativeThickness - 0.04, LIGHTENED_SLAB_SECTION_MIN_BOVEDILLA_THICKNESS)
    );
    const bovedillaHeight = Math.min(cassetteThickness * LIGHTENED_SLAB_SECTION_DETAIL_SCALE, slabHeight - 0.28);
    const topRibHeight = Math.max(slabHeight - bovedillaHeight, 0.28);
    const sectionTopOffset = 0.42;
    const layerHeight = floorHeight + mortarHeight + slabHeight + plasterHeight;

    return {
        representativeSlab,
        representativeThickness,
        cassetteThickness,
        width: LIGHTENED_SLAB_SECTION_DETAIL_WIDTH,
        height: sectionTopOffset + layerHeight + LIGHTENED_SLAB_SECTION_TITLE_GAP + LIGHTENED_SLAB_SECTION_BOTTOM_CLEARANCE,
        sectionTopOffset,
        sectionWidth: 5.65,
        floorHeight,
        mortarHeight,
        slabHeight,
        plasterHeight,
        bovedillaHeight,
        topRibHeight
    };
}

function getLightenedSlabSectionDetailHeight(level) {
    const metrics = getLightenedSlabSectionDetailMetrics(level);
    return metrics ? metrics.height : 0;
}

function drawLightenedSlabSectionDetail(dxf, plan, level, leftX, topY) {
    const metrics = getLightenedSlabSectionDetailMetrics(level);
    if (!metrics) {
        return 0;
    }

    const detailLeft = leftX + 0.38;
    const detailRight = detailLeft + metrics.sectionWidth;
    const floorTopY = topY + metrics.sectionTopOffset;
    const floorBottomY = floorTopY + metrics.floorHeight;
    const mortarBottomY = floorBottomY + metrics.mortarHeight;
    const slabBottomY = mortarBottomY + metrics.slabHeight;
    const plasterBottomY = slabBottomY + metrics.plasterHeight;
    const sectionWidth = detailRight - detailLeft;
    const bovedillaWidth = sectionWidth * 0.52;
    const bovedillaLeft = detailLeft + (sectionWidth - bovedillaWidth) / 2;
    const bovedillaRight = bovedillaLeft + bovedillaWidth;
    const bovedillaTopY = mortarBottomY + metrics.topRibHeight;

    plan.addRectangle("PLANO_LOSA", detailLeft, floorTopY, sectionWidth, metrics.floorHeight);
    plan.addRectangle("PLANO_LOSA", detailLeft, floorBottomY, sectionWidth, metrics.mortarHeight);
    plan.addRectangle("PLANO_LOSA", detailLeft, mortarBottomY, sectionWidth, metrics.slabHeight);
    plan.addRectangle("PLANO_LOSA", detailLeft, slabBottomY, sectionWidth, metrics.plasterHeight);

    plan.addHatch("PLANO_LOSA", [
        { x: detailLeft, y: floorBottomY },
        { x: detailRight, y: floorBottomY },
        { x: detailRight, y: mortarBottomY },
        { x: detailLeft, y: mortarBottomY }
    ], {
        patternName: "ANSI31",
        patternScale: ANSI31_HATCH_SPACING / 3.175,
        patternAngle: 0,
        hatchStyle: 1
    });

    plan.addHatch("LOSA_BOVEDILLA", [
        { x: bovedillaLeft, y: bovedillaTopY },
        { x: bovedillaRight, y: bovedillaTopY },
        { x: bovedillaRight, y: slabBottomY },
        { x: bovedillaLeft, y: slabBottomY }
    ], {
        patternName: SLAB_PLAN_LIGHTENED_CASSETTE_HATCH_PATTERN,
        patternScale: SLAB_PLAN_LIGHTENED_CASSETTE_HATCH_SCALE,
        patternAngle: 0,
        hatchStyle: 1,
        color: 8
    });
    plan.addRectangle("BOVEDILLAS_LOSA_BORDE", bovedillaLeft, bovedillaTopY, bovedillaWidth, slabBottomY - bovedillaTopY);
    plan.addLine("PLANO_LOSA", bovedillaLeft, mortarBottomY, bovedillaLeft, slabBottomY);
    plan.addLine("PLANO_LOSA", bovedillaRight, mortarBottomY, bovedillaRight, slabBottomY);
    plan.addLine("PLANO_LOSA", detailLeft + 0.15, bovedillaTopY, detailRight - 0.15, bovedillaTopY);

    const floorJointCount = 4;
    for (let index = 1; index < floorJointCount; index += 1) {
        const jointX = detailLeft + (sectionWidth * index) / floorJointCount;
        plan.addLine("PLANO_LOSA", jointX, floorTopY, jointX, floorBottomY);
    }

    plan.addVerticalDimension("COTAS_SECCION", detailLeft - 0.40, mortarBottomY, slabBottomY, "H", detailLeft, { preserveValue: true });
    plan.addVerticalDimension("COTAS_SECCION", detailRight + 0.36, floorBottomY, mortarBottomY, LIGHTENED_SLAB_SECTION_MORTAR_THICKNESS.toFixed(2), detailRight);
    plan.addVerticalDimension("COTAS_SECCION", detailRight + 0.36, bovedillaTopY, slabBottomY, metrics.cassetteThickness.toFixed(2), detailRight);
    plan.addVerticalDimension("COTAS_SECCION", detailRight + 0.36, slabBottomY, plasterBottomY, LIGHTENED_SLAB_SECTION_PLASTER_THICKNESS.toFixed(2), detailRight);

    plan.drawLeaderText(
        "SECCION_TEXTO",
        "PISO (D3)",
        detailLeft + 1.35,
        floorTopY - 0.32,
        detailLeft + 0.55,
        floorTopY + metrics.floorHeight * 0.5,
        0.12,
        "above"
    );
    plan.drawLeaderText(
        "SECCION_TEXTO",
        "MORTERO DE PISO (D1)",
        detailRight - 1.25,
        floorTopY - 0.28,
        detailRight - 1.85,
        floorBottomY + metrics.mortarHeight * 0.52,
        0.12,
        "above"
    );
    plan.drawLeaderText(
        "SECCION_TEXTO",
        "BOVEDILLA",
        detailRight - 0.55,
        bovedillaTopY - 0.25,
        bovedillaRight - 0.18,
        bovedillaTopY + (slabBottomY - bovedillaTopY) * 0.48,
        0.12,
        "above"
    );
    plan.drawLeaderText(
        "SECCION_TEXTO",
        "LOSA",
        detailLeft + 0.85,
        slabBottomY - 0.18,
        detailLeft + 0.95,
        mortarBottomY + metrics.topRibHeight * 0.42,
        0.12,
        "below"
    );
    plan.drawLeaderText(
        "SECCION_TEXTO",
        "PANETE (D2)",
        detailLeft + 0.92,
        plasterBottomY + 0.34,
        detailLeft + 1.45,
        slabBottomY + metrics.plasterHeight * 0.5,
        0.12,
        "below"
    );

    const markerLogicalX = leftX + 0.36;
    const markerLogicalY = plasterBottomY + LIGHTENED_SLAB_SECTION_TITLE_GAP;
    const markerX = plan.mapX(markerLogicalX);
    const markerY = plan.mapY(markerLogicalY);
    drawDetailTitleMarker(
        dxf,
        markerX,
        markerY,
        "DLA",
        "E-04",
        "DETALLE DE SECCION DE LOSA ALIGERADA",
        { rightLineLength: 6.0 }
    );
    addText(dxf, "SECCION_TEXTO", markerX + 0.42, markerY - 0.30, "ESC. 1:15", 0.15);

    return metrics.height;
}

function getSlabPlanSideTablesMetrics(level, options = {}) {
    const includeBovedillaQuantityTable = options.includeBovedillaQuantityTable === true;
    const includeLightenedTable = options.includeTable !== false;
    const includeLightenedSectionDetail = LIGHTENED_SLAB_SECTION_DETAIL_EXPORT_ENABLED
        && options.includeLightenedSectionDetail === true;
    const includeSolidThicknessTable = options.includeSolidThicknessTable === true;
    const includeSolidReinforcementTable = options.includeSolidReinforcementTable === true;
    const bovedillaQuantityHeight = includeBovedillaQuantityTable ? getLevelBovedillaQuantityTableHeight(level) : 0;
    const lightenedHeight = includeLightenedTable ? getLightenedSlabTableHeight(level) : 0;
    const solidThicknessHeight = includeSolidThicknessTable ? getSolidSlabThicknessTableHeight(level) : 0;
    const solidReinforcementHeight = includeSolidReinforcementTable ? getSolidSlabReinforcementTableHeight(level) : 0;
    const solidSectionDetailHeight = solidThicknessHeight > 0 ? getSolidSlabSectionDetailHeight(level) : 0;
    const lightenedSectionDetailHeight = includeLightenedSectionDetail && lightenedHeight > 0
        ? getLightenedSlabSectionDetailHeight(level)
        : 0;
    const visibleTableHeights = [
        solidThicknessHeight,
        solidReinforcementHeight,
        bovedillaQuantityHeight,
        lightenedHeight
    ].filter((height) => height > 0);
    const visibleDetailHeights = [solidSectionDetailHeight, lightenedSectionDetailHeight].filter((height) => height > 0);
    const tableStackHeight = visibleTableHeights.reduce((total, value) => total + value, 0)
        + Math.max(visibleTableHeights.length - 1, 0) * SLAB_PLAN_TABLE_VERTICAL_GAP;
    const detailStackHeight = visibleDetailHeights.reduce((total, value) => total + value, 0)
        + Math.max(visibleDetailHeights.length - 1, 0) * SLAB_PLAN_TABLE_VERTICAL_GAP;
    const height = tableStackHeight
        + (detailStackHeight > 0 && tableStackHeight > 0 ? SLAB_PLAN_TABLE_VERTICAL_GAP : 0)
        + detailStackHeight;
    const width = Math.max(
        solidThicknessHeight > 0 ? getSolidSlabThicknessTableWidth() : 0,
        solidReinforcementHeight > 0 ? getSolidSlabReinforcementTableWidth() : 0,
        bovedillaQuantityHeight > 0 ? getLevelBovedillaQuantityTableWidth() : 0,
        lightenedHeight > 0 ? getLightenedSlabTableWidth() : 0,
        solidSectionDetailHeight > 0 ? SOLID_SLAB_SECTION_DETAIL_WIDTH : 0,
        lightenedSectionDetailHeight > 0 ? LIGHTENED_SLAB_SECTION_DETAIL_WIDTH : 0
    );

    return {
        width,
        height,
        hasBovedillaQuantityTable: bovedillaQuantityHeight > 0,
        hasLightenedTable: lightenedHeight > 0,
        hasSolidReinforcementTable: solidReinforcementHeight > 0,
        hasSolidThicknessTable: solidThicknessHeight > 0,
        hasSolidSectionDetail: solidSectionDetailHeight > 0,
        hasLightenedSectionDetail: lightenedSectionDetailHeight > 0
    };
}

function getSlabPlanSelectedTablesWidth(options = {}) {
    const includeBovedillaQuantityTable = options.includeBovedillaQuantityTable === true;
    const includeLightenedTable = options.includeTable !== false;
    const includeLightenedSectionDetail = LIGHTENED_SLAB_SECTION_DETAIL_EXPORT_ENABLED
        && options.includeLightenedSectionDetail === true;
    const includeSolidThicknessTable = options.includeSolidThicknessTable === true;
    const includeSolidReinforcementTable = options.includeSolidReinforcementTable === true;

    return Math.max(
        includeSolidThicknessTable ? getSolidSlabThicknessTableWidth() : 0,
        includeSolidReinforcementTable ? getSolidSlabReinforcementTableWidth() : 0,
        includeBovedillaQuantityTable ? getLevelBovedillaQuantityTableWidth() : 0,
        includeLightenedTable ? getLightenedSlabTableWidth() : 0,
        includeSolidThicknessTable ? SOLID_SLAB_SECTION_DETAIL_WIDTH : 0,
        includeLightenedSectionDetail ? LIGHTENED_SLAB_SECTION_DETAIL_WIDTH : 0
    );
}

function formatDxfTableNumber(value, decimals = 2) {
    const numericValue = Number.parseFloat(value);
    if (!Number.isFinite(numericValue)) {
        return "0.00";
    }

    return numericValue.toFixed(decimals);
}

const STEEL_DENSITY_KG_PER_CUBIC_METER = REBAR_STEEL_DENSITY_TON_PER_M3 * 1000;

function calculateRoundBarWeightKg(totalLengthMeters, diameterLabel) {
    const safeLength = Math.max(parseNumberOrFallback(totalLengthMeters, 0), 0);
    const diameterMeters = Math.max(parseDiameterInMeters(diameterLabel), 0);
    if (!(safeLength > 0) || !(diameterMeters > 0)) {
        return 0;
    }

    const barAreaSquareMeters = Math.PI * Math.pow(diameterMeters, 2) / 4;
    return STEEL_DENSITY_KG_PER_CUBIC_METER * safeLength * barAreaSquareMeters;
}

const STRUCTURAL_SUMMARY_GROUP_ORDER = [
    "col",
    "tieColumn",
    "beam",
    "tieBeam",
    "wallMasonry",
    "wallConcrete",
    "foundation",
    "slab"
];

function getMasonrySummaryTieEntries() {
    const entries = [];
    const seenTieColumns = new Map();
    (Array.isArray(projectState?.levels) ? projectState.levels : []).forEach((level) => {
        (Array.isArray(level?.walls) ? level.walls : []).forEach((wall) => {
            const normalizedWall = normalizeWall(wall);
            if (normalizedWall.material !== "masonry") {
                return;
            }

            const wallLength = Math.max(getWallPlanInfo(normalizedWall).length, 0);
            const material = normalizeStructuralMaterialSpec(normalizedWall.structuralMaterial);
            const endColumns = getMasonryWallEndColumnEntries(normalizedWall, {
                start: 0,
                end: wallLength,
                length: wallLength
            }, level);

            endColumns.forEach((entry) => {
                const key = `${level?.id || "level"}|${entry.sharedKey || `${getDetailMetricKey(entry.start, 3)}|${getDetailMetricKey(entry.end, 3)}`}`;
                const existing = seenTieColumns.get(key);
                if (existing) {
                    existing.height = Math.max(existing.height, Math.max(normalizedWall.h, 0));
                    return;
                }
                const tieEntry = {
                    type: "tieColumn",
                    element: entry.column,
                    level,
                    sourceWall: normalizedWall,
                    structuralMaterial: material,
                    height: Math.max(normalizedWall.h, 0)
                };
                seenTieColumns.set(key, tieEntry);
                entries.push(tieEntry);
            });

            if (shouldIncludeDxfMasonryTieBeam(level, normalizedWall) && wallLength > 0) {
                entries.push({
                    type: "tieBeam",
                    element: normalizedWall.masonry.tieBeam,
                    level,
                    sourceWall: normalizedWall,
                    structuralMaterial: material,
                    length: wallLength,
                    b: Math.max(normalizedWall.b, 0.05),
                    h: 0.18,
                    coverTop: DRAWING_COVER,
                    coverBottom: DRAWING_COVER,
                    coverSide: DRAWING_COVER
                });
            }
        });
    });
    return entries;
}

function getStructuralSummaryEntries() {
    return [
        ...getProjectQuantityEntries(),
        ...getMasonrySummaryTieEntries()
    ];
}

function getStructuralSummaryGroup(entry) {
    if (entry?.type === "tieColumn") {
        return { key: "tieColumn", label: translate("exportDock.details.summaryGroupTieColumns") };
    }
    if (entry?.type === "tieBeam") {
        return { key: "tieBeam", label: translate("exportDock.details.summaryGroupTieBeams") };
    }
    if (entry?.type !== "wall") {
        return { key: entry?.type || "", label: getQuantityGroupLabel(entry?.type) };
    }
    const normalizedWall = normalizeWall(entry.element);
    const isMasonry = normalizedWall.material === "masonry";
    return {
        key: isMasonry ? "wallMasonry" : "wallConcrete",
        label: translate(isMasonry
            ? "exportDock.details.summaryGroupMasonryWalls"
            : "exportDock.details.summaryGroupConcreteWalls")
    };
}

function getStructuralSummarySteelItems(entry) {
    if (entry?.type === "tieColumn") {
        const column = normalizeMasonryTieColumnSpec(entry.element);
        const longRebar = normalizeColumnLongitudinalRebar(column.longRebar);
        const longBreakdown = getColumnLongitudinalBarBreakdown(longRebar);
        const stirrups = normalizeColumnTransverseRebar(column.stirrups, longRebar);
        const height = Math.max(parseNumberOrFallback(entry.height, entry?.sourceWall?.h), 0);
        const stirrupCount = getQuantityPlacementCount(height, stirrups.spacing);
        return [
            createSteelQuantityLineItem(`${translate("modal.longitudinalSteel")} X`, longBreakdown.xBars, longRebar.xDiameter, height, null, "longitudinal"),
            createSteelQuantityLineItem(`${translate("modal.longitudinalSteel")} Y`, longBreakdown.yBars, longRebar.yDiameter, height, null, "longitudinal"),
            createSteelQuantityLineItem(translate("modal.cornerBars"), longBreakdown.cornerBars, longRebar.cornerDiameter, height, null, "longitudinal"),
            createSteelQuantityLineItem(translate("modal.stirrups"), stirrupCount, stirrups.d, getColumnConfinementSetLength(column.b, column.h, stirrups, longRebar), null, "stirrups")
        ].filter(Boolean);
    }
    if (entry?.type === "tieBeam") {
        const tieBeam = normalizeMasonryTieBeamSpec(entry.element);
        const length = Math.max(parseNumberOrFallback(entry.length, 0), 0);
        const stirrups = normalizeTransverseRebar(tieBeam.stirrups, 0.20);
        const stirrupCount = getQuantityPlacementCount(length, stirrups.spacing);
        const hookLength = getColumnStirrupHookLengthMeters(stirrups.d);
        return [
            createSteelQuantityLineItem(translate("modal.mainTopSteel"), parseBarCount(tieBeam.topRebar?.n), tieBeam.topRebar?.d, length, null, "longitudinal"),
            createSteelQuantityLineItem(translate("modal.mainBottomSteel"), parseBarCount(tieBeam.botRebar?.n), tieBeam.botRebar?.d, length, null, "longitudinal"),
            createSteelQuantityLineItem(
                translate("modal.stirrups"),
                stirrupCount,
                stirrups.d,
                getClosedTieLength(entry.b, entry.h, hookLength, getBeamSideCover(tieBeam.coverTop, tieBeam.coverBottom, 0.03)),
                null,
                "stirrups"
            )
        ].filter(Boolean);
    }
    return getSteelBreakdownForQuantityEntry(entry?.type, entry?.element, entry?.level);
}

function getStructuralSummaryMaterial(entry) {
    if (entry?.type === "tieColumn" || entry?.type === "tieBeam") {
        return normalizeStructuralMaterialSpec(entry.structuralMaterial ?? entry?.sourceWall?.structuralMaterial);
    }
    if (entry?.type === "col") return normalizeStructuralMaterialSpec(normalizeColumnModel(entry.element).structuralMaterial);
    if (entry?.type === "beam") return normalizeStructuralMaterialSpec(normalizeBeamModel(entry.element).structuralMaterial);
    if (entry?.type === "wall") return normalizeStructuralMaterialSpec(normalizeWall(entry.element).structuralMaterial);
    if (entry?.type === "foundation") return normalizeStructuralMaterialSpec(normalizeFoundation(entry.element).structuralMaterial);
    return normalizeStructuralMaterialSpec(normalizeSlab(entry?.element).structuralMaterial);
}

function getSteelSummaryTableRows() {
    const rowMap = new Map();
    getStructuralSummaryEntries().forEach((entry) => {
        const summaryGroup = getStructuralSummaryGroup(entry);
        getStructuralSummarySteelItems(entry).forEach((item) => {
            const diameter = normalizeDiameterLabel(item?.diameter);
            const totalLength = Math.max(parseNumberOrFallback(item?.totalLength, 0), 0);
            const weightKg = calculateRoundBarWeightKg(totalLength, diameter);
            if (!diameter || !(totalLength > 0) || !(weightKg > 0)) return;
            const key = `${summaryGroup.key}|${diameter}`;
            const current = rowMap.get(key) || { type: summaryGroup.key, element: summaryGroup.label, diameter, totalLength: 0, weightKg: 0 };
            current.totalLength += totalLength;
            current.weightKg += weightKg;
            rowMap.set(key, current);
        });
    });
    return Array.from(rowMap.values()).sort((left, right) => {
        const leftIndex = STRUCTURAL_SUMMARY_GROUP_ORDER.indexOf(left.type);
        const rightIndex = STRUCTURAL_SUMMARY_GROUP_ORDER.indexOf(right.type);
        if (leftIndex !== rightIndex) return leftIndex - rightIndex;
        return parseDiameterInMeters(left.diameter) - parseDiameterInMeters(right.diameter);
    });
}

function getMaterialsSummaryRows() {
    const groups = new Map(STRUCTURAL_SUMMARY_GROUP_ORDER.map((groupKey) => ([groupKey, {
        element: groupKey === "wallMasonry" ? translate("exportDock.details.summaryGroupMasonryWalls")
            : groupKey === "wallConcrete" ? translate("exportDock.details.summaryGroupConcreteWalls")
                : groupKey === "tieColumn" ? translate("exportDock.details.summaryGroupTieColumns")
                    : groupKey === "tieBeam" ? translate("exportDock.details.summaryGroupTieBeams")
                        : getQuantityGroupLabel(groupKey),
        concrete: new Set(), steelLongitudinal: new Set(), steelTransverse: new Set()
    }])));
    getStructuralSummaryEntries().forEach((entry) => {
        const group = groups.get(getStructuralSummaryGroup(entry).key);
        if (!group) return;
        const material = getStructuralSummaryMaterial(entry);
        if (material.type !== "steel") group.concrete.add(material.concreteStrength);
        group.steelLongitudinal.add(material.longitudinalSteelStrength);
        group.steelTransverse.add(material.transverseSteelStrength);
    });
    return STRUCTURAL_SUMMARY_GROUP_ORDER.map((groupKey) => groups.get(groupKey)).filter(Boolean).map((group) => ({
        element: group.element,
        concrete: Array.from(group.concrete).sort((a, b) => a - b),
        steelLongitudinal: Array.from(group.steelLongitudinal).sort((a, b) => a - b),
        steelTransverse: Array.from(group.steelTransverse).sort((a, b) => a - b)
    })).filter((row) => row.concrete.length || row.steelLongitudinal.length || row.steelTransverse.length);
}

function formatDxfCoverTableValue(valueMeters) {
    const value = Math.max(parseNumberOrFallback(valueMeters, 0), 0);
    return value > 0 ? formatDxfSpacingLength(value, { kind: "section", decimals: 2 }) : "-";
}

function getStructuralCoverSummaryRows() {
    const rowsBySignature = new Map();
    const addRow = (key, element, top, bottom, sides) => {
        const safeTop = Math.max(parseNumberOrFallback(top, 0), 0);
        const safeBottom = Math.max(parseNumberOrFallback(bottom, 0), 0);
        const safeSides = Math.max(parseNumberOrFallback(sides, 0), 0);
        const signature = [key, safeTop.toFixed(4), safeBottom.toFixed(4), safeSides.toFixed(4)].join("|");
        if (!rowsBySignature.has(signature)) rowsBySignature.set(signature, { key, element, top: safeTop, bottom: safeBottom, sides: safeSides });
    };
    (Array.isArray(projectState?.levels) ? projectState.levels : []).forEach((level) => {
        (level.columns || []).forEach((column) => {
            const normalized = normalizeColumnModel(column);
            const cover = normalizeColumnTransverseRebar(normalized.stirrups, normalized.longRebar).cover;
            addRow("col", getQuantityGroupLabel("col"), cover, cover, cover);
        });
        (level.beams || []).forEach((beam) => {
            const normalized = normalizeBeamModel(beam);
            addRow("beam", getQuantityGroupLabel("beam"), normalized.coverTop, normalized.coverBottom, normalized.coverSide);
        });
        (level.walls || []).forEach((wall) => {
            const normalized = normalizeWall(wall);
            if (normalized.material === "concrete" || normalized.material === "thin_wall") {
                const cover = normalizeWallCover(normalized.concrete.cover, DEFAULT_WALL_COVER);
                addRow(normalized.material === "thin_wall" ? "thinWall" : "wall", getQuantityGroupLabel("wall"), cover, cover, cover);
            }
            if (normalized.material === "masonry") {
                const wallLength = Math.max(getWallPlanInfo(normalized).length, 0);
                getMasonryWallEndColumnEntries(normalized, { start: 0, end: wallLength, length: wallLength }, level).forEach((entry) => {
                    const cover = normalizeColumnTransverseRebar(entry.column.stirrups, entry.column.longRebar).cover;
                    addRow("tieColumn", translate("exportDock.details.summaryGroupTieColumns"), cover, cover, cover);
                });
                if (shouldIncludeDxfMasonryTieBeam(level, normalized)) {
                    addRow("tieBeam", translate("exportDock.details.summaryGroupTieBeams"), DRAWING_COVER, DRAWING_COVER, DRAWING_COVER);
                }
            }
        });
        (level.foundations || []).forEach((foundation) => {
            const normalized = normalizeFoundation(foundation);
            addRow("foundation", getQuantityGroupLabel("foundation"), normalized.coverTop ?? normalized.cover, normalized.coverBottom ?? normalized.cover, normalized.coverSide ?? normalized.cover);
        });
        (level.slabs || []).forEach(() => addRow("slab", getQuantityGroupLabel("slab"), DRAWING_COVER, DRAWING_COVER, DRAWING_COVER));
    });
    const order = ["col", "tieColumn", "beam", "tieBeam", "wall", "thinWall", "foundation", "slab"];
    return Array.from(rowsBySignature.values()).sort((left, right) => order.indexOf(left.key) - order.indexOf(right.key) || left.top - right.top || left.bottom - right.bottom || left.sides - right.sides);
}

function drawStructuralCoverSummarySheet(dxf, originY = 0, options = {}) {
    const rows = getStructuralCoverSummaryRows().map((row) => [row.element, formatDxfCoverTableValue(row.top), formatDxfCoverTableValue(row.bottom), formatDxfCoverTableValue(row.sides)]);
    return drawSimpleDxfTableSheet(dxf, translate("exportDock.details.coversTitle"), [
        { label: translate("exportDock.details.coversHeaderElement"), width: 3.0 },
        { label: translate("exportDock.details.coversHeaderTop"), width: 1.7 },
        { label: translate("exportDock.details.coversHeaderBottom"), width: 1.7 },
        { label: translate("exportDock.details.coversHeaderSides"), width: 1.7 }
    ], rows, originY, { minimumHeight: 4.6, textSize: options.textSize, left: options.left });
}

function drawSimpleDxfTableSheet(dxf, title, columns, rows, originY = 0, options = {}) {
    const left = options.left ?? 0.6;
    const titleGap = options.titleGap ?? 0.5;
    const headerHeight = options.headerHeight ?? 0.4;
    const rowHeight = options.rowHeight ?? 0.38;
    const minimumHeight = options.minimumHeight ?? 4.8;
    const baseTextSize = normalizeDrawingItemTextSize(options.textSize, 0.15);
    const titleTextSize = normalizeDrawingItemTextSize(options.titleTextSize, Math.max(baseTextSize, 0.16));
    const headerTextSize = normalizeDrawingItemTextSize(options.headerTextSize, Math.max(baseTextSize * 0.75, 0.08));
    const bodyTextSize = normalizeDrawingItemTextSize(options.bodyTextSize, Math.max(baseTextSize * 0.68, 0.075));
    const tableWidth = columns.reduce((sum, column) => sum + column.width, 0);
    const safeRows = rows.length > 0 ? rows : [columns.map(() => "-")];
    const totalHeight = Math.max(titleGap + headerHeight + safeRows.length * rowHeight + 1.0, minimumHeight);
    const sheetTop = originY + totalHeight;
    const headerBottom = sheetTop - 1.0 - headerHeight;

    addText(dxf, "SECCION_TEXTO", left, sheetTop - 0.45, title, titleTextSize);

    let headerX = left;
    columns.forEach((column, columnIndex) => {
        addRectangle(dxf, DXF_TABLE_LINE_LAYER, headerX, headerBottom, column.width, headerHeight);
        addCenteredText(dxf, "SECCION_TEXTO", headerX + column.width / 2, headerBottom + headerHeight / 2, column.label, headerTextSize);

        safeRows.forEach((row, rowIndex) => {
            const rowBottom = headerBottom - rowHeight * (rowIndex + 1);
            addRectangle(dxf, DXF_TABLE_LINE_LAYER, headerX, rowBottom, column.width, rowHeight);
            addCenteredText(dxf, "SECCION_TEXTO", headerX + column.width / 2, rowBottom + rowHeight / 2, String(row[columnIndex] ?? "-"), bodyTextSize);
        });

        headerX += column.width;
    });

    addRectangle(dxf, DXF_TABLE_LINE_LAYER, left, headerBottom - rowHeight * safeRows.length, tableWidth, headerHeight + rowHeight * safeRows.length);

    return {
        width: tableWidth,
        height: totalHeight
    };
}


function getBovedillaQuantityRowsForLevel(level) {
    const rowMap = new Map();

    (Array.isArray(level?.slabs) ? level.slabs : []).forEach((slab) => {
        const normalizedSlab = normalizeSlab(slab);
        if (normalizeSlabType(normalizedSlab.type) !== "lightened") {
            return;
        }

        const lightened = normalizeLightenedSlabConfig(normalizedSlab.lightened);
        const layout = getLightenedCassetteLayout(normalizedSlab);
        const quantity = getLightenedCassetteRects(normalizedSlab).length;
        if (!(quantity > 0)) {
            return;
        }

        const width = Math.max(parsePositiveNumberOrFallback(layout?.cassetteWidth, lightened.cassetteWidth, 0.001), 0);
        const length = Math.max(parsePositiveNumberOrFallback(layout?.cassetteHeight, lightened.cassetteHeight, 0.001), 0);
        const thickness = Math.max(parsePositiveNumberOrFallback(lightened.cassetteThickness, 0, 0.001), 0);
        if (!(width > 0) || !(length > 0) || !(thickness > 0)) {
            return;
        }

        // Six decimal places keep grouping stable without splitting rows because
        // of harmless floating-point differences in imported or edited slabs.
        const key = [width, length, thickness].map((value) => value.toFixed(6)).join("|");
        const current = rowMap.get(key) || { width, length, thickness, quantity: 0 };
        current.quantity += quantity;
        rowMap.set(key, current);
    });

    const levelName = normalizeTextValue(level?.name) || translate("naming.level");
    return Array.from(rowMap.values())
        .sort((left, right) => (
            left.width - right.width
            || left.length - right.length
            || left.thickness - right.thickness
        ))
        .map((row) => ({
            ...row,
            levelId: level?.id ?? "",
            levelName
        }));
}

function getBovedillaQuantityTableRows() {
    return (Array.isArray(projectState?.levels) ? projectState.levels : [])
        .flatMap((level) => getBovedillaQuantityRowsForLevel(level));
}

function formatBovedillaDimensionForTable(valueMeters, unitSystem = getCurrentUnitSystem()) {
    const normalizedUnitSystem = normalizeUnitSystem(unitSystem);
    const numericValue = convertMetersToUnit(valueMeters, "model", normalizedUnitSystem);
    if (!Number.isFinite(numericValue)) {
        return "0.00";
    }

    // In MKS the designation is deliberately shown exactly as conventional
    // bovedilla notation: 0.50 x 0.50 x 0.15, without repeating the unit.
    if (normalizedUnitSystem === "metric-mks") {
        return numericValue.toFixed(2);
    }

    const decimals = getUnitDefinition("model", normalizedUnitSystem).decimals;
    return numericValue.toFixed(Math.max(0, decimals));
}

function formatBovedillaLabelForTable(row) {
    const unitSystem = getCurrentUnitSystem();
    const unit = getUnitDefinition("model", unitSystem).unit;
    const dimensions = [row.width, row.length, row.thickness]
        .map((value) => formatBovedillaDimensionForTable(value, unitSystem))
        .join(" X ");

    // The MKS output intentionally has no suffix because the table designation
    // is requested as 0.50 X 0.50 X 0.15. Other unit systems carry one suffix
    // at the end so the three dimensions remain easy to scan.
    return normalizeUnitSystem(unitSystem) === "metric-mks"
        ? dimensions
        : `${dimensions} ${unit}`;
}

function formatBovedillaQuantityForTable(quantity) {
    return `${Math.round(Math.max(parseNumberOrFallback(quantity, 0), 0))} ${translate("exportDock.details.bovedillaQuantityUnits")}`;
}

function getBovedillaQuantityTableTotal(rows = getBovedillaQuantityTableRows()) {
    return (Array.isArray(rows) ? rows : []).reduce(
        (total, row) => total + Math.max(parseNumberOrFallback(row?.quantity, 0), 0),
        0
    );
}

function drawBovedillaQuantityTableSheet(dxf, originY = 0, options = {}) {
    const rows = getBovedillaQuantityTableRows();
    if (!rows.length) {
        return { width: 0, height: 0 };
    }

    const left = options.left ?? 0.6;
    const titleGap = 0.5;
    const headerHeight = 0.4;
    const rowHeight = 0.38;
    const minimumHeight = 4.6;
    const baseTextSize = normalizeDrawingItemTextSize(options.textSize, 0.15);
    const titleTextSize = normalizeDrawingItemTextSize(options.titleTextSize, Math.max(baseTextSize, 0.16));
    const headerTextSize = normalizeDrawingItemTextSize(options.headerTextSize, Math.max(baseTextSize * 0.75, 0.08));
    const bodyTextSize = normalizeDrawingItemTextSize(options.bodyTextSize, Math.max(baseTextSize * 0.68, 0.075));
    const columns = [
        { label: translate("exportDock.details.bovedillaQuantityHeaderBovedilla"), width: 4.2 },
        { label: translate("exportDock.details.bovedillaQuantityHeaderLevel"), width: 2.4 },
        { label: translate("exportDock.details.bovedillaQuantityHeaderQuantity"), width: 2.2 },
        { label: translate("exportDock.details.bovedillaQuantityHeaderTotal"), width: 2.2 }
    ];
    const tableWidth = columns.reduce((sum, column) => sum + column.width, 0);
    const totalHeight = Math.max(titleGap + headerHeight + rows.length * rowHeight + 1.0, minimumHeight);
    const sheetTop = originY + totalHeight;
    const headerBottom = sheetTop - 1.0 - headerHeight;
    const bodyBottom = headerBottom - rows.length * rowHeight;
    const totalColumnLeft = left + columns.slice(0, 3).reduce((sum, column) => sum + column.width, 0);

    addText(
        dxf,
        "SECCION_TEXTO",
        left,
        sheetTop - 0.45,
        translate("exportDock.details.bovedillaQuantityTitle"),
        titleTextSize
    );

    let headerX = left;
    columns.forEach((column) => {
        addRectangle(dxf, DXF_TABLE_LINE_LAYER, headerX, headerBottom, column.width, headerHeight);
        addCenteredText(
            dxf,
            "SECCION_TEXTO",
            headerX + column.width / 2,
            headerBottom + headerHeight / 2,
            column.label,
            headerTextSize
        );
        headerX += column.width;
    });

    // The TOTAL body cell is intentionally merged: row separators stop before
    // this last column and only the table's final bottom line closes it.
    addRectangle(dxf, DXF_TABLE_LINE_LAYER, left, bodyBottom, tableWidth, rows.length * rowHeight);
    let separatorX = left;
    columns.slice(0, -1).forEach((column) => {
        separatorX += column.width;
        addLine(dxf, DXF_TABLE_LINE_LAYER, separatorX, bodyBottom, separatorX, headerBottom);
    });
    for (let rowIndex = 1; rowIndex < rows.length; rowIndex += 1) {
        const rowY = headerBottom - rowIndex * rowHeight;
        addLine(dxf, DXF_TABLE_LINE_LAYER, left, rowY, totalColumnLeft, rowY);
    }

    const firstColumnCenter = left + columns[0].width / 2;
    const levelColumnCenter = left + columns[0].width + columns[1].width / 2;
    const quantityColumnCenter = left + columns[0].width + columns[1].width + columns[2].width / 2;

    rows.forEach((row, rowIndex) => {
        const rowCenterY = headerBottom - rowHeight * rowIndex - rowHeight / 2;
        addCenteredText(dxf, "SECCION_TEXTO", firstColumnCenter, rowCenterY, formatBovedillaLabelForTable(row), bodyTextSize);
        addCenteredText(dxf, "SECCION_TEXTO", levelColumnCenter, rowCenterY, String(row.levelName || "-").toUpperCase(), bodyTextSize);
        addCenteredText(dxf, "SECCION_TEXTO", quantityColumnCenter, rowCenterY, formatBovedillaQuantityForTable(row.quantity), bodyTextSize);
    });

    addCenteredText(
        dxf,
        "SECCION_TEXTO",
        totalColumnLeft + columns[3].width / 2,
        bodyBottom + (rows.length * rowHeight) / 2,
        formatBovedillaQuantityForTable(getBovedillaQuantityTableTotal(rows)),
        bodyTextSize
    );

    return {
        width: tableWidth,
        height: totalHeight
    };
}

function getLevelBovedillaQuantityTableColumns() {
    return [
        { key: "bovedilla", label: translate("exportDock.details.bovedillaQuantityHeaderBovedilla"), width: 4.2 },
        { key: "level", label: translate("exportDock.details.bovedillaQuantityHeaderLevel"), width: 2.4 },
        { key: "quantity", label: translate("exportDock.details.bovedillaQuantityHeaderQuantity"), width: 2.2 }
    ];
}

function getLevelBovedillaQuantityTableHeight(level) {
    const rows = getBovedillaQuantityRowsForLevel(level);
    if (!rows.length) {
        return 0;
    }

    const titleGap = 0.42;
    const headerHeight = 0.36;
    const rowHeight = 0.36;
    return titleGap + headerHeight + rows.length * rowHeight + 0.18;
}

function getLevelBovedillaQuantityTableWidth() {
    return getLevelBovedillaQuantityTableColumns().reduce((total, column) => total + column.width, 0);
}

function drawLevelBovedillaQuantityTable(plan, level, leftX, topY, options = {}) {
    const sourceRows = getBovedillaQuantityRowsForLevel(level);
    if (!sourceRows.length) {
        return 0;
    }

    const columns = getLevelBovedillaQuantityTableColumns();
    const titleGap = 0.42;
    const headerHeight = 0.36;
    const rowHeight = 0.36;
    const textSize = normalizeDrawingItemTextSize(options.textSize, 0.10);
    const titleTextSize = normalizeDrawingItemTextSize(options.titleTextSize, Math.max(textSize * 1.2, 0.13));
    const rows = sourceRows.map((row) => ({
        bovedilla: formatBovedillaLabelForTable(row),
        level: String(row.levelName || "-").toUpperCase(),
        quantity: formatBovedillaQuantityForTable(row.quantity)
    }));

    plan.addText(
        SLAB_PLAN_TABLE_TEXT_LAYER,
        leftX,
        topY + 0.18,
        translate("exportDock.slabs.bovedillaQuantityTitle"),
        titleTextSize
    );

    const headerTopY = topY + titleGap;
    let cellX = leftX;
    columns.forEach((column) => {
        plan.addRectangle(DXF_TABLE_LINE_LAYER, cellX, headerTopY, column.width, headerHeight);
        plan.addCenteredText(
            SLAB_PLAN_TABLE_TEXT_LAYER,
            cellX + column.width / 2,
            headerTopY + headerHeight / 2,
            column.label,
            textSize
        );
        cellX += column.width;
    });

    rows.forEach((row, rowIndex) => {
        const rowTopY = headerTopY + headerHeight + rowIndex * rowHeight;
        let rowCellX = leftX;
        columns.forEach((column) => {
            plan.addRectangle(DXF_TABLE_LINE_LAYER, rowCellX, rowTopY, column.width, rowHeight);
            plan.addCenteredText(
                SLAB_PLAN_TABLE_TEXT_LAYER,
                rowCellX + column.width / 2,
                rowTopY + rowHeight / 2,
                row[column.key],
                textSize
            );
            rowCellX += column.width;
        });
    });

    return titleGap + headerHeight + rows.length * rowHeight + 0.18;
}

function drawDevelopmentLengthTableSheet(dxf, originY = 0, options = {}) {
    const settings = getExportDevelopmentLengthSettings(options.exportConfig);
    const values = getSelectedDevelopmentLengthValues(settings);
    const left = options.left ?? 0.6;
    const baseTextSize = normalizeDrawingItemTextSize(options.textSize, 0.15);
    const titleTextSize = normalizeDrawingItemTextSize(options.titleTextSize, Math.max(baseTextSize * 1.12, 0.16));
    const headerTextSize = normalizeDrawingItemTextSize(options.headerTextSize, Math.max(baseTextSize * 0.72, 0.08));
    const bodyTextSize = normalizeDrawingItemTextSize(options.bodyTextSize, Math.max(baseTextSize * 0.76, 0.085));
    const noteTextSize = Math.max(bodyTextSize * 0.9, 0.075);
    const diameterWidth = 0.95;
    const cellWidth = 0.78;
    const groupHeaderHeight = 0.42;
    const fcHeaderHeight = 0.34;
    const rowHeight = 0.36;
    const tableNumber = translate("exportDock.details.developmentLengthTableNumber");
    const title = translate("exportDock.details.developmentLengthTitle");
    const tableWidth = diameterWidth + DEVELOPMENT_LENGTH_FY_GROUPS.length * DEVELOPMENT_LENGTH_FC_VALUES.length * cellWidth;
    const dataHeight = DEVELOPMENT_LENGTH_DIAMETER_ROWS.length * rowHeight;
    const tableHeight = groupHeaderHeight + fcHeaderHeight + dataHeight;
    const totalHeight = Math.max(tableHeight + 1.85, 4.6);
    const sheetTop = originY + totalHeight;
    const tableTop = sheetTop - 1.25;
    const groupHeaderBottom = tableTop - groupHeaderHeight;
    const fcHeaderBottom = groupHeaderBottom - fcHeaderHeight;
    const tableBottom = fcHeaderBottom - dataHeight;
    const centerX = left + tableWidth / 2;
    const titleY = sheetTop - 0.35;
    const subtitleY = titleY - 0.34;
    const tableNumberWidth = Math.min(Math.max(estimateDxfTextWidth(tableNumber, titleTextSize) * 1.05, 1.2), tableWidth * 0.75);

    addCenteredText(dxf, "SECCION_TEXTO", centerX, titleY, tableNumber, titleTextSize);
    addLine(dxf, DXF_TABLE_LINE_LAYER, centerX - tableNumberWidth / 2, titleY - titleTextSize * 0.85, centerX + tableNumberWidth / 2, titleY - titleTextSize * 0.85);
    addCenteredText(dxf, "SECCION_TEXTO", centerX, subtitleY, title, titleTextSize);

    DEVELOPMENT_LENGTH_FY_GROUPS.forEach((fy, groupIndex) => {
        const groupLeft = left + diameterWidth + groupIndex * DEVELOPMENT_LENGTH_FC_VALUES.length * cellWidth;
        const groupWidth = DEVELOPMENT_LENGTH_FC_VALUES.length * cellWidth;
        addRectangle(dxf, DXF_TABLE_LINE_LAYER, groupLeft, groupHeaderBottom, groupWidth, groupHeaderHeight);
        addCenteredText(
            dxf,
            "SECCION_TEXTO",
            groupLeft + groupWidth / 2,
            groupHeaderBottom + groupHeaderHeight / 2,
            translate("exportDock.details.developmentLengthFy", { value: fy }),
            headerTextSize
        );
    });

    addRectangle(dxf, DXF_TABLE_LINE_LAYER, left, fcHeaderBottom, diameterWidth, fcHeaderHeight);
    addLine(dxf, DXF_TABLE_LINE_LAYER, left, groupHeaderBottom, left + diameterWidth, fcHeaderBottom);
    addCenteredText(
        dxf,
        "SECCION_TEXTO",
        left + diameterWidth * 0.73,
        groupHeaderBottom - fcHeaderHeight * 0.28,
        translate("exportDock.details.developmentLengthConcrete"),
        headerTextSize
    );
    addCenteredText(
        dxf,
        "SECCION_TEXTO",
        left + diameterWidth * 0.3,
        fcHeaderBottom + fcHeaderHeight * 0.28,
        translate("exportDock.details.developmentLengthDiameter"),
        headerTextSize
    );

    DEVELOPMENT_LENGTH_FY_GROUPS.forEach((fy, groupIndex) => {
        DEVELOPMENT_LENGTH_FC_VALUES.forEach((fc, fcIndex) => {
            const cellLeft = left + diameterWidth + (groupIndex * DEVELOPMENT_LENGTH_FC_VALUES.length + fcIndex) * cellWidth;
            addRectangle(dxf, DXF_TABLE_LINE_LAYER, cellLeft, fcHeaderBottom, cellWidth, fcHeaderHeight);
            addCenteredText(dxf, "SECCION_TEXTO", cellLeft + cellWidth / 2, fcHeaderBottom + fcHeaderHeight / 2, String(fc), headerTextSize);
        });
    });

    DEVELOPMENT_LENGTH_DIAMETER_ROWS.forEach((row, rowIndex) => {
        const rowBottom = fcHeaderBottom - (rowIndex + 1) * rowHeight;
        addRectangle(dxf, DXF_TABLE_LINE_LAYER, left, rowBottom, diameterWidth, rowHeight);
        addCenteredText(dxf, "SECCION_TEXTO", left + diameterWidth / 2, rowBottom + rowHeight / 2, row.label, bodyTextSize);

        DEVELOPMENT_LENGTH_FY_GROUPS.forEach((fy, groupIndex) => {
            DEVELOPMENT_LENGTH_FC_VALUES.forEach((fc, fcIndex) => {
                const fyKey = String(fy);
                const fcKey = String(fc);
                const cellLeft = left + diameterWidth + (groupIndex * DEVELOPMENT_LENGTH_FC_VALUES.length + fcIndex) * cellWidth;
                const cellValue = values?.[row.id]?.[fyKey]?.[fcKey];
                addRectangle(dxf, DXF_TABLE_LINE_LAYER, cellLeft, rowBottom, cellWidth, rowHeight);
                addCenteredText(dxf, "SECCION_TEXTO", cellLeft + cellWidth / 2, rowBottom + rowHeight / 2, formatDevelopmentLengthCellValue(cellValue), bodyTextSize);
            });
        });
    });

    const groupSeparatorX = left + diameterWidth + DEVELOPMENT_LENGTH_FC_VALUES.length * cellWidth;
    addLine(dxf, DXF_TABLE_LINE_LAYER, groupSeparatorX, tableBottom, groupSeparatorX, tableTop);
    addRectangle(dxf, DXF_TABLE_LINE_LAYER, left, tableBottom, tableWidth, tableHeight);
    addText(dxf, "SECCION_TEXTO", left, tableBottom - 0.28, translate("exportDock.details.developmentLengthNote"), noteTextSize);

    return {
        width: tableWidth,
        height: totalHeight
    };
}

function drawMaterialsSummarySheet(dxf, originY = 0, options = {}) {
    const formatStrengthList = (values) => values.length > 0
        ? values.map((value) => formatMaterialStrengthForUnit(value, { includeUnit: false })).join(" / ")
        : "-";
    const rows = getMaterialsSummaryRows().map((row) => ([
        row.element,
        formatStrengthList(row.concrete),
        formatStrengthList(row.steelLongitudinal),
        formatStrengthList(row.steelTransverse)
    ]));

    return drawSimpleDxfTableSheet(
        dxf,
        translate("exportDock.details.materialsTitle"),
        [
            { label: translate("exportDock.details.materialsHeaderElement"), width: 2.0 },
            { label: withMaterialStrengthUnitLabel(translate("exportDock.details.materialsHeaderConcrete")), width: 1.4 },
            { label: withMaterialStrengthUnitLabel(translate("exportDock.details.materialsHeaderSteelLong")), width: 1.9 },
            { label: withMaterialStrengthUnitLabel(translate("exportDock.details.materialsHeaderSteelTrans")), width: 1.9 }
        ],
        rows,
        originY,
        { minimumHeight: 4.6, textSize: options.textSize, left: options.left }
    );
}

function drawGroupedSteelSummaryDxfTableSheet(dxf, title, columns, rows, originY = 0, options = {}) {
    const left = options.left ?? 0.6;
    const titleGap = options.titleGap ?? 0.5;
    const headerHeight = options.headerHeight ?? 0.4;
    const rowHeight = options.rowHeight ?? 0.38;
    const minimumHeight = options.minimumHeight ?? 4.8;
    const baseTextSize = normalizeDrawingItemTextSize(options.textSize, 0.15);
    const titleTextSize = normalizeDrawingItemTextSize(options.titleTextSize, Math.max(baseTextSize, 0.16));
    const headerTextSize = normalizeDrawingItemTextSize(options.headerTextSize, Math.max(baseTextSize * 0.75, 0.08));
    const bodyTextSize = normalizeDrawingItemTextSize(options.bodyTextSize, Math.max(baseTextSize * 0.68, 0.075));
    const tableWidth = columns.reduce((sum, column) => sum + column.width, 0);
    const safeRows = rows.length > 0
        ? rows
        : [{ type: "", cells: columns.map(() => "-"), isTotal: false }];
    const totalHeight = Math.max(titleGap + headerHeight + safeRows.length * rowHeight + 1.0, minimumHeight);
    const sheetTop = originY + totalHeight;
    const tableTop = sheetTop - 1.0;
    const headerBottom = tableTop - headerHeight;
    const tableBottom = headerBottom - rowHeight * safeRows.length;

    addText(dxf, "SECCION_TEXTO", left, sheetTop - 0.45, title, titleTextSize);
    addRectangle(dxf, DXF_TABLE_LINE_LAYER, left, tableBottom, tableWidth, headerHeight + rowHeight * safeRows.length);

    let currentX = left;
    columns.forEach((column, columnIndex) => {
        if (columnIndex > 0) {
            addLine(dxf, DXF_TABLE_LINE_LAYER, currentX, tableBottom, currentX, tableTop);
        }
        addCenteredText(dxf, "SECCION_TEXTO", currentX + column.width / 2, headerBottom + headerHeight / 2, column.label, headerTextSize);
        currentX += column.width;
    });

    addLine(dxf, DXF_TABLE_LINE_LAYER, left, headerBottom, left + tableWidth, headerBottom);

    safeRows.forEach((row, rowIndex) => {
        const rowTop = headerBottom - rowHeight * rowIndex;
        const rowBottom = rowTop - rowHeight;
        const centerY = rowBottom + rowHeight / 2;
        let cellX = left;
        columns.forEach((column, columnIndex) => {
            addCenteredText(dxf, "SECCION_TEXTO", cellX + column.width / 2, centerY, String(row.cells?.[columnIndex] ?? ""), bodyTextSize);
            cellX += column.width;
        });

        const nextRow = safeRows[rowIndex + 1];
        const shouldDrawDivider = Boolean(nextRow)
            && (row.isTotal || nextRow.isTotal || row.type !== nextRow.type);
        if (shouldDrawDivider) {
            addLine(dxf, DXF_TABLE_LINE_LAYER, left, rowBottom, left + tableWidth, rowBottom);
        }
    });

    return {
        width: tableWidth,
        height: totalHeight
    };
}

function drawSteelSummarySheet(dxf, originY = 0, options = {}) {
    const summaryRows = getSteelSummaryTableRows();
    const totalWeightKg = summaryRows.reduce((sum, row) => sum + row.weightKg, 0);
    const rows = summaryRows.map((row, rowIndex) => {
        const previousRow = summaryRows[rowIndex - 1] || null;
        const showElement = !previousRow || previousRow.type !== row.type;
        return {
            type: row.type,
            isTotal: false,
            cells: [
                showElement ? row.element : "",
                `ø${formatDxfRebarDiameterLabel(row.diameter)}`,
                formatDxfTableNumber(row.totalLength, 2),
                formatDxfTableNumber(row.weightKg, 2),
                ""
            ]
        };
    });

    if (rows.length > 0) {
        rows.push({
            type: "__total",
            isTotal: true,
            cells: [
                translate("exportDock.details.steelSummaryTotalLabel"),
                "",
                "",
                "",
                formatDxfTableNumber(totalWeightKg, 2)
            ]
        });
    }

    return drawGroupedSteelSummaryDxfTableSheet(
        dxf,
        translate("exportDock.details.steelSummaryTitle"),
        [
            { label: translate("exportDock.details.steelSummaryHeaderElement"), width: 2.1 },
            { label: translate("exportDock.details.steelSummaryHeaderDiameter"), width: 1.35 },
            { label: translate("exportDock.details.steelSummaryHeaderLength"), width: 2.05 },
            { label: translate("exportDock.details.steelSummaryHeaderWeight"), width: 1.65 },
            { label: translate("exportDock.details.steelSummaryHeaderTotal"), width: 1.65 }
        ],
        rows,
        originY,
        { minimumHeight: 4.6, textSize: options.textSize, left: options.left }
    );
}

function drawSolidSlabThicknessSheet(dxf, level, originY = 0, options = {}) {
    const rows = getSolidSlabThicknessTableRows(level).map((row) => ([
        row.name,
        row.type,
        row.thickness
    ]));

    return drawSimpleDxfTableSheet(
        dxf,
        `${translate("exportDock.details.slabThicknessTitle")} | ${level.name}`,
        [
            { label: translate("exportDock.details.slabThicknessName"), width: 2.8 },
            { label: translate("exportDock.details.slabThicknessType"), width: 1.8 },
            { label: translate("exportDock.details.slabThicknessThickness"), width: 1.2 }
        ],
        rows,
        originY,
        { minimumHeight: 4.6, textSize: options.textSize }
    );
}

function getSlabPlanSheetHeight(level, minY, maxY) {
    return getSlabPlanSheetHeightForOptions(level, minY, maxY, {
        includePlan: true,
        includeBovedillaQuantityTable: true,
        includeTable: true,
        includeSolidReinforcementTable: true,
        includeSolidThicknessTable: true,
        tablePlacement: "right"
    });
}

function getSlabPlanSheetHeightForOptions(level, minY, maxY, options = {}) {
    const tableMetrics = getSlabPlanSideTablesMetrics(level, options);
    const hasSideTables = tableMetrics.width > 0;
    const includePlan = options.forceTableOnly === true
        ? false
        : (options.includePlan !== false || hasSideTables);
    const tableOnRight = includePlan && hasSideTables && options.tablePlacement === "right";
    const slabTitleVerticalShift = includePlan
        ? Math.max(SLAB_PLAN_TITLE_ORIGIN_Y_OFFSET - SLAB_PLAN_BASE_ORIGIN_Y_OFFSET, 0)
        : 0;
    const planHeight = includePlan ? (maxY - minY) + 3.2 + slabTitleVerticalShift : 0;
    const tableHeight = hasSideTables ? tableMetrics.height + 0.6 : 0;
    const contentHeight = tableOnRight
        ? Math.max(planHeight, tableHeight, 4.2)
        : includePlan && hasSideTables
            ? planHeight + tableHeight
            : Math.max(planHeight, tableHeight, 4.2);

    return contentHeight + SLAB_PLAN_SHEET_VERTICAL_SAFE_MARGIN;
}

function getSlabPlanSheetWidthForOptions(minX, maxX, options = {}, level = null) {
    const tableWidth = level
        ? getSlabPlanSideTablesMetrics(level, options).width
        : getSlabPlanSelectedTablesWidth(options);
    const hasSideTables = tableWidth > 0;
    const includePlan = options.forceTableOnly === true
        ? false
        : (options.includePlan !== false || hasSideTables);
    const tableOnRight = includePlan && hasSideTables && options.tablePlacement === "right";
    const planWidth = includePlan ? (maxX - minX) + 3.2 : 0;
    const contentWidth = tableOnRight
        ? planWidth + SLAB_PLAN_TABLE_RIGHT_GAP + tableWidth
        : Math.max(planWidth, tableWidth, 4.2);

    return Math.max(contentWidth, 4.2) + SLAB_PLAN_HORIZONTAL_SAFE_MARGIN;
}

function drawSlabPlanSheetWithOptions(dxf, level, minX, maxX, minY, maxY, sheetOffsetY = 0, options = {}) {
    const tableMetrics = getSlabPlanSideTablesMetrics(level, options);
    const includeBovedillaQuantityTable = tableMetrics.hasBovedillaQuantityTable;
    const includeLightenedTable = tableMetrics.hasLightenedTable;
    const includeSolidThicknessTable = tableMetrics.hasSolidThicknessTable;
    const includeSolidReinforcementTable = tableMetrics.hasSolidReinforcementTable;
    const includeSolidSectionDetail = tableMetrics.hasSolidSectionDetail;
    const includeLightenedSectionDetail = tableMetrics.hasLightenedSectionDetail;
    const includePlan = options.forceTableOnly === true
        ? false
        : (options.includePlan !== false || includeBovedillaQuantityTable || includeLightenedTable || includeSolidThicknessTable || includeSolidReinforcementTable);
    const showRepresentativeSteelBars = normalizeSlabPlanBooleanPreference(
        options.showRepresentativeSteelBars,
        getDefaultSlabPlanRepresentativeSteelBars(projectState.projectCountry, projectState.projectLocation)
    );
    const includeSteelDetailText = normalizeSlabPlanBooleanPreference(
        options.includeSteelDetailText,
        getDefaultSlabPlanSteelDetailText(projectState.projectCountry, projectState.projectLocation)
    );
    const columnLabelStyle = normalizeSlabPlanColumnLabelStyle(
        options.columnLabelStyle,
        getDefaultSlabPlanColumnLabelStyle(projectState.projectCountry, projectState.projectLocation)
    );
    const beamLineStyle = normalizeSlabPlanBeamLineStyle(options.beamLineStyle);
    const beamLineColor = normalizeSlabPlanBeamLineColor(options.beamLineColor);
    const beamLineTypeScale = normalizeSlabPlanBeamLineTypeScale(options.beamLineTypeScale);
    const beamLabelStyle = normalizeSlabPlanBeamLabelStyle(
        options.beamLabelStyle,
        getDefaultSlabPlanBeamLabelStyle(projectState.projectCountry, projectState.projectLocation)
    );
    const planElementLabelTextSize = getPlanElementLabelTextSizeForBounds({ minX, maxX, minY, maxY });
    const xAxisEntries = getPlanAxisEntries("x", minX, maxX, [minX, maxX]);
    const yAxisEntries = getPlanAxisEntries("y", minY, maxY, [minY, maxY]);
    const sheetOffsetX = Number.isFinite(options.sheetOffsetX) ? options.sheetOffsetX : 0;
    const plan = createSlabPlanExportHelpers(
        dxf,
        minX,
        minY,
        maxY,
        sheetOffsetX + 0.6,
        sheetOffsetY + SLAB_PLAN_TITLE_ORIGIN_Y_OFFSET
    );
    const title = `Plano de losa - ${level.name}`;
    const slabMarkerCenterX = plan.mapX(minX) + 0.35;
    const slabMarkerCenterY = plan.mapY(maxY + SLAB_PLAN_TITLE_BELOW_OFFSET);

    drawDetailTitleMarker(
        dxf,
        slabMarkerCenterX,
        slabMarkerCenterY,
        "PL",
        "E-00",
        normalizeTextValue(options.titleText) || getSlabPlanTitleText([level]),
        { rightLineLength: 3.4 }
    );

    if (includePlan) {
        const axisBubbleOffset = SLAB_PLAN_AXIS_BUBBLE_OFFSET;
        const axisBubbleRadius = SLAB_PLAN_AXIS_BUBBLE_RADIUS;
        const axisTextHeight = getPlanAxisDimensionTextSize(options.axisDimensionTextSize, getPlanAnnotationTextHeight());

        xAxisEntries.forEach((entry) => {
            const bubbleY = minY - axisBubbleOffset;

            plan.addLine(
                DXF_AXIS_LINE_LAYER,
                entry.value,
                bubbleY + axisBubbleRadius,
                entry.value,
                maxY + 0.52,
                { lineType: DXF_AXIS_LINE_TYPE, lineTypeScale: PLAN_DRAWING_AXIS_LINE_TYPE_SCALE }
            );

            plan.addAxisBubbleBlock(entry.value, bubbleY, entry.label, {
                layer: "COTAS_EJES",
                radius: axisBubbleRadius,
                textHeight: axisTextHeight
            });
        });

        yAxisEntries.forEach((entry) => {
            const bubbleX = minX - axisBubbleOffset;

            plan.addLine(
                DXF_AXIS_LINE_LAYER,
                bubbleX + axisBubbleRadius,
                entry.value,
                maxX + 0.35,
                entry.value,
                { lineType: DXF_AXIS_LINE_TYPE, lineTypeScale: PLAN_DRAWING_AXIS_LINE_TYPE_SCALE }
            );

            plan.addAxisBubbleBlock(bubbleX, entry.value, entry.label, {
                layer: "COTAS_EJES",
                radius: axisBubbleRadius,
                textHeight: axisTextHeight
            });
        });

        for (let index = 0; index < xAxisEntries.length - 1; index += 1) {
            // createSlabPlanExportHelpers flips the model Y axis for the DXF sheet.
            // Referencing minY places the horizontal axis dimensions on the upper
            // visual side of the slab plan, instead of below it.
            plan.addDimension(
                "COTAS_EJES",
                xAxisEntries[index].value,
                xAxisEntries[index + 1].value,
                minY - SLAB_PLAN_AXIS_DIMENSION_OFFSET,
                (xAxisEntries[index + 1].value - xAxisEntries[index].value).toFixed(2),
                minY - SLAB_PLAN_AXIS_DIMENSION_ORIGIN_OFFSET,
                { textHeight: planElementLabelTextSize }
            );
        }

        for (let index = 0; index < yAxisEntries.length - 1; index += 1) {
            plan.addVerticalDimension(
                "COTAS_EJES",
                minX - SLAB_PLAN_AXIS_DIMENSION_OFFSET,
                yAxisEntries[index].value,
                yAxisEntries[index + 1].value,
                (yAxisEntries[index + 1].value - yAxisEntries[index].value).toFixed(2),
                minX - SLAB_PLAN_AXIS_DIMENSION_ORIGIN_OFFSET,
                { textHeight: planElementLabelTextSize }
            );
        }

        level.slabs.forEach((slab) => addSlabPlanPanel(dxf, slab, level.slabs, plan, level, {
            showRepresentativeSteelBars,
            includeSteelDetailText,
            elementLabelTextSize: planElementLabelTextSize
        }));
        drawSlabPlanStructuralElements(dxf, level, plan, { minX, maxX, minY, maxY }, {
            beamLineStyle,
            beamLineColor,
            beamLineTypeScale,
            beamLabelStyle,
            columnLabelStyle,
            elementLabelTextSize: planElementLabelTextSize,
            includeFrameBeamIndividualDetails: options.includeFrameBeamIndividualDetails === true
        });
    }

    if (includeBovedillaQuantityTable || includeLightenedTable || includeSolidThicknessTable || includeSolidReinforcementTable || includeSolidSectionDetail || includeLightenedSectionDetail) {
        const tableOnRight = includePlan && options.tablePlacement === "right";
        const tableLeftX = tableOnRight
            ? maxX + SLAB_PLAN_TABLE_RIGHT_GAP
            : includePlan && options.tablePlacement === "top-right"
                ? Math.max(
                    minX,
                    maxX - Math.max(
                        getLightenedSlabTableWidth(),
                        getLevelBovedillaQuantityTableWidth(),
                        getSolidSlabReinforcementTableWidth(),
                        getSolidSlabThicknessTableWidth(),
                        SOLID_SLAB_SECTION_DETAIL_WIDTH,
                        LIGHTENED_SLAB_SECTION_DETAIL_WIDTH
                    )
                )
                : minX;
        let tableTopY = tableOnRight ? minY - 0.1 : maxY + 1.45;
        let hasDrawnSlabBlock = false;

        if (includeSolidThicknessTable) {
            const solidTableHeight = drawSolidSlabThicknessTable(plan, level, tableLeftX, tableTopY);
            if (solidTableHeight > 0) {
                tableTopY += solidTableHeight;
                hasDrawnSlabBlock = true;
            }
        }

        if (includeSolidReinforcementTable) {
            if (hasDrawnSlabBlock) {
                tableTopY += SLAB_PLAN_TABLE_VERTICAL_GAP;
            }
            const solidReinforcementHeight = drawSolidSlabReinforcementTable(plan, level, tableLeftX, tableTopY);
            if (solidReinforcementHeight > 0) {
                tableTopY += solidReinforcementHeight;
                hasDrawnSlabBlock = true;
            }
        }

        if (includeBovedillaQuantityTable) {
            if (hasDrawnSlabBlock) {
                tableTopY += SLAB_PLAN_TABLE_VERTICAL_GAP;
            }
            const bovedillaQuantityHeight = drawLevelBovedillaQuantityTable(plan, level, tableLeftX, tableTopY, {
                textSize: options.bovedillaQuantityTextSize
            });
            if (bovedillaQuantityHeight > 0) {
                tableTopY += bovedillaQuantityHeight;
                hasDrawnSlabBlock = true;
            }
        }

        if (includeLightenedTable) {
            if (hasDrawnSlabBlock) {
                tableTopY += SLAB_PLAN_TABLE_VERTICAL_GAP;
            }
            const lightenedTableHeight = drawLightenedSlabTable(plan, level, tableLeftX, tableTopY);
            if (lightenedTableHeight > 0) {
                tableTopY += lightenedTableHeight;
                hasDrawnSlabBlock = true;
            }
        }

        if (includeSolidSectionDetail) {
            if (hasDrawnSlabBlock) {
                tableTopY += SLAB_PLAN_TABLE_VERTICAL_GAP;
            }
            const solidSectionHeight = drawSolidSlabSectionDetail(dxf, plan, level, tableLeftX, tableTopY);
            if (solidSectionHeight > 0) {
                tableTopY += solidSectionHeight;
                hasDrawnSlabBlock = true;
            }
        }

        if (includeLightenedSectionDetail) {
            if (hasDrawnSlabBlock) {
                tableTopY += SLAB_PLAN_TABLE_VERTICAL_GAP;
            }
            drawLightenedSlabSectionDetail(dxf, plan, level, tableLeftX, tableTopY);
        }
    }
}

function drawSlabPlanRegularConcreteColumn(plan, column) {
    if (isCircularColumnSection(column)) {
        const vertices = getDxfCircularColumnPlanPolygon(column);
        if (!Array.isArray(vertices) || vertices.length < 3) {
            return;
        }
        plan.addHatch("CONCRETO_COLUMNAS", vertices, { patternName: "ANSI31", patternScale: 0.03, color: 7 });
        plan.addCircle("CONCRETO_COLUMNAS", column.x, column.y, getColumnDiameter(column) / 2);
        return;
    }

    const vertices = getDxfRegularColumnPlanPoints(column);
    if (!Array.isArray(vertices) || vertices.length < 4) {
        return;
    }

    plan.addFilledQuadrilateral("CONCRETO_COLUMNAS", vertices, 7);
    getPolygonSegments(vertices).forEach((segment) => {
        plan.addLine("CONCRETO_COLUMNAS", segment.x1, segment.y1, segment.x2, segment.y2);
    });
}

function getDxfRotatedProfileFootprint(width, height, rotationRadians = 0) {
    const safeWidth = Math.max(parsePositiveNumberOrFallback(width, 0, 0), 0);
    const safeHeight = Math.max(parsePositiveNumberOrFallback(height, 0, 0), 0);
    const cosine = Math.abs(Math.cos(rotationRadians));
    const sine = Math.abs(Math.sin(rotationRadians));
    return {
        width: safeWidth * cosine + safeHeight * sine,
        height: safeWidth * sine + safeHeight * cosine
    };
}

function drawSlabPlanSheet(dxf, level, minX, maxX, minY, maxY, sheetOffsetY = 0) {
    drawSlabPlanSheetWithOptions(dxf, level, minX, maxX, minY, maxY, sheetOffsetY, {
        includePlan: true,
        includeBovedillaQuantityTable: true,
        includeTable: true,
        includeLightenedSectionDetail: false,
        includeSolidReinforcementTable: true,
        includeSolidThicknessTable: true,
        tablePlacement: "right"
    });
}

function getBeamGlobalPlanDirection(beam) {
    const normalizedBeam = normalizeBeamModel(beam);
    const dx = Math.abs(parseNumberOrFallback(normalizedBeam.x2, 0) - parseNumberOrFallback(normalizedBeam.x1, 0));
    const dy = Math.abs(parseNumberOrFallback(normalizedBeam.y2, 0) - parseNumberOrFallback(normalizedBeam.y1, 0));
    return dx >= dy ? "x" : "y";
}

function isBeamInGlobalDirection(beam, direction = "x") {
    return getBeamGlobalPlanDirection(beam) === direction;
}

function formatIndonesiaBeamPlanMainLabel(rebar) {
    const normalizedRebar = normalizeBeamMainLongitudinalRebar(rebar);
    const count = parseBarCount(normalizedRebar.n, { maximum: MAX_BEAM_MAIN_BAR_COUNT });
    const diameterLabel = normalizeDiameterLabel(normalizedRebar.d);
    if (count <= 0 || !diameterLabel) {
        return "0";
    }
    return `${count}D${diameterLabel}`;
}

function formatIndonesiaBeamPlanSupportLabel(mainRebar, extraRebar) {
    const normalizedMain = normalizeBeamMainLongitudinalRebar(mainRebar);
    const normalizedExtra = normalizeOptionalLongitudinalRebar(extraRebar);
    const mainCount = parseBarCount(normalizedMain.n, { maximum: MAX_BEAM_MAIN_BAR_COUNT });
    const extraCount = parseOptionalBarCount(normalizedExtra.n, { maximum: MAX_BEAM_ADDITIONAL_BAR_COUNT });
    const mainDiameter = normalizeDiameterLabel(normalizedMain.d);
    const extraDiameter = normalizeDiameterLabel(normalizedExtra.d);
    if (mainCount <= 0 || !mainDiameter) {
        return "0";
    }
    if (extraCount <= 0) {
        return String(mainCount);
    }
    if (mainDiameter === extraDiameter) {
        return String(mainCount + extraCount);
    }
    return `${mainCount}D${mainDiameter}+${extraCount}D${extraDiameter}`;
}

function getIndonesiaBeamPlanStirrupZonesInDrawingOrder(beam, direction = "x", zones = null) {
    const normalizedBeam = normalizeBeamModel(beam);
    const normalizedZones = zones || normalizeBeamTransverseRebarZones(normalizedBeam.transverseRebarZones, normalizedBeam.stirrups);

    if (direction === "x") {
        return normalizedBeam.x1 <= normalizedBeam.x2
            ? [normalizedZones.iEnd, normalizedZones.mid, normalizedZones.jEnd]
            : [normalizedZones.jEnd, normalizedZones.mid, normalizedZones.iEnd];
    }

    return normalizedBeam.y1 <= normalizedBeam.y2
        ? [normalizedZones.iEnd, normalizedZones.mid, normalizedZones.jEnd]
        : [normalizedZones.jEnd, normalizedZones.mid, normalizedZones.iEnd];
}

function formatIndonesiaBeamPlanStirrupSpacingMm(spacing) {
    const normalizedSpacing = parsePositiveNumberOrFallback(spacing, DEFAULT_BEAM_STIRRUP_SPACING, 0.01);
    return String(Math.max(Math.round(normalizedSpacing * 1000), 1));
}

function formatIndonesiaBeamPlanStirrupDiameterLabel(diameterLabel, barSet = null) {
    const targetBarSet = normalizeBarSet(barSet || getActiveBarSetForDiameters());
    const convertedLabel = convertDiameterLabelToBarSet(diameterLabel || DEFAULT_TRANSVERSE_DIAMETER, targetBarSet);
    const normalizedLabel = normalizeDiameterLabel(convertedLabel);
    if (!normalizedLabel) {
        return "";
    }

    if (/^d/i.test(normalizedLabel)) {
        return `D${normalizedLabel.replace(/^d/i, "")}`;
    }

    if (targetBarSet === "si" || /^\d+(?:[.,]\d+)?$/.test(normalizedLabel)) {
        return `D${normalizedLabel}`;
    }

    return normalizedLabel;
}

function formatIndonesiaBeamPlanStirrupLabel(beam, direction = "x", options = {}) {
    const normalizedBeam = normalizeBeamModel(beam);
    const zones = normalizeBeamTransverseRebarZones(normalizedBeam.transverseRebarZones, normalizedBeam.stirrups);
    const orderedZones = getIndonesiaBeamPlanStirrupZonesInDrawingOrder(normalizedBeam, direction, zones);
    const diameterSource = orderedZones.find((zone) => normalizeDiameterLabel(zone?.d))
        || normalizeTransverseRebar(normalizedBeam.stirrups, DEFAULT_BEAM_STIRRUP_SPACING)
        || zones.iEnd;
    const diameterLabel = formatIndonesiaBeamPlanStirrupDiameterLabel(diameterSource?.d, options.barSet);
    if (!diameterLabel) {
        return "";
    }

    const spacingLabel = orderedZones
        .map((zone) => formatIndonesiaBeamPlanStirrupSpacingMm(zone?.spacing));
    return `${diameterLabel}-${spacingLabel.join("/")}`;
}

function drawBeamDirectionPlanWall(plan, wall) {
    const normalizedWall = normalizeWall(wall);
    const vertices = getWallFootprintVertices(normalizedWall);
    if (vertices.length < 4) {
        return;
    }
    // Beam-direction plans use their own linework convention. Slab-plan
    // concrete walls are hatched separately by addSlabPlanConcreteWalls.
    getPolygonSegments(vertices).forEach((segment) => {
        plan.addLine(CONCRETE_WALL_PLAN_OUTLINE_LAYER, segment.x1, segment.y1, segment.x2, segment.y2);
    });
}

function drawIndonesiaBeamPlanLabels(plan, beam, direction = "x", options = {}) {
    const normalizedBeam = normalizeBeamModel(beam);
    const beamLabel = normalizeTextValue(normalizedBeam.name) || getSmartEntityName("beam", normalizedBeam);
    const additional = normalizeBeamAdditionalRebar(normalizedBeam.additionalRebar);
    const topCenterLabel = formatIndonesiaBeamPlanMainLabel(normalizedBeam.topRebar);
    const bottomCenterLabel = formatIndonesiaBeamPlanMainLabel(normalizedBeam.botRebar);
    const textSize = getPlanAnnotationTextHeight();
    const labelTextSize = getPlanElementLabelTextSize(options.elementLabelTextSize, getPlanAnnotationTextHeight());

    if (direction === "x") {
        const startX = Math.min(normalizedBeam.x1, normalizedBeam.x2);
        const endX = Math.max(normalizedBeam.x1, normalizedBeam.x2);
        const centerX = (startX + endX) / 2;
        const centerY = (parseNumberOrFallback(normalizedBeam.y1, 0) + parseNumberOrFallback(normalizedBeam.y2, 0)) / 2;
        const beamWidth = parsePositiveNumberOrFallback(normalizedBeam.b, 0.3, 0.1);
        const beamLength = Math.max(endX - startX, 0.1);
        const leftX = startX + beamLength * (5 / 16);
        const rightX = startX + beamLength * (11 / 16);
        const steelOffset = 0.10 + textSize / 2;
        const titleOffset = 0.40 + labelTextSize / 2;
        const topY = centerY - beamWidth / 2 - steelOffset;
        const bottomY = centerY + beamWidth / 2 + steelOffset;
        const titleY = centerY - beamWidth / 2 - titleOffset;
        const leftSupport = normalizedBeam.x1 <= normalizedBeam.x2
            ? { top: additional.iEndTop, bottom: additional.iEndBottom }
            : { top: additional.jEndTop, bottom: additional.jEndBottom };
        const rightSupport = normalizedBeam.x1 <= normalizedBeam.x2
            ? { top: additional.jEndTop, bottom: additional.jEndBottom }
            : { top: additional.iEndTop, bottom: additional.iEndBottom };
        const stirrupLabel = formatIndonesiaBeamPlanStirrupLabel(normalizedBeam, direction, options);
        const stirrupY = centerY + beamWidth / 2 + 0.45;

        plan.addCenteredText(SLAB_PLAN_DRAWING_TEXT_LAYER, centerX, titleY, beamLabel, labelTextSize);
        plan.addCenteredText(SLAB_PLAN_DRAWING_TEXT_LAYER, leftX, topY, formatIndonesiaBeamPlanSupportLabel(normalizedBeam.topRebar, leftSupport.top), textSize);
        plan.addCenteredText(SLAB_PLAN_DRAWING_TEXT_LAYER, centerX, topY, topCenterLabel, textSize);
        plan.addCenteredText(SLAB_PLAN_DRAWING_TEXT_LAYER, rightX, topY, formatIndonesiaBeamPlanSupportLabel(normalizedBeam.topRebar, rightSupport.top), textSize);
        plan.addCenteredText(SLAB_PLAN_DRAWING_TEXT_LAYER, leftX, bottomY, formatIndonesiaBeamPlanSupportLabel(normalizedBeam.botRebar, leftSupport.bottom), textSize);
        plan.addCenteredText(SLAB_PLAN_DRAWING_TEXT_LAYER, centerX, bottomY, bottomCenterLabel, textSize);
        plan.addCenteredText(SLAB_PLAN_DRAWING_TEXT_LAYER, rightX, bottomY, formatIndonesiaBeamPlanSupportLabel(normalizedBeam.botRebar, rightSupport.bottom), textSize);
        if (stirrupLabel) {
            plan.addCenteredText(SLAB_PLAN_DRAWING_TEXT_LAYER, centerX, stirrupY, stirrupLabel, textSize);
        }
        return;
    }

    const startY = Math.min(normalizedBeam.y1, normalizedBeam.y2);
    const endY = Math.max(normalizedBeam.y1, normalizedBeam.y2);
    const centerX = (parseNumberOrFallback(normalizedBeam.x1, 0) + parseNumberOrFallback(normalizedBeam.x2, 0)) / 2;
    const centerY = (startY + endY) / 2;
    const beamWidth = parsePositiveNumberOrFallback(normalizedBeam.b, 0.3, 0.1);
    const beamLength = Math.max(endY - startY, 0.1);
    const lowerY = startY + beamLength * (5 / 16);
    const upperY = startY + beamLength * (11 / 16);
    const steelOffset = 0.10 + textSize / 2;
    const titleOffset = 0.40 + labelTextSize / 2;
    const leftX = centerX - beamWidth / 2 - steelOffset;
    const rightX = centerX + beamWidth / 2 + steelOffset;
    const titleX = centerX - beamWidth / 2 - titleOffset;
    const bottomSupport = normalizedBeam.y1 <= normalizedBeam.y2
        ? { top: additional.iEndTop, bottom: additional.iEndBottom }
        : { top: additional.jEndTop, bottom: additional.jEndBottom };
    const topSupport = normalizedBeam.y1 <= normalizedBeam.y2
        ? { top: additional.jEndTop, bottom: additional.jEndBottom }
        : { top: additional.iEndTop, bottom: additional.iEndBottom };
    const stirrupLabel = formatIndonesiaBeamPlanStirrupLabel(normalizedBeam, direction, options);
    const stirrupX = centerX + beamWidth / 2 + 0.45;

    plan.addCenteredRotatedText(SLAB_PLAN_DRAWING_TEXT_LAYER, titleX, centerY, beamLabel, labelTextSize, 90);
    plan.addCenteredRotatedText(SLAB_PLAN_DRAWING_TEXT_LAYER, leftX, upperY, formatIndonesiaBeamPlanSupportLabel(normalizedBeam.topRebar, topSupport.top), textSize, 90);
    plan.addCenteredRotatedText(SLAB_PLAN_DRAWING_TEXT_LAYER, leftX, centerY, topCenterLabel, textSize, 90);
    plan.addCenteredRotatedText(SLAB_PLAN_DRAWING_TEXT_LAYER, leftX, lowerY, formatIndonesiaBeamPlanSupportLabel(normalizedBeam.topRebar, bottomSupport.top), textSize, 90);
    plan.addCenteredRotatedText(SLAB_PLAN_DRAWING_TEXT_LAYER, rightX, upperY, formatIndonesiaBeamPlanSupportLabel(normalizedBeam.botRebar, topSupport.bottom), textSize, 90);
    plan.addCenteredRotatedText(SLAB_PLAN_DRAWING_TEXT_LAYER, rightX, centerY, bottomCenterLabel, textSize, 90);
    plan.addCenteredRotatedText(SLAB_PLAN_DRAWING_TEXT_LAYER, rightX, lowerY, formatIndonesiaBeamPlanSupportLabel(normalizedBeam.botRebar, bottomSupport.bottom), textSize, 90);
    if (stirrupLabel) {
        plan.addCenteredRotatedText(SLAB_PLAN_DRAWING_TEXT_LAYER, stirrupX, centerY, stirrupLabel, textSize, 90);
    }
}

function drawBeamDirectionPlanSheet(dxf, level, direction = "x", minX, maxX, minY, maxY, sheetOffsetY = 0, options = {}) {
    const xAxisEntries = getPlanAxisEntries("x", minX, maxX, [minX, maxX]);
    const yAxisEntries = getPlanAxisEntries("y", minY, maxY, [minY, maxY]);
    const sheetOffsetX = Number.isFinite(options.sheetOffsetX) ? options.sheetOffsetX : 0;
    const plan = createSlabPlanExportHelpers(
        dxf,
        minX,
        minY,
        maxY,
        sheetOffsetX + 0.6,
        sheetOffsetY + SLAB_PLAN_TITLE_ORIGIN_Y_OFFSET
    );
    const titleLabel = direction === "x"
        ? `VISTA EN PLANTA DE REFUERZO DE VIGAS DIR-X ${level.name}`.trim()
        : `VISTA EN PLANTA DE REFUERZO DE VIGAS DIR-Y ${level.name}`.trim();
    const axisTextHeight = getPlanAxisDimensionTextSize(options.axisDimensionTextSize, getPlanAnnotationTextHeight());
    const planElementLabelTextSize = getPlanElementLabelTextSizeForBounds({ minX, maxX, minY, maxY });
    const markerLabel = direction === "x" ? "BX" : "BY";
    const codeLabel = direction === "x" ? "E-BX" : "E-BY";
    const markerCenterX = plan.mapX(minX) + 0.35;
    const markerCenterY = plan.mapY(maxY + SLAB_PLAN_TITLE_BELOW_OFFSET);

    drawDetailTitleMarker(dxf, markerCenterX, markerCenterY, markerLabel, codeLabel, titleLabel, { rightLineLength: 4.6 });

    xAxisEntries.forEach((entry) => {
        const bubbleY = minY - SLAB_PLAN_AXIS_BUBBLE_OFFSET;
        plan.addLine(DXF_AXIS_LINE_LAYER, entry.value, bubbleY + SLAB_PLAN_AXIS_BUBBLE_RADIUS, entry.value, maxY + 0.52, { lineType: DXF_AXIS_LINE_TYPE });
        plan.addAxisBubbleBlock(entry.value, bubbleY, entry.label, {
            layer: "COTAS_EJES",
            radius: SLAB_PLAN_AXIS_BUBBLE_RADIUS,
            textHeight: axisTextHeight
        });
    });

    yAxisEntries.forEach((entry) => {
        const bubbleX = minX - SLAB_PLAN_AXIS_BUBBLE_OFFSET;
        plan.addLine(DXF_AXIS_LINE_LAYER, bubbleX + SLAB_PLAN_AXIS_BUBBLE_RADIUS, entry.value, maxX + 0.35, entry.value, { lineType: DXF_AXIS_LINE_TYPE });
        plan.addAxisBubbleBlock(bubbleX, entry.value, entry.label, {
            layer: "COTAS_EJES",
            radius: SLAB_PLAN_AXIS_BUBBLE_RADIUS,
            textHeight: axisTextHeight
        });
    });

    for (let index = 0; index < xAxisEntries.length - 1; index += 1) {
        plan.addDimension("COTAS_EJES", xAxisEntries[index].value, xAxisEntries[index + 1].value, maxY + SLAB_PLAN_AXIS_DIMENSION_OFFSET, (xAxisEntries[index + 1].value - xAxisEntries[index].value).toFixed(2), maxY + SLAB_PLAN_AXIS_DIMENSION_ORIGIN_OFFSET, { textHeight: planElementLabelTextSize });
    }
    for (let index = 0; index < yAxisEntries.length - 1; index += 1) {
        plan.addVerticalDimension("COTAS_EJES", minX - SLAB_PLAN_AXIS_DIMENSION_OFFSET, yAxisEntries[index].value, yAxisEntries[index + 1].value, (yAxisEntries[index + 1].value - yAxisEntries[index].value).toFixed(2), minX - SLAB_PLAN_AXIS_DIMENSION_ORIGIN_OFFSET, { textHeight: planElementLabelTextSize });
    }

    (level.walls || []).forEach((wall) => drawBeamDirectionPlanWall(plan, wall));
    (level.columns || []).forEach((column) => {
        const normalizedColumn = normalizeColumnModel(column);
        const footprint = getColumnFootprint(normalizedColumn);
        if (getDxfSectionDesignerConcrete(normalizedColumn)) {
            drawDxfSectionDesignerPlanProfile(dxf, normalizedColumn, plan.mapX, plan.mapY, { includeReinforcement: false });
            return;
        }
        if (isCircularColumnSection(normalizedColumn)) {
            const vertices = getDxfCircularColumnPlanPolygon(normalizedColumn);
            plan.addHatch("RELLENO_COLUMNAS_LOSA", vertices, { patternName: "ANSI31", patternScale: 0.03, color: 1 });
            plan.addCircle("CONCRETO_COLUMNAS", normalizedColumn.x, normalizedColumn.y, getColumnDiameter(normalizedColumn) / 2);
            return;
        }
        plan.addFilledRectangle("RELLENO_COLUMNAS_LOSA", normalizedColumn.x - footprint.width / 2, normalizedColumn.y - footprint.height / 2, footprint.width, footprint.height, 1);
        plan.addRectangle("CONCRETO_COLUMNAS", normalizedColumn.x - footprint.width / 2, normalizedColumn.y - footprint.height / 2, footprint.width, footprint.height);
    });
    (level.beams || []).forEach((beam) => {
        const shouldLabel = isBeamInGlobalDirection(beam, direction);
        addSlabPlanBeam(dxf, normalizeBeamModel(beam), plan, false, {
            supportColumns: level.columns || [],
            supportWalls: level.walls || []
        });
        if (shouldLabel) {
            drawIndonesiaBeamPlanLabels(plan, beam, direction, {
                ...options,
                elementLabelTextSize: planElementLabelTextSize
            });
        }
    });
}

function drawBeamDirectionPlanSheetStack(dxf, level, direction = "x", cursorY = 0, options = {}) {
    const bounds = getSlabPlanSheetBounds(level);
    const sheetSizeOptions = { includePlan: true, includeSteelDetailText: false };
    drawBeamDirectionPlanSheet(dxf, level, direction, bounds.minX, bounds.maxX, bounds.minY, bounds.maxY, cursorY, options);
    return {
        width: getSlabPlanSheetWidthForOptions(bounds.minX, bounds.maxX, sheetSizeOptions, level),
        height: getSlabPlanSheetHeightForOptions(level, bounds.minY, bounds.maxY, sheetSizeOptions)
    };
}


function formatDxfWeldedWireMeshLabel(mesh) {
    const raw = normalizeThinWallWeldedMesh(mesh);
    if (!raw) {
        return "";
    }

    const match = raw.match(/^W([0-9.]+)XW([0-9.]+)X([0-9.]+)X([0-9.]+)$/i);
    if (!match) {
        return raw;
    }

    return `W${match[1]} x W${match[2]} x ${match[3]} x ${match[4]}`;
}

function formatCompactDxfWeldedWireMeshLabel(mesh) {
    const raw = normalizeThinWallWeldedMesh(mesh);
    if (!raw) {
        return "";
    }
    return raw.replace(/X/g, "x");
}

function evaluateSlabWeldedMeshReferenceSpline(parameter) {
    const degree = SLAB_WELDED_MESH_REFERENCE_SPLINE_DEGREE;
    const controlPoints = SLAB_WELDED_MESH_REFERENCE_SPLINE_CONTROL_POINTS;
    const knots = SLAB_WELDED_MESH_REFERENCE_SPLINE_KNOTS;
    const lastControlPointIndex = controlPoints.length - 1;
    const endParameter = knots[lastControlPointIndex + 1];

    if (parameter >= endParameter - 1e-12) {
        return { ...controlPoints[lastControlPointIndex] };
    }

    let knotSpan = degree;
    for (let index = degree; index <= lastControlPointIndex; index += 1) {
        if (knots[index] <= parameter && parameter < knots[index + 1]) {
            knotSpan = index;
            break;
        }
    }

    const workingPoints = Array.from({ length: degree + 1 }, (_, index) => ({
        ...controlPoints[knotSpan - degree + index]
    }));

    for (let recursionLevel = 1; recursionLevel <= degree; recursionLevel += 1) {
        for (let index = degree; index >= recursionLevel; index -= 1) {
            const controlPointIndex = knotSpan - degree + index;
            const denominator = knots[controlPointIndex + degree - recursionLevel + 1] - knots[controlPointIndex];
            const blend = Math.abs(denominator) <= 1e-12
                ? 0
                : (parameter - knots[controlPointIndex]) / denominator;
            workingPoints[index] = {
                x: (1 - blend) * workingPoints[index - 1].x + blend * workingPoints[index].x,
                y: (1 - blend) * workingPoints[index - 1].y + blend * workingPoints[index].y
            };
        }
    }

    return workingPoints[degree];
}

function buildSlabWeldedMeshRepresentativeVertices(centerX, centerY, targetWidth) {
    const degree = SLAB_WELDED_MESH_REFERENCE_SPLINE_DEGREE;
    const knots = SLAB_WELDED_MESH_REFERENCE_SPLINE_KNOTS;
    const controlPointCount = SLAB_WELDED_MESH_REFERENCE_SPLINE_CONTROL_POINTS.length;
    const startParameter = knots[degree];
    const endParameter = knots[controlPointCount];
    const sampleCount = SLAB_WELDED_MESH_REFERENCE_SPLINE_SAMPLE_COUNT;
    const sourceVertices = Array.from({ length: sampleCount }, (_, index) => {
        const parameter = startParameter + ((endParameter - startParameter) * index) / sampleCount;
        return evaluateSlabWeldedMeshReferenceSpline(parameter);
    });
    const sourceMinX = Math.min(...sourceVertices.map((point) => point.x));
    const sourceMaxX = Math.max(...sourceVertices.map((point) => point.x));
    const sourceWidth = Math.max(sourceMaxX - sourceMinX, 1e-9);
    const safeTargetWidth = Math.max(Number.parseFloat(targetWidth) || sourceWidth, 1e-9);
    const scale = safeTargetWidth / sourceWidth;

    return sourceVertices.map((point) => ({
        x: centerX + point.x * scale,
        // plan.mapY mirrors model-space Y. Negating the source offset here
        // preserves the exact orientation shown in the submitted DXF.
        y: centerY - point.y * scale
    }));
}

function drawLightenedSlabWeldedWireMeshDetail(dxf, plan, slab) {
    const mesh = normalizeThinWallWeldedMesh(slab?.lightened?.topWeldedWireMesh);
    const slabVertices = normalizeSlabVertices(slab);
    if (!mesh || slabVertices.length < 3) {
        return;
    }

    const centroid = getSlabCentroid(slab);
    const bounds = normalizeSlabBounds(slab);
    const slabWidth = Math.max(bounds.x2 - bounds.x1, 0);
    const slabHeight = Math.max(bounds.y2 - bounds.y1, 0);
    const target = {
        x: centroid.x - slabWidth * SLAB_WELDED_MESH_OFFSET_X_RATIO,
        // createSlabPlanExportHelpers mirrors Y, so a lower model-space Y is
        // visually higher in the exported plan.
        y: centroid.y - slabHeight * SLAB_WELDED_MESH_OFFSET_Y_RATIO
    };
    const representativeWidth = slabWidth * SLAB_WELDED_MESH_REPRESENTATIVE_WIDTH_RATIO;
    const representativeVertices = buildSlabWeldedMeshRepresentativeVertices(
        target.x,
        target.y,
        representativeWidth
    );

    // Use one representative patch per slab instead of covering the entire
    // slab. Its exact irregular shape is preserved and its total width is 20%
    // of the slab width.
    plan.addHatch("MALLA_ELECTROSOLDADA_LOSA", representativeVertices, {
        patternName: "MALLA_ELECTROSOLDADA",
        patternScale: SLAB_WELDED_MESH_REFERENCE_HATCH_SPACING,
        hatchStyle: 0
    });
    plan.addPolyline("MALLA_ELECTROSOLDADA_LOSA_BORDE", representativeVertices, { closed: true });

    // Annotation style follows the submitted reference: text and callout stay
    // at fixed drafting size while the representative mesh scales with the slab.
    const elbow = {
        x: target.x - SLAB_WELDED_MESH_LEADER_TARGET_OFFSET_X,
        y: target.y - SLAB_WELDED_MESH_LEADER_DIAGONAL
    };
    const leaderEnd = {
        x: elbow.x + SLAB_WELDED_MESH_LEADER_HORIZONTAL,
        y: elbow.y
    };
    // The submitted reference positions the label immediately above the
    // leader elbow.  Only the anchor moves with a different slab; all text
    // spacing and leader lengths remain constant.
    const labelX = elbow.x - SLAB_WELDED_MESH_LABEL_LEFT_OF_ELBOW;
    const labelBottomY = elbow.y - SLAB_WELDED_MESH_LABEL_BOTTOM_ABOVE_ELBOW;

    addText(
        dxf,
        "TEXTO_ACERO",
        plan.mapX(labelX),
        plan.mapY(labelBottomY - (SLAB_WELDED_MESH_TEXT_LINE_GAP * 2)),
        "MALLA",
        SLAB_WELDED_MESH_TEXT_HEIGHT
    );
    addText(
        dxf,
        "TEXTO_ACERO",
        plan.mapX(labelX),
        plan.mapY(labelBottomY - SLAB_WELDED_MESH_TEXT_LINE_GAP),
        "ELECTROSOLDADA",
        SLAB_WELDED_MESH_TEXT_HEIGHT
    );
    addText(
        dxf,
        "TEXTO_ACERO",
        plan.mapX(labelX),
        plan.mapY(labelBottomY),
        formatDxfWeldedWireMeshLabel(mesh),
        SLAB_WELDED_MESH_TEXT_HEIGHT
    );

    drawSteelDenotationPolyline(
        dxf,
        plan.mapX(labelX),
        plan.mapY(labelBottomY),
        plan.mapX(target.x),
        plan.mapY(target.y)
    );
}

function parseSlabPlanInchLabel(value) {
    const normalized = normalizeFractionText(value)
        .replace(/["″]/g, "")
        .trim();
    if (!normalized) {
        return Number.NaN;
    }
    const parts = normalized.split(/\s+/);
    let total = 0;
    parts.forEach((part) => {
        const fractionMatch = part.match(/^(\d+)\/(\d+)$/);
        if (fractionMatch) {
            const denominator = Number.parseFloat(fractionMatch[2]);
            if (denominator > 0) {
                total += Number.parseFloat(fractionMatch[1]) / denominator;
            }
            return;
        }
        const numeric = Number.parseFloat(part);
        if (Number.isFinite(numeric)) {
            total += numeric;
        }
    });
    return total > 0 ? total : Number.NaN;
}

function getSlabPlanUsBarDesignation(diameter) {
    const normalized = normalizeDiameterLabel(diameter).toUpperCase();
    if (/^#\d+$/.test(normalized)) {
        return normalized;
    }

    const compact = normalized.replace(/\s+/g, "").replace(/[″]/g, '"');
    const matchedEntry = Object.entries(US_CUSTOMARY_BAR_INCH_LABELS).find(([, inchLabel]) => (
        normalizeDiameterLabel(inchLabel).toUpperCase().replace(/\s+/g, "") === compact
    ));
    if (matchedEntry) {
        return matchedEntry[0];
    }

    const diameterMeters = getDiameterMetersFromBarLabel(normalized, getActiveBarSetForDiameters());
    if (diameterMeters > 0) {
        const nearestEntry = Object.entries(US_CUSTOMARY_BAR_INCH_LABELS)
            .map(([barLabel, inchLabel]) => ({
                barLabel,
                difference: Math.abs((parseSlabPlanInchLabel(inchLabel) || 0) * 0.0254 - diameterMeters)
            }))
            .sort((left, right) => left.difference - right.difference)[0];
        if (nearestEntry && nearestEntry.difference <= 0.0015) {
            return nearestEntry.barLabel;
        }
    }

    return normalized || "#4";
}

function formatSlabPlanNoteLength(valueMeters, kind = "length") {
    const safeValue = Math.max(parsePositiveNumberOrFallback(valueMeters, 0, 0), 0);
    const useImperial = isUnitedStatesDrawingContext(projectState.projectCountry, projectState.projectLocation)
        || normalizeUnitSystem(getCurrentUnitSystem()) === "imperial";
    if (useImperial) {
        return `${Math.max(1, Math.round(safeValue / 0.0254))}"`;
    }
    const centimeters = safeValue * 100;
    const rounded = Math.round(centimeters * 10) / 10;
    return `${Number.isInteger(rounded) ? rounded.toFixed(0) : rounded.toFixed(1)} cm`;
}

function formatSlabPlanNoteBar(diameter) {
    const useImperial = isUnitedStatesDrawingContext(projectState.projectCountry, projectState.projectLocation)
        || normalizeUnitSystem(getCurrentUnitSystem()) === "imperial";
    if (useImperial) {
        return getSlabPlanUsBarDesignation(diameter);
    }
    return `Ø${normalizeDiameterLabel(diameter) || DEFAULT_SLAB_BAR_DIAMETER}`;
}

function getSlabPlanPropertiesReinforcementLines(slab) {
    const normalizedSlab = normalizeSlab(slab);
    const thickness = formatSlabPlanNoteLength(normalizedSlab.h, "thickness");
    const xBar = formatSlabPlanNoteBar(normalizedSlab.solid.xBarDiameter);
    const yBar = formatSlabPlanNoteBar(normalizedSlab.solid.yBarDiameter);
    const xSpacing = formatSlabPlanNoteLength(normalizedSlab.solid.xSpacing, "spacing");
    const ySpacing = formatSlabPlanNoteLength(normalizedSlab.solid.ySpacing, "spacing");
    const sameReinforcement = xBar === yBar
        && Math.abs(normalizedSlab.solid.xSpacing - normalizedSlab.solid.ySpacing) <= 0.0005;
    const isEnglish = projectState.language === "en";

    if (isEnglish && sameReinforcement) {
        return [
            `${thickness} CONC. SLAB REINF. W/`,
            `${xBar} @ ${xSpacing} O.C. EA. WAY`,
            "BOTTOM. PROVIDE TOP",
            "REINF. AS SHOWN"
        ];
    }
    if (isEnglish) {
        return [
            `${thickness} CONC. SLAB REINF. W/`,
            `X: ${xBar} @ ${xSpacing} O.C. BOTTOM`,
            `Y: ${yBar} @ ${ySpacing} O.C. BOTTOM`,
            "PROVIDE TOP REINF. AS SHOWN"
        ];
    }
    if (sameReinforcement) {
        return [
            `LOSA DE CONC. DE ${thickness} REF. CON`,
            `${xBar} @ ${xSpacing} C/C EN AMBAS DIR.`,
            "INFERIOR. COLOCAR REFUERZO",
            "SUPERIOR SEGUN SE INDICA"
        ];
    }
    return [
        `LOSA DE CONC. DE ${thickness} REF. CON`,
        `X: ${xBar} @ ${xSpacing} C/C INFERIOR`,
        `Y: ${yBar} @ ${ySpacing} C/C INFERIOR`,
        "REF. SUPERIOR SEGUN SE INDICA"
    ];
}

function addSlabPlanPropertiesReinforcementText(plan, slab, options = {}) {
    const normalizedSlab = normalizeSlab(slab);
    if (!isSolidSlabType(normalizedSlab.type)) {
        return;
    }

    const lines = getSlabPlanPropertiesReinforcementLines(normalizedSlab);
    if (!lines.length) {
        return;
    }

    const bounds = normalizeSlabBounds(normalizedSlab);
    const centroid = getSlabCentroid(normalizedSlab);
    const textSize = getPlanElementLabelTextSize(options.elementLabelTextSize, getPlanAnnotationTextHeight());
    const lineGap = textSize * 1.42;
    const paddingX = textSize * 0.60;
    const paddingY = textSize * 0.48;
    const textWidth = Math.max(...lines.map((line) => estimateDxfTextWidth(line, textSize)));
    const boxWidth = textWidth + paddingX * 2;
    const boxHeight = paddingY * 2 + textSize + lineGap * (lines.length - 1);
    const slabWidth = Math.max(bounds.x2 - bounds.x1, boxWidth);
    const slabHeight = Math.max(bounds.y2 - bounds.y1, boxHeight);
    const margin = Math.max(0.04, textSize * 0.30);
    const desiredCenterX = centroid.x - Math.min(slabWidth * 0.12, 0.45);
    const desiredTopY = centroid.y - Math.min(slabHeight * 0.12, 0.35) - boxHeight / 2;
    const left = Math.min(
        Math.max(desiredCenterX - boxWidth / 2, bounds.x1 + margin),
        Math.max(bounds.x2 - boxWidth - margin, bounds.x1 + margin)
    );
    const topY = Math.min(
        Math.max(desiredTopY, bounds.y1 + margin),
        Math.max(bounds.y2 - boxHeight - margin, bounds.y1 + margin)
    );

    plan.addRectangle(SLAB_PLAN_PROPERTIES_TEXT_LAYER, left, topY, boxWidth, boxHeight, {
        color: 1,
        lineWeight: 18
    });
    lines.forEach((line, index) => {
        plan.addText(
            SLAB_PLAN_PROPERTIES_TEXT_LAYER,
            left + paddingX,
            topY + paddingY + textSize + index * lineGap,
            line,
            textSize
        );
    });
}

function addSlabPlanPanel(dxf, slab, slabs, plan, supportContext = null, options = {}) {
    const normalizedSlab = normalizeSlab(slab);
    const bounds = normalizeSlabBounds(normalizedSlab);
    const slabCenter = getSlabCentroid(normalizedSlab);
    const slabCenterX = slabCenter.x;
    const slabCenterY = slabCenter.y;
    const slabWidth = bounds.x2 - bounds.x1;
    const slabHeight = bounds.y2 - bounds.y1;
    const showRepresentativeSteelBars = options.showRepresentativeSteelBars !== false;
    const includeSteelDetailText = options.includeSteelDetailText !== false;
    getPolygonSegments(normalizedSlab.vertices).forEach((segment) => {
        plan.addLine("PLANO_LOSA", segment.x1, segment.y1, segment.x2, segment.y2);
    });

    if (normalizedSlab.type === SLAB_TYPE_METAL_DECK) {
        drawDxfSlabNameBadge(plan, normalizedSlab.name, slabCenterX, slabCenterY, slabWidth, slabHeight, { elementLabelTextSize: options.elementLabelTextSize });
        return;
    }

    if (isSolidSlabType(normalizedSlab.type)) {
        if (showRepresentativeSteelBars && !isCantileverSlab(normalizedSlab)) {
            getSolidSlabRepresentativeBars(slabs, normalizedSlab, "x", supportContext).forEach((bar) => {
                addSolidSlabBarToDxf(dxf, "ACERO_LOSA_X", bar, normalizedSlab, plan.mapX, plan.mapY);
            });

            getSolidSlabRepresentativeBars(slabs, normalizedSlab, "y", supportContext).forEach((bar) => {
                addSolidSlabBarToDxf(dxf, "ACERO_LOSA_Y", bar, normalizedSlab, plan.mapX, plan.mapY);
            });
        }

        if (showRepresentativeSteelBars) {
            getSlabTemperatureBarSegments(normalizedSlab).forEach((segment) => {
                plan.addPolyline("ACERO_LOSA_TEMP", [
                    { x: segment.x1, y: segment.y1 },
                    { x: segment.x2, y: segment.y2 }
                ]);
            });
        }

        if (includeSteelDetailText) {
            addSlabPlanPropertiesReinforcementText(plan, normalizedSlab, options);
        }

        drawDxfSlabNameBadge(plan, normalizedSlab.name, slabCenterX, slabCenterY, slabWidth, slabHeight, { elementLabelTextSize: options.elementLabelTextSize });
        return;
    }

    getLightenedCassetteRects(normalizedSlab).forEach((cassette) => {
        // Each bovedilla is one closed editable polyline/rectangle. Do not emit
        // its four sides as independent LINE entities.
        plan.addPolyline("BOVEDILLAS_LOSA_BORDE", [
            { x: cassette.x1, y: cassette.y1 },
            { x: cassette.x2, y: cassette.y1 },
            { x: cassette.x2, y: cassette.y2 },
            { x: cassette.x1, y: cassette.y2 }
        ], {
            closed: true,
            color: 7,
            lineWeight: 5
        });
    });

    drawLightenedSlabWeldedWireMeshDetail(dxf, plan, normalizedSlab);

    // La información de bovedilla y separación se reporta en la tabla de acero de losas aligeradas.
    // Una losa en voladizo solo conserva su acero a temperatura.
    if (showRepresentativeSteelBars && isCantileverSlab(normalizedSlab)) {
        getSlabTemperatureBarSegments(normalizedSlab).forEach((segment) => {
            plan.addPolyline("ACERO_LOSA_TEMP", [
                { x: segment.x1, y: segment.y1 },
                { x: segment.x2, y: segment.y2 }
            ]);
        });
    }

    drawDxfSlabNameBadge(plan, normalizedSlab.name, slabCenterX, slabCenterY, slabWidth, slabHeight, { elementLabelTextSize: options.elementLabelTextSize });
}
/* SERVER_ONLY_END */

/* SERVER_ONLY_START */
