function getBeamBoundsForFrame(beam, type) {
    if (type === "o" && Number.isFinite(beam?.__frameLocalStart) && Number.isFinite(beam?.__frameLocalEnd)) {
        return {
            start: Math.min(beam.__frameLocalStart, beam.__frameLocalEnd),
            end: Math.max(beam.__frameLocalStart, beam.__frameLocalEnd)
        };
    }
    const coordinates = type === "x" ? [beam.y1, beam.y2] : [beam.x1, beam.x2];
    const bounds = getNumericArrayBounds(coordinates);
    return {
        start: bounds?.min ?? 0,
        end: bounds?.max ?? 0
    };
}

function getContinuousFrameBeamChains(beamSegments, tolerance = 0.12, supports = null) {
    const sortedSegments = (beamSegments || [])
        .slice()
        .sort((left, right) => (left.start - right.start) || (left.end - right.end));

    if (!sortedSegments.length) {
        return [];
    }

    const chains = [];
    let currentChain = {
        start: sortedSegments[0].start,
        end: sortedSegments[0].end,
        members: [sortedSegments[0]]
    };

    for (let index = 1; index < sortedSegments.length; index += 1) {
        const segment = sortedSegments[index];
        const previousMember = currentChain.members[currentChain.members.length - 1];
        const supportConnected = Array.isArray(supports)
            && shouldTreatFrameBeamMembersAsAdjacent(previousMember, segment, supports, tolerance);
        if (segment.start <= currentChain.end + tolerance || supportConnected) {
            currentChain.end = Math.max(currentChain.end, segment.end);
            currentChain.members.push(segment);
            continue;
        }

        chains.push(currentChain);
        currentChain = {
            start: segment.start,
            end: segment.end,
            members: [segment]
        };
    }

    chains.push(currentChain);
    return chains;
}

function groupContiguousBeamDepthRuns(chainMembers = [], tolerance = 0.001) {
    const runs = [];
    let currentRun = null;

    (Array.isArray(chainMembers) ? chainMembers : []).forEach((member) => {
        const start = parseNumberOrFallback(member?.start, Number.NaN);
        const end = parseNumberOrFallback(member?.end, Number.NaN);
        const depth = parsePositiveNumberOrFallback(member?.beam?.h, 0.4, 0.1);

        if (!Number.isFinite(start) || !Number.isFinite(end)) {
            return;
        }

        if (!currentRun || Math.abs(depth - currentRun.depth) > tolerance) {
            currentRun = {
                depth,
                start,
                end,
                members: [member]
            };
            runs.push(currentRun);
            return;
        }

        currentRun.depth = Math.max(currentRun.depth, depth);
        currentRun.start = Math.min(currentRun.start, start);
        currentRun.end = Math.max(currentRun.end, end);
        currentRun.members.push(member);
    });

    return runs;
}

function getFrameBeamAnnotationChains(beamSegments, supports, tolerance = 0.08) {
    const sortedSegments = (beamSegments || [])
        .slice()
        .sort((left, right) => (left.start - right.start) || (left.end - right.end));

    if (!sortedSegments.length) {
        return [];
    }

    const chains = [];
    let currentChain = {
        start: sortedSegments[0].start,
        end: sortedSegments[0].end,
        members: [sortedSegments[0]]
    };

    for (let index = 1; index < sortedSegments.length; index += 1) {
        const segment = sortedSegments[index];
        const boundarySupport = findFrameSupportBetweenAdjacentBeamMembers(supports, currentChain.end, segment.start, tolerance);
        if (!boundarySupport && segment.start <= currentChain.end + tolerance) {
            currentChain.end = Math.max(currentChain.end, segment.end);
            currentChain.members.push(segment);
            continue;
        }

        chains.push(currentChain);
        currentChain = {
            start: segment.start,
            end: segment.end,
            members: [segment]
        };
    }

    chains.push(currentChain);
    return chains;
}

function getLongestFrameChainMember(chainMembers = []) {
    let longestMember = null;
    let longestLength = -1;

    (Array.isArray(chainMembers) ? chainMembers : []).forEach((member) => {
        const start = parseNumberOrFallback(member?.start, Number.NaN);
        const end = parseNumberOrFallback(member?.end, Number.NaN);
        const length = Number.isFinite(start) && Number.isFinite(end) ? Math.max(end - start, 0) : -1;
        if (length > longestLength) {
            longestMember = member;
            longestLength = length;
        }
    });

    return longestMember;
}

function getUniformFrameChainSignature(chainMembers = [], getSignature = () => "") {
    const members = Array.isArray(chainMembers) ? chainMembers : [];
    if (!members.length || typeof getSignature !== "function") {
        return {
            uniform: false,
            signature: ""
        };
    }

    const firstSignature = String(getSignature(members[0]) || "");
    const uniform = members.every((member) => String(getSignature(member) || "") === firstSignature);

    return {
        uniform,
        signature: firstSignature
    };
}

function getBeamLocalAxisType(beam, preferredAxisType = null) {
    if (preferredAxisType === "x" || preferredAxisType === "y" || preferredAxisType === "o") {
        return preferredAxisType;
    }
    if (beam?.__frameAxisType === "o") {
        return "o";
    }

    const deltaX = Math.abs(parseNumberOrFallback(beam?.x2, 0) - parseNumberOrFallback(beam?.x1, 0));
    const deltaY = Math.abs(parseNumberOrFallback(beam?.y2, 0) - parseNumberOrFallback(beam?.y1, 0));
    return deltaY >= deltaX ? "x" : "y";
}

function isBeamIEndAtLocalStart(beam, preferredAxisType = null) {
    const axisType = getBeamLocalAxisType(beam, preferredAxisType);
    if (axisType === "x") {
        return parseNumberOrFallback(beam?.y1, 0) <= parseNumberOrFallback(beam?.y2, 0);
    }
    if (axisType === "o" && Number.isFinite(beam?.__frameLocalStart) && Number.isFinite(beam?.__frameLocalEnd)) {
        return parseNumberOrFallback(beam?.__frameLocalStart, 0) <= parseNumberOrFallback(beam?.__frameLocalEnd, 0);
    }

    return parseNumberOrFallback(beam?.x1, 0) <= parseNumberOrFallback(beam?.x2, 0);
}

function getBeamDeadEndState(beam, chain = null, preferredAxisType = null, tolerance = 0.05) {
    const axisType = getBeamLocalAxisType(beam, preferredAxisType);
    const bounds = getBeamBoundsForFrame(beam, axisType);
    const iEndAtLocalStart = isBeamIEndAtLocalStart(beam, axisType);
    const atChainStart = chain ? Math.abs(bounds.start - chain.start) <= tolerance : true;
    const atChainEnd = chain ? Math.abs(bounds.end - chain.end) <= tolerance : true;

    return iEndAtLocalStart
        ? { iEndDead: atChainStart, jEndDead: atChainEnd }
        : { iEndDead: atChainEnd, jEndDead: atChainStart };
}

function formatAutocadAdditionalRebarLabel(rebar) {
    const normalized = normalizeOptionalLongitudinalRebar(rebar);
    const count = parseOptionalBarCount(normalized.n);
    if (count <= 0) {
        return "";
    }

    return `${count}%%c${formatDxfRebarDiameterLabel(normalized.d)} (ADIC)`;
}

function formatSpacingInCentimeters(spacingMeters) {
    // Stirrup labels must keep a compact, dimension-like format (for example: ø3/8"@0.20m).
    return formatLengthForUnit(
        parsePositiveNumberOrFallback(spacingMeters, DEFAULT_BEAM_STIRRUP_SPACING),
        "spacing",
        { decimals: 2 }
    ).replace(/\s+/g, "");
}

function buildBeamAdditionalRebarSegments(beam, {
    bodyStart,
    bodyEnd,
    anchorStart = bodyStart,
    anchorEnd = bodyEnd,
    terminalAnchorStart = bodyStart,
    terminalAnchorEnd = bodyEnd,
    terminalStartHookInset = FRAME_ADDITIONAL_TERMINAL_END_CLEARANCE,
    terminalEndHookInset = FRAME_ADDITIONAL_TERMINAL_END_CLEARANCE,
    bottomDevelopmentStartExtension = 0,
    bottomDevelopmentEndExtension = 0,
    bottomDevelopmentStartDimensionLength = bottomDevelopmentStartExtension,
    bottomDevelopmentEndDimensionLength = bottomDevelopmentEndExtension,
    bottomDevelopmentStartCriticalX = Number.NaN,
    bottomDevelopmentEndCriticalX = Number.NaN,
    bottomDevelopmentStartBarEndX = Number.NaN,
    bottomDevelopmentEndBarEndX = Number.NaN,
    axisType = null,
    chain = null
} = {}) {
    const normalizedBeam = normalizeBeamModel(beam);
    const additionalRebar = normalizeBeamAdditionalRebar(normalizedBeam.additionalRebar);
    const iEndAtLocalStart = isBeamIEndAtLocalStart(normalizedBeam, axisType);
    const deadEnds = getBeamDeadEndState(normalizedBeam, chain, axisType);
    const clearSpan = Math.max(parseNumberOrFallback(bodyEnd, bodyStart) - parseNumberOrFallback(bodyStart, 0), 0);
    const thirdSpan = clearSpan / 3;
    const bottomStartExtension = Math.max(parseNumberOrFallback(bottomDevelopmentStartExtension, 0), 0);
    const bottomEndExtension = Math.max(parseNumberOrFallback(bottomDevelopmentEndExtension, 0), 0);
    const bottomStartDimensionLength = Math.max(
        parseNumberOrFallback(bottomDevelopmentStartDimensionLength, bottomStartExtension),
        0
    );
    const bottomEndDimensionLength = Math.max(
        parseNumberOrFallback(bottomDevelopmentEndDimensionLength, bottomEndExtension),
        0
    );
    const resolvedStartCriticalX = parseNumberOrFallback(bottomDevelopmentStartCriticalX, Number.NaN);
    const resolvedEndCriticalX = parseNumberOrFallback(bottomDevelopmentEndCriticalX, Number.NaN);
    const resolvedStartBarEndX = parseNumberOrFallback(bottomDevelopmentStartBarEndX, Number.NaN);
    const resolvedEndBarEndX = parseNumberOrFallback(bottomDevelopmentEndBarEndX, Number.NaN);
    const hasStartDevelopment = bottomStartDimensionLength > EDGE_TOLERANCE
        && Number.isFinite(resolvedStartCriticalX)
        && Number.isFinite(resolvedStartBarEndX);
    const hasEndDevelopment = bottomEndDimensionLength > EDGE_TOLERANCE
        && Number.isFinite(resolvedEndCriticalX)
        && Number.isFinite(resolvedEndBarEndX);
    const createDevelopmentDimension = (x1, x2, length) => (
        length > EDGE_TOLERANCE && Number.isFinite(x1) && Number.isFinite(x2)
            ? [{ x1, x2, length }]
            : []
    );
    const createStartDevelopmentDimension = (extension, dimensionLength) => createDevelopmentDimension(
        hasStartDevelopment ? resolvedStartBarEndX : anchorStart - extension,
        hasStartDevelopment ? resolvedStartCriticalX : anchorStart,
        dimensionLength
    );
    const createEndDevelopmentDimension = (extension, dimensionLength) => createDevelopmentDimension(
        hasEndDevelopment ? resolvedEndCriticalX : anchorEnd,
        hasEndDevelopment ? resolvedEndBarEndX : anchorEnd + extension,
        dimensionLength
    );
    const zoneDefinitions = [
        { key: "iEndTop", zone: "iEnd", face: "top" },
        { key: "iEndBottom", zone: "iEnd", face: "bottom" },
        { key: "midTop", zone: "mid", face: "top" },
        { key: "midBottom", zone: "mid", face: "bottom" },
        { key: "jEndTop", zone: "jEnd", face: "top" },
        { key: "jEndBottom", zone: "jEnd", face: "bottom" }
    ];

    return zoneDefinitions.flatMap((definition) => {
        const rebar = additionalRebar[definition.key];
        if (parseOptionalBarCount(rebar?.n) <= 0) {
            return [];
        }

        if (definition.zone === "mid") {
            const startExtension = definition.face === "bottom" ? bottomStartExtension : 0;
            const endExtension = definition.face === "bottom" ? bottomEndExtension : 0;
            return [{
                ...definition,
                rebar,
                x1: hasStartDevelopment ? resolvedStartBarEndX : (startExtension > EDGE_TOLERANCE ? anchorStart - startExtension : bodyStart),
                x2: hasEndDevelopment ? resolvedEndBarEndX : (endExtension > EDGE_TOLERANCE ? anchorEnd + endExtension : bodyEnd),
                hookLeft: false,
                hookRight: false,
                developmentDimensions: [
                    ...createStartDevelopmentDimension(startExtension, bottomStartDimensionLength),
                    ...createEndDevelopmentDimension(endExtension, bottomEndDimensionLength)
                ],
                label: formatAutocadAdditionalRebarLabel(rebar)
            }];
        }

        const isIEnd = definition.zone === "iEnd";
        const zoneAtLocalStart = isIEnd ? iEndAtLocalStart : !iEndAtLocalStart;
        const deadKey = isIEnd ? "iEndDead" : "jEndDead";
        const isDeadEnd = Boolean(deadEnds[deadKey]);

        if (zoneAtLocalStart) {
            const startExtension = definition.face === "bottom" && !isDeadEnd ? bottomStartExtension : 0;
            return [{
                ...definition,
                rebar,
                // At a terminal frame end, continue through the terminal support;
                // the hook is inset from its exterior face. At an interior support,
                // retain the centerline anchor so matching bars can merge continuously.
                x1: isDeadEnd ? terminalAnchorStart : (hasStartDevelopment ? resolvedStartBarEndX : anchorStart - startExtension),
                x2: Math.min(bodyStart + thirdSpan, bodyEnd),
                hookLeft: isDeadEnd,
                hookRight: false,
                leftHookInnerOffset: isDeadEnd ? terminalStartHookInset : undefined,
                developmentDimensions: createStartDevelopmentDimension(startExtension, bottomStartDimensionLength),
                label: formatAutocadAdditionalRebarLabel(rebar)
            }];
        }

        const endExtension = definition.face === "bottom" && !isDeadEnd ? bottomEndExtension : 0;
        return [{
            ...definition,
            rebar,
            x1: Math.max(bodyEnd - thirdSpan, bodyStart),
            // Mirror the terminal rule at the far beam end.
            x2: isDeadEnd ? terminalAnchorEnd : (hasEndDevelopment ? resolvedEndBarEndX : anchorEnd + endExtension),
            hookLeft: false,
            hookRight: isDeadEnd,
            rightHookInnerOffset: isDeadEnd ? terminalEndHookInset : undefined,
            developmentDimensions: createEndDevelopmentDimension(endExtension, bottomEndDimensionLength),
            label: formatAutocadAdditionalRebarLabel(rebar)
        }];
    });
}


function normalizeBeamAdditionalSegmentKeyPart(value) {
    return String(value || "").trim();
}

function getBeamAdditionalSegmentConsumptionKey(beamId, zoneKey) {
    const safeBeamId = normalizeBeamAdditionalSegmentKeyPart(beamId);
    const safeZoneKey = normalizeBeamAdditionalSegmentKeyPart(zoneKey);
    return safeBeamId && safeZoneKey ? `${safeBeamId}|${safeZoneKey}` : "";
}

function getBeamAdditionalZoneKeyAtLocalSide(beam, side, face, axisType = null) {
    const normalizedSide = side === "end" ? "end" : "start";
    const normalizedFace = face === "bottom" ? "Bottom" : "Top";
    const iEndAtLocalStart = isBeamIEndAtLocalStart(beam, axisType);
    const zone = normalizedSide === "start"
        ? (iEndAtLocalStart ? "iEnd" : "jEnd")
        : (iEndAtLocalStart ? "jEnd" : "iEnd");

    return `${zone}${normalizedFace}`;
}

function getFrameAdditionalRebarSignature(rebar) {
    const normalized = normalizeOptionalLongitudinalRebar(rebar, {
        n: "0",
        d: DEFAULT_LONGITUDINAL_DIAMETER
    });
    const count = parseOptionalBarCount(normalized.n);
    const diameter = normalizeDiameterLabel(normalized.d);

    return count > 0 && diameter ? `${count}|${diameter}` : "";
}

function getFrameAdditionalRebarDrawSettings(contentOriginY, topElevation, beamHeight, barThicknessValue) {
    const safeBeamHeight = parsePositiveNumberOrFallback(beamHeight, 0.4, 0.1);
    const safeBarThickness = parsePositiveNumberOrFallback(barThicknessValue, 0.012, 0.001);
    const topMainBarOffset = 0.04;
    const bottomMainBarOffset = 0.04;
    const additionalBarClearOffset = 0.035;
    const topAdditionalOffset = Math.min(
        topMainBarOffset + additionalBarClearOffset,
        Math.max(topMainBarOffset + safeBarThickness, safeBeamHeight - 0.08)
    );
    const bottomAdditionalOffset = Math.min(
        bottomMainBarOffset + additionalBarClearOffset,
        Math.max(bottomMainBarOffset + safeBarThickness, safeBeamHeight - 0.08)
    );
    const topZ1 = contentOriginY + topElevation - topAdditionalOffset;
    const topZ2 = topZ1 - safeBarThickness;
    const bottomZ1 = contentOriginY + topElevation - safeBeamHeight + bottomAdditionalOffset;
    const bottomZ2 = bottomZ1 + safeBarThickness;
    const hookDirectionReference = Math.max(
        Math.min(safeBeamHeight * 0.25, 0.10),
        safeBarThickness * 2
    );

    return {
        topZ1,
        topZ2,
        bottomZ1,
        bottomZ2,
        // The sign of the hook level controls the hook direction in drawSmartRebar.
        // Keep top additional hooks facing down and bottom additional hooks facing up,
        // including in shallow beams where a level derived from the beam top may flip sign.
        topHookLevel: (topZ1 + topZ2) / 2 - hookDirectionReference,
        bottomHookLevel: (bottomZ1 + bottomZ2) / 2 + hookDirectionReference,
        // Keep additional-steel notes on the same horizontal text line as
        // the corresponding principal longitudinal-steel notes.
        topLabelY: contentOriginY + topElevation + 0.15,
        bottomLabelY: contentOriginY + topElevation - safeBeamHeight - 0.15,
        // Upper additional-bar length dimensions belong above the upper beam
        // face. Lower dimensions retain their location below the lower face.
        topLengthDimensionY: contentOriginY + topElevation + 0.25,
        topLengthDimensionOriginY: contentOriginY + topElevation,
        bottomLengthDimensionY: contentOriginY + topElevation - safeBeamHeight - 0.25,
        bottomLengthDimensionOriginY: contentOriginY + topElevation - safeBeamHeight,
        // Legacy fallbacks retained for older segment callers.
        lengthDimensionY: contentOriginY + topElevation - safeBeamHeight - 0.25,
        lengthDimensionOriginY: contentOriginY + topElevation - safeBeamHeight,
        labelSize: 0.1
    };
}

function getFrameBeamAdditionalGeometry(member, supports, localizePosition, concreteCoverValue = 0) {
    const start = parseNumberOrFallback(member?.start, Number.NaN);
    const end = parseNumberOrFallback(member?.end, Number.NaN);
    const beam = member?.beam;

    if (!beam || !Number.isFinite(start) || !Number.isFinite(end)) {
        return null;
    }

    const spanStart = Math.min(start, end);
    const spanEnd = Math.max(start, end);
    const startSupport = getFrameSupportAtPosition(supports, spanStart);
    const endSupport = getFrameSupportAtPosition(supports, spanEnd);
    const bodyStartMetric = spanStart + (startSupport?.width || 0) / 2;
    const bodyEndMetric = spanEnd - (endSupport?.width || 0) / 2;
    const normalizedBodyStartMetric = Math.min(bodyStartMetric, bodyEndMetric);
    const normalizedBodyEndMetric = Math.max(bodyStartMetric, bodyEndMetric);
    const clearSpan = Math.max(normalizedBodyEndMetric - normalizedBodyStartMetric, 0);

    if (clearSpan <= EDGE_TOLERANCE) {
        return null;
    }

    return {
        beam,
        start: spanStart,
        end: spanEnd,
        bodyStartMetric: normalizedBodyStartMetric,
        bodyEndMetric: normalizedBodyEndMetric,
        bodyStart: localizePosition(normalizedBodyStartMetric),
        bodyEnd: localizePosition(normalizedBodyEndMetric),
        anchorStart: localizePosition(spanStart),
        anchorEnd: localizePosition(spanEnd),
        clearSpan,
        thirdSpan: clearSpan / 3,
        beamHeight: parsePositiveNumberOrFallback(beam.h, 0.4, 0.1),
        concreteCover: Math.max(parseNumberOrFallback(concreteCoverValue, 0), 0)
    };
}

function findFrameSupportBetweenAdjacentBeamMembers(supports, leftEnd, rightStart, tolerance = 0.08) {
    const safeTolerance = Math.max(Number.isFinite(tolerance) ? tolerance : 0.08, 0.01);
    const start = Math.min(leftEnd, rightStart);
    const end = Math.max(leftEnd, rightStart);

    return (Array.isArray(supports) ? supports : []).find((support) => {
        if (!support || !Number.isFinite(support.position)) {
            return false;
        }

        const width = parsePositiveNumberOrFallback(support.width, 0, 0);
        const supportStart = support.position - width / 2;
        const supportEnd = support.position + width / 2;

        return supportEnd >= start - safeTolerance
            && supportStart <= end + safeTolerance;
    }) || null;
}

function shouldTreatFrameBeamMembersAsAdjacent(leftMember, rightMember, supports, tolerance = 0.08) {
    const leftEnd = parseNumberOrFallback(leftMember?.end, Number.NaN);
    const rightStart = parseNumberOrFallback(rightMember?.start, Number.NaN);

    if (!Number.isFinite(leftEnd) || !Number.isFinite(rightStart) || rightStart < leftEnd - tolerance) {
        return false;
    }

    const gap = Math.max(rightStart - leftEnd, 0);
    if (gap <= tolerance) {
        return true;
    }

    const support = findFrameSupportBetweenAdjacentBeamMembers(supports, leftEnd, rightStart, tolerance);
    if (support) {
        const allowedGap = Math.max(parsePositiveNumberOrFallback(support.width, 0, 0) + 0.25, 0.35);
        return gap <= allowedGap + tolerance;
    }

    return gap <= Math.max(tolerance, 0.12);
}

function buildDirectFrameJointAdditionalRebarSegments({
    beamSegments,
    supports,
    localizePosition,
    contentOriginY,
    topElevation,
    concreteCover,
    barThickness,
    axisType
} = {}) {
    const sortedMembers = (Array.isArray(beamSegments) ? beamSegments : [])
        .slice()
        .sort((left, right) => (left.start - right.start) || (left.end - right.end));
    const segments = [];
    const consumedZoneKeys = new Set();

    for (let index = 0; index < sortedMembers.length - 1; index += 1) {
        const leftMember = sortedMembers[index];
        const rightMember = sortedMembers[index + 1];
        if (!leftMember?.beam?.id || !rightMember?.beam?.id) {
            continue;
        }

        if (!shouldTreatFrameBeamMembersAsAdjacent(leftMember, rightMember, supports)) {
            continue;
        }

        const leftGeometry = getFrameBeamAdditionalGeometry(leftMember, supports, localizePosition, concreteCover);
        const rightGeometry = getFrameBeamAdditionalGeometry(rightMember, supports, localizePosition, concreteCover);
        if (!leftGeometry || !rightGeometry) {
            continue;
        }

        const leftAdditional = normalizeBeamAdditionalRebar(leftMember.beam.additionalRebar);
        const rightAdditional = normalizeBeamAdditionalRebar(rightMember.beam.additionalRebar);
        const support = findFrameSupportBetweenAdjacentBeamMembers(supports, leftMember.end, rightMember.start);
        const labelCenterX = support?.position !== undefined
            ? localizePosition(support.position)
            : (localizePosition(leftMember.end) + localizePosition(rightMember.start)) / 2;

        ["top", "bottom"].forEach((face) => {
            const leftZoneKey = getBeamAdditionalZoneKeyAtLocalSide(leftMember.beam, "end", face, axisType);
            const rightZoneKey = getBeamAdditionalZoneKeyAtLocalSide(rightMember.beam, "start", face, axisType);
            const leftRebar = leftAdditional[leftZoneKey];
            const rightRebar = rightAdditional[rightZoneKey];
            const leftSignature = getFrameAdditionalRebarSignature(leftRebar);
            const rightSignature = getFrameAdditionalRebarSignature(rightRebar);
            const signature = leftSignature || rightSignature;

            if (!signature) {
                return;
            }

            if (leftSignature && rightSignature && leftSignature !== rightSignature) {
                return;
            }

            const sharedRebar = leftSignature ? leftRebar : rightRebar;

            const leftSettings = getFrameAdditionalRebarDrawSettings(contentOriginY, topElevation, leftGeometry.beamHeight, barThickness);
            const rightSettings = getFrameAdditionalRebarDrawSettings(contentOriginY, topElevation, rightGeometry.beamHeight, barThickness);
            if (face === "bottom") {
                const leftCenter = (leftSettings.bottomZ1 + leftSettings.bottomZ2) / 2;
                const rightCenter = (rightSettings.bottomZ1 + rightSettings.bottomZ2) / 2;
                if (Math.abs(leftCenter - rightCenter) > 0.01) {
                    return;
                }
            }

            const x1 = localizePosition(leftGeometry.bodyEndMetric - leftGeometry.thirdSpan);
            const x2 = localizePosition(rightGeometry.bodyStartMetric + rightGeometry.thirdSpan);
            if (!(x2 > x1 + 0.01)) {
                return;
            }

            segments.push({
                key: `${leftZoneKey}-${rightZoneKey}`,
                zone: "mid",
                face,
                rebar: sharedRebar,
                x1,
                x2,
                hookLeft: false,
                hookRight: false,
                label: formatAutocadAdditionalRebarLabel(sharedRebar),
                labelCenterX,
                ...leftSettings
            });

            consumedZoneKeys.add(getBeamAdditionalSegmentConsumptionKey(leftMember.beam.id, leftZoneKey));
            consumedZoneKeys.add(getBeamAdditionalSegmentConsumptionKey(rightMember.beam.id, rightZoneKey));
        });
    }

    return {
        segments,
        consumedZoneKeys
    };
}

function normalizeAdditionalRebarMergeOptions(options = {}) {
    if (typeof options === "number") {
        return {
            tolerance: Math.max(Number.isFinite(options) ? options : 0.01, 0.001),
            bridgeIntervals: [],
            maxBridgeGap: 0
        };
    }

    const tolerance = Math.max(parsePositiveNumberOrFallback(options?.tolerance, 0.01, 0.001), 0.001);
    const rawMaxBridgeGap = parseNumberOrFallback(options?.maxBridgeGap, 0);
    const maxBridgeGap = Number.isFinite(rawMaxBridgeGap) ? Math.max(rawMaxBridgeGap, 0) : 0;
    const bridgeIntervals = (Array.isArray(options?.bridgeIntervals) ? options.bridgeIntervals : [])
        .map((interval) => {
            const start = parseNumberOrFallback(interval?.start, Number.NaN);
            const end = parseNumberOrFallback(interval?.end, Number.NaN);
            return {
                start: Math.min(start, end),
                end: Math.max(start, end)
            };
        })
        .filter((interval) => Number.isFinite(interval.start) && Number.isFinite(interval.end) && interval.end > interval.start + tolerance)
        .sort((left, right) => left.start - right.start || left.end - right.end);

    return { tolerance, bridgeIntervals, maxBridgeGap };
}

function isAdditionalRebarGapBridgeable(leftX, rightX, bridgeIntervals = [], tolerance = 0.01, maxBridgeGap = 0) {
    if (!Number.isFinite(leftX) || !Number.isFinite(rightX) || rightX < leftX - tolerance) {
        return false;
    }

    const gap = rightX - leftX;
    if (gap <= tolerance) {
        return true;
    }

    if (maxBridgeGap > 0 && gap <= maxBridgeGap + tolerance) {
        return true;
    }

    return (Array.isArray(bridgeIntervals) ? bridgeIntervals : []).some((interval) => (
        Number.isFinite(interval?.start)
        && Number.isFinite(interval?.end)
        && interval.start <= leftX + tolerance
        && interval.end >= rightX - tolerance
    ));
}

function getAdditionalRebarSegmentVerticalKey(segment, face) {
    const z1 = face === "bottom"
        ? parseNumberOrFallback(segment?.bottomZ1, Number.NaN)
        : parseNumberOrFallback(segment?.topZ1, Number.NaN);
    const z2 = face === "bottom"
        ? parseNumberOrFallback(segment?.bottomZ2, Number.NaN)
        : parseNumberOrFallback(segment?.topZ2, Number.NaN);
    const center = Number.isFinite(z1) && Number.isFinite(z2)
        ? (z1 + z2) / 2
        : Number.isFinite(z1)
            ? z1
            : z2;

    return Number.isFinite(center) ? getDetailMetricKey(center, 2) : "";
}

function getAdditionalRebarSegmentMergeKey(segment) {
    const face = segment?.face === "bottom" ? "bottom" : "top";
    const normalizedRebar = normalizeOptionalLongitudinalRebar(segment?.rebar, {
        n: "0",
        d: DEFAULT_LONGITUDINAL_DIAMETER
    });
    const count = parseOptionalBarCount(normalizedRebar.n);
    const diameter = normalizeDiameterLabel(normalizedRebar.d);
    const rebarKey = count > 0 && diameter
        ? `${count}|${diameter}`
        : String(segment?.label || "");

    return [
        face,
        rebarKey,
        getAdditionalRebarSegmentVerticalKey(segment, face)
    ].join("|");
}

function mergeBeamAdditionalRebarSegments(segments, options = {}) {
    const { tolerance, bridgeIntervals, maxBridgeGap } = normalizeAdditionalRebarMergeOptions(options);
    const groupedSegments = new Map();

    (Array.isArray(segments) ? segments : []).forEach((segment, index) => {
        if (!segment) {
            return;
        }

        const x1 = parseNumberOrFallback(segment.x1, Number.NaN);
        const x2 = parseNumberOrFallback(segment.x2, Number.NaN);
        if (!Number.isFinite(x1) || !Number.isFinite(x2) || x2 <= x1 + tolerance) {
            return;
        }

        const face = segment.face === "bottom" ? "bottom" : "top";
        const normalizedSegment = {
            ...segment,
            face,
            x1,
            x2
        };
        const key = getAdditionalRebarSegmentMergeKey(normalizedSegment);

        if (!groupedSegments.has(key)) {
            groupedSegments.set(key, []);
        }

        groupedSegments.get(key).push({
            ...normalizedSegment,
            _order: index
        });
    });

    const mergedSegments = [];
    const faceOrder = { top: 0, bottom: 1 };

    groupedSegments.forEach((groupSegments) => {
        const sortedSegments = groupSegments.sort((left, right) => (
            left.x1 - right.x1
            || left.x2 - right.x2
            || left._order - right._order
        ));

        let currentSegment = null;

        const flushCurrentSegment = () => {
            if (!currentSegment) {
                return;
            }

            const sourceSegments = currentSegment._sourceSegments || [];
            const mergedX1 = currentSegment.x1;
            const mergedX2 = currentSegment.x2;

            mergedSegments.push({
                ...currentSegment,
                x1: mergedX1,
                x2: mergedX2,
                zone: sourceSegments.length > 1 ? "mid" : currentSegment.zone,
                labelCenterX: sourceSegments.length > 1 ? (mergedX1 + mergedX2) / 2 : undefined,
                _sourceSegments: undefined
            });
        };

        sortedSegments.forEach((segment) => {
            if (!currentSegment) {
                currentSegment = {
                    ...segment,
                    _sourceSegments: [segment]
                };
                return;
            }

            const canMergeAcrossGap = isAdditionalRebarGapBridgeable(
                currentSegment.x2,
                segment.x1,
                bridgeIntervals,
                tolerance,
                maxBridgeGap
            );

            if (segment.x1 <= currentSegment.x2 + tolerance || canMergeAcrossGap) {
                const previousX1 = currentSegment.x1;
                const previousX2 = currentSegment.x2;
                const extendsLeft = segment.x1 < previousX1 - tolerance;
                const sharesLeftEnd = Math.abs(segment.x1 - previousX1) <= tolerance;
                const extendsRight = segment.x2 > previousX2 + tolerance;
                const sharesRightEnd = Math.abs(segment.x2 - previousX2) <= tolerance;

                currentSegment.x1 = Math.min(previousX1, segment.x1);
                currentSegment.x2 = Math.max(previousX2, segment.x2);

                if (extendsLeft) {
                    currentSegment.hookLeft = Boolean(segment.hookLeft);
                    currentSegment.leftHookInnerOffset = segment.hookLeft
                        ? segment.leftHookInnerOffset
                        : undefined;
                } else if (sharesLeftEnd && segment.hookLeft) {
                    currentSegment.hookLeft = true;
                    currentSegment.leftHookInnerOffset = segment.leftHookInnerOffset;
                }

                if (extendsRight) {
                    currentSegment.hookRight = Boolean(segment.hookRight);
                    currentSegment.rightHookInnerOffset = segment.hookRight
                        ? segment.rightHookInnerOffset
                        : undefined;
                } else if (sharesRightEnd && segment.hookRight) {
                    currentSegment.hookRight = true;
                    currentSegment.rightHookInnerOffset = segment.rightHookInnerOffset;
                }

                const currentDevelopmentDimensions = Array.isArray(currentSegment.developmentDimensions)
                    ? currentSegment.developmentDimensions
                    : [];
                const segmentDevelopmentDimensions = Array.isArray(segment.developmentDimensions)
                    ? segment.developmentDimensions
                    : [];
                if (segmentDevelopmentDimensions.length) {
                    currentSegment.developmentDimensions = [
                        ...currentDevelopmentDimensions,
                        ...segmentDevelopmentDimensions
                    ];
                }

                currentSegment._sourceSegments.push(segment);
                return;
            }

            flushCurrentSegment();
            currentSegment = {
                ...segment,
                _sourceSegments: [segment]
            };
        });

        flushCurrentSegment();
    });

    return mergedSegments.sort((left, right) => (
        faceOrder[left.face] - faceOrder[right.face]
        || left.x1 - right.x1
        || left.x2 - right.x2
        || (left._order || 0) - (right._order || 0)
    ));
}

function getBeamAdditionalLabelYOffset(zone, step = 0.18) {
    // Keep every additional-steel note vertically aligned with the principal
    // longitudinal-steel note on the same beam face.
    return 0;
}

function getBeamAdditionalLabelCenterX(segment, x1, x2) {
    const span = Math.max(x2 - x1, 0.01);
    const faceBias = segment?.face === "top" ? -0.06 : 0.06;

    if (segment?.zone === "iEnd") {
        return x1 + span * Math.max(0.12, Math.min(0.24 + faceBias, 0.34));
    }

    if (segment?.zone === "jEnd") {
        return x1 + span * Math.max(0.66, Math.min(0.76 + faceBias, 0.88));
    }

    return x1 + span * Math.max(0.4, Math.min(0.5 + faceBias, 0.6));
}

function normalizeBeamAdditionalDimensionBreakIntervals(intervals = [], tolerance = EDGE_TOLERANCE) {
    const safeTolerance = Math.max(parsePositiveNumberOrFallback(tolerance, EDGE_TOLERANCE, 0.001), 0.001);
    const normalized = (Array.isArray(intervals) ? intervals : [])
        .map((interval) => {
            const rawStart = parseNumberOrFallback(interval?.start ?? interval?.x1, Number.NaN);
            const rawEnd = parseNumberOrFallback(interval?.end ?? interval?.x2, Number.NaN);
            return {
                start: Math.min(rawStart, rawEnd),
                end: Math.max(rawStart, rawEnd)
            };
        })
        .filter((interval) => (
            Number.isFinite(interval.start)
            && Number.isFinite(interval.end)
            && interval.end > interval.start + safeTolerance
        ))
        .sort((left, right) => left.start - right.start || left.end - right.end);

    const merged = [];
    normalized.forEach((interval) => {
        const current = merged[merged.length - 1];
        if (!current || interval.start > current.end + safeTolerance) {
            merged.push({ ...interval });
            return;
        }
        current.end = Math.max(current.end, interval.end);
    });

    return merged;
}

function getBeamAdditionalLengthDimensionIntervals(x1, x2, breakIntervals = [], tolerance = EDGE_TOLERANCE) {
    const start = Math.min(parseNumberOrFallback(x1, Number.NaN), parseNumberOrFallback(x2, Number.NaN));
    const end = Math.max(parseNumberOrFallback(x1, Number.NaN), parseNumberOrFallback(x2, Number.NaN));
    const safeTolerance = Math.max(parsePositiveNumberOrFallback(tolerance, EDGE_TOLERANCE, 0.001), 0.001);

    if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start + safeTolerance) {
        return [];
    }

    // Split only where the additional bar fully crosses an interior support.
    // Terminal supports keep the existing end treatment and dimension behavior.
    const internalBreaks = normalizeBeamAdditionalDimensionBreakIntervals(breakIntervals, safeTolerance)
        .map((interval) => ({
            start: Math.max(interval.start, start),
            end: Math.min(interval.end, end)
        }))
        .filter((interval) => (
            interval.start > start + safeTolerance
            && interval.end < end - safeTolerance
            && interval.end > interval.start + safeTolerance
        ));

    if (!internalBreaks.length) {
        return [{ x1: start, x2: end }];
    }

    const dimensionIntervals = [];
    let cursor = start;
    internalBreaks.forEach((interval) => {
        if (interval.start > cursor + safeTolerance) {
            dimensionIntervals.push({ x1: cursor, x2: interval.start });
        }
        cursor = Math.max(cursor, interval.end);
    });

    if (end > cursor + safeTolerance) {
        dimensionIntervals.push({ x1: cursor, x2: end });
    }

    return dimensionIntervals;
}

/* SERVER_ONLY_START */
function drawBeamAdditionalRebarSegments(dxf, segments, {
    topZ1,
    topZ2,
    bottomZ1,
    bottomZ2,
    topHookLevel,
    bottomHookLevel,
    topLabelY,
    bottomLabelY,
    labelSize = 0.1,
    hookOuterOffset = 0.03,
    hookInnerOffset = 0.055,
    hookLegAtSegmentEnds = false,
    bridgeIntervals = [],
    tolerance = 0.01,
    maxBridgeGap = 0,
    includeFill = true,
    fillStyle = "solid",
    hatchLayer = FRAME_LONGITUDINAL_HATCH_LAYER,
    hatchPatternName = FRAME_REBAR_HATCH_PATTERN,
    hatchPatternScale = FRAME_REBAR_HATCH_SCALE,
    hatchPatternAngle = 45,
    textResolver = null,
    drawLengthDimensions = false,
    lengthDimensionVisualScale = 1,
    lengthDimensionStackStep = 0.16,
    lengthDimensionBreakIntervals = []
} = {}) {
    const mergedSegments = mergeBeamAdditionalRebarSegments(segments, { bridgeIntervals, tolerance, maxBridgeGap });
    const dimensionCountByBaseY = new Map();
    const drawnDimensionKeys = new Set();
    const developmentDimensionCountByBaseY = new Map();
    const drawnDevelopmentDimensionKeys = new Set();
    const getLengthDimensionIntervalKey = (x1, x2) => {
        const start = Math.min(parseNumberOrFallback(x1, Number.NaN), parseNumberOrFallback(x2, Number.NaN));
        const end = Math.max(parseNumberOrFallback(x1, Number.NaN), parseNumberOrFallback(x2, Number.NaN));
        return Number.isFinite(start) && Number.isFinite(end)
            ? `${getDetailMetricKey(start, 3)}|${getDetailMetricKey(end, 3)}`
            : "";
    };
    // When upper and lower longitudinal bars have the same dimension interval,
    // retain only the lower dimension to avoid duplicating the same measurement
    // above and below the beam.
    const bottomLengthDimensionIntervalKeys = new Set();
    if (drawLengthDimensions) {
        mergedSegments.forEach((segment) => {
            if (!segment || segment.face !== "bottom") {
                return;
            }

            const x1 = parseNumberOrFallback(segment.x1, Number.NaN);
            const x2 = parseNumberOrFallback(segment.x2, Number.NaN);
            const baseDimensionY = parseNumberOrFallback(
                segment.bottomLengthDimensionY,
                parseNumberOrFallback(segment.lengthDimensionY, Number.NaN)
            );
            const dimensionOriginY = parseNumberOrFallback(
                segment.bottomLengthDimensionOriginY,
                parseNumberOrFallback(segment.lengthDimensionOriginY, Number.NaN)
            );
            if (!Number.isFinite(x1) || !Number.isFinite(x2) || x2 <= x1 + 0.01
                || !Number.isFinite(baseDimensionY) || !Number.isFinite(dimensionOriginY)) {
                return;
            }

            getBeamAdditionalLengthDimensionIntervals(
                x1,
                x2,
                lengthDimensionBreakIntervals,
                tolerance
            ).forEach((interval) => {
                const intervalKey = getLengthDimensionIntervalKey(interval.x1, interval.x2);
                if (intervalKey) {
                    bottomLengthDimensionIntervalKeys.add(intervalKey);
                }
            });
        });
    }

    mergedSegments.forEach((segment) => {
        if (!segment) {
            return;
        }

        const x1 = parseNumberOrFallback(segment.x1, Number.NaN);
        const x2 = parseNumberOrFallback(segment.x2, Number.NaN);
        if (!Number.isFinite(x1) || !Number.isFinite(x2) || x2 <= x1 + 0.01) {
            return;
        }

        const isTop = segment.face === "top";
        const resolvedTopZ1 = parseNumberOrFallback(segment.topZ1, topZ1);
        const resolvedTopZ2 = parseNumberOrFallback(segment.topZ2, topZ2);
        const resolvedBottomZ1 = parseNumberOrFallback(segment.bottomZ1, bottomZ1);
        const resolvedBottomZ2 = parseNumberOrFallback(segment.bottomZ2, bottomZ2);
        const resolvedTopLabelY = parseNumberOrFallback(segment.topLabelY, topLabelY);
        const resolvedBottomLabelY = parseNumberOrFallback(segment.bottomLabelY, bottomLabelY);
        const resolvedLabelSize = parsePositiveNumberOrFallback(segment.labelSize, labelSize, 0.01);
        const z1 = isTop ? resolvedTopZ1 : resolvedBottomZ1;
        const z2 = isTop ? resolvedTopZ2 : resolvedBottomZ2;
        const barCenterY = (z1 + z2) / 2;
        const fallbackTopHookLevel = parseNumberOrFallback(topHookLevel, barCenterY);
        const fallbackBottomHookLevel = parseNumberOrFallback(bottomHookLevel, barCenterY);
        // Frame segments carry their own hook levels because adjacent beams can
        // have different depths.  Use those per-segment values first; otherwise
        // keep the caller-provided level for standalone beam details.
        const resolvedTopHookLevel = parseNumberOrFallback(segment.topHookLevel, fallbackTopHookLevel);
        const resolvedBottomHookLevel = parseNumberOrFallback(segment.bottomHookLevel, fallbackBottomHookLevel);
        const resolvedHookLevel = isTop ? resolvedTopHookLevel : resolvedBottomHookLevel;
        const labelYBase = isTop ? resolvedTopLabelY : resolvedBottomLabelY;

        if (!Number.isFinite(z1) || !Number.isFinite(z2) || !Number.isFinite(labelYBase) || !Number.isFinite(resolvedHookLevel)) {
            return;
        }

        const labelYOffset = getBeamAdditionalLabelYOffset(segment.zone);
        const labelY = isTop ? labelYBase + labelYOffset : labelYBase - labelYOffset;
        const baseLabelCenterX = Number.isFinite(segment.labelCenterX)
            ? segment.labelCenterX
            : getBeamAdditionalLabelCenterX(segment, x1, x2);
        const labelCenterX = isTop ? baseLabelCenterX - 0.25 : baseLabelCenterX;
        const leftHookInnerOffset = parsePositiveNumberOrFallback(segment.leftHookInnerOffset, hookInnerOffset, 0);
        const rightHookInnerOffset = parsePositiveNumberOrFallback(segment.rightHookInnerOffset, hookInnerOffset, 0);

        drawSmartRebar(
            dxf,
            isTop ? "ACERO_SUPERIOR" : "ACERO_INFERIOR",
            x1,
            x2,
            z1,
            z2,
            resolvedHookLevel,
            Boolean(segment.hookLeft),
            Boolean(segment.hookRight),
            {
                leftHookInnerOffset,
                rightHookInnerOffset,
                hookBendRadius: DXF_REBAR_HOOK_BEND_RADIUS,
                hookOuterOffset,
                hookLength: Math.max((getDiameterMetersFromBarLabel(segment.rebar?.d, getActiveBarSetForDiameters()) || 0) * 16, 0),
                as2d: includeFill !== false,
                fillStyle,
                hatchLayer,
                hatchPatternName,
                hatchPatternScale,
                hatchPatternAngle,
                capStyle: "semicircle",
                hookLegAtBarExtents: hookLegAtSegmentEnds === true
            }
        );

        if (segment.label) {
            drawCollisionAwareLeaderText(
                dxf,
                textResolver,
                "TEXTO_ACERO",
                segment.label,
                labelCenterX,
                labelY,
                labelCenterX,
                (z1 + z2) / 2,
                resolvedLabelSize,
                isTop ? "above" : "below",
                {
                    axis: "x",
                    minX: x1,
                    maxX: x2,
                    followTargetX: true
                }
            );
        }

        if (drawLengthDimensions) {
            const faceDimensionY = isTop
                ? segment.topLengthDimensionY
                : segment.bottomLengthDimensionY;
            const faceDimensionOriginY = isTop
                ? segment.topLengthDimensionOriginY
                : segment.bottomLengthDimensionOriginY;
            const baseDimensionY = parseNumberOrFallback(
                faceDimensionY,
                parseNumberOrFallback(segment.lengthDimensionY, Number.NaN)
            );
            const dimensionOriginY = parseNumberOrFallback(
                faceDimensionOriginY,
                parseNumberOrFallback(segment.lengthDimensionOriginY, Number.NaN)
            );
            if (Number.isFinite(baseDimensionY) && Number.isFinite(dimensionOriginY)) {
                const dimensionIntervals = getBeamAdditionalLengthDimensionIntervals(
                    x1,
                    x2,
                    lengthDimensionBreakIntervals,
                    tolerance
                );
                const baseKey = getDetailMetricKey(baseDimensionY, 3);
                const pendingIntervals = dimensionIntervals.filter((interval) => {
                    const intervalKey = getLengthDimensionIntervalKey(interval.x1, interval.x2);
                    if (isTop && intervalKey && bottomLengthDimensionIntervalKeys.has(intervalKey)) {
                        return false;
                    }
                    const dimensionKey = `${getDetailMetricKey(interval.x1, 3)}|${getDetailMetricKey(interval.x2, 3)}|${baseKey}`;
                    return !drawnDimensionKeys.has(dimensionKey);
                });

                if (pendingIntervals.length) {
                    const stackIndex = dimensionCountByBaseY.get(baseKey) || 0;
                    const dimensionStackOffset = stackIndex * Math.max(parseNumberOrFallback(lengthDimensionStackStep, 0.16), 0.08);
                    // Stack top dimensions upward and bottom dimensions downward,
                    // always moving away from the corresponding beam face.
                    const dimensionY = isTop
                        ? baseDimensionY + dimensionStackOffset
                        : baseDimensionY - dimensionStackOffset;
                    pendingIntervals.forEach((interval) => {
                        const dimensionKey = `${getDetailMetricKey(interval.x1, 3)}|${getDetailMetricKey(interval.x2, 3)}|${baseKey}`;
                        addDimension(
                            dxf,
                            "COTAS_SECCION",
                            interval.x1,
                            interval.x2,
                            dimensionY,
                            Math.abs(interval.x2 - interval.x1),
                            dimensionOriginY,
                            { visualScale: lengthDimensionVisualScale }
                        );
                        drawnDimensionKeys.add(dimensionKey);
                    });
                    // Every piece of the same bar remains aligned on one dimension line.
                    dimensionCountByBaseY.set(baseKey, stackIndex + 1);
                }
            }
        }

        if (!isTop && Array.isArray(segment.developmentDimensions) && segment.developmentDimensions.length) {
            const baseDimensionY = Number.isFinite(parseNumberOrFallback(segment.developmentDimensionY, Number.NaN))
                ? parseNumberOrFallback(segment.developmentDimensionY, Number.NaN)
                : Number.isFinite(parseNumberOrFallback(segment.lengthDimensionY, Number.NaN))
                    ? parseNumberOrFallback(segment.lengthDimensionY, Number.NaN) + 0.04
                    : barCenterY - 0.28;
            const dimensionOriginY = Number.isFinite(parseNumberOrFallback(segment.developmentDimensionOriginY, Number.NaN))
                ? parseNumberOrFallback(segment.developmentDimensionOriginY, Number.NaN)
                : barCenterY;

            segment.developmentDimensions.forEach((dimension) => {
                const dimensionX1 = parseNumberOrFallback(dimension?.x1, Number.NaN);
                const dimensionX2 = parseNumberOrFallback(dimension?.x2, Number.NaN);
                const dimensionLength = parsePositiveNumberOrFallback(dimension?.length, Math.abs(dimensionX2 - dimensionX1), 0);
                if (!Number.isFinite(dimensionX1) || !Number.isFinite(dimensionX2) || !(dimensionLength > EDGE_TOLERANCE)) {
                    return;
                }

                const dimensionKey = `${getDetailMetricKey(Math.min(dimensionX1, dimensionX2), 3)}|${getDetailMetricKey(Math.max(dimensionX1, dimensionX2), 3)}|${getDetailMetricKey(baseDimensionY, 3)}`;
                if (drawnDevelopmentDimensionKeys.has(dimensionKey)) {
                    return;
                }

                const baseKey = getDetailMetricKey(baseDimensionY, 3);
                const stackIndex = developmentDimensionCountByBaseY.get(baseKey) || 0;
                const dimensionY = baseDimensionY - (stackIndex * Math.max(parseNumberOrFallback(lengthDimensionStackStep, 0.16), 0.08));
                drawDevelopmentInsertionDimension(dxf, {
                    x1: dimensionX1,
                    x2: dimensionX2,
                    dimensionY,
                    originY: dimensionOriginY,
                    length: dimensionLength,
                    visualScale: lengthDimensionVisualScale
                });
                developmentDimensionCountByBaseY.set(baseKey, stackIndex + 1);
                drawnDevelopmentDimensionKeys.add(dimensionKey);
            });
        }
    });
}
/* SERVER_ONLY_END */

function findLevelByName(levelName) {
    const normalizedName = normalizeTextValue(levelName).toLowerCase();
    if (!normalizedName) {
        return null;
    }

    return projectState.levels.find((level) => normalizeTextValue(level?.name).toLowerCase() === normalizedName) || null;
}

function getBeamContinuousChainForLevel(level, beam) {
    if (!level || !beam?.id) {
        return null;
    }

    return getContinuousBeamChainsForLevel(level).find((chain) => (
        (chain.members || []).some((member) => member?.id === beam.id)
    )) || null;
}

function getBeamSectionZoneLabel(zone) {
    if (zone === "iEnd") {
        return translate("modal.zoneIEnd");
    }

    if (zone === "jEnd") {
        return translate("modal.zoneJEnd");
    }

    return translate("modal.zoneMid");
}

function getBeamEffectiveSectionFaceDetailParts(beam, zone, face) {
    const normalizedBeam = beam?.id ? normalizeBeamModel(beam) : normalizeBeamInsertDraft(beam);
    const additionalRebar = normalizeBeamAdditionalRebar(normalizedBeam.additionalRebar);
    const isTopFace = face === "top";
    const mainRebar = isTopFace ? normalizedBeam.topRebar : normalizedBeam.botRebar;
    const midRebar = isTopFace ? additionalRebar.midTop : additionalRebar.midBottom;
    const zoneRebar = zone === "iEnd"
        ? (isTopFace ? additionalRebar.iEndTop : additionalRebar.iEndBottom)
        : zone === "jEnd"
            ? (isTopFace ? additionalRebar.jEndTop : additionalRebar.jEndBottom)
            : null;

    return [
        {
            role: "main",
            count: parseBarCount(mainRebar?.n),
            diameterLabel: mainRebar?.d
        },
        {
            role: "mid",
            count: parseOptionalBarCount(midRebar?.n),
            diameterLabel: midRebar?.d
        },
        {
            role: "zone",
            count: parseOptionalBarCount(zoneRebar?.n),
            diameterLabel: zoneRebar?.d
        }
    ].filter((part) => part.count > 0 && normalizeDiameterLabel(part.diameterLabel));
}

function formatBeamSectionFaceDetailParts(detailParts = [], zone = "mid") {
    const partLabels = {
        main: translate("quantities.beamDetailMain"),
        mid: translate("quantities.beamDetailAdditionalMid"),
        zone: translate("quantities.beamDetailAdditionalZone", {
            zone: getBeamSectionZoneLabel(zone)
        })
    };

    const parts = (Array.isArray(detailParts) ? detailParts : [])
        .map((part) => {
            const label = partLabels[part.role] || partLabels.main;
            const count = getQuantityCountLabel(part.count);
            const diameter = normalizeDiameterLabel(part.diameterLabel);
            if (!count || !diameter) {
                return "";
            }

            return `${label}: ${formatDxfRebarCountLabel(count, diameter)}`;
        })
        .filter(Boolean);

    return parts.length > 0 ? parts.join("; ") : "-";
}

function formatBeamSectionZoneSummary(zones = []) {
    const uniqueZones = (Array.isArray(zones) ? zones : [])
        .filter(Boolean)
        .filter((zone, index, source) => source.indexOf(zone) === index);

    if (!uniqueZones.length) {
        return "";
    }

    return uniqueZones.map((zone) => getBeamSectionZoneLabel(zone)).join(" / ");
}

function getBeamEffectiveSectionFaceSpecs(beam, zone, face) {
    return normalizeBeamSectionFaceBarSpecs(
        getBeamEffectiveSectionFaceDetailParts(beam, zone, face).map((part) => ({
            count: part.count,
            diameterLabel: part.diameterLabel
        }))
    );
}

function getBeamEffectiveSectionDetailData(beam, zone = "mid") {
    const normalizedBeam = beam?.id ? normalizeBeamModel(beam) : normalizeBeamInsertDraft(beam);
    const topDetailParts = getBeamEffectiveSectionFaceDetailParts(normalizedBeam, zone, "top");
    const bottomDetailParts = getBeamEffectiveSectionFaceDetailParts(normalizedBeam, zone, "bottom");
    const topSpecs = normalizeBeamSectionFaceBarSpecs(topDetailParts);
    const bottomSpecs = normalizeBeamSectionFaceBarSpecs(bottomDetailParts);
    const transverseRebar = getBeamDrawingTransverseRebarForZone(normalizedBeam, zone, normalizedBeam.stirrups);

    return {
        zone,
        topSpecs,
        bottomSpecs,
        topDetailParts,
        bottomDetailParts,
        transverseRebar,
        stirrupLabel: formatDxfBeamStirrupLabel(transverseRebar, DEFAULT_BEAM_STIRRUP_SPACING),
        topLabel: formatBeamSectionFaceBarSpecs(topSpecs),
        bottomLabel: formatBeamSectionFaceBarSpecs(bottomSpecs),
        topDetail: formatBeamSectionFaceDetailParts(topDetailParts, zone),
        bottomDetail: formatBeamSectionFaceDetailParts(bottomDetailParts, zone),
        layout: getBeamSectionLongitudinalBarLayout(normalizedBeam, {
            topSpecs,
            bottomSpecs,
            stirrupDiameterLabel: transverseRebar.d
        }),
        signatureKey: JSON.stringify({
            b: getDetailMetricKey(normalizedBeam.b),
            h: getDetailMetricKey(normalizedBeam.h),
            structuralMaterial: normalizedBeam.structuralMaterial,
            stirrups: transverseRebar,
            coverTop: getDetailMetricKey(normalizedBeam.coverTop),
            coverBottom: getDetailMetricKey(normalizedBeam.coverBottom),
            topSpecs: topSpecs.map((barSpec) => ({
                count: barSpec.count,
                diameterLabel: barSpec.diameterLabel
            })),
            bottomSpecs: bottomSpecs.map((barSpec) => ({
                count: barSpec.count,
                diameterLabel: barSpec.diameterLabel
            }))
        })
    };
}

function getBeamSectionZoneCutOffset(beam, zone = "mid", axisType = null) {
    const span = getBeamSpan(beam);
    if (!(span > 0.01)) {
        return 0;
    }

    if (zone === "mid") {
        return span / 2;
    }

    const endZoneCenter = span / 6;
    const iEndAtLocalStart = isBeamIEndAtLocalStart(beam, axisType);

    if (zone === "iEnd") {
        return iEndAtLocalStart ? endZoneCenter : span - endZoneCenter;
    }

    return iEndAtLocalStart ? span - endZoneCenter : endZoneCenter;
}

function getBeamStrategicSectionDetailEntries(beam, axisType = null) {
    const normalizedBeam = beam?.id ? normalizeBeamModel(beam) : normalizeBeamInsertDraft(beam);
    const entries = [];
    const entryBySectionKey = new Map();
    const registerEntry = (zone) => {
        const sectionSpec = getBeamEffectiveSectionDetailData(normalizedBeam, zone);
        const existingEntry = entryBySectionKey.get(sectionSpec.signatureKey);

        if (existingEntry) {
            existingEntry.zones.push(zone);
            return;
        }

        const nextEntry = {
            zone,
            zones: [zone],
            cutOffset: getBeamSectionZoneCutOffset(normalizedBeam, zone, axisType),
            sectionSpec,
            sectionKey: sectionSpec.signatureKey
        };
        entryBySectionKey.set(sectionSpec.signatureKey, nextEntry);
        entries.push(nextEntry);
    };

    registerEntry("mid");
    registerEntry("iEnd");
    registerEntry("jEnd");

    return entries;
}

// A frame-elevation span is documented with one representative section only.
// Unlike standalone-beam details, pórticos must not create additional cuts for
// the end zones when their reinforcement differs.  The cut is always centered
// on the physical beam body and displays the midspan reinforcement state.
function getFrameMidspanSectionDetailEntry(beam, axisType = null) {
    const normalizedBeam = beam?.id ? normalizeBeamModel(beam) : normalizeBeamInsertDraft(beam);
    const zone = "mid";
    const sectionSpec = getBeamEffectiveSectionDetailData(normalizedBeam, zone);

    return {
        zone,
        zones: [zone],
        cutOffset: getBeamSectionZoneCutOffset(normalizedBeam, zone, axisType),
        sectionSpec,
        sectionKey: sectionSpec.signatureKey
    };
}

// Frame and standalone-beam elevations share a compact numeric section reference.
function formatSectionTag(index) {
    return formatFrameSectionTag(index);
}

function formatFrameSectionTag(index) {
    const safeIndex = Math.max(0, Math.floor(parseNumberOrFallback(index, 0)));
    return `S${safeIndex + 1}`;
}

function formatSignedMetricValue(value) {
    const safeValue = parseNumberOrFallback(value, 0);
    const sign = safeValue >= 0 ? "+" : "-";
    return `${sign}${formatDxfLengthValue(Math.abs(safeValue))}`;
}

function getFrameLevelAnnotation(levelName, elevation) {
    return {
        title: normalizeTextValue(levelName) || "NIVEL",
        subtitle: `N.P.T.: (${formatSignedMetricValue(elevation)})`
    };
}

function getAlphabeticLabel(index) {
    let current = index;
    let label = "";

    do {
        label = String.fromCharCode(AXIS_LABEL_START + (current % 26)) + label;
        current = Math.floor(current / 26) - 1;
    } while (current >= 0);

    return label;
}

function getDefaultAxisLabel(axisType, index) {
    return axisType === "x" ? getAlphabeticLabel(index) : String(index + 1);
}

function getStoredAxisLabel(axisType, value) {
    return projectState.axisLabels?.[axisType]?.[getAxisValueKey(value)] || "";
}

function getAxisLabelForIndex(axisType, index) {
    const axisValues = projectState.axes[axisType] || [];
    const axisValue = axisValues[index];
    if (!Number.isFinite(axisValue)) {
        return getDefaultAxisLabel(axisType, index);
    }

    return getStoredAxisLabel(axisType, axisValue) || getDefaultAxisLabel(axisType, index);
}

function getSectionCutPosition(start, end, cutOffset) {
    const span = end - start;
    if (span <= DRAWING_COVER * 2) {
        return (start + end) / 2;
    }

    return Math.min(
        Math.max(start + cutOffset, start + DRAWING_COVER),
        end - DRAWING_COVER
    );
}

// Re-map a cut from the full beam span into the exposed clear span between supports.
function scaleSectionCutOffset(cutOffset, sourceSpan, targetSpan) {
    const safeSourceSpan = Math.max(parseNumberOrFallback(sourceSpan, 0), 0);
    const safeTargetSpan = Math.max(parseNumberOrFallback(targetSpan, 0), 0);

    if (!(safeSourceSpan > EDGE_TOLERANCE) || !(safeTargetSpan > EDGE_TOLERANCE)) {
        return Math.max(parseNumberOrFallback(cutOffset, 0), 0);
    }

    const ratio = Math.max(0, Math.min(parseNumberOrFallback(cutOffset, 0) / safeSourceSpan, 1));
    return safeTargetSpan * ratio;
}

/* SERVER_ONLY_START */
function drawSectionCutTagMarker(dxf, position, topElevation, beamHeight, sectionTag, options = {}) {
    const sharedLabelOffsetX = parseNumberOrFallback(options?.labelOffsetX, 0);
    const topLabelOffsetX = parseNumberOrFallback(options?.topLabelOffsetX, sharedLabelOffsetX);
    const bottomLabelOffsetX = parseNumberOrFallback(options?.bottomLabelOffsetX, sharedLabelOffsetX);
    const markerExtension = 0.42;
    const lineTopY = topElevation + markerExtension;
    const lineBottomY = topElevation - beamHeight - markerExtension;
    const arrowWidth = 0.09;
    const arrowHeight = 0.16;
    const tagSize = 0.22;
    const codeSize = 0.105;
    const labelGap = 0.10;
    const codeWidth = 0.28;
    const codeHeight = 0.66;
    const codeText = normalizeTextValue(options?.detailCode ?? options?.sheetCode ?? options?.drawingCode) || "E-00";
    const safeTag = normalizeTextValue(sectionTag) || "A";

    addDashedLine(dxf, "SECCION_CORTE", position, lineTopY, position, lineBottomY);
    addLine(dxf, "SECCION_CORTE", position - arrowWidth, topElevation + arrowHeight, position, topElevation + 0.01);
    addLine(dxf, "SECCION_CORTE", position + arrowWidth, topElevation + arrowHeight, position, topElevation + 0.01);
    addLine(dxf, "SECCION_CORTE", position - arrowWidth, topElevation - beamHeight - arrowHeight, position, topElevation - beamHeight - 0.01);
    addLine(dxf, "SECCION_CORTE", position + arrowWidth, topElevation - beamHeight - arrowHeight, position, topElevation - beamHeight - 0.01);

    const drawTag = (labelCenterX, baselineY, connectorY) => {
        if (Math.abs(labelCenterX - position) > EDGE_TOLERANCE) {
            addLine(dxf, "SECCION_CORTE", position, connectorY, labelCenterX, connectorY);
        }
        const tagWidth = estimateDxfTextWidth(safeTag, tagSize);
        const tagX = labelCenterX - (tagWidth + codeWidth + labelGap) / 2;
        const codeX = tagX + tagWidth + labelGap;
        const codeY = baselineY - codeHeight * 0.32;
        addText(dxf, "SECCION_TEXTO", tagX, baselineY, safeTag, tagSize);
        addRectangle(dxf, "SECCION_CORTE", codeX, codeY, codeWidth, codeHeight);
        addRotatedCenteredText(dxf, "SECCION_TEXTO", codeX + codeWidth / 2, codeY + codeHeight / 2, codeText, codeSize, 90);
    };

    drawTag(position + topLabelOffsetX, lineTopY + 0.05, lineTopY - 0.06);
    drawTag(position + bottomLabelOffsetX, lineBottomY - 0.24, lineBottomY + 0.06);
}

function drawFrameSectionCutMarker(dxf, position, topElevation, beamHeight, sectionTag, options = {}) {
    // Frame section cuts are deliberately compact: 0.15 m diameter bubbles,
    // 0.06 m labels, color 8, and continuous linework.
    const bubbleRadius = 0.075;
    const bubbleClearance = 0.12;
    const topBubbleY = topElevation + bubbleRadius + bubbleClearance;
    const bottomBubbleY = topElevation - beamHeight - bubbleRadius - bubbleClearance;
    const lineTopY = topBubbleY - bubbleRadius;
    const lineBottomY = bottomBubbleY + bubbleRadius;
    const sharedLabelOffsetX = parseNumberOrFallback(options?.labelOffsetX, 0);
    const topLabelOffsetX = parseNumberOrFallback(options?.topLabelOffsetX, sharedLabelOffsetX);
    const bottomLabelOffsetX = parseNumberOrFallback(options?.bottomLabelOffsetX, sharedLabelOffsetX);
    const topBubbleX = position + topLabelOffsetX;
    const bottomBubbleX = position + bottomLabelOffsetX;
    const safeTag = normalizeTextValue(sectionTag) || "S1";
    const lineLayer = "CORTE_PORTICO";
    const textLayer = "TEXTO_CORTE_PORTICO";

    // Do not use addDashedLine here: the requested frame-cut convention is
    // continuous from one bubble to the other.
    addLine(dxf, lineLayer, position, lineTopY, position, lineBottomY);
    if (Math.abs(topLabelOffsetX) > EDGE_TOLERANCE) {
        addLine(dxf, lineLayer, position, lineTopY, topBubbleX, lineTopY);
    }
    if (Math.abs(bottomLabelOffsetX) > EDGE_TOLERANCE) {
        addLine(dxf, lineLayer, position, lineBottomY, bottomBubbleX, lineBottomY);
    }
    addFrameSectionBubbleBlock(dxf, topBubbleX, topBubbleY, safeTag, { lineLayer, textLayer, bubbleRadius, textHeight: 0.06 });
    addFrameSectionBubbleBlock(dxf, bottomBubbleX, bottomBubbleY, safeTag, { lineLayer, textLayer, bubbleRadius, textHeight: 0.06 });
}

function drawSectionCutMarker(dxf, position, topElevation, beamHeight, sectionTag, options = {}) {
    const markerStyle = normalizeFrameElevationSectionMarkerStyle(options?.style ?? options?.sectionMarkerStyle);
    if (markerStyle === FRAME_ELEVATION_SECTION_MARKER_STYLE_TAG) {
        drawSectionCutTagMarker(dxf, position, topElevation, beamHeight, sectionTag, options);
        return;
    }

    const bubbleRadius = Math.max(0.18, (estimateDxfTextWidth(sectionTag, 0.1) / 2) + 0.06);
    const bubbleOffset = bubbleRadius + 0.12;
    const topBubbleY = topElevation + bubbleOffset;
    const bottomBubbleY = topElevation - beamHeight - bubbleOffset;
    const lineTopY = topBubbleY - bubbleRadius;
    const lineBottomY = bottomBubbleY + bubbleRadius;
    const sharedLabelOffsetX = parseNumberOrFallback(options?.labelOffsetX, 0);
    const topLabelOffsetX = parseNumberOrFallback(options?.topLabelOffsetX, sharedLabelOffsetX);
    const bottomLabelOffsetX = parseNumberOrFallback(options?.bottomLabelOffsetX, sharedLabelOffsetX);
    const topBubbleX = position + topLabelOffsetX;
    const bottomBubbleX = position + bottomLabelOffsetX;

    addDashedLine(dxf, "SECCION_CORTE", position, lineTopY, position, lineBottomY);
    if (Math.abs(topLabelOffsetX) > EDGE_TOLERANCE) {
        addLine(dxf, "SECCION_CORTE", position, lineTopY, topBubbleX, lineTopY);
    }
    if (Math.abs(bottomLabelOffsetX) > EDGE_TOLERANCE) {
        addLine(dxf, "SECCION_CORTE", position, lineBottomY, bottomBubbleX, lineBottomY);
    }
    addCircle(dxf, "SECCION_CORTE", topBubbleX, topBubbleY, bubbleRadius);
    addCircle(dxf, "SECCION_CORTE", bottomBubbleX, bottomBubbleY, bubbleRadius);
    addCenteredText(dxf, "SECCION_TEXTO", topBubbleX, topBubbleY, sectionTag, 0.1);
    addCenteredText(dxf, "SECCION_TEXTO", bottomBubbleX, bottomBubbleY, sectionTag, 0.1);
}

function drawSectionDetails(dxf, sectionDetails, startX, startY, options = {}) {
    const bottomLimit = options.bottomLimit ?? -1.5;
    let cursorX = startX;
    let cursorY = startY;
    let currentColumnWidth = 0;
    let maxRight = startX;
    let minBottom = startY;

    sectionDetails.forEach((detail) => {
        const detailSize = getSectionDetailBoxSize(detail);

        if (cursorY - detailSize.height < bottomLimit) {
            // Keep every new frame-section column five metres closer to the
            // preceding column than the previous layout.
            cursorX += currentColumnWidth + SECTION_DETAIL_MARGIN - FRAME_SECTION_DETAIL_COLUMN_LEFT_COMPRESSION;
            cursorY = startY;
            currentColumnWidth = 0;
        }

        drawBeamSectionDetail(dxf, detail, cursorX, cursorY, detailSize);
        maxRight = Math.max(maxRight, cursorX + detailSize.width);
        minBottom = Math.min(minBottom, cursorY - detailSize.height);
        // Keep each following row 4.60 m higher than before. The section-box
        // dimensions are retained for wrapping, while the drawn detail itself
        // uses this compact vertical grid.
        cursorY -= detailSize.height + SECTION_DETAIL_MARGIN - FRAME_SECTION_DETAIL_ROW_UP_COMPRESSION;
        currentColumnWidth = Math.max(currentColumnWidth, detailSize.width);
    });

    return {
        width: Math.max(maxRight - startX, 0),
        height: Math.max(startY - minBottom, 0)
    };
}

function getSectionDetailBoxSize(detailOrBeam) {
    const beam = detailOrBeam?.beam || detailOrBeam;
    const sectionWidth = beam.b * BEAM_SECTION_DETAIL_SCALE;
    const sectionHeight = beam.h * BEAM_SECTION_DETAIL_SCALE;
    const slabContext = detailOrBeam?.beam ? getBeamSectionAdjacentSlabContext(detailOrBeam) : null;
    const leftExtension = slabContext?.left?.totalDrawnWidth || 0;
    const rightExtension = slabContext?.right?.totalDrawnWidth || 0;
    const totalSectionWidth = sectionWidth + leftExtension + rightExtension;

    return {
        sectionWidth,
        sectionHeight,
        width: Math.max(totalSectionWidth + 3.5, 6.0),
        height: Math.max(sectionHeight + 3.35, 5.7)
    };
}

function getBeamSectionFallbackCutOffset(detail, beam) {
    const span = Math.max(getBeamSpanLength(beam), 0);
    if (!(span > EDGE_TOLERANCE)) {
        return 0;
    }

    const explicitCutOffset = parseNumberOrFallback(detail?.cutOffset, Number.NaN);
    if (Number.isFinite(explicitCutOffset)) {
        return Math.max(0, Math.min(explicitCutOffset, span));
    }

    const normalizedZone = String(detail?.zone || "mid").trim().toLowerCase();
    if (normalizedZone === "iend") {
        return span * 0.2;
    }
    if (normalizedZone === "jend") {
        return span * 0.8;
    }
    return span * 0.5;
}

function getBeamSectionCutPoint(detail) {
    const beam = detail?.beam;
    if (!beam) {
        return null;
    }

    const x1 = parseNumberOrFallback(beam?.x1, Number.NaN);
    const y1 = parseNumberOrFallback(beam?.y1, Number.NaN);
    const x2 = parseNumberOrFallback(beam?.x2, Number.NaN);
    const y2 = parseNumberOrFallback(beam?.y2, Number.NaN);
    if (!hasFiniteNumbers(x1, y1, x2, y2)) {
        return null;
    }

    const dx = x2 - x1;
    const dy = y2 - y1;
    const span = Math.hypot(dx, dy);
    if (!(span > EDGE_TOLERANCE)) {
        return { x: x1, y: y1, unitX: 1, unitY: 0 };
    }

    const cutOffset = getBeamSectionFallbackCutOffset(detail, beam);
    const unitX = dx / span;
    const unitY = dy / span;

    return {
        x: x1 + unitX * cutOffset,
        y: y1 + unitY * cutOffset,
        unitX,
        unitY
    };
}

function getBeamSectionSideSlabDescriptor(detail, side = "left") {
    const level = findLevelByName(detail?.levelName);
    const cutPoint = getBeamSectionCutPoint(detail);
    if (!level || !cutPoint) {
        return null;
    }

    const sideMultiplier = side === "right" ? -1 : 1;
    const normalX = -cutPoint.unitY * sideMultiplier;
    const normalY = cutPoint.unitX * sideMultiplier;
    // Slabs normally terminate at the beam face, not at its centerline.  Sample
    // just outside that face so a slab whose boundary is offset by b / 2 (as in
    // imported ETABS models) is recognized as adjacent to the beam section.
    const beamHalfWidth = Math.max(parsePositiveNumberOrFallback(detail?.beam?.b, 0, 0) / 2, 0);
    const sampleDistance = beamHalfWidth + SECTION_DETAIL_SIDE_SAMPLE_CLEARANCE;
    const samplePoint = {
        x: cutPoint.x + normalX * sampleDistance,
        y: cutPoint.y + normalY * sampleDistance
    };

    const slabs = (level?.slabs || [])
        .map((slab) => normalizeSlab(slab))
        .filter((slab) => slab.type !== "hole")
        .filter((slab) => normalizeStructuralMaterialSpec(slab.structuralMaterial).type === "concrete")
        .filter((slab) => isPointInPolygon(samplePoint, slab.vertices, { includeBoundary: false }));

    if (!slabs.length) {
        return null;
    }

    const slab = slabs.sort((left, right) => {
        const leftArea = Math.abs(getSlabPolygonArea(left.vertices));
        const rightArea = Math.abs(getSlabPolygonArea(right.vertices));
        if (Math.abs(leftArea - rightArea) > EDGE_TOLERANCE) {
            return leftArea - rightArea;
        }
        return String(left.name || "").localeCompare(String(right.name || ""), undefined, { numeric: true, sensitivity: "base" });
    })[0];

    const totalThickness = Math.min(
        Math.max(parsePositiveNumberOrFallback(slab?.h, 0, 0), 0),
        Math.max(parsePositiveNumberOrFallback(detail?.beam?.h, 0, 0), 0)
    );
    if (!(totalThickness > EDGE_TOLERANCE)) {
        return null;
    }

    const isLightened = slab.type === "lightened";
    const cassetteThickness = isLightened
        ? Math.min(
            Math.max(parsePositiveNumberOrFallback(slab?.lightened?.cassetteThickness, totalThickness * 0.7, 0.01), 0.01),
            totalThickness
        )
        : 0;
    const firstExtension = SLAB_SECTION_CONCRETE_EXTENSION_LENGTH * BEAM_SECTION_DETAIL_SCALE;
    const secondExtension = isLightened ? LIGHTENED_SLAB_SECTION_CONCRETE_EXTENSION_LENGTH * BEAM_SECTION_DETAIL_SCALE : 0;

    return {
        side,
        slab,
        type: isLightened ? "lightened" : "solid",
        meshLabel: isLightened ? formatCompactDxfWeldedWireMeshLabel(slab?.lightened?.topWeldedWireMesh) : "",
        thickness: totalThickness,
        cassetteThickness,
        drawnThickness: totalThickness * BEAM_SECTION_DETAIL_SCALE,
        drawnCassetteThickness: cassetteThickness * BEAM_SECTION_DETAIL_SCALE,
        firstExtension,
        secondExtension,
        totalDrawnWidth: firstExtension + secondExtension
    };
}

function getBeamSectionAdjacentSlabContext(detail) {
    if (!detail?.beam || isDxfSteelBeam(detail.beam)) {
        return null;
    }

    return {
        left: getBeamSectionSideSlabDescriptor(detail, "left"),
        right: getBeamSectionSideSlabDescriptor(detail, "right")
    };
}

function getFrameSectionLongitudinalReinforcementKey(sectionSpec = {}) {
    const toFaceKey = (barSpecs = []) => (Array.isArray(barSpecs) ? barSpecs : []).map((barSpec) => ({
        count: parseBarCount(barSpec?.count ?? barSpec?.n),
        diameterLabel: normalizeDiameterLabel(barSpec?.diameterLabel ?? barSpec?.d)
    }));

    return {
        top: toFaceKey(sectionSpec.topSpecs),
        bottom: toFaceKey(sectionSpec.bottomSpecs)
    };
}

function getFrameSectionTransverseReinforcementKey(sectionSpec = {}) {
    const transverseRebar = sectionSpec?.transverseRebar || {};
    return {
        count: parseBarCount(transverseRebar.count ?? transverseRebar.n ?? transverseRebar.quantity ?? 1),
        diameterLabel: normalizeDiameterLabel(transverseRebar.diameterLabel ?? transverseRebar.diameter ?? transverseRebar.d),
        spacing: getDetailMetricKey(transverseRebar.spacing ?? transverseRebar.s ?? DEFAULT_BEAM_STIRRUP_SPACING)
    };
}

// A pórtico section is normally duplicated only when its visible geometry
// changes.  The two optional drawing preferences allow the reference to split
// by longitudinal and/or transverse reinforcement, while still ignoring cover,
// level, beam ID, span and cut position.  Left/right are kept separate because
// a slab on one face is not the same drawing as a slab on the opposite face.
function getFrameSectionReferenceKey(detail) {
    const sourceBeam = detail?.beam || null;
    const beam = sourceBeam?.id ? normalizeBeamModel(sourceBeam) : normalizeBeamInsertDraft(sourceBeam || {});
    const sectionSpec = detail?.sectionSpec || getBeamEffectiveSectionDetailData(beam, detail?.zone || "mid");
    const preferences = normalizeFrameSectionDrawingPreferences(
        detail?.frameSectionPreferences ?? detail?.sectionPreferences
    );
    const slabContext = getBeamSectionAdjacentSlabContext({
        beam,
        levelName: detail?.levelName,
        cutOffset: detail?.cutOffset
    });
    const getSideType = (sideData) => {
        if (!sideData) {
            return "none";
        }
        return sideData.type === "lightened" ? "lightened" : "solid";
    };
    const referenceKey = {
        b: getDetailMetricKey(beam.b),
        h: getDetailMetricKey(beam.h),
        leftSlab: getSideType(slabContext?.left),
        rightSlab: getSideType(slabContext?.right)
    };

    if (preferences.createSectionPerDistinctLongitudinalReinforcement) {
        referenceKey.longitudinalReinforcement = getFrameSectionLongitudinalReinforcementKey(sectionSpec);
    }
    if (preferences.createSectionPerDistinctTransverseReinforcement) {
        referenceKey.transverseReinforcement = getFrameSectionTransverseReinforcementKey(sectionSpec);
    }

    return JSON.stringify(referenceKey);
}

function getColumnElevationStyleBreakPoints(originX, bottom, top, mirrored = false, options = {}) {
    const startY = Math.min(bottom, top);
    const endY = Math.max(bottom, top);
    const height = endY - startY;
    if (!(height > EDGE_TOLERANCE)) {
        return [];
    }

    const extension = parsePositiveNumberOrFallback(options.extension, 0.10, 0);
    const xRatios = mirrored
        ? [0, 0, 0.175, -0.175, 0, 0]
        : [0, 0, -0.175, 0.175, 0, 0];
    const yValues = [
        startY - extension,
        startY + (0.15 * height),
        startY + (0.325 * height),
        startY + (0.675 * height),
        startY + (0.85 * height),
        endY + extension
    ];

    return xRatios.map((xRatio, index) => ({
        x: originX + (xRatio * height),
        y: yValues[index]
    }));
}

function drawBeamSectionContinuitySymbol(arr, x, y1, y2, mirrored = false) {
    const points = getColumnElevationStyleBreakPoints(x, y1, y2, mirrored, { extension: 0.10 });

    for (let index = 0; index < points.length - 1; index += 1) {
        const start = points[index];
        const end = points[index + 1];
        addPolylineLine(arr, "CONTINUIDAD_SIMBOLO", start.x, start.y, end.x, end.y);
    }
}

function drawLightenedSlabSectionMesh(arr, sideData, beamFaceX, slabStartY) {
    if (!sideData || sideData.type !== "lightened") {
        return;
    }

    const direction = sideData.side === "left" ? -1 : 1;
    const symbolX = beamFaceX + direction * sideData.totalDrawnWidth;
    const meshY = slabStartY + sideData.drawnCassetteThickness + (LIGHTENED_SLAB_SECTION_MESH_VERTICAL_OFFSET * BEAM_SECTION_DETAIL_SCALE);
    const meshEndX = symbolX - direction * (LIGHTENED_SLAB_SECTION_MESH_LENGTH * BEAM_SECTION_DETAIL_SCALE);
    addPolylineLine(arr, "MALLA_SECCION", symbolX, meshY, meshEndX, meshY, { lineType: "CONTINUOUS", color: 151 });
    const pointRadius = (LIGHTENED_SLAB_SECTION_MESH_POINT_DIAMETER * BEAM_SECTION_DETAIL_SCALE) / 2;
    for (let current = LIGHTENED_SLAB_SECTION_MESH_POINT_SPACING; current < LIGHTENED_SLAB_SECTION_MESH_LENGTH + EDGE_TOLERANCE; current += LIGHTENED_SLAB_SECTION_MESH_POINT_SPACING) {
        const pointX = symbolX - direction * (current * BEAM_SECTION_DETAIL_SCALE);
        addFilledCircle(arr, "MALLA_SECCION", pointX, meshY, pointRadius, 4);
    }
}

function drawBeamSectionMeshCallout(dxf, sideData, beamFaceX, slabStartY, beamTopY) {
    if (!sideData || sideData.type !== "lightened") {
        return;
    }

    const meshLabel = sideData.meshLabel || formatCompactDxfWeldedWireMeshLabel(DEFAULT_THIN_WALL_WELDED_MESH);
    if (!meshLabel) {
        return;
    }

    const direction = sideData.side === "left" ? -1 : 1;
    const symbolX = beamFaceX + direction * sideData.totalDrawnWidth;
    const meshY = slabStartY + sideData.drawnCassetteThickness + (LIGHTENED_SLAB_SECTION_MESH_VERTICAL_OFFSET * BEAM_SECTION_DETAIL_SCALE);
    const meshTargetX = symbolX - direction * ((LIGHTENED_SLAB_SECTION_MESH_LENGTH * BEAM_SECTION_DETAIL_SCALE) * 0.5);
    const textSize = BEAM_SECTION_TEXT_HEIGHT;
    const textTopY = beamTopY + 0.18;
    const baseTextLeftX = direction > 0
        ? symbolX + 0.12
        : symbolX - Math.max(estimateDxfTextWidth("MALLA ELECTROSOLDADA", textSize), estimateDxfTextWidth(meshLabel, textSize)) - 0.12;
    const textLeftX = baseTextLeftX + LIGHTENED_SLAB_SECTION_MESH_CALLOUT_TEXT_RIGHT_SHIFT - 1.0;
    // The horizontal steel-denotation shoulder is intentionally located just
    // below the first annotation line, independently of the mesh target.
    const leaderStartX = (direction > 0
        ? baseTextLeftX + 0.24
        : baseTextLeftX + Math.max(estimateDxfTextWidth("MALLA ELECTROSOLDADA", textSize), estimateDxfTextWidth(meshLabel, textSize)) - 0.12) + LIGHTENED_SLAB_SECTION_MESH_CALLOUT_LEADER_RIGHT_SHIFT - 1.0;
    const leaderStartY = textTopY - (textSize * 0.55) - LIGHTENED_SLAB_SECTION_MESH_CALLOUT_LEADER_DOWN_SHIFT;

    addText(dxf, "TEXTO_ACERO", textLeftX, textTopY, "MALLA ELECTROSOLDADA", textSize);
    addText(dxf, "TEXTO_ACERO", textLeftX, textTopY - (textSize + 0.05), meshLabel, textSize);
    drawSteelDenotationPolyline(dxf, leaderStartX, leaderStartY, meshTargetX, meshY);
}

function drawBeamSectionAdjacentSlabGeometry(dxf, sideData, beamFaceX, slabStartY, topY) {
    if (!sideData) {
        return;
    }

    const direction = sideData.side === "left" ? -1 : 1;
    const firstOuterX = beamFaceX + direction * sideData.firstExtension;
    const symbolX = beamFaceX + direction * sideData.totalDrawnWidth;

    if (sideData.type === "solid") {
        addPolylineLine(dxf, "CONCRETO_VIGAS", beamFaceX, slabStartY, firstOuterX, slabStartY);
        addPolylineLine(dxf, "CONCRETO_VIGAS", beamFaceX, topY, symbolX, topY);
        drawBeamSectionContinuitySymbol(dxf, symbolX, slabStartY, topY, direction > 0);
        return;
    }

    const cassetteTopY = slabStartY + sideData.drawnCassetteThickness;
    addPolylineLine(dxf, "CONCRETO_VIGAS", beamFaceX, slabStartY, firstOuterX, slabStartY);
    addPolylineLine(dxf, "CONCRETO_VIGAS", firstOuterX, slabStartY, firstOuterX, cassetteTopY);
    addPolylineLine(dxf, "CONCRETO_VIGAS", firstOuterX, cassetteTopY, symbolX, cassetteTopY);
    addPolylineLine(dxf, "CONCRETO_VIGAS", beamFaceX, topY, symbolX, topY);
    drawBeamSectionContinuitySymbol(dxf, symbolX, slabStartY, topY, direction > 0);
    addHatch(dxf, "LOSA_BOVEDILLA", [
        { x: firstOuterX, y: slabStartY },
        { x: symbolX, y: slabStartY },
        { x: symbolX, y: cassetteTopY },
        { x: firstOuterX, y: cassetteTopY }
    ], {
        patternName: "ANSI31",
        patternScale: ANSI31_HATCH_SPACING / 3.175,
        patternAngle: 0,
        hatchStyle: 1,
        color: 8
    });
    drawLightenedSlabSectionMesh(dxf, sideData, beamFaceX, slabStartY);
}

function drawBeamSectionAdjacentSlabDimensions(dxf, sideData, beamFaceX, beamBottomY, beamTopY, options = {}) {
    if (!sideData) {
        return;
    }

    const dimensionSide = options.dimensionSide === "right" ? "right" : "left";
    const dimensionDirection = dimensionSide === "right" ? 1 : -1;
    const slabStartY = beamTopY - sideData.drawnThickness;
    const outerEdgeX = beamFaceX + (sideData.side === "left" ? -1 : 1) * sideData.totalDrawnWidth;
    const outsideOffset = dimensionSide === "right"
        ? SECTION_DETAIL_RIGHT_DIMENSION_OUTSIDE_OFFSET
        : SECTION_DETAIL_LEFT_DIMENSION_OUTSIDE_OFFSET + SECTION_DETAIL_LEFT_DIMENSION_LEFT_SHIFT;
    const alignedDimensionX = outerEdgeX + dimensionDirection * outsideOffset;
    const beamAnchorX = beamFaceX + dimensionDirection * SECTION_DETAIL_DIMENSION_POINT_CLEARANCE;
    const includeVerticalDimensions = options.includeVerticalDimensions !== false;
    const dimensionOptions = { textHeight: BEAM_SECTION_TEXT_HEIGHT };
    if (includeVerticalDimensions) {
        // The slab thickness and beam-base-to-slab dimensions share one aligned
        // dimension line.  The total beam height uses a second line farther
        // outward, keeping every dimension outside the section geometry.
        addVerticalDimension(dxf, "COTAS_SECCION", alignedDimensionX, slabStartY, beamTopY, sideData.thickness, beamAnchorX, dimensionOptions);
        addVerticalDimension(dxf, "COTAS_SECCION", alignedDimensionX, beamBottomY, slabStartY, Math.max(parsePositiveNumberOrFallback(options.beamHeightMeters, 0, 0) - sideData.thickness, 0), beamAnchorX, dimensionOptions);
        addVerticalDimension(
            dxf,
            "COTAS_SECCION",
            alignedDimensionX + dimensionDirection * SECTION_DETAIL_DIMENSION_TOTAL_HEIGHT_GAP,
            beamBottomY,
            beamTopY,
            options.beamHeightMeters,
            beamAnchorX,
            dimensionOptions
        );
    }

    if (sideData.type === "lightened") {
        const dimensionOuterX = beamFaceX + (sideData.side === "left" ? -1 : 1) * sideData.firstExtension;
        addDimension(
            dxf,
            "COTAS_SECCION",
            beamFaceX,
            dimensionOuterX,
            beamBottomY - (SECTION_DETAIL_LIGHTENED_BOTTOM_DIMENSION_BASE_OFFSET - SECTION_DETAIL_LIGHTENED_BOTTOM_DIMENSION_RAISE),
            "VARIABLE",
            beamBottomY,
            {
                ...dimensionOptions,
                preserveValue: true,
                textHorizontalPosition: sideData.side === "right"
                    ? "secondExtensionLine"
                    : "firstExtensionLine"
            }
        );
    }
}

function drawBeamSectionDetail(dxf, detail, originX, originY, detailSize) {
    const { beam, tag } = detail;
    if (isDxfSteelBeam(beam)) {
        drawSteelBeamSectionDetail(dxf, detail, originX, originY, detailSize);
        return;
    }
    const slabContext = getBeamSectionAdjacentSlabContext(detail);
    const leftSlab = slabContext?.left || null;
    const rightSlab = slabContext?.right || null;
    const sectionWidth = detailSize.sectionWidth;
    const sectionHeight = detailSize.sectionHeight;
    const left = originX + 0.45 + (leftSlab?.totalDrawnWidth || 0);
    const bottom = originY - sectionHeight - 1.05;
    const right = left + sectionWidth;
    const top = bottom + sectionHeight;
    const coverSideMeters = getBeamSideCover(beam.coverTop, beam.coverBottom);
    const coverSide = Math.min(coverSideMeters * BEAM_SECTION_DETAIL_SCALE, Math.max(sectionWidth / 2 - 0.06, 0.04));
    const coverTop = Math.min(beam.coverTop * BEAM_SECTION_DETAIL_SCALE, Math.max(sectionHeight / 2 - 0.06, 0.04));
    const coverBottom = Math.min(beam.coverBottom * BEAM_SECTION_DETAIL_SCALE, Math.max(sectionHeight / 2 - 0.06, 0.04));
    // These coordinates represent the exterior faces of the stirrup, because
    // the concrete cover is measured to the outside of the transverse steel.
    // For frame sections, the drawing centerline is shifted toward the beam
    // core by half the stirrup thickness. This anchors R0.0242 precisely on
    // the exterior (beam-edge) face and R0.0146 on the interior face.
    const stirrupExteriorLeft = left + coverSide;
    const stirrupExteriorRight = right - coverSide;
    const stirrupExteriorBottom = bottom + coverBottom;
    const stirrupExteriorTop = top - coverTop;
    const isStandaloneBeamSection = detail?.detailContext === "standalone";
    const isFrameBeamSection = detail?.detailContext === "frame";
    // Standalone beam sections intentionally reuse the full pórtico stirrup geometry:
    // ANSI37 hatch, prescribed tangent corner radii, and tangent hook tails.
    const usesFrameSteelHatches = detail?.detailContext === "frame" || isStandaloneBeamSection;
    // The coordinates passed to the rounded-stirrup routine are its centerline.
    // For standalone sections, offset that centerline by the physical rendered
    // half-thickness so the *outside* of the stirrup sits exactly at the specified
    // concrete cover instead of visually adding a second cover margin.
    const stirrupCenterlineInset = usesFrameSteelHatches
        ? ((FRAME_SECTION_STIRRUP_HOOK_OUTER_RADIUS - FRAME_SECTION_STIRRUP_HOOK_INNER_RADIUS) / 2) * BEAM_SECTION_DETAIL_SCALE
        : isStandaloneBeamSection
            ? DXF_STIRRUP_2D_RADIUS
            : 0;
    const stirrupLeft = stirrupExteriorLeft + stirrupCenterlineInset;
    const stirrupRight = stirrupExteriorRight - stirrupCenterlineInset;
    const stirrupBottom = stirrupExteriorBottom + stirrupCenterlineInset;
    const stirrupTop = stirrupExteriorTop - stirrupCenterlineInset;
    const stirrupHookLength = Math.max(Math.min(stirrupRight - stirrupLeft, stirrupTop - stirrupBottom) * 0.18, 0.1);
    const stirrupSegments = createColumnConfinementRectangleSegments(
        stirrupLeft,
        stirrupBottom,
        stirrupRight,
        stirrupTop,
        stirrupHookLength
    );
    const sectionSpec = detail.sectionSpec || getBeamEffectiveSectionDetailData(beam, detail.zone || "mid");
    const longitudinalLayout = sectionSpec.layout || getBeamSectionLongitudinalBarLayout(beam);
    const coverLabel = (Math.abs(beam.coverTop - beam.coverBottom) <= 1e-3
        ? `REC.: ${formatLengthForUnit(beam.coverTop, "section")}`
        : `REC.: SUP./INF./LAT. ${formatLengthForUnit(beam.coverTop, "section")}/${formatLengthForUnit(beam.coverBottom, "section")}/${formatLengthForUnit(coverSideMeters, "section")}`
    ).toUpperCase();
    const frameSectionDrawingPreferences = normalizeFrameSectionDrawingPreferences(
        detail?.frameSectionPreferences ?? detail?.sectionPreferences
    );
    const showFrameLongitudinalReinforcement = isFrameBeamSection
        && frameSectionDrawingPreferences.createSectionPerDistinctLongitudinalReinforcement;
    const showFrameTransverseReinforcement = isFrameBeamSection
        && frameSectionDrawingPreferences.createSectionPerDistinctTransverseReinforcement;
    const isSharedSection = Number.isFinite(detail.referenceCount) && detail.referenceCount > 1;
    // Keep the concrete-cover note immediately below the beam bottom face in
    // pórtico and standalone transverse sections.
    const coverTextY = (isFrameBeamSection || isStandaloneBeamSection)
        ? bottom - 0.07
        : bottom - 0.72;
    const steelLabelX = right + 0.78;
    const stirrupLabelX = steelLabelX - 0.75;
    const beamSectionDimensionOptions = { textHeight: BEAM_SECTION_TEXT_HEIGHT };
    const topSteelBar = longitudinalLayout.bars.find((bar) => bar.face === "top") || null;
    const bottomSteelBar = longitudinalLayout.bars.find((bar) => bar.face === "bottom") || null;
    const renderedStirrupHalfThickness = usesFrameSteelHatches
        ? ((FRAME_SECTION_STIRRUP_HOOK_OUTER_RADIUS - FRAME_SECTION_STIRRUP_HOOK_INNER_RADIUS) / 2) * BEAM_SECTION_DETAIL_SCALE
        : DXF_STIRRUP_2D_RADIUS;
    const stirrupInnerBounds = {
        left: stirrupLeft + renderedStirrupHalfThickness,
        right: stirrupRight - renderedStirrupHalfThickness,
        bottom: stirrupBottom + renderedStirrupHalfThickness,
        top: stirrupTop - renderedStirrupHalfThickness
    };
    const renderedBars = longitudinalLayout.bars.map((bar) => ({
        ...bar,
        centerX: left + (bar.xMeters * BEAM_SECTION_DETAIL_SCALE),
        centerY: bottom + (bar.yMeters * BEAM_SECTION_DETAIL_SCALE),
        radius: getBeamSectionRebarDrawRadius(bar.diameterLabel)
    }));
    if (isStandaloneBeamSection) {
        const barsByRow = new Map();
        renderedBars.forEach((bar) => {
            const rowKey = `${bar.face}|${bar.layerIndex}`;
            const row = barsByRow.get(rowKey) || [];
            row.push(bar);
            barsByRow.set(rowKey, row);
        });
        barsByRow.forEach((row, rowKey) => {
            if (row.length > 1) {
                const leftmost = row.reduce((current, bar) => (bar.centerX < current.centerX ? bar : current));
                const rightmost = row.reduce((current, bar) => (bar.centerX > current.centerX ? bar : current));
                leftmost.centerX = stirrupInnerBounds.left + leftmost.radius;
                rightmost.centerX = stirrupInnerBounds.right - rightmost.radius;
            }
            const [face, layerIndexText] = rowKey.split("|");
            if (Number(layerIndexText) === 0) {
                row.forEach((bar) => {
                    if (face === "top") {
                        bar.centerY = stirrupInnerBounds.top - bar.radius;
                    } else if (face === "bottom") {
                        bar.centerY = stirrupInnerBounds.bottom + bar.radius;
                    }
                });
            }
        });
    }
    const topRenderedBar = renderedBars.find((bar) => bar.face === "top") || null;
    const bottomRenderedBar = renderedBars.find((bar) => bar.face === "bottom") || null;
    const topSteelTarget = topRenderedBar
        ? { x: topRenderedBar.centerX, y: topRenderedBar.centerY }
        : { x: left + (sectionWidth / 2), y: top - coverTop };
    const bottomSteelTarget = bottomRenderedBar
        ? { x: bottomRenderedBar.centerX, y: bottomRenderedBar.centerY }
        : { x: left + (sectionWidth / 2), y: bottom + coverBottom };
    const stirrupTarget = {
        x: stirrupRight,
        y: (stirrupTop + stirrupBottom) / 2
    };
    const sideLabelMidY = bottom + (sectionHeight * 0.5);
    const markerCenterX = left + 0.15;
    // Raise the entire beam-section title marker, its title line, and text
    // together so the notation stays aligned in frame and standalone sections.
    const markerCenterY = bottom - 1.45 + BEAM_SECTION_TITLE_RAISE + BEAM_SECTION_TITLE_UP_SHIFT;
    const leftSlabStartY = leftSlab ? top - leftSlab.drawnThickness : null;
    const rightSlabStartY = rightSlab ? top - rightSlab.drawnThickness : null;

    addPolylineLine(dxf, "CONCRETO_VIGAS", left, bottom, right, bottom);
    addPolylineLine(dxf, "CONCRETO_VIGAS", left, top, right, top);
    if (leftSlabStartY === null) {
        addPolylineLine(dxf, "CONCRETO_VIGAS", left, bottom, left, top);
    } else {
        addPolylineLine(dxf, "CONCRETO_VIGAS", left, bottom, left, leftSlabStartY);
        drawBeamSectionAdjacentSlabGeometry(dxf, leftSlab, left, leftSlabStartY, top);
    }
    if (rightSlabStartY === null) {
        addPolylineLine(dxf, "CONCRETO_VIGAS", right, bottom, right, top);
    } else {
        addPolylineLine(dxf, "CONCRETO_VIGAS", right, bottom, right, rightSlabStartY);
        drawBeamSectionAdjacentSlabGeometry(dxf, rightSlab, right, rightSlabStartY, top);
    }
    [
        { sideData: leftSlab, beamFaceX: left, slabStartY: leftSlabStartY },
        { sideData: rightSlab, beamFaceX: right, slabStartY: rightSlabStartY }
    ].forEach(({ sideData, beamFaceX, slabStartY }) => {
        if (sideData && slabStartY !== null) {
            drawBeamSectionMeshCallout(dxf, sideData, beamFaceX, slabStartY, top);
        }
    });
    if (stirrupRight > stirrupLeft && stirrupTop > stirrupBottom) {
        const frameSectionStirrupCenterlineRadius = ((FRAME_SECTION_STIRRUP_HOOK_INNER_RADIUS + FRAME_SECTION_STIRRUP_HOOK_OUTER_RADIUS) / 2) * BEAM_SECTION_DETAIL_SCALE;
        drawDxfConfinementSegmentsWithRoundedCorners(dxf, "ACERO_TRANSVERSAL", stirrupSegments, usesFrameSteelHatches
            ? {
                fillStyle: "hatch",
                hatchLayer: FRAME_STIRRUP_HATCH_LAYER,
                hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
                hatchPatternScale: FRAME_REBAR_HATCH_SCALE,
                frameSectionTangentHooks: true,
                // All stirrup corners must use the same prescribed inside and
                // outside tangent radii as the hooks.  This keeps every corner
                // of the frame-section stirrup at R0.0146 / R0.0242 physically.
                radius: frameSectionStirrupCenterlineRadius,
                barRadius: stirrupCenterlineInset,
                frameSectionTangentCorners: true,
                frameSectionCornerInnerRadius: FRAME_SECTION_STIRRUP_HOOK_INNER_RADIUS,
                frameSectionCornerOuterRadius: FRAME_SECTION_STIRRUP_HOOK_OUTER_RADIUS,
                frameSectionCornerScale: BEAM_SECTION_DETAIL_SCALE,
                frameSectionHookInnerRadius: FRAME_SECTION_STIRRUP_HOOK_INNER_RADIUS,
                frameSectionHookOuterRadius: FRAME_SECTION_STIRRUP_HOOK_OUTER_RADIUS,
                frameSectionHookScale: BEAM_SECTION_DETAIL_SCALE
            }
            : {}
        );
    }

    renderedBars.forEach((bar) => {
        const layer = bar.face === "top" ? "ACERO_SUPERIOR" : "ACERO_INFERIOR";
        // On standalone beam sections, the outer edge of the first/last bar
        // is tangent to the stirrup's visible inner line, rather than sitting
        // unnecessarily toward the section center.
        addRepresentativeRebarCircle(dxf, layer, bar.centerX, bar.centerY, bar.radius, DXF_REBAR_REPRESENTATIVE_FILL_COLOR);
    });

    const bottomBeamDimensionY = bottom - ([leftSlab, rightSlab].some((sideData) => sideData?.type === "lightened")
        ? SECTION_DETAIL_LIGHTENED_BOTTOM_DIMENSION_BASE_OFFSET - SECTION_DETAIL_LIGHTENED_BOTTOM_DIMENSION_RAISE
        : 0.35) + BEAM_SECTION_BOTTOM_DIMENSION_UP_SHIFT;
    addDimension(dxf, "COTAS_SECCION", left, right, bottomBeamDimensionY, beam.b, bottom, beamSectionDimensionOptions);
    const adjacentSlabs = [leftSlab, rightSlab].filter(Boolean);
    if (adjacentSlabs.length) {
        adjacentSlabs.forEach((sideData) => {
            drawBeamSectionAdjacentSlabDimensions(
                dxf,
                sideData,
                sideData.side === "left" ? left : right,
                bottom,
                top,
                {
                    dimensionSide: sideData.side,
                    beamHeightMeters: beam.h
                }
            );
        });
    } else {
        addVerticalDimension(dxf, "COTAS_SECCION", left - 0.35 - SECTION_DETAIL_LEFT_DIMENSION_LEFT_SHIFT, bottom, top, beam.h, left, beamSectionDimensionOptions);
    }
    if (detail?.detailContext === "standalone") {
        addDimension(dxf, "COTAS_SECCION", left, stirrupExteriorLeft, top + 0.18, coverSideMeters, top, beamSectionDimensionOptions);
    }

    addText(dxf, "SECCION_TEXTO", left, coverTextY, coverLabel, BEAM_SECTION_TEXT_HEIGHT);
    // When a pórtico-cut preference separates the sections by a reinforcement
    // family, that family must be documented in the representative cut itself.
    // Otherwise, keep the compact cross-reference to the pórtico elevation.
    const topSteelSectionLabel = isFrameBeamSection
        ? (showFrameLongitudinalReinforcement
            ? `${sectionSpec.topLabel || formatRebar(beam.topRebar)}`
            : "VER PÓRTICOS")
        : `${sectionSpec.topLabel || formatRebar(beam.topRebar)}`;
    const bottomSteelSectionLabel = isFrameBeamSection
        ? (showFrameLongitudinalReinforcement
            ? `${sectionSpec.bottomLabel || formatRebar(beam.botRebar)}`
            : "VER PÓRTICOS")
        : `${sectionSpec.bottomLabel || formatRebar(beam.botRebar)}`;
    const stirrupSectionLabel = isFrameBeamSection
        ? (showFrameTransverseReinforcement
            ? formatFrameElevationStirrupLabel(
                sectionSpec.transverseRebar || getBeamTransverseRebarForZone(beam, detail.zone || "mid", beam.stirrups),
                DEFAULT_BEAM_STIRRUP_SPACING
            )
            : "EST. VER PÓRTICOS")
        : (sectionSpec.stirrupLabel || formatDxfBeamStirrupLabel(getBeamTransverseRebarForZone(beam, detail.zone || "mid", beam.stirrups), DEFAULT_BEAM_STIRRUP_SPACING));
    drawSideLeaderText(
        dxf,
        "TEXTO_ACERO",
        topSteelSectionLabel,
        steelLabelX - BEAM_SECTION_TOP_STEEL_LABEL_LEFT_SHIFT
            - (isStandaloneBeamSection ? STANDALONE_BEAM_SECTION_TOP_STEEL_LABEL_LEFT_SHIFT : 0),
        top + 0.18 - BEAM_SECTION_TOP_STEEL_LABEL_DOWN_SHIFT
            - (isFrameBeamSection ? FRAME_BEAM_SECTION_TOP_STEEL_LABEL_DOWN_SHIFT : 0)
            + (isStandaloneBeamSection ? STANDALONE_BEAM_SECTION_TOP_STEEL_LABEL_UP_SHIFT : 0),
        topSteelTarget.x,
        topSteelTarget.y,
        BEAM_SECTION_TEXT_HEIGHT,
        "above"
    );
    const bottomSteelLabelX = steelLabelX + BEAM_SECTION_BOTTOM_STEEL_LABEL_RIGHT_SHIFT
        - (isFrameBeamSection ? FRAME_BEAM_SECTION_BOTTOM_STEEL_LABEL_LEFT_SHIFT : 0)
        - (isStandaloneBeamSection ? STANDALONE_BEAM_SECTION_BOTTOM_STEEL_LABEL_LEFT_SHIFT : 0);
    const bottomSteelLabelY = bottom - 0.18 + BEAM_SECTION_BOTTOM_STEEL_LABEL_UP_SHIFT
        + (isFrameBeamSection ? FRAME_BEAM_SECTION_BOTTOM_STEEL_LABEL_UP_SHIFT : 0)
        + (isStandaloneBeamSection ? STANDALONE_BEAM_SECTION_BOTTOM_STEEL_LABEL_UP_SHIFT : 0);
    drawSideLeaderText(
        dxf,
        "TEXTO_ACERO",
        bottomSteelSectionLabel,
        bottomSteelLabelX,
        bottomSteelLabelY,
        bottomSteelTarget.x,
        bottomSteelTarget.y,
        BEAM_SECTION_TEXT_HEIGHT,
        "below"
    );
    drawSideLeaderText(dxf, "TEXTO_ESTRIBOS", stirrupSectionLabel, stirrupLabelX, sideLabelMidY, stirrupTarget.x, stirrupTarget.y, BEAM_SECTION_TEXT_HEIGHT, "below");
    const sectionMarkerTag = normalizeTextValue(tag) || normalizeTextValue(beam?.name) || "A";
    const beamDetailName = normalizeTextValue(detail?.detailBeamName || beam?.displayName || beam?.name) || sectionMarkerTag;
    const standaloneSectionNumber = Math.max(
        1,
        Math.floor(parseNumberOrFallback(detail?.sectionNumber, 1))
    );
    drawDetailTitleMarker(
        dxf,
        markerCenterX,
        markerCenterY,
        isStandaloneBeamSection ? "SV" : sectionMarkerTag,
        "E-00",
        isStandaloneBeamSection
            ? `SECCIÓN ${standaloneSectionNumber} DE VIGA ${beamDetailName}`
            : `SECCIÓN ${sectionMarkerTag}`,
        {
            diameter: BEAM_SECTION_TITLE_MARKER_DIAMETER,
            rightLineLength: BEAM_SECTION_TITLE_LINE_LENGTH,
            internalTextHeight: BEAM_SECTION_TITLE_INTERNAL_TEXT_HEIGHT,
            externalTextHeight: BEAM_SECTION_TITLE_EXTERNAL_TEXT_HEIGHT,
            titleOffsetX: 0.10 - BEAM_SECTION_TITLE_TEXT_LEFT_SHIFT,
            titleOffsetY: 0.08 - BEAM_SECTION_TITLE_TEXT_DOWN_SHIFT
        }
    );
}

function getStandaloneBeamElevationSupports(level, beam) {
    if (!level || !beam) return [];
    const axisType = getBeamLocalAxisType(beam);
    if (axisType === "o") return [];
    const axisValue = axisType === "x" ? parseNumberOrFallback(beam?.x1, Number.NaN) : parseNumberOrFallback(beam?.y1, Number.NaN);
    if (!Number.isFinite(axisValue)) return [];
    const supports = getFrameSupportEntries(level, axisType, axisValue, 0.10);
    const bounds = getBeamBoundsForFrame(beam, axisType);
    return [bounds.start, bounds.end]
        .map((position) => ({ support: getFrameSupportAtBeamEndpoint(supports, position, 0.12), position }))
        .filter(({ support }) => Boolean(support));
}

function getStandaloneBeamElevationSegments(detail = {}) {
    const supplied = Array.isArray(detail?.beamSegments) ? detail.beamSegments : [];
    if (supplied.length) {
        return supplied
            .filter((segment) => segment?.beam)
            .slice()
            .sort((left, right) => left.start - right.start || left.end - right.end);
    }
    const beam = detail?.beam || {};
    const axisType = detail?.axisType || getBeamLocalAxisType(beam);
    return [{ beam, ...getBeamBoundsForFrame(beam, axisType) }];
}

function getStandaloneBeamDetailSupportEntries(level, detail, segments = []) {
    const axisType = detail?.axisType || getBeamLocalAxisType(detail?.beam || {});
    if (!level || !segments.length || (axisType !== "x" && axisType !== "y" && axisType !== "o")) {
        return [];
    }
    const start = Math.min(...segments.map((segment) => segment.start));
    const end = Math.max(...segments.map((segment) => segment.end));
    const axisValue = Number.isFinite(detail?.axisValue)
        ? detail.axisValue
        : (axisType === "x" ? detail?.beam?.x1 : detail?.beam?.y1);
    return getFrameSupportEntries(level, axisType, axisValue, 0.10)
        .filter((support) => support.position >= start - Math.max(support.width || 0, 0.1)
            && support.position <= end + Math.max(support.width || 0, 0.1));
}


const STANDALONE_BEAM_SUPPORT_DISPLAY_HEIGHT = 0.40;

function getStandaloneBeamBoundarySupport(supports = [], boundaryPosition, tolerance = 0.12) {
    let closestSupport = null;
    let closestDistance = Infinity;

    (Array.isArray(supports) ? supports : []).forEach((support) => {
        const position = parseNumberOrFallback(support?.position, Number.NaN);
        const width = parsePositiveNumberOrFallback(support?.width, 0, 0);
        if (!Number.isFinite(position) || !(width > EDGE_TOLERANCE)) {
            return;
        }

        const distance = Math.abs(position - boundaryPosition);
        const allowedDistance = Math.max(parsePositiveNumberOrFallback(tolerance, 0.12, 0.01), width / 2 + 0.02);
        if (distance <= allowedDistance && distance < closestDistance) {
            closestSupport = support;
            closestDistance = distance;
        }
    });

    return closestSupport;
}

function getStandaloneBeamSupportDisplayRect(support, chainStart, originLeft, beamFaceY, placement = "below") {
    const position = parseNumberOrFallback(support?.position, Number.NaN);
    const width = parsePositiveNumberOrFallback(support?.width, 0, 0);
    const resolvedBeamFaceY = typeof beamFaceY === "function" ? beamFaceY(support) : beamFaceY;
    if (!Number.isFinite(position) || !(width > EDGE_TOLERANCE) || !Number.isFinite(resolvedBeamFaceY)) {
        return null;
    }

    const supportLeft = originLeft + (position - chainStart) - width / 2;
    const supportBottom = placement === "above"
        ? resolvedBeamFaceY
        : resolvedBeamFaceY - STANDALONE_BEAM_SUPPORT_DISPLAY_HEIGHT;

    return {
        x1: supportLeft,
        y1: supportBottom,
        x2: supportLeft + width,
        y2: supportBottom + STANDALONE_BEAM_SUPPORT_DISPLAY_HEIGHT
    };
}

function drawStandaloneBeamSupportContinuitySymbols(dxf, rect, placement = "below") {
    const left = Math.min(parseNumberOrFallback(rect?.x1, Number.NaN), parseNumberOrFallback(rect?.x2, Number.NaN));
    const right = Math.max(parseNumberOrFallback(rect?.x1, Number.NaN), parseNumberOrFallback(rect?.x2, Number.NaN));
    const bottom = Math.min(parseNumberOrFallback(rect?.y1, Number.NaN), parseNumberOrFallback(rect?.y2, Number.NaN));
    const top = Math.max(parseNumberOrFallback(rect?.y1, Number.NaN), parseNumberOrFallback(rect?.y2, Number.NaN));
    const width = right - left;
    if (!Number.isFinite(left) || !Number.isFinite(right) || !Number.isFinite(bottom) || !Number.isFinite(top) || !(width > EDGE_TOLERANCE)) {
        return;
    }

    const symbolY = placement === "above" ? top : bottom;
    const symbolStartX = left - 0.10;
    const symbolWidth = width + 0.20;
    // Keep the break readable on wide standalone-beam cuts without letting
    // its downward tooth intrude more than 0.20 m into the detail.
    const zigzagAmplitude = Math.min(0.15 * symbolWidth, 0.20);
    const localPoints = [
        { u: 0.00 * symbolWidth, v: 0 },
        { u: 0.45 * symbolWidth, v: 0 },
        { u: 0.50 * symbolWidth, v: zigzagAmplitude },
        { u: 0.50 * symbolWidth, v: -zigzagAmplitude },
        { u: 0.55 * symbolWidth, v: 0 },
        { u: 1.00 * symbolWidth, v: 0 }
    ];
    const worldPoints = localPoints.map((point) => ({
        x: symbolStartX + point.u,
        y: symbolY + point.v
    }));

    for (let index = 0; index < worldPoints.length - 1; index += 1) {
        const start = worldPoints[index];
        const end = worldPoints[index + 1];
        addLine(dxf, "CONTINUIDAD_SIMBOLO", start.x, start.y, end.x, end.y);
    }
}

function isStandaloneBeamStirrupBlockedAtX(x, supportRects = [], tolerance = EDGE_TOLERANCE) {
    if (!Number.isFinite(x)) {
        return false;
    }

    const safeTolerance = Math.max(Number.isFinite(tolerance) ? tolerance : EDGE_TOLERANCE, 1e-6);
    return getFrameClipRectangles(supportRects).some((rect) => (
        x >= rect.x1 - safeTolerance && x <= rect.x2 + safeTolerance
    ));
}

function mergeStandaloneBeamSupportRects(rects = [], tolerance = 0.02) {
    const safeTolerance = Math.max(Number.isFinite(tolerance) ? tolerance : 0.02, 0);
    const normalizedRects = (Array.isArray(rects) ? rects : [])
        .map((rect) => ({
            x1: Math.min(parseNumberOrFallback(rect?.x1, Number.NaN), parseNumberOrFallback(rect?.x2, Number.NaN)),
            x2: Math.max(parseNumberOrFallback(rect?.x1, Number.NaN), parseNumberOrFallback(rect?.x2, Number.NaN)),
            y1: Math.min(parseNumberOrFallback(rect?.y1, Number.NaN), parseNumberOrFallback(rect?.y2, Number.NaN)),
            y2: Math.max(parseNumberOrFallback(rect?.y1, Number.NaN), parseNumberOrFallback(rect?.y2, Number.NaN))
        }))
        .filter((rect) => Number.isFinite(rect.x1) && Number.isFinite(rect.x2) && rect.x2 > rect.x1 + EDGE_TOLERANCE)
        .sort((left, right) => left.x1 - right.x1 || left.x2 - right.x2);

    const mergedRects = [];
    normalizedRects.forEach((rect) => {
        const currentRect = mergedRects[mergedRects.length - 1];
        if (currentRect && rect.x1 <= currentRect.x2 + safeTolerance) {
            currentRect.x2 = Math.max(currentRect.x2, rect.x2);
            currentRect.y1 = Math.min(currentRect.y1, rect.y1);
            currentRect.y2 = Math.max(currentRect.y2, rect.y2);
            return;
        }
        mergedRects.push({ ...rect });
    });

    return mergedRects.map((rect) => ({
        ...rect,
        width: rect.x2 - rect.x1
    }));
}

function getStandaloneBeamMainBottomRebarBounds(topBarStartX, topBarEndX) {
    const start = parseNumberOrFallback(topBarStartX, Number.NaN);
    const end = parseNumberOrFallback(topBarEndX, Number.NaN);
    if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start + EDGE_TOLERANCE) {
        return { startX: start, endX: end };
    }

    const maximumEndShortening = Math.max(
        (end - start - STANDALONE_BEAM_BOTTOM_REBAR_MIN_DRAWN_LENGTH) / 2,
        0
    );
    const endShortening = Math.min(
        STANDALONE_BEAM_BOTTOM_REBAR_END_SHORTENING,
        maximumEndShortening
    );
    return {
        startX: start + endShortening,
        endX: end - endShortening
    };
}

function getStandaloneBeamInteriorSupportDimensionBounds({
    startPosition,
    endPosition,
    supports = [],
    chainStart = 0,
    originLeft = 0
} = {}) {
    const start = parseNumberOrFallback(startPosition, Number.NaN);
    const end = parseNumberOrFallback(endPosition, Number.NaN);
    if (!Number.isFinite(start) || !Number.isFinite(end) || end < start - EDGE_TOLERANCE) {
        return null;
    }

    const startSupport = getStandaloneBeamBoundarySupport(supports, start);
    const endSupport = getStandaloneBeamBoundarySupport(supports, end);
    const modelStartX = originLeft + (start - chainStart);
    const modelEndX = originLeft + (end - chainStart);
    // A beam span is dimensioned to the support face facing the beam, not to
    // the support centerline.  This preserves the original coordinate when
    // a support cannot be resolved at either endpoint.
    const startX = startSupport
        ? originLeft + (startSupport.position - chainStart) + startSupport.width / 2
        : modelStartX;
    const endX = endSupport
        ? originLeft + (endSupport.position - chainStart) - endSupport.width / 2
        : modelEndX;

    // Extremely short or overlapping supports can leave no physical clear
    // span.  In that exceptional case retain the model endpoints rather than
    // emitting a reversed dimension entity.
    if (endX < startX - EDGE_TOLERANCE) {
        return {
            startX: modelStartX,
            endX: modelEndX,
            length: Math.max(end - start, 0)
        };
    }

    return {
        startX,
        endX,
        length: Math.max(endX - startX, 0)
    };
}

function getStandaloneBeamSupportDimensionSpans(supports = [], chainStart = 0, originLeft = 0) {
    const rawRects = (Array.isArray(supports) ? supports : []).map((support) => {
        const position = parseNumberOrFallback(support?.position, Number.NaN);
        const width = parsePositiveNumberOrFallback(support?.width, 0, 0);
        if (!Number.isFinite(position) || !(width > EDGE_TOLERANCE)) {
            return null;
        }

        const x1 = originLeft + (position - chainStart) - width / 2;
        return {
            x1,
            x2: x1 + width,
            y1: 0,
            y2: 0
        };
    }).filter(Boolean);

    return mergeStandaloneBeamSupportRects(rawRects).map((rect) => ({
        x1: rect.x1,
        x2: rect.x2,
        width: rect.width
    }));
}

function drawStandaloneBeamSupportSegments(dxf, supports = [], chainStart, originLeft, beamBottom, beamTop, beamRects = []) {
    const normalizedSupports = Array.isArray(supports) ? supports : [];
    const lowerRects = [];
    const upperRects = [];

    normalizedSupports.forEach((support) => {
        const lowerRect = getStandaloneBeamSupportDisplayRect(support, chainStart, originLeft, beamBottom, "below");
        const upperRect = getStandaloneBeamSupportDisplayRect(support, chainStart, originLeft, beamTop, "above");
        const layer = getFrameElevationConcreteLayer(support?.layer || "CONCRETO_COLUMNAS");
        const skipEdges = support?.kind === "wall"
            ? getFrameWallTerminalSkipEdges(support, normalizedSupports, 0.10)
            : (Array.isArray(support?.hiddenEdges) ? support.hiddenEdges : []);
        const lowerSkipEdges = Array.from(new Set([...skipEdges, "bottom"]));
        const upperSkipEdges = Array.from(new Set([...skipEdges, "top"]));

        if (lowerRect) {
            drawFrameSupportConcreteRectangle(
                dxf,
                layer,
                lowerRect.x1,
                lowerRect.y1,
                lowerRect.x2 - lowerRect.x1,
                lowerRect.y2 - lowerRect.y1,
                {
                    beamRectsAbove: beamRects,
                    beamContactRectsAbove: beamRects,
                    skipEdges: lowerSkipEdges
                }
            );
            lowerRects.push(lowerRect);
        }

        if (upperRect) {
            drawFrameSupportConcreteRectangle(
                dxf,
                layer,
                upperRect.x1,
                upperRect.y1,
                upperRect.x2 - upperRect.x1,
                upperRect.y2 - upperRect.y1,
                {
                    beamRectsBelow: beamRects,
                    beamContactRectsBelow: beamRects,
                    skipEdges: upperSkipEdges
                }
            );
            upperRects.push(upperRect);
        }
    });

    mergeStandaloneBeamSupportRects(lowerRects).forEach((rect) => {
        drawStandaloneBeamSupportContinuitySymbols(dxf, rect, "below");
    });
    mergeStandaloneBeamSupportRects(upperRects).forEach((rect) => {
        drawStandaloneBeamSupportContinuitySymbols(dxf, rect, "above");
    });
}

function drawContinuousSteelBeamElevationDetail(dxf, detail, originX, originY) {
    const segments = getStandaloneBeamElevationSegments(detail);
    if (!segments.length) {
        return;
    }

    const chainStart = Number.isFinite(detail?.chainStart)
        ? detail.chainStart
        : Math.min(...segments.map((segment) => segment.start));
    const chainEnd = Number.isFinite(detail?.chainEnd)
        ? detail.chainEnd
        : Math.max(...segments.map((segment) => segment.end));
    const left = originX + 0.45;
    const top = originY - 1.05;
    const overallRight = left + Math.max(chainEnd - chainStart, 0.6);
    const deepestProfile = Math.max(...segments.map((segment) => getDxfSteelProfileDepth(getDxfSteelProfileForBeam(segment?.beam || {}), segment?.beam || {})), 0.01);
    const bottom = top - deepestProfile;
    const displayName = normalizeTextValue(detail?.displayName || getBeamDetailBaseExportName(segments[0]?.beam || {}));

    drawBeamDetailNameMarker(dxf, left + 0.15, bottom - 1.35, displayName, "E-00");

    segments.forEach((segment) => {
        const beam = segment?.beam || {};
        const profile = getDxfSteelProfileForBeam(beam);
        const profileDepth = Math.max(getDxfSteelProfileDepth(profile, beam), 0.01);
        const segmentLeft = left + (segment.start - chainStart);
        const segmentRight = left + (segment.end - chainStart);
        const segmentBottom = top - profileDepth;
        const profileParts = getDxfWideFlangeProfileDrawingParts(profile, 1, profileDepth);
        const topFlangeBottomY = segmentBottom + profileParts.safeHeight - profileParts.topT;
        const bottomFlangeTopY = segmentBottom + profileParts.botT;
        const profileName = normalizeTextValue(profile?.name || beam?.sourceSection || beam?.name || "PERFIL W");

        addRectangle(dxf, "PERFILES_METALICOS", segmentLeft, segmentBottom, Math.max(segmentRight - segmentLeft, 0.01), profileDepth);
        addLine(dxf, "SECCION_CORTE", segmentLeft, topFlangeBottomY, segmentRight, topFlangeBottomY);
        addLine(dxf, "SECCION_CORTE", segmentLeft, bottomFlangeTopY, segmentRight, bottomFlangeTopY);
        addVerticalDimension(dxf, "COTAS_SECCION", segmentRight + 0.35, segmentBottom, top, profileDepth, segmentRight);
        addCenteredText(dxf, "SECCION_TEXTO", (segmentLeft + segmentRight) / 2, top + 0.36, profileName, 0.14);
    });

    addDimension(dxf, "COTAS_SECCION", left, overallRight, bottom - 0.72, Math.max(chainEnd - chainStart, 0.6).toFixed(2), bottom);
}

function drawContinuousStandaloneBeamElevationDetail(dxf, detail, originX, originY, detailSize, sectionEntries = [], options = {}) {
    const segments = getStandaloneBeamElevationSegments(detail);
    if (!segments.length) return;
    if (segments.every((segment) => isDxfSteelBeam(segment?.beam || {}))) {
        drawContinuousSteelBeamElevationDetail(dxf, detail, originX, originY);
        return;
    }
    const level = findLevelByName(detail?.levelName);
    const chainStart = Number.isFinite(detail?.chainStart) ? detail.chainStart : Math.min(...segments.map((segment) => segment.start));
    const chainEnd = Number.isFinite(detail?.chainEnd) ? detail.chainEnd : Math.max(...segments.map((segment) => segment.end));
    const span = Math.max(chainEnd - chainStart, 0.6);
    const left = originX + 0.45;
    const right = left + span;
    const elevationTop = originY - 1.05;
    const axisType = detail?.axisType || getBeamLocalAxisType(detail?.beam || segments[0]?.beam || {});
    const supports = getStandaloneBeamDetailSupportEntries(level, detail, segments);
    const additionalRebarDimensionBreakIntervals = getStandaloneBeamSupportDimensionSpans(supports, chainStart, left)
        .map((supportSpan) => ({ start: supportSpan.x1, end: supportSpan.x2 }));
    const leftBoundarySupport = getStandaloneBeamBoundarySupport(supports, chainStart);
    const rightBoundarySupport = getStandaloneBeamBoundarySupport(supports, chainEnd);
    const beamConcreteLeft = leftBoundarySupport
        ? left + (leftBoundarySupport.position - chainStart) - leftBoundarySupport.width / 2
        : left;
    const beamConcreteRight = rightBoundarySupport
        ? left + (rightBoundarySupport.position - chainStart) + rightBoundarySupport.width / 2
        : right;
    const beamRects = segments.map((segment, index) => {
        const beamHeight = Math.max(parsePositiveNumberOrFallback(segment?.beam?.h, 0.01, 0.01), 0.01);
        const segmentLeft = index === 0 ? beamConcreteLeft : left + (segment.start - chainStart);
        const segmentRight = index === segments.length - 1 ? beamConcreteRight : left + (segment.end - chainStart);
        return {
            x1: segmentLeft,
            x2: segmentRight,
            y1: elevationTop - beamHeight,
            y2: elevationTop
        };
    });
    const deepestBeam = segments.reduce((maximum, segment) => Math.max(maximum, parsePositiveNumberOrFallback(segment?.beam?.h, 0, 0)), 0.01);
    const getBeamBottomAtSupport = (support) => {
        const position = parseNumberOrFallback(support?.position, Number.NaN);
        const width = parsePositiveNumberOrFallback(support?.width, 0, 0);
        if (!Number.isFinite(position) || !(width > EDGE_TOLERANCE)) {
            return elevationTop - deepestBeam;
        }
        const supportLeft = left + (position - chainStart) - width / 2;
        const supportRight = supportLeft + width;
        const overlappingBottoms = beamRects
            .filter((beamRect) => beamRect.x2 >= supportLeft - EDGE_TOLERANCE && beamRect.x1 <= supportRight + EDGE_TOLERANCE)
            .map((beamRect) => beamRect.y1);
        return overlappingBottoms.length ? Math.min(...overlappingBottoms) : (elevationTop - deepestBeam);
    };
    const lowerSupportRects = supports
        .map((support) => getStandaloneBeamSupportDisplayRect(support, chainStart, left, getBeamBottomAtSupport, "below"))
        .filter(Boolean);
    const upperSupportRects = supports
        .map((support) => getStandaloneBeamSupportDisplayRect(support, chainStart, left, elevationTop, "above"))
        .filter(Boolean);
    const deepestSupport = supports.length ? STANDALONE_BEAM_SUPPORT_DISPLAY_HEIGHT : 0;
    const markerCenterY = elevationTop - deepestBeam - Math.max(1.35, deepestSupport + 0.42);
    const beamDetailPreferences = normalizeStandaloneBeamDetailDrawingPreferences(
        options?.beamDetailPreferences ?? options?.drawingPreferences?.beamDetail ?? options?.drawingPreferences
    );
    const beamSpanDimensionOffsetFromBottom = normalizeStandaloneBeamDetailAnnotationOffsetFromBottom(
        beamDetailPreferences.beamSpanDimensionOffsetFromBottom,
        STANDALONE_BEAM_DETAIL_SPAN_DIMENSION_OFFSET_FROM_BOTTOM_DEFAULT
    );
    const stirrupDetailOffsetFromBottom = normalizeStandaloneBeamDetailAnnotationOffsetFromBottom(
        beamDetailPreferences.stirrupDetailOffsetFromBottom,
        STANDALONE_BEAM_DETAIL_STIRRUP_DETAIL_OFFSET_FROM_BOTTOM_DEFAULT
    );

    drawBeamDetailNameMarker(dxf, beamConcreteLeft + 0.15, markerCenterY, detail?.displayName || getBeamDetailBaseExportName(segments[0].beam), "E-00");

    drawStandaloneBeamSupportSegments(dxf, supports, chainStart, left, getBeamBottomAtSupport, elevationTop, beamRects);

    // Draw the principal longitudinal steel as physical runs instead of one
    // independent bar pair per imported span.  This mirrors the frame-detail
    // convention: the upper bar travels across the complete named beam, while
    // the lower bar continues through every consecutive run with the same
    // peralte.  Internal supports therefore no longer create artificial hooks
    // or gaps between spans that are geometrically one beam.
    const getLongitudinalGeometry = (segment) => {
        const beam = segment?.beam || {};
        const beamHeight = Math.max(parsePositiveNumberOrFallback(beam?.h, 0.01, 0.01), 0.01);
        const transverseRebar = ensureTransverseRebar(beam?.stirrups, DEFAULT_BEAM_STIRRUP_SPACING);
        const topCover = normalizeBeamCover(beam?.coverTop, DRAWING_COVER);
        const bottomCover = normalizeBeamCover(beam?.coverBottom, DRAWING_COVER);
        const sideCover = getBeamSideCover(topCover, bottomCover);
        const maxFaceInset = Math.max(beamHeight / 2 - 0.01, 0.01);
        return {
            beam,
            beamHeight,
            transverseRebar,
            topInset: Math.min(getStandaloneBeamLongitudinalBarCenterlineInset(topCover, transverseRebar.d, beam?.topRebar?.d), maxFaceInset),
            bottomInset: Math.min(getStandaloneBeamLongitudinalBarCenterlineInset(bottomCover, transverseRebar.d, beam?.botRebar?.d), maxFaceInset),
            sideInset: Math.min(
                getStandaloneBeamLongitudinalBarCenterlineInset(sideCover, transverseRebar.d, beam?.topRebar?.d),
                Math.max((segment.end - segment.start) / 2 - 0.02, 0.02)
            )
        };
    };
    const longitudinalGeometryByBeamId = new Map();
    const geometryBySegment = new Map();
    segments.forEach((segment) => {
        const geometry = getLongitudinalGeometry(segment);
        geometryBySegment.set(segment, geometry);
        if (geometry.beam?.id) {
            longitudinalGeometryByBeamId.set(geometry.beam.id, geometry);
        }
    });

    const firstSegment = segments[0];
    const lastSegment = segments[segments.length - 1];
    const firstGeometry = geometryBySegment.get(firstSegment) || getLongitudinalGeometry(firstSegment);
    const lastGeometry = geometryBySegment.get(lastSegment) || getLongitudinalGeometry(lastSegment);
    const commonTopInset = Math.max(...segments.map((segment) => (geometryBySegment.get(segment) || getLongitudinalGeometry(segment)).topInset));
    const continuousTopBarY = elevationTop - commonTopInset;
    const topBarStartX = beamConcreteLeft + firstGeometry.sideInset;
    const topBarEndX = beamConcreteRight - lastGeometry.sideInset;
    const topHookLevel = elevationTop - deepestBeam * 0.68;

    if (topBarEndX > topBarStartX + EDGE_TOLERANCE) {
        drawSmartRebar(
            dxf,
            "ACERO_SUPERIOR",
            topBarStartX,
            topBarEndX,
            continuousTopBarY,
            continuousTopBarY - 0.028,
            topHookLevel,
            true,
            true,
            {
                leftHookInnerOffset: 0.05,
                rightHookInnerOffset: 0.05,
                hookLegAtBarExtents: true,
                capStyle: "semicircle",
                fillStyle: "hatch",
                hatchLayer: FRAME_LONGITUDINAL_HATCH_LAYER,
                hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
                hatchPatternScale: FRAME_REBAR_HATCH_SCALE
            }
        );
    }

    const bottomBarYByBeamId = new Map();
    const depthRuns = groupContiguousBeamDepthRuns(segments);
    // Show one vertical peralte dimension for each contiguous depth run.  A
    // beam with constant depth therefore has one dimension total; when the
    // depth changes, each new run receives its own representative dimension.
    const depthDimensionSegments = new Set(depthRuns
        .map((run) => {
            const members = Array.isArray(run?.members) ? run.members : [];
            return members.length ? members[Math.floor(members.length / 2)] : null;
        })
        .filter(Boolean));
    const depthDevelopmentPlan = getBeamDepthTransitionDevelopmentPlan(depthRuns, {
        exportConfig: options.exportConfig,
        supports
    });
    depthRuns.forEach((run) => {
        const runMembers = Array.isArray(run?.members) ? run.members : [];
        if (!runMembers.length) return;
        const developmentExtension = depthDevelopmentPlan.runExtensions.get(run) || {};
        const developmentExtensionDetails = depthDevelopmentPlan.runExtensionDetails?.get(run) || {};
        const runFirstSegment = runMembers[0];
        const runLastSegment = runMembers[runMembers.length - 1];
        const runFirstGeometry = geometryBySegment.get(runFirstSegment) || getLongitudinalGeometry(runFirstSegment);
        const runLastGeometry = geometryBySegment.get(runLastSegment) || getLongitudinalGeometry(runLastSegment);
        const runBottomInset = Math.max(...runMembers.map((member) => (geometryBySegment.get(member) || getLongitudinalGeometry(member)).bottomInset));
        const runElevationBottom = elevationTop - run.depth;
        const runBottomBarY = runElevationBottom + runBottomInset;
        const runStartX = runFirstSegment === firstSegment
            ? beamConcreteLeft + runFirstGeometry.sideInset
            : left + (runFirstSegment.start - chainStart) + runFirstGeometry.sideInset;
        const runEndX = runLastSegment === lastSegment
            ? beamConcreteRight - runLastGeometry.sideInset
            : left + (runLastSegment.end - chainStart) - runLastGeometry.sideInset;
        const runStartExtension = runFirstSegment === firstSegment ? 0 : Math.max(parseNumberOrFallback(developmentExtension.start, 0), 0);
        const runEndExtension = runLastSegment === lastSegment ? 0 : Math.max(parseNumberOrFallback(developmentExtension.end, 0), 0);
        const runStartDimensionLength = Math.max(
            parseNumberOrFallback(developmentExtensionDetails.start?.dimensionLength, runStartExtension),
            0
        );
        const runEndDimensionLength = Math.max(
            parseNumberOrFallback(developmentExtensionDetails.end?.dimensionLength, runEndExtension),
            0
        );
        const runStartCriticalPosition = parseNumberOrFallback(
            developmentExtensionDetails.start?.criticalPosition,
            runFirstSegment.start
        );
        const runEndCriticalPosition = parseNumberOrFallback(
            developmentExtensionDetails.end?.criticalPosition,
            runLastSegment.end
        );
        const runStartBarEndPosition = parseNumberOrFallback(
            developmentExtensionDetails.start?.barEndPosition,
            runFirstSegment.start - runStartExtension
        );
        const runEndBarEndPosition = parseNumberOrFallback(
            developmentExtensionDetails.end?.barEndPosition,
            runLastSegment.end + runEndExtension
        );
        const hasRunStartDevelopment = runStartDimensionLength > EDGE_TOLERANCE;
        const hasRunEndDevelopment = runEndDimensionLength > EDGE_TOLERANCE;
        const runStartBoundaryX = left + (runFirstSegment.start - chainStart);
        const runEndBoundaryX = left + (runLastSegment.end - chainStart);
        const runStartCriticalX = left + (runStartCriticalPosition - chainStart);
        const runEndCriticalX = left + (runEndCriticalPosition - chainStart);
        const runStartBarEndX = left + (runStartBarEndPosition - chainStart);
        const runEndBarEndX = left + (runEndBarEndPosition - chainStart);

        const lowerBarBounds = getStandaloneBeamMainBottomRebarBounds(runStartX, runEndX);
        const lowerBarStartX = hasRunStartDevelopment
            ? runStartBarEndX
            : lowerBarBounds.startX;
        const lowerBarEndX = hasRunEndDevelopment
            ? runEndBarEndX
            : lowerBarBounds.endX;
        if (lowerBarEndX > lowerBarStartX + EDGE_TOLERANCE) {
            drawSmartRebar(
                dxf,
                "ACERO_INFERIOR",
                lowerBarStartX,
                lowerBarEndX,
                runBottomBarY,
                runBottomBarY + 0.028,
                elevationTop - Math.min(run.depth * 0.32, Math.max(run.depth - 0.04, 0.04)),
                !hasRunStartDevelopment,
                !hasRunEndDevelopment,
                {
                    leftHookInnerOffset: 0.10,
                    rightHookInnerOffset: 0.10,
                    hookLegAtBarExtents: true,
                    capStyle: "semicircle",
                    fillStyle: "hatch",
                    hatchLayer: FRAME_LONGITUDINAL_HATCH_LAYER,
                    hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
                    hatchPatternScale: FRAME_REBAR_HATCH_SCALE
                }
            );

            if (hasRunStartDevelopment) {
                drawDevelopmentInsertionDimension(dxf, {
                    x1: runStartBarEndX,
                    x2: runStartCriticalX,
                    dimensionY: runBottomBarY - 0.28,
                    originY: runBottomBarY,
                    length: runStartDimensionLength
                });
            }

            if (hasRunEndDevelopment) {
                drawDevelopmentInsertionDimension(dxf, {
                    x1: runEndCriticalX,
                    x2: runEndBarEndX,
                    dimensionY: runBottomBarY - 0.28,
                    originY: runBottomBarY,
                    length: runEndDimensionLength
                });
            }
        }

        runMembers.forEach((member) => {
            const memberBeamId = member?.beam?.id;
            if (memberBeamId) {
                bottomBarYByBeamId.set(memberBeamId, runBottomBarY);
            }
        });
    });

    segments.forEach((segment) => {
        const beam = segment.beam;
        const segmentStartX = left + (segment.start - chainStart);
        const segmentEndX = left + (segment.end - chainStart);
        const segmentSpan = Math.max(segmentEndX - segmentStartX, 0.01);
        const beamHeight = Math.max(parsePositiveNumberOrFallback(beam?.h, 0.01, 0.01), 0.01);
        const elevationBottom = elevationTop - beamHeight;
        const isFirst = segment === firstSegment;
        const isLast = segment === lastSegment;
        const segmentConcreteStartX = isFirst ? beamConcreteLeft : segmentStartX;
        const segmentConcreteEndX = isLast ? beamConcreteRight : segmentEndX;
        const segmentConcreteSpan = Math.max(segmentConcreteEndX - segmentConcreteStartX, 0.01);
        drawFrameBeamConcreteRectangle(dxf, "CONCRETO_VIGAS", segmentConcreteStartX, elevationBottom, segmentConcreteSpan, beamHeight, {
            bottomSupportRects: lowerSupportRects,
            topSupportRects: upperSupportRects,
            drawLeftEnd: isFirst,
            drawRightEnd: isLast,
            topLineStart: segmentConcreteStartX,
            topLineEnd: segmentConcreteEndX
        });

        const geometry = geometryBySegment.get(segment) || getLongitudinalGeometry(segment);
        const transverseRebar = geometry.transverseRebar;
        const maxFaceInset = Math.max(beamHeight / 2 - 0.01, 0.01);
        const topBarY = continuousTopBarY;
        const bottomBarY = bottomBarYByBeamId.get(beam?.id) ?? (elevationBottom + geometry.bottomInset);
        const stirrupTopY = elevationTop - Math.min(getStandaloneBeamStirrupCenterlineInset(normalizeBeamCover(beam?.coverTop, DRAWING_COVER), transverseRebar.d), maxFaceInset);
        const stirrupBottomY = elevationBottom + Math.min(getStandaloneBeamStirrupCenterlineInset(normalizeBeamCover(beam?.coverBottom, DRAWING_COVER), transverseRebar.d), maxFaceInset);
        const sideInset = geometry.sideInset;
        const bottomDevelopmentExtensions = depthDevelopmentPlan.beamExtensionsById.get(beam?.id) || { start: 0, end: 0 };

        const additionalSegments = buildBeamAdditionalRebarSegments(beam, {
            bodyStart: segmentConcreteStartX + sideInset,
            bodyEnd: segmentConcreteEndX - sideInset,
            anchorStart: segmentConcreteStartX + sideInset,
            anchorEnd: segmentConcreteEndX - sideInset,
            bottomDevelopmentStartExtension: bottomDevelopmentExtensions.start > EDGE_TOLERANCE
                ? bottomDevelopmentExtensions.start + sideInset
                : 0,
            bottomDevelopmentEndExtension: bottomDevelopmentExtensions.end > EDGE_TOLERANCE
                ? bottomDevelopmentExtensions.end + sideInset
                : 0,
            bottomDevelopmentStartDimensionLength: bottomDevelopmentExtensions.startDimensionLength,
            bottomDevelopmentEndDimensionLength: bottomDevelopmentExtensions.endDimensionLength,
            bottomDevelopmentStartCriticalX: Number.isFinite(bottomDevelopmentExtensions.startCriticalPosition)
                ? left + (bottomDevelopmentExtensions.startCriticalPosition - chainStart)
                : Number.NaN,
            bottomDevelopmentEndCriticalX: Number.isFinite(bottomDevelopmentExtensions.endCriticalPosition)
                ? left + (bottomDevelopmentExtensions.endCriticalPosition - chainStart)
                : Number.NaN,
            bottomDevelopmentStartBarEndX: Number.isFinite(bottomDevelopmentExtensions.startBarEndPosition)
                ? left + (bottomDevelopmentExtensions.startBarEndPosition - chainStart)
                : Number.NaN,
            bottomDevelopmentEndBarEndX: Number.isFinite(bottomDevelopmentExtensions.endBarEndPosition)
                ? left + (bottomDevelopmentExtensions.endBarEndPosition - chainStart)
                : Number.NaN,
            axisType
        }).map((additionalSegment) => ({
            ...additionalSegment,
            topLengthDimensionY: elevationTop + 0.25,
            topLengthDimensionOriginY: elevationTop,
            bottomLengthDimensionY: elevationBottom - 0.25,
            bottomLengthDimensionOriginY: elevationBottom,
            lengthDimensionY: elevationBottom - 0.25,
            lengthDimensionOriginY: elevationBottom
        }));
        drawBeamAdditionalRebarSegments(dxf, additionalSegments, {
            topZ1: topBarY + 0.08, topZ2: topBarY + 0.052, bottomZ1: bottomBarY + 0.08, bottomZ2: bottomBarY + 0.108,
            topHookLevel: elevationTop - beamHeight * 0.52, bottomHookLevel: elevationTop - beamHeight * 0.4,
            topLabelY: elevationTop + 0.15,
            bottomLabelY: elevationBottom - 0.15 + STANDALONE_BEAM_DETAIL_BOTTOM_STEEL_LABEL_UP_SHIFT,
            labelSize: 0.06,
            includeFill: true, fillStyle: "hatch", hatchLayer: FRAME_LONGITUDINAL_HATCH_LAYER, hatchPatternName: FRAME_REBAR_HATCH_PATTERN, hatchPatternScale: FRAME_REBAR_HATCH_SCALE,
            hookLegAtSegmentEnds: true,
            drawLengthDimensions: true,
            lengthDimensionBreakIntervals: additionalRebarDimensionBreakIntervals
        });

        const clearance = segmentSpan >= (STANDALONE_BEAM_TERMINAL_STIRRUP_CLEARANCE * 2) - EDGE_TOLERANCE
            ? STANDALONE_BEAM_TERMINAL_STIRRUP_CLEARANCE
            : segmentSpan / 2;
        const blockedSupportRects = [...lowerSupportRects, ...upperSupportRects];
        getMergedBeamTransverseRebarIntervals(beam, clearance, segmentSpan - clearance).forEach((interval) => {
            getMarkerPositions(Math.max(interval.start, clearance), Math.min(interval.end, segmentSpan - clearance), getDxfBeamStirrupSpacingMeters(interval.rebar.spacing), 0)
                .forEach((position) => {
                    const x = segmentStartX + position;
                    if (isStandaloneBeamStirrupBlockedAtX(x, blockedSupportRects)) {
                        return;
                    }
                    addFilledBarSegment(dxf, "ACERO_TRANSVERSAL", x, stirrupTopY, x, stirrupBottomY, DXF_REBAR_2D_RADIUS, DXF_REBAR_SOLID_COLOR, {
                        roundStart: true, roundEnd: true, capStyle: "semicircle", drawFlatCaps: false,
                        fillStyle: "hatch", hatchLayer: FRAME_STIRRUP_HATCH_LAYER, hatchPatternName: FRAME_REBAR_HATCH_PATTERN, hatchPatternScale: FRAME_REBAR_HATCH_SCALE
                    });
                });
        });

        const localCuts = sectionEntries.filter((entry) => entry?.parentDetailKey === detail?.detailKey
            && (entry?.beam === beam || (entry?.beam?.id && entry.beam.id === beam.id)));
        localCuts.forEach((entry) => {
            const cutOffset = Number.isFinite(entry.chainCutOffset)
                ? entry.chainCutOffset
                : (segment.start - chainStart) + entry.cutOffset;
            const cutX = left + cutOffset;
            if (isStandaloneBeamStirrupBlockedAtX(cutX, blockedSupportRects)) {
                return;
            }
            drawFrameSectionCutMarker(dxf, cutX, elevationTop, beamHeight, entry.tag);
        });

        const segmentDimension = getStandaloneBeamInteriorSupportDimensionBounds({
            startPosition: segment.start,
            endPosition: segment.end,
            supports,
            chainStart,
            originLeft: left
        });
        const dimensionStartX = segmentDimension?.startX ?? segmentStartX;
        const dimensionEndX = segmentDimension?.endX ?? segmentEndX;
        const dimensionLength = segmentDimension?.length ?? Math.max(segment.end - segment.start, 0);
        if (depthDimensionSegments.has(segment)) {
            addVerticalDimension(dxf, "COTAS_SECCION", segmentConcreteEndX + 0.35, elevationBottom, elevationTop, beam.h, segmentConcreteEndX);
        }
        drawLeaderText(dxf, "TEXTO_ACERO", formatRebar(beam.topRebar), segmentStartX + segmentSpan * 0.34, elevationTop + 0.15, segmentStartX + segmentSpan * 0.42, topBarY, 0.06, "above");
        drawLeaderText(dxf, "TEXTO_ACERO", formatRebar(beam.botRebar), segmentStartX + segmentSpan * 0.24 - STANDALONE_BEAM_DETAIL_BOTTOM_STEEL_LABEL_LEFT_SHIFT, elevationBottom - 0.15 + STANDALONE_BEAM_DETAIL_BOTTOM_STEEL_LABEL_UP_SHIFT, segmentStartX + segmentSpan * 0.34, bottomBarY, 0.06, "below");
        addDimension(dxf, "COTAS_SECCION", dimensionStartX, dimensionEndX, elevationBottom - beamSpanDimensionOffsetFromBottom, dimensionLength.toFixed(2), elevationBottom);
        addCenteredText(dxf, "TEXTO_ESTRIBOS", (dimensionStartX + dimensionEndX) / 2, elevationBottom - stirrupDetailOffsetFromBottom, formatDxfBeamStirrupLabel(getBeamDrawingTransverseRebarForZone(beam, "mid", beam.stirrups), DEFAULT_BEAM_STIRRUP_SPACING), 0.06);
    });

    getStandaloneBeamSupportDimensionSpans(supports, chainStart, left).forEach((spanData) => {
        addDimension(
            dxf,
            "COTAS_SECCION",
            spanData.x1,
            spanData.x2,
            elevationTop - deepestBeam - beamSpanDimensionOffsetFromBottom,
            spanData.width.toFixed(2),
            elevationTop - deepestBeam
        );
    });
}

function getBeamElevationDetailBoxSize(detail) {
    const segments = getStandaloneBeamElevationSegments(detail);
    const span = Math.max(
        Number.isFinite(detail?.chainEnd) && Number.isFinite(detail?.chainStart)
            ? detail.chainEnd - detail.chainStart
            : (segments.length ? Math.max(...segments.map((segment) => segment.end)) - Math.min(...segments.map((segment) => segment.start)) : getBeamSpanLength(detail?.beam)),
        0.6
    );
    const level = findLevelByName(detail?.levelName);
    const supportHeight = getStandaloneBeamDetailSupportEntries(level, detail, segments).length
        ? STANDALONE_BEAM_SUPPORT_DISPLAY_HEIGHT
        : 0;
    return { width: Math.max(span + 1.35, 3.0), height: Math.max(4.8, supportHeight + 2.55) };
}

function drawBeamElevationDetail(dxf, detail, originX, originY, detailSize, sectionEntries = [], options = {}) {
    const groupedSegments = getStandaloneBeamElevationSegments(detail);
    if (groupedSegments.length > 1) {
        drawContinuousStandaloneBeamElevationDetail(dxf, detail, originX, originY, detailSize, sectionEntries, options);
        return;
    }
    const beam = detail.beam;
    if (isDxfSteelBeam(beam)) {
        drawSteelBeamElevationDetail(dxf, detail, originX, originY, detailSize);
        return;
    }
    const beamDetailPreferences = normalizeStandaloneBeamDetailDrawingPreferences(
        options?.beamDetailPreferences
            ?? options?.drawingPreferences?.beamDetail
            ?? options?.drawingPreferences
    );
    const beamSpanDimensionOffsetFromBottom = normalizeStandaloneBeamDetailAnnotationOffsetFromBottom(
        beamDetailPreferences.beamSpanDimensionOffsetFromBottom,
        STANDALONE_BEAM_DETAIL_SPAN_DIMENSION_OFFSET_FROM_BOTTOM_DEFAULT
    );
    const stirrupDetailOffsetFromBottom = normalizeStandaloneBeamDetailAnnotationOffsetFromBottom(
        beamDetailPreferences.stirrupDetailOffsetFromBottom,
        STANDALONE_BEAM_DETAIL_STIRRUP_DETAIL_OFFSET_FROM_BOTTOM_DEFAULT
    );
    const span = Math.max(getBeamSpanLength(beam), 0.6);
    const level = findLevelByName(detail.levelName);
    const beamChain = getBeamContinuousChainForLevel(level, beam);
    const left = originX + 0.45;
    const elevationTop = originY - 1.05;
    // Standalone-beam elevations use actual model dimensions at 1:1.
    // The drawing box may be wider to reserve space for annotations, but the
    // concrete outline and reinforcement are never stretched to fill it.
    const beamHeight = Math.max(parsePositiveNumberOrFallback(beam.h, 0.01, 0.01), 0.01);
    const elevationBottom = elevationTop - beamHeight;
    const beamWidth = span;
    const right = left + beamWidth;
    const supportEntries = getStandaloneBeamElevationSupports(level, beam);
    const axisType = getBeamLocalAxisType(beam);
    const beamBounds = getBeamBoundsForFrame(beam, axisType);
    const supportModels = supportEntries.map((entry) => entry.support).filter(Boolean);
    const additionalRebarDimensionBreakIntervals = getStandaloneBeamSupportDimensionSpans(supportModels, beamBounds.start, left)
        .map((supportSpan) => ({ start: supportSpan.x1, end: supportSpan.x2 }));
    const leftBoundarySupport = getStandaloneBeamBoundarySupport(supportModels, beamBounds.start);
    const rightBoundarySupport = getStandaloneBeamBoundarySupport(supportModels, beamBounds.end);
    const beamConcreteLeft = leftBoundarySupport
        ? left + (leftBoundarySupport.position - beamBounds.start) - leftBoundarySupport.width / 2
        : left;
    const beamConcreteRight = rightBoundarySupport
        ? left + (rightBoundarySupport.position - beamBounds.start) + rightBoundarySupport.width / 2
        : right;
    const beamRect = { x1: beamConcreteLeft, y1: elevationBottom, x2: beamConcreteRight, y2: elevationTop };
    const lowerSupportRects = supportModels
        .map((support) => getStandaloneBeamSupportDisplayRect(support, beamBounds.start, left, elevationBottom, "below"))
        .filter(Boolean);
    const upperSupportRects = supportModels
        .map((support) => getStandaloneBeamSupportDisplayRect(support, beamBounds.start, left, elevationTop, "above"))
        .filter(Boolean);
    drawStandaloneBeamSupportSegments(dxf, supportModels, beamBounds.start, left, elevationBottom, elevationTop, [beamRect]);
    const transverseRebar = ensureTransverseRebar(beam?.stirrups, DEFAULT_BEAM_STIRRUP_SPACING);
    const topCover = normalizeBeamCover(beam?.coverTop, DRAWING_COVER);
    const bottomCover = normalizeBeamCover(beam?.coverBottom, DRAWING_COVER);
    const sideCover = getBeamSideCover(topCover, bottomCover);
    const topBarInset = getStandaloneBeamLongitudinalBarCenterlineInset(topCover, transverseRebar.d, beam?.topRebar?.d);
    const bottomBarInset = getStandaloneBeamLongitudinalBarCenterlineInset(bottomCover, transverseRebar.d, beam?.botRebar?.d);
    const stirrupTopInset = getStandaloneBeamStirrupCenterlineInset(topCover, transverseRebar.d);
    const stirrupBottomInset = getStandaloneBeamStirrupCenterlineInset(bottomCover, transverseRebar.d);
    const maximumFaceInset = Math.max(beamHeight / 2 - 0.01, 0.01);
    const topBarY = elevationTop - Math.min(topBarInset, maximumFaceInset);
    const bottomBarY = elevationBottom + Math.min(bottomBarInset, maximumFaceInset);
    const stirrupTopY = elevationTop - Math.min(stirrupTopInset, maximumFaceInset);
    const stirrupBottomY = elevationBottom + Math.min(stirrupBottomInset, maximumFaceInset);
    const longitudinalSideInset = Math.min(
        getStandaloneBeamLongitudinalBarCenterlineInset(sideCover, transverseRebar.d, beam?.topRebar?.d),
        Math.max(span / 2 - 0.02, 0.02)
    );
    const localCuts = sectionEntries.flatMap((entry) => {
        const memberCuts = Array.isArray(entry?.memberCuts) ? entry.memberCuts : [];
        if (memberCuts.length) {
            return memberCuts
                .filter((memberCut) => memberCut?.beam === beam)
                .map((memberCut) => ({ ...entry, cutOffset: memberCut.cutOffset }));
        }
        return entry?.beam === beam ? [entry] : [];
    });

    const markerCenterX = beamConcreteLeft + 0.15;
    const deepestSupport = supportModels.length ? STANDALONE_BEAM_SUPPORT_DISPLAY_HEIGHT : 0;
    const markerCenterY = elevationBottom - Math.max(1.35, deepestSupport + 0.42);

    drawBeamDetailNameMarker(
        dxf,
        markerCenterX,
        markerCenterY,
        detail?.displayName || detail?.beam?.displayName || beam.name || "",
        "E-00"
    );

    drawFrameBeamConcreteRectangle(dxf, "CONCRETO_VIGAS", beamConcreteLeft, elevationBottom, beamConcreteRight - beamConcreteLeft, beamHeight, {
        bottomSupportRects: lowerSupportRects,
        topSupportRects: upperSupportRects,
        topLineStart: beamConcreteLeft,
        topLineEnd: beamConcreteRight
    });

    const topMainBarStartX = beamConcreteLeft + longitudinalSideInset;
    const topMainBarEndX = beamConcreteRight - longitudinalSideInset;
    const bottomMainBarBounds = getStandaloneBeamMainBottomRebarBounds(topMainBarStartX, topMainBarEndX);

    drawSmartRebar(
        dxf,
        "ACERO_SUPERIOR",
        topMainBarStartX,
        topMainBarEndX,
        topBarY,
        topBarY - 0.028,
        elevationBottom + beamHeight * 0.32,
        true,
        true,
        {
            leftHookInnerOffset: 0.05,
            rightHookInnerOffset: 0.05,
            hookLegAtBarExtents: true,
            capStyle: "semicircle",
            fillStyle: "hatch",
            hatchLayer: FRAME_LONGITUDINAL_HATCH_LAYER,
            hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
            hatchPatternScale: FRAME_REBAR_HATCH_SCALE
        }
    );
    drawSmartRebar(
        dxf,
        "ACERO_INFERIOR",
        bottomMainBarBounds.startX,
        bottomMainBarBounds.endX,
        bottomBarY,
        bottomBarY + 0.028,
        elevationTop - beamHeight * 0.32,
        true,
        true,
        {
            leftHookInnerOffset: 0.10,
            rightHookInnerOffset: 0.10,
            hookLegAtBarExtents: true,
            capStyle: "semicircle",
            fillStyle: "hatch",
            hatchLayer: FRAME_LONGITUDINAL_HATCH_LAYER,
            hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
            hatchPatternScale: FRAME_REBAR_HATCH_SCALE
        }
    );

    const additionalSegments = buildBeamAdditionalRebarSegments(beam, {
        bodyStart: beamConcreteLeft + longitudinalSideInset,
        bodyEnd: beamConcreteRight - longitudinalSideInset,
        anchorStart: beamConcreteLeft + longitudinalSideInset,
        anchorEnd: beamConcreteRight - longitudinalSideInset,
        axisType: beamChain?.axisType ?? null,
        chain: beamChain
    }).map((additionalSegment) => ({
        ...additionalSegment,
        topLengthDimensionY: elevationTop + 0.25,
        topLengthDimensionOriginY: elevationTop,
        bottomLengthDimensionY: elevationBottom - 0.25,
        bottomLengthDimensionOriginY: elevationBottom,
        lengthDimensionY: elevationBottom - 0.25,
        lengthDimensionOriginY: elevationBottom
    }));

    drawBeamAdditionalRebarSegments(dxf, additionalSegments, {
        topZ1: topBarY + 0.08,
        topZ2: topBarY + 0.052,
        bottomZ1: bottomBarY + 0.08,
        bottomZ2: bottomBarY + 0.108,
        topHookLevel: elevationTop - beamHeight * 0.52,
        bottomHookLevel: elevationTop - beamHeight * 0.4,
        topLabelY: elevationTop + 0.15,
        bottomLabelY: elevationBottom - 0.15 + STANDALONE_BEAM_DETAIL_BOTTOM_STEEL_LABEL_UP_SHIFT,
        labelSize: 0.06,
        includeFill: true,
        fillStyle: "hatch",
        hatchLayer: FRAME_LONGITUDINAL_HATCH_LAYER,
        hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
        hatchPatternScale: FRAME_REBAR_HATCH_SCALE,
        hookLegAtSegmentEnds: true,
        drawLengthDimensions: true,
        lengthDimensionBreakIntervals: additionalRebarDimensionBreakIntervals
    });

    // The terminal stirrup centerline is kept at least 0.185 m from the beam end line.
    // For unusually short beams where two such clearances cannot coexist, one centered
    // stirrup is retained instead of placing an invalid terminal one.
    const canFitTerminalStirrups = span >= (STANDALONE_BEAM_TERMINAL_STIRRUP_CLEARANCE * 2) - EDGE_TOLERANCE;
    const stirrupEndClearance = canFitTerminalStirrups
        ? STANDALONE_BEAM_TERMINAL_STIRRUP_CLEARANCE
        : span / 2;
    const stirrupIntervals = getMergedBeamTransverseRebarIntervals(beam, stirrupEndClearance, span - stirrupEndClearance);
    const stirrupIntervalsWithPositions = stirrupIntervals.map((interval) => {
        const intervalStart = Math.max(interval.start, stirrupEndClearance);
        const intervalEnd = Math.min(interval.end, span - stirrupEndClearance);
        const positions = intervalEnd >= intervalStart - EDGE_TOLERANCE
            ? getMarkerPositions(intervalStart, intervalEnd, getDxfBeamStirrupSpacingMeters(interval.rebar.spacing), 0)
            : [];

        return {
            ...interval,
            markerPositions: positions
        };
    });
    const stirrupPositions = Array.from(new Map(
        stirrupIntervalsWithPositions
            .flatMap((interval) => interval.markerPositions)
            .map((position) => [getDetailMetricKey(position, 3), Number(position.toFixed(3))])
    ).values()).sort((leftValue, rightValue) => leftValue - rightValue);
    const blockedSupportRects = [...lowerSupportRects, ...upperSupportRects];
    stirrupPositions.forEach((position) => {
        const x = left + beamWidth * (span > EDGE_TOLERANCE ? (position / span) : 0.5);
        if (isStandaloneBeamStirrupBlockedAtX(x, blockedSupportRects)) {
            return;
        }
        addFilledBarSegment(dxf, "ACERO_TRANSVERSAL", x, stirrupTopY, x, stirrupBottomY, DXF_REBAR_2D_RADIUS, DXF_REBAR_SOLID_COLOR, {
            roundStart: true,
            roundEnd: true,
            capStyle: "semicircle",
            drawFlatCaps: false,
            fillStyle: "hatch",
            hatchLayer: FRAME_STIRRUP_HATCH_LAYER,
            hatchPatternName: FRAME_REBAR_HATCH_PATTERN,
            hatchPatternScale: FRAME_REBAR_HATCH_SCALE
        });
    });

    const blockedSupportRectsForCuts = [...lowerSupportRects, ...upperSupportRects];
    localCuts.forEach((entry) => {
        const cutRatio = span > 0 ? entry.cutOffset / span : 0.5;
        const x = left + beamWidth * Math.max(0.05, Math.min(0.95, cutRatio));
        if (isStandaloneBeamStirrupBlockedAtX(x, blockedSupportRectsForCuts)) {
            return;
        }
        // Standalone-beam cuts use the same compact continuous marker as frame cuts:
        // identical Ø0.15 bubbles, linework, layers, and centered labels.
        drawFrameSectionCutMarker(dxf, x, elevationTop, beamHeight, entry.tag);
    });

    addVerticalDimension(dxf, "COTAS_SECCION", beamConcreteRight + 0.35, elevationBottom, elevationTop, beam.h, beamConcreteRight);
    // Main beam-steel annotations keep a fixed 0.15 m separation from the
    // concrete faces, matching the frame-elevation callouts.
    drawLeaderText(dxf, "TEXTO_ACERO", `${formatRebar(beam.topRebar)}`, left + beamWidth * 0.34, elevationTop + 0.15, left + beamWidth * 0.42, topBarY, 0.06, "above");
    const bottomSteelDetailLabelCenterX = left + beamWidth * 0.24 - STANDALONE_BEAM_DETAIL_BOTTOM_STEEL_LABEL_LEFT_SHIFT;
    const bottomSteelDetailLabelY = elevationBottom - 0.15 + STANDALONE_BEAM_DETAIL_BOTTOM_STEEL_LABEL_UP_SHIFT;
    drawLeaderText(
        dxf,
        "TEXTO_ACERO",
        `${formatRebar(beam.botRebar)}`,
        bottomSteelDetailLabelCenterX,
        bottomSteelDetailLabelY,
        left + beamWidth * 0.34,
        bottomBarY,
        0.06,
        "below"
    );

    // Both annotations are measured independently from the lower edge of the beam.
    const dimensionY = elevationBottom - beamSpanDimensionOffsetFromBottom;
    const stirrupDetailY = elevationBottom - stirrupDetailOffsetFromBottom;
    const clearSpanDimension = getStandaloneBeamInteriorSupportDimensionBounds({
        startPosition: beamBounds.start,
        endPosition: beamBounds.end,
        supports: supportModels,
        chainStart: beamBounds.start,
        originLeft: left
    });
    const clearSpanStartX = clearSpanDimension?.startX ?? left;
    const clearSpanEndX = clearSpanDimension?.endX ?? right;
    const clearSpanLength = clearSpanDimension?.length ?? span;
    if (stirrupIntervalsWithPositions.length === 0) {
        addDimension(dxf, "COTAS_SECCION", clearSpanStartX, clearSpanEndX, dimensionY, clearSpanLength.toFixed(2), elevationBottom);
        addCenteredText(dxf, "TEXTO_ESTRIBOS", (clearSpanStartX + clearSpanEndX) / 2, stirrupDetailY, formatDxfBeamStirrupLabel(getBeamDrawingTransverseRebarForZone(beam, "mid", beam.stirrups), DEFAULT_BEAM_STIRRUP_SPACING), 0.06);
    } else {
        stirrupIntervalsWithPositions.forEach((interval) => {
            const markerPositions = interval.markerPositions || [];
            // The length dimension ends at the actual first/last stirrup centerline.
            // This prevents it from extending to the beam edge after end spacing changes.
            const isFirstInterval = interval === stirrupIntervalsWithPositions[0];
            const isLastInterval = interval === stirrupIntervalsWithPositions[stirrupIntervalsWithPositions.length - 1];
            const startPosition = isFirstInterval
                ? 0
                : markerPositions.length
                    ? markerPositions[0]
                    : Math.max(interval.start, stirrupEndClearance);
            const endPosition = isLastInterval
                ? span
                : markerPositions.length
                    ? markerPositions[markerPositions.length - 1]
                    : Math.min(interval.end, span - stirrupEndClearance);
            if (endPosition < startPosition - EDGE_TOLERANCE) {
                return;
            }

            const modelIntervalStart = left + beamWidth * (span > EDGE_TOLERANCE ? (startPosition / span) : 0);
            const modelIntervalEnd = left + beamWidth * (span > EDGE_TOLERANCE ? (endPosition / span) : 1);
            // Only the two external interval boundaries coincide with supports.
            // Pull those extension lines to the inner support faces while
            // retaining the actual interval boundaries inside the clear span.
            const intervalStart = startPosition <= EDGE_TOLERANCE
                ? clearSpanStartX
                : modelIntervalStart;
            const intervalEnd = endPosition >= span - EDGE_TOLERANCE
                ? clearSpanEndX
                : modelIntervalEnd;
            const intervalLength = Math.max(intervalEnd - intervalStart, 0);
            const intervalCenter = (intervalStart + intervalEnd) / 2;
            addDimension(
                dxf,
                "COTAS_SECCION",
                intervalStart,
                intervalEnd,
                dimensionY,
                intervalLength.toFixed(2),
                elevationBottom
            );
            addCenteredText(dxf, "TEXTO_ESTRIBOS", intervalCenter, stirrupDetailY, formatDxfBeamStirrupLabel(interval.rebar, DEFAULT_BEAM_STIRRUP_SPACING), 0.06);
        });
    }

    getStandaloneBeamSupportDimensionSpans(supportModels, beamBounds.start, left).forEach((spanData) => {
        addDimension(
            dxf,
            "COTAS_SECCION",
            spanData.x1,
            spanData.x2,
            dimensionY,
            spanData.width.toFixed(2),
            elevationBottom
        );
    });
}
/* SERVER_ONLY_END */

function clampBeamBarCount(count, { minimum = 0, maximum = MAX_BEAM_LAYOUT_BAR_COUNT_PER_FACE } = {}) {
    const parsed = Number.isFinite(count) ? Math.trunc(count) : minimum;
    const upperLimit = Math.max(Number.parseInt(maximum, 10) || MAX_BEAM_LAYOUT_BAR_COUNT_PER_FACE, minimum);
    return Math.max(Math.min(parsed, upperLimit), minimum);
}

function parseBarCount(value, options = {}) {
    const matches = String(value || "").match(/\d+/g);
    if (!matches) {
        return clampBeamBarCount(2, { minimum: 1, maximum: options.maximum ?? MAX_BEAM_MAIN_BAR_COUNT });
    }

    const count = matches.reduce((sum, item) => sum + Number.parseInt(item, 10), 0);
    return clampBeamBarCount(count, { minimum: 1, maximum: options.maximum ?? MAX_BEAM_MAIN_BAR_COUNT });
}

function parseOptionalBarCount(value, options = {}) {
    const matches = String(value || "").match(/\d+/g);
    if (!matches) {
        return 0;
    }

    const count = matches.reduce((sum, item) => sum + Number.parseInt(item, 10), 0);
    return clampBeamBarCount(count, { minimum: 0, maximum: options.maximum ?? MAX_BEAM_ADDITIONAL_BAR_COUNT });
}

function normalizeBeamSectionFaceBarSpecs(barSpecs = []) {
    const normalizedSpecs = [];
    const indexByDiameter = new Map();

    (Array.isArray(barSpecs) ? barSpecs : []).forEach((barSpec) => {
        const count = resolveBeamLayoutBarCount(barSpec?.count, 0, MAX_BEAM_LAYOUT_BAR_COUNT_PER_FACE);
        const diameterLabel = normalizeBeamLongitudinalDiameterLabel(barSpec?.diameterLabel ?? barSpec?.d ?? DEFAULT_LONGITUDINAL_DIAMETER);

        if (count <= 0) {
            return;
        }

        if (indexByDiameter.has(diameterLabel)) {
            normalizedSpecs[indexByDiameter.get(diameterLabel)].count += count;
            return;
        }

        indexByDiameter.set(diameterLabel, normalizedSpecs.length);
        normalizedSpecs.push({
            count,
            diameterLabel
        });
    });

    return normalizedSpecs;
}

function getBeamSectionFaceTotalBarCount(barSpecs = []) {
    return normalizeBeamSectionFaceBarSpecs(barSpecs).reduce((sum, barSpec) => sum + barSpec.count, 0);
}

function getBeamSectionFaceControlDiameterLabel(barSpecs = [], fallback = DEFAULT_LONGITUDINAL_DIAMETER) {
    const normalizedSpecs = normalizeBeamSectionFaceBarSpecs(barSpecs);
    if (!normalizedSpecs.length) {
        return fallback;
    }

    return normalizedSpecs.reduce((largestDiameterLabel, currentSpec) => (
        parseDiameterInMeters(currentSpec.diameterLabel) > parseDiameterInMeters(largestDiameterLabel)
            ? currentSpec.diameterLabel
            : largestDiameterLabel
    ), normalizedSpecs[0].diameterLabel);
}

function expandBeamSectionFaceBarDiameters(barSpecs = []) {
    return normalizeBeamSectionFaceBarSpecs(barSpecs).flatMap((barSpec) => (
        Array.from({ length: barSpec.count }, () => barSpec.diameterLabel)
    ));
}

function formatBeamSectionFaceBarSpecs(barSpecs = []) {
    const normalizedSpecs = normalizeBeamSectionFaceBarSpecs(barSpecs);
    if (!normalizedSpecs.length) {
        return "0";
    }

    return normalizedSpecs
        .map((barSpec) => formatDxfRebarCountLabel(barSpec.count, barSpec.diameterLabel))
        .join(" + ");
}

function getRebarDrawRadius(diameterLabel) {
    return Math.max((parseDiameterInMeters(diameterLabel) * SECTION_DETAIL_SCALE) / 2, 0.006);
}

// Wall detail geometry is emitted in model metres, without SECTION_DETAIL_SCALE.
function getWallDetailRebarRadius(diameterLabel, fallback = 0.003) {
    const physicalRadius = parseDiameterInMeters(diameterLabel) / 2;
    return Math.max(Number.isFinite(physicalRadius) ? physicalRadius : 0, fallback);
}

function getBeamSectionRebarDrawRadius(diameterLabel) {
    return Math.max((parseDiameterInMeters(diameterLabel) * BEAM_SECTION_DETAIL_SCALE) / 2, 0.006);
}

function getBeamMinimumClearSpacing(diameterLabel) {
    return Math.max(BEAM_MIN_CLEAR_BAR_SPACING, parseDiameterInMeters(diameterLabel));
}

function getBeamRowCapacity(clearWidth, diameterMeters, minimumClearSpacing) {
    if (!(diameterMeters > 0) || clearWidth + EDGE_TOLERANCE < diameterMeters) {
        return 0;
    }

    return Math.max(
        1,
        Math.floor((clearWidth + minimumClearSpacing + EDGE_TOLERANCE) / (diameterMeters + minimumClearSpacing))
    );
}

function getBeamLayerXPositions(count, leftCenter, rightCenter, mode = "distributed") {
    if (count <= 0) {
        return [];
    }

    if (count === 1) {
        return [mode === "corners-first" ? leftCenter : (leftCenter + rightCenter) / 2];
    }

    if (rightCenter <= leftCenter + EDGE_TOLERANCE) {
        return Array.from({ length: count }, () => (leftCenter + rightCenter) / 2);
    }

    return Array.from({ length: count }, (_, index) => (
        leftCenter + ((rightCenter - leftCenter) * index) / (count - 1)
    ));
}

function getBeamSecondLayerXPositions(firstLayerPositions, secondLayerCount) {
    const basePositions = Array.isArray(firstLayerPositions)
        ? [...firstLayerPositions].sort((left, right) => left - right)
        : [];
    const count = Math.min(Math.max(secondLayerCount, 0), basePositions.length);
    if (count <= 0) {
        return [];
    }

    const selectedIndices = [];
    const usedIndices = new Set();
    const registerIndex = (index) => {
        if (index < 0 || index >= basePositions.length || usedIndices.has(index)) {
            return;
        }

        usedIndices.add(index);
        selectedIndices.push(index);
    };

    registerIndex(0);
    if (selectedIndices.length < count) {
        registerIndex(basePositions.length - 1);
    }
    for (let index = 1; selectedIndices.length < count && index < basePositions.length - 1; index += 1) {
        registerIndex(index);
    }

    return selectedIndices
        .map((index) => basePositions[index])
        .sort((left, right) => left - right);
}

function resolveBeamLayoutBarCount(value, fallbackCount = 0, maximum = MAX_BEAM_LAYOUT_BAR_COUNT_PER_FACE) {
    const parsed = Number.parseInt(String(value ?? ""), 10);
    if (Number.isFinite(parsed)) {
        return clampBeamBarCount(parsed, { minimum: 0, maximum });
    }

    return clampBeamBarCount(fallbackCount, { minimum: 0, maximum });
}

function buildBeamFaceLongitudinalRows({
    face,
    count,
    diameterLabel,
    beamWidth,
    beamHeight,
    cover,
    sideCover = cover,
    stirrupDiameterMeters
}) {
    const totalCount = resolveBeamLayoutBarCount(count, 0);
    const diameterMeters = parseDiameterInMeters(diameterLabel);
    const minimumClearSpacingMeters = getBeamMinimumClearSpacing(diameterLabel);
    const horizontalCover = normalizeBeamCover(sideCover, cover);
    const clearWidthMeters = Math.max(beamWidth - (2 * (horizontalCover + stirrupDiameterMeters)), 0);
    const leftCenter = horizontalCover + stirrupDiameterMeters + diameterMeters / 2;
    const rightCenter = beamWidth - horizontalCover - stirrupDiameterMeters - diameterMeters / 2;
    const rowCapacity = getBeamRowCapacity(clearWidthMeters, diameterMeters, minimumClearSpacingMeters);

    const minimumFirstLayerCount = totalCount >= 2 ? 2 : totalCount;
    let firstRowCount = Math.max(Math.min(totalCount, rowCapacity), minimumFirstLayerCount);
    let secondRowCount = Math.max(totalCount - firstRowCount, 0);
    const validHorizontal = totalCount === 0 || (
        rowCapacity >= minimumFirstLayerCount
        && secondRowCount <= rowCapacity
        && secondRowCount <= firstRowCount
    );

    if (!validHorizontal) {
        firstRowCount = Math.max(Math.ceil(totalCount / 2), minimumFirstLayerCount);
        secondRowCount = totalCount - firstRowCount;
    }

    const firstRowCenterY = face === "top"
        ? beamHeight - (cover + stirrupDiameterMeters + diameterMeters / 2)
        : cover + stirrupDiameterMeters + diameterMeters / 2;
    const nominalLayerPitch = diameterMeters + minimumClearSpacingMeters;
    const reducedLayerPitch = nominalLayerPitch - BEAM_SECOND_LAYER_OUTWARD_SHIFT;
    const minimumLayerPitch = diameterMeters + BEAM_SECOND_LAYER_MIN_CLEAR_SPACING;
    const layerPitch = Math.max(minimumLayerPitch, reducedLayerPitch);
    const secondRowCenterY = face === "top"
        ? firstRowCenterY - layerPitch
        : firstRowCenterY + layerPitch;
    const rows = [];
    const firstRowXPositions = getBeamLayerXPositions(firstRowCount, leftCenter, rightCenter, "distributed");

    if (firstRowCount > 0) {
        rows.push({
            face,
            layerIndex: 0,
            count: firstRowCount,
            diameterLabel,
            diameterMeters,
            minimumClearSpacingMeters,
            centerYMeters: firstRowCenterY,
            xPositionsMeters: firstRowXPositions
        });
    }

    if (secondRowCount > 0) {
        rows.push({
            face,
            layerIndex: 1,
            count: secondRowCount,
            diameterLabel,
            diameterMeters,
            minimumClearSpacingMeters,
            centerYMeters: secondRowCenterY,
            xPositionsMeters: getBeamSecondLayerXPositions(firstRowXPositions, secondRowCount)
        });
    }

    const rowsWithinSection = rows.every((row) => (
        row.centerYMeters - row.diameterMeters / 2 >= -EDGE_TOLERANCE
        && row.centerYMeters + row.diameterMeters / 2 <= beamHeight + EDGE_TOLERANCE
    ));

    return {
        rows,
        validHorizontal,
        rowsWithinSection
    };
}

function buildBeamFaceLongitudinalRowsFromSpecs({
    face,
    barSpecs,
    beamWidth,
    beamHeight,
    cover,
    sideCover,
    stirrupDiameterMeters
}) {
    const normalizedSpecs = normalizeBeamSectionFaceBarSpecs(barSpecs);
    const controllingDiameterLabel = getBeamSectionFaceControlDiameterLabel(normalizedSpecs);
    const baseRows = buildBeamFaceLongitudinalRows({
        face,
        count: getBeamSectionFaceTotalBarCount(normalizedSpecs),
        diameterLabel: controllingDiameterLabel,
        beamWidth,
        beamHeight,
        cover,
        sideCover,
        stirrupDiameterMeters
    });
    const expandedDiameters = expandBeamSectionFaceBarDiameters(normalizedSpecs);
    let barIndex = 0;

    return {
        rows: baseRows.rows,
        validHorizontal: baseRows.validHorizontal,
        rowsWithinSection: baseRows.rowsWithinSection,
        bars: baseRows.rows.flatMap((row) => (
            row.xPositionsMeters.map((xMeters) => {
                const diameterLabel = expandedDiameters[barIndex] || controllingDiameterLabel;
                barIndex += 1;
                return {
                    face: row.face,
                    layerIndex: row.layerIndex,
                    diameterLabel,
                    xMeters,
                    yMeters: row.centerYMeters
                };
            })
        ))
    };
}

function getBeamSectionLongitudinalBarLayout(beam, options = {}) {
    const normalizedBeam = beam?.id ? normalizeBeamModel(beam) : normalizeBeamInsertDraft(beam);
    const stirrups = ensureTransverseRebar(normalizedBeam, DEFAULT_BEAM_STIRRUP_SPACING);
    const stirrupDiameterMeters = parseDiameterInMeters(options.stirrupDiameterLabel ?? stirrups.d);
    const topCount = options.topCount != null
        ? resolveBeamLayoutBarCount(options.topCount, 0)
        : parseBarCount(normalizedBeam.topRebar?.n);
    const bottomCount = options.bottomCount != null
        ? resolveBeamLayoutBarCount(options.bottomCount, 0)
        : parseBarCount(normalizedBeam.botRebar?.n);
    const topDiameterLabel = normalizeBeamLongitudinalDiameterLabel(options.topDiameterLabel ?? normalizedBeam.topRebar?.d, normalizedBeam.topRebar?.d);
    const bottomDiameterLabel = normalizeBeamLongitudinalDiameterLabel(options.bottomDiameterLabel ?? normalizedBeam.botRebar?.d, normalizedBeam.botRebar?.d);
    const topSpecs = normalizeBeamSectionFaceBarSpecs(options.topSpecs?.length ? options.topSpecs : [{
        count: topCount,
        diameterLabel: topDiameterLabel
    }]);
    const bottomSpecs = normalizeBeamSectionFaceBarSpecs(options.bottomSpecs?.length ? options.bottomSpecs : [{
        count: bottomCount,
        diameterLabel: bottomDiameterLabel
    }]);
    const topRows = buildBeamFaceLongitudinalRowsFromSpecs({
        face: "top",
        barSpecs: topSpecs,
        beamWidth: normalizedBeam.b,
        beamHeight: normalizedBeam.h,
        cover: normalizedBeam.coverTop,
        sideCover: normalizedBeam.coverSide,
        stirrupDiameterMeters
    });
    const bottomRows = buildBeamFaceLongitudinalRowsFromSpecs({
        face: "bottom",
        barSpecs: bottomSpecs,
        beamWidth: normalizedBeam.b,
        beamHeight: normalizedBeam.h,
        cover: normalizedBeam.coverBottom,
        sideCover: normalizedBeam.coverSide,
        stirrupDiameterMeters
    });
    const allRows = [...topRows.rows, ...bottomRows.rows].sort((leftRow, rightRow) => leftRow.centerYMeters - rightRow.centerYMeters);
    let validVertical = topRows.rowsWithinSection && bottomRows.rowsWithinSection;

    for (let index = 1; index < allRows.length; index += 1) {
        const lowerRow = allRows[index - 1];
        const upperRow = allRows[index];
        const clearSpacing = upperRow.centerYMeters - lowerRow.centerYMeters - ((lowerRow.diameterMeters + upperRow.diameterMeters) / 2);
        const requiredSpacing = Math.max(lowerRow.minimumClearSpacingMeters, upperRow.minimumClearSpacingMeters);

        if (clearSpacing + EDGE_TOLERANCE < requiredSpacing) {
            validVertical = false;
            break;
        }
    }

    return {
        valid: topRows.validHorizontal && bottomRows.validHorizontal && validVertical,
        bars: [...topRows.bars, ...bottomRows.bars],
        rows: {
            top: topRows.rows,
            bottom: bottomRows.rows
        }
    };
}

function getBeamRepresentativeSectionLongitudinalCounts(topMainCount, bottomMainCount, additionalRebar) {
    const additional = normalizeBeamAdditionalRebar(additionalRebar);
    const midTopCount = parseOptionalBarCount(additional.midTop?.n);
    const midBottomCount = parseOptionalBarCount(additional.midBottom?.n);
    const iEndTopCount = parseOptionalBarCount(additional.iEndTop?.n);
    const iEndBottomCount = parseOptionalBarCount(additional.iEndBottom?.n);
    const jEndTopCount = parseOptionalBarCount(additional.jEndTop?.n);
    const jEndBottomCount = parseOptionalBarCount(additional.jEndBottom?.n);

    return [
        {
            zone: "iEnd",
            topCount: topMainCount + midTopCount + iEndTopCount,
            bottomCount: bottomMainCount + midBottomCount + iEndBottomCount
        },
        {
            zone: "mid",
            topCount: topMainCount + midTopCount,
            bottomCount: bottomMainCount + midBottomCount
        },
        {
            zone: "jEnd",
            topCount: topMainCount + midTopCount + jEndTopCount,
            bottomCount: bottomMainCount + midBottomCount + jEndBottomCount
        }
    ];
}


function normalizeBarSet(value) {
    const normalizedValue = String(value || "").trim().toLowerCase();
    return BAR_SET_DEFINITIONS[normalizedValue] ? normalizedValue : DEFAULT_BAR_SET;
}

function getBarSetDefinition(barSet = DEFAULT_BAR_SET) {
    return BAR_SET_DEFINITIONS[normalizeBarSet(barSet)] || BAR_SET_DEFINITIONS[DEFAULT_BAR_SET];
}

function getBarSetBars(barSet = DEFAULT_BAR_SET) {
    return getBarSetDefinition(barSet).bars || [];
}

function getBarSetLabel(barSet = DEFAULT_BAR_SET) {
    return getBarSetDefinition(barSet).label || BAR_SET_DEFINITIONS[DEFAULT_BAR_SET].label;
}

function getBarSetDiameterLabels(barSet = DEFAULT_BAR_SET) {
    return getBarSetBars(barSet).map((bar) => bar.id);
}

function getActiveBarSetForDiameters(fallback = DEFAULT_BAR_SET) {
    try {
        if (typeof state !== "undefined" && state?.barSet) {
            return normalizeBarSet(state.barSet);
        }
    } catch (error) {
        // The client state may still be in its initialization phase.
    }

    try {
        if (typeof projectState !== "undefined" && projectState?.barSet) {
            return normalizeBarSet(projectState.barSet);
        }
    } catch (error) {
        // The server project state may still be in its initialization phase.
    }

    return normalizeBarSet(fallback);
}

function findBarEntryByLabel(diameterLabel, barSet = null) {
    const normalizedLabel = normalizeDiameterLabel(diameterLabel);
    if (!normalizedLabel) {
        return null;
    }

    const normalizedBarSet = barSet ? normalizeBarSet(barSet) : "*";
    const cacheKey = `${normalizedBarSet}|${normalizedLabel}`;
    if (BAR_ENTRY_BY_LABEL_CACHE.has(cacheKey)) {
        return BAR_ENTRY_BY_LABEL_CACHE.get(cacheKey);
    }

    const barSets = barSet ? [normalizedBarSet] : BAR_SET_OPTIONS;
    for (const candidateSet of barSets) {
        const match = getBarSetBars(candidateSet).find((bar) => normalizeDiameterLabel(bar.id) === normalizedLabel);
        if (match) {
            const result = {
                ...match,
                barSet: candidateSet
            };
            BAR_ENTRY_BY_LABEL_CACHE.set(cacheKey, result);
            return result;
        }
    }

    BAR_ENTRY_BY_LABEL_CACHE.set(cacheKey, null);
    return null;
}

function parseInchDiameterLabelInMeters(label) {
    const normalizedLabel = normalizeDiameterLabel(label).replace(/in\.?|inch(?:es)?/gi, " ").replace(/["']/g, " ").trim();
    if (!normalizedLabel) {
        return 0;
    }

    const mixedFractionMatch = normalizedLabel.match(/(\d+)(?:\s+|-)(\d+)\s*\/\s*(\d+)/);
    if (mixedFractionMatch) {
        return (
            Number.parseFloat(mixedFractionMatch[1])
            + (Number.parseFloat(mixedFractionMatch[2]) / Number.parseFloat(mixedFractionMatch[3]))
        ) * 0.0254;
    }

    const fractionMatch = normalizedLabel.match(/(\d+)\s*\/\s*(\d+)/);
    if (fractionMatch) {
        return (Number.parseFloat(fractionMatch[1]) / Number.parseFloat(fractionMatch[2])) * 0.0254;
    }

    const numericMatch = normalizedLabel.match(/(\d+(?:\.\d+)?)/);
    if (numericMatch) {
        return Number.parseFloat(numericMatch[1]) * 0.0254;
    }

    return 0;
}

function parseMillimeterDiameterLabelInMeters(label) {
    const normalizedLabel = normalizeDiameterLabel(label).replace(/mm/gi, " ").trim();
    const numericMatch = normalizedLabel.match(/(\d+(?:[.,]\d+)?)/);
    if (!numericMatch) {
        return 0;
    }
    const diameterMm = Number.parseFloat(numericMatch[1].replace(",", "."));
    return Number.isFinite(diameterMm) && diameterMm > 0 ? diameterMm / 1000 : 0;
}

function getDiameterMetersFromBarLabel(diameterLabel, sourceBarSet = null) {
    const normalizedLabel = normalizeDiameterLabel(diameterLabel);
    if (!normalizedLabel) {
        return 0;
    }

    const normalizedSourceSet = sourceBarSet ? normalizeBarSet(sourceBarSet) : null;
    const cacheKey = `${normalizedSourceSet || "*"}|${normalizedLabel}`;
    if (BAR_DIAMETER_METERS_CACHE.has(cacheKey)) {
        return BAR_DIAMETER_METERS_CACHE.get(cacheKey);
    }
    const cacheResult = (value) => {
        const normalizedValue = Number.isFinite(value) && value > 0 ? value : 0;
        BAR_DIAMETER_METERS_CACHE.set(cacheKey, normalizedValue);
        return normalizedValue;
    };

    const sourceMatch = normalizedSourceSet ? findBarEntryByLabel(normalizedLabel, normalizedSourceSet) : null;
    if (sourceMatch) {
        return cacheResult(sourceMatch.diameterMm / 1000);
    }

    const anySetMatch = findBarEntryByLabel(normalizedLabel);
    if (anySetMatch) {
        return cacheResult(anySetMatch.diameterMm / 1000);
    }

    if (/mm\b/i.test(String(diameterLabel))) {
        return cacheResult(parseMillimeterDiameterLabelInMeters(normalizedLabel));
    }

    if (/["']|\/|\bin\.?\b|inch/i.test(String(diameterLabel))) {
        return cacheResult(parseInchDiameterLabelInMeters(normalizedLabel));
    }

    const numericMatch = normalizedLabel.match(/(\d+(?:[.,]\d+)?)/);
    if (numericMatch) {
        const numericValue = Number.parseFloat(numericMatch[1].replace(",", "."));
        if (Number.isFinite(numericValue) && numericValue > 0) {
            // Numeric labels in the new bar sets are millimeters.
            if (normalizedSourceSet && normalizedSourceSet !== "us-customary") {
                return cacheResult(numericValue / 1000);
            }
            // Old U.S. Customary labels without #/fraction are treated as inches only as a legacy fallback.
            return cacheResult(numericValue * 0.0254);
        }
    }

    return cacheResult(0);
}

function getNearestBarEntryForDiameterMeters(diameterMeters, barSet = DEFAULT_BAR_SET) {
    const normalizedDiameter = Number.parseFloat(diameterMeters);
    const candidates = getBarSetBars(barSet);
    if (!(normalizedDiameter > 0) || !candidates.length) {
        return candidates[0] || null;
    }

    return candidates.reduce((closest, current) => {
        if (!closest) {
            return current;
        }
        const currentDelta = Math.abs((current.diameterMm / 1000) - normalizedDiameter);
        const closestDelta = Math.abs((closest.diameterMm / 1000) - normalizedDiameter);
        return currentDelta < closestDelta ? current : closest;
    }, null);
}

function getMaximumBeamLongitudinalDiameterMeters() {
    const activeDiameters = getBarSetBars(getActiveBarSetForDiameters())
        .map((bar) => Number.parseFloat(bar?.diameterMm) / 1000)
        .filter((diameter) => Number.isFinite(diameter) && diameter > 0);
    const activeSetMaximum = activeDiameters.length ? Math.max(...activeDiameters) : 0;
    const beamMaximum = getDiameterMetersFromBarLabel(MAX_BEAM_LONGITUDINAL_DIAMETER) || parseInchDiameterLabelInMeters(MAX_BEAM_LONGITUDINAL_DIAMETER);
    return Math.min(activeSetMaximum || beamMaximum, beamMaximum || activeSetMaximum);
}

function getMinimumBeamLongitudinalDiameterMeters() {
    const activeDiameters = getBarSetBars(getActiveBarSetForDiameters())
        .map((bar) => Number.parseFloat(bar?.diameterMm) / 1000)
        .filter((diameter) => Number.isFinite(diameter) && diameter > 0);
    const activeSetMinimum = activeDiameters.length ? Math.min(...activeDiameters) : 0;
    const beamMinimum = getDiameterMetersFromBarLabel(MIN_BEAM_LONGITUDINAL_DIAMETER) || parseInchDiameterLabelInMeters(MIN_BEAM_LONGITUDINAL_DIAMETER);
    return Math.max(activeSetMinimum || beamMinimum, beamMinimum || activeSetMinimum);
}

function convertDiameterLabelToBarSet(diameterLabel, targetBarSet = DEFAULT_BAR_SET, sourceBarSet = null) {
    const normalizedLabel = normalizeDiameterLabel(diameterLabel);
    if (!normalizedLabel) {
        return diameterLabel;
    }

    const diameterMeters = getDiameterMetersFromBarLabel(normalizedLabel, sourceBarSet);
    if (!(diameterMeters > 0)) {
        return normalizedLabel;
    }

    const nearestTargetEntry = getNearestBarEntryForDiameterMeters(diameterMeters, targetBarSet);
    return nearestTargetEntry?.id || normalizedLabel;
}

const REBAR_DIAMETER_PROPERTY_KEYS = new Set([
    "d",
    "diameter",
    "diameterLabel",
    "barDiameter",
    "xBarDiameter",
    "yBarDiameter",
    "xDiameter",
    "yDiameter",
    "cornerDiameter",
    "longitudinalDiameter",
    "transverseDiameter",
    "hookDiameter"
]);

function remapDiameterLabelsDeep(value, targetBarSet = DEFAULT_BAR_SET, sourceBarSet = null) {
    if (!value || typeof value !== "object") {
        return value;
    }

    if (Array.isArray(value)) {
        value.forEach((item) => remapDiameterLabelsDeep(item, targetBarSet, sourceBarSet));
        return value;
    }

    Object.keys(value).forEach((key) => {
        const currentValue = value[key];
        if (REBAR_DIAMETER_PROPERTY_KEYS.has(key) && (typeof currentValue === "string" || typeof currentValue === "number")) {
            value[key] = convertDiameterLabelToBarSet(currentValue, targetBarSet, sourceBarSet);
            return;
        }
        if (currentValue && typeof currentValue === "object") {
            remapDiameterLabelsDeep(currentValue, targetBarSet, sourceBarSet);
        }
    });

    return value;
}

function parseDiameterInMeters(diameterLabel) {
    const diameterMeters = getDiameterMetersFromBarLabel(diameterLabel, getActiveBarSetForDiameters());
    return diameterMeters > 0 ? diameterMeters : 0.019;
}

function getBarLayoutPositions(count, left, right, radius) {
    const start = left + Math.max(radius * 1.4, 0.05);
    const end = right - Math.max(radius * 1.4, 0.05);

    if (count <= 1 || end <= start + 0.01) {
        return [(left + right) / 2];
    }

    return Array.from({ length: count }, (_, index) => (
        start + ((end - start) * index) / (count - 1)
    ));
}

function parseNumberOrFallback(value, fallback) {
    const parsed = Number.parseFloat(value);
    return Number.isNaN(parsed) ? fallback : parsed;
}

function getNumericArrayBounds(values = []) {
    let min = Number.POSITIVE_INFINITY;
    let max = Number.NEGATIVE_INFINITY;
    let foundValue = false;

    (Array.isArray(values) ? values : []).forEach((value) => {
        const numericValue = parseNumberOrFallback(value, Number.NaN);
        if (!Number.isFinite(numericValue)) {
            return;
        }

        foundValue = true;
        if (numericValue < min) {
            min = numericValue;
        }
        if (numericValue > max) {
            max = numericValue;
        }
    });

    return foundValue ? { min, max } : null;
}

function parsePositiveNumberOrFallback(value, fallback, min = 0.05) {
    const parsed = Number.parseFloat(String(value).replace(",", "."));
    if (Number.isNaN(parsed)) {
        return fallback;
    }

    return Math.max(parsed, min);
}

function roundCoordinate(value) {
    return Number(Number(value).toFixed(3));
}

function getCachedNormalizedText(cache, key, normalizer) {
    const cachedValue = cache.get(key);
    if (cachedValue !== undefined) {
        return cachedValue;
    }

    const normalizedValue = normalizer(key);
    if (key.length <= NORMALIZED_TEXT_CACHE_MAX_KEY_LENGTH) {
        if (cache.size >= NORMALIZED_TEXT_CACHE_MAX_SIZE) {
            cache.clear();
        }
        cache.set(key, normalizedValue);
    }

    return normalizedValue;
}

function normalizeFractionText(value) {
    const rawValue = String(value ?? "");
    return getCachedNormalizedText(normalizedFractionTextCache, rawValue, (text) => (
        FRACTION_TEXT_TEST_PATTERN.test(text)
            ? text.replace(FRACTION_TEXT_PATTERN, (character) => FRACTION_TEXT_REPLACEMENTS[character] || character)
            : text
    ));
}

function normalizeDiameterLabel(value) {
    const rawValue = String(value ?? "");
    return getCachedNormalizedText(normalizedDiameterLabelCache, rawValue, (text) => (
        normalizeFractionText(text)
            .replace(DIAMETER_SYMBOL_PATTERN, "")
            .trim()
    ));
}


const US_CUSTOMARY_BAR_INCH_LABELS = {
    "#2": "1/4\"",
    "#3": "3/8\"",
    "#4": "1/2\"",
    "#5": "5/8\"",
    "#6": "3/4\"",
    "#7": "7/8\"",
    "#8": "1\"",
    "#9": "1 1/8\"",
    "#10": "1 1/4\"",
    "#11": "1 3/8\"",
    "#14": "1 3/4\"",
    "#18": "2 1/4\""
};

function getGreatestCommonDivisor(leftValue, rightValue) {
    let left = Math.abs(Number.parseInt(leftValue, 10) || 0);
    let right = Math.abs(Number.parseInt(rightValue, 10) || 0);
    while (right) {
        const next = left % right;
        left = right;
        right = next;
    }
    return left || 1;
}

function formatDecimalInchesAsFraction(valueInches, denominator = 16) {
    const numericValue = Number.parseFloat(valueInches);
    if (!Number.isFinite(numericValue) || numericValue <= 0) {
        return "";
    }

    let whole = Math.floor(numericValue);
    let numerator = Math.round((numericValue - whole) * denominator);
    if (numerator >= denominator) {
        whole += 1;
        numerator = 0;
    }

    if (numerator <= 0) {
        return `${whole}\"`;
    }

    const divisor = getGreatestCommonDivisor(numerator, denominator);
    const reducedNumerator = numerator / divisor;
    const reducedDenominator = denominator / divisor;
    return whole > 0
        ? `${whole} ${reducedNumerator}/${reducedDenominator}\"`
        : `${reducedNumerator}/${reducedDenominator}\"`;
}

function isUsCustomaryDxfRebarDisplay() {
    return getActiveBarSetForDiameters() === "us-customary";
}

function formatDxfRebarDiameterLabel(diameterLabel) {
    const normalized = normalizeDiameterLabel(diameterLabel) || DEFAULT_LONGITUDINAL_DIAMETER;
    // U.S. Customary drawings use the physical bar diameter in inches throughout
    // the DXF, including labels generated from imported # bar designations.
    if (!isUsCustomaryDxfRebarDisplay()) {
        return normalized;
    }

    const exactLabel = US_CUSTOMARY_BAR_INCH_LABELS[normalized];
    if (exactLabel) {
        return exactLabel;
    }

    const diameterMeters = getDiameterMetersFromBarLabel(normalized, getActiveBarSetForDiameters());
    if (!(diameterMeters > 0)) {
        return normalized;
    }

    return formatDecimalInchesAsFraction(diameterMeters / 0.0254) || normalized;
}

function formatDxfSpacingLength(valueMeters, options = {}) {
    const kind = options.kind || "spacing";
    const unitDefinition = getUnitDefinition(kind, options.unitSystem || null);
    const displayValue = convertMetersToUnit(valueMeters, kind, options.unitSystem || null);
    if (!Number.isFinite(displayValue)) {
        return "";
    }

    const decimals = Number.isInteger(options.decimals) ? options.decimals : 2;
    const valueLabel = displayValue.toFixed(decimals);
    if (options.includeUnit === false) {
        return valueLabel;
    }
    return `${valueLabel}${String(unitDefinition.unit || "").toUpperCase()}`;
}

function formatDxfRebarSpacingLabel(diameter, spacing, options = {}) {
    const symbol = options.symbol === false ? "" : (options.symbol || TRANSVERSE_SYMBOL);
    const normalizedSpacing = parsePositiveNumberOrFallback(spacing, DEFAULT_SLAB_BAR_SPACING);
    return `${symbol}${formatDxfRebarDiameterLabel(diameter)}@${formatDxfSpacingLength(normalizedSpacing, { decimals: 2 })}`;
}

function formatDxfRebarCountLabel(count, diameter) {
    return `${count}${TRANSVERSE_SYMBOL}${formatDxfRebarDiameterLabel(diameter)}`;
}

function formatDxfWallRebarLayoutLabel(concrete = {}, direction = "longitudinal") {
    const isTransverse = direction === "transverse";
    const isHorizontal = direction === "horizontal";
    if (!isTransverse && !isHorizontal && getWallConcreteReinforcementMode(concrete) === WALL_REINFORCEMENT_MODE_QUANTITY) {
        const count = normalizeWallRebarCount(concrete.longitudinalCount, DEFAULT_WALL_LONGITUDINAL_COUNT);
        return formatDxfRebarCountLabel(count, concrete.longitudinalDiameter);
    }
    return formatDxfRebarSpacingLabel(
        isTransverse
            ? concrete.transverseDiameter
            : isHorizontal
                ? concrete.horizontalDiameter
                : concrete.longitudinalDiameter,
        isTransverse
            ? concrete.transverseSpacing
            : isHorizontal
                ? concrete.horizontalSpacing
                : concrete.longitudinalSpacing
    );
}

function getRawSlabBounds(slab) {
    const x1 = parseNumberOrFallback(slab?.x1, 0);
    const x2 = parseNumberOrFallback(slab?.x2, x1);
    const y1 = parseNumberOrFallback(slab?.y1, 0);
    const y2 = parseNumberOrFallback(slab?.y2, y1);
    return {
        x1: Math.min(x1, x2),
        x2: Math.max(x1, x2),
        y1: Math.min(y1, y2),
        y2: Math.max(y1, y2)
    };
}

function areMetricPointsEqual(pointA, pointB, tolerance = EDGE_TOLERANCE) {
    return Boolean(
        pointA
        && pointB
        && Math.abs(parseNumberOrFallback(pointA.x, Number.NaN) - parseNumberOrFallback(pointB.x, Number.NaN)) <= tolerance
        && Math.abs(parseNumberOrFallback(pointA.y, Number.NaN) - parseNumberOrFallback(pointB.y, Number.NaN)) <= tolerance
    );
}

function normalizeSlabVertices(slab) {
    const rawVertices = Array.isArray(slab?.vertices)
        ? slab.vertices
            .map((vertex) => {
                const normalizedVertex = {
                    x: parseNumberOrFallback(vertex?.x, Number.NaN),
                    y: parseNumberOrFallback(vertex?.y, Number.NaN)
                };
                const z = parseNumberOrFallback(vertex?.z, Number.NaN);
                if (Number.isFinite(z)) {
                    normalizedVertex.z = roundCoordinate(z);
                }
                return normalizedVertex;
            })
            .filter((vertex) => Number.isFinite(vertex.x) && Number.isFinite(vertex.y))
        : [];
    const vertices = [];

    rawVertices.forEach((vertex) => {
        if (!vertices.length || !areMetricPointsEqual(vertices[vertices.length - 1], vertex)) {
            vertices.push(vertex);
        }
    });

    if (vertices.length > 1 && areMetricPointsEqual(vertices[0], vertices[vertices.length - 1])) {
        vertices.pop();
    }

    if (vertices.length >= 3) {
        return vertices;
    }

    const bounds = getRawSlabBounds(slab);
    return [
        { x: bounds.x1, y: bounds.y1 },
        { x: bounds.x2, y: bounds.y1 },
        { x: bounds.x2, y: bounds.y2 },
        { x: bounds.x1, y: bounds.y2 }
    ];
}

function getPolygonBounds(vertices = []) {
    let x1 = Number.POSITIVE_INFINITY;
    let x2 = Number.NEGATIVE_INFINITY;
    let y1 = Number.POSITIVE_INFINITY;
    let y2 = Number.NEGATIVE_INFINITY;
    let foundValue = false;

    (Array.isArray(vertices) ? vertices : []).forEach((vertex) => {
        const x = parseNumberOrFallback(vertex?.x, Number.NaN);
        const y = parseNumberOrFallback(vertex?.y, Number.NaN);
        if (!Number.isFinite(x) || !Number.isFinite(y)) {
            return;
        }

        foundValue = true;
        if (x < x1) {
            x1 = x;
        }
        if (x > x2) {
            x2 = x;
        }
        if (y < y1) {
            y1 = y;
        }
        if (y > y2) {
            y2 = y;
        }
    });

    if (!foundValue) {
        return {
            x1: 0,
            x2: 0,
            y1: 0,
            y2: 0
        };
    }

    return { x1, x2, y1, y2 };
}

function normalizeSlabBounds(slab) {
    const vertices = normalizeSlabVertices(slab);
    return getPolygonBounds(vertices);
}

function getSlabPolygonArea(verticesOrSlab) {
    const vertices = Array.isArray(verticesOrSlab) ? verticesOrSlab : normalizeSlabVertices(verticesOrSlab);
    if (vertices.length < 3) {
        return 0;
    }

    let twiceArea = 0;
    for (let index = 0; index < vertices.length; index += 1) {
        const current = vertices[index];
        const next = vertices[(index + 1) % vertices.length];
        twiceArea += current.x * next.y - next.x * current.y;
    }
    return twiceArea / 2;
}

function getSlabCentroid(verticesOrSlab) {
    const vertices = Array.isArray(verticesOrSlab) ? verticesOrSlab : normalizeSlabVertices(verticesOrSlab);
    const signedArea = getSlabPolygonArea(vertices);
    if (vertices.length < 3 || Math.abs(signedArea) <= EDGE_TOLERANCE) {
        const bounds = getPolygonBounds(vertices);
        return {
            x: (bounds.x1 + bounds.x2) / 2,
            y: (bounds.y1 + bounds.y2) / 2
        };
    }

    let centroidX = 0;
    let centroidY = 0;
    for (let index = 0; index < vertices.length; index += 1) {
        const current = vertices[index];
        const next = vertices[(index + 1) % vertices.length];
        const cross = current.x * next.y - next.x * current.y;
        centroidX += (current.x + next.x) * cross;
        centroidY += (current.y + next.y) * cross;
    }

    const factor = 1 / (6 * signedArea);
    return {
        x: centroidX * factor,
        y: centroidY * factor
    };
}

function getPolygonSegments(vertices = []) {
    if (vertices.length < 2) {
        return [];
    }

    return vertices.map((vertex, index) => ({
        x1: vertex.x,
        y1: vertex.y,
        x2: vertices[(index + 1) % vertices.length].x,
        y2: vertices[(index + 1) % vertices.length].y
    }));
}

function isPointOnPolygonSegment(point, segment, tolerance = EDGE_TOLERANCE) {
    const dx = segment.x2 - segment.x1;
    const dy = segment.y2 - segment.y1;
    const cross = (point.x - segment.x1) * dy - (point.y - segment.y1) * dx;
    if (Math.abs(cross) > tolerance) {
        return false;
    }

    const dot = (point.x - segment.x1) * (point.x - segment.x2) + (point.y - segment.y1) * (point.y - segment.y2);
    return dot <= tolerance;
}

function isPointInPolygon(point, vertices = [], { includeBoundary = true } = {}) {
    if (!point || vertices.length < 3) {
        return false;
    }

    if (includeBoundary && getPolygonSegments(vertices).some((segment) => isPointOnPolygonSegment(point, segment))) {
        return true;
    }

    let inside = false;
    for (let index = 0, previousIndex = vertices.length - 1; index < vertices.length; previousIndex = index, index += 1) {
        const current = vertices[index];
        const previous = vertices[previousIndex];
        const intersects = ((current.y > point.y) !== (previous.y > point.y))
            && (point.x < ((previous.x - current.x) * (point.y - current.y)) / ((previous.y - current.y) || 1e-9) + current.x);
        if (intersects) {
            inside = !inside;
        }
    }

    return inside;
}

function getSegmentIntersectionParameter(segmentA, segmentB, tolerance = EDGE_TOLERANCE) {
    const r = { x: segmentA.x2 - segmentA.x1, y: segmentA.y2 - segmentA.y1 };
    const s = { x: segmentB.x2 - segmentB.x1, y: segmentB.y2 - segmentB.y1 };
    const denominator = r.x * s.y - r.y * s.x;
    if (Math.abs(denominator) <= tolerance) {
        return null;
    }

    const qp = { x: segmentB.x1 - segmentA.x1, y: segmentB.y1 - segmentA.y1 };
    const t = (qp.x * s.y - qp.y * s.x) / denominator;
    const u = (qp.x * r.y - qp.y * r.x) / denominator;
    if (t < -tolerance || t > 1 + tolerance || u < -tolerance || u > 1 + tolerance) {
        return null;
    }

    return Math.min(1, Math.max(0, t));
}

function getSegmentPointAt(segment, parameter) {
    return {
        x: segment.x1 + (segment.x2 - segment.x1) * parameter,
        y: segment.y1 + (segment.y2 - segment.y1) * parameter
    };
}

function clipSegmentToPolygon(segment, vertices = []) {
    if (!segment || vertices.length < 3) {
        return [];
    }

    const tValues = [0, 1];
    getPolygonSegments(vertices).forEach((edge) => {
        const parameter = getSegmentIntersectionParameter(segment, edge);
        if (Number.isFinite(parameter)) {
            tValues.push(parameter);
        }
    });

    const sortedParameters = Array.from(new Set(
        tValues
            .map((value) => Number(value.toFixed(6)))
            .filter((value) => value >= 0 && value <= 1)
    )).sort((left, right) => left - right);

    const clippedSegments = [];
    for (let index = 0; index < sortedParameters.length - 1; index += 1) {
        const start = sortedParameters[index];
        const end = sortedParameters[index + 1];
        if (end - start <= 1e-6) {
            continue;
        }

        const midpoint = getSegmentPointAt(segment, (start + end) / 2);
        if (!isPointInPolygon(midpoint, vertices)) {
            continue;
        }

        const startPoint = getSegmentPointAt(segment, start);
        const endPoint = getSegmentPointAt(segment, end);
        clippedSegments.push({
            x1: startPoint.x,
            y1: startPoint.y,
            x2: endPoint.x,
            y2: endPoint.y
        });
    }

    return clippedSegments;
}

function clipSegmentsToSlabPolygon(segments, slab) {
    const vertices = normalizeSlabVertices(slab);
    return (segments || []).flatMap((segment) => clipSegmentToPolygon(segment, vertices));
}

function doSlabPolygonsOverlap(slabA, slabB) {
    const verticesA = normalizeSlabVertices(slabA);
    const verticesB = normalizeSlabVertices(slabB);
    const boundsA = getPolygonBounds(verticesA);
    const boundsB = getPolygonBounds(verticesB);
    if (!slabBoundsOverlap(boundsA, boundsB)) {
        return false;
    }

    if (verticesA.some((vertex) => isPointInPolygon(vertex, verticesB, { includeBoundary: false }))) {
        return true;
    }
    if (verticesB.some((vertex) => isPointInPolygon(vertex, verticesA, { includeBoundary: false }))) {
        return true;
    }
    if (isPointInPolygon(getSlabCentroid(verticesA), verticesB, { includeBoundary: false })) {
        return true;
    }
    if (isPointInPolygon(getSlabCentroid(verticesB), verticesA, { includeBoundary: false })) {
        return true;
    }

    return getPolygonSegments(verticesA).some((segmentA) => (
        getPolygonSegments(verticesB).some((segmentB) => {
            const parameter = getSegmentIntersectionParameter(segmentA, segmentB);
            if (!Number.isFinite(parameter)) {
                return false;
            }

            const intersectionPoint = getSegmentPointAt(segmentA, parameter);
            const touchesBoundaryOnly = isPointOnPolygonSegment(intersectionPoint, segmentA, 1e-6)
                && isPointOnPolygonSegment(intersectionPoint, segmentB, 1e-6)
                && (
                    areMetricPointsEqual(intersectionPoint, { x: segmentA.x1, y: segmentA.y1 }, 1e-6)
                    || areMetricPointsEqual(intersectionPoint, { x: segmentA.x2, y: segmentA.y2 }, 1e-6)
                    || areMetricPointsEqual(intersectionPoint, { x: segmentB.x1, y: segmentB.y1 }, 1e-6)
                    || areMetricPointsEqual(intersectionPoint, { x: segmentB.x2, y: segmentB.y2 }, 1e-6)
                );
            return !touchesBoundaryOnly;
        })
    ));
}

function normalizeWall(wall) {
    const defaults = createDefaultWallSection();
    const material = normalizeWallMaterialType(wall?.material);
    const masonryBlockWidth = normalizeMasonryBlockWidth(
        wall?.masonry?.blockWidth ?? (material === "masonry" ? wall?.b : defaults.masonry.blockWidth),
        defaults.masonry.blockWidth
    );
    return {
        id: wall?.id ?? createEntityId("wall"),
        name: normalizeTextValue(wall?.name),
        x1: parseNumberOrFallback(wall?.x1, 0),
        y1: parseNumberOrFallback(wall?.y1, 0),
        x2: parseNumberOrFallback(wall?.x2, 0),
        y2: parseNumberOrFallback(wall?.y2, 0),
        b: material === "masonry"
            ? masonryBlockWidth
            : parsePositiveNumberOrFallback(wall?.b, DEFAULT_WALL_THICKNESS, 0.08),
        h: parsePositiveNumberOrFallback(wall?.h, 2.5, 0.1),
        structuralMaterial: normalizeStructuralMaterialSpec(wall?.structuralMaterial),
        material,
        concrete: {
            reinforcementMode: normalizeWallReinforcementMode(wall?.concrete?.reinforcementMode ?? defaults.concrete.reinforcementMode),
            longitudinalDiameter: normalizeDiameterLabel(wall?.concrete?.longitudinalDiameter ?? defaults.concrete.longitudinalDiameter) || defaults.concrete.longitudinalDiameter,
            longitudinalSpacing: parsePositiveNumberOrFallback(wall?.concrete?.longitudinalSpacing, defaults.concrete.longitudinalSpacing),
            longitudinalCount: normalizeWallRebarCount(wall?.concrete?.longitudinalCount, defaults.concrete.longitudinalCount),
            longitudinalGrouped: normalizeWallLongitudinalGrouped(wall?.concrete?.longitudinalGrouped ?? defaults.concrete.longitudinalGrouped),
            horizontalDiameter: normalizeDiameterLabel(wall?.concrete?.horizontalDiameter ?? defaults.concrete.horizontalDiameter) || defaults.concrete.horizontalDiameter,
            horizontalSpacing: parsePositiveNumberOrFallback(wall?.concrete?.horizontalSpacing, defaults.concrete.horizontalSpacing),
            includeHooks: wall?.concrete?.includeHooks !== false,
            transverseDiameter: normalizeDiameterLabel(wall?.concrete?.transverseDiameter ?? defaults.concrete.transverseDiameter) || defaults.concrete.transverseDiameter,
            transverseSpacing: parsePositiveNumberOrFallback(wall?.concrete?.transverseSpacing, defaults.concrete.transverseSpacing),
            transverseCount: normalizeWallRebarCount(wall?.concrete?.transverseCount, defaults.concrete.transverseCount),
            weldedWireMesh: normalizeThinWallWeldedMesh(wall?.concrete?.weldedWireMesh ?? defaults.concrete.weldedWireMesh),
            cover: normalizeWallCover(wall?.concrete?.cover, material === "thin_wall" ? DEFAULT_THIN_WALL_COVER : defaults.concrete.cover)
        },
        masonry: {
            blockWidth: masonryBlockWidth,
            fillMode: normalizeMasonryFillMode(wall?.masonry?.fillMode),
            barsPerCell: Math.max(Number.parseInt(wall?.masonry?.barsPerCell ?? defaults.masonry.barsPerCell, 10) || defaults.masonry.barsPerCell, 1),
            barDiameter: normalizeDiameterLabel(wall?.masonry?.barDiameter ?? defaults.masonry.barDiameter) || defaults.masonry.barDiameter,
            horizontalBarDiameter: normalizeDiameterLabel(wall?.masonry?.horizontalBarDiameter ?? defaults.masonry.horizontalBarDiameter) || defaults.masonry.horizontalBarDiameter,
            horizontalSpacing: parsePositiveNumberOrFallback(wall?.masonry?.horizontalSpacing, defaults.masonry.horizontalSpacing, 0.1),
            includeTieBeam: wall?.masonry?.includeTieBeam !== false,
            tieBeam: normalizeMasonryTieBeamSpec(wall?.masonry?.tieBeam ?? defaults.masonry.tieBeam),
            wallType: wall?.masonry?.wallType === "thin_wall" ? "thin_wall" : "masonry",
            endColumns: material === "masonry"
                ? normalizeMasonryEndColumnsForWallWidth(
                    wall?.masonry?.endColumns ?? defaults.masonry.endColumns,
                    masonryBlockWidth
                )
                : normalizeMasonryEndColumnsConfig(wall?.masonry?.endColumns ?? defaults.masonry.endColumns)
        },
        windows: normalizeWallWindows(wall?.windows, { length: getSegmentLength(wall?.x1, wall?.y1, wall?.x2, wall?.y2), height: parsePositiveNumberOrFallback(wall?.h, 2.5, 0.1) })
    };
}

function normalizeWallWindow(windowSource = {}, context = {}) {
    const wallLength = parsePositiveNumberOrFallback(context.length, 1, 0.01);
    const wallHeight = parsePositiveNumberOrFallback(context.height, 2.5, 0.1);
    const width = Math.min(parsePositiveNumberOrFallback(windowSource?.width, Math.min(1.2, wallLength), 0.05), Math.max(wallLength, 0.05));
    const offset = Math.min(Math.max(parseNumberOrFallback(windowSource?.offset, wallLength / 2), width / 2), Math.max(wallLength - width / 2, width / 2));
    const sillHeight = Math.min(Math.max(parsePositiveNumberOrFallback(windowSource?.sillHeight ?? windowSource?.height, Math.min(1.0, wallHeight * 0.45), 0.05), 0.05), Math.max(wallHeight - 0.05, 0.05));
    return {
        id: normalizeTextValue(windowSource?.id) || createEntityId("wall-window"),
        offset,
        width,
        sillHeight
    };
}

function normalizeWallWindows(windows = [], context = {}) {
    return (Array.isArray(windows) ? windows : [])
        .map((windowSource) => normalizeWallWindow(windowSource, context))
        .filter((windowEntry) => windowEntry.width > 0 && windowEntry.sillHeight > 0)
        .sort((left, right) => left.offset - right.offset);
}

function getSegmentLength(x1, y1, x2, y2) {
    const dx = parseNumberOrFallback(x2, 0) - parseNumberOrFallback(x1, 0);
    const dy = parseNumberOrFallback(y2, 0) - parseNumberOrFallback(y1, 0);
    return Math.hypot(dx, dy);
}

function getWallLength(wall) {
    const normalizedWall = normalizeWall(wall);
    return getSegmentLength(normalizedWall.x1, normalizedWall.y1, normalizedWall.x2, normalizedWall.y2);
}

function getWallProjectionOffset(wall, x, y) {
    const normalizedWall = normalizeWall(wall);
    const length = getWallLength(normalizedWall);
    if (!(length > 0)) {
        return 0;
    }
    const ux = (normalizedWall.x2 - normalizedWall.x1) / length;
    const uy = (normalizedWall.y2 - normalizedWall.y1) / length;
    return Math.min(Math.max((x - normalizedWall.x1) * ux + (y - normalizedWall.y1) * uy, 0), length);
}

function normalizeSlab(slab) {
    const vertices = normalizeSlabVertices(slab);
    const bounds = getPolygonBounds(vertices);
    const slabType = normalizeSlabType(slab?.type);
    const defaultActionType = getDefaultSlabActionType(slab, slabType, bounds);
    const actionType = slabType === SLAB_TYPE_METAL_DECK
        ? SLAB_ACTION_ONE_WAY
        : supportsSlabActionType(slabType)
            ? normalizeSlabActionType(
                slab?.actionType
                    ?? slab?.slabActionType
                    ?? slab?.reinforcementActionType
                    ?? slab?.reinforcementLayout
                    ?? slab?.action,
                defaultActionType
            )
            : SLAB_ACTION_TWO_WAY;
    const topSteelDirection = normalizeSlabTopSteelDirectionForAction(slab?.solid?.topSteelDirection, actionType, bounds);
    const zBounds = getNumericArrayBounds(vertices.map((vertex) => vertex.z));
    const minZ = parseNumberOrFallback(slab?.minZ, zBounds?.min ?? 0);
    const maxZ = parseNumberOrFallback(slab?.maxZ, zBounds?.max ?? minZ);
    const slopeHeight = parseNumberOrFallback(slab?.slopeHeight, maxZ - minZ);
    return {
        id: slab?.id ?? `${slabType === "hole" ? "hole" : "slab"}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        name: normalizeTextValue(slab?.name),
        sourceId: normalizeTextValue(slab?.sourceId),
        sourceStory: normalizeTextValue(slab?.sourceStory),
        sourceSection: normalizeTextValue(slab?.sourceSection),
        areaTypeFromEtabs: normalizeTextValue(slab?.areaTypeFromEtabs),
        sectionName: normalizeTextValue(slab?.sectionName || slab?.sourceSection),
        pointIds: Array.isArray(slab?.pointIds) ? slab.pointIds.map((pointId) => normalizeTextValue(pointId)).filter(Boolean) : [],
        vertices,
        ...bounds,
        b: parsePositiveNumberOrFallback(slab?.b, 1.0, 0.1),
        h: parsePositiveNumberOrFallback(slab?.h, 0.15, 0.05),
        structuralMaterial: normalizeStructuralMaterialSpec(slab?.structuralMaterial),
        type: slabType,
        actionType,
        isSloped: Boolean(slab?.isSloped) || Math.abs(slopeHeight) > SLOPED_SLAB_Z_TOLERANCE,
        minZ: roundCoordinate(minZ),
        maxZ: roundCoordinate(maxZ),
        slopeHeight: roundCoordinate(slopeHeight),
        temperatureSteel: normalizeSlabTemperatureSteelForAction(slab?.temperatureSteel, actionType, bounds, topSteelDirection),
        solid: {
            xBarDiameter: normalizeDiameterLabel(slab?.solid?.xBarDiameter ?? DEFAULT_SLAB_BAR_DIAMETER) || DEFAULT_SLAB_BAR_DIAMETER,
            xSpacing: parsePositiveNumberOrFallback(slab?.solid?.xSpacing, DEFAULT_SLAB_BAR_SPACING),
            yBarDiameter: normalizeDiameterLabel(slab?.solid?.yBarDiameter ?? DEFAULT_SLAB_BAR_DIAMETER) || DEFAULT_SLAB_BAR_DIAMETER,
            ySpacing: parsePositiveNumberOrFallback(slab?.solid?.ySpacing, DEFAULT_SLAB_BAR_SPACING),
            topSteelDirection
        },
        lightened: normalizeLightenedSlabConfig(slab?.lightened),
        metalDeck: normalizeMetalDeckConfig(slab?.metalDeck),
        cantilever: Boolean(slab?.cantilever ?? slab?.isCantilever),
        importSupportBehaviorResolved: Boolean(slab?.importSupportBehaviorResolved),
        autoDetectedCantilever: Boolean(slab?.autoDetectedCantilever)
    };
}

function getSlabSplitIdFragment(value, fallback = "item") {
    const fragment = normalizeTextValue(value || fallback)
        .replace(/[^a-zA-Z0-9_-]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .slice(0, 48);
    return fragment || fallback;
}

function getSlabBeamSplitPieceId(slab, beam, index) {
    const slabFragment = getSlabSplitIdFragment(slab?.id, "slab");
    const beamFragment = getSlabSplitIdFragment(
        beam?.id || `${roundCoordinate(beam?.x1)}-${roundCoordinate(beam?.y1)}-${roundCoordinate(beam?.x2)}-${roundCoordinate(beam?.y2)}`,
        "beam"
    );
    return `${slabFragment}-split-${beamFragment}-${index + 1}`;
}

function cloneMetricPoint(point) {
    const cloned = {
        x: roundCoordinate(point?.x),
        y: roundCoordinate(point?.y)
    };
    const z = parseNumberOrFallback(point?.z, Number.NaN);
    if (Number.isFinite(z)) {
        cloned.z = roundCoordinate(z);
    }
    return cloned;
}

function getInterpolatedSlabBoundaryPoint(start, end, point) {
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const lengthSquared = dx * dx + dy * dy;
    const rawParameter = lengthSquared > 1e-9
        ? (((point.x - start.x) * dx) + ((point.y - start.y) * dy)) / lengthSquared
        : 0;
    const parameter = Math.max(0, Math.min(1, rawParameter));
    const interpolated = {
        x: roundCoordinate(start.x + dx * parameter),
        y: roundCoordinate(start.y + dy * parameter)
    };
    const startZ = parseNumberOrFallback(start.z, Number.NaN);
    const endZ = parseNumberOrFallback(end.z, Number.NaN);
    if (Number.isFinite(startZ) && Number.isFinite(endZ)) {
        interpolated.z = roundCoordinate(startZ + (endZ - startZ) * parameter);
    }
    return interpolated;
}

function findOrInsertSlabSplitPoint(vertices, point, tolerance = EDGE_TOLERANCE) {
    const existingIndex = vertices.findIndex((vertex) => areMetricPointsEqual(vertex, point, tolerance));
    if (existingIndex >= 0) {
        return existingIndex;
    }

    for (let index = 0; index < vertices.length; index += 1) {
        const nextIndex = (index + 1) % vertices.length;
        const segment = {
            x1: vertices[index].x,
            y1: vertices[index].y,
            x2: vertices[nextIndex].x,
            y2: vertices[nextIndex].y
        };
        if (!isPointOnPolygonSegment(point, segment, tolerance)) {
            continue;
        }

        const insertedPoint = getInterpolatedSlabBoundaryPoint(vertices[index], vertices[nextIndex], point);
        vertices.splice(index + 1, 0, insertedPoint);
        return index + 1;
    }

    return -1;
}

function getPolygonPathBetween(vertices, startIndex, endIndex) {
    const path = [];
    let index = startIndex;
    for (let steps = 0; steps <= vertices.length; steps += 1) {
        path.push(cloneMetricPoint(vertices[index]));
        if (index === endIndex) {
            return path;
        }
        index = (index + 1) % vertices.length;
    }
    return [];
}

function cleanSlabSplitVertices(vertices = []) {
    const cleaned = [];
    vertices.forEach((vertex) => {
        const point = cloneMetricPoint(vertex);
        if (!cleaned.length || !areMetricPointsEqual(cleaned[cleaned.length - 1], point, 1e-6)) {
            cleaned.push(point);
        }
    });

    if (cleaned.length > 1 && areMetricPointsEqual(cleaned[0], cleaned[cleaned.length - 1], 1e-6)) {
        cleaned.pop();
    }

    return cleaned;
}

function buildSplitSlabPiece(slab, beam, vertices, index) {
    const cleanedVertices = cleanSlabSplitVertices(vertices);
    if (cleanedVertices.length < 3 || Math.abs(getSlabPolygonArea(cleanedVertices)) <= SLAB_BEAM_SPLIT_MIN_AREA) {
        return null;
    }

    return normalizeSlab({
        ...slab,
        id: getSlabBeamSplitPieceId(slab, beam, index),
        vertices: cleanedVertices,
        pointIds: []
    });
}

function splitSlabByBoundaryChord(slab, beam, chord) {
    const vertices = normalizeSlabVertices(slab).map(cloneMetricPoint);
    const startPoint = { x: chord.x1, y: chord.y1 };
    const endPoint = { x: chord.x2, y: chord.y2 };
    if (getSegmentLength(startPoint, endPoint) <= SLAB_BEAM_SPLIT_MIN_CHORD_LENGTH) {
        return [normalizeSlab(slab)];
    }

    findOrInsertSlabSplitPoint(vertices, startPoint, EDGE_TOLERANCE);
    findOrInsertSlabSplitPoint(vertices, endPoint, EDGE_TOLERANCE);
    const startIndex = vertices.findIndex((vertex) => areMetricPointsEqual(vertex, startPoint, EDGE_TOLERANCE));
    const endIndex = vertices.findIndex((vertex) => areMetricPointsEqual(vertex, endPoint, EDGE_TOLERANCE));
    if (startIndex < 0 || endIndex < 0 || startIndex === endIndex) {
        return [normalizeSlab(slab)];
    }

    const firstPath = getPolygonPathBetween(vertices, startIndex, endIndex);
    const secondPath = getPolygonPathBetween(vertices, endIndex, startIndex);
    const pieces = [
        buildSplitSlabPiece(slab, beam, firstPath, 0),
        buildSplitSlabPiece(slab, beam, secondPath, 1)
    ].filter(Boolean);

    return pieces.length === 2 ? pieces : [normalizeSlab(slab)];
}

function createExtendedBeamLineForSlab(vertices, beam) {
    const startPoint = { x: beam.x1, y: beam.y1 };
    const endPoint = { x: beam.x2, y: beam.y2 };
    const beamLength = getSegmentLength(startPoint, endPoint);
    if (beamLength <= EDGE_TOLERANCE) {
        return null;
    }

    const bounds = getPolygonBounds(vertices);
    const diagonal = Math.hypot(bounds.x2 - bounds.x1, bounds.y2 - bounds.y1);
    const extension = Math.max(diagonal + beamLength, 1);
    const unitX = (endPoint.x - startPoint.x) / beamLength;
    const unitY = (endPoint.y - startPoint.y) / beamLength;
    const centerX = (startPoint.x + endPoint.x) / 2;
    const centerY = (startPoint.y + endPoint.y) / 2;

    return {
        x1: centerX - unitX * extension,
        y1: centerY - unitY * extension,
        x2: centerX + unitX * extension,
        y2: centerY + unitY * extension
    };
}

function doesBeamOverlapSlabSplitChord(beamSegment, chord) {
    const chordLength = getSegmentLength(
        { x: chord.x1, y: chord.y1 },
        { x: chord.x2, y: chord.y2 }
    );
    const minOverlap = Math.max(
        EDGE_TOLERANCE,
        Math.min(SLAB_BEAM_SPLIT_MIN_CHORD_LENGTH, chordLength * 0.25)
    );
    return getCollinearSegmentOverlapLength(chord, beamSegment, EDGE_TOLERANCE) > minOverlap;
}

function getCollinearSegmentOverlapInterval(baseSegment, overlapSegment, tolerance = EDGE_TOLERANCE) {
    const baseStart = { x: baseSegment.x1, y: baseSegment.y1 };
    const baseEnd = { x: baseSegment.x2, y: baseSegment.y2 };
    const baseLength = getSegmentLength(baseStart, baseEnd);
    if (baseLength <= tolerance) {
        return null;
    }

    const overlapLength = getCollinearSegmentOverlapLength(baseSegment, overlapSegment, tolerance);
    if (overlapLength <= tolerance) {
        return null;
    }

    const otherStartDistance = getPointParameterOnSegment(baseStart, baseEnd, { x: overlapSegment.x1, y: overlapSegment.y1 });
    const otherEndDistance = getPointParameterOnSegment(baseStart, baseEnd, { x: overlapSegment.x2, y: overlapSegment.y2 });
    const startDistance = Math.max(0, Math.min(otherStartDistance, otherEndDistance));
    const endDistance = Math.min(baseLength, Math.max(otherStartDistance, otherEndDistance));

    return endDistance - startDistance > tolerance
        ? { startDistance, endDistance, baseLength }
        : null;
}

function getSegmentPointAtDistance(segment, distance) {
    const startPoint = { x: segment.x1, y: segment.y1 };
    const endPoint = { x: segment.x2, y: segment.y2 };
    const segmentLength = getSegmentLength(startPoint, endPoint);
    const parameter = segmentLength > EDGE_TOLERANCE
        ? Math.max(0, Math.min(1, distance / segmentLength))
        : 0;

    return {
        x: roundCoordinate(segment.x1 + ((segment.x2 - segment.x1) * parameter)),
        y: roundCoordinate(segment.y1 + ((segment.y2 - segment.y1) * parameter))
    };
}

function interpolateSlabClipVertex(startVertex, endVertex, parameter) {
    const clampedParameter = Math.max(0, Math.min(1, parameter));
    const interpolated = {
        x: roundCoordinate(startVertex.x + ((endVertex.x - startVertex.x) * clampedParameter)),
        y: roundCoordinate(startVertex.y + ((endVertex.y - startVertex.y) * clampedParameter))
    };
    const startZ = parseNumberOrFallback(startVertex.z, Number.NaN);
    const endZ = parseNumberOrFallback(endVertex.z, Number.NaN);
    if (Number.isFinite(startZ) && Number.isFinite(endZ)) {
        interpolated.z = roundCoordinate(startZ + ((endZ - startZ) * clampedParameter));
    }
    return interpolated;
}

function clipSlabVerticesByBeamPerpendicular(vertices, cutPoint, beamDirection, keepSign) {
    if (!Array.isArray(vertices) || vertices.length < 3 || !cutPoint || !beamDirection) {
        return [];
    }

    const signedValue = (point) => (
        (((point.x - cutPoint.x) * beamDirection.x) + ((point.y - cutPoint.y) * beamDirection.y)) * keepSign
    );
    const clipped = [];

    for (let index = 0; index < vertices.length; index += 1) {
        const current = cloneMetricPoint(vertices[index]);
        const next = cloneMetricPoint(vertices[(index + 1) % vertices.length]);
        const currentValue = signedValue(current);
        const nextValue = signedValue(next);
        const currentInside = currentValue >= -EDGE_TOLERANCE;
        const nextInside = nextValue >= -EDGE_TOLERANCE;

        if (currentInside) {
            clipped.push(current);
        }

        if (currentInside !== nextInside) {
            const denominator = currentValue - nextValue;
            if (Math.abs(denominator) > 1e-9) {
                clipped.push(interpolateSlabClipVertex(current, next, currentValue / denominator));
            }
        }
    }

    return cleanSlabSplitVertices(clipped);
}

function splitSlabByPartialBeamChord(slab, beam, chord, overlapInterval) {
    if (!overlapInterval) {
        return null;
    }

    const chordTolerance = Math.max(EDGE_TOLERANCE, overlapInterval.baseLength * 1e-4);
    const startsAtBoundary = overlapInterval.startDistance <= chordTolerance;
    const endsAtBoundary = overlapInterval.baseLength - overlapInterval.endDistance <= chordTolerance;

    if (startsAtBoundary === endsAtBoundary) {
        return null;
    }

    const boundaryPoint = startsAtBoundary
        ? { x: chord.x1, y: chord.y1 }
        : { x: chord.x2, y: chord.y2 };
    const cutPoint = startsAtBoundary
        ? getSegmentPointAtDistance(chord, overlapInterval.endDistance)
        : getSegmentPointAtDistance(chord, overlapInterval.startDistance);
    if (getSegmentLength(boundaryPoint, cutPoint) <= SLAB_BEAM_SPLIT_MIN_CHORD_LENGTH) {
        return null;
    }

    const chordStart = { x: chord.x1, y: chord.y1 };
    const chordEnd = { x: chord.x2, y: chord.y2 };
    const directionLength = getSegmentLength(chordStart, chordEnd);
    if (directionLength <= EDGE_TOLERANCE) {
        return null;
    }

    const beamDirection = {
        x: (chord.x2 - chord.x1) / directionLength,
        y: (chord.y2 - chord.y1) / directionLength
    };
    const referenceValue = ((boundaryPoint.x - cutPoint.x) * beamDirection.x)
        + ((boundaryPoint.y - cutPoint.y) * beamDirection.y);
    if (Math.abs(referenceValue) <= EDGE_TOLERANCE) {
        return null;
    }

    const activeSign = referenceValue >= 0 ? 1 : -1;
    const slabVertices = normalizeSlabVertices(slab).map(cloneMetricPoint);
    const activeVertices = clipSlabVerticesByBeamPerpendicular(slabVertices, cutPoint, beamDirection, activeSign);
    const inactiveVertices = clipSlabVerticesByBeamPerpendicular(slabVertices, cutPoint, beamDirection, -activeSign);
    if (
        activeVertices.length < 3
        || inactiveVertices.length < 3
        || Math.abs(getSlabPolygonArea(activeVertices)) <= SLAB_BEAM_SPLIT_MIN_AREA
        || Math.abs(getSlabPolygonArea(inactiveVertices)) <= SLAB_BEAM_SPLIT_MIN_AREA
    ) {
        return null;
    }

    const activeSlab = normalizeSlab({
        ...slab,
        vertices: activeVertices,
        pointIds: []
    });
    const activeSplitPieces = splitSlabByBoundaryChord(activeSlab, beam, {
        x1: boundaryPoint.x,
        y1: boundaryPoint.y,
        x2: cutPoint.x,
        y2: cutPoint.y
    });
    if (activeSplitPieces.length !== 2) {
        return null;
    }

    const inactivePiece = buildSplitSlabPiece(slab, beam, inactiveVertices, 2);
    return inactivePiece ? [...activeSplitPieces, inactivePiece] : null;
}

function splitSlabByBeam(slab, beam) {
    const normalizedSlab = normalizeSlab(slab);
    const normalizedBeam = normalizeBeamModel(beam);
    const vertices = normalizeSlabVertices(normalizedSlab);
    const beamSegment = {
        x1: normalizedBeam.x1,
        y1: normalizedBeam.y1,
        x2: normalizedBeam.x2,
        y2: normalizedBeam.y2
    };
    const beamLength = getSegmentLength(
        { x: beamSegment.x1, y: beamSegment.y1 },
        { x: beamSegment.x2, y: beamSegment.y2 }
    );
    if (vertices.length < 3 || beamLength <= SLAB_BEAM_SPLIT_MIN_CHORD_LENGTH) {
        return [normalizedSlab];
    }

    const extendedLine = createExtendedBeamLineForSlab(vertices, beamSegment);
    if (!extendedLine) {
        return [normalizedSlab];
    }

    const candidateChords = clipSegmentToPolygon(extendedLine, vertices)
        .filter((chord) => {
            const chordLength = getSegmentLength(
                { x: chord.x1, y: chord.y1 },
                { x: chord.x2, y: chord.y2 }
            );
            return chordLength > SLAB_BEAM_SPLIT_MIN_CHORD_LENGTH
                && doesBeamOverlapSlabSplitChord(beamSegment, chord);
        })
        .sort((left, right) => (
            getCollinearSegmentOverlapLength(right, beamSegment, EDGE_TOLERANCE)
            - getCollinearSegmentOverlapLength(left, beamSegment, EDGE_TOLERANCE)
        ));

    for (const chord of candidateChords) {
        const overlapInterval = getCollinearSegmentOverlapInterval(chord, beamSegment, EDGE_TOLERANCE);
        if (!overlapInterval) {
            continue;
        }

        const chordTolerance = Math.max(EDGE_TOLERANCE, overlapInterval.baseLength * 1e-4);
        const beamCoversFullChord = overlapInterval.startDistance <= chordTolerance
            && overlapInterval.baseLength - overlapInterval.endDistance <= chordTolerance;

        if (!beamCoversFullChord) {
            const partialPieces = splitSlabByPartialBeamChord(normalizedSlab, normalizedBeam, chord, overlapInterval);
            if (Array.isArray(partialPieces) && partialPieces.length > 1) {
                return partialPieces;
            }
            continue;
        }

        const pieces = splitSlabByBoundaryChord(normalizedSlab, normalizedBeam, chord);
        if (pieces.length > 1) {
            return pieces;
        }
    }

    return [normalizedSlab];
}

function splitSlabsByBeams(slabs = [], beams = []) {
    const normalizedBeams = (Array.isArray(beams) ? beams : [])
        .map((beam) => normalizeBeamModel(beam))
        .filter((beam) => getSegmentLength({ x: beam.x1, y: beam.y1 }, { x: beam.x2, y: beam.y2 }) > SLAB_BEAM_SPLIT_MIN_CHORD_LENGTH);
    let currentSlabs = (Array.isArray(slabs) ? slabs : []).map((slab) => normalizeSlab(slab));

    normalizedBeams.forEach((beam) => {
        currentSlabs = currentSlabs.flatMap((slab) => splitSlabByBeam(slab, beam));
    });

    return currentSlabs;
}

function splitLevelSlabsByBeams(level) {
    if (!level) {
        return 0;
    }

    const originalCount = Array.isArray(level.slabs) ? level.slabs.length : 0;
    level.slabs = splitSlabsByBeams(level.slabs || [], level.beams || []);
    return Math.max(0, level.slabs.length - originalCount);
}


function getSmartSlabSplitPieceId(slab, index) {
    const slabFragment = getSlabSplitIdFragment(slab?.id, "slab");
    return `${slabFragment}-panel-${index + 1}`;
}

function buildSmartSplitSlabPiece(slab, vertices, index) {
    const cleanedVertices = cleanSlabSplitVertices(vertices);
    if (cleanedVertices.length < 3 || Math.abs(getSlabPolygonArea(cleanedVertices)) <= SLAB_BEAM_SPLIT_MIN_AREA) {
        return null;
    }

    return normalizeSlab({
        ...slab,
        id: getSmartSlabSplitPieceId(slab, index),
        vertices: cleanedVertices,
        pointIds: []
    });
}

function getSmartDividerSegmentLength(segment) {
    return getSegmentLength(
        { x: segment.x1, y: segment.y1 },
        { x: segment.x2, y: segment.y2 }
    );
}

function normalizeSmartDividerSegment(segment, type = "support", source = null) {
    const normalized = {
        x1: roundCoordinate(segment?.x1),
        y1: roundCoordinate(segment?.y1),
        x2: roundCoordinate(segment?.x2),
        y2: roundCoordinate(segment?.y2),
        type,
        source
    };
    return Number.isFinite(normalized.x1)
        && Number.isFinite(normalized.y1)
        && Number.isFinite(normalized.x2)
        && Number.isFinite(normalized.y2)
        && getSmartDividerSegmentLength(normalized) > SLAB_BEAM_SPLIT_MIN_CHORD_LENGTH
        ? normalized
        : null;
}

function isSmartDividerSegmentDuplicate(existingSegments, candidate, tolerance = EDGE_TOLERANCE) {
    return existingSegments.some((segment) => (
        (
            areMetricPointsEqual({ x: segment.x1, y: segment.y1 }, { x: candidate.x1, y: candidate.y1 }, tolerance)
            && areMetricPointsEqual({ x: segment.x2, y: segment.y2 }, { x: candidate.x2, y: candidate.y2 }, tolerance)
        )
        || (
            areMetricPointsEqual({ x: segment.x1, y: segment.y1 }, { x: candidate.x2, y: candidate.y2 }, tolerance)
            && areMetricPointsEqual({ x: segment.x2, y: segment.y2 }, { x: candidate.x1, y: candidate.y1 }, tolerance)
        )
    ));
}

function addSmartDividerSegment(segments, segment, type = "support", source = null) {
    const normalized = normalizeSmartDividerSegment(segment, type, source);
    if (!normalized || isSmartDividerSegmentDuplicate(segments, normalized)) {
        return;
    }
    segments.push(normalized);
}

function getSmartSlabHoleVerticesInsideSlab(slabVertices, holes = []) {
    return (Array.isArray(holes) ? holes : [])
        .map((hole) => normalizeSlabVertices(hole))
        .filter((vertices) => (
            vertices.length >= 3
            && Math.abs(getSlabPolygonArea(vertices)) > SLAB_BEAM_SPLIT_MIN_AREA
            && isPointInPolygon(getSlabCentroid(vertices), slabVertices)
        ));
}

function collectSmartSlabDividerSegments(slab, level) {
    const slabVertices = normalizeSlabVertices(slab);
    const segments = [];
    getPolygonSegments(slabVertices).forEach((segment) => {
        addSmartDividerSegment(segments, segment, "slab-boundary", slab?.id || null);
    });

    getSmartSlabHoleVerticesInsideSlab(slabVertices, level?.holes).forEach((holeVertices) => {
        getPolygonSegments(holeVertices).forEach((segment) => {
            addSmartDividerSegment(segments, segment, "hole-boundary", slab?.id || null);
        });
    });

    (Array.isArray(level?.beams) ? level.beams : []).forEach((beam) => {
        const normalizedBeam = normalizeBeamModel(beam);
        const beamSegment = {
            x1: normalizedBeam.x1,
            y1: normalizedBeam.y1,
            x2: normalizedBeam.x2,
            y2: normalizedBeam.y2
        };
        clipSegmentToPolygon(beamSegment, slabVertices).forEach((segment) => {
            addSmartDividerSegment(segments, segment, "beam", normalizedBeam.id || null);
        });
    });

    (Array.isArray(level?.walls) ? level.walls : []).forEach((wall) => {
        const normalizedWall = normalizeWall(wall);
        const wallSegment = {
            x1: normalizedWall.x1,
            y1: normalizedWall.y1,
            x2: normalizedWall.x2,
            y2: normalizedWall.y2
        };
        clipSegmentToPolygon(wallSegment, slabVertices).forEach((segment) => {
            addSmartDividerSegment(segments, segment, "wall", normalizedWall.id || null);
        });
    });

    return segments;
}

function getSmartSegmentParameter(segment, point) {
    const dx = segment.x2 - segment.x1;
    const dy = segment.y2 - segment.y1;
    const lengthSquared = dx * dx + dy * dy;
    if (lengthSquared <= 1e-12) {
        return 0;
    }
    return (((point.x - segment.x1) * dx) + ((point.y - segment.y1) * dy)) / lengthSquared;
}

function addSmartSegmentParameter(parameters, value) {
    if (!Number.isFinite(value)) {
        return;
    }
    const normalized = Math.max(0, Math.min(1, value));
    if (!parameters.some((parameter) => Math.abs(parameter - normalized) <= 1e-6)) {
        parameters.push(normalized);
    }
}

function areSegmentsCollinear(segmentA, segmentB, tolerance = EDGE_TOLERANCE) {
    const lengthA = getSmartDividerSegmentLength(segmentA);
    if (lengthA <= tolerance) {
        return false;
    }
    const crossOne = Math.abs(
        ((segmentA.x2 - segmentA.x1) * (segmentB.y1 - segmentA.y1))
        - ((segmentA.y2 - segmentA.y1) * (segmentB.x1 - segmentA.x1))
    ) / lengthA;
    const crossTwo = Math.abs(
        ((segmentA.x2 - segmentA.x1) * (segmentB.y2 - segmentA.y1))
        - ((segmentA.y2 - segmentA.y1) * (segmentB.x2 - segmentA.x1))
    ) / lengthA;
    return crossOne <= tolerance && crossTwo <= tolerance;
}

function getSmartSegmentSplitParameters(segment, allSegments, segmentIndex) {
    const parameters = [0, 1];
    allSegments.forEach((otherSegment, otherIndex) => {
        if (otherIndex === segmentIndex) {
            return;
        }

        const intersectionParameter = getSegmentIntersectionParameter(segment, otherSegment, SMART_SLAB_CONNECT_TOLERANCE);
        if (Number.isFinite(intersectionParameter)) {
            addSmartSegmentParameter(parameters, intersectionParameter);
        }

        if (!areSegmentsCollinear(segment, otherSegment)) {
            return;
        }

        [
            { x: otherSegment.x1, y: otherSegment.y1 },
            { x: otherSegment.x2, y: otherSegment.y2 }
        ].forEach((point) => {
            if (isPointOnSegment(point, { x: segment.x1, y: segment.y1 }, { x: segment.x2, y: segment.y2 }, SMART_SLAB_CONNECT_TOLERANCE)) {
                addSmartSegmentParameter(parameters, getSmartSegmentParameter(segment, point));
            }
        });
    });

    return parameters.sort((left, right) => left - right);
}

function findOrCreateSmartSlabNode(nodes, point, tolerance = SMART_SLAB_CONNECT_TOLERANCE) {
    const existingIndex = nodes.findIndex((node) => areMetricPointsEqual(node, point, tolerance));
    if (existingIndex >= 0) {
        return existingIndex;
    }
    nodes.push({ x: roundCoordinate(point.x), y: roundCoordinate(point.y) });
    return nodes.length - 1;
}

function getSmartSlabGraphEdgeKey(startIndex, endIndex) {
    return startIndex < endIndex
        ? `${startIndex}:${endIndex}`
        : `${endIndex}:${startIndex}`;
}

function buildSmartSlabDividerGraph(segments) {
    const nodes = [];
    const edges = [];
    const edgeKeys = new Set();

    segments.forEach((segment, segmentIndex) => {
        const parameters = getSmartSegmentSplitParameters(segment, segments, segmentIndex);
        for (let index = 0; index < parameters.length - 1; index += 1) {
            const startParameter = parameters[index];
            const endParameter = parameters[index + 1];
            if (endParameter - startParameter <= 1e-6) {
                continue;
            }

            const startPoint = getSegmentPointAt(segment, startParameter);
            const endPoint = getSegmentPointAt(segment, endParameter);
            if (getSegmentLength(startPoint, endPoint) <= SLAB_BEAM_SPLIT_MIN_CHORD_LENGTH) {
                continue;
            }

            const startIndex = findOrCreateSmartSlabNode(nodes, startPoint);
            const endIndex = findOrCreateSmartSlabNode(nodes, endPoint);
            if (startIndex === endIndex) {
                continue;
            }

            const edgeKey = getSmartSlabGraphEdgeKey(startIndex, endIndex);
            if (edgeKeys.has(edgeKey)) {
                continue;
            }
            edgeKeys.add(edgeKey);
            edges.push({ startIndex, endIndex, type: segment.type, source: segment.source });
        }
    });

    return { nodes, edges };
}

function pruneSmartSlabGraphDeadEndEdges(graph) {
    const nodes = Array.isArray(graph?.nodes) ? graph.nodes : [];
    let edges = Array.isArray(graph?.edges) ? graph.edges.slice() : [];
    let changed = true;

    while (changed && edges.length) {
        const degrees = new Array(nodes.length).fill(0);
        edges.forEach((edge) => {
            degrees[edge.startIndex] = (degrees[edge.startIndex] || 0) + 1;
            degrees[edge.endIndex] = (degrees[edge.endIndex] || 0) + 1;
        });

        const nextEdges = edges.filter((edge) => degrees[edge.startIndex] > 1 && degrees[edge.endIndex] > 1);
        changed = nextEdges.length !== edges.length;
        edges = nextEdges;
    }

    return { nodes, edges };
}

function getSmartSlabTargetArea(slabVertices, holeVerticesList = []) {
    const slabArea = Math.abs(getSlabPolygonArea(slabVertices));
    const holeArea = (Array.isArray(holeVerticesList) ? holeVerticesList : []).reduce((total, holeVertices) => {
        const centroid = getSlabCentroid(holeVertices);
        return isPointInPolygon(centroid, slabVertices)
            ? total + Math.abs(getSlabPolygonArea(holeVertices))
            : total;
    }, 0);
    return Math.max(0, slabArea - holeArea);
}

function doSmartSlabFacesCoverTargetArea(faces, slabVertices, holeVerticesList = []) {
    const targetArea = getSmartSlabTargetArea(slabVertices, holeVerticesList);
    if (!(targetArea > SLAB_BEAM_SPLIT_MIN_AREA)) {
        return false;
    }

    const facesArea = (Array.isArray(faces) ? faces : []).reduce((total, vertices) => (
        total + Math.abs(getSlabPolygonArea(vertices))
    ), 0);
    const tolerance = Math.max(SLAB_BEAM_SPLIT_MIN_AREA, targetArea * 0.01);
    return facesArea >= targetArea - tolerance && facesArea <= targetArea + tolerance;
}

function findSmartSlabGraphFaces(graph) {
    const nodes = graph?.nodes || [];
    const edges = graph?.edges || [];
    const adjacency = new Map();
    nodes.forEach((node, index) => adjacency.set(index, []));
    edges.forEach((edge) => {
        adjacency.get(edge.startIndex)?.push(edge.endIndex);
        adjacency.get(edge.endIndex)?.push(edge.startIndex);
    });

    adjacency.forEach((neighbors, nodeIndex) => {
        neighbors.sort((leftIndex, rightIndex) => {
            const leftNode = nodes[leftIndex];
            const rightNode = nodes[rightIndex];
            const node = nodes[nodeIndex];
            return Math.atan2(leftNode.y - node.y, leftNode.x - node.x)
                - Math.atan2(rightNode.y - node.y, rightNode.x - node.x);
        });
    });

    const visited = new Set();
    const faces = [];
    edges.forEach((edge) => {
        [
            [edge.startIndex, edge.endIndex],
            [edge.endIndex, edge.startIndex]
        ].forEach(([startIndex, endIndex]) => {
            const startKey = `${startIndex}:${endIndex}`;
            if (visited.has(startKey)) {
                return;
            }

            const faceNodeIndexes = [];
            let currentStartIndex = startIndex;
            let currentEndIndex = endIndex;
            for (let guard = 0; guard < edges.length * 4 + nodes.length * 4 + 20; guard += 1) {
                const directedKey = `${currentStartIndex}:${currentEndIndex}`;
                if (visited.has(directedKey)) {
                    break;
                }
                visited.add(directedKey);
                faceNodeIndexes.push(currentStartIndex);

                const neighbors = adjacency.get(currentEndIndex) || [];
                const reverseNeighborIndex = neighbors.indexOf(currentStartIndex);
                if (reverseNeighborIndex < 0 || !neighbors.length) {
                    break;
                }

                const nextNeighborIndex = (reverseNeighborIndex - 1 + neighbors.length) % neighbors.length;
                const nextEndIndex = neighbors[nextNeighborIndex];
                currentStartIndex = currentEndIndex;
                currentEndIndex = nextEndIndex;

                if (currentStartIndex === startIndex && currentEndIndex === endIndex) {
                    faces.push(faceNodeIndexes);
                    break;
                }
            }
        });
    });

    return faces;
}

function smartSlabFaceHasRepeatedNode(faceNodeIndexes) {
    const uniqueNodes = new Set(faceNodeIndexes);
    return uniqueNodes.size !== faceNodeIndexes.length;
}

function getSmartSlabFaceVertices(faceNodeIndexes, nodes) {
    return cleanSlabSplitVertices(faceNodeIndexes.map((nodeIndex) => nodes[nodeIndex]));
}

function getSmartSlabFaceSignature(vertices) {
    return vertices
        .map((vertex) => `${roundCoordinate(vertex.x).toFixed(4)},${roundCoordinate(vertex.y).toFixed(4)}`)
        .sort()
        .join("|");
}

function isSmartSlabFaceInsideHole(vertices, holeVerticesList) {
    const centroid = getSlabCentroid(vertices);
    return holeVerticesList.some((holeVertices) => isPointInPolygon(centroid, holeVertices));
}

function getSmartStructuralDividerSegmentsForFallback(level = {}) {
    const segments = [];
    (Array.isArray(level?.beams) ? level.beams : []).forEach((beam) => {
        const normalizedBeam = normalizeBeamModel(beam);
        const segment = normalizeSmartDividerSegment({
            x1: normalizedBeam.x1,
            y1: normalizedBeam.y1,
            x2: normalizedBeam.x2,
            y2: normalizedBeam.y2
        }, "beam", normalizedBeam.id || null);
        if (segment) {
            segments.push(segment);
        }
    });

    (Array.isArray(level?.walls) ? level.walls : []).forEach((wall) => {
        const normalizedWall = normalizeWall(wall);
        const segment = normalizeSmartDividerSegment({
            x1: normalizedWall.x1,
            y1: normalizedWall.y1,
            x2: normalizedWall.x2,
            y2: normalizedWall.y2
        }, "wall", normalizedWall.id || null);
        if (segment) {
            segments.push(segment);
        }
    });

    return segments;
}

function splitSlabByFullStructuralDivider(slab, dividerSegment) {
    const normalizedSlab = normalizeSlab(slab);
    const vertices = normalizeSlabVertices(normalizedSlab);
    const segment = normalizeSmartDividerSegment(dividerSegment, dividerSegment?.type || "support", dividerSegment?.source || null);
    if (!segment || vertices.length < 3) {
        return [normalizedSlab];
    }

    const extendedLine = createExtendedBeamLineForSlab(vertices, segment);
    if (!extendedLine) {
        return [normalizedSlab];
    }

    const candidateChords = clipSegmentToPolygon(extendedLine, vertices)
        .filter((chord) => {
            const chordLength = getSegmentLength(
                { x: chord.x1, y: chord.y1 },
                { x: chord.x2, y: chord.y2 }
            );
            if (chordLength <= SLAB_BEAM_SPLIT_MIN_CHORD_LENGTH) {
                return false;
            }
            const overlapInterval = getCollinearSegmentOverlapInterval(chord, segment, SMART_SLAB_CONNECT_TOLERANCE);
            if (!overlapInterval) {
                return false;
            }
            const chordTolerance = Math.max(SMART_SLAB_CONNECT_TOLERANCE, overlapInterval.baseLength * 1e-4);
            return overlapInterval.startDistance <= chordTolerance
                && overlapInterval.baseLength - overlapInterval.endDistance <= chordTolerance;
        })
        .sort((left, right) => (
            getCollinearSegmentOverlapLength(right, segment, SMART_SLAB_CONNECT_TOLERANCE)
            - getCollinearSegmentOverlapLength(left, segment, SMART_SLAB_CONNECT_TOLERANCE)
        ));

    for (const chord of candidateChords) {
        const pieces = splitSlabByBoundaryChord(normalizedSlab, {
            id: segment.source || `${segment.type || "support"}-${roundCoordinate(segment.x1)}-${roundCoordinate(segment.y1)}-${roundCoordinate(segment.x2)}-${roundCoordinate(segment.y2)}`,
            x1: segment.x1,
            y1: segment.y1,
            x2: segment.x2,
            y2: segment.y2
        }, chord);
        if (pieces.length > 1) {
            return pieces;
        }
    }

    return [normalizedSlab];
}

function splitSlabByFullStructuralDividers(slab, level = {}) {
    let pieces = [normalizeSlab(slab)];
    getSmartStructuralDividerSegmentsForFallback(level).forEach((segment) => {
        pieces = pieces.flatMap((piece) => splitSlabByFullStructuralDivider(piece, segment));
    });
    return pieces;
}

function splitSlabByStructuralDividerGraph(slab, level) {
    const normalizedSlab = normalizeSlab(slab);
    const slabVertices = normalizeSlabVertices(normalizedSlab);
    if (slabVertices.length < 3 || Math.abs(getSlabPolygonArea(slabVertices)) <= SLAB_BEAM_SPLIT_MIN_AREA) {
        return [normalizedSlab];
    }

    const dividerSegments = collectSmartSlabDividerSegments(normalizedSlab, level);
    const structuralDividerCount = dividerSegments.filter((segment) => segment.type === "beam" || segment.type === "wall").length;
    if (structuralDividerCount <= 0) {
        return [normalizedSlab];
    }

    const graph = pruneSmartSlabGraphDeadEndEdges(buildSmartSlabDividerGraph(dividerSegments));
    if (graph.edges.length < 3) {
        const fullDividerFallbackPieces = splitSlabByFullStructuralDividers(normalizedSlab, level);
        return fullDividerFallbackPieces.length > 1 ? fullDividerFallbackPieces : [normalizedSlab];
    }

    const holeVerticesList = getSmartSlabHoleVerticesInsideSlab(slabVertices, level?.holes);
    const faceSignatures = new Set();
    const faces = findSmartSlabGraphFaces(graph)
        .filter((faceNodeIndexes) => faceNodeIndexes.length >= 3 && !smartSlabFaceHasRepeatedNode(faceNodeIndexes))
        .map((faceNodeIndexes) => getSmartSlabFaceVertices(faceNodeIndexes, graph.nodes))
        .filter((vertices) => {
            if (vertices.length < 3) {
                return false;
            }
            const area = getSlabPolygonArea(vertices);
            if (area <= SLAB_BEAM_SPLIT_MIN_AREA) {
                return false;
            }
            const centroid = getSlabCentroid(vertices);
            if (!isPointInPolygon(centroid, slabVertices) || isSmartSlabFaceInsideHole(vertices, holeVerticesList)) {
                return false;
            }
            const signature = getSmartSlabFaceSignature(vertices);
            if (faceSignatures.has(signature)) {
                return false;
            }
            faceSignatures.add(signature);
            return true;
        })
        .sort((left, right) => {
            const leftCentroid = getSlabCentroid(left);
            const rightCentroid = getSlabCentroid(right);
            if (Math.abs(leftCentroid.y - rightCentroid.y) > EDGE_TOLERANCE) {
                return leftCentroid.y - rightCentroid.y;
            }
            return leftCentroid.x - rightCentroid.x;
        });

    if (faces.length <= 1 || !doSmartSlabFacesCoverTargetArea(faces, slabVertices, holeVerticesList)) {
        const fullDividerFallbackPieces = splitSlabByFullStructuralDividers(normalizedSlab, level);
        return fullDividerFallbackPieces.length > 1 ? fullDividerFallbackPieces : [normalizedSlab];
    }

    const pieces = faces
        .map((vertices, index) => buildSmartSplitSlabPiece(normalizedSlab, vertices, index))
        .filter(Boolean);

    return pieces.length > 1 ? pieces : [normalizedSlab];
}

function splitSlabsByStructuralDividerGraph(slabs = [], level = {}) {
    return (Array.isArray(slabs) ? slabs : []).flatMap((slab) => splitSlabByStructuralDividerGraph(slab, level));
}

function splitLevelSlabsByEtabsStructuralSupports(level) {
    if (!level) {
        return 0;
    }

    const originalCount = Array.isArray(level.slabs) ? level.slabs.length : 0;
    level.slabs = splitSlabsByStructuralDividerGraph(level.slabs || [], level);
    return Math.max(0, level.slabs.length - originalCount);
}

function areClose(valueA, valueB, tolerance = EDGE_TOLERANCE) {
    return Math.abs(valueA - valueB) <= tolerance;
}

function getIntervalOverlap(startA, endA, startB, endB) {
    return Math.max(0, Math.min(endA, endB) - Math.max(startA, startB));
}

function createSolidSlabClipRectangle(x1, y1, x2, y2) {
    const left = Math.min(x1, x2);
    const right = Math.max(x1, x2);
    const bottom = Math.min(y1, y2);
    const top = Math.max(y1, y2);

    if (right - left <= EDGE_TOLERANCE || top - bottom <= EDGE_TOLERANCE) {
        return null;
    }

    return {
        vertices: [
            { x: left, y: bottom },
            { x: right, y: bottom },
            { x: right, y: top },
            { x: left, y: top }
        ]
    };
}

function getSlabSideInfo(bounds, side) {
    if (side === "left" || side === "right") {
        return {
            side,
            axis: "x",
            direction: side === "left" ? -1 : 1,
            coordinate: side === "left" ? bounds.x1 : bounds.x2,
            perpMin: bounds.y1,
            perpMax: bounds.y2
        };
    }

    return {
        side,
        axis: "y",
        direction: side === "bottom" ? -1 : 1,
        coordinate: side === "bottom" ? bounds.y1 : bounds.y2,
        perpMin: bounds.x1,
        perpMax: bounds.x2
    };
}

function getSolidSlabSideForAxisDirection(axis, direction) {
    if (axis === "x") {
        return direction < 0 ? "left" : "right";
    }

    return direction < 0 ? "bottom" : "top";
}

function normalizeSolidSlabSupportContext(context) {
    if (!context) {
        return null;
    }

    const normalizeSupportGeometry = (element, fallbackThickness) => ({
        x1: parseNumberOrFallback(element?.x1, 0),
        y1: parseNumberOrFallback(element?.y1, 0),
        x2: parseNumberOrFallback(element?.x2, element?.x1 ?? 0),
        y2: parseNumberOrFallback(element?.y2, element?.y1 ?? 0),
        b: parsePositiveNumberOrFallback(
            element?.b ?? element?.width ?? element?.thickness,
            fallbackThickness,
            0.01
        )
    });

    // Only support geometry is needed here. Fully normalizing imported beam
    // reinforcement for every slab side makes large ETABS projects quadratic.
    return {
        beams: Array.isArray(context.beams)
            ? context.beams.map((beam) => normalizeSupportGeometry(beam, 0.3))
            : [],
        walls: Array.isArray(context.walls)
            ? context.walls.map((wall) => normalizeSupportGeometry(wall, DEFAULT_WALL_THICKNESS))
            : []
    };
}

function getAxisAlignedSupportSpansForSide(supportContext, side) {
    const context = normalizeSolidSlabSupportContext(supportContext);
    if (!context) {
        return [];
    }

    const spans = [];
    const supportTolerance = Math.max(EDGE_TOLERANCE, 0.04);
    const needsVerticalSupport = side === "left" || side === "right";
    const addSupport = (element, thickness) => {
        const x1 = parseNumberOrFallback(element?.x1, 0);
        const y1 = parseNumberOrFallback(element?.y1, 0);
        const x2 = parseNumberOrFallback(element?.x2, x1);
        const y2 = parseNumberOrFallback(element?.y2, y1);
        const dx = x2 - x1;
        const dy = y2 - y1;
        const isVertical = Math.abs(dx) <= supportTolerance && Math.abs(dy) > EDGE_TOLERANCE;
        const isHorizontal = Math.abs(dy) <= supportTolerance && Math.abs(dx) > EDGE_TOLERANCE;
        const halfThickness = parsePositiveNumberOrFallback(thickness, 0, 0) / 2;

        if (!(halfThickness > 0)) {
            return;
        }

        if (needsVerticalSupport && isVertical) {
            const center = (x1 + x2) / 2;
            spans.push({
                axisMin: center - halfThickness,
                axisMax: center + halfThickness,
                perpMin: Math.min(y1, y2),
                perpMax: Math.max(y1, y2)
            });
            return;
        }

        if (!needsVerticalSupport && isHorizontal) {
            const center = (y1 + y2) / 2;
            spans.push({
                axisMin: center - halfThickness,
                axisMax: center + halfThickness,
                perpMin: Math.min(x1, x2),
                perpMax: Math.max(x1, x2)
            });
        }
    };

    context.beams.forEach((beam) => addSupport(beam, beam.b));
    context.walls.forEach((wall) => addSupport(wall, wall.b));

    return spans;
}

function getSolidSlabSupportExteriorInfo(supportContext, slab, side) {
    const bounds = normalizeSlabBounds(slab);
    const sideInfo = getSlabSideInfo(bounds, side);
    const supportTolerance = Math.max(EDGE_TOLERANCE, 0.04);
    let bestMatch = null;

    getAxisAlignedSupportSpansForSide(supportContext, side).forEach((support) => {
        const overlapsSide = getIntervalOverlap(
            support.perpMin,
            support.perpMax,
            sideInfo.perpMin,
            sideInfo.perpMax
        ) > EDGE_TOLERANCE;

        if (!overlapsSide) {
            return;
        }

        const isOnSupport = sideInfo.coordinate >= support.axisMin - supportTolerance
            && sideInfo.coordinate <= support.axisMax + supportTolerance;
        if (!isOnSupport) {
            return;
        }

        const exteriorCoordinate = sideInfo.direction < 0 ? support.axisMin : support.axisMax;
        const offset = Math.max(
            sideInfo.direction < 0
                ? sideInfo.coordinate - exteriorCoordinate
                : exteriorCoordinate - sideInfo.coordinate,
            0
        );

        if (!bestMatch || offset > bestMatch.offset) {
            bestMatch = {
                exteriorCoordinate,
                offset,
                support
            };
        }
    });

    return bestMatch;
}

function getSolidSlabSideSupportClipRegion(supportContext, slab, side) {
    const bounds = normalizeSlabBounds(slab);
    const sideInfo = getSlabSideInfo(bounds, side);
    const supportInfo = getSolidSlabSupportExteriorInfo(supportContext, slab, side);

    if (!supportInfo) {
        return null;
    }

    if (sideInfo.axis === "x") {
        return createSolidSlabClipRectangle(
            sideInfo.coordinate,
            bounds.y1,
            supportInfo.exteriorCoordinate,
            bounds.y2
        );
    }

    return createSolidSlabClipRectangle(
        bounds.x1,
        sideInfo.coordinate,
        bounds.x2,
        supportInfo.exteriorCoordinate
    );
}

function getSolidSlabSupportBridgeClipRegion(supportContext, slab, neighbor, side) {
    if (!supportContext || !neighbor) {
        return null;
    }

    const currentBounds = normalizeSlabBounds(slab);
    const neighborBounds = normalizeSlabBounds(neighbor);
    const isHorizontalBridge = side === "left" || side === "right";
    const gapStart = side === "right"
        ? currentBounds.x2
        : side === "left"
            ? neighborBounds.x2
            : side === "top"
                ? currentBounds.y2
                : neighborBounds.y2;
    const gapEnd = side === "right"
        ? neighborBounds.x1
        : side === "left"
            ? currentBounds.x1
            : side === "top"
                ? neighborBounds.y1
                : currentBounds.y1;

    if (gapEnd - gapStart <= EDGE_TOLERANCE) {
        return null;
    }

    const perpMin = isHorizontalBridge
        ? Math.max(currentBounds.y1, neighborBounds.y1)
        : Math.max(currentBounds.x1, neighborBounds.x1);
    const perpMax = isHorizontalBridge
        ? Math.min(currentBounds.y2, neighborBounds.y2)
        : Math.min(currentBounds.x2, neighborBounds.x2);

    if (perpMax - perpMin <= EDGE_TOLERANCE) {
        return null;
    }

    const supportTolerance = Math.max(EDGE_TOLERANCE, 0.04);
    const support = getAxisAlignedSupportSpansForSide(supportContext, side).find((candidate) => (
        candidate.axisMin <= gapStart + supportTolerance
        && candidate.axisMax >= gapEnd - supportTolerance
        && getIntervalOverlap(candidate.perpMin, candidate.perpMax, perpMin, perpMax) > EDGE_TOLERANCE
    ));

    if (!support) {
        return null;
    }

    const clippedPerpMin = Math.max(perpMin, support.perpMin);
    const clippedPerpMax = Math.min(perpMax, support.perpMax);
    if (clippedPerpMax - clippedPerpMin <= EDGE_TOLERANCE) {
        return null;
    }

    return isHorizontalBridge
        ? createSolidSlabClipRectangle(gapStart, clippedPerpMin, gapEnd, clippedPerpMax)
        : createSolidSlabClipRectangle(clippedPerpMin, gapStart, clippedPerpMax, gapEnd);
}

function getSolidSlabAxisEdgeCoordinate(bounds, slab, axis, side, supportContext) {
    const sideInfo = getSlabSideInfo(bounds, side);
    const supportInfo = getSolidSlabSupportExteriorInfo(supportContext, slab, side);

    if (supportInfo) {
        // A 180-degree slab hook projects one bend radius beyond its tangent
        // in the support-normal direction.  Move the tangent inward by that
        // radius, which keeps the whole arc contained by the beam/wall outer
        // face instead of allowing it to cross the exterior line.
        const hookFaceInset = SOLID_SLAB_HOOK_BEND_RADIUS + 0.002;
        return sideInfo.direction < 0
            ? supportInfo.exteriorCoordinate + hookFaceInset
            : supportInfo.exteriorCoordinate - hookFaceInset;
    }

    return sideInfo.direction < 0
        ? sideInfo.coordinate + DRAWING_COVER
        : sideInfo.coordinate - DRAWING_COVER;
}

function findAdjacentSlab(slabs, slab, side, supportContext = null) {
    const current = normalizeSlab(slab);
    const perpendicularSpan = side === "left" || side === "right"
        ? current.y2 - current.y1
        : current.x2 - current.x1;
    const minimumOverlap = perpendicularSpan * SOLID_SLAB_MIN_SHARED_EDGE_RATIO;
    let bestMatch = null;
    let bestOverlap = minimumOverlap;

    (slabs || []).forEach((candidate) => {
        const neighbor = normalizeSlab(candidate);
        if (neighbor.id === current.id) {
            return;
        }

        let isCandidateOnSide = false;
        let touchesCurrent = false;
        let crossesSupport = false;
        let overlap = 0;

        if (side === "left") {
            const gap = current.x1 - neighbor.x2;
            isCandidateOnSide = gap >= -EDGE_TOLERANCE;
            touchesCurrent = areClose(neighbor.x2, current.x1);
            crossesSupport = gap > EDGE_TOLERANCE
                && Boolean(getSolidSlabSupportBridgeClipRegion(supportContext, current, neighbor, side));
            overlap = getIntervalOverlap(neighbor.y1, neighbor.y2, current.y1, current.y2);
        } else if (side === "right") {
            const gap = neighbor.x1 - current.x2;
            isCandidateOnSide = gap >= -EDGE_TOLERANCE;
            touchesCurrent = areClose(neighbor.x1, current.x2);
            crossesSupport = gap > EDGE_TOLERANCE
                && Boolean(getSolidSlabSupportBridgeClipRegion(supportContext, current, neighbor, side));
            overlap = getIntervalOverlap(neighbor.y1, neighbor.y2, current.y1, current.y2);
        } else if (side === "bottom") {
            const gap = current.y1 - neighbor.y2;
            isCandidateOnSide = gap >= -EDGE_TOLERANCE;
            touchesCurrent = areClose(neighbor.y2, current.y1);
            crossesSupport = gap > EDGE_TOLERANCE
                && Boolean(getSolidSlabSupportBridgeClipRegion(supportContext, current, neighbor, side));
            overlap = getIntervalOverlap(neighbor.x1, neighbor.x2, current.x1, current.x2);
        } else if (side === "top") {
            const gap = neighbor.y1 - current.y2;
            isCandidateOnSide = gap >= -EDGE_TOLERANCE;
            touchesCurrent = areClose(neighbor.y1, current.y2);
            crossesSupport = gap > EDGE_TOLERANCE
                && Boolean(getSolidSlabSupportBridgeClipRegion(supportContext, current, neighbor, side));
            overlap = getIntervalOverlap(neighbor.x1, neighbor.x2, current.x1, current.x2);
        }

        if (!isCandidateOnSide || (!touchesCurrent && !crossesSupport) || overlap <= bestOverlap) {
            return;
        }

        bestMatch = neighbor;
        bestOverlap = overlap;
    });

    return bestMatch;
}

function getSolidSlabAxisSpan(bounds, axis) {
    return axis === "x"
        ? bounds.x2 - bounds.x1
        : bounds.y2 - bounds.y1;
}

function getSolidSlabAxisLimits(bounds, axis) {
    return axis === "x"
        ? { start: bounds.x1 + DRAWING_COVER, end: bounds.x2 - DRAWING_COVER }
        : { start: bounds.y1 + DRAWING_COVER, end: bounds.y2 - DRAWING_COVER };
}

function getSolidSlabRepresentativeOffset(bounds, axis) {
    const perpendicularSpan = axis === "x" ? bounds.y2 - bounds.y1 : bounds.x2 - bounds.x1;
    return Math.max(
        Math.min(SOLID_SLAB_PAIR_SEPARATION, Math.max(perpendicularSpan - DRAWING_COVER * 4, 0.05)),
        0.05
    );
}

function getSolidSlabPerpendicularLimits(bounds, axis) {
    return axis === "x"
        ? { min: bounds.y1 + DRAWING_COVER, max: bounds.y2 - DRAWING_COVER }
        : { min: bounds.x1 + DRAWING_COVER, max: bounds.x2 - DRAWING_COVER };
}

function clampSolidSlabCoordinate(value, min, max) {
    return Math.min(Math.max(value, min), max);
}

function getSolidSlabAlternatingAnchor(slabs, slab, axis) {
    const bounds = normalizeSlabBounds(slab);
    const coordinateKey = axis === "x" ? "x1" : "y1";
    const sortedStarts = Array.from(new Set(
        (slabs || [])
            .map((item) => Number(normalizeSlabBounds(item)[coordinateKey].toFixed(3)))
            .sort((a, b) => a - b)
    ));
    const currentStart = Number(bounds[coordinateKey].toFixed(3));
    const startIndex = sortedStarts.findIndex((value) => areClose(value, currentStart, EDGE_TOLERANCE));
    const ratio = startIndex >= 0 && startIndex % 2 === 1 ? 0.75 : 0.25;
    const span = axis === "x" ? bounds.y2 - bounds.y1 : bounds.x2 - bounds.x1;
    const base = axis === "x" ? bounds.y1 : bounds.x1;
    return base + span * ratio;
}

function getSolidSlabChainAlternatingAnchor(slabs, slab, axis, supportContext = null) {
    const bounds = normalizeSlabBounds(slab);
    const negativeSide = axis === "x" ? "left" : "bottom";
    const visited = new Set([String(slab?.id ?? `${bounds.x1}:${bounds.y1}:${bounds.x2}:${bounds.y2}`)]);
    let current = normalizeSlab(slab);
    let index = 0;

    // Determine parity only inside the connected slab strip. The previous global
    // ordering used every slab start in the level, so unrelated slabs could make
    // two continuous panels choose the same representative bar track.
    while (current) {
        const previous = findAdjacentSlab(slabs, current, negativeSide, supportContext);
        if (!previous) {
            break;
        }
        const key = String(previous?.id ?? `${previous.x1}:${previous.y1}:${previous.x2}:${previous.y2}`);
        if (visited.has(key)) {
            break;
        }
        visited.add(key);
        current = previous;
        index += 1;
    }

    const ratio = index % 2 === 1 ? 0.75 : 0.25;
    const span = axis === "x" ? bounds.y2 - bounds.y1 : bounds.x2 - bounds.x1;
    const base = axis === "x" ? bounds.y1 : bounds.x1;
    return base + span * ratio;
}

function getSolidSlabAnchorCandidates(bounds, axis, separation, preferredAnchor, adjacentAnchor = null) {
    const perpendicularLimits = getSolidSlabPerpendicularLimits(bounds, axis);
    const minAnchor = perpendicularLimits.min + separation / 2;
    const maxAnchor = perpendicularLimits.max - separation / 2;
    const midpoint = (minAnchor + maxAnchor) / 2;

    if (maxAnchor <= minAnchor + EDGE_TOLERANCE) {
        return [midpoint];
    }

    const candidates = [
        preferredAnchor,
        // The other side of the slab is the first alternate placement.
        minAnchor + maxAnchor - preferredAnchor,
        minAnchor,
        maxAnchor,
        midpoint
    ];

    // Beyond the usual top/bottom alternation, probe tracks spaced 0.70 m apart.
    // This gives continuous panels a readable, non-overlapping bar layout even when
    // their different widths/heights make the 25% / 75% tracks coincide in world
    // coordinates.
    const gridStep = SOLID_SLAB_ADJACENT_BAR_CLEARANCE;
    for (let coordinate = minAnchor; coordinate <= maxAnchor + EDGE_TOLERANCE; coordinate += gridStep) {
        candidates.push(coordinate);
    }

    if (Number.isFinite(adjacentAnchor)) {
        for (let step = 1; step <= 4; step += 1) {
            candidates.push(adjacentAnchor - gridStep * step);
            candidates.push(adjacentAnchor + gridStep * step);
        }
    }

    return candidates
        .map((value) => clampSolidSlabCoordinate(value, minAnchor, maxAnchor))
        .filter((value, index, values) => (
            Number.isFinite(value)
            && values.findIndex((candidate) => Math.abs(candidate - value) <= SOLID_SLAB_BAR_TRACK_COLLISION_TOLERANCE / 2) === index
        ));
}

function getSolidSlabCollisionSafeAnchor(slabs, slab, axis, separation, supportContext = null, visited = new Set()) {
    const normalizedSlab = normalizeSlab(slab);
    const bounds = normalizeSlabBounds(normalizedSlab);
    const slabKey = `${axis}:${normalizedSlab.id ?? `${bounds.x1}:${bounds.y1}:${bounds.x2}:${bounds.y2}`}`;
    const preferredAnchor = getSolidSlabChainAlternatingAnchor(slabs, normalizedSlab, axis, supportContext);

    if (visited.has(slabKey)) {
        return preferredAnchor;
    }

    const negativeSide = axis === "x" ? "left" : "bottom";
    const previous = findAdjacentSlab(slabs, normalizedSlab, negativeSide, supportContext);
    if (!previous) {
        return preferredAnchor;
    }

    const nextVisited = new Set(visited);
    nextVisited.add(slabKey);
    const adjacentAnchor = getSolidSlabCollisionSafeAnchor(
        slabs,
        previous,
        axis,
        separation,
        supportContext,
        nextVisited
    );
    const candidates = getSolidSlabAnchorCandidates(
        bounds,
        axis,
        separation,
        preferredAnchor,
        adjacentAnchor
    );

    const clearCandidates = candidates
        .filter((candidate) => Math.abs(candidate - adjacentAnchor) >= (
            SOLID_SLAB_ADJACENT_BAR_CLEARANCE - SOLID_SLAB_BAR_TRACK_COLLISION_TOLERANCE
        ))
        .sort((left, right) => Math.abs(left - preferredAnchor) - Math.abs(right - preferredAnchor));

    if (clearCandidates.length > 0) {
        return clearCandidates[0];
    }

    // A narrow slab cannot always provide 0.70 m. In that case, pick the furthest
    // valid track rather than leaving the two panels directly on top of one another.
    return candidates
        .slice()
        .sort((left, right) => (
            Math.abs(right - adjacentAnchor) - Math.abs(left - adjacentAnchor)
            || Math.abs(left - preferredAnchor) - Math.abs(right - preferredAnchor)
        ))[0] ?? preferredAnchor;
}

function getSolidSlabHookLength(bounds, axis) {
    return SOLID_SLAB_HOOK_LENGTH;
}

function getSolidSlabBendLegLength(hookLength) {
    const targetLength = Math.max(parsePositiveNumberOrFallback(hookLength, SOLID_SLAB_HOOK_LENGTH), EDGE_TOLERANCE);
    return targetLength / Math.SQRT2;
}

function getSolidSlabBendAxisRun(targetLength, crossRun) {
    const safeTargetLength = Math.max(parsePositiveNumberOrFallback(targetLength, SOLID_SLAB_HOOK_LENGTH), EDGE_TOLERANCE);
    const safeCrossRun = Math.min(Math.max(parseNumberOrFallback(crossRun, 0), 0), safeTargetLength);
    return Math.sqrt(Math.max((safeTargetLength * safeTargetLength) - (safeCrossRun * safeCrossRun), 0));
}

function createSolidSlabPoint(axis, axisValue, crossValue) {
    return axis === "x"
        ? { x: axisValue, y: crossValue }
        : { x: crossValue, y: axisValue };
}

function isCantileverSlab(slab) {
    return Boolean(slab?.cantilever ?? slab?.isCantilever);
}

function getSolidSlabContinuation(slabs, slab, axis, supportContext = null) {
    const negativeSide = axis === "x" ? "left" : "bottom";
    const positiveSide = axis === "x" ? "right" : "top";
    const negativeNeighbor = findAdjacentSlab(slabs, slab, negativeSide, supportContext);
    const positiveNeighbor = findAdjacentSlab(slabs, slab, positiveSide, supportContext);

    if (isCantileverSlab(positiveNeighbor)) {
        return {
            direction: 1,
            neighbor: positiveNeighbor,
            bridgeRegion: getSolidSlabSupportBridgeClipRegion(supportContext, slab, positiveNeighbor, positiveSide)
        };
    }

    if (isCantileverSlab(negativeNeighbor)) {
        return {
            direction: -1,
            neighbor: negativeNeighbor,
            bridgeRegion: getSolidSlabSupportBridgeClipRegion(supportContext, slab, negativeNeighbor, negativeSide)
        };
    }

    if (positiveNeighbor) {
        return {
            direction: 1,
            neighbor: positiveNeighbor,
            bridgeRegion: getSolidSlabSupportBridgeClipRegion(supportContext, slab, positiveNeighbor, positiveSide)
        };
    }

    if (negativeNeighbor) {
        return {
            direction: -1,
            neighbor: negativeNeighbor,
            bridgeRegion: getSolidSlabSupportBridgeClipRegion(supportContext, slab, negativeNeighbor, negativeSide)
        };
    }

    return { direction: 1, neighbor: null, bridgeRegion: null };
}

function getSolidSlabExtensionEnd(axis, neighbor, direction, options = {}) {
    if (!neighbor) {
        return null;
    }

    const extendToCantileverEdge = options.extendToCantileverEdge === true && isCantileverSlab(neighbor);

    if (axis === "x") {
        if (extendToCantileverEdge) {
            return direction > 0 ? neighbor.x2 - DRAWING_COVER : neighbor.x1 + DRAWING_COVER;
        }
        return direction > 0
            ? Math.min(
                neighbor.x1 + (neighbor.x2 - neighbor.x1) * SOLID_SLAB_EXTENSION_RATIO,
                neighbor.x2 - DRAWING_COVER
            )
            : Math.max(
                neighbor.x2 - (neighbor.x2 - neighbor.x1) * SOLID_SLAB_EXTENSION_RATIO,
                neighbor.x1 + DRAWING_COVER
            );
    }

    if (extendToCantileverEdge) {
        return direction > 0 ? neighbor.y2 - DRAWING_COVER : neighbor.y1 + DRAWING_COVER;
    }
    return direction > 0
        ? Math.min(
            neighbor.y1 + (neighbor.y2 - neighbor.y1) * SOLID_SLAB_EXTENSION_RATIO,
            neighbor.y2 - DRAWING_COVER
        )
        : Math.max(
            neighbor.y2 - (neighbor.y2 - neighbor.y1) * SOLID_SLAB_EXTENSION_RATIO,
            neighbor.y1 + DRAWING_COVER
        );
}

function getSolidSlabRepresentativeBars(slabs, slab, axis, supportContext = null) {
    const normalizedSlab = normalizeSlab(slab);
    if (normalizedSlab.actionType === SLAB_ACTION_ONE_WAY && axis !== normalizedSlab.solid.topSteelDirection) {
        return [];
    }
    const bounds = normalizeSlabBounds(slab);
    const axisLimits = getSolidSlabAxisLimits(bounds, axis);
    const span = axisLimits.end - axisLimits.start;
    if (span <= EDGE_TOLERANCE) {
        return [];
    }

    const separation = getSolidSlabRepresentativeOffset(bounds, axis);
    const perpendicularLimits = getSolidSlabPerpendicularLimits(bounds, axis);
    const anchorCross = clampSolidSlabCoordinate(
        getSolidSlabCollisionSafeAnchor(slabs, normalizedSlab, axis, separation, supportContext),
        perpendicularLimits.min + separation / 2,
        perpendicularLimits.max - separation / 2
    );
    const primaryTrack = anchorCross - separation / 2;
    const secondaryTrack = anchorCross + separation / 2;
    const hookLength = getSolidSlabHookLength(bounds, axis);
    const bendLegLength = getSolidSlabBendLegLength(hookLength);
    const primaryOuterTrack = clampSolidSlabCoordinate(primaryTrack - bendLegLength, perpendicularLimits.min, perpendicularLimits.max);
    const secondaryOuterTrack = clampSolidSlabCoordinate(secondaryTrack + bendLegLength, perpendicularLimits.min, perpendicularLimits.max);
    const primaryBendAxisRun = getSolidSlabBendAxisRun(hookLength, Math.abs(primaryTrack - primaryOuterTrack));
    const secondaryBendAxisRun = getSolidSlabBendAxisRun(hookLength, Math.abs(secondaryOuterTrack - secondaryTrack));
    const continuation = getSolidSlabContinuation(slabs, normalizedSlab, axis, supportContext);
    const direction = continuation.direction;
    const startSide = getSolidSlabSideForAxisDirection(axis, -direction);
    const endSide = getSolidSlabSideForAxisDirection(axis, direction);
    const slabStart = getSolidSlabAxisEdgeCoordinate(bounds, normalizedSlab, axis, startSide, supportContext);
    const slabEnd = getSolidSlabAxisEdgeCoordinate(bounds, normalizedSlab, axis, endSide, supportContext);
    const referenceStart = direction > 0 ? axisLimits.start : axisLimits.end;
    const firstBendAxis = referenceStart + direction * span * SOLID_SLAB_FIRST_BEND_RATIO;
    const secondBendAxis = referenceStart + direction * span * SOLID_SLAB_SECOND_BEND_RATIO;
    const continuesIntoCantilever = isCantileverSlab(continuation.neighbor);
    const primaryLineEnd = continuesIntoCantilever
        ? (getSolidSlabExtensionEnd(axis, continuation.neighbor, direction, { extendToCantileverEdge: true }) ?? slabEnd)
        : slabEnd;
    const secondLineEnd = getSolidSlabExtensionEnd(axis, continuation.neighbor, direction, { extendToCantileverEdge: continuesIntoCantilever }) ?? slabEnd;
    const startSupportRegion = getSolidSlabSideSupportClipRegion(supportContext, normalizedSlab, startSide);
    const endSupportRegion = getSolidSlabSideSupportClipRegion(supportContext, normalizedSlab, endSide);
    const primaryClipRegions = continuesIntoCantilever
        ? [startSupportRegion, continuation.bridgeRegion, continuation.neighbor ? null : endSupportRegion].filter(Boolean)
        : [startSupportRegion, endSupportRegion].filter(Boolean);
    const secondaryClipRegions = [
        startSupportRegion,
        continuation.bridgeRegion,
        continuation.neighbor ? null : endSupportRegion
    ].filter(Boolean);

    return [
        {
            axis,
            primary: true,
            hookDirection: 1,
            endHookDirection: -1,
            hookLength,
            continuationNeighbor: continuesIntoCantilever ? continuation.neighbor : null,
            clipRegions: primaryClipRegions,
            points: [
                createSolidSlabPoint(axis, slabStart, primaryOuterTrack),
                createSolidSlabPoint(axis, firstBendAxis, primaryOuterTrack),
                createSolidSlabPoint(axis, firstBendAxis + direction * primaryBendAxisRun, primaryTrack),
                createSolidSlabPoint(axis, primaryLineEnd, primaryTrack)
            ]
        },
        {
            axis,
            primary: false,
            hookDirection: -1,
            endHookDirection: 1,
            hookLength,
            continuationNeighbor: continuation.neighbor,
            clipRegions: secondaryClipRegions,
            points: [
                createSolidSlabPoint(axis, slabStart, secondaryOuterTrack),
                createSolidSlabPoint(axis, secondBendAxis, secondaryOuterTrack),
                createSolidSlabPoint(axis, secondBendAxis + direction * secondaryBendAxisRun, secondaryTrack),
                createSolidSlabPoint(axis, secondLineEnd, secondaryTrack)
            ]
        }
    ];
}

function getLightenedCassetteLayout(slab) {
    const normalizedSlab = normalizeSlab(slab);
    const bounds = normalizeSlabBounds(normalizedSlab);
    const vertices = normalizeSlabVertices(normalizedSlab);
    const lightened = normalizedSlab.lightened;
    const cassetteGap = lightened.cassetteGap;
    const availableWidth = (bounds.x2 - bounds.x1) - SLAB_CASSETTE_EDGE_GAP * 2;
    const availableHeight = (bounds.y2 - bounds.y1) - SLAB_CASSETTE_EDGE_GAP * 2;
    let cassetteWidth = lightened.cassetteWidth;
    let cassetteHeight = lightened.cassetteHeight;
    let countX = 0;
    let countY = 0;

    if (!(availableWidth > 0) || !(availableHeight > 0)) {
        return null;
    }

    if (normalizedSlab.actionType === SLAB_ACTION_ONE_WAY) {
        const workDirection = normalizedSlab.solid.topSteelDirection === "y" ? "y" : "x";
        if (workDirection === "y") {
            if (availableWidth < cassetteWidth) {
                return null;
            }
            cassetteHeight = availableHeight;
            countX = Math.max(Math.floor((availableWidth + cassetteGap) / (cassetteWidth + cassetteGap)), 1);
            countY = 1;
        } else {
            if (availableHeight < cassetteHeight) {
                return null;
            }
            cassetteWidth = availableWidth;
            countX = 1;
            countY = Math.max(Math.floor((availableHeight + cassetteGap) / (cassetteHeight + cassetteGap)), 1);
        }
    } else {
        if (availableWidth < cassetteWidth || availableHeight < cassetteHeight) {
            return null;
        }

        countX = Math.max(Math.floor((availableWidth + cassetteGap) / (cassetteWidth + cassetteGap)), 1);
        countY = Math.max(Math.floor((availableHeight + cassetteGap) / (cassetteHeight + cassetteGap)), 1);
    }

    if (!(countX > 0) || !(countY > 0)) {
        return null;
    }

    const usedWidth = countX * cassetteWidth + (countX - 1) * cassetteGap;
    const usedHeight = countY * cassetteHeight + (countY - 1) * cassetteGap;
    return {
        bounds,
        vertices,
        cassetteGap,
        cassetteWidth,
        cassetteHeight,
        countX,
        countY,
        startX: bounds.x1 + SLAB_CASSETTE_EDGE_GAP + Math.max((availableWidth - usedWidth) / 2, 0),
        startY: bounds.y1 + SLAB_CASSETTE_EDGE_GAP + Math.max((availableHeight - usedHeight) / 2, 0)
    };
}

function getLightenedCassetteRects(slab) {
    const layout = getLightenedCassetteLayout(slab);

    if (!layout) {
        return [];
    }

    const rectangles = [];

    for (let xIndex = 0; xIndex < layout.countX; xIndex += 1) {
        for (let yIndex = 0; yIndex < layout.countY; yIndex += 1) {
            const x1 = layout.startX + xIndex * (layout.cassetteWidth + layout.cassetteGap);
            const y1 = layout.startY + yIndex * (layout.cassetteHeight + layout.cassetteGap);
            rectangles.push({
                x1,
                y1,
                x2: x1 + layout.cassetteWidth,
                y2: y1 + layout.cassetteHeight
            });
        }
    }

    return rectangles.filter((rectangle) => (
        isPointInPolygon({ x: rectangle.x1, y: rectangle.y1 }, layout.vertices, { includeBoundary: true })
        && isPointInPolygon({ x: rectangle.x2, y: rectangle.y1 }, layout.vertices, { includeBoundary: true })
        && isPointInPolygon({ x: rectangle.x2, y: rectangle.y2 }, layout.vertices, { includeBoundary: true })
        && isPointInPolygon({ x: rectangle.x1, y: rectangle.y2 }, layout.vertices, { includeBoundary: true })
    ));
}

function getRepresentativeBand(bands) {
    if (!bands.length) {
        return null;
    }

    return bands[Math.floor(bands.length / 2)];
}

function getCassetteBands(rectangles, axisStart, axisEnd, axis) {
    const rawBands = rectangles
        .map((rectangle) => axis === "x"
            ? { start: rectangle.x1, end: rectangle.x2 }
            : { start: rectangle.y1, end: rectangle.y2 })
        .sort((a, b) => a.start - b.start || a.end - b.end);
    const uniqueBands = [];

    rawBands.forEach((band) => {
        const lastBand = uniqueBands[uniqueBands.length - 1];
        if (!lastBand || Math.abs(lastBand.start - band.start) > 0.01 || Math.abs(lastBand.end - band.end) > 0.01) {
            uniqueBands.push(band);
        }
    });

    const freeBands = [];
    let cursor = axisStart;

    uniqueBands.forEach((band) => {
        if (band.start > cursor + 0.01) {
            freeBands.push({ start: cursor, end: band.start });
        }
        cursor = Math.max(cursor, band.end);
    });

    if (axisEnd > cursor + 0.01) {
        freeBands.push({ start: cursor, end: axisEnd });
    }

    return freeBands.filter((band) => band.end - band.start > 0.04);
}

function getLightenedRibBarSegments(slab, axis) {
    const normalizedSlab = normalizeSlab(slab);
    if (normalizedSlab.actionType === SLAB_ACTION_ONE_WAY && axis !== normalizedSlab.solid.topSteelDirection) {
        return [];
    }
    const bounds = normalizeSlabBounds(normalizedSlab);
    const cassettes = getLightenedCassetteRects(normalizedSlab);
    const bands = cassettes.length === 0
        ? [axis === "x"
            ? { start: bounds.y1 + DRAWING_COVER, end: bounds.y2 - DRAWING_COVER }
            : { start: bounds.x1 + DRAWING_COVER, end: bounds.x2 - DRAWING_COVER }]
        : axis === "x"
            ? getCassetteBands(cassettes, bounds.y1, bounds.y2, "y")
            : getCassetteBands(cassettes, bounds.x1, bounds.x2, "x");
    const representativeBand = getRepresentativeBand(bands);

    if (!representativeBand) {
        return [];
    }

    const barsPerRib = axis === "x"
        ? normalizedSlab.lightened.xBarsPerRib
        : normalizedSlab.lightened.yBarsPerRib;
    const positions = getBarLayoutPositions(barsPerRib, representativeBand.start, representativeBand.end, 0);

    return positions.map((position) => (
        axis === "x"
            ? {
                x1: bounds.x1 + DRAWING_COVER,
                y1: position,
                x2: bounds.x2 - DRAWING_COVER,
                y2: position
            }
            : {
                x1: position,
                y1: bounds.y1 + DRAWING_COVER,
                x2: position,
                y2: bounds.y2 - DRAWING_COVER
            }
    ));
}

function getLightenedRibCallout(slab, axis) {
    const normalizedSlab = normalizeSlab(slab);
    const bounds = normalizeSlabBounds(normalizedSlab);
    const segments = getLightenedRibBarSegments(normalizedSlab, axis);

    if (!segments.length) {
        return null;
    }

    const targetSegment = segments[Math.floor(segments.length / 2)];
    return {
        label: formatLightenedAxisRebarLabel(normalizedSlab.lightened, axis),
        targetX: (targetSegment.x1 + targetSegment.x2) / 2,
        targetY: (targetSegment.y1 + targetSegment.y2) / 2,
        labelCenterX: axis === "x"
            ? (bounds.x1 + bounds.x2) / 2
            : bounds.x1 + (bounds.x2 - bounds.x1) * 0.72,
        labelY: axis === "x"
            ? bounds.y1 - 0.35
            : bounds.y2 + 0.35,
        placement: axis === "x" ? "above" : "below"
    };
}

function getSolidSlabCallout(slabs, slab, axis) {
    const normalizedSlab = normalizeSlab(slab);
    const bounds = normalizeSlabBounds(normalizedSlab);
    const bars = getSolidSlabRepresentativeBars(slabs, normalizedSlab, axis);
    const targetBar = bars.find((bar) => bar.primary) || bars[0];
    const targetSegments = targetBar ? getSolidSlabVisibleSegments(targetBar, normalizedSlab) : [];
    const targetSegment = targetSegments[Math.floor(targetSegments.length / 2)] || targetSegments[0];

    if (!targetSegment) {
        return null;
    }

    return {
        label: `${axis.toUpperCase()}: ${formatSlabSpacingLabel(
            axis === "x" ? normalizedSlab.solid.xBarDiameter : normalizedSlab.solid.yBarDiameter,
            axis === "x" ? normalizedSlab.solid.xSpacing : normalizedSlab.solid.ySpacing
        )}`,
        targetX: (targetSegment.x1 + targetSegment.x2) / 2,
        targetY: (targetSegment.y1 + targetSegment.y2) / 2,
        labelCenterX: axis === "x"
            ? (bounds.x1 + bounds.x2) / 2
            : bounds.x1 + (bounds.x2 - bounds.x1) * 0.72,
        labelY: axis === "x"
            ? bounds.y1 - 0.35
            : bounds.y2 + 0.35,
        placement: axis === "x" ? "above" : "below"
    };
}

function normalizeLongitudinalRebar(rebar) {
    return {
        n: String(rebar?.n ?? 2).trim() || "2",
        d: normalizeDiameterLabel(rebar?.d ?? DEFAULT_LONGITUDINAL_DIAMETER) || DEFAULT_LONGITUDINAL_DIAMETER
    };
}

function normalizeColumnDirectionBarCount(value, fallback = DEFAULT_COLUMN_DIRECTION_BAR_COUNT) {
    return Math.max(Number.parseInt(value, 10) || fallback, 2);
}

function getPreferredColumnCornerDiameter(xDiameter, yDiameter) {
    const normalizedX = normalizeDiameterLabel(xDiameter) || DEFAULT_LONGITUDINAL_DIAMETER;
    const normalizedY = normalizeDiameterLabel(yDiameter) || normalizedX;
    return parseDiameterInMeters(normalizedX) >= parseDiameterInMeters(normalizedY)
        ? normalizedX
        : normalizedY;
}

function getColumnDirectionCountsFromTotal(totalBars) {
    const normalizedTotal = Math.max(Number.parseInt(totalBars, 10) || 4, 4);
    const evenTotal = normalizedTotal % 2 === 0 ? normalizedTotal : normalizedTotal + 1;
    const faceSum = (evenTotal + 4) / 2;
    const xCount = Math.max(Math.ceil(faceSum / 2), 2);
    const yCount = Math.max(faceSum - xCount, 2);

    return { xCount, yCount };
}

function getColumnLongitudinalLayout(value, options = {}) {
    const normalizedValue = normalizeTextValue(value).toLowerCase();
    if (["circular", "circle", "round"].includes(normalizedValue)) {
        return "circular";
    }
    const shapeDescriptor = [
        options?.sectionShape,
        options?.columnShape,
        options?.sourceShape,
        options?.shape
    ].map((item) => normalizeTextValue(item).toLowerCase()).join(" ");
    if (/(?:concrete\s+)?circle|circular|round|redonda/.test(shapeDescriptor)) {
        return "circular";
    }
    return "rectangular";
}

function getCircularColumnBarCount(rebar) {
    const source = rebar && typeof rebar === "object" ? rebar : {};
    const explicitCount = source.count ?? source.barCount ?? source.totalCount ?? source.n;
    const parsedExplicitCount = Number.parseInt(explicitCount, 10);
    if (Number.isFinite(parsedExplicitCount) && parsedExplicitCount > 0) {
        return Math.max(parsedExplicitCount, 4);
    }
    return getTotalColumnBarCount({ ...source, layout: "rectangular" });
}

function isCircularColumnLongitudinalRebar(rebar) {
    return normalizeColumnLongitudinalRebar(rebar).layout === "circular";
}

function normalizeColumnLongitudinalRebar(rebar, options = {}) {
    const legacyRebar = normalizeLongitudinalRebar(rebar);
    const rebarObject = rebar && typeof rebar === "object" ? rebar : {};
    const hasDirectionalCounts = "xCount" in rebarObject || "yCount" in rebarObject;
    const layout = getColumnLongitudinalLayout(rebarObject.layout ?? rebarObject.type ?? rebarObject.shape, {
        ...options,
        ...rebarObject
    });
    const counts = hasDirectionalCounts
        ? {
            xCount: normalizeColumnDirectionBarCount(rebar?.xCount),
            yCount: normalizeColumnDirectionBarCount(rebar?.yCount)
        }
        : getColumnDirectionCountsFromTotal(parseBarCount(rebar?.n));
    const circularDiameter = normalizeDiameterLabel(rebar?.diameter ?? rebar?.barDiameter ?? rebar?.d ?? rebar?.xDiameter ?? legacyRebar.d) || legacyRebar.d;
    const xDiameter = normalizeDiameterLabel(rebar?.xDiameter ?? circularDiameter ?? legacyRebar.d) || legacyRebar.d;
    const yDiameter = normalizeDiameterLabel(rebar?.yDiameter ?? circularDiameter ?? legacyRebar.d) || legacyRebar.d;
    const preferredCornerDiameter = getPreferredColumnCornerDiameter(xDiameter, yDiameter);
    const explicitCornerDiameter = normalizeDiameterLabel(rebar?.cornerDiameter ?? rebar?.cornerD ?? preferredCornerDiameter) || preferredCornerDiameter;
    const rawCornerToggle = typeof rebar?.hasCustomCornerDiameter === "boolean"
        ? rebar.hasCustomCornerDiameter
        : typeof rebar?.useCustomCornerDiameter === "boolean"
            ? rebar.useCustomCornerDiameter
            : typeof rebar?.cornerDiameterEnabled === "boolean"
                ? rebar.cornerDiameterEnabled
                : null;
    const hasCustomCornerDiameter = rawCornerToggle ?? (explicitCornerDiameter !== preferredCornerDiameter);

    const normalized = {
        layout,
        xCount: counts.xCount,
        xDiameter,
        yCount: counts.yCount,
        yDiameter,
        cornerDiameter: hasCustomCornerDiameter ? explicitCornerDiameter : preferredCornerDiameter,
        hasCustomCornerDiameter
    };

    if (layout === "circular") {
        const count = getCircularColumnBarCount({
            ...rebarObject,
            xCount: counts.xCount,
            yCount: counts.yCount
        });
        const circularCounts = getColumnDirectionCountsFromTotal(count);
        return {
            ...normalized,
            count,
            n: String(count),
            diameter: circularDiameter,
            d: circularDiameter,
            xCount: circularCounts.xCount,
            xDiameter: circularDiameter,
            yCount: circularCounts.yCount,
            yDiameter: circularDiameter,
            cornerDiameter: circularDiameter,
            hasCustomCornerDiameter: false
        };
    }

    return normalized;
}

function getTotalColumnBarCount(rebar) {
    const normalized = normalizeColumnLongitudinalRebar(rebar);
    if (normalized.layout === "circular") {
        return Math.max(Number.parseInt(normalized.count, 10) || 4, 4);
    }
    return Math.max((normalized.xCount * 2) + (normalized.yCount * 2) - 4, 4);
}

function getColumnNonCornerBarCountFromDirection(directionCount) {
    return Math.max((normalizeColumnDirectionBarCount(directionCount) - 2) * 2, 0);
}

function getColumnLongitudinalBarBreakdown(rebar) {
    const normalized = normalizeColumnLongitudinalRebar(rebar);
    if (normalized.layout === "circular") {
        return {
            xBars: 0,
            yBars: 0,
            cornerBars: 0,
            circularBars: getTotalColumnBarCount(normalized)
        };
    }
    return {
        xBars: getColumnNonCornerBarCountFromDirection(normalized.xCount),
        yBars: getColumnNonCornerBarCountFromDirection(normalized.yCount),
        cornerBars: 4
    };
}

function parseRebarInput(value) {
    const normalizedValue = String(value || "").trim();
    const match = normalizedValue.match(/^(.*?)\s*(?:%%c|[\u00d8\u00f8\u2300])\s*(.+)$/i);
    const count = match ? match[1] : normalizedValue;
    const diameter = match ? match[2] : DEFAULT_LONGITUDINAL_DIAMETER;

    return normalizeLongitudinalRebar({
        n: (count || "").trim(),
        d: (diameter || DEFAULT_LONGITUDINAL_DIAMETER).trim() || DEFAULT_LONGITUDINAL_DIAMETER
    });
}

function formatRebar(rebar) {
    const normalized = normalizeLongitudinalRebar(rebar);
    return formatDxfRebarCountLabel(normalized.n, normalized.d);
}

function formatOptionalRebar(rebar) {
    const normalized = normalizeOptionalLongitudinalRebar(rebar);
    return parseOptionalBarCount(normalized.n) > 0
        ? formatDxfRebarCountLabel(normalized.n, normalized.d)
        : "0";
}

function formatColumnLongitudinalRebar(rebar) {
    const normalized = normalizeColumnLongitudinalRebar(rebar);
    if (normalized.layout === "circular") {
        return formatDxfRebarCountLabel(normalized.count, normalized.diameter);
    }
    if (normalized.hasCustomCornerDiameter) {
        const breakdown = getColumnLongitudinalBarBreakdown(normalized);
        const segments = [];

        if (breakdown.xBars > 0) {
            segments.push(`X: ${formatDxfRebarCountLabel(breakdown.xBars, normalized.xDiameter)}`);
        }

        if (breakdown.yBars > 0) {
            segments.push(`Y: ${formatDxfRebarCountLabel(breakdown.yBars, normalized.yDiameter)}`);
        }

        return segments.length > 0
            ? segments.join(" | ")
            : "Laterales: 0";
    }

    return `X: ${formatDxfRebarCountLabel(normalized.xCount, normalized.xDiameter)} | Y: ${formatDxfRebarCountLabel(normalized.yCount, normalized.yDiameter)}`;
}

function formatColumnCornerRebar(rebar) {
    const normalized = normalizeColumnLongitudinalRebar(rebar);
    if (normalized.layout === "circular") {
        return "";
    }
    const breakdown = getColumnLongitudinalBarBreakdown(normalized);
    return normalized.hasCustomCornerDiameter
        ? `Esq: ${formatDxfRebarCountLabel(breakdown.cornerBars, normalized.cornerDiameter)}`
        : `Esq: ${breakdown.cornerBars} barras, mayor ${TRANSVERSE_SYMBOL}${formatDxfRebarDiameterLabel(normalized.cornerDiameter)}`;
}

function normalizeTransverseRebar(transverseRebar, defaultSpacing = DEFAULT_BEAM_STIRRUP_SPACING) {
    const spacing = Math.max(parseNumberOrFallback(transverseRebar?.spacing, defaultSpacing), 0.05);
    const diameter = normalizeDiameterLabel(transverseRebar?.d ?? DEFAULT_TRANSVERSE_DIAMETER) || DEFAULT_TRANSVERSE_DIAMETER;

    return {
        d: diameter,
        spacing
    };
}

function normalizeColumnStirrupDiameter(value, fallback = DEFAULT_TRANSVERSE_DIAMETER) {
    const normalizedFallback = normalizeDiameterLabel(fallback) || DEFAULT_TRANSVERSE_DIAMETER;
    const normalizedValue = normalizeDiameterLabel(value);
    if (!normalizedValue) {
        return normalizedFallback;
    }

    const diameterMeters = getDiameterMetersFromBarLabel(
        normalizedValue,
        getActiveBarSetForDiameters()
    );
    return diameterMeters > 0 && diameterMeters <= MAX_COLUMN_STIRRUP_DIAMETER_METERS + 1e-9
        ? normalizedValue
        : normalizedFallback;
}

function getDefaultColumnStirrupCount(longRebar) {
    return Math.max(getTotalColumnBarCount(longRebar) > 4 ? 2 : DEFAULT_COLUMN_STIRRUP_COUNT, MIN_COLUMN_CONFINEMENT_COUNT);
}

function normalizeColumnConfinementBarCount(value, fallback = MIN_COLUMN_CONFINEMENT_COUNT) {
    return Math.max(Number.parseInt(value, 10) || fallback, MIN_COLUMN_CONFINEMENT_COUNT);
}

function getColumnConfinementCounts(transverseRebar, longRebar) {
    const rebarObject = transverseRebar && typeof transverseRebar === "object" ? transverseRebar : {};
    const explicitCount3Dir = rebarObject.count3Dir ?? rebarObject.bars3Dir ?? rebarObject.xCount;
    const explicitCount2Dir = rebarObject.count2Dir ?? rebarObject.bars2Dir ?? rebarObject.yCount;
    const hasDirectionalCounts = explicitCount3Dir != null || explicitCount2Dir != null;

    if (hasDirectionalCounts) {
        return {
            count3Dir: normalizeColumnConfinementBarCount(explicitCount3Dir, MIN_COLUMN_CONFINEMENT_COUNT),
            count2Dir: normalizeColumnConfinementBarCount(explicitCount2Dir, MIN_COLUMN_CONFINEMENT_COUNT)
        };
    }

    const legacyCount = normalizeColumnConfinementBarCount(rebarObject.count, getDefaultColumnStirrupCount(longRebar));
    if (legacyCount <= MIN_COLUMN_CONFINEMENT_COUNT) {
        return {
            count3Dir: MIN_COLUMN_CONFINEMENT_COUNT,
            count2Dir: MIN_COLUMN_CONFINEMENT_COUNT
        };
    }

    const normalizedLongRebar = normalizeColumnLongitudinalRebar(longRebar);
    return normalizedLongRebar.xCount >= normalizedLongRebar.yCount
        ? { count3Dir: legacyCount, count2Dir: MIN_COLUMN_CONFINEMENT_COUNT }
        : { count3Dir: MIN_COLUMN_CONFINEMENT_COUNT, count2Dir: legacyCount };
}

function getDefaultColumnCentralZoneSpacing(confinementSpacing) {
    const resolvedConfinementSpacing = parsePositiveNumberOrFallback(
        confinementSpacing,
        DEFAULT_COLUMN_TIE_SPACING,
        0.05
    );
    return Math.min(
        resolvedConfinementSpacing + COLUMN_CENTRAL_ZONE_SPACING_INCREMENT,
        MAX_COLUMN_CENTRAL_ZONE_SPACING
    );
}

function normalizeColumnCentralZoneRebar(transverseRebar, confinementRebar) {
    const source = transverseRebar && typeof transverseRebar === "object" ? transverseRebar : {};
    const confinement = normalizeTransverseRebar(confinementRebar, DEFAULT_COLUMN_TIE_SPACING);
    const centralSource = source.centralZone ?? source.centralStirrups ?? source.midZone ?? {};
    const explicitCentralSpacing = centralSource?.spacing ?? source.centralSpacing;
    const normalized = normalizeTransverseRebar({
        d: centralSource?.d ?? source.centralDiameter ?? confinement.d,
        spacing: explicitCentralSpacing ?? getDefaultColumnCentralZoneSpacing(confinement.spacing)
    }, confinement.spacing);
    return {
        ...normalized,
        d: normalizeColumnStirrupDiameter(normalized.d, confinement.d)
    };
}

function normalizeColumnTransverseRebar(transverseRebar, longRebar) {
    const source = transverseRebar && typeof transverseRebar === "object" ? transverseRebar : {};
    const transverse = normalizeTransverseRebar(source, DEFAULT_COLUMN_TIE_SPACING);
    const normalized = {
        ...transverse,
        d: normalizeColumnStirrupDiameter(transverse.d)
    };
    const directionalCounts = getColumnConfinementCounts(source, longRebar);
    const fallbackCount = Math.max(directionalCounts.count3Dir, directionalCounts.count2Dir, MIN_COLUMN_CONFINEMENT_COUNT);
    const centralZone = normalizeColumnCentralZoneRebar(source, normalized);

    return {
        ...normalized,
        count: Math.max(Number.parseInt(source?.count ?? fallbackCount, 10) || fallbackCount, MIN_COLUMN_CONFINEMENT_COUNT),
        count3Dir: directionalCounts.count3Dir,
        count2Dir: directionalCounts.count2Dir,
        cover: Math.max(parsePositiveNumberOrFallback(source?.cover, DRAWING_COVER, 0.01), 0.01),
        useCentralZoneSpacing: source?.useCentralZoneSpacing !== false,
        centralZone
    };
}

function ensureTransverseRebar(element, defaultSpacing) {
    element.stirrups = normalizeTransverseRebar(element.stirrups, defaultSpacing);
    return element.stirrups;
}

function ensureColumnTransverseRebar(element, longRebar = element?.longRebar ?? element?.longitudinalRebar) {
    element.stirrups = normalizeColumnTransverseRebar(element.stirrups, longRebar);
    return element.stirrups;
}

function parseTransverseRebarInput(value, defaultSpacing = DEFAULT_BEAM_STIRRUP_SPACING) {
    const [rawDiameter, rawSpacing] = String(value || "").split("@");
    const spacingValue = (rawSpacing || "").replace(/m/gi, "").replace(",", ".").trim();

    return normalizeTransverseRebar({
        d: rawDiameter,
        spacing: Number.parseFloat(spacingValue)
    }, defaultSpacing);
}

function formatTransverseRebar(transverseRebar, defaultSpacing = DEFAULT_BEAM_STIRRUP_SPACING) {
    const normalized = normalizeTransverseRebar(transverseRebar, defaultSpacing);
    return formatDxfRebarSpacingLabel(normalized.d, normalized.spacing);
}

function formatFrameElevationStirrupSpacing(spacingMeters, unitSystem = null) {
    const normalizedUnitSystem = normalizeUnitSystem(unitSystem || getCurrentUnitSystem());
    const normalizedSpacing = Math.max(
        parsePositiveNumberOrFallback(spacingMeters, DEFAULT_BEAM_STIRRUP_SPACING, 0.001),
        0.001
    );
    if (normalizedUnitSystem === "imperial") {
        const spacingInches = normalizedSpacing / 0.0254;
        const wholeInches = Math.round(spacingInches);
        return Math.abs(spacingInches - wholeInches) <= 1e-6
            ? `${wholeInches}"`
            : formatDecimalInchesAsFraction(spacingInches);
    }

    if (normalizedUnitSystem === "metric-mks") {
        return `${normalizedSpacing.toFixed(2)}m`;
    }

    return `${Math.round(normalizedSpacing * 1000)}mm`;
}

function getDxfBeamStirrupSpacingMeters(spacingMeters, unitSystem = null) {
    const normalizedSpacing = Math.max(
        parsePositiveNumberOrFallback(spacingMeters, DEFAULT_BEAM_STIRRUP_SPACING, 0.001),
        0.001
    );
    const normalizedUnitSystem = normalizeUnitSystem(unitSystem || getCurrentUnitSystem());
    if (normalizedUnitSystem !== "imperial") {
        return normalizedSpacing;
    }

    // Beam stirrup spacing in U.S. Customary drawings is always a whole-inch
    // module. Keep the drawn markers and their callout synchronized.
    return Math.max(1, Math.round(normalizedSpacing / 0.0254)) * 0.0254;
}

function formatDxfBeamStirrupSpacing(spacingMeters, unitSystem = null) {
    const normalizedUnitSystem = normalizeUnitSystem(unitSystem || getCurrentUnitSystem());
    if (normalizedUnitSystem === "imperial") {
        const wholeInches = Math.max(1, Math.round(getDxfBeamStirrupSpacingMeters(spacingMeters, normalizedUnitSystem) / 0.0254));
        return `${wholeInches}"`;
    }
    return formatFrameElevationStirrupSpacing(spacingMeters, normalizedUnitSystem);
}

function formatDxfBeamStirrupLabel(transverseRebar, defaultSpacing = DEFAULT_BEAM_STIRRUP_SPACING) {
    const normalized = normalizeTransverseRebar(transverseRebar, defaultSpacing);
    if (normalizeUnitSystem(getCurrentUnitSystem()) !== "imperial") {
        return formatDxfRebarSpacingLabel(normalized.d, normalized.spacing);
    }
    return `${TRANSVERSE_SYMBOL}${formatDxfRebarDiameterLabel(normalized.d)}@${formatDxfBeamStirrupSpacing(normalized.spacing)}`;
}

// Frame elevations use a compact, conventional callout distinct from the
// generic transverse-rebar label used in tables and section details.
function formatFrameElevationStirrupLabel(transverseRebar, defaultSpacing = DEFAULT_BEAM_STIRRUP_SPACING) {
    const normalized = normalizeTransverseRebar(transverseRebar, defaultSpacing);
    return `EST.${TRANSVERSE_SYMBOL}${formatDxfRebarDiameterLabel(normalized.d)}@${formatDxfBeamStirrupSpacing(normalized.spacing)}`;
}

function formatColumnTransverseRebar(transverseRebar, longRebar) {
    const normalized = normalizeColumnTransverseRebar(transverseRebar, longRebar);
    if (isCircularColumnLongitudinalRebar(longRebar)) {
        return formatDxfRebarSpacingLabel(normalized.d, normalized.spacing);
    }
    return `${formatDxfRebarSpacingLabel(normalized.d, normalized.spacing)} | X: ${normalized.count3Dir} | Y: ${normalized.count2Dir}`;
}

function formatColumnLongitudinalDetailLabel(rebar) {
    const normalized = normalizeColumnLongitudinalRebar(rebar);
    if (normalized.layout === "circular") {
        return formatDxfRebarCountLabel(normalized.count, normalized.diameter);
    }
    const breakdown = getColumnLongitudinalBarBreakdown(normalized);
    const groupedCounts = new Map();

    const registerCount = (count, diameter) => {
        if (!(count > 0)) {
            return;
        }

        const current = groupedCounts.get(diameter) || 0;
        groupedCounts.set(diameter, current + count);
    };

    registerCount(breakdown.xBars, normalized.xDiameter);
    registerCount(breakdown.yBars, normalized.yDiameter);
    registerCount(breakdown.cornerBars, normalized.cornerDiameter);

    return Array.from(groupedCounts.entries())
        .map(([diameter, count]) => formatDxfRebarCountLabel(count, diameter))
        .join(" + ");
}

function formatColumnTransverseDetailLabel(transverseRebar, longRebar) {
    const normalized = normalizeColumnTransverseRebar(transverseRebar, longRebar);
    return formatDxfRebarSpacingLabel(normalized.d, normalized.spacing);
}

function formatSlabSpacingLabel(diameter, spacing) {
    return formatDxfRebarSpacingLabel(normalizeDiameterLabel(diameter) || DEFAULT_SLAB_BAR_DIAMETER, parsePositiveNumberOrFallback(spacing, DEFAULT_SLAB_BAR_SPACING));
}

function formatWallRebarLayoutLabel(concrete = {}, direction = "longitudinal") {
    const isTransverse = direction === "transverse";
    const isHorizontal = direction === "horizontal";
    if (!isTransverse && !isHorizontal && getWallConcreteReinforcementMode(concrete) === WALL_REINFORCEMENT_MODE_QUANTITY) {
        return formatDxfRebarCountLabel(
            normalizeWallRebarCount(concrete.longitudinalCount, DEFAULT_WALL_LONGITUDINAL_COUNT),
            concrete.longitudinalDiameter
        );
    }
    return formatSlabSpacingLabel(
        isTransverse
            ? concrete.transverseDiameter
            : isHorizontal
                ? concrete.horizontalDiameter
                : concrete.longitudinalDiameter,
        isTransverse
            ? concrete.transverseSpacing
            : isHorizontal
                ? concrete.horizontalSpacing
                : concrete.longitudinalSpacing
    );
}

function formatSlabTopSteelDirectionLabel(direction) {
    return normalizeTextValue(direction).toLowerCase() === "y"
        ? translate("modal.slabTopSteelDirY")
        : translate("modal.slabTopSteelDirX");
}

function formatAngleValue(value) {
    const rounded = Math.round(parseNumberOrFallback(value, 0) * 10) / 10;
    return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
}

function getSlabTemperatureDirectionAngle(temperatureSteel) {
    const normalized = normalizeSlabTemperatureSteel(temperatureSteel);
    return normalized.direction === "y" ? 90 : 0;
}

function formatSlabTemperatureSteelLabel(temperatureSteel) {
    const normalized = normalizeSlabTemperatureSteel(temperatureSteel);
    if (!normalized.enabled) {
        return "";
    }

    const directionLabel = normalized.direction === "y"
        ? translate("modal.slabTemperatureDirY")
        : translate("modal.slabTemperatureDirX");

    return `${translate("modal.slabTemperatureSteel")}: ${directionLabel} ${formatDxfRebarSpacingLabel(normalized.barDiameter, normalized.spacing)}`;
}

function clipInfiniteLineToRect(point, direction, rect) {
    let tMin = -Infinity;
    let tMax = Infinity;
    const epsilon = 1e-9;

    if (Math.abs(direction.x) < epsilon) {
        if (point.x < rect.x1 || point.x > rect.x2) {
            return null;
        }
    } else {
        const t1 = (rect.x1 - point.x) / direction.x;
        const t2 = (rect.x2 - point.x) / direction.x;
        tMin = Math.max(tMin, Math.min(t1, t2));
        tMax = Math.min(tMax, Math.max(t1, t2));
    }

    if (Math.abs(direction.y) < epsilon) {
        if (point.y < rect.y1 || point.y > rect.y2) {
            return null;
        }
    } else {
        const t1 = (rect.y1 - point.y) / direction.y;
        const t2 = (rect.y2 - point.y) / direction.y;
        tMin = Math.max(tMin, Math.min(t1, t2));
        tMax = Math.min(tMax, Math.max(t1, t2));
    }

    if (!(tMax >= tMin)) {
        return null;
    }

    return {
        x1: point.x + direction.x * tMin,
        y1: point.y + direction.y * tMin,
        x2: point.x + direction.x * tMax,
        y2: point.y + direction.y * tMax
    };
}

function getSlabTemperatureBarSegments(slab) {
    const normalizedSlab = normalizeSlab(slab);
    if (!normalizedSlab.temperatureSteel.enabled) {
        return [];
    }

    const bounds = normalizeSlabBounds(normalizedSlab);
    const vertices = normalizeSlabVertices(normalizedSlab);
    const rect = {
        x1: bounds.x1 + DRAWING_COVER,
        y1: bounds.y1 + DRAWING_COVER,
        x2: bounds.x2 - DRAWING_COVER,
        y2: bounds.y2 - DRAWING_COVER
    };
    const rectWidth = rect.x2 - rect.x1;
    const rectHeight = rect.y2 - rect.y1;

    if (rectWidth <= EDGE_TOLERANCE || rectHeight <= EDGE_TOLERANCE) {
        return [];
    }

    const angleRadians = getSlabTemperatureDirectionAngle(normalizedSlab.temperatureSteel) * Math.PI / 180;
    const direction = {
        x: Math.cos(angleRadians),
        y: Math.sin(angleRadians)
    };
    const normal = {
        x: -direction.y,
        y: direction.x
    };
    const centroid = getSlabCentroid(normalizedSlab);
    const center = {
        x: Math.min(Math.max(centroid.x, rect.x1), rect.x2),
        y: Math.min(Math.max(centroid.y, rect.y1), rect.y2)
    };
    const separation = Math.max(
        Math.min(SOLID_SLAB_PAIR_SEPARATION, Math.min(rectWidth, rectHeight) * 0.32),
        0.05
    );

    const offsets = normalizedSlab.actionType === SLAB_ACTION_ONE_WAY
        ? [0]
        : [-separation / 2, separation / 2];

    return offsets
        .map((offset) => clipInfiniteLineToRect(
            {
                x: center.x + normal.x * offset,
                y: center.y + normal.y * offset
            },
            direction,
            rect
        ))
        .filter(Boolean)
        .flatMap((segment) => clipSegmentToPolygon(segment, vertices));
}

function drawSlabTemperatureBars(context, slab, toCanvasX, toCanvasY) {
    const segments = getSlabTemperatureBarSegments(slab);
    if (!segments.length) {
        return;
    }

    const palette = getModelSpacePalette();
    context.save();
    context.strokeStyle = palette.temperatureBar;
    context.lineWidth = 1.2;
    context.lineCap = "round";
    segments.forEach((segment) => {
        context.beginPath();
        context.moveTo(toCanvasX(segment.x1), toCanvasY(segment.y1));
        context.lineTo(toCanvasX(segment.x2), toCanvasY(segment.y2));
        context.stroke();
    });
    context.restore();
}

function getMasonryPlan45DegreeHatchSegments(vertices, spacing = 0.08, edgeInset = 0.006) {
    const polygon = (Array.isArray(vertices) ? vertices : [])
        .map((vertex) => ({ x: Number.parseFloat(vertex?.x), y: Number.parseFloat(vertex?.y) }))
        .filter((vertex) => Number.isFinite(vertex.x) && Number.isFinite(vertex.y));

    if (polygon.length < 3) {
        return [];
    }

    const bounds = getPolygonBounds(polygon);
    if (!bounds || !(bounds.x2 > bounds.x1) || !(bounds.y2 > bounds.y1)) {
        return [];
    }

    const tolerance = Math.max(EDGE_TOLERANCE, 1e-7);
    const safeSpacing = Math.max(parsePositiveNumberOrFallback(spacing, 0.08, 0.02), 0.02);
    const safeInset = Math.max(parseNumberOrFallback(edgeInset, 0.006), 0);
    const minOffset = bounds.y1 - bounds.x2 + safeInset;
    const maxOffset = bounds.y2 - bounds.x1 - safeInset;
    const offsetStep = safeSpacing * Math.SQRT2;
    const direction = { x: Math.SQRT1_2, y: Math.SQRT1_2 };
    const segments = [];

    if (maxOffset < minOffset - tolerance) {
        return segments;
    }

    for (let offset = minOffset; offset <= maxOffset + tolerance; offset += offsetStep) {
        const intersections = [];
        const addIntersection = (rawX, rawY) => {
            if (!Number.isFinite(rawX) || !Number.isFinite(rawY)) {
                return;
            }
            const x = rawX;
            const y = rawX + offset;
            if (!intersections.some((point) => (
                Math.abs(point.x - x) <= tolerance
                && Math.abs(point.y - y) <= tolerance
            ))) {
                intersections.push({ x, y });
            }
        };

        for (let index = 0; index < polygon.length; index += 1) {
            const start = polygon[index];
            const end = polygon[(index + 1) % polygon.length];
            const startValue = start.y - start.x - offset;
            const endValue = end.y - end.x - offset;

            if (Math.abs(startValue) <= tolerance && Math.abs(endValue) <= tolerance) {
                addIntersection(start.x, start.y);
                addIntersection(end.x, end.y);
                continue;
            }
            if ((startValue > tolerance && endValue > tolerance) || (startValue < -tolerance && endValue < -tolerance)) {
                continue;
            }
            const denominator = startValue - endValue;
            if (Math.abs(denominator) <= tolerance) {
                continue;
            }
            const parameter = startValue / denominator;
            if (parameter < -tolerance || parameter > 1 + tolerance) {
                continue;
            }
            addIntersection(
                start.x + (end.x - start.x) * parameter,
                start.y + (end.y - start.y) * parameter
            );
        }

        intersections.sort((left, right) => (
            ((left.x + left.y) - (right.x + right.y)) || (left.x - right.x)
        ));

        for (let index = 0; index + 1 < intersections.length; index += 2) {
            const start = intersections[index];
            const end = intersections[index + 1];
            const midpoint = { x: (start.x + end.x) / 2, y: (start.y + end.y) / 2 };
            if (!isPointInPolygon(midpoint, polygon, { includeBoundary: false })) {
                continue;
            }
            const length = Math.hypot(end.x - start.x, end.y - start.y);
            if (!(length > Math.max(safeInset * 2, tolerance))) {
                continue;
            }
            const inset = Math.min(safeInset, length * 0.22);
            segments.push({
                x1: start.x + direction.x * inset,
                y1: start.y + direction.y * inset,
                x2: end.x - direction.x * inset,
                y2: end.y - direction.y * inset
            });
        }
    }

    return segments;
}

function getAnsi31RectHatchSegments(x1, y1, x2, y2, spacing = ANSI31_HATCH_SPACING, edgeInset = ANSI31_HATCH_EDGE_INSET) {
    const left = Math.min(x1, x2) + edgeInset;
    const right = Math.max(x1, x2) - edgeInset;
    const bottom = Math.min(y1, y2) + edgeInset;
    const top = Math.max(y1, y2) - edgeInset;
    const safeSpacing = Math.max(parsePositiveNumberOrFallback(spacing, ANSI31_HATCH_SPACING, 0.02), 0.02);

    if (right <= left + EDGE_TOLERANCE || top <= bottom + EDGE_TOLERANCE) {
        return [];
    }

    const lineOffsetStep = safeSpacing * Math.SQRT2;
    const minOffset = bottom - right;
    const maxOffset = top - left;
    const segments = [];

    for (let offset = minOffset; offset <= maxOffset + EDGE_TOLERANCE; offset += lineOffsetStep) {
        const points = [];
        const yAtLeft = left + offset;
        const yAtRight = right + offset;
        const xAtBottom = bottom - offset;
        const xAtTop = top - offset;

        if (yAtLeft >= bottom - EDGE_TOLERANCE && yAtLeft <= top + EDGE_TOLERANCE) {
            points.push({ x: left, y: yAtLeft });
        }
        if (yAtRight >= bottom - EDGE_TOLERANCE && yAtRight <= top + EDGE_TOLERANCE) {
            points.push({ x: right, y: yAtRight });
        }
        if (xAtBottom >= left - EDGE_TOLERANCE && xAtBottom <= right + EDGE_TOLERANCE) {
            points.push({ x: xAtBottom, y: bottom });
        }
        if (xAtTop >= left - EDGE_TOLERANCE && xAtTop <= right + EDGE_TOLERANCE) {
            points.push({ x: xAtTop, y: top });
        }

        const uniquePoints = [];
        points.forEach((point) => {
            const exists = uniquePoints.some((candidate) => (
                Math.abs(candidate.x - point.x) <= EDGE_TOLERANCE
                && Math.abs(candidate.y - point.y) <= EDGE_TOLERANCE
            ));
            if (!exists) {
                uniquePoints.push(point);
            }
        });

        if (uniquePoints.length < 2) {
            continue;
        }

        uniquePoints.sort((leftPoint, rightPoint) => (
            (leftPoint.x - rightPoint.x) || (leftPoint.y - rightPoint.y)
        ));

        const start = uniquePoints[0];
        const end = uniquePoints[uniquePoints.length - 1];
        if (Math.hypot(end.x - start.x, end.y - start.y) > EDGE_TOLERANCE) {
            segments.push({
                x1: start.x,
                y1: start.y,
                x2: end.x,
                y2: end.y
            });
        }
    }

    return segments;
}

function getAnsi31PolygonHatchSegments(vertices, spacing = ANSI31_HATCH_SPACING, edgeInset = ANSI31_HATCH_EDGE_INSET) {
    const polygon = (Array.isArray(vertices) ? vertices : [])
        .map((vertex) => ({ x: Number.parseFloat(vertex?.x), y: Number.parseFloat(vertex?.y) }))
        .filter((vertex) => Number.isFinite(vertex.x) && Number.isFinite(vertex.y));

    if (polygon.length < 3) {
        return [];
    }

    const safeSpacing = Math.max(parsePositiveNumberOrFallback(spacing, ANSI31_HATCH_SPACING, 0.02), 0.02);
    const bounds = getPolygonBounds(polygon);
    if (!bounds || !(bounds.x2 > bounds.x1 + EDGE_TOLERANCE) || !(bounds.y2 > bounds.y1 + EDGE_TOLERANCE)) {
        return [];
    }

    const centerX = (bounds.x1 + bounds.x2) / 2;
    const centerY = (bounds.y1 + bounds.y2) / 2;
    const insetPolygon = polygon.map((vertex) => {
        const dx = centerX - vertex.x;
        const dy = centerY - vertex.y;
        const length = Math.hypot(dx, dy);
        if (!(length > EDGE_TOLERANCE)) {
            return vertex;
        }
        const inset = Math.min(edgeInset, length * 0.35);
        return {
            x: vertex.x + (dx / length) * inset,
            y: vertex.y + (dy / length) * inset
        };
    });
    const insetBounds = getPolygonBounds(insetPolygon);
    if (!insetBounds || !(insetBounds.x2 > insetBounds.x1 + EDGE_TOLERANCE) || !(insetBounds.y2 > insetBounds.y1 + EDGE_TOLERANCE)) {
        return [];
    }

    const lineOffsetStep = safeSpacing * Math.SQRT2;
    const minOffset = insetBounds.y1 - insetBounds.x2;
    const maxOffset = insetBounds.y2 - insetBounds.x1;
    const segments = [];

    for (let offset = minOffset; offset <= maxOffset + EDGE_TOLERANCE; offset += lineOffsetStep) {
        const points = [];
        for (let index = 0; index < insetPolygon.length; index += 1) {
            const start = insetPolygon[index];
            const end = insetPolygon[(index + 1) % insetPolygon.length];
            const startValue = start.y - start.x - offset;
            const endValue = end.y - end.x - offset;

            if (Math.abs(startValue) <= EDGE_TOLERANCE) {
                points.push({ x: start.x, y: start.y });
            }
            if (Math.abs(endValue) <= EDGE_TOLERANCE) {
                points.push({ x: end.x, y: end.y });
            }
            if (startValue * endValue > EDGE_TOLERANCE) {
                continue;
            }
            const denominator = startValue - endValue;
            if (Math.abs(denominator) <= EDGE_TOLERANCE) {
                continue;
            }
            const t = startValue / denominator;
            if (t < -EDGE_TOLERANCE || t > 1 + EDGE_TOLERANCE) {
                continue;
            }
            points.push({
                x: start.x + (end.x - start.x) * t,
                y: start.y + (end.y - start.y) * t
            });
        }

        const uniquePoints = [];
        points.forEach((point) => {
            if (!uniquePoints.some((candidate) => (
                Math.abs(candidate.x - point.x) <= EDGE_TOLERANCE
                && Math.abs(candidate.y - point.y) <= EDGE_TOLERANCE
            ))) {
                uniquePoints.push(point);
            }
        });
        uniquePoints.sort((leftPoint, rightPoint) => (
            (leftPoint.x - rightPoint.x) || (leftPoint.y - rightPoint.y)
        ));

        for (let index = 0; index < uniquePoints.length - 1; index += 1) {
            const start = uniquePoints[index];
            const end = uniquePoints[index + 1];
            const midpoint = {
                x: (start.x + end.x) / 2,
                y: (start.y + end.y) / 2
            };
            if (!isPointInPolygon(midpoint, insetPolygon, { includeBoundary: false })) {
                continue;
            }

            const length = Math.hypot(end.x - start.x, end.y - start.y);
            if (!(length > EDGE_TOLERANCE)) {
                continue;
            }
            segments.push({
                x1: start.x,
                y1: start.y,
                x2: end.x,
                y2: end.y
            });
        }
    }

    return segments;
}

function getLightenedAxisRebar(lightened, axis) {
    return getLightenedZoneRebar(lightened, axis, "v");
}

function getLightenedZoneRebar(lightened, axis, zoneKey = "v") {
    const normalizedLightened = normalizeLightenedSlabConfig(lightened);
    const zones = axis === "x" ? normalizedLightened.xZones : normalizedLightened.yZones;
    return zones[LIGHTENED_SLAB_ZONE_KEYS.includes(zoneKey) ? zoneKey : "v"];
}

function formatLightenedZoneRebarLabel(rebar) {
    return formatDxfRebarCountLabel(rebar.bars, rebar.diameter);
}

function formatLightenedAxisZoneSeries(lightened, axis) {
    return LIGHTENED_SLAB_ZONE_KEYS
        .map((zoneKey) => formatLightenedZoneRebarLabel(getLightenedZoneRebar(lightened, axis, zoneKey)))
        .join("/");
}

function formatLengthInCentimeters(value) {
    return formatLengthForUnit(parseNumberOrFallback(value, 0), "section");
}

function formatLightenedSlabTableDepthLabel(slab) {
    const normalized = normalizeSlab(slab);
    return formatLengthInCentimeters(normalized.h);
}

function formatLightenedAxisRebarLabel(lightened, axis) {
    return `${axis.toUpperCase()}: ${formatLightenedAxisZoneSeries(lightened, axis)}`;
}

function getSlabDetailNote(slab) {
    const normalized = normalizeSlab(slab);
    if (normalized.type === "hole") {
        const bounds = normalizeSlabBounds(normalized);
        return [
            translate("modal.hole"),
            `${formatLengthForUnit(bounds.x2 - bounds.x1, "model")} x ${formatLengthForUnit(bounds.y2 - bounds.y1, "model")}`
        ].join(" | ");
    }
    const depthText = `h = ${formatLengthForUnit(normalized.h, "section")}`;
    const temperatureText = formatSlabTemperatureSteelLabel(normalized.temperatureSteel);
    if (normalized.type === "lightened") {
        return [
            `H ${formatLightenedSlabTableDepthLabel(normalized)}`,
            `X/Y I-V-J`,
            `Sep ${formatLengthForUnit(normalized.lightened.cassetteGap, "spacing")}`
        ]
            .filter(Boolean)
            .join(" | ");
    }

    const stairText = normalized.type === SLAB_TYPE_SOLID_STAIR ? translate("modal.slabSolidStair") : "";
    const slopeText = normalized.isSloped ? `dz = ${formatLengthForUnit(normalized.slopeHeight, "model")}` : "";

    return [
        stairText,
        depthText,
        `X ${formatLengthForUnit(normalized.solid.xSpacing, "spacing")}`,
        `Y ${formatLengthForUnit(normalized.solid.ySpacing, "spacing")}`,
        `${translate("modal.topSteel")} ${formatSlabTopSteelDirectionLabel(normalized.solid.topSteelDirection)}`,
        slopeText,
        temperatureText
    ]
        .filter(Boolean)
        .join(" | ");
}

function getSlabNameBadgeRadius(label, baseSize, minimumRadius, maximumRadius, widthFactor = 0.32) {
    const estimatedTextRadius = String(label || "").length * baseSize * widthFactor + baseSize * 0.7;
    return Math.max(minimumRadius, Math.min(estimatedTextRadius, maximumRadius));
}

function getCanvasSlabNameBadgeLayout(label, centerX, centerY, slabSize, forceSmall = false, zoomScale = 1) {
    if (!label) {
        return null;
    }

    const safeZoomScale = getScreenLockedZoomScale(zoomScale);
    const minRadius = Math.max(Math.min(slabSize * 0.1, 15), 10);
    const maxRadius = forceSmall ? minRadius : Math.max(Math.min(slabSize * 0.2, 26), 13);
    const radius = getSlabNameBadgeRadius(
        label,
        Math.max(Math.min(slabSize * 0.085, 13), 9),
        minRadius,
        maxRadius,
        0.34
    );
    const lockedRadius = radius / safeZoomScale;
    const fontSize = Math.max(Math.min(radius * 0.82, 11), 8) / safeZoomScale;

    return {
        label,
        centerX,
        centerY,
        radius: lockedRadius,
        fontSize,
        font: `600 ${fontSize}px "Segoe UI", sans-serif`,
        lineWidth: 1.5 / safeZoomScale,
        rect: {
            left: centerX - lockedRadius,
            top: centerY - lockedRadius,
            right: centerX + lockedRadius,
            bottom: centerY + lockedRadius
        }
    };
}

function drawCanvasSlabNameBadge(context, label, centerX, centerY, slabSize, palette, forceSmall = false, layout = null, zoomScale = 1) {
    const resolvedLayout = layout || getCanvasSlabNameBadgeLayout(label, centerX, centerY, slabSize, forceSmall, zoomScale);
    if (!resolvedLayout) {
        return;
    }

    context.save();
    context.fillStyle = palette.fillStyle;
    context.strokeStyle = palette.strokeStyle;
    context.lineWidth = resolvedLayout.lineWidth || (1.5 / getScreenLockedZoomScale(zoomScale));
    context.beginPath();
    context.arc(resolvedLayout.centerX, resolvedLayout.centerY, resolvedLayout.radius, 0, Math.PI * 2);
    context.fill();
    context.stroke();
    context.fillStyle = palette.textStyle;
    context.font = resolvedLayout.font || `600 ${resolvedLayout.fontSize || (11 / getScreenLockedZoomScale(zoomScale))}px "Segoe UI", sans-serif`;
    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillText(resolvedLayout.label, resolvedLayout.centerX, resolvedLayout.centerY);
    context.restore();
}

/* SERVER_ONLY_START */
function ensureSlabNameBadgeBlock(arr, label, textSize = getPlanAnnotationTextHeight()) {
    const blockEntities = ensureDxfBlockStore(arr);
    const circleLayer = "ETIQUETA_LOSA";
    const textLayer = "ETIQUETA_LOSA";
    const radius = 0.20; // Ø 0.40 m
    const text = sanitizeDxfText(label).trim() || "-";
    const key = ["slab-name-badge", circleLayer, textLayer, radius.toFixed(6), Number(textSize).toFixed(6), text].join("|");

    if (!(arr._namedDxfBlockNames instanceof Map)) arr._namedDxfBlockNames = new Map();
    if (!(arr._usedDxfBlockNames instanceof Set)) arr._usedDxfBlockNames = new Set();
    const existingName = arr._namedDxfBlockNames.get(key);
    if (existingName) return existingName;

    const baseName = `ETIQUETA_LOSA_${getDxfBlockHash(key)}`;
    let blockName = baseName;
    let suffix = 2;
    while (arr._usedDxfBlockNames.has(blockName)) {
        blockName = `${baseName}_${suffix}`;
        suffix += 1;
    }

    arr._namedDxfBlockNames.set(key, blockName);
    arr._usedDxfBlockNames.add(blockName);
    blockEntities.push(
        "0", "BLOCK", "8", circleLayer, "2", blockName, "70", "0",
        "10", "0", "20", "0", "30", "0", "3", blockName, "1", ""
    );
    addCircle(blockEntities, circleLayer, 0, 0, radius);
    addCenteredText(blockEntities, textLayer, 0, 0, text, textSize);
    blockEntities.push("0", "ENDBLK", "8", circleLayer);
    return blockName;
}

function addSlabNameBadgeBlock(arr, x, y, label, textSize = getPlanAnnotationTextHeight()) {
    if (!hasFiniteNumbers(x, y)) return;
    const blockName = ensureSlabNameBadgeBlock(arr, label, textSize);
    arr.push(
        "0", "INSERT", "8", "ETIQUETA_LOSA", "2", blockName,
        "10", x, "20", y, "30", "0", "41", "1", "42", "1", "43", "1", "50", "0"
    );
}

function drawDxfSlabNameBadge(plan, label, centerX, centerY, slabWidth, slabHeight, options = {}) {
    if (!label) return;
    const textSize = getPlanElementLabelTextSize(options.elementLabelTextSize, getPlanAnnotationTextHeight());
    const verticalOffset = 0.4;
    const badgeCenterY = centerY + verticalOffset;
    // The DXF badge is deliberately fixed at Ø0.40 m and emitted as one block.
    plan.addSlabNameBadgeBlock(centerX, badgeCenterY, label, textSize);
}
/* SERVER_ONLY_END */

function getSolidSlabHookPoint(point, tangentPoint, axis, hookLength, hookDirection, isStart) {
    const hookOffset = hookLength / Math.SQRT2;
    const tangentSign = axis === "x"
        ? Math.sign(isStart ? (tangentPoint?.x ?? point.x) - point.x : point.x - (tangentPoint?.x ?? point.x)) || 1
        : Math.sign(isStart ? (tangentPoint?.y ?? point.y) - point.y : point.y - (tangentPoint?.y ?? point.y)) || 1;
    const axialDirection = isStart ? tangentSign : -tangentSign;

    if (axis === "x") {
        return {
            x: point.x + axialDirection * hookOffset,
            y: point.y + hookDirection * hookOffset
        };
    }

    return {
        x: point.x + hookDirection * hookOffset,
        y: point.y + axialDirection * hookOffset
    };
}

function normalizeSolidSlabHookDirection(direction, fallback = 1) {
    const numericDirection = Number(direction);
    if (!Number.isFinite(numericDirection) || Math.abs(numericDirection) <= 1e-9) {
        return fallback;
    }

    return Math.sign(numericDirection);
}

function getSolidSlabBarSegments(bar) {
    const points = Array.isArray(bar?.points) ? bar.points : [];
    const segments = [];
    for (let index = 0; index < points.length - 1; index += 1) {
        const start = points[index];
        const end = points[index + 1];
        if (hasFiniteNumbers(start?.x, start?.y, end?.x, end?.y)) {
            segments.push({ x1: start.x, y1: start.y, x2: end.x, y2: end.y });
        }
    }
    return segments;
}

function getSolidSlabHookGeometry(bar, endpoint = "start") {
    const points = Array.isArray(bar?.points) ? bar.points : [];
    if (points.length < 2) return null;
    const isStart = endpoint === "start";
    const point = isStart ? points[0] : points[points.length - 1];
    const towardInterior = isStart ? points[1] : points[points.length - 2];
    const dx = towardInterior.x - point.x;
    const dy = towardInterior.y - point.y;
    const length = Math.hypot(dx, dy);
    if (!(length > EDGE_TOLERANCE)) return null;

    // u always points from the bar end toward the interior.  A 180-degree bend
    // returns to a line parallel to the principal bar and both hook tails run
    // inward, so they remain inside the slab footprint.
    const u = { x: dx / length, y: dy / length };
    const baseDirection = normalizeSolidSlabHookDirection(bar.hookDirection);
    const hookDirection = isStart
        ? normalizeSolidSlabHookDirection(bar.startHookDirection, baseDirection)
        : normalizeSolidSlabHookDirection(bar.endHookDirection, baseDirection);
    const v = bar.axis === "x"
        ? { x: 0, y: hookDirection }
        : { x: hookDirection, y: 0 };
    const radius = SOLID_SLAB_HOOK_BEND_RADIUS;
    const center = { x: point.x + v.x * radius, y: point.y + v.y * radius };

    // A semicircle ends two radii away in the hook-normal direction.  Its outer
    // half faces away from the slab interior, while the final 0.1187 m tail runs
    // back parallel to the longitudinal reinforcement.
    const arcEnd = {
        x: point.x + v.x * radius * 2,
        y: point.y + v.y * radius * 2
    };
    const arcMid = {
        x: center.x - u.x * radius,
        y: center.y - u.y * radius
    };
    const tailDirection = u;
    const tailEnd = {
        x: arcEnd.x + tailDirection.x * SOLID_SLAB_HOOK_TAIL_LENGTH,
        y: arcEnd.y + tailDirection.y * SOLID_SLAB_HOOK_TAIL_LENGTH
    };
    return { point, center, arcMid, arcEnd, tailEnd, radius };
}

function addSolidSlabHookToDxf(dxf, layer, geometry, mapX, mapY) {
    if (!geometry) return;
    const center = { x: mapX(geometry.center.x), y: mapY(geometry.center.y) };
    const start = { x: mapX(geometry.point.x), y: mapY(geometry.point.y) };
    const mid = { x: mapX(geometry.arcMid.x), y: mapY(geometry.arcMid.y) };
    const end = { x: mapX(geometry.arcEnd.x), y: mapY(geometry.arcEnd.y) };
    const tail = { x: mapX(geometry.tailEnd.x), y: mapY(geometry.tailEnd.y) };
    const startAngle = getDxfVectorAngleDegrees(start.x - center.x, start.y - center.y);
    const midAngle = getDxfVectorAngleDegrees(mid.x - center.x, mid.y - center.y);
    const endAngle = getDxfVectorAngleDegrees(end.x - center.x, end.y - center.y);
    if (!Number.isFinite(startAngle) || !Number.isFinite(midAngle) || !Number.isFinite(endAngle)) return;

    // DXF arcs are counter-clockwise.  Start/end points of a semicircle are
    // diametrically opposite, so use the intended midpoint to select the outer
    // half rather than accidentally drawing the inward-facing semicircle.
    const directSweep = getPositiveDxfAngleSweep(startAngle, endAngle);
    const sweepToMid = getPositiveDxfAngleSweep(startAngle, midAngle);
    const midpointIsOnDirectSweep = sweepToMid <= directSweep + 1e-6;
    if (midpointIsOnDirectSweep) {
        addArcPolyline(dxf, layer, center.x, center.y, geometry.radius, startAngle, endAngle);
    } else {
        addArcPolyline(dxf, layer, center.x, center.y, geometry.radius, endAngle, startAngle);
    }
    addPolylineLine(dxf, layer, end.x, end.y, tail.x, tail.y);
}

function getSolidSlabVisibleSegments(bar, slab) {
    const sourceSegments = getSolidSlabBarSegments(bar);
    const continuationNeighbor = bar?.continuationNeighbor || null;
    const clipRegions = Array.isArray(bar?.clipRegions) ? bar.clipRegions : [];
    const clipSlabs = continuationNeighbor
        ? [slab, ...clipRegions, continuationNeighbor]
        : [slab, ...clipRegions];

    return clipSlabs.flatMap((clipSlab) => clipSegmentsToSlabPolygon(sourceSegments, clipSlab));
}

function drawSolidSlabPreviewBar(context, bar, slab, toCanvasX, toCanvasY) {
    context.beginPath();
    getSolidSlabVisibleSegments(bar, slab).forEach((segment) => {
        context.moveTo(toCanvasX(segment.x1), toCanvasY(segment.y1));
        context.lineTo(toCanvasX(segment.x2), toCanvasY(segment.y2));
    });
    context.stroke();
}

/* SERVER_ONLY_START */
function addSolidSlabBarToDxf(dxf, layer, bar, slab, mapX = (value) => value, mapY = (value) => value) {
    getSolidSlabVisibleSegments(bar, slab).forEach((segment) => {
        addPolyline(dxf, layer, [
            { x: mapX(segment.x1), y: mapY(segment.y1) },
            { x: mapX(segment.x2), y: mapY(segment.y2) }
        ]);
    });
    addSolidSlabHookToDxf(dxf, layer, getSolidSlabHookGeometry(bar, "start"), mapX, mapY);
    addSolidSlabHookToDxf(dxf, layer, getSolidSlabHookGeometry(bar, "end"), mapX, mapY);
}

function getAxisAlignedSlabBarSegment(segments, axis) {
    const candidates = (segments || [])
        .map((segment) => {
            const dx = segment.x2 - segment.x1;
            const dy = segment.y2 - segment.y1;
            const axisSpan = axis === "x" ? Math.abs(dx) : Math.abs(dy);
            const offAxisSpan = axis === "x" ? Math.abs(dy) : Math.abs(dx);

            return {
                ...segment,
                axisSpan,
                offAxisSpan
            };
        })
        .filter((segment) => segment.axisSpan > 0.08 && segment.offAxisSpan < 0.03)
        .sort((a, b) => b.axisSpan - a.axisSpan);

    return candidates[0] || null;
}

function addManualDimensionTick(dxf, layer, centerX, centerY, size = 0.20) {
    const half = size / 2;
    const offset = half / Math.SQRT2;

    addLine(
        dxf,
        layer,
        centerX - offset,
        centerY - offset,
        centerX + offset,
        centerY + offset
    );
}

function getSolidSlabSpacingDimensionData(slabs, slab, axis, supportContext = null) {
    const normalizedSlab = normalizeSlab(slab);
    const bars = getSolidSlabRepresentativeBars(slabs, normalizedSlab, axis, supportContext);

    if (bars.length < 2) {
        return null;
    }

    const primaryBar = bars.find((bar) => bar.primary) || bars[0];
    const secondaryBar = bars.find((bar) => !bar.primary) || bars[1];

    const primarySegment = getAxisAlignedSlabBarSegment(
        getSolidSlabVisibleSegments(primaryBar, normalizedSlab),
        axis
    );
    const secondarySegment = getAxisAlignedSlabBarSegment(
        getSolidSlabVisibleSegments(secondaryBar, normalizedSlab),
        axis
    );

    if (!primarySegment || !secondarySegment) {
        return null;
    }

    const label = formatSlabSpacingLabel(
        axis === "x" ? normalizedSlab.solid.xBarDiameter : normalizedSlab.solid.yBarDiameter,
        axis === "x" ? normalizedSlab.solid.xSpacing : normalizedSlab.solid.ySpacing
    );

    const leaderOrthLength = 0.18;
    const leaderDiagLength = 0.18;
    const textOffsetX = 0.04;
    const textOffsetY = 0.03;

    if (axis === "x") {
        const p1Start = Math.min(primarySegment.x1, primarySegment.x2);
        const p1End = Math.max(primarySegment.x1, primarySegment.x2);
        const p2Start = Math.min(secondarySegment.x1, secondarySegment.x2);
        const p2End = Math.max(secondarySegment.x1, secondarySegment.x2);

        const overlapStart = Math.max(p1Start, p2Start);
        const overlapEnd = Math.min(p1End, p2End);

        const dimX = overlapEnd > overlapStart
            ? (overlapStart + overlapEnd) / 2
            : (p1Start + p1End) / 2;

        const y1 = (primarySegment.y1 + primarySegment.y2) / 2;
        const y2 = (secondarySegment.y1 + secondarySegment.y2) / 2;
        const midY = (y1 + y2) / 2;

        const leaderStart = { x: dimX, y: midY };
        const leaderCorner = { x: dimX + leaderOrthLength, y: midY };
        const leaderEnd = {
            x: leaderCorner.x + leaderDiagLength,
            y: leaderCorner.y + leaderDiagLength
        };

        return {
            lineStart: { x: dimX, y: y1 },
            lineEnd: { x: dimX, y: y2 },
            text: label,
            textX: leaderEnd.x + textOffsetX,
            textY: leaderEnd.y + textOffsetY,
            leaderStart,
            leaderCorner,
            leaderEnd
        };
    }

    const p1Start = Math.min(primarySegment.y1, primarySegment.y2);
    const p1End = Math.max(primarySegment.y1, primarySegment.y2);
    const p2Start = Math.min(secondarySegment.y1, secondarySegment.y2);
    const p2End = Math.max(secondarySegment.y1, secondarySegment.y2);

    const overlapStart = Math.max(p1Start, p2Start);
    const overlapEnd = Math.min(p1End, p2End);

    const dimY = overlapEnd > overlapStart
        ? (overlapStart + overlapEnd) / 2
        : (p1Start + p1End) / 2;

    const x1 = (primarySegment.x1 + primarySegment.x2) / 2;
    const x2 = (secondarySegment.x1 + secondarySegment.x2) / 2;
    const midX = (x1 + x2) / 2;

    // En la planta de losas el eje Y se invierte al mapear a DXF; sumar
    // 0.25 m en coordenadas de planta baja visualmente todo el detalle del acero en Y.
    const ySteelOffset = SLAB_PLAN_Y_STEEL_TEXT_DOWN_OFFSET;
    const dimensionY = dimY + ySteelOffset;

    const leaderStart = { x: midX, y: dimensionY };
    const leaderCorner = { x: midX, y: dimensionY + leaderOrthLength };
    const leaderEnd = {
        x: leaderCorner.x + leaderDiagLength,
        y: leaderCorner.y + leaderDiagLength
    };

    return {
        lineStart: { x: x1, y: dimensionY },
        lineEnd: { x: x2, y: dimensionY },
        text: label,
        textX: leaderEnd.x + textOffsetX,
        textY: leaderEnd.y + textOffsetY,
        leaderStart,
        leaderCorner,
        leaderEnd
    };
    }

function addManualSlabSpacingDimensionToDxf(dxf, slabs, slab, axis, mapX = (value) => value, mapY = (value) => value, supportContext = null) {
    const data = getSolidSlabSpacingDimensionData(slabs, slab, axis, supportContext);

    if (!data) {
        return;
    }

    addManualDimensionTick(
        dxf,
        SLAB_PLAN_DRAWING_TEXT_LAYER,
        mapX(data.lineStart.x),
        mapY(data.lineStart.y)
    );

    addManualDimensionTick(
        dxf,
        SLAB_PLAN_DRAWING_TEXT_LAYER,
        mapX(data.lineEnd.x),
        mapY(data.lineEnd.y)
    );

    addLine(
        dxf,
        SLAB_PLAN_DRAWING_TEXT_LAYER,
        mapX(data.lineStart.x),
        mapY(data.lineStart.y),
        mapX(data.lineEnd.x),
        mapY(data.lineEnd.y)
    );

    addLine(
        dxf,
        SLAB_PLAN_DRAWING_TEXT_LAYER,
        mapX(data.leaderStart.x),
        mapY(data.leaderStart.y),
        mapX(data.leaderCorner.x),
        mapY(data.leaderCorner.y)
    );

    addLine(
        dxf,
        SLAB_PLAN_DRAWING_TEXT_LAYER,
        mapX(data.leaderCorner.x),
        mapY(data.leaderCorner.y),
        mapX(data.leaderEnd.x),
        mapY(data.leaderEnd.y)
    );

    addText(
        dxf,
        SLAB_PLAN_DRAWING_TEXT_LAYER,
        mapX(data.textX),
        mapY(data.textY),
        data.text,
        SLAB_PLAN_STEEL_TEXT_HEIGHT
    );
}
/* SERVER_ONLY_END */

function getBeamSpan(beam) {
    return Math.max(Math.abs(beam.x2 - beam.x1), Math.abs(beam.y2 - beam.y1));
}

function getDefaultBeamSectionCuts(beamOrSpan) {
    const span = typeof beamOrSpan === "number" ? beamOrSpan : getBeamSpan(beamOrSpan);
    if (!Number.isFinite(span) || span <= 0.01) {
        return [];
    }

    return [span / 2];
}

function normalizeSectionCuts(sectionCuts, beamOrSpan) {
    const span = typeof beamOrSpan === "number" ? beamOrSpan : getBeamSpan(beamOrSpan);
    if (span <= 0) {
        return [];
    }

    const cuts = (Array.isArray(sectionCuts) ? sectionCuts : [])
        .map((value) => parseNumberOrFallback(value, Number.NaN))
        .filter((value) => !Number.isNaN(value))
        .map((value) => Math.min(Math.max(value, 0), span))
        .sort((a, b) => a - b);

    const uniqueCuts = cuts.filter((value, index) => index === 0 || Math.abs(value - cuts[index - 1]) > 0.01);
    return uniqueCuts.length ? uniqueCuts : getDefaultBeamSectionCuts(span);
}

function parseSectionCutsInput(value, beam) {
    const span = getBeamSpan(beam);
    const values = String(value || "").match(/\d+(?:[.,]\d+)?/g) || [];

    return normalizeSectionCuts(
        values.map((entry) => Number.parseFloat(entry.replace(",", "."))),
        span
    );
}

function formatSectionCuts(sectionCuts, beam) {
    return normalizeSectionCuts(sectionCuts, beam)
        .map((value) => value.toFixed(2))
        .join("; ");
}

function escapeHtml(value) {
    return String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

function getMarkerPositions(start, end, spacing, edgeOffset = 0.15) {
    const safeSpacing = Math.max(parseNumberOrFallback(spacing, DEFAULT_BEAM_STIRRUP_SPACING), 0.05);
    const span = end - start;
    if (span <= 0) {
        return [];
    }

    const effectiveOffset = Math.max(0, Math.min(edgeOffset, span / 2));
    const first = start + effectiveOffset;
    const last = end - effectiveOffset;
    if (last <= first + 0.01) {
        return [(start + end) / 2];
    }

    const positions = [first];
    let current = first + safeSpacing;

    while (current < last - 0.01) {
        positions.push(Number(current.toFixed(3)));
        current += safeSpacing;
    }

    if (positions[positions.length - 1] < last - 0.01) {
        positions.push(Number(last.toFixed(3)));
    }

    return positions;
}

function getClosestValue(values, target) {
    if (!Array.isArray(values) || values.length === 0) {
        return null;
    }

    return values.reduce((closest, current) => (
        Math.abs(current - target) < Math.abs(closest - target) ? current : closest
    ));
}

/* SERVER_ONLY_START */
function ensureDxfBlockStore(arr) {
    if (!Array.isArray(arr._blocks)) {
        arr._blocks = [];
    }

    if (!Number.isInteger(arr._dimensionBlockCount)) {
        arr._dimensionBlockCount = 0;
    }

    return arr._blocks;
}

function getNextDxfDimensionBlockName(arr) {
    ensureDxfBlockStore(arr);
    arr._dimensionBlockCount += 1;
    return `*D${arr._dimensionBlockCount}`;
}

function getDxfBlockHash(value) {
    const input = String(value ?? "");
    let hash = 2166136261;
    for (let index = 0; index < input.length; index += 1) {
        hash ^= input.charCodeAt(index);
        hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(36).toUpperCase();
}

function ensureAxisBubbleBlock(arr, label, options = {}) {
    const blockEntities = ensureDxfBlockStore(arr);
    const circleLayer = DXF_AXIS_CIRCLE_LAYER;
    const textLayer = DXF_AXIS_TEXT_LAYER;
    const radius = DXF_AXIS_CIRCLE_RADIUS;
    const textHeight = DXF_AXIS_TEXT_HEIGHT;
    const textStyle = DXF_AXIS_TEXT_STYLE_NAME;
    const text = sanitizeDxfText(label).trim() || "-";
    const key = ["axis-bubble", circleLayer, textLayer, textStyle, radius.toFixed(6), textHeight.toFixed(6), text].join("|");

    if (!(arr._namedDxfBlockNames instanceof Map)) {
        arr._namedDxfBlockNames = new Map();
    }
    if (!(arr._usedDxfBlockNames instanceof Set)) {
        arr._usedDxfBlockNames = new Set();
    }

    const existingName = arr._namedDxfBlockNames.get(key);
    if (existingName) {
        return existingName;
    }

    const baseName = `EJE_CIRCULAR_${getDxfBlockHash(key)}`;
    let blockName = baseName;
    let suffix = 2;
    while (arr._usedDxfBlockNames.has(blockName)) {
        blockName = `${baseName}_${suffix}`;
        suffix += 1;
    }

    arr._namedDxfBlockNames.set(key, blockName);
    arr._usedDxfBlockNames.add(blockName);
    blockEntities.push(
        "0", "BLOCK",
        "8", circleLayer,
        "2", blockName,
        "70", "0",
        "10", "0", "20", "0", "30", "0",
        "3", blockName,
        "1", ""
    );
    addCircle(blockEntities, circleLayer, 0, 0, radius);
    addCenteredText(blockEntities, textLayer, 0, 0, text, textHeight, textStyle);
    blockEntities.push("0", "ENDBLK", "8", circleLayer);
    return blockName;
}

function addAxisBubbleBlock(arr, x, y, label, options = {}) {
    if (!hasFiniteNumbers(x, y)) {
        return;
    }

    const layer = DXF_AXIS_CIRCLE_LAYER;
    const blockName = ensureAxisBubbleBlock(arr, label, options);
    arr.push(
        "0", "INSERT",
        "8", layer,
        "2", blockName,
        "10", x,
        "20", y,
        "30", "0",
        "41", "1",
        "42", "1",
        "43", "1",
        "50", "0"
    );
}


function ensureFrameSectionBubbleBlock(arr, label, options = {}) {
    const blockEntities = ensureDxfBlockStore(arr);
    const lineLayer = options.lineLayer || "CORTE_PORTICO";
    const textLayer = options.textLayer || "TEXTO_CORTE_PORTICO";
    const radius = Math.max(parsePositiveNumberOrFallback(options.radius, 0.075, 0.001), 0.001);
    const textHeight = Math.max(parsePositiveNumberOrFallback(options.textHeight, 0.06, 0.001), 0.001);
    const text = sanitizeDxfText(label).trim() || "S1";
    const key = ["frame-section-bubble", lineLayer, textLayer, radius.toFixed(6), textHeight.toFixed(6), text].join("|");

    if (!(arr._namedDxfBlockNames instanceof Map)) {
        arr._namedDxfBlockNames = new Map();
    }
    if (!(arr._usedDxfBlockNames instanceof Set)) {
        arr._usedDxfBlockNames = new Set();
    }

    const existingName = arr._namedDxfBlockNames.get(key);
    if (existingName) {
        return existingName;
    }

    const baseName = `CORTE_PORTICO_${getDxfBlockHash(key)}`;
    let blockName = baseName;
    let suffix = 2;
    while (arr._usedDxfBlockNames.has(blockName)) {
        blockName = `${baseName}_${suffix}`;
        suffix += 1;
    }

    arr._namedDxfBlockNames.set(key, blockName);
    arr._usedDxfBlockNames.add(blockName);
    blockEntities.push(
        "0", "BLOCK",
        "8", lineLayer,
        "2", blockName,
        "70", "0",
        "10", "0", "20", "0", "30", "0",
        "3", blockName,
        "1", ""
    );
    addCircle(blockEntities, lineLayer, 0, 0, radius);
    addCenteredText(blockEntities, textLayer, 0, 0, text, textHeight);
    blockEntities.push("0", "ENDBLK", "8", lineLayer);
    return blockName;
}

function addFrameSectionBubbleBlock(arr, x, y, label, options = {}) {
    if (!hasFiniteNumbers(x, y)) {
        return;
    }
    const lineLayer = options.lineLayer || "CORTE_PORTICO";
    const blockName = ensureFrameSectionBubbleBlock(arr, label, options);
    arr.push(
        "0", "INSERT",
        "8", lineLayer,
        "2", blockName,
        "10", x,
        "20", y,
        "30", "0",
        "41", "1",
        "42", "1",
        "43", "1",
        "50", "0"
    );
}

function getAlignedDimensionGeometry(startPoint, endPoint, linePoint) {
    if (!hasFiniteNumbers(startPoint?.x, startPoint?.y, endPoint?.x, endPoint?.y, linePoint?.x, linePoint?.y)) {
        return null;
    }

    const dx = endPoint.x - startPoint.x;
    const dy = endPoint.y - startPoint.y;
    const length = Math.hypot(dx, dy);
    if (length <= EDGE_TOLERANCE) {
        return null;
    }

    const unitX = dx / length;
    const unitY = dy / length;
    let normalX = -unitY;
    let normalY = unitX;
    const rawOffset = ((linePoint.x - startPoint.x) * normalX) + ((linePoint.y - startPoint.y) * normalY);
    if (rawOffset < 0) {
        normalX *= -1;
        normalY *= -1;
    }

    const offset = Math.abs(rawOffset);
    const dimStart = {
        x: startPoint.x + normalX * offset,
        y: startPoint.y + normalY * offset
    };
    const dimEnd = {
        x: endPoint.x + normalX * offset,
        y: endPoint.y + normalY * offset
    };

    const rawRotation = Math.atan2(unitY, unitX) * 180 / Math.PI;
    const rotation = rawRotation > 90
        ? rawRotation - 180
        : rawRotation < -90
            ? rawRotation + 180
            : rawRotation;

    return {
        length,
        offset,
        unitX,
        unitY,
        normalX,
        normalY,
        dimStart,
        dimEnd,
        textCenter: {
            x: (dimStart.x + dimEnd.x) / 2,
            y: (dimStart.y + dimEnd.y) / 2
        },
        rotation
    };
}

function addDimensionArchitecturalTick(arr, layer, tipX, tipY, directionX, directionY, size) {
    if (!hasFiniteNumbers(tipX, tipY, directionX, directionY, size)) {
        return;
    }

    const magnitude = Math.hypot(directionX, directionY);
    if (magnitude <= EDGE_TOLERANCE) {
        return;
    }

    // Architectural ticks are short 45-degree strokes centered at the dimension line.
    // This mirrors the _ARCHTICK arrowhead assigned to Arrow 1 and Arrow 2 in the DIMSTYLE.
    const unitX = directionX / magnitude;
    const unitY = directionY / magnitude;
    const tickUnitX = (unitX - unitY) / Math.SQRT2;
    const tickUnitY = (unitY + unitX) / Math.SQRT2;
    const halfLength = Math.max(size, 0) / 2;

    addLine(
        arr,
        layer,
        tipX - tickUnitX * halfLength,
        tipY - tickUnitY * halfLength,
        tipX + tickUnitX * halfLength,
        tipY + tickUnitY * halfLength,
        "CONTINUOUS",
        null,
        DXF_DIMENSION_LINE_COLOR
    );
}

function addDimensionClosedFilledArrow(arr, layer, tipX, tipY, directionX, directionY, size) {
    if (!hasFiniteNumbers(tipX, tipY, directionX, directionY, size)) {
        return;
    }

    const magnitude = Math.hypot(directionX, directionY);
    if (magnitude <= EDGE_TOLERANCE) {
        return;
    }

    const unitX = directionX / magnitude;
    const unitY = directionY / magnitude;
    const arrowLength = Math.max(size * 1.8, 0.018);
    const halfWidth = Math.max(size * 0.62, 0.008);
    const baseCenterX = tipX + unitX * arrowLength;
    const baseCenterY = tipY + unitY * arrowLength;
    const perpendicularX = -unitY;
    const perpendicularY = unitX;
    const leftBase = {
        x: baseCenterX + perpendicularX * halfWidth,
        y: baseCenterY + perpendicularY * halfWidth
    };
    const rightBase = {
        x: baseCenterX - perpendicularX * halfWidth,
        y: baseCenterY - perpendicularY * halfWidth
    };

    arr.push(
        "0", "SOLID",
        "8", layer,
        "62", String(DXF_DIMENSION_LINE_COLOR),
        "10", tipX,
        "20", tipY,
        "11", leftBase.x,
        "21", leftBase.y,
        "12", rightBase.x,
        "22", rightBase.y,
        "13", rightBase.x,
        "23", rightBase.y
    );
}

function addAlignedDimension(arr, layer, startPoint, endPoint, linePoint, value, options = {}) {
    if (!hasFiniteNumbers(startPoint?.x, startPoint?.y, endPoint?.x, endPoint?.y, linePoint?.x, linePoint?.y)) {
        return;
    }

    const geometry = getAlignedDimensionGeometry(startPoint, endPoint, linePoint);
    if (!geometry) {
        return;
    }

    const {
        length,
        offset,
        unitX,
        unitY,
        normalX,
        normalY,
        dimStart,
        dimEnd,
        textCenter,
        rotation
    } = geometry;
    const visualScale = Math.max(parseNumberOrFallback(options.visualScale, 1), 0.05);
    const blockName = getNextDxfDimensionBlockName(arr);
    const blockEntities = ensureDxfBlockStore(arr);
    const dimensionValue = sanitizeDxfText(formatDxfDimensionLabel(value, {
        ...options,
        measurementMeters: length
    }));
    // Keep every dimension at the requested Architectural Tick size, regardless of drawing visual scale.
    const arrowSize = DXF_DIMENSION_ARROW_SIZE;
    // Dimension text is a plotted standard, not a view-dependent annotation.
    // Keep all DXF dimensions at 0.06 m regardless of the source drawing scale.
    const dimensionTextHeight = Math.max(parsePositiveNumberOrFallback(options.textHeight, DXF_DIMENSION_TEXT_HEIGHT, 0.001), 0.001);
    const textHalfLength = estimateDxfTextWidth(dimensionValue, dimensionTextHeight) / 2 + DXF_DIMENSION_TEXT_GAP * visualScale;
    const midpointLength = length / 2;
    const gapStart = Math.max(arrowSize * 1.4, midpointLength - textHalfLength);
    const gapEnd = Math.min(length - arrowSize * 1.4, midpointLength + textHalfLength);
    const extensionOvershoot = Math.min(
        DXF_DIMENSION_EXTENSION_OVERSHOOT * visualScale,
        Math.max(length * 0.2, DXF_DIMENSION_MIN_ARROW_SIZE * visualScale)
    );

    // DXF dimensions reference an anonymous block containing their rendered geometry.
    blockEntities.push(
        "0", "BLOCK",
        "8", layer,
        "2", blockName,
        "70", "65",
        "10", "0",
        "20", "0",
        "30", "0",
        "3", blockName,
        "1", ""
    );

    if (offset > EDGE_TOLERANCE) {
        addLine(
            blockEntities,
            layer,
            startPoint.x,
            startPoint.y,
            dimStart.x + normalX * extensionOvershoot,
            dimStart.y + normalY * extensionOvershoot,
            "CONTINUOUS",
            null,
            DXF_DIMENSION_EXTENSION_LINE_COLOR
        );
        addLine(
            blockEntities,
            layer,
            endPoint.x,
            endPoint.y,
            dimEnd.x + normalX * extensionOvershoot,
            dimEnd.y + normalY * extensionOvershoot,
            "CONTINUOUS",
            null,
            DXF_DIMENSION_EXTENSION_LINE_COLOR
        );
    }

    if (gapEnd > gapStart) {
        addLine(
            blockEntities,
            layer,
            dimStart.x,
            dimStart.y,
            dimStart.x + unitX * gapStart,
            dimStart.y + unitY * gapStart,
            "CONTINUOUS",
            null,
            DXF_DIMENSION_LINE_COLOR
        );
        addLine(
            blockEntities,
            layer,
            dimStart.x + unitX * gapEnd,
            dimStart.y + unitY * gapEnd,
            dimEnd.x,
            dimEnd.y,
            "CONTINUOUS",
            null,
            DXF_DIMENSION_LINE_COLOR
        );
    } else {
        addLine(
            blockEntities,
            layer,
            dimStart.x,
            dimStart.y,
            dimEnd.x,
            dimEnd.y,
            "CONTINUOUS",
            null,
            DXF_DIMENSION_LINE_COLOR
        );
    }

    if (options.arrowStyle === "closed-filled") {
        addDimensionClosedFilledArrow(blockEntities, layer, dimStart.x, dimStart.y, unitX, unitY, arrowSize);
        addDimensionClosedFilledArrow(blockEntities, layer, dimEnd.x, dimEnd.y, -unitX, -unitY, arrowSize);
    } else {
        addDimensionArchitecturalTick(blockEntities, layer, dimStart.x, dimStart.y, unitX, unitY, arrowSize);
        addDimensionArchitecturalTick(blockEntities, layer, dimEnd.x, dimEnd.y, -unitX, -unitY, arrowSize);
    }
    const normalizedTextHorizontalPosition = options.textHorizontalPosition === "firstExtensionLine"
        ? "firstExtensionLine"
        : options.textHorizontalPosition === "secondExtensionLine"
            ? "secondExtensionLine"
            : "centered";
    const renderedTextCenter = normalizedTextHorizontalPosition === "firstExtensionLine"
        ? dimStart
        : normalizedTextHorizontalPosition === "secondExtensionLine"
            ? dimEnd
            : textCenter;

    addRotatedCenteredText(
        blockEntities,
        layer,
        renderedTextCenter.x,
        renderedTextCenter.y,
        dimensionValue,
        dimensionTextHeight,
        rotation,
        DXF_DIMENSION_TEXT_COLOR
    );
    blockEntities.push("0", "ENDBLK", "8", layer);

    // Numeric dimensions must use AutoCAD's measured-value token instead of
    // storing the initially rendered label as a text override.  Otherwise the
    // displayed value remains frozen when the dimension grips are stretched.
    // preserveValue is reserved for intentional symbolic labels such as LX,
    // H, e, or VARIABLE that are annotations rather than measured values.
    const dimensionEntityText = options.preserveValue ? dimensionValue : "<>";

    arr.push(
        "0", "DIMENSION",
        "8", layer,
        "6", "CONTINUOUS",
        "2", blockName,
        "3", DXF_DIM_STYLE_NAME,
        "10", linePoint.x,
        "20", linePoint.y,
        "30", "0",
        "11", renderedTextCenter.x,
        "21", renderedTextCenter.y,
        "31", "0",
        "12", "0",
        "22", "0",
        "32", "0",
        "70", "1",
        "1", dimensionEntityText,
        "13", startPoint.x,
        "23", startPoint.y,
        "33", "0",
        "14", endPoint.x,
        "24", endPoint.y,
        "34", "0"
    );

    const dimStyleOverrides = [];
    const outputUnitScale = Math.max(Number.parseFloat(getDxfUnitDefinition().scale) || 1, 1e-9);
    const defaultOutputTextHeight = getDxfDimensionStyleTextHeight() * outputUnitScale;
    const outputTextHeight = dimensionTextHeight * outputUnitScale;
    const hasExplicitTextHeight = Number.isFinite(Number.parseFloat(options.textHeight));
    if (hasExplicitTextHeight || Math.abs(outputTextHeight - defaultOutputTextHeight) > 1e-9) {
        dimStyleOverrides.push("1070", "140", "1040", formatUnitNumber(outputTextHeight, 6));
    }
    if (getCurrentUnitSystem() === "imperial") {
        const architecturalDenominator = normalizeArchitecturalDenominator(
            options.architecturalDenominator,
            DXF_IMPERIAL_DETAIL_DENOMINATOR
        );
        const architecturalPrecision = Math.max(0, Math.round(Math.log2(architecturalDenominator)));
        if (architecturalPrecision !== Math.round(Math.log2(DXF_IMPERIAL_DETAIL_DENOMINATOR))) {
            dimStyleOverrides.push("1070", "271", "1070", String(architecturalPrecision));
        }
    }
    if (normalizedTextHorizontalPosition !== "centered") {
        const dimJust = normalizedTextHorizontalPosition === "firstExtensionLine" ? 1 : 2;
        dimStyleOverrides.push("1070", "280", "1070", String(dimJust));
    }
    if (dimStyleOverrides.length) {
        arr.push(
            "1001", "ACAD",
            "1000", "DSTYLE",
            "1002", "{",
            ...dimStyleOverrides,
            "1002", "}"
        );
    }
}

function addDimension(arr, layer, x1, x2, y, value, originY = y, options = {}) {
    const startX = Math.min(x1, x2);
    const endX = Math.max(x1, x2);
    addAlignedDimension(
        arr,
        layer,
        { x: startX, y: originY },
        { x: endX, y: originY },
        { x: (startX + endX) / 2, y },
        value,
        options
    );
}

function addVerticalDimension(arr, layer, x, y1, y2, value, originX = x, options = {}) {
    const startY = Math.min(y1, y2);
    const endY = Math.max(y1, y2);
    addAlignedDimension(
        arr,
        layer,
        { x: originX, y: startY },
        { x: originX, y: endY },
        { x, y: (startY + endY) / 2 },
        value,
        options
    );
}

function drawAxisBubble(arr, x, y, label, lineLength, options = {}) {
    addAxisBubbleBlock(arr, x, y + 0.25, label, {
        layer: "COTAS_EJES",
        radius: 0.25,
        textHeight: 0.2
    });
    const safeLineLength = Math.max(parseNumberOrFallback(lineLength, 0), 0);
    const lineTypeScale = Number.parseFloat(options.lineTypeScale);
    addLine(
        arr,
        DXF_AXIS_LINE_LAYER,
        x,
        y,
        x,
        y - safeLineLength,
        DXF_AXIS_LINE_TYPE,
        Number.isFinite(lineTypeScale) ? lineTypeScale : null
    );
}


function isBeamLongitudinalRebarLayer(layer) {
    const normalizedLayer = String(layer || "").trim().toUpperCase();
    return normalizedLayer === "ACERO_SUPERIOR" || normalizedLayer === "ACERO_INFERIOR";
}

function appendUniqueDxfRoutePoint(points, point, tolerance = 1e-8) {
    if (!Array.isArray(points) || !hasFiniteNumbers(point?.x, point?.y)) {
        return;
    }

    const previous = points[points.length - 1];
    if (previous && Math.hypot(previous.x - point.x, previous.y - point.y) <= tolerance) {
        return;
    }
    points.push({ x: point.x, y: point.y });
}

function appendDirectedDxfArcRoute(points, centerX, centerY, radius, startAngle, endAngle, clockwise = false) {
    if (!Array.isArray(points) || !hasFiniteNumbers(centerX, centerY, radius, startAngle, endAngle) || !(radius > 0)) {
        return;
    }

    let sweep = endAngle - startAngle;
    if (clockwise) {
        while (sweep >= 0) {
            sweep -= 360;
        }
    } else {
        while (sweep <= 0) {
            sweep += 360;
        }
    }
    const segmentCount = Math.max(6, Math.min(Math.ceil(Math.abs(sweep) / 7.5), 48));
    for (let index = 0; index <= segmentCount; index += 1) {
        const angle = startAngle + (sweep * index) / segmentCount;
        appendUniqueDxfRoutePoint(points, getDxfAnglePoint(centerX, centerY, radius, angle));
    }
}

function buildBeamLongitudinalCenterlineRoute({
    barStartX,
    barEndX,
    barCenterY,
    hookLevel,
    hookLeft,
    hookRight,
    bendRadius,
    curvedHooks
}) {
    if (!hasFiniteNumbers(barStartX, barEndX, barCenterY, hookLevel, bendRadius) || barEndX <= barStartX) {
        return [];
    }

    const points = [];
    const hookDirectionY = Math.sign(hookLevel - barCenterY) || 1;
    if (!curvedHooks) {
        if (hookLeft) {
            appendUniqueDxfRoutePoint(points, { x: barStartX, y: hookLevel });
        }
        appendUniqueDxfRoutePoint(points, { x: barStartX, y: barCenterY });
        appendUniqueDxfRoutePoint(points, { x: barEndX, y: barCenterY });
        if (hookRight) {
            appendUniqueDxfRoutePoint(points, { x: barEndX, y: hookLevel });
        }
        return points;
    }

    if (hookLeft) {
        appendUniqueDxfRoutePoint(points, { x: barStartX, y: hookLevel });
        appendUniqueDxfRoutePoint(points, {
            x: barStartX,
            y: barCenterY + hookDirectionY * bendRadius
        });
        if (hookDirectionY > 0) {
            appendDirectedDxfArcRoute(
                points,
                barStartX + bendRadius,
                barCenterY + bendRadius,
                bendRadius,
                180,
                270,
                false
            );
        } else {
            appendDirectedDxfArcRoute(
                points,
                barStartX + bendRadius,
                barCenterY - bendRadius,
                bendRadius,
                180,
                90,
                true
            );
        }
    } else {
        appendUniqueDxfRoutePoint(points, { x: barStartX, y: barCenterY });
    }

    if (hookRight) {
        appendUniqueDxfRoutePoint(points, { x: barEndX - bendRadius, y: barCenterY });
        if (hookDirectionY > 0) {
            appendDirectedDxfArcRoute(
                points,
                barEndX - bendRadius,
                barCenterY + bendRadius,
                bendRadius,
                270,
                360,
                false
            );
        } else {
            appendDirectedDxfArcRoute(
                points,
                barEndX - bendRadius,
                barCenterY - bendRadius,
                bendRadius,
                90,
                0,
                true
            );
        }
        appendUniqueDxfRoutePoint(points, { x: barEndX, y: hookLevel });
    } else {
        appendUniqueDxfRoutePoint(points, { x: barEndX, y: barCenterY });
    }

    return points;
}

function getDxfRoutePointTangent(points, index) {
    const point = points[index];
    const previous = points[Math.max(index - 1, 0)];
    const next = points[Math.min(index + 1, points.length - 1)];
    const dx = next.x - previous.x;
    const dy = next.y - previous.y;
    const length = Math.hypot(dx, dy);
    if (!(length > 1e-10)) {
        return { x: 1, y: 0 };
    }
    return { x: dx / length, y: dy / length };
}

function appendDxfSemicircle(points, center, startVector, clockwise = true, segmentCount = 12, includeLast = true) {
    if (!Array.isArray(points) || !hasFiniteNumbers(center?.x, center?.y, startVector?.x, startVector?.y)) {
        return;
    }
    const radius = Math.hypot(startVector.x, startVector.y);
    if (!(radius > 0)) {
        return;
    }
    const startAngle = Math.atan2(startVector.y, startVector.x);
    const sweep = clockwise ? -Math.PI : Math.PI;
    const safeSegments = Math.max(6, Math.min(Number.parseInt(segmentCount, 10) || 12, 36));
    const finalIndex = includeLast ? safeSegments : safeSegments - 1;
    for (let index = 1; index <= finalIndex; index += 1) {
        const angle = startAngle + (sweep * index) / safeSegments;
        appendUniqueDxfRoutePoint(points, {
            x: center.x + Math.cos(angle) * radius,
            y: center.y + Math.sin(angle) * radius
        });
    }
}

function buildBeamLongitudinalOutlineVertices(centerline, radius) {
    const points = Array.isArray(centerline) ? centerline : [];
    const barRadius = Math.max(parsePositiveNumberOrFallback(radius, 0, 0), 0);
    if (points.length < 2 || !(barRadius > 0)) {
        return [];
    }

    const plus = [];
    const minus = [];
    points.forEach((point, index) => {
        const tangent = getDxfRoutePointTangent(points, index);
        const normal = { x: -tangent.y, y: tangent.x };
        plus.push({ x: point.x + normal.x * barRadius, y: point.y + normal.y * barRadius });
        minus.push({ x: point.x - normal.x * barRadius, y: point.y - normal.y * barRadius });
    });

    const outline = plus.map((point) => ({ ...point }));
    const end = points[points.length - 1];
    const endPlus = plus[plus.length - 1];
    appendDxfSemicircle(outline, end, {
        x: endPlus.x - end.x,
        y: endPlus.y - end.y
    }, true, 12, true);

    for (let index = minus.length - 2; index >= 0; index -= 1) {
        appendUniqueDxfRoutePoint(outline, minus[index]);
    }

    const start = points[0];
    const startMinus = minus[0];
    appendDxfSemicircle(outline, start, {
        x: startMinus.x - start.x,
        y: startMinus.y - start.y
    }, true, 12, false);
    return outline;
}

function drawJoinedBeamLongitudinalPolyline(dxf, layer, route, radius, asOutline = true) {
    if (!Array.isArray(route) || route.length < 2) {
        return false;
    }

    if (!asOutline) {
        addPolyline(dxf, layer, route);
        return true;
    }

    const outline = buildBeamLongitudinalOutlineVertices(route, radius);
    if (outline.length < 4) {
        return false;
    }
    addPolyline(dxf, layer, outline, { closed: true });
    return true;
}

function drawSmartRebar(dxf, layer, x1, x2, z1, z2, hookLevel, hookLeft, hookRight, options = {}) {
    const barCenterY = (parseNumberOrFallback(z1, 0) + parseNumberOrFallback(z2, 0)) / 2;
    const leftHookInset = Math.max(parseNumberOrFallback(options.leftHookInnerOffset, 0.02), 0);
    const rightHookInset = Math.max(parseNumberOrFallback(options.rightHookInnerOffset, 0.02), 0);
    const hookLegAtBarExtents = options.hookLegAtBarExtents === true;
    const barStartX = hookLeft ? (hookLegAtBarExtents ? x1 : x1 + leftHookInset) : x1;
    const barEndX = hookRight ? (hookLegAtBarExtents ? x2 : x2 - rightHookInset) : x2;
    const defaultHookLevel = parseNumberOrFallback(hookLevel, barCenterY);
    const defaultVerticalHookDelta = defaultHookLevel - barCenterY;
    const hookDirectionY = Math.sign(defaultVerticalHookDelta) || 1;
    const explicitHookLength = Math.max(parsePositiveNumberOrFallback(options.hookLength, 0, 0), 0);
    const resolvedHookLevel = explicitHookLength > 0
        ? barCenterY + hookDirectionY * explicitHookLength
        : defaultHookLevel;
    const verticalHookDelta = resolvedHookLevel - barCenterY;
    const availableHookHeight = Math.abs(verticalHookDelta);
    const availableBarLength = Math.max(barEndX - barStartX, 0);
    const barRadius = Math.max(
        parsePositiveNumberOrFallback(options.barRadius, Math.abs(parseNumberOrFallback(z1, 0) - parseNumberOrFallback(z2, 0)) / 2, 0.001),
        DXF_REBAR_2D_RADIUS
    );
    const requestedRadius = parsePositiveNumberOrFallback(options.hookBendRadius, DXF_REBAR_HOOK_BEND_RADIUS, 0.001);
    const bendRadius = Math.min(
        Math.max(requestedRadius, barRadius * 2.2),
        Math.max(availableHookHeight * 0.45, 0),
        Math.max(availableBarLength * 0.18, 0)
    );
    const canDrawCurvedHooks = bendRadius > barRadius + 0.001
        && availableHookHeight > bendRadius + barRadius + 0.001
        && availableBarLength > (hookLeft && hookRight ? bendRadius * 2 : bendRadius) + 0.001;
    const use2D = options.as2d !== false;
    const capStyle = options.capStyle;
    const joinBeamLongitudinalPolyline = isBeamLongitudinalRebarLayer(layer)
        && options.joinAsPolyline !== false;
    const joinedRoute = joinBeamLongitudinalPolyline
        ? buildBeamLongitudinalCenterlineRoute({
            barStartX,
            barEndX,
            barCenterY,
            hookLevel: resolvedHookLevel,
            hookLeft,
            hookRight,
            bendRadius,
            curvedHooks: canDrawCurvedHooks
        })
        : [];
    const fillOptions = {
        fillStyle: options.fillStyle,
        hatchLayer: options.hatchLayer,
        hatchColor: options.hatchColor,
        hatchPatternName: options.hatchPatternName,
        hatchPatternScale: options.hatchPatternScale,
        hatchPatternAngle: options.hatchPatternAngle,
        capStyle,
        // Beam longitudinal bars receive one final closed outline after every
        // straight segment, bend and hook has been filled.
        drawOutline: !joinBeamLongitudinalPolyline
    };

    if (!use2D) {
        if (joinBeamLongitudinalPolyline) {
            drawJoinedBeamLongitudinalPolyline(dxf, layer, joinedRoute, barRadius, false);
            return;
        }

        if (!canDrawCurvedHooks) {
            if (barEndX > barStartX + 0.0001) {
                addPolylineLine(dxf, layer, barStartX, barCenterY, barEndX, barCenterY);
            }

            if (hookLeft) {
                addPolylineLine(dxf, layer, barStartX, barCenterY, barStartX, resolvedHookLevel);
            }

            if (hookRight) {
                addPolylineLine(dxf, layer, barEndX, barCenterY, barEndX, resolvedHookLevel);
            }
            return;
        }

        const horizontalStartX = hookLeft ? barStartX + bendRadius : barStartX;
        const horizontalEndX = hookRight ? barEndX - bendRadius : barEndX;

        if (horizontalEndX > horizontalStartX + 0.0001) {
            addPolylineLine(dxf, layer, horizontalStartX, barCenterY, horizontalEndX, barCenterY);
        }

        if (hookLeft) {
            addPolylineLine(dxf, layer, barStartX, resolvedHookLevel, barStartX, barCenterY + hookDirectionY * bendRadius);
            (shouldUsePolylineForDxfLayer(layer) ? addArcPolyline : addArc)(
                dxf,
                layer,
                barStartX + bendRadius,
                barCenterY + hookDirectionY * bendRadius,
                bendRadius,
                hookDirectionY > 0 ? 180 : 90,
                hookDirectionY > 0 ? 270 : 180
            );
        }

        if (hookRight) {
            addPolylineLine(dxf, layer, barEndX, resolvedHookLevel, barEndX, barCenterY + hookDirectionY * bendRadius);
            (shouldUsePolylineForDxfLayer(layer) ? addArcPolyline : addArc)(
                dxf,
                layer,
                barEndX - bendRadius,
                barCenterY + hookDirectionY * bendRadius,
                bendRadius,
                hookDirectionY > 0 ? 270 : 0,
                hookDirectionY > 0 ? 360 : 90
            );
        }
        return;
    }

    if (!canDrawCurvedHooks) {
        if (barEndX > barStartX + 0.0001) {
            addFilledBarSegment(dxf, layer, barStartX, barCenterY, barEndX, barCenterY, barRadius, DXF_REBAR_SOLID_COLOR, {
                roundStart: !hookLeft,
                roundEnd: !hookRight,
                ...fillOptions
            });
        }

        if (hookLeft) {
            addFilledBarSegment(dxf, layer, barStartX, barCenterY, barStartX, resolvedHookLevel, barRadius, DXF_REBAR_SOLID_COLOR, {
                roundStart: false,
                roundEnd: true,
                ...fillOptions
            });
        }

        if (hookRight) {
            addFilledBarSegment(dxf, layer, barEndX, barCenterY, barEndX, resolvedHookLevel, barRadius, DXF_REBAR_SOLID_COLOR, {
                roundStart: false,
                roundEnd: true,
                ...fillOptions
            });
        }
        if (joinBeamLongitudinalPolyline) {
            drawJoinedBeamLongitudinalPolyline(dxf, layer, joinedRoute, barRadius, true);
        }
        return;
    }

    const horizontalStartX = hookLeft ? barStartX + bendRadius : barStartX;
    const horizontalEndX = hookRight ? barEndX - bendRadius : barEndX;

    if (horizontalEndX > horizontalStartX + 0.0001) {
        addFilledBarSegment(dxf, layer, horizontalStartX, barCenterY, horizontalEndX, barCenterY, barRadius, DXF_REBAR_SOLID_COLOR, {
            roundStart: !hookLeft,
            roundEnd: !hookRight,
            // The straight bar meets the hook arc at a tangent point. Do not
            // close the rectangular segment there with a transverse seam line.
            drawFlatCaps: false,
            ...fillOptions
        });
    }

    if (hookLeft) {
        const verticalEndY = barCenterY + hookDirectionY * bendRadius;
        addFilledBarSegment(dxf, layer, barStartX, resolvedHookLevel, barStartX, verticalEndY, barRadius, DXF_REBAR_SOLID_COLOR, {
            roundStart: true,
            roundEnd: false,
            // Leave the tangent end open so the vertical leg and bend read as
            // one continuous longitudinal bar instead of two joined pieces.
            drawFlatCaps: false,
            ...fillOptions
        });

        addFilledAnnularSector(
            dxf,
            layer,
            barStartX + bendRadius,
            barCenterY + hookDirectionY * bendRadius,
            bendRadius - barRadius,
            bendRadius + barRadius,
            hookDirectionY > 0 ? 180 : 90,
            hookDirectionY > 0 ? 270 : 180,
            DXF_REBAR_SOLID_COLOR,
            null,
            fillOptions
        );
    }

    if (hookRight) {
        const verticalEndY = barCenterY + hookDirectionY * bendRadius;
        addFilledBarSegment(dxf, layer, barEndX, resolvedHookLevel, barEndX, verticalEndY, barRadius, DXF_REBAR_SOLID_COLOR, {
            roundStart: true,
            roundEnd: false,
            // Leave the tangent end open so the vertical leg and bend read as
            // one continuous longitudinal bar instead of two joined pieces.
            drawFlatCaps: false,
            ...fillOptions
        });

        addFilledAnnularSector(
            dxf,
            layer,
            barEndX - bendRadius,
            barCenterY + hookDirectionY * bendRadius,
            bendRadius - barRadius,
            bendRadius + barRadius,
            hookDirectionY > 0 ? 270 : 0,
            hookDirectionY > 0 ? 360 : 90,
            DXF_REBAR_SOLID_COLOR,
            null,
            fillOptions
        );
    }

    if (joinBeamLongitudinalPolyline) {
        drawJoinedBeamLongitudinalPolyline(dxf, layer, joinedRoute, barRadius, true);
    }
}

function drawSmartVerticalRebar(dxf, layer, centerX, y1, y2, hookTargetX, options = {}) {
    const bottomY = Math.min(parseNumberOrFallback(y1, 0), parseNumberOrFallback(y2, 0));
    const topY = Math.max(parseNumberOrFallback(y1, 0), parseNumberOrFallback(y2, 0));
    const availableBarLength = Math.max(topY - bottomY, 0);
    const targetX = parseNumberOrFallback(hookTargetX, centerX);
    const hookDirectionX = Math.sign(targetX - centerX) || 1;
    const availableHookWidth = Math.abs(targetX - centerX);
    const barRadius = Math.max(
        parsePositiveNumberOrFallback(options.barRadius, DXF_REBAR_2D_RADIUS, 0.001),
        DXF_REBAR_2D_RADIUS
    );
    const requestedRadius = parsePositiveNumberOrFallback(options.hookBendRadius, DXF_REBAR_HOOK_BEND_RADIUS, 0.001);
    const bendRadius = Math.min(
        Math.max(requestedRadius, barRadius * 2.2),
        Math.max(availableHookWidth * 0.45, 0),
        Math.max(availableBarLength * 0.18, 0)
    );
    const canDrawCurvedHooks = bendRadius > barRadius + 0.001
        && availableHookWidth > bendRadius + barRadius + 0.001
        && availableBarLength > bendRadius * 2 + 0.001;
    const use2D = options.as2d !== false;
    const fillOptions = {
        fillStyle: options.fillStyle,
        hatchLayer: options.hatchLayer,
        hatchColor: options.hatchColor,
        hatchPatternName: options.hatchPatternName,
        hatchPatternScale: options.hatchPatternScale,
        hatchPatternAngle: options.hatchPatternAngle,
        capStyle: options.capStyle
    };

    if (!canDrawCurvedHooks) {
        if (topY > bottomY + 0.0001) {
            if (use2D) {
                addFilledBarSegment(dxf, layer, centerX, bottomY, centerX, topY, barRadius, DXF_REBAR_SOLID_COLOR, {
                    roundStart: false,
                    roundEnd: false,
                    ...fillOptions
                });
                addFilledBarSegment(dxf, layer, centerX, bottomY, targetX, bottomY, barRadius, DXF_REBAR_SOLID_COLOR, {
                    roundStart: false,
                    roundEnd: true,
                    ...fillOptions
                });
                addFilledBarSegment(dxf, layer, centerX, topY, targetX, topY, barRadius, DXF_REBAR_SOLID_COLOR, {
                    roundStart: false,
                    roundEnd: true,
                    ...fillOptions
                });
            } else {
                addPolylineLine(dxf, layer, centerX, bottomY, centerX, topY);
                addPolylineLine(dxf, layer, centerX, bottomY, targetX, bottomY);
                addPolylineLine(dxf, layer, centerX, topY, targetX, topY);
            }
        }
        return;
    }

    const hookTangentX = centerX + hookDirectionX * bendRadius;
    const mainBottomY = bottomY + bendRadius;
    const mainTopY = topY - bendRadius;
    const bottomArcStart = hookDirectionX > 0 ? 180 : 270;
    const bottomArcEnd = hookDirectionX > 0 ? 270 : 360;
    const topArcStart = hookDirectionX > 0 ? 90 : 0;
    const topArcEnd = hookDirectionX > 0 ? 180 : 90;

    if (!use2D) {
        addPolylineLine(dxf, layer, centerX, mainBottomY, centerX, mainTopY);
        addPolylineLine(dxf, layer, targetX, bottomY, hookTangentX, bottomY);
        addPolylineLine(dxf, layer, targetX, topY, hookTangentX, topY);
        (shouldUsePolylineForDxfLayer(layer) ? addArcPolyline : addArc)(
            dxf,
            layer,
            hookTangentX,
            mainBottomY,
            bendRadius,
            bottomArcStart,
            bottomArcEnd
        );
        (shouldUsePolylineForDxfLayer(layer) ? addArcPolyline : addArc)(
            dxf,
            layer,
            hookTangentX,
            mainTopY,
            bendRadius,
            topArcStart,
            topArcEnd
        );
        return;
    }

    addFilledBarSegment(dxf, layer, centerX, mainBottomY, centerX, mainTopY, barRadius, DXF_REBAR_SOLID_COLOR, {
        roundStart: false,
        roundEnd: false,
        ...fillOptions
    });
    addFilledBarSegment(dxf, layer, targetX, bottomY, hookTangentX, bottomY, barRadius, DXF_REBAR_SOLID_COLOR, {
        roundStart: true,
        roundEnd: false,
        ...fillOptions
    });
    addFilledBarSegment(dxf, layer, targetX, topY, hookTangentX, topY, barRadius, DXF_REBAR_SOLID_COLOR, {
        roundStart: true,
        roundEnd: false,
        ...fillOptions
    });
    [
        { centerY: mainBottomY, startAngle: bottomArcStart, endAngle: bottomArcEnd },
        { centerY: mainTopY, startAngle: topArcStart, endAngle: topArcEnd }
    ].forEach((arc) => {
        addFilledAnnularSector(
            dxf,
            layer,
            hookTangentX,
            arc.centerY,
            bendRadius - barRadius,
            bendRadius + barRadius,
            arc.startAngle,
            arc.endAngle,
            DXF_REBAR_SOLID_COLOR,
            null,
            {
                fillStyle: options.fillStyle,
                hatchLayer: options.hatchLayer,
                hatchColor: options.hatchColor,
                hatchPatternName: options.hatchPatternName,
                hatchPatternScale: options.hatchPatternScale,
                hatchPatternAngle: options.hatchPatternAngle
            }
        );
    });
}

function isSteelDenotationTextLayer(layer) {
    const normalizedLayer = String(layer || "").trim().toUpperCase();
    return normalizedLayer === "TEXTO_ACERO" || normalizedLayer === "TEXTO_ESTRIBOS";
}

function drawSteelDenotationPolyline(arr, textLeftX, startY, targetX, targetY) {
    if (!hasFiniteNumbers(textLeftX, startY, targetX, targetY)) {
        return;
    }

    // Every steel callout begins at the left edge of its label.  Its first
    // shoulder is fixed at 0.05 m; the second segment reaches the indicated
    // reinforcement.  Both segments are emitted as one editable LWPOLYLINE.
    const shoulderDirection = targetX < textLeftX ? -1 : 1;
    const elbowX = textLeftX + shoulderDirection * STEEL_DENOTATION_SHOULDER_LENGTH;
    addPolyline(arr, STEEL_DENOTATION_LAYER, [
        { x: textLeftX, y: startY },
        { x: elbowX, y: startY },
        { x: targetX, y: targetY }
    ], {
        color: STEEL_DENOTATION_COLOR,
        lineWeight: STEEL_DENOTATION_LINEWEIGHT
    });
}

function drawLeaderText(arr, layer, text, labelCenterX, labelY, targetX, targetY, size, placement, options = {}) {
    const textOriginX = labelCenterX - estimateDxfTextWidth(text, size) / 2;
    const leaderStartY = placement === "above" ? labelY - size * 0.1 : labelY + size * 0.22;
    const denotesSteel = options?.denotesSteel === true || isSteelDenotationTextLayer(layer);

    addText(arr, layer, textOriginX, labelY, text, size);
    if (denotesSteel) {
        drawSteelDenotationPolyline(arr, textOriginX, leaderStartY, targetX, targetY);
        return;
    }
    drawLeaderArrow(arr, layer, labelCenterX, leaderStartY, targetX, targetY);
}

function drawSideLeaderText(arr, layer, text, labelLeftX, labelY, targetX, targetY, size, placement, options = {}) {
    const leaderStartY = placement === "above" ? labelY - size * 0.1 : labelY + size * 0.22;
    const denotesSteel = options?.denotesSteel === true || isSteelDenotationTextLayer(layer);

    addText(arr, layer, labelLeftX, labelY, text, size);
    if (denotesSteel) {
        drawSteelDenotationPolyline(arr, labelLeftX, leaderStartY, targetX, targetY);
        return;
    }
    drawLeaderArrow(arr, layer, labelLeftX - 0.08, leaderStartY, targetX, targetY);
}

function getDxfLeaderTextBounds(text, labelCenterX, labelY, size, padding = 0) {
    if (!hasFiniteNumbers(labelCenterX, labelY, size)) {
        return null;
    }

    const textWidth = estimateDxfTextWidth(text, size);
    const textHeight = Math.max(size * 1.25, 0.01);
    return {
        left: labelCenterX - textWidth / 2 - padding,
        right: labelCenterX + textWidth / 2 + padding,
        bottom: labelY - size * 0.25 - padding,
        top: labelY - size * 0.25 + textHeight + padding
    };
}

function getDxfCenteredTextBounds(text, centerX, centerY, size, padding = 0) {
    if (!hasFiniteNumbers(centerX, centerY, size)) {
        return null;
    }

    const textWidth = estimateDxfTextWidth(text, size);
    const textHeight = Math.max(size * 1.2, 0.01);
    return {
        left: centerX - textWidth / 2 - padding,
        right: centerX + textWidth / 2 + padding,
        bottom: centerY - textHeight / 2 - padding,
        top: centerY + textHeight / 2 + padding
    };
}

function getDxfLeftTextBounds(text, leftX, baselineY, size, padding = 0) {
    if (!hasFiniteNumbers(leftX, baselineY, size)) {
        return null;
    }

    const textWidth = estimateDxfTextWidth(text, size);
    const textHeight = Math.max(size * 1.25, 0.01);
    return {
        left: leftX - padding,
        right: leftX + textWidth + padding,
        bottom: baselineY - size * 0.25 - padding,
        top: baselineY - size * 0.25 + textHeight + padding
    };
}

function dxfTextBoundsOverlap(left, right) {
    if (!left || !right) {
        return false;
    }

    return !(
        left.right <= right.left
        || left.left >= right.right
        || left.top <= right.bottom
        || left.bottom >= right.top
    );
}

function getDxfTextCollisionScore(candidate, boxes = []) {
    if (!candidate) {
        return Number.POSITIVE_INFINITY;
    }

    return boxes.reduce((score, box) => {
        if (!dxfTextBoundsOverlap(candidate, box)) {
            return score;
        }

        const overlapWidth = Math.max(0, Math.min(candidate.right, box.right) - Math.max(candidate.left, box.left));
        const overlapHeight = Math.max(0, Math.min(candidate.top, box.top) - Math.max(candidate.bottom, box.bottom));
        return score + 1000 + overlapWidth * overlapHeight;
    }, 0);
}

function clampDxfTextCandidate(value, minimum, maximum) {
    if (Number.isFinite(minimum) && Number.isFinite(maximum) && minimum > maximum) {
        return (minimum + maximum) / 2;
    }

    if (Number.isFinite(minimum) && value < minimum) {
        return minimum;
    }

    if (Number.isFinite(maximum) && value > maximum) {
        return maximum;
    }

    return value;
}

function createDxfTextCollisionResolver(options = {}) {
    const placedBoxes = [];
    const fixedBoxes = Array.isArray(options.blockers) ? options.blockers.filter(Boolean) : [];
    const padding = Math.max(parseNumberOrFallback(options.padding, DXF_TEXT_COLLISION_PADDING), 0);
    const step = Math.max(parseNumberOrFallback(options.step, DXF_TEXT_COLLISION_STEP), 0.01);
    const maxSteps = Math.max(Math.round(parseNumberOrFallback(options.maxSteps, DXF_TEXT_COLLISION_MAX_STEPS)), 1);

    const getBlockingBoxes = () => [...fixedBoxes, ...placedBoxes];
    const registerBox = (box, meta = {}) => {
        if (!box || !hasFiniteNumbers(box.left, box.right, box.bottom, box.top)) {
            return null;
        }

        const normalizedBox = {
            left: Math.min(box.left, box.right),
            right: Math.max(box.left, box.right),
            bottom: Math.min(box.bottom, box.top),
            top: Math.max(box.bottom, box.top),
            ...meta
        };
        placedBoxes.push(normalizedBox);
        return normalizedBox;
    };

    const findFreePlacement = ({
        desiredX,
        desiredY,
        axis = "x",
        minX = Number.NEGATIVE_INFINITY,
        maxX = Number.POSITIVE_INFINITY,
        minY = Number.NEGATIVE_INFINITY,
        maxY = Number.POSITIVE_INFINITY,
        buildBounds
    }) => {
        const safeAxis = axis === "y" ? "y" : "x";
        const safeDesiredX = parseNumberOrFallback(desiredX, 0);
        const safeDesiredY = parseNumberOrFallback(desiredY, 0);
        const safeMinX = parseNumberOrFallback(minX, Number.NEGATIVE_INFINITY);
        const safeMaxX = parseNumberOrFallback(maxX, Number.POSITIVE_INFINITY);
        const safeMinY = parseNumberOrFallback(minY, Number.NEGATIVE_INFINITY);
        const safeMaxY = parseNumberOrFallback(maxY, Number.POSITIVE_INFINITY);
        const blockingBoxes = getBlockingBoxes();
        const offsets = [0];
        for (let index = 1; index <= maxSteps; index += 1) {
            offsets.push(index * step, -index * step);
        }

        const triedKeys = new Set();
        let bestCandidate = null;
        let bestScore = Number.POSITIVE_INFINITY;

        offsets.forEach((offset) => {
            const candidateX = safeAxis === "x"
                ? clampDxfTextCandidate(safeDesiredX + offset, safeMinX, safeMaxX)
                : clampDxfTextCandidate(safeDesiredX, safeMinX, safeMaxX);
            const candidateY = safeAxis === "y"
                ? clampDxfTextCandidate(safeDesiredY + offset, safeMinY, safeMaxY)
                : clampDxfTextCandidate(safeDesiredY, safeMinY, safeMaxY);
            const numericCandidateX = parseNumberOrFallback(candidateX, safeDesiredX);
            const numericCandidateY = parseNumberOrFallback(candidateY, safeDesiredY);
            const key = `${numericCandidateX.toFixed(4)}|${numericCandidateY.toFixed(4)}`;
            if (triedKeys.has(key)) {
                return;
            }
            triedKeys.add(key);

            const candidateBounds = buildBounds(numericCandidateX, numericCandidateY, padding);
            const score = getDxfTextCollisionScore(candidateBounds, blockingBoxes) + Math.abs(offset) * 0.001;
            if (score < bestScore) {
                bestScore = score;
                bestCandidate = {
                    x: numericCandidateX,
                    y: numericCandidateY,
                    bounds: candidateBounds,
                    score
                };
            }
        });

        return bestCandidate || {
            x: safeDesiredX,
            y: safeDesiredY,
            bounds: buildBounds(safeDesiredX, safeDesiredY, padding),
            score: Number.POSITIVE_INFINITY
        };
    };

    return {
        boxes: placedBoxes,
        registerBox,
        registerCenteredText(text, centerX, centerY, size, meta = {}) {
            return registerBox(getDxfCenteredTextBounds(text, centerX, centerY, size, padding), meta);
        },
        registerLeftText(text, leftX, baselineY, size, meta = {}) {
            return registerBox(getDxfLeftTextBounds(text, leftX, baselineY, size, padding), meta);
        },
        placeLeaderText(arr, layer, text, labelCenterX, labelY, targetX, targetY, size, placement, placementOptions = {}) {
            const textWidth = estimateDxfTextWidth(text, size);
            const halfWidth = textWidth / 2;
            const minX = Number.isFinite(placementOptions.minX) ? placementOptions.minX + halfWidth : Number.NEGATIVE_INFINITY;
            const maxX = Number.isFinite(placementOptions.maxX) ? placementOptions.maxX - halfWidth : Number.POSITIVE_INFINITY;
            const minY = Number.isFinite(placementOptions.minY) ? placementOptions.minY : Number.NEGATIVE_INFINITY;
            const maxY = Number.isFinite(placementOptions.maxY) ? placementOptions.maxY : Number.POSITIVE_INFINITY;
            const candidate = findFreePlacement({
                desiredX: labelCenterX,
                desiredY: labelY,
                axis: placementOptions.axis || "x",
                minX,
                maxX,
                minY,
                maxY,
                buildBounds: (candidateX, candidateY, candidatePadding) => getDxfLeaderTextBounds(text, candidateX, candidateY, size, candidatePadding)
            });
            const resolvedTargetX = placementOptions.followTargetX ? candidate.x : targetX;
            const resolvedTargetY = placementOptions.followTargetY ? candidate.y : targetY;

            drawLeaderText(arr, layer, text, candidate.x, candidate.y, resolvedTargetX, resolvedTargetY, size, placement, placementOptions);
            registerBox(candidate.bounds, { layer, text: sanitizeDxfText(text), kind: "leader" });
            return candidate;
        },
        placeCenteredText(arr, layer, text, centerX, centerY, size, placementOptions = {}) {
            const textWidth = estimateDxfTextWidth(text, size);
            const halfWidth = textWidth / 2;
            const halfHeight = Math.max(size * 1.2, 0.01) / 2;
            const minX = Number.isFinite(placementOptions.minX) ? placementOptions.minX + halfWidth : Number.NEGATIVE_INFINITY;
            const maxX = Number.isFinite(placementOptions.maxX) ? placementOptions.maxX - halfWidth : Number.POSITIVE_INFINITY;
            const minY = Number.isFinite(placementOptions.minY) ? placementOptions.minY + halfHeight : Number.NEGATIVE_INFINITY;
            const maxY = Number.isFinite(placementOptions.maxY) ? placementOptions.maxY - halfHeight : Number.POSITIVE_INFINITY;
            const candidate = findFreePlacement({
                desiredX: centerX,
                desiredY: centerY,
                axis: placementOptions.axis || "x",
                minX,
                maxX,
                minY,
                maxY,
                buildBounds: (candidateX, candidateY, candidatePadding) => getDxfCenteredTextBounds(text, candidateX, candidateY, size, candidatePadding)
            });

            addCenteredText(arr, layer, candidate.x, candidate.y, text, size);
            registerBox(candidate.bounds, { layer, text: sanitizeDxfText(text), kind: "centered" });
            return candidate;
        }
    };
}

function drawCollisionAwareLeaderText(arr, resolver, layer, text, labelCenterX, labelY, targetX, targetY, size, placement, options = {}) {
    if (resolver?.placeLeaderText) {
        return resolver.placeLeaderText(arr, layer, text, labelCenterX, labelY, targetX, targetY, size, placement, options);
    }

    drawLeaderText(arr, layer, text, labelCenterX, labelY, targetX, targetY, size, placement);
    return null;
}

function drawCollisionAwareCenteredText(arr, resolver, layer, text, centerX, centerY, size, options = {}) {
    if (resolver?.placeCenteredText) {
        return resolver.placeCenteredText(arr, layer, text, centerX, centerY, size, options);
    }

    addCenteredText(arr, layer, centerX, centerY, text, size);
    return null;
}

function drawLeaderArrow(arr, layer, x1, y1, x2, y2, arrowSize = 0.08) {
    if (!hasFiniteNumbers(x1, y1, x2, y2, arrowSize)) {
        return;
    }

    if (isSteelDenotationTextLayer(layer)) {
        drawSteelDenotationPolyline(arr, x1, y1, x2, y2);
        return;
    }

    const angle = Math.atan2(y2 - y1, x2 - x1);
    const arrowAngle = Math.PI / 7;

    addLine(arr, layer, x1, y1, x2, y2);
    addLine(
        arr,
        layer,
        x2,
        y2,
        x2 - Math.cos(angle - arrowAngle) * arrowSize,
        y2 - Math.sin(angle - arrowAngle) * arrowSize
    );
    addLine(
        arr,
        layer,
        x2,
        y2,
        x2 - Math.cos(angle + arrowAngle) * arrowSize,
        y2 - Math.sin(angle + arrowAngle) * arrowSize
    );
}

function estimateDxfTextWidth(text, size) {
    return sanitizeDxfText(text).length * size * 0.6;
}

function hasFiniteNumbers(...values) {
    return values.every((value) => Number.isFinite(value));
}

function addLine(arr, layer, x1, y1, x2, y2, lineType = "", lineTypeScale = null, color = null, lineWeight = null) {
    if (!hasFiniteNumbers(x1, y1, x2, y2)) {
        return;
    }

    if (shouldUsePolylineForDxfLayer(layer)) {
        addPolylineLine(arr, layer, x1, y1, x2, y2, { lineType, lineTypeScale, color, lineWeight });
        return;
    }

    arr.push(
        "0", "LINE",
        "8", layer,
        ...(lineType ? ["6", lineType] : []),
        ...(Number.isFinite(lineTypeScale) ? ["48", String(lineTypeScale)] : []),
        ...(Number.isFinite(color) ? ["62", String(color)] : []),
        ...(Number.isFinite(lineWeight) ? ["370", String(lineWeight)] : []),
        "10", x1,
        "20", y1,
        "11", x2,
        "21", y2
    );
}

function addPolyline(arr, layer, vertices, options = {}) {
    const points = (Array.isArray(vertices) ? vertices : [])
        .map((vertex) => ({ x: Number.parseFloat(vertex?.x), y: Number.parseFloat(vertex?.y) }))
        .filter((vertex) => Number.isFinite(vertex.x) && Number.isFinite(vertex.y));
    if (points.length < 2) {
        return;
    }

    const color = Number.parseInt(options?.color, 10);
    const lineWeight = Number.parseInt(options?.lineWeight, 10);
    const lineType = String(options?.lineType || "").trim();
    const lineTypeScale = Number.parseFloat(options?.lineTypeScale);
    const constantWidth = Number.parseFloat(options?.constantWidth);
    arr.push(
        "0", "LWPOLYLINE",
        "8", layer,
        ...(lineType ? ["6", lineType] : []),
        ...(Number.isFinite(lineTypeScale) ? ["48", String(lineTypeScale)] : []),
        ...(Number.isFinite(color) ? ["62", String(color)] : []),
        ...(Number.isFinite(lineWeight) ? ["370", String(lineWeight)] : []),
        "90", String(points.length),
        "70", options?.closed === true ? "1" : "0",
        ...(Number.isFinite(constantWidth) && constantWidth > 0 ? ["43", String(constantWidth)] : []),
        ...points.flatMap((point) => ["10", String(point.x), "20", String(point.y)])
    );
}

function addPolylineLine(arr, layer, x1, y1, x2, y2, options = {}) {
    if (!hasFiniteNumbers(x1, y1, x2, y2)) {
        return;
    }

    addPolyline(arr, layer, [
        { x: x1, y: y1 },
        { x: x2, y: y2 }
    ], options);
}

function addPolylineRectangle(arr, layer, x, y, width, height, options = {}) {
    if (!hasFiniteNumbers(x, y, width, height) || !(width > 0) || !(height > 0)) {
        return;
    }

    addPolyline(arr, layer, [
        { x, y },
        { x: x + width, y },
        { x: x + width, y: y + height },
        { x, y: y + height }
    ], {
        ...options,
        closed: true
    });
}

function normalizeDxfAngleDegrees(angle) {
    if (!Number.isFinite(angle)) {
        return 0;
    }

    const normalized = angle % 360;
    return normalized < 0 ? normalized + 360 : normalized;
}

function addExactArc(arr, layer, centerX, centerY, radius, startAngle, endAngle, lineType = "", lineTypeScale = null, color = null) {
    if (!hasFiniteNumbers(centerX, centerY, radius, startAngle, endAngle) || !(radius > 0)) {
        return;
    }

    arr.push(
        "0", "ARC",
        "8", layer,
        ...(lineType ? ["6", lineType] : []),
        ...(Number.isFinite(lineTypeScale) ? ["48", String(lineTypeScale)] : []),
        ...(Number.isFinite(color) ? ["62", String(color)] : []),
        "10", centerX,
        "20", centerY,
        "40", radius,
        "50", normalizeDxfAngleDegrees(startAngle),
        "51", normalizeDxfAngleDegrees(endAngle)
    );
}

function addArc(arr, layer, centerX, centerY, radius, startAngle, endAngle, lineType = "", lineTypeScale = null, color = null) {
    if (!hasFiniteNumbers(centerX, centerY, radius, startAngle, endAngle) || !(radius > 0)) {
        return;
    }

    if (shouldUsePolylineForDxfLayer(layer)) {
        addArcPolyline(arr, layer, centerX, centerY, radius, startAngle, endAngle, { lineType, lineTypeScale, color });
        return;
    }

    addExactArc(arr, layer, centerX, centerY, radius, startAngle, endAngle, lineType, lineTypeScale, color);
}


function getDxfAnglePoint(centerX, centerY, radius, angleDegrees) {
    const angleRadians = (angleDegrees * Math.PI) / 180;
    return {
        x: centerX + Math.cos(angleRadians) * radius,
        y: centerY + Math.sin(angleRadians) * radius
    };
}

function getPositiveDxfAngleSweep(startAngle, endAngle) {
    if (!Number.isFinite(startAngle) || !Number.isFinite(endAngle)) {
        return 0;
    }

    let sweep = endAngle - startAngle;
    while (sweep <= 0) {
        sweep += 360;
    }
    while (sweep > 360) {
        sweep -= 360;
    }

    return sweep;
}

function addArcPolyline(arr, layer, centerX, centerY, radius, startAngle, endAngle, options = {}) {
    if (!hasFiniteNumbers(centerX, centerY, radius, startAngle, endAngle) || !(radius > 0)) {
        return;
    }

    const sweep = getPositiveDxfAngleSweep(startAngle, endAngle);
    if (!(sweep > 0.0001)) {
        return;
    }

    const requestedSegments = Number.parseInt(options?.segmentCount, 10);
    const segmentCount = Math.max(3, Math.min(
        Number.isFinite(requestedSegments) ? requestedSegments : Math.ceil(sweep / 10),
        72
    ));
    const vertices = Array.from({ length: segmentCount + 1 }, (_, index) => (
        getDxfAnglePoint(centerX, centerY, radius, startAngle + (sweep * index) / segmentCount)
    ));
    addPolyline(arr, layer, vertices, options);
}

function shouldUsePolylineForDxfLayer(layer) {
    return new Set([
        "ACERO_LOSA_X",
        "ACERO_LOSA_Y",
        "ACERO_LOSA_TEMP",
        "ACERO_SUPERIOR",
        "ACERO_INFERIOR",
        "ACERO_TRANSVERSAL",
        "ACERO_LONGITUDINAL",
        "ACERO_MURO_LONG",
        "ACERO_MURO_TRANS",
        "CONCRETO_PORTICO",
        "CONCRETO_PORTICO_OCULTO",
        "CONCRETO_VIGAS",
        "CONCRETO_COLUMNAS",
        "CONCRETO_MUROS",
        "CONCRETO_MUROS_PLANTA",
        "CONCRETO_MUROS_OCULTOS"
    ]).has(String(layer || "").trim().toUpperCase());
}

function addFilledSemicircularBarCap(arr, layer, centerX, centerY, unitX, unitY, radius, color = DXF_REBAR_SOLID_COLOR, outwardSign = 1, segmentCount = 12, options = {}) {
    if (!hasFiniteNumbers(centerX, centerY, unitX, unitY, radius) || !(radius > 0)) {
        return;
    }

    const unitLength = Math.hypot(unitX, unitY);
    if (!(unitLength > 0.0001)) {
        return;
    }

    const safeUnitX = unitX / unitLength;
    const safeUnitY = unitY / unitLength;
    const capDirection = outwardSign < 0 ? -1 : 1;
    const centerAngle = Math.atan2(safeUnitY * capDirection, safeUnitX * capDirection) * 180 / Math.PI;
    const startAngle = centerAngle - 90;
    const endAngle = centerAngle + 90;
    const safeSegments = Math.max(4, Math.min(Number.parseInt(segmentCount, 10) || 12, 36));

    for (let index = 0; index < safeSegments; index += 1) {
        const angle1 = startAngle + ((endAngle - startAngle) * index) / safeSegments;
        const angle2 = startAngle + ((endAngle - startAngle) * (index + 1)) / safeSegments;
        const p1 = getDxfAnglePoint(centerX, centerY, radius, angle1);
        const p2 = getDxfAnglePoint(centerX, centerY, radius, angle2);
        addFilledQuadrilateral(arr, layer, [
            { x: centerX, y: centerY },
            p1,
            p2,
            { x: centerX, y: centerY }
        ], color);
    }

    if (options.drawOutline !== false) {
        if (shouldUsePolylineForDxfLayer(layer)) {
            addArcPolyline(arr, layer, centerX, centerY, radius, startAngle, endAngle, { segmentCount: safeSegments });
        } else {
            addArc(arr, layer, centerX, centerY, radius, startAngle, endAngle);
        }
    }
}

function getRebarHatchStyle(layer, options = {}) {
    const normalizedLayer = String(layer || "").trim().toUpperCase();
    const normalizedOptions = options && typeof options === "object" ? options : {};
    const explicitHatch = normalizedOptions.fillStyle === "hatch";
    const isRebarLineLayer = normalizedLayer.startsWith("ACERO_")
        && normalizedLayer !== FRAME_LONGITUDINAL_HATCH_LAYER
        && normalizedLayer !== FRAME_STIRRUP_HATCH_LAYER;

    if (!explicitHatch && !isRebarLineLayer) {
        return null;
    }

    const isStirrupLayer = normalizedLayer === "ACERO_TRANSVERSAL"
        || normalizedLayer === "ACERO_MURO_TRANS"
        || normalizedLayer.includes("ESTRIBO")
        || normalizedLayer.includes("TRANSVERSAL");
    const hatchOptions = {
        patternName: normalizedOptions.hatchPatternName || FRAME_REBAR_HATCH_PATTERN,
        patternScale: Number.isFinite(normalizedOptions.hatchPatternScale)
            ? normalizedOptions.hatchPatternScale
            : FRAME_REBAR_HATCH_SCALE,
        patternAngle: Number.isFinite(normalizedOptions.hatchPatternAngle)
            ? normalizedOptions.hatchPatternAngle
            : 45
    };
    if (Number.isFinite(normalizedOptions.hatchColor)) {
        hatchOptions.color = normalizedOptions.hatchColor;
    }

    return {
        hatchLayer: normalizedOptions.hatchLayer || (
            isStirrupLayer ? FRAME_STIRRUP_HATCH_LAYER : FRAME_LONGITUDINAL_HATCH_LAYER
        ),
        hatchOptions
    };
}

function addFilledBarSegment(arr, layer, x1, y1, x2, y2, radius = DXF_REBAR_2D_RADIUS, color = DXF_REBAR_SOLID_COLOR, options = {}) {
    const barRadius = Math.max(parsePositiveNumberOrFallback(radius, DXF_REBAR_2D_RADIUS, 0.001), 0.001);
    if (!hasFiniteNumbers(x1, y1, x2, y2, barRadius)) {
        return;
    }

    const dx = x2 - x1;
    const dy = y2 - y1;
    const length = Math.hypot(dx, dy);
    const rebarHatchStyle = getRebarHatchStyle(layer, options);
    const useHatch = Boolean(rebarHatchStyle);
    const hatchLayer = rebarHatchStyle?.hatchLayer || layer;
    const drawOutline = options.drawOutline !== false;
    const hatchOptions = {
        ...(rebarHatchStyle?.hatchOptions || {}),
        outlineLayer: layer,
        drawOutline
    };
    if (!(length > 0.0001)) {
        if (useHatch) {
            addHatchedCircle(arr, hatchLayer, x1, y1, barRadius, hatchOptions, 16);
        } else {
            addFilledCircle(arr, layer, x1, y1, barRadius, color, 16);
        }
        return;
    }

    const unitX = dx / length;
    const unitY = dy / length;
    const offsetX = -unitY * barRadius;
    const offsetY = unitX * barRadius;
    const p1 = { x: x1 + offsetX, y: y1 + offsetY };
    const p2 = { x: x2 + offsetX, y: y2 + offsetY };
    const p3 = { x: x2 - offsetX, y: y2 - offsetY };
    const p4 = { x: x1 - offsetX, y: y1 - offsetY };
    const roundStart = options.roundStart !== false;
    const roundEnd = options.roundEnd !== false;

    if (useHatch) {
        addHatch(arr, hatchLayer, [p1, p2, p3, p4], hatchOptions);
    } else {
        addFilledQuadrilateral(arr, layer, [p1, p2, p3, p4], color);
    }
    const addOutlineSegment = (xStart, yStart, xEnd, yEnd) => {
        if (!drawOutline) {
            return;
        }
        if (options.outlineAsPolyline === true || shouldUsePolylineForDxfLayer(layer)) {
            addPolylineLine(arr, layer, xStart, yStart, xEnd, yEnd);
            return;
        }
        addLine(arr, layer, xStart, yStart, xEnd, yEnd);
    };
    addOutlineSegment(p1.x, p1.y, p2.x, p2.y);
    addOutlineSegment(p4.x, p4.y, p3.x, p3.y);

    const drawFlatCaps = options.drawFlatCaps !== false;
    if (!roundStart && drawFlatCaps) {
        addOutlineSegment(p1.x, p1.y, p4.x, p4.y);
    }

    if (!roundEnd && drawFlatCaps) {
        addOutlineSegment(p2.x, p2.y, p3.x, p3.y);
    }

    const capStyle = options.capStyle || "circle";
    if (roundStart) {
        if (capStyle === "semicircle") {
            if (useHatch) {
                const centerAngle = Math.atan2(-unitY, -unitX) * 180 / Math.PI;
                addHatchedAnnularSector(arr, hatchLayer, x1, y1, 0.0001, barRadius, centerAngle - 90, centerAngle + 90, hatchOptions, 12);
            } else {
                addFilledSemicircularBarCap(arr, layer, x1, y1, unitX, unitY, barRadius, color, -1, 12, { drawOutline });
            }
        } else if (useHatch) {
            addHatchedCircle(arr, hatchLayer, x1, y1, barRadius, hatchOptions, 16);
        } else {
            addFilledCircle(arr, layer, x1, y1, barRadius, color, 16);
        }
    }

    if (roundEnd) {
        if (capStyle === "semicircle") {
            if (useHatch) {
                const centerAngle = Math.atan2(unitY, unitX) * 180 / Math.PI;
                addHatchedAnnularSector(arr, hatchLayer, x2, y2, 0.0001, barRadius, centerAngle - 90, centerAngle + 90, hatchOptions, 12);
            } else {
                addFilledSemicircularBarCap(arr, layer, x2, y2, unitX, unitY, barRadius, color, 1, 12, { drawOutline });
            }
        } else if (useHatch) {
            addHatchedCircle(arr, hatchLayer, x2, y2, barRadius, hatchOptions, 16);
        } else {
            addFilledCircle(arr, layer, x2, y2, barRadius, color, 16);
        }
    }
}

function addFilledAnnularSector(arr, layer, centerX, centerY, innerRadius, outerRadius, startAngle, endAngle, color = DXF_REBAR_SOLID_COLOR, segmentCount = null, options = {}) {
    if (!hasFiniteNumbers(centerX, centerY, innerRadius, outerRadius, startAngle, endAngle)) {
        return;
    }

    const safeInnerRadius = Math.max(parsePositiveNumberOrFallback(innerRadius, 0, 0), 0.0001);
    const safeOuterRadius = Math.max(parsePositiveNumberOrFallback(outerRadius, 0, 0), safeInnerRadius + 0.0001);
    const sweep = getPositiveDxfAngleSweep(startAngle, endAngle);
    if (!(sweep > 0.0001)) {
        return;
    }

    const rebarHatchStyle = getRebarHatchStyle(layer, options);
    if (rebarHatchStyle) {
        const hatchOptions = {
            ...rebarHatchStyle.hatchOptions,
            outlineLayer: layer,
            drawOutline: options.drawOutline !== false,
            drawRadialEdges: options.drawRadialEdges === true
        };
        addHatchedAnnularSector(arr, rebarHatchStyle.hatchLayer, centerX, centerY, safeInnerRadius, safeOuterRadius, startAngle, endAngle, hatchOptions, segmentCount);
        return;
    }

    const safeSegments = Math.max(4, Math.min(Number.parseInt(segmentCount, 10) || Math.ceil(sweep / 10), 72));
    for (let index = 0; index < safeSegments; index += 1) {
        const angle1 = startAngle + (sweep * index) / safeSegments;
        const angle2 = startAngle + (sweep * (index + 1)) / safeSegments;
        const outer1 = getDxfAnglePoint(centerX, centerY, safeOuterRadius, angle1);
        const outer2 = getDxfAnglePoint(centerX, centerY, safeOuterRadius, angle2);
        const inner2 = getDxfAnglePoint(centerX, centerY, safeInnerRadius, angle2);
        const inner1 = getDxfAnglePoint(centerX, centerY, safeInnerRadius, angle1);
        addFilledQuadrilateral(arr, layer, [outer1, outer2, inner2, inner1], color);
    }

    const drawOutline = options.drawOutline !== false;
    const usePolylineOutline = options.outlineAsPolyline === true || shouldUsePolylineForDxfLayer(layer);
    if (drawOutline) {
        if (usePolylineOutline) {
            addArcPolyline(arr, layer, centerX, centerY, safeOuterRadius, startAngle, endAngle);
            addArcPolyline(arr, layer, centerX, centerY, safeInnerRadius, startAngle, endAngle);
        } else {
            addArc(arr, layer, centerX, centerY, safeOuterRadius, startAngle, endAngle);
            addArc(arr, layer, centerX, centerY, safeInnerRadius, startAngle, endAngle);
        }
    }

    if (drawOutline && options.drawRadialEdges === true) {
        const startOuter = getDxfAnglePoint(centerX, centerY, safeOuterRadius, startAngle);
        const startInner = getDxfAnglePoint(centerX, centerY, safeInnerRadius, startAngle);
        const endOuter = getDxfAnglePoint(centerX, centerY, safeOuterRadius, startAngle + sweep);
        const endInner = getDxfAnglePoint(centerX, centerY, safeInnerRadius, startAngle + sweep);
        if (usePolylineOutline) {
            addPolylineLine(arr, layer, startOuter.x, startOuter.y, startInner.x, startInner.y);
            addPolylineLine(arr, layer, endOuter.x, endOuter.y, endInner.x, endInner.y);
        } else {
            addLine(arr, layer, startOuter.x, startOuter.y, startInner.x, startInner.y);
            addLine(arr, layer, endOuter.x, endOuter.y, endInner.x, endInner.y);
        }
    }
}

/**
 * Draws a closed frame-section stirrup with a prescribed pair of tangent
 * radii at each of its four corners.  The input radii are the physical radii
 * of the steel faces; the coordinates emitted to DXF are multiplied by the
 * section-detail scale.  Keeping these values explicit avoids letting a
 * generic rounded-rectangle fallback change the specified geometry.
 */
function drawFrameSectionStirrupWithTangentCorners(
    arr,
    layer,
    left,
    bottom,
    right,
    top,
    innerRadiusMeters,
    outerRadiusMeters,
    drawingScale = SECTION_DETAIL_SCALE,
    color = DXF_REBAR_SOLID_COLOR,
    options = {}
) {
    if (!hasFiniteNumbers(
        left,
        bottom,
        right,
        top,
        innerRadiusMeters,
        outerRadiusMeters,
        drawingScale
    )) {
        return false;
    }

    const minX = Math.min(left, right);
    const maxX = Math.max(left, right);
    const minY = Math.min(bottom, top);
    const maxY = Math.max(bottom, top);
    const width = maxX - minX;
    const height = maxY - minY;
    const safeScale = Math.max(parsePositiveNumberOrFallback(drawingScale, SECTION_DETAIL_SCALE, 0.0001), 0.0001);
    const innerRadius = Math.max(parsePositiveNumberOrFallback(innerRadiusMeters, Number.NaN, 0), 0) * safeScale;
    const outerRadius = Math.max(parsePositiveNumberOrFallback(outerRadiusMeters, Number.NaN, 0), 0) * safeScale;
    const centerlineRadius = (innerRadius + outerRadius) / 2;
    const barRadius = (outerRadius - innerRadius) / 2;

    // There is no valid tangent construction if the required curve does not
    // fit in the available stirrup centerline rectangle.  Returning false
    // lets the generic renderer retain its defensive fallback for malformed
    // or extremely small imported sections rather than corrupting the DXF.
    if (!(width > 2 * centerlineRadius + 0.0001)
        || !(height > 2 * centerlineRadius + 0.0001)
        || !(innerRadius > 0.0001)
        || !(outerRadius > innerRadius + 0.0001)
        || !(barRadius > 0.0001)) {
        return false;
    }

    const fillOptions = {
        fillStyle: options.fillStyle,
        hatchLayer: options.hatchLayer,
        hatchColor: options.hatchColor,
        hatchPatternName: options.hatchPatternName,
        hatchPatternScale: options.hatchPatternScale,
        hatchPatternAngle: options.hatchPatternAngle
    };

    // Straight portions terminate exactly at the tangent points of the arcs.
    // Their outlines and the annular sectors meet without radial closing
    // lines, so the interior and exterior faces stay continuously tangent.
    addFilledBarSegment(arr, layer, minX + centerlineRadius, minY, maxX - centerlineRadius, minY, barRadius, color, { roundStart: false, roundEnd: false, drawFlatCaps: false, ...fillOptions });
    addFilledBarSegment(arr, layer, maxX, minY + centerlineRadius, maxX, maxY - centerlineRadius, barRadius, color, { roundStart: false, roundEnd: false, drawFlatCaps: false, ...fillOptions });
    addFilledBarSegment(arr, layer, maxX - centerlineRadius, maxY, minX + centerlineRadius, maxY, barRadius, color, { roundStart: false, roundEnd: false, drawFlatCaps: false, ...fillOptions });
    addFilledBarSegment(arr, layer, minX, maxY - centerlineRadius, minX, minY + centerlineRadius, barRadius, color, { roundStart: false, roundEnd: false, drawFlatCaps: false, ...fillOptions });

    const corners = [
        { x: maxX - centerlineRadius, y: minY + centerlineRadius, startAngle: 270, endAngle: 360 },
        { x: maxX - centerlineRadius, y: maxY - centerlineRadius, startAngle: 0, endAngle: 90 },
        { x: minX + centerlineRadius, y: maxY - centerlineRadius, startAngle: 90, endAngle: 180 },
        { x: minX + centerlineRadius, y: minY + centerlineRadius, startAngle: 180, endAngle: 270 }
    ];
    corners.forEach((corner) => {
        addFilledAnnularSector(
            arr,
            layer,
            corner.x,
            corner.y,
            innerRadius,
            outerRadius,
            corner.startAngle,
            corner.endAngle,
            color,
            null,
            fillOptions
        );
    });

    return true;
}

function draw2DRoundedRectangleBar(arr, layer, left, bottom, right, top, bendRadius = DXF_STIRRUP_BEND_RADIUS, barRadius = DXF_STIRRUP_2D_RADIUS, color = DXF_REBAR_SOLID_COLOR, options = {}) {
    if (!hasFiniteNumbers(left, bottom, right, top, bendRadius, barRadius)) {
        return;
    }

    const minX = Math.min(left, right);
    const maxX = Math.max(left, right);
    const minY = Math.min(bottom, top);
    const maxY = Math.max(bottom, top);
    const width = maxX - minX;
    const height = maxY - minY;
    if (!(width > 0.0001) || !(height > 0.0001)) {
        return;
    }

    const safeBarRadius = Math.max(parsePositiveNumberOrFallback(barRadius, DXF_STIRRUP_2D_RADIUS, 0.001), 0.001);
    const fillOptions = {
        fillStyle: options.fillStyle,
        hatchLayer: options.hatchLayer,
        hatchColor: options.hatchColor,
        hatchPatternName: options.hatchPatternName,
        hatchPatternScale: options.hatchPatternScale,
        hatchPatternAngle: options.hatchPatternAngle
    };
    const centerlineRadius = Math.min(
        Math.max(parsePositiveNumberOrFallback(bendRadius, DXF_STIRRUP_BEND_RADIUS, 0.001), safeBarRadius * 2.2),
        width / 2,
        height / 2
    );

    if (!(centerlineRadius > safeBarRadius + 0.0001)) {
        addFilledBarSegment(arr, layer, minX, minY, maxX, minY, safeBarRadius, color, { roundStart: true, roundEnd: true, ...fillOptions });
        addFilledBarSegment(arr, layer, maxX, minY, maxX, maxY, safeBarRadius, color, { roundStart: true, roundEnd: true, ...fillOptions });
        addFilledBarSegment(arr, layer, maxX, maxY, minX, maxY, safeBarRadius, color, { roundStart: true, roundEnd: true, ...fillOptions });
        addFilledBarSegment(arr, layer, minX, maxY, minX, minY, safeBarRadius, color, { roundStart: true, roundEnd: true, ...fillOptions });
        return;
    }

    addFilledBarSegment(arr, layer, minX + centerlineRadius, minY, maxX - centerlineRadius, minY, safeBarRadius, color, { roundStart: false, roundEnd: false, drawFlatCaps: false, ...fillOptions });
    addFilledBarSegment(arr, layer, maxX, minY + centerlineRadius, maxX, maxY - centerlineRadius, safeBarRadius, color, { roundStart: false, roundEnd: false, drawFlatCaps: false, ...fillOptions });
    addFilledBarSegment(arr, layer, maxX - centerlineRadius, maxY, minX + centerlineRadius, maxY, safeBarRadius, color, { roundStart: false, roundEnd: false, drawFlatCaps: false, ...fillOptions });
    addFilledBarSegment(arr, layer, minX, maxY - centerlineRadius, minX, minY + centerlineRadius, safeBarRadius, color, { roundStart: false, roundEnd: false, drawFlatCaps: false, ...fillOptions });

    addFilledAnnularSector(arr, layer, maxX - centerlineRadius, minY + centerlineRadius, centerlineRadius - safeBarRadius, centerlineRadius + safeBarRadius, 270, 360, color, null, fillOptions);
    addFilledAnnularSector(arr, layer, maxX - centerlineRadius, maxY - centerlineRadius, centerlineRadius - safeBarRadius, centerlineRadius + safeBarRadius, 0, 90, color, null, fillOptions);
    addFilledAnnularSector(arr, layer, minX + centerlineRadius, maxY - centerlineRadius, centerlineRadius - safeBarRadius, centerlineRadius + safeBarRadius, 90, 180, color, null, fillOptions);
    addFilledAnnularSector(arr, layer, minX + centerlineRadius, minY + centerlineRadius, centerlineRadius - safeBarRadius, centerlineRadius + safeBarRadius, 180, 270, color, null, fillOptions);
}

function addRoundedRectangleOutline(arr, layer, left, bottom, right, top, radius, lineType = "", lineTypeScale = null, color = null) {
    if (!hasFiniteNumbers(left, bottom, right, top, radius)) {
        return;
    }

    const minX = Math.min(left, right);
    const maxX = Math.max(left, right);
    const minY = Math.min(bottom, top);
    const maxY = Math.max(bottom, top);
    const width = maxX - minX;
    const height = maxY - minY;
    const bendRadius = Math.min(Math.max(radius, 0), width / 2, height / 2);

    if (!(width > 0) || !(height > 0)) {
        return;
    }

    if (!(bendRadius > 0.0001)) {
        addRectangle(arr, layer, minX, minY, width, height);
        return;
    }

    const lineOptions = { lineType, lineTypeScale, color };
    const addOutlineLine = shouldUsePolylineForDxfLayer(layer) ? addPolylineLine : addLine;
    const addOutlineArc = shouldUsePolylineForDxfLayer(layer) ? addArcPolyline : addArc;
    addOutlineLine(arr, layer, minX + bendRadius, minY, maxX - bendRadius, minY, lineOptions);
    addOutlineLine(arr, layer, maxX, minY + bendRadius, maxX, maxY - bendRadius, lineOptions);
    addOutlineLine(arr, layer, maxX - bendRadius, maxY, minX + bendRadius, maxY, lineOptions);
    addOutlineLine(arr, layer, minX, maxY - bendRadius, minX, minY + bendRadius, lineOptions);

    addOutlineArc(arr, layer, maxX - bendRadius, minY + bendRadius, bendRadius, 270, 360, lineOptions);
    addOutlineArc(arr, layer, maxX - bendRadius, maxY - bendRadius, bendRadius, 0, 90, lineOptions);
    addOutlineArc(arr, layer, minX + bendRadius, maxY - bendRadius, bendRadius, 90, 180, lineOptions);
    addOutlineArc(arr, layer, minX + bendRadius, minY + bendRadius, bendRadius, 180, 270, lineOptions);
}

function getAxisAlignedRectangleFromSegments(segments) {
    const candidate = Array.isArray(segments) ? segments.slice(0, 4) : [];
    if (candidate.length < 4) {
        return null;
    }

    const isAxisAligned = candidate.every((segment) => (
        hasFiniteNumbers(segment?.x1, segment?.y1, segment?.x2, segment?.y2)
        && (Math.abs(segment.x1 - segment.x2) <= 0.0001 || Math.abs(segment.y1 - segment.y2) <= 0.0001)
    ));

    if (!isAxisAligned) {
        return null;
    }

    const xValues = candidate.flatMap((segment) => [segment.x1, segment.x2]);
    const yValues = candidate.flatMap((segment) => [segment.y1, segment.y2]);
    const minX = Math.min(...xValues);
    const maxX = Math.max(...xValues);
    const minY = Math.min(...yValues);
    const maxY = Math.max(...yValues);

    if (!(maxX > minX + 0.0001) || !(maxY > minY + 0.0001)) {
        return null;
    }

    return { left: minX, right: maxX, bottom: minY, top: maxY };
}

function getDxfVectorAngleDegrees(x, y) {
    if (!hasFiniteNumbers(x, y) || Math.hypot(x, y) <= 0.000001) {
        return Number.NaN;
    }
    return Math.atan2(y, x) * 180 / Math.PI;
}

function normalizeSignedDxfAngleDegrees(angle) {
    if (!Number.isFinite(angle)) {
        return Number.NaN;
    }
    let normalized = angle % 360;
    if (normalized <= -180) {
        normalized += 360;
    }
    if (normalized > 180) {
        normalized -= 360;
    }
    return normalized;
}

function drawDxfFrameSectionTangentHook(arr, layer, segment, barRadius, options = {}) {
    const startX = parseNumberOrFallback(segment?.x1, Number.NaN);
    const startY = parseNumberOrFallback(segment?.y1, Number.NaN);
    const tailX = parseNumberOrFallback(segment?.x2, Number.NaN);
    const tailY = parseNumberOrFallback(segment?.y2, Number.NaN);
    const tangentX = parseNumberOrFallback(segment?.tangentDirectionX, Number.NaN);
    const tangentY = parseNumberOrFallback(segment?.tangentDirectionY, Number.NaN);
    if (!hasFiniteNumbers(startX, startY, tailX, tailY, tangentX, tangentY)) {
        return false;
    }

    const tangentLength = Math.hypot(tangentX, tangentY);
    const tailVectorX = tailX - startX;
    const tailVectorY = tailY - startY;
    const tailLengthTotal = Math.hypot(tailVectorX, tailVectorY);
    if (!(tangentLength > 0.000001) || !(tailLengthTotal > 0.000001)) {
        return false;
    }

    const tangentUnitX = tangentX / tangentLength;
    const tangentUnitY = tangentY / tangentLength;
    const tailUnitX = tailVectorX / tailLengthTotal;
    const tailUnitY = tailVectorY / tailLengthTotal;
    const tangentAngle = getDxfVectorAngleDegrees(tangentUnitX, tangentUnitY);
    const tailAngle = getDxfVectorAngleDegrees(tailUnitX, tailUnitY);
    const signedTurn = normalizeSignedDxfAngleDegrees(tailAngle - tangentAngle);
    // Closed stirrup branches use a 45-degree tangent transition, while the
    // terminal hooks of internal crossties require the actual 135-degree bend
    // from the straight bar back toward the confined longitudinal bar.
    const absoluteTurn = Math.abs(signedTurn);
    const isSupportedHookTurn = Math.abs(absoluteTurn - 45) <= 0.01
        || Math.abs(absoluteTurn - 135) <= 0.01;
    if (!Number.isFinite(signedTurn) || !isSupportedHookTurn) {
        return false;
    }

    const drawingScale = parsePositiveNumberOrFallback(
        options.frameSectionHookScale ?? options.frameSectionHookCurveScale,
        SECTION_DETAIL_SCALE,
        0.0001
    );
    const configuredInnerRadius = parsePositiveNumberOrFallback(
        options.frameSectionHookInnerRadius,
        Number.NaN,
        0
    );
    const configuredOuterRadius = parsePositiveNumberOrFallback(
        options.frameSectionHookOuterRadius,
        Number.NaN,
        0
    );
    const hasExplicitFaceRadii = Number.isFinite(configuredInnerRadius)
        && Number.isFinite(configuredOuterRadius)
        && configuredOuterRadius > configuredInnerRadius;
    const configuredDiameter = parsePositiveNumberOrFallback(
        options.frameSectionHookCurveDiameter,
        0.0146,
        0.0001
    );
    const configuredTailExtension = parsePositiveNumberOrFallback(
        options.frameSectionHookTailExtension,
        FRAME_SECTION_STIRRUP_HOOK_TAIL_EXTENSION,
        0.0001
    );
    const tailExtension = configuredTailExtension * drawingScale;
    const safeBarRadius = Math.max(parsePositiveNumberOrFallback(barRadius, DXF_STIRRUP_2D_RADIUS, 0.001), 0.001);
    // Legacy callers can still supply a bend diameter. Frame sections now pass
    // both physical face radii, which makes the exterior and interior arcs
    // exactly R0.0242 m and R0.0146 m after section scaling.
    const centerlineRadius = hasExplicitFaceRadii
        ? ((configuredInnerRadius + configuredOuterRadius) * drawingScale) / 2
        : Math.max((configuredDiameter * drawingScale) / 2, safeBarRadius * 1.15);
    const innerCurveRadius = hasExplicitFaceRadii
        ? configuredInnerRadius * drawingScale
        : Math.max(centerlineRadius - safeBarRadius, 0.0001);
    const outerCurveRadius = hasExplicitFaceRadii
        ? configuredOuterRadius * drawingScale
        : centerlineRadius + safeBarRadius;
    const hookBarRadius = hasExplicitFaceRadii
        ? (outerCurveRadius - innerCurveRadius) / 2
        : safeBarRadius;

    const turnDirection = Math.sign(signedTurn) || 1;
    const leftNormalX = -tangentUnitY;
    const leftNormalY = tangentUnitX;
    const centerX = startX + leftNormalX * centerlineRadius * turnDirection;
    const centerY = startY + leftNormalY * centerlineRadius * turnDirection;
    const startRadiusAngle = getDxfVectorAngleDegrees(startX - centerX, startY - centerY);
    const endRadiusAngle = startRadiusAngle + signedTurn;
    const arcStartAngle = signedTurn > 0 ? startRadiusAngle : endRadiusAngle;
    const arcEndAngle = signedTurn > 0 ? endRadiusAngle : startRadiusAngle;

    const centerlineArcEnd = getDxfAnglePoint(centerX, centerY, centerlineRadius, endRadiusAngle);
    const outerArcEnd = getDxfAnglePoint(centerX, centerY, outerCurveRadius, endRadiusAngle);
    const innerArcEnd = getDxfAnglePoint(centerX, centerY, innerCurveRadius, endRadiusAngle);

    let intersectionDistance = Number.NaN;
    const hookUsesHorizontalReference = Math.abs(tangentUnitX) >= Math.abs(tangentUnitY);
    if (hookUsesHorizontalReference) {
        const tailReferenceY = startY + (Math.sign(tailUnitY) || 1) * hookBarRadius;
        if (Math.abs(tailUnitY) > 0.000001) {
            intersectionDistance = (tailReferenceY - outerArcEnd.y) / tailUnitY;
        }
    } else {
        const tailReferenceX = startX + (Math.sign(tailUnitX) || 1) * hookBarRadius;
        if (Math.abs(tailUnitX) > 0.000001) {
            intersectionDistance = (tailReferenceX - outerArcEnd.x) / tailUnitX;
        }
    }

    const turnRadians = Math.abs(signedTurn) * Math.PI / 180;
    const developedCurveLength = centerlineRadius * turnRadians;
    const fallbackTailLength = Math.max(tailLengthTotal - developedCurveLength, hookBarRadius * 0.75);
    // The exterior tail must continue exactly 0.02 m past its intersection
    // with the inner stirrup face.  The original hook-length fallback is
    // only used when no intersection can be resolved; otherwise it would
    // make the -45° tail longer than the requested extension.
    const useIntersectionTailLength = Math.abs(absoluteTurn - 45) <= 0.01
        && Number.isFinite(intersectionDistance);
    const tailLength = useIntersectionTailLength
        ? Math.max(intersectionDistance + tailExtension, hookBarRadius * 0.75)
        : Math.max(fallbackTailLength, hookBarRadius * 0.75);
    const outerTailEnd = {
        x: outerArcEnd.x + tailUnitX * tailLength,
        y: outerArcEnd.y + tailUnitY * tailLength
    };
    const innerTailEnd = {
        x: innerArcEnd.x + tailUnitX * tailLength,
        y: innerArcEnd.y + tailUnitY * tailLength
    };
    const fillOptions = {
        fillStyle: options.fillStyle,
        hatchLayer: options.hatchLayer,
        hatchColor: options.hatchColor,
        hatchPatternName: options.hatchPatternName,
        hatchPatternScale: options.hatchPatternScale,
        hatchPatternAngle: options.hatchPatternAngle
    };

    addFilledAnnularSector(
        arr,
        layer,
        centerX,
        centerY,
        innerCurveRadius,
        outerCurveRadius,
        arcStartAngle,
        arcEndAngle,
        DXF_REBAR_SOLID_COLOR,
        null,
        fillOptions
    );

    const rebarHatchStyle = getRebarHatchStyle(layer, fillOptions);
    const tailVertices = [outerArcEnd, outerTailEnd, innerTailEnd, innerArcEnd];
    if (rebarHatchStyle) {
        addHatch(arr, rebarHatchStyle.hatchLayer, tailVertices, {
            ...rebarHatchStyle.hatchOptions,
            outlineLayer: layer
        });
    } else {
        addFilledQuadrilateral(arr, layer, tailVertices, DXF_REBAR_SOLID_COLOR);
    }
    const addTailOutline = shouldUsePolylineForDxfLayer(layer) ? addPolylineLine : addLine;
    addTailOutline(arr, layer, outerArcEnd.x, outerArcEnd.y, outerTailEnd.x, outerTailEnd.y);
    addTailOutline(arr, layer, innerArcEnd.x, innerArcEnd.y, innerTailEnd.x, innerTailEnd.y);
    addTailOutline(arr, layer, outerTailEnd.x, outerTailEnd.y, innerTailEnd.x, innerTailEnd.y);
    return true;
}

function drawDxfConfinementSegmentsWithRoundedCorners(arr, layer, segments, options = {}) {
    const normalizedSegments = Array.isArray(segments) ? segments : [];
    const barRadius = Math.max(parsePositiveNumberOrFallback(options.barRadius, DXF_STIRRUP_2D_RADIUS, 0.001), 0.001);
    const fillOptions = {
        fillStyle: options.fillStyle,
        hatchLayer: options.hatchLayer,
        hatchColor: options.hatchColor,
        hatchPatternName: options.hatchPatternName,
        hatchPatternScale: options.hatchPatternScale,
        hatchPatternAngle: options.hatchPatternAngle
    };
    const rectangle = getAxisAlignedRectangleFromSegments(normalizedSegments);
    if (!rectangle) {
        const tangentHookStarts = normalizedSegments
            .filter((segment) => options.frameSectionTangentHooks === true
                && segment?.kind === "frame-section-tangent-hook"
                && hasFiniteNumbers(segment?.x1, segment?.y1))
            .map((segment) => ({ x: segment.x1, y: segment.y1 }));
        const connectionTolerance = Math.max(barRadius * 0.25, 0.00001);
        const isConnectedToTangentHook = (x, y) => tangentHookStarts.some((point) => (
            Math.hypot(point.x - x, point.y - y) <= connectionTolerance
        ));

        normalizedSegments.forEach((segment) => {
            const hasFrameTangentHook = options.frameSectionTangentHooks === true
                && segment?.kind === "frame-section-tangent-hook";
            if (hasFrameTangentHook && drawDxfFrameSectionTangentHook(arr, layer, segment, barRadius, {
                ...fillOptions,
                frameSectionHookInnerRadius: options.frameSectionHookInnerRadius,
                frameSectionHookOuterRadius: options.frameSectionHookOuterRadius,
                frameSectionHookScale: options.frameSectionHookScale,
                frameSectionHookCurveDiameter: options.frameSectionHookCurveDiameter,
                frameSectionHookCurveScale: options.frameSectionHookCurveScale
            })) {
                return;
            }
            const connectedStart = !hasFrameTangentHook
                && isConnectedToTangentHook(segment.x1, segment.y1);
            const connectedEnd = !hasFrameTangentHook
                && isConnectedToTangentHook(segment.x2, segment.y2);
            addFilledBarSegment(arr, layer, segment.x1, segment.y1, segment.x2, segment.y2, barRadius, DXF_REBAR_SOLID_COLOR, {
                roundStart: !hasFrameTangentHook && !connectedStart,
                roundEnd: hasFrameTangentHook || !connectedEnd,
                capStyle: "semicircle",
                drawFlatCaps: false,
                ...fillOptions
            });
        });
        return;
    }

    const width = rectangle.right - rectangle.left;
    const height = rectangle.top - rectangle.bottom;
    const radius = Math.min(
        Math.max(parsePositiveNumberOrFallback(options.radius, DXF_STIRRUP_BEND_RADIUS, 0.001), barRadius * 2.2),
        Math.max(Math.min(width, height) * 0.18, barRadius * 2.2),
        width / 2,
        height / 2
    );

    const drawnWithPrescribedFrameCornerRadii = options.frameSectionTangentCorners === true
        && drawFrameSectionStirrupWithTangentCorners(
            arr,
            layer,
            rectangle.left,
            rectangle.bottom,
            rectangle.right,
            rectangle.top,
            options.frameSectionCornerInnerRadius,
            options.frameSectionCornerOuterRadius,
            options.frameSectionCornerScale,
            DXF_REBAR_SOLID_COLOR,
            fillOptions
        );
    if (!drawnWithPrescribedFrameCornerRadii) {
        draw2DRoundedRectangleBar(
            arr,
            layer,
            rectangle.left,
            rectangle.bottom,
            rectangle.right,
            rectangle.top,
            radius,
            barRadius,
            DXF_REBAR_SOLID_COLOR,
            fillOptions
        );
    }

    normalizedSegments.slice(4).forEach((segment) => {
        const hasFrameTangentHook = options.frameSectionTangentHooks === true
            && segment?.kind === "frame-section-tangent-hook";
        if (hasFrameTangentHook && drawDxfFrameSectionTangentHook(arr, layer, segment, barRadius, {
            ...fillOptions,
            frameSectionHookInnerRadius: options.frameSectionHookInnerRadius,
            frameSectionHookOuterRadius: options.frameSectionHookOuterRadius,
            frameSectionHookScale: options.frameSectionHookScale,
            // Kept as a fallback for older callers that still pass only a
            // centerline bend diameter.
            frameSectionHookCurveDiameter: options.frameSectionHookCurveDiameter,
            frameSectionHookCurveScale: options.frameSectionHookCurveScale
        })) {
            return;
        }
        addFilledBarSegment(arr, layer, segment.x1, segment.y1, segment.x2, segment.y2, barRadius, DXF_REBAR_SOLID_COLOR, {
            roundStart: false,
            roundEnd: true,
            capStyle: "semicircle",
            drawFlatCaps: false,
            ...fillOptions
        });
    });
}

function addDashedLine(arr, layer, x1, y1, x2, y2, dashSize = DXF_DASH_SIZE, gapSize = DXF_GAP_SIZE) {
    if (!hasFiniteNumbers(x1, y1, x2, y2)) {
        return;
    }

    const dx = x2 - x1;
    const dy = y2 - y1;
    const length = Math.hypot(dx, dy);
    if (length < 0.001) {
        return;
    }

    const unitX = dx / length;
    const unitY = dy / length;
    let traveled = 0;

    while (traveled < length) {
        const segmentStart = traveled;
        const segmentEnd = Math.min(traveled + dashSize, length);
        addLine(
            arr,
            layer,
            x1 + unitX * segmentStart,
            y1 + unitY * segmentStart,
            x1 + unitX * segmentEnd,
            y1 + unitY * segmentEnd
        );
        traveled += dashSize + gapSize;
    }
}

function addRectangle(arr, layer, x, y, width, height, options = {}) {
    if (!hasFiniteNumbers(x, y, width, height) || !(width > 0) || !(height > 0)) {
        return;
    }

    const lineType = typeof options === "object" ? String(options.lineType || "") : "";
    const lineTypeScale = typeof options === "object" ? Number.parseFloat(options.lineTypeScale) : Number.NaN;
    const color = typeof options === "object" ? Number.parseInt(options.color, 10) : Number.NaN;
    const safeLineTypeScale = Number.isFinite(lineTypeScale) ? lineTypeScale : null;
    const safeColor = Number.isFinite(color) ? color : null;

    if (shouldUsePolylineForDxfLayer(layer)) {
        addPolylineRectangle(arr, layer, x, y, width, height, { lineType, lineTypeScale: safeLineTypeScale, color: safeColor });
        return;
    }
    addLine(arr, layer, x, y, x + width, y, lineType, safeLineTypeScale, safeColor);
    addLine(arr, layer, x + width, y, x + width, y + height, lineType, safeLineTypeScale, safeColor);
    addLine(arr, layer, x + width, y + height, x, y + height, lineType, safeLineTypeScale, safeColor);
    addLine(arr, layer, x, y + height, x, y, lineType, safeLineTypeScale, safeColor);
}

function addFilledRectangle(arr, layer, x, y, width, height, color = 250) {
    if (!hasFiniteNumbers(x, y, width, height) || !(width > 0) || !(height > 0)) {
        return;
    }

    // Uses SOLID entity (code 0 SOLID) to fill a quadrilateral area.
    arr.push(
        "0", "SOLID",
        "8", layer,
        "62", String(color),
        "10", x,
        "20", y,
        "11", x + width,
        "21", y,
        "12", x,
        "22", y + height,
        "13", x + width,
        "23", y + height
    );
}

function addFilledQuadrilateral(arr, layer, vertices, color = 250) {
    if (!Array.isArray(vertices) || vertices.length < 4) {
        return;
    }

    const [first, second, third, fourth] = vertices;
    if (!hasFiniteNumbers(first?.x, first?.y, second?.x, second?.y, third?.x, third?.y, fourth?.x, fourth?.y)) {
        return;
    }

    arr.push(
        "0", "SOLID",
        "8", layer,
        "62", String(color),
        "10", first.x,
        "20", first.y,
        "11", second.x,
        "21", second.y,
        "12", fourth.x,
        "22", fourth.y,
        "13", third.x,
        "23", third.y
    );
}

function getDxfHatchPatternDefinitions(patternName, patternScale, patternAngle = 45, options = {}) {
    const safePatternScale = Math.max(parsePositiveNumberOrFallback(patternScale, 0.1, 0.000001), 0.0001);
    const defaultAngle = Number.isFinite(patternAngle) ? patternAngle : 45;
    const normalizedPattern = normalizeTextValue(patternName).toUpperCase();

    if (normalizedPattern === "ANSI37") {
        return [
            { angle: 45, baseX: 0, baseY: 0, offsetX: 0, offsetY: safePatternScale },
            { angle: 135, baseX: 0, baseY: 0, offsetX: 0, offsetY: safePatternScale }
        ];
    }

    if (normalizedPattern === "ANSI31") {
        if (options?.masonryReferenceDefinition === true) {
            // Match the supplied masonry-reference DXF: ANSI31 at scale 0.30,
            // a 45-degree line definition, and a compact repeat vector of
            // scale / (8*sqrt(2)). This produces the same diagonal density
            // without resorting to manually drawn LINE entities.
            const referenceOffset = safePatternScale / (8 * Math.SQRT2);
            return [{
                angle: 45,
                baseX: 0,
                baseY: 0,
                offsetX: -referenceOffset,
                offsetY: referenceOffset
            }];
        }
        // ANSI31 is a predefined AutoCAD pattern, not a generic single-line
        // hatch.  The pattern-line angle (group 53) and offset vector
        // (groups 45/46) must be the transformed native ANSI31 values.
        // Writing the header angle alone (or using the header angle as group
        // 53) can leave AutoCAD with stale/invalid pattern geometry until the
        // user opens HATCHEDIT and re-applies the same angle or scale.
        //
        // Native definition at scale 1: line angle 45°, repeat vector 3.175
        // drawing units at 135°.  Rotate both by the requested hatch angle.
        const rotationDegrees = ((defaultAngle % 360) + 360) % 360;
        const rotationRadians = (rotationDegrees * Math.PI) / 180;
        const repeatLength = 3.175 * safePatternScale;
        const repeatAngleRadians = rotationRadians + (135 * Math.PI) / 180;
        // Preserve AutoCAD's native double-precision values.  Re-rounding
        // this vector can make a DXF look equivalent on paper, but it no
        // longer matches the value AutoCAD rebuilds when HATCHEDIT is used.
        const nativePatternValue = (value) => (Object.is(value, -0) ? 0 : value);
        const offsetX = nativePatternValue(repeatLength * Math.cos(repeatAngleRadians));
        const rawOffsetY = nativePatternValue(repeatLength * Math.sin(repeatAngleRadians));
        // For the 0-degree user hatch angle, AutoCAD serializes the 135°
        // repeat vector symmetrically from the X component.  Keeping that
        // exact relationship avoids one-ULP drift in the Y value.
        const offsetY = rotationDegrees === 0 ? nativePatternValue(-offsetX) : rawOffsetY;
        return [
            {
                angle: nativePatternValue(rotationDegrees + 45),
                baseX: 0,
                baseY: 0,
                offsetX,
                offsetY
            }
        ];
    }

    if (normalizedPattern === "MALLA_ELECTROSOLDADA") {
        // The reference DXF uses an orthogonal custom hatch.  Unlike a normal
        // physical bar spacing, this is a detail symbol: the grid must scale
        // with the slab shape independently in X and Y from the 4x4 reference.
        const scaleX = Math.max(parsePositiveNumberOrFallback(options?.hatchScaleX, 1, 0.000001), 0.000001);
        const scaleY = Math.max(parsePositiveNumberOrFallback(options?.hatchScaleY, 1, 0.000001), 0.000001);
        return [
            { angle: 0, baseX: 0, baseY: 0, offsetX: 0, offsetY: safePatternScale * scaleY },
            { angle: 90, baseX: 0, baseY: 0, offsetX: -safePatternScale * scaleX, offsetY: 0 }
        ];
    }

    if (normalizedPattern === "AR-CONC") {
        // Match AutoCAD's native AR-CONC definition exactly.  A HATCH entity
        // must carry the same scaled pattern-line geometry that AutoCAD
        // rebuilds from ACAD.PAT during HATCHEDIT.  The former simplified
        // three-line approximation (and a 45° base angle) made a newly
        // opened DXF look different until AutoCAD regenerated it after the
        // user re-entered the scale.
        const scalePatternValue = (value) => Number((value * safePatternScale).toFixed(12));
        const createDefinition = (angle, baseX, baseY, offsetX, offsetY, dashLengths = []) => ({
            angle,
            baseX: scalePatternValue(baseX),
            baseY: scalePatternValue(baseY),
            offsetX: scalePatternValue(offsetX),
            offsetY: scalePatternValue(offsetY),
            dashLengths: dashLengths.map(scalePatternValue)
        });
        return [
            createDefinition(50, 0, 0, 4.12975034, -5.89789472, [0.75, -8.25]),
            createDefinition(355, 0, 0, -2.03781207, 7.37236840, [0.60, -6.6]),
            createDefinition(100.45144446, 0.59771681, -0.05229344, 5.7305871, -6.9397673, [0.63740192, -7.01142112]),
            createDefinition(46.1842, 0, 2, 6.19462554, -8.84684596, [1.125, -12.375]),
            createDefinition(96.63563549, 0.88936745, 1.86206693, 8.59588239, -10.40964966, [0.95610342, -10.5171376]),
            createDefinition(351.18416399, 0, 2, 7.74327494, 11.05855746, [0.9, -9.90000001]),
            createDefinition(21, 1, 1.5, 4.12975034, -5.89789472, [0.75, -8.25]),
            createDefinition(326, 1, 1.5, -2.03781207, 7.37236840, [0.60, -6.6]),
            createDefinition(71.45144474, 1.49742254, 1.16448426, 5.7305871, -6.9397673, [0.6374019, -7.01142112]),
            createDefinition(37.5, 0, 0, 2.123, 2.567, [0, -6.52, 0, -6.7, 0, -6.625]),
            createDefinition(7.5, 0, 0, 3.123, 3.567, [0, -3.82, 0, -6.37, 0, -2.525]),
            createDefinition(-32.5, -2.23, 0, 4.6234, 2.678, [0, -2.5, 0, -7.8, 0, -10.35]),
            createDefinition(-42.5, -3.23, 0, 3.6234, 4.678, [0, -3.25, 0, -5.18, 0, -7.35])
        ];
    }

    if (normalizedPattern === "AR-B816C") {
        // The HATCH entity stores the effective pattern geometry in drawing
        // units.  Group 41 preserves the user-facing hatch scale, but does
        // not scale groups 43–49 when AutoCAD first renders an imported DXF.
        // Therefore each ACAD.PAT value must be written at the requested
        // scale here.  Leaving the raw 8x16 values made the pattern spacing
        // eight drawing units wide, so a normal masonry elevation contained
        // no visible strokes until HATCHEDIT forced AutoCAD to rebuild it.
        const scalePatternValue = (value) => Number((value * safePatternScale).toFixed(10));
        return [
            {
                angle: 0,
                baseX: scalePatternValue(0),
                baseY: scalePatternValue(0),
                offsetX: scalePatternValue(8),
                offsetY: scalePatternValue(8),
                dashLengths: [scalePatternValue(15.625), scalePatternValue(-0.375)]
            },
            {
                angle: 0,
                baseX: scalePatternValue(-8),
                baseY: scalePatternValue(0.375),
                offsetX: scalePatternValue(8),
                offsetY: scalePatternValue(8),
                dashLengths: [scalePatternValue(15.625), scalePatternValue(-0.375)]
            },
            {
                angle: 90,
                baseX: scalePatternValue(0),
                baseY: scalePatternValue(0),
                offsetX: scalePatternValue(8),
                offsetY: scalePatternValue(8),
                dashLengths: [scalePatternValue(-8.375), scalePatternValue(7.625)]
            },
            {
                angle: 90,
                baseX: scalePatternValue(-0.375),
                baseY: scalePatternValue(0),
                offsetX: scalePatternValue(8),
                offsetY: scalePatternValue(8),
                dashLengths: [scalePatternValue(-8.375), scalePatternValue(7.625)]
            }
        ];
    }

    return [
        { angle: defaultAngle, baseX: 0, baseY: 0, offsetX: 0, offsetY: safePatternScale }
    ];
}

function addHatch(arr, layer, vertices, options = {}) {
    const normalizedVertices = [];
    const duplicateTolerance = 0.000001;
    (Array.isArray(vertices) ? vertices : []).forEach((vertex) => {
        const x = Number.parseFloat(vertex?.x);
        const y = Number.parseFloat(vertex?.y);
        if (!Number.isFinite(x) || !Number.isFinite(y)) {
            return;
        }
        const previous = normalizedVertices[normalizedVertices.length - 1];
        if (previous && Math.abs(previous.x - x) <= duplicateTolerance && Math.abs(previous.y - y) <= duplicateTolerance) {
            return;
        }
        normalizedVertices.push({ x, y });
    });

    if (normalizedVertices.length > 2) {
        const first = normalizedVertices[0];
        const last = normalizedVertices[normalizedVertices.length - 1];
        if (Math.abs(first.x - last.x) <= duplicateTolerance && Math.abs(first.y - last.y) <= duplicateTolerance) {
            normalizedVertices.pop();
        }
    }

    if (normalizedVertices.length < 3) {
        return;
    }

    const signedArea = normalizedVertices.reduce((area, vertex, index) => {
        const next = normalizedVertices[(index + 1) % normalizedVertices.length];
        return area + vertex.x * next.y - next.x * vertex.y;
    }, 0);
    if (signedArea < 0) {
        normalizedVertices.reverse();
    }

    const patternName = String(options?.patternName || "ANSI31").trim().toUpperCase() || "ANSI31";
    const requestedScale = parsePositiveNumberOrFallback(options?.patternScale, SLAB_PLAN_MASONRY_HATCH_SPACING, 0.000001);
    // Architectural patterns carry their own line angles.  Their header
    // angle must remain zero unless an explicit rotation is requested.
    const defaultPatternAngle = ["AR-CONC", "AR-B816C"].includes(patternName) ? 0 : 45;
    const patternAngle = parseNumberOrFallback(options?.patternAngle, defaultPatternAngle);
    const color = Number.parseInt(options?.color, 10);
    const unitScale = Number.isFinite(arr?._unitScale) && arr._unitScale > 0 ? arr._unitScale : 1;
    const patternScale = requestedScale * unitScale;
    const patternDefinitions = getDxfHatchPatternDefinitions(patternName, patternScale, patternAngle, options);
    // AutoCAD's repaired/native cassette hatch stores the ANSI31 pattern
    // base at the WCS origin.  A base point derived from the cassette's
    // insertion point is what causes the hatch to remain blank or malformed
    // until the user changes an option in HATCHEDIT and AutoCAD rebuilds it.
    const forceCassetteNativeOrigin = layer === "LOSA_BOVEDILLA" && patternName === "ANSI31";
    const usesReferenceEdgeBoundary = options?.boundaryStyle === "edges";
    const boundaryPayload = usesReferenceEdgeBoundary
        ? [
            // External edge boundary, matching the reference HATCH rather
            // than writing a polyline boundary. Each wall edge remains a
            // proper native hatch boundary in AutoCAD.
            "92", "1",
            "93", String(normalizedVertices.length),
            ...normalizedVertices.flatMap((vertex, index) => {
                const next = normalizedVertices[(index + 1) % normalizedVertices.length];
                return [
                    "72", "1",
                    "10", String(vertex.x),
                    "20", String(vertex.y),
                    "11", String(next.x),
                    "21", String(next.y)
                ];
            })
        ]
        : [
            // External closed polyline boundary (1 = external, 2 = polyline).
            "92", "3",
            "72", "0",
            "73", "1",
            "93", String(normalizedVertices.length),
            ...normalizedVertices.flatMap((vertex) => ["10", String(vertex.x), "20", String(vertex.y)])
        ];

    arr.push(
        "0", "HATCH",
        "8", layer,
        ...(Number.isFinite(color) ? ["62", String(color)] : []),
        // HATCH strokes always plot at 0.00 mm, independent of their host layer.
        "370", "0",
        "10", "0", "20", "0", "30", "0",
        "210", "0", "220", "0", "230", "1",
        "2", patternName,
        "70", "0",
        "71", options?.associative === true ? "1" : "0",
        "91", "1",
        ...boundaryPayload,
        "97", "0",
        "75", String(Number.parseInt(options?.hatchStyle, 10) || 0),
        "76", "1",
        "52", String(patternAngle),
        "41", String(patternScale),
        "77", "0",
        "78", String(patternDefinitions.length)
    );

    patternDefinitions.forEach((definition) => {
        const dashLengths = Array.isArray(definition.dashLengths)
            ? definition.dashLengths.map((value) => Number.parseFloat(value)).filter(Number.isFinite)
            : [];
        arr.push(
            "53", String(Number.isFinite(definition.angle) ? definition.angle : patternAngle),
            // Keep the literal 0.0 used by AutoCAD's regenerated ANSI31
            // cassette entity, rather than inheriting any local insertion
            // coordinates that may have been supplied by an upstream writer.
            "43", forceCassetteNativeOrigin ? "0.0" : String(Number.isFinite(definition.baseX) ? definition.baseX : 0),
            "44", forceCassetteNativeOrigin ? "0.0" : String(Number.isFinite(definition.baseY) ? definition.baseY : 0),
            "45", String(Number.isFinite(definition.offsetX) ? definition.offsetX : 0),
            "46", String(Number.isFinite(definition.offsetY) ? definition.offsetY : patternScale),
            "79", String(dashLengths.length),
            ...dashLengths.flatMap((dashLength) => ["49", String(dashLength)])
        );
    });

    arr.push("98", "0");
}

function addCircle(arr, layer, x, y, radius, color = null, lineWeight = null) {
    if (!hasFiniteNumbers(x, y, radius) || !(radius > 0)) {
        return;
    }

    if (shouldUsePolylineForDxfLayer(layer)) {
        addPolyline(arr, layer, buildRegularPolygonVertices(x, y, radius, 32, -90), { closed: true, color, lineWeight });
        return;
    }

    arr.push(
        "0", "CIRCLE",
        "8", layer,
        ...(Number.isFinite(color) ? ["62", String(color)] : []),
        ...(Number.isFinite(lineWeight) ? ["370", String(lineWeight)] : []),
        "10", x,
        "20", y,
        "40", radius
    );
}

function buildRegularPolygonVertices(centerX, centerY, radius, segmentCount = 32, startAngleDegrees = 0) {
    const safeSegments = Math.max(12, Math.min(Math.round(segmentCount) || 32, 96));
    const startAngleRadians = (startAngleDegrees * Math.PI) / 180;
    return Array.from({ length: safeSegments }, (_, index) => {
        const angle = startAngleRadians + (Math.PI * 2 * index) / safeSegments;
        return {
            x: centerX + Math.cos(angle) * radius,
            y: centerY + Math.sin(angle) * radius
        };
    });
}

function buildArcVertices(centerX, centerY, radius, startAngleDegrees, endAngleDegrees, segmentCount = 12) {
    const sweep = getPositiveDxfAngleSweep(startAngleDegrees, endAngleDegrees);
    const safeSegments = Math.max(4, Math.min(Math.round(segmentCount) || Math.ceil(sweep / 10), 96));
    return Array.from({ length: safeSegments + 1 }, (_, index) => {
        const angle = startAngleDegrees + (sweep * index) / safeSegments;
        return getDxfAnglePoint(centerX, centerY, radius, angle);
    });
}

function addHatchedCircle(arr, layer, x, y, radius, options = {}, segmentCount = 32) {
    if (!hasFiniteNumbers(x, y, radius) || !(radius > 0)) {
        return;
    }
    const vertices = buildRegularPolygonVertices(x, y, radius, segmentCount, -90);
    addHatch(arr, layer, vertices, options);
    const outlineLayer = options.outlineLayer || layer;
    if (options.drawOutline !== false) {
        if (shouldUsePolylineForDxfLayer(outlineLayer)) {
            addPolyline(arr, outlineLayer, vertices, { closed: true });
        } else {
            addCircle(arr, outlineLayer, x, y, radius);
        }
    }
}

function addHatchedAnnularSector(arr, layer, centerX, centerY, innerRadius, outerRadius, startAngle, endAngle, options = {}, segmentCount = null) {
    if (!hasFiniteNumbers(centerX, centerY, innerRadius, outerRadius, startAngle, endAngle)) {
        return;
    }

    const safeInnerRadius = Math.max(parsePositiveNumberOrFallback(innerRadius, 0, 0), 0.0001);
    const safeOuterRadius = Math.max(parsePositiveNumberOrFallback(outerRadius, 0, 0), safeInnerRadius + 0.0001);
    const sweep = getPositiveDxfAngleSweep(startAngle, endAngle);
    if (!(sweep > 0.0001)) {
        return;
    }

    const safeSegments = Math.max(6, Math.min(Math.round(segmentCount) || Math.ceil(sweep / 10), 144));
    const outerVertices = buildArcVertices(centerX, centerY, safeOuterRadius, startAngle, endAngle, safeSegments);
    const innerVertices = buildArcVertices(centerX, centerY, safeInnerRadius, startAngle, endAngle, safeSegments).reverse();
    const outlineLayer = options.outlineLayer || layer;
    addHatch(arr, layer, [...outerVertices, ...innerVertices], options);
    const drawOutline = options.drawOutline !== false;
    const outlineWithPolylines = shouldUsePolylineForDxfLayer(outlineLayer);
    if (drawOutline) {
        if (outlineWithPolylines) {
            addPolyline(arr, outlineLayer, outerVertices);
            addPolyline(arr, outlineLayer, innerVertices.slice().reverse());
        } else {
            addArc(arr, outlineLayer, centerX, centerY, safeOuterRadius, startAngle, endAngle);
            addArc(arr, outlineLayer, centerX, centerY, safeInnerRadius, startAngle, endAngle);
        }
    }

    if (drawOutline && options.drawRadialEdges === true) {
        const startOuter = getDxfAnglePoint(centerX, centerY, safeOuterRadius, startAngle);
        const startInner = getDxfAnglePoint(centerX, centerY, safeInnerRadius, startAngle);
        const endOuter = getDxfAnglePoint(centerX, centerY, safeOuterRadius, startAngle + sweep);
        const endInner = getDxfAnglePoint(centerX, centerY, safeInnerRadius, startAngle + sweep);
        if (outlineWithPolylines) {
            addPolylineLine(arr, outlineLayer, startOuter.x, startOuter.y, startInner.x, startInner.y);
            addPolylineLine(arr, outlineLayer, endOuter.x, endOuter.y, endInner.x, endInner.y);
        } else {
            addLine(arr, outlineLayer, startOuter.x, startOuter.y, startInner.x, startInner.y);
            addLine(arr, outlineLayer, endOuter.x, endOuter.y, endInner.x, endInner.y);
        }
    }
}

function addRepresentativeRebarCircle(arr, layer, x, y, radius, fillColor = DXF_REBAR_REPRESENTATIVE_FILL_COLOR, segmentCount = 32) {
    if (!hasFiniteNumbers(x, y, radius) || !(radius > 0)) {
        return;
    }

    const safeSegments = Math.max(12, Math.min(Math.round(segmentCount) || 32, 96));
    for (let index = 0; index < safeSegments; index += 1) {
        const startAngle = (Math.PI * 2 * index) / safeSegments;
        const endAngle = (Math.PI * 2 * (index + 1)) / safeSegments;
        const x1 = x + Math.cos(startAngle) * radius;
        const y1 = y + Math.sin(startAngle) * radius;
        const x2 = x + Math.cos(endAngle) * radius;
        const y2 = y + Math.sin(endAngle) * radius;

        arr.push(
            "0", "SOLID",
            "8", layer,
            "62", String(fillColor),
            "10", x,
            "20", y,
            "11", x1,
            "21", y1,
            "12", x2,
            "22", y2,
            "13", x2,
            "23", y2
        );
    }

    if (shouldUsePolylineForDxfLayer(layer)) {
        addPolyline(arr, layer, buildRegularPolygonVertices(x, y, radius, safeSegments, -90), { closed: true });
    } else {
        addCircle(arr, layer, x, y, radius);
    }
}

function addFilledCircle(arr, layer, x, y, radius, color = 7, segmentCount = 32) {
    if (!hasFiniteNumbers(x, y, radius) || !(radius > 0)) {
        return;
    }

    const rebarHatchStyle = getRebarHatchStyle(layer);
    if (rebarHatchStyle) {
        addHatchedCircle(arr, rebarHatchStyle.hatchLayer, x, y, radius, {
            ...rebarHatchStyle.hatchOptions,
            outlineLayer: layer
        }, segmentCount);
        return;
    }

    const safeSegments = Math.max(12, Math.min(Math.round(segmentCount) || 32, 96));
    for (let index = 0; index < safeSegments; index += 1) {
        const startAngle = (Math.PI * 2 * index) / safeSegments;
        const endAngle = (Math.PI * 2 * (index + 1)) / safeSegments;
        const x1 = x + Math.cos(startAngle) * radius;
        const y1 = y + Math.sin(startAngle) * radius;
        const x2 = x + Math.cos(endAngle) * radius;
        const y2 = y + Math.sin(endAngle) * radius;

        arr.push(
            "0", "SOLID",
            "8", layer,
            "62", String(color),
            "10", x,
            "20", y,
            "11", x1,
            "21", y1,
            "12", x2,
            "22", y2,
            "13", x2,
            "23", y2
        );
    }

    if (shouldUsePolylineForDxfLayer(layer)) {
        addPolyline(arr, layer, buildRegularPolygonVertices(x, y, radius, safeSegments, -90), { closed: true });
    } else {
        addCircle(arr, layer, x, y, radius);
    }
}

function drawDetailTitleMarker(dxf, centerX, centerY, topText, bottomText = "E-00", titleText = "", options = {}) {
    // Drawing-title markers are deliberately standardized instead of inheriting
    // the local detail scale. This keeps every title bubble consistent across
    // plans, sections, elevations, and reference details.
    const diameter = Math.max(parsePositiveNumberOrFallback(
        options.diameter,
        DXF_DETAIL_TITLE_MARKER_DIAMETER,
        0.001
    ), 0.001);
    const radius = diameter / 2;
    const internalTextHeight = Math.max(parsePositiveNumberOrFallback(options.internalTextHeight, DXF_DETAIL_TITLE_MARKER_INTERNAL_TEXT_HEIGHT, 0.001), 0.001);
    const externalTextHeight = Math.max(parsePositiveNumberOrFallback(options.externalTextHeight, DXF_DETAIL_TITLE_MARKER_EXTERNAL_TEXT_HEIGHT, 0.001), 0.001);
    const rightLineLength = Math.max(parsePositiveNumberOrFallback(options.rightLineLength, 2.8, 0.2), 0.2);
    const circleLayer = options.circleLayer || "SECCION_CORTE";
    const textLayer = options.textLayer || "SECCION_TEXTO";
    const titleOffsetX = parseNumberOrFallback(options.titleOffsetX, 0.10);
    const titleOffsetY = parseNumberOrFallback(options.titleOffsetY, 0.08);
    const safeTopText = normalizeTextValue(topText);
    const safeBottomText = normalizeTextValue(bottomText) || "E-00";
    const safeTitleText = normalizeTextValue(titleText);
    const lineStartX = centerX + radius;
    const lineEndX = lineStartX + rightLineLength;

    addCircle(dxf, circleLayer, centerX, centerY, radius, null, DXF_DETAIL_TITLE_MARKER_LINEWEIGHT);
    addLine(dxf, circleLayer, centerX - radius, centerY, centerX + radius, centerY, "", null, null, DXF_DETAIL_TITLE_MARKER_LINEWEIGHT);

    addCenteredText(
        dxf,
        textLayer,
        centerX,
        centerY + radius * 0.42,
        safeTopText,
        internalTextHeight
    );

    addCenteredText(
        dxf,
        textLayer,
        centerX,
        centerY - radius * 0.42,
        safeBottomText,
        internalTextHeight
    );

    addLine(dxf, circleLayer, lineStartX, centerY, lineEndX, centerY, "", null, null, DXF_DETAIL_TITLE_MARKER_LINEWEIGHT);

    if (safeTitleText) {
        addText(
            dxf,
            textLayer,
            lineStartX + titleOffsetX,
            centerY + titleOffsetY,
            safeTitleText,
            externalTextHeight
        );
    }
}

function drawBeamDetailNameMarker(dxf, centerX, centerY, beamName, detailCode = "E-00") {
    const displayName = stripLegacyBeamSpanSuffix(beamName) || normalizeTextValue(beamName);
    drawDetailTitleMarker(
        dxf,
        centerX,
        centerY,
        displayName || "",
        detailCode,
        `DETALLE DE VIGA ${displayName || ""}`.trim(),
        { rightLineLength: STANDALONE_BEAM_DETAIL_TITLE_LINE_LENGTH }
    );
}

function addSolid(arr, layer, x1, y1, x2, y2, x3, y3, x4 = x3, y4 = y3, color = null) {
    if (!hasFiniteNumbers(x1, y1, x2, y2, x3, y3, x4, y4)) {
        return;
    }

    arr.push(
        "0", "SOLID",
        "8", layer,
        "6", "CONTINUOUS",
        ...(Number.isFinite(color) ? ["62", String(color)] : []),
        "10", x1,
        "20", y1,
        "11", x2,
        "21", y2,
        "12", x3,
        "22", y3,
        "13", x4,
        "23", y4
    );
}

